import { InstantGame } from './instant-game.model';
import { Vendor } from './vendor.model';

export interface InstantGameCategory {
  id: number;
  name: string;
  active: boolean;
  iconUrl: string;
  displayPriority: number;
  instantGamesNumber: number;
  hasNew: boolean;
  hasHighlighted: boolean;
  type: InstantGameCategoryType;
  data: any;
  instantGames: InstantGame[];
  miniMode: boolean;
  vendor?: Vendor;
  vendors?: Vendor[];
  withCounter: boolean;
  smallThumbnails: boolean;
}

export enum InstantGameCategoryType {
  Classic = 'Classic',
  Providers = 'Providers',
  Highlights = 'Highlights',
  Top10 = 'Top10',
  Animated = 'Animated',
  HighlightProvider = 'HighlightProvider',
  BigWinners = 'BigWinners',
  Favorites = 'Favorites',
  RecentlyAdded = 'RecentlyAdded',
  GameOfTheWeek = 'GameOfTheWeek',
  RecentlyPlayed = 'RecentlyPlayed',
  MostLiked = 'MostLiked',
  HotGames = 'HotGames',
  ColdGames = 'ColdGames',
  WinnersStream = 'WinnersStream',
  Tournaments = 'Tournaments'
}
