export function isInternalLink(link: string): boolean {
  if (!link) {
    return false;
  }

  if (link.startsWith('/')) {
    return true;
  }

  try {
    const wwwPattern: RegExp = /^www\./;
    const linkHostname: string = new URL(link).hostname.replace(wwwPattern, '');
    const currentHostname: string = window.location.hostname.replace(wwwPattern, '');

    return linkHostname === currentHostname;
  } catch {
    return false;
  }
}

export function toInternalUrl(link: string): string {
  if (link.startsWith('/')) {
    return link;
  }

  try {
    const url: URL = new URL(link);
    return `${url.pathname}${url.search}${url.hash}`;
  } catch {
    return link;
  }
}

let currentScopeNumber = 0;

// create a style tag and add attribute selector to each rules of @styleText
export function addScopedStyle(styleText: string, doc: Document, element: HTMLElement, isSsr: boolean) {
  if (!styleText) {
    return;
  }

  setTimeout(() => {
    const scope = '_hgcontent-s' + (isSsr ? 'sr' : '') + currentScopeNumber++;
    const attr = doc.createAttribute(scope);
    element.setAttributeNode(attr);

    const style = doc.createElement('style');
    style.type = 'text/css';
    style.innerHTML = styleText.replace(/\[host\]/g, `[${scope}]`);
    // DEV
    // style.innerHTML = styleText
    //  .replace(/\[host\]/g, '')
    //  .replace(/^\s*([^{]*)\s*{/g, '[' + scope + '] $1{')
    //  .replace(/}\s*([^}]*)\s*{/g, '} [' + scope + '] $1{');

    element.appendChild(style);
  });
}
