import { Component, ChangeDetectionStrategy, Renderer2, ViewChild, ChangeDetectorRef } from '@angular/core';
import { NG_VALUE_ACCESSOR, ControlValueAccessor } from '@angular/forms';

@Component({
  selector: 'hg-toggle',
  templateUrl: './toggle.component.html',
  styleUrls: ['./toggle.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
  providers: [{ provide: NG_VALUE_ACCESSOR, useExisting: ToggleComponent, multi: true }]
})
export class ToggleComponent implements ControlValueAccessor {
  @ViewChild('input')
  input;

  innerValue: boolean;
  private changed = new Array<(v: boolean) => void>();
  private touched = new Array<() => void>();
  disabled = false;

  get value(): boolean {
    return this.innerValue;
  }

  set value(value: boolean) {
    if (this.innerValue !== value) {
      this.innerValue = value;
      this.changed.forEach(f => f(value));
    }
  }

  constructor(private readonly renderer: Renderer2, private readonly cdrRef: ChangeDetectorRef) {}

  setDisabledState(isDisabled: boolean) {
    if (this.input) {
      this.renderer.setProperty(this.input.nativeElement, 'disabled', isDisabled);
    }
    this.disabled = isDisabled;
    this.cdrRef.markForCheck();
  }

  writeValue(value: boolean): void {
    this.value = value;
  }

  innerWriteValue(value: boolean): void {
    if (!this.disabled) {
      this.value = value;
    }
  }

  registerOnChange(fn: any): void {
    this.changed.push(fn);
  }

  registerOnTouched(fn: any): void {
    this.touched.push(fn);
  }

  touch() {
    this.touched.forEach(f => f());
  }
}
