import { DrawGame, DrawGameExtendedModel, DrawGameBorletteBetType } from '@honoregaming/types';

const drawGameWithPrizesBetTypeIds: number[] = [
  DrawGameBorletteBetType.Borlette,
  DrawGameBorletteBetType.DoubChans,
  DrawGameBorletteBetType.Loto3,
  DrawGameBorletteBetType.Loto4,
  DrawGameBorletteBetType.Loto5,
  DrawGameBorletteBetType.Loto6,
  DrawGameBorletteBetType.Mariage
];

const drawGameWithOptionsBetTypeIds = [DrawGameBorletteBetType.Loto4, DrawGameBorletteBetType.Loto5];

export function EnrichDrawGame(drawGame: DrawGame & DrawGameExtendedModel) {
  drawGame.hasPrizesOrOptions = drawGame.drawGameRule.maxBaseNumber > 100;

  if (drawGame.hasPrizesOrOptions) {
    let hasResult = drawGame.result && drawGame.baseSelection;
    if (hasResult) {
      drawGame.baseSelectionAsStringArray = addMissingZerosToBaseSelection(drawGame.baseSelection);
    }
  }
}

export function IsDrawGameWithPrizes(betTypeId: number): boolean {
  let isIn: boolean = false;

  drawGameWithPrizesBetTypeIds.forEach(targetBetTypeId => {
    if (targetBetTypeId === betTypeId) {
      isIn = true;
    }
  });

  return isIn;
}

export function IsDrawGameWithOptions(betTypeId: number): boolean {
  let isIn: boolean = false;

  drawGameWithOptionsBetTypeIds.forEach(targetBetTypeId => {
    if (targetBetTypeId === betTypeId) {
      isIn = true;
    }
  });

  return isIn;
}

export function GetNumberOfDigitsPerWinningNumber(betTypeId: number): number {
  let numberOfDigitOfResult = 0;

  switch (betTypeId) {
    case DrawGameBorletteBetType.Borlette:
    case DrawGameBorletteBetType.Loto6:
    case DrawGameBorletteBetType.DoubChans:
      numberOfDigitOfResult = 2;
      break;
    case DrawGameBorletteBetType.Loto3:
      numberOfDigitOfResult = 3;
      break;
    case DrawGameBorletteBetType.Loto4:
    case DrawGameBorletteBetType.Mariage:
      numberOfDigitOfResult = 4;
      break;
    case DrawGameBorletteBetType.Loto5:
      numberOfDigitOfResult = 5;
      break;
  }

  return numberOfDigitOfResult;
}

export function addMissingZerosToBaseSelection(results: string[]): string[] {
  let resultAsString: string[] = [];

  if (!results || results?.length === 0) {
    return resultAsString;
  }

  for (let index = 0; index < results.length; index++) {
    const length = index === 0 ? 3 : 2;
    resultAsString.push(results[index].padStart(length, '0'));
  }

  return resultAsString;
}

export function GetMissingZerosPrefix(selection: number, targetDigitNumber: number): string {
  let prefix: string = '';
  let currentDigitNumber = CountDigits(selection);

  if (currentDigitNumber < targetDigitNumber) {
    let numberOf0ToAdd = targetDigitNumber - currentDigitNumber;

    for (let i = 0; i < numberOf0ToAdd; i++) {
      prefix += '0';
    }
  }

  return prefix;
}

export function FormatMariageSelectionWithXSeparator(number: string): string {
  return number.substring(0, 2) + 'x' + number.substring(2, 4);
}

export function CountDigits(input: number) {
  var count = 0;
  if (input >= 0) ++count;

  while (input / 10 >= 1) {
    input /= 10;
    ++count;
  }

  return count;
}
