import {
  Component,
  OnInit,
  ChangeDetectionStrategy,
  Input,
  ChangeDetectorRef,
  Output,
  EventEmitter
} from '@angular/core';
import { BorletteSelectionToBetslip } from '@honoregaming/draw-games-ui';
import { I18nService } from '@honoregaming/i18n';
import { DrawGame, DrawGameBorletteBetType } from '@honoregaming/types';
import { add, sub, mod, div, mul } from '@honoregaming/core';

@Component({
  selector: 'hg-borlette-selection',
  templateUrl: './borlette-selection.component.html',
  styleUrls: ['./borlette-selection.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class BorletteSelectionComponent implements OnInit {
  @Input() description: string = '';
  @Input() digitCount: number = 0;
  @Input() numbersCount: number = 0;
  @Input() optionsCount: number = 0;
  @Input() displayXBetweenNumbers: boolean = false;
  @Input() addSelectionButtonLabel: string = '';
  @Input() defaultStake: number = 1;
  @Input() minimumAmount: number = 1;
  @Input() maximumAmount?: number = undefined;
  @Input() increment: number = 1;
  @Input() predefinedStakes: number[] = [];
  @Input() isQuickBet: boolean = false;
  @Input() displayAddSelectionButton: boolean = true;
  @Input() drawGames: DrawGame[] = [];
  @Input() defaultSelectedDrawGamesIds: number[] = [];
  @Input() requiredDrawGamesSelectionCount?: number = undefined;
  @Input() drawGamesChoiceDescription: string = '';
  @Input() betTypePrefix: DrawGameBorletteBetType = DrawGameBorletteBetType.Borlette;
  @Output() addToBetSlipEmitted: EventEmitter<BorletteSelectionToBetslip> =
    new EventEmitter<BorletteSelectionToBetslip>();
  @Output() selectionChangedEmitted: EventEmitter<void> = new EventEmitter<void>();
  selections: string[][] = [];
  totalStake: number = 0;
  isSelectionValid: boolean = false;
  DrawGameBorletteBetType = DrawGameBorletteBetType;
  stakes: number[] = [];
  selectedDrawGamesIds: number[] = [];

  constructor(private readonly cdRef: ChangeDetectorRef, private readonly i18nService: I18nService) {}

  ngOnInit(): void {
    this.selectedDrawGamesIds = this.defaultSelectedDrawGamesIds.filter(id =>
      this.drawGames.some(game => game.id === id)
    );
    this.selectionChangedEmitted.emit();
    this.addEmptySelection();
    this.resetStakes(this.defaultStake);
    this.updateBettingStatus();
  }

  removeSelection(index: number): void {
    this.selections.splice(index, 1);
    this.updateBettingStatus();
  }

  updateNumber(
    drawGame: Event,
    selectionIndex: number,
    numberIndex: number,
    shouldFormat: boolean,
    withQuickBet: boolean
  ): void {
    const input = drawGame.target as HTMLInputElement;
    let result: string = input.value;
    if (result && result.toString().length > 0 && Number.isInteger(+result)) {
      const match = Number(result)
        .toString()
        .match(new RegExp(`\\d{1,${this.digitCount}}`));
      result = match ? match[0] : null;
    } else {
      result = undefined;
    }

    result = shouldFormat ? this.i18nService.formatIntegerNumber(result, this.digitCount) : result ?? '';
    this.selections[selectionIndex][numberIndex] = result;
    input.value = result;
    this.updateBettingStatus();
    if (withQuickBet) {
      this.manageQuickBet();
    }
  }

  addEmptySelection(): void {
    this.selections.push(new Array(this.numbersCount).fill(''));
    this.updateBettingStatus();
  }

  trackBy(index: number): number {
    return index;
  }

  addToBetslip(): void {
    this.updateBettingStatus();
    if (this.isSelectionValid) {
      this.addToBetSlipEmitted.emit({
        selections: this.selections,
        stakes: this.stakes,
        drawGamesIds: this.selectedDrawGamesIds
      });
      this.selections = [];
      this.addEmptySelection();
      this.updateBettingStatus();
    }
  }

  updateBettingStatus(): void {
    this.totalStake =
      this.selections.length *
      this.stakes.reduce((acc, curr) => acc + (Number.isFinite(curr) ? curr : 0), 0) *
      (this.betTypePrefix === DrawGameBorletteBetType.DoubChans
        ? this.selectedDrawGamesIds.length === 2
          ? 1
          : 0
        : this.selectedDrawGamesIds.length);

    const stakeCanBeEmpty: boolean = this.stakes.length > 1;
    this.isSelectionValid =
      this.selections.every(x => x.every(y => this.checkNumber(y))) &&
      this.totalStake > 0 &&
      this.stakes.every(
        x =>
          (!x && stakeCanBeEmpty) ||
          (x &&
            x.toString().length > 0 &&
            Number.isFinite(x) &&
            x > 0 &&
            x >= this.minimumAmount &&
            x <= (this.maximumAmount ?? Number.MAX_VALUE) &&
            mod(x, this.increment) === 0)
      ) &&
      (this.requiredDrawGamesSelectionCount > 0
        ? this.selectedDrawGamesIds.length === this.requiredDrawGamesSelectionCount
        : this.selectedDrawGamesIds.length > 0);
  }

  checkNumber(number: string): boolean {
    return (
      number &&
      number.toString().length > 0 &&
      Number.isInteger(+number) &&
      +number >= 0 &&
      +number <= Number('9'.repeat(this.digitCount))
    );
  }

  addSelections(selections: number[][]): void {
    for (let selection of selections) {
      const emptyIndex = this.selections.findIndex(x => !x.some(y => y && y.length > 0 && Number.isInteger(+y)));
      if (emptyIndex >= 0) {
        this.selections[emptyIndex] = selection.map(x => this.i18nService.formatIntegerNumber(x, this.digitCount));
      } else {
        this.selections.push(selection.map(x => this.i18nService.formatIntegerNumber(x, this.digitCount)));
      }
    }

    this.cdRef.markForCheck();
    this.updateBettingStatus();
    this.manageQuickBet();
  }

  getSelectedNumbers(): string[][] {
    return this.selections.map(x => [...x]);
  }

  decreaseStake(index: number): void {
    this.stakes[index] = this.stakes[index]
      ? Math.max(sub(this.stakes[index], this.increment), this.minimumAmount)
      : this.defaultStake ?? this.minimumAmount;
    this.updateBettingStatus();
    this.manageQuickBet();
  }

  increaseStake(index: number): void {
    this.stakes[index] = this.stakes[index]
      ? Math.min(add(this.stakes[index], this.increment), this.maximumAmount ?? Number.MAX_VALUE)
      : this.defaultStake
      ? Math.max(this.defaultStake, this.minimumAmount)
      : this.minimumAmount;
    this.updateBettingStatus();
    this.manageQuickBet();
  }

  resetStakes(stake: number = undefined): void {
    this.stakes = new Array(this.optionsCount > 0 ? this.optionsCount : 1).fill(Math.max(stake, this.minimumAmount));
    this.updateBettingStatus();
  }

  setStake(stake: number) {
    for (let i = 0; i < this.stakes.length; i++) {
      this.stakes[i] = Math.max(Math.min(stake, this.maximumAmount ?? Number.MAX_VALUE), this.minimumAmount);
    }

    this.updateBettingStatus();
    this.manageQuickBet();
  }

  updateStake(index: number): void {
    let stake = this.stakes[index];
    if (stake) {
      const modulo = mod(stake, this.increment);
      if (modulo !== 0) {
        stake = mul(Math.trunc(div(stake, this.increment)) + 1, this.increment);
      }

      stake = Math.max(Math.min(stake, this.maximumAmount ?? Number.MAX_VALUE), this.minimumAmount);
    }

    this.stakes[index] = stake;

    this.updateBettingStatus();
    this.manageQuickBet();
  }

  manageQuickBet(): void {
    if (this.isQuickBet) {
      this.addToBetslip();
    }
  }

  updateDrawGamesSelection(selection: number[]): void {
    selection = selection.filter(id => this.drawGames.some(game => game.id === id));
    this.selectedDrawGamesIds = selection;
    this.selectionChangedEmitted.emit();
    this.updateBettingStatus();
    this.manageQuickBet();
  }
}
