import { Component, ChangeDetectionStrategy, Output, EventEmitter } from '@angular/core';
import { Router } from '@angular/router';
import { LocalStorageService } from '@honoregaming/core';

@Component({
  selector: 'hg-initial-freebet',
  templateUrl: './initial-freebet.component.html',
  styleUrls: ['./initial-freebet.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class InitialFreebetComponent {
  @Output()
  public close = new EventEmitter<boolean>();

  constructor(private router: Router, private localStorageService: LocalStorageService) {}
  closePopin(): void {
    this.localStorageService.setItem('freebet_initial:valid', true);
    this.close.emit(true);
  }

  displayRules(): void {
    this.closePopin();
    this.router.navigate(['/about/content/freebets-rules']);
  }
}
