import { Injectable } from '@angular/core';
import { from, Observable } from 'rxjs';
// tslint:disable-next-line: no-submodule-imports
import { BarcodeScanner } from '@ionic-native/barcode-scanner/ngx';
import { I18nService } from '@honoregaming/i18n';
import { IScannerService } from '@honoregaming/core';

@Injectable({ providedIn: 'root' })
export class ScannerService implements IScannerService {
  constructor(private barcodeScanner: BarcodeScanner, private i18nService: I18nService) {}

  public scan(): Observable<string> {
    return from(
      this.barcodeScanner
        .scan({
          formats: 'CODE_128, QR_CODE',
          torchOn: true,
          orientation: 'portrait',
          prompt: this.i18nService.translateSync('TICKET_SEARCH.SCAN_PROMPT')
        })
        .then(result => {
          return result.text;
        })
    );
  }
}
