declare var window: any;

import { mergeMap, switchMap } from 'rxjs/operators';
import { Inject, Injectable, PLATFORM_ID } from '@angular/core';
import { DestroySubject } from '@honoregaming/core';
import { ICaptchaService } from './captcha-service.model';
import { CustomerService } from '../customer.service';
import { SecurityPolicy } from '@honoregaming/types';
import { DOCUMENT, isPlatformBrowser } from '@angular/common';
import { Observable, of } from 'rxjs';

@Injectable()
export class EvinaCaptchaService extends DestroySubject implements ICaptchaService {
  private securityPolicy: SecurityPolicy;
  private script: any;

  private evinaToken: string;

  constructor(
    private customerService: CustomerService,
    @Inject(DOCUMENT) private document,
    @Inject(PLATFORM_ID) private platformId
  ) {
    super();
  }

  loadCaptcha(securityPolicy: SecurityPolicy) {
    this.securityPolicy = securityPolicy;
  }

  applyCaptcha(targetElement: string): Observable<void> {
    return this.customerService.getSecurityPolicy().pipe(
      switchMap(securityPolicy => {
        this.securityPolicy = securityPolicy;

        if (this.securityPolicy.captchaProvider?.evina?.enabled && isPlatformBrowser(this.platformId)) {
          return this.customerService.getCaptcha(targetElement).pipe(
            mergeMap(results => {
              this.clearCaptcha();

              if (results && results.script) {
                this.evinaToken = results.transactionIdentifier;

                this.script = this.document.createElement('script');
                this.script.type = 'text/javascript';
                this.script.text = results.script;
                this.script.id = 'Evina';

                this.document.querySelector('body').appendChild(this.script);

                var ev = new Event('DCBProtectRun');
                this.document.dispatchEvent(ev);
              }

              return of(void 0);
            })
          );
        }

        return of(void 0);
      })
    );
  }

  validateCaptcha(): Observable<string> {
    if (this.securityPolicy.captchaProvider?.evina?.enabled && isPlatformBrowser(this.platformId)) {
      return of(this.evinaToken);
    }

    return of(null);
  }

  getLegend(): string {
    return null;
  }

  clearCaptcha(): void {
    if (this.document.querySelector('#Evina')) {
      this.evinaToken = null;
      window.evina_scram();
    }
  }
}
