import { Component, ChangeDetectionStrategy, Input, OnChanges } from '@angular/core';
import { I18nService } from '@honoregaming/i18n';
import { EventStateType, BetState, BetSystemHistory, BetLineHistory } from '@honoregaming/types';
import { ToasterService } from '@honoregaming/ui';
import { take } from 'rxjs/operators';

@Component({
  selector: 'hg-horse-racing-bet-system',
  templateUrl: './horse-racing-bet-system.component.html',
  styleUrls: ['../generic-bet-system.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class HorseRacingBetSystemComponent implements OnChanges {
  @Input()
  betSystem: BetSystemHistory;

  @Input()
  hideSection: boolean;

  betLine: BetLineHistory;

  multiBetTypeIds = [9, 11, 1009, 1019];

  BetState = BetState;
  EventStateType = EventStateType;

  constructor(private toasterService: ToasterService, private i18n: I18nService) {}

  ngOnChanges() {
    this.betLine = this.betSystem.betLines[0];
  }

  contentCopied() {
    this.i18n
      .translate('ACCOUNT.COPIED.REFERENCE')
      .pipe(take(1))
      .subscribe(translation => this.toasterService.show(translation));
  }
}
