import { Inject, Injectable } from '@angular/core';
import { defer, EMPTY, from, Observable, Subject } from 'rxjs';
import { catchError, finalize, switchMap, switchMapTo, take, takeUntil, tap } from 'rxjs/operators';
import * as signalr from '@microsoft/signalr';
import {
  appConfiguration,
  globalConfiguration,
  OperatorConfiguration,
  operatorConfigurationToken
} from '@honoregaming/configuration';
import { EventBetTypeChangedModel, EventChangedModel } from '@honoregaming/types';
import { BalanceChangesModel } from 'projects/core/hg-types/models/balance-changes.model';
import { authServiceToken, IAuthService } from '../../../../hg-authentication/src/lib/services/auth.service';
import { Scope, scopeToken } from '../enum';
import { DestroySubject } from '../utils';
import { ApplicationStateService } from './application-state.service';
import { IPushService } from './push.interface';
import { natifToken } from './tokens';

@Injectable()
export class PushService extends DestroySubject implements IPushService {
  private eventSubscriptions: { [scope: string]: number[] } = {};
  private oddsSubscriptions: { [scope: string]: number[] } = {};
  private oddsByEventSubscriptions: { [scope: string]: number[] } = {};

  publicClient?: signalr.HubConnection;
  authorizedClient?: signalr.HubConnection;

  private readonly eventBetTypeChangedSubject = new Subject<EventBetTypeChangedModel>();
  eventBetTypeChanged$: Observable<EventBetTypeChangedModel> = this.eventBetTypeChangedSubject.asObservable();

  private readonly eventChangedSubject = new Subject<EventChangedModel>();
  eventChanged$: Observable<EventChangedModel> = this.eventChangedSubject.asObservable();

  private readonly liveCounterChangedSubject = new Subject<EventChangedModel>();
  liveCounterChanged$: Observable<EventChangedModel> = this.liveCounterChangedSubject.asObservable();

  private readonly balanceChangedSubject = new Subject<BalanceChangesModel>();
  balanceChanged$: Observable<BalanceChangesModel> = this.balanceChangedSubject.asObservable();

  public readonly directMessageIncrementChangedSubject = new Subject<number>();
  directMessageIncrementChanged$: Observable<number> = this.directMessageIncrementChangedSubject.asObservable();

  private readonly manualOddsChangedSubject = new Subject<EventChangedModel>();
  manualOddsChanged$: Observable<EventChangedModel> = this.manualOddsChangedSubject.asObservable();

  constructor(
    private readonly applicationRef: ApplicationStateService,
    @Inject(natifToken) private readonly isNatif: boolean,
    @Inject(scopeToken) private readonly scope: Scope,
    @Inject(operatorConfigurationToken) public readonly operatorConfiguration: OperatorConfiguration,
    @Inject(authServiceToken) private readonly authService: IAuthService
  ) {
    super();

    this.startPublicClient().pipe(take(1)).subscribe();
    // this.sendFakeChanges();

    if (this.scope !== Scope.Customer) {
      return;
    }

    this.authService.status$
      .pipe(
        switchMap(status => (status === 'connected' ? this.startAuthorizedClient() : this.stopAuthorizedClient())),
        takeUntil(this.destroy$)
      )
      .subscribe();
  }

  // @ts-expect-error
  private sendFakeChanges() {
    setTimeout(() => {
      const changed: EventChangedModel = {
        eventId: 35381364,
        changes: {
          data: {
            eventTime: '52:16',
            stoppageTime: null,
            stoppageTimeAnnounced: null,
            remainingDate: '7:44',
            remainingTimeInPeriod: '7:44',
            stopped: 'true'
          },
          homeTeamScore: '0',
          awayTeamScore: '2'
        }
      };
      this.eventChangedSubject.next(changed);
    }, 5e3);

    setInterval(() => {
      var changed: EventBetTypeChangedModel = {
        active: true,
        eventBetTypeId: 1624853808,
        eventId: 395,
        bettingAllowed: true,
        items: [
          {
            bettingAllowed: true,
            eventBetTypeItemId: 3236131922,
            odds: Math.round(Math.random() * 10000) / 100
          }
        ]
      };
      this.eventBetTypeChangedSubject.next(changed);
    }, 5000);
  }

  subscribeToEvents(ids: number[], scope = 'global'): void {
    this.eventSubscriptions[scope] = ids;
    if (this.publicClient?.state === signalr.HubConnectionState.Connected) {
      this.publicClient.invoke('RegisterEvents', this.flatten(this.eventSubscriptions));
    }
  }

  subscribeToOdds(ids: number[], eventIds: number[], scope = 'global'): void {
    this.oddsSubscriptions[scope] = ids;
    this.oddsByEventSubscriptions[scope] = eventIds;
    if (this.publicClient?.state === signalr.HubConnectionState.Connected) {
      this.publicClient.invoke('RegisterOddsByEventBetType', this.flatten(this.oddsSubscriptions));
      this.publicClient.invoke('RegisterOddsByEvents', this.flatten(this.oddsByEventSubscriptions));
    }
  }

  private startPublicClient(): Observable<void> {
    this.publicClient = new signalr.HubConnectionBuilder()
      .withUrl(
        `${globalConfiguration.liveApiBaseUrl}public${
          this.isNatif ? '?HonoreOperator=' + appConfiguration.operatorKey : ''
        }`,
        {
          skipNegotiation: true,
          transport: signalr.HttpTransportType.WebSockets
        }
      )
      .withAutomaticReconnect()
      .build();

    this.publicClient.on('EventChanged', this.createChangesHandler(this.eventChangedSubject));
    this.publicClient.on('ManualOddsChanged', this.createChangesHandler(this.manualOddsChangedSubject));
    if (this.operatorConfiguration.onlineConfiguration?.showLiveCounter) {
      this.publicClient.on('LiveCounterChanged', this.createChangesHandler(this.liveCounterChangedSubject));
    }
    this.publicClient.on('OddsChanged', this.createChangesHandler(this.eventBetTypeChangedSubject));

    return this.applicationRef.isReady$.pipe(
      take(1),
      switchMapTo(from(this.publicClient.start())),
      tap(() => {
        const eventIds = this.flatten(this.eventSubscriptions);
        if (eventIds.length > 0) {
          this.publicClient.invoke('RegisterEvents', eventIds);
        }
        const oddsEventBetTypeIds = this.flatten(this.oddsSubscriptions);
        if (oddsEventBetTypeIds.length > 0) {
          this.publicClient.invoke('RegisterOddsByEventBetType', oddsEventBetTypeIds);
        }
        const oddsEventIds = this.flatten(this.oddsByEventSubscriptions);
        if (oddsEventIds.length > 0) {
          this.publicClient.invoke('RegisterOddsByEvents', oddsEventIds);
        }
      }),
      catchError(err => {
        console.error('Error connecting to public hub:', err);
        return EMPTY;
      })
    );
  }

  private startAuthorizedClient(): Observable<void> {
    if (
      (this.authorizedClient != null && this.authorizedClient.state !== signalr.HubConnectionState.Disconnected) ||
      !this.authService.isAuthenticated() ||
      this.scope !== Scope.Customer
    ) {
      return EMPTY;
    }

    this.authorizedClient = new signalr.HubConnectionBuilder()
      .withUrl(
        `${globalConfiguration.liveApiBaseUrl}authorized${
          this.isNatif ? '?HonoreOperator=' + appConfiguration.operatorKey : ''
        }`,
        {
          skipNegotiation: true,
          transport: signalr.HttpTransportType.WebSockets,
          accessTokenFactory: () => this.authService.getToken().toPromise()
        }
      )
      .withAutomaticReconnect()
      .build();

    this.authorizedClient.on('BalanceChanged', (changes: string) =>
      this.balanceChangedSubject.next(JSON.parse(changes))
    );

    this.authorizedClient.on('DirectMessageIncrementChanged', (changes: { increment: number }) =>
      this.directMessageIncrementChangedSubject.next(changes.increment)
    );

    return this.applicationRef.isReady$.pipe(
      take(1),
      switchMap(() => from(this.authorizedClient.start())),
      catchError(err => {
        console.error('Error connecting to authorized hub:', err);
        return EMPTY;
      })
    );
  }

  private stopAuthorizedClient(): Observable<void> {
    return defer(() => {
      if (!this.authorizedClient) {
        return EMPTY;
      }
      return from(this.authorizedClient.stop());
    }).pipe(
      catchError(err => {
        console.error('Error disconnecting from authorized hub:', err);
        return EMPTY;
      }),
      finalize(() => {
        this.authorizedClient = null;
      })
    );
  }

  private flatten(subscriptions: { [scope: string]: number[] }): number[] {
    return Object.keys(subscriptions).reduce((cur, next) => cur.concat(subscriptions[next]), []);
  }

  private createChangesHandler<T>(subject: Subject<T>) {
    return (changes: string[]) => {
      changes.forEach(change => {
        subject.next(JSON.parse(change) as T);
      });
    };
  }
}
