export function getNameForEntryPoint(entryPoint: number) {
  switch (entryPoint) {
    case 101:
      return 'Soccer';
    case 102:
      return 'Basketball';
    case 103:
      return 'Tennis';
    case 104:
      return 'Rugby';
    case 105:
      return 'American Football';
    case 106:
      return 'Badminton';
    case 107:
      return 'Baseball';
    case 108:
      return 'Darts';
    case 109:
      return 'Futsal';
    case 110:
      return 'Handball';
    case 111:
      return 'Ice Hockey';
    case 112:
      return 'Snooker';
    case 113:
      return 'Table Tennis';
    case 114:
      return 'Volleyball';
    case 8019:
    case 8020:
    case 8021:
    case 8027:
    case 8028:
    case 8029:
      return 'Soccer';
    default:
      return '';
  }
}
