import { Injectable } from '@angular/core';
import { Subject } from 'rxjs';
import { I18nService } from '@honoregaming/i18n';
import { take } from 'rxjs/operators';

@Injectable({
  providedIn: 'root'
})
export class UserInformationsService {
  private userMessageSubject = new Subject<string>();
  userMessage$ = this.userMessageSubject.asObservable();

  constructor(private i18nService: I18nService) {}

  sendMessageUserI18n(key: string, ...values: string[]) {
    this.i18nService
      .translate(key, ...values)
      .pipe(take(1))
      .subscribe(msg => this.userMessageSubject.next(msg));
  }
}
