import { Directive, ElementRef, Input } from '@angular/core';

const animationEvent = [
  'animationiteration',
  'webkitAnimationIteration',
  'oAnimationIteration',
  'animationend',
  'webkitAnimationEnd',
  'oAnimationEnd'
];

const fakeScopeUnTreeShakable: any = {};

export const reanimate = (element: any, className: string) => {
  element.classList.remove(className);
  fakeScopeUnTreeShakable.off = element.offsetWidth;
  element.classList.add(className);
};

@Directive({
  selector: '[hgAnimate]',
  exportAs: 'hgAnimate'
})
export class AnimateDirective {
  private stop: boolean;
  private animatedClass: string;
  constructor(private elementRef: ElementRef) {}

  @Input('hgAnimate')
  identifier: any;

  animate(className: string) {
    if (this.animatedClass) {
      this.elementRef.nativeElement.classList.remove(this.animatedClass);
    }

    this.animatedClass = className;
    reanimate(this.elementRef.nativeElement, className);
    const listener = () => {
      if (this.stop) {
        this.stop = false;
        this.animatedClass = undefined;
        this.elementRef.nativeElement.classList.remove(className);
        animationEvent.forEach(e => this.elementRef.nativeElement.removeEventListener(e, listener));
      }
    };
    animationEvent.forEach(e => this.elementRef.nativeElement.addEventListener(e, listener));
  }

  stopAnimation() {
    this.stop = true;
  }
}
