const univers = [
  'myaccount',
  '/myaccount/registration',
  '/sports/101',
  'about',
  'horseracing',
  'sports',
  'virtual',
  'draw-games',
  'instant-games',
  'promotions'
];

export function getRootFromPath(path: string, betCategoryInstantGamesPathOverride: string): string {
  var root = path.split('/').filter(x => x)[0] || '';

  if (root === betCategoryInstantGamesPathOverride) {
    return 'instant-games';
  }

  if (univers.includes(root)) {
    if (path.startsWith('/myaccount/registration')) {
      return 'registration';
    } else if (path.startsWith('/sports/101')) {
      return 'football';
    } else if (path.startsWith('/about/promotions')) {
      return 'promotions';
    }

    return root;
  }

  return '';
}
