import {
  Component,
  OnInit,
  ChangeDetectionStrategy,
  Input,
  Output,
  EventEmitter,
  ChangeDetectorRef,
  ViewChild,
  ElementRef,
  Inject
} from '@angular/core';
import { Me, CustomerService } from '@honoregaming/customer-core';
import { finalize, takeUntil } from 'rxjs/operators';
import { DestroySubject } from '@honoregaming/core';
import { I18nService } from '@honoregaming/i18n';
import { OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';

@Component({
  selector: 'hg-account-update-email',
  templateUrl: './account-update-email.component.html',
  styleUrls: ['./account-update-email.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class AccountUpdateEmailComponent extends DestroySubject implements OnInit {
  @Input() me: Me;

  @ViewChild('updateEmailElement') updateEmailElement: ElementRef;

  email: string;
  loading: boolean = false;
  success: boolean = false;
  error: boolean;

  errorMessage: string;

  @Output()
  backEvent = new EventEmitter();
  mfaCode: string;
  showMfa: boolean;

  constructor(
    @Inject(operatorConfigurationToken) private operatorConfiguration: OperatorConfiguration,
    private customerService: CustomerService,
    private cdRef: ChangeDetectorRef,
    private i18nService: I18nService
  ) {
    super();
  }

  ngOnInit(): void {
    this.email = this.me.profile?.email;
    this.goToTop();
  }

  submit() {
    if (this.operatorConfiguration.mfaConfiguration?.customerConfiguration?.updatePersonalInformation) {
      this.showMfa = true;
      this.cdRef.markForCheck();
    } else {
      this.sendSubmit();
    }
  }

  sendRequestWithMFA(code: string) {
    this.mfaCode = code;
    this.showMfa = false;
    this.sendSubmit();
  }

  sendSubmit() {
    this.loading = true;
    this.error = false;
    this.customerService
      .updateEmail(this.email, this.mfaCode)
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.loading = false;
          this.showMfa = false;
          this.cdRef.markForCheck();
        })
      )
      .subscribe(
        () => {
          this.me.profile.email = this.email;
          this.success = true;
        },
        err => {
          this.error = true;
          if (err.error?.code === UpdateEmailFailure.EmailAlreadyTaken) {
            this.errorMessage = this.i18nService.translateSync('UPDATE_EMAIL.ERROR.ALREADY_TAKEN');
          } else {
            this.errorMessage = this.i18nService.translateSync('COMMON.GENERIC.ERROR');
          }
        }
      );
  }

  goToTop() {
    setTimeout(() => {
      this.updateEmailElement.nativeElement.scrollIntoView();
    }, 0);
  }

  back() {
    this.backEvent.emit(this.email);
  }
}

enum UpdateEmailFailure {
  EmailAlreadyTaken = 0
}
