import { ChangeDetectionStrategy, Component, EventEmitter, Input, Output } from '@angular/core';
import { WonTournament } from 'projects/customer/hg-core/src/lib/models/notifications-infos.model';

@Component({
  selector: 'hg-won-tournament-notification',
  templateUrl: './won-tournament-notification.component.html',
  styleUrls: ['./won-tournament-notification.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class WonTournamentNotificationComponent {
  @Input() tournaments: WonTournament[] = [];
  @Output() close = new EventEmitter<void>();

  index: number = 0;

  get current(): WonTournament {
    return this.tournaments[this.index];
  }

  get rankImageSrc(): string | null {
    return this.current.ranking <= 3 ? `assets/instant-games/tournament/rank-${this.current.ranking}.png` : null;
  }

  previous(): void {
    this.index = this.index > 0 ? this.index - 1 : this.tournaments.length - 1;
  }

  next(): void {
    this.index = this.index < this.tournaments.length - 1 ? this.index + 1 : 0;
  }
}
