export function toCents(amount: number) {
  if (!Number.isFinite(amount)) {
    throw new Error('Invalid amount');
  }
  return Math.round((amount + 1e-10) * 1000); // 1000 for more precision
}

export function fromCents(cents: number) {
  if (!Number.isFinite(cents)) {
    throw new Error('Invalid cents');
  }
  return cents / 1000; // 1000 for more precision
}

export function add(a: number, b: number) {
  // Because some calculations are broken if we don't return NaN for payout
  if (Number.isNaN(a) || Number.isNaN(b)) {
    return NaN;
  }
  a ??= 0;
  b ??= 0;
  return fromCents(toCents(a) + toCents(b));
}

export function sub(a: number, b: number) {
  // Because some calculations are broken if we don't return NaN for payout
  if (Number.isNaN(a) || Number.isNaN(b)) {
    return NaN;
  }
  a ??= 0;
  b ??= 0;
  return fromCents(toCents(a) - toCents(b));
}

export function mod(a: number, b: number) {
  // Because some calculations are broken if we don't return NaN for payout
  if (Number.isNaN(a) || Number.isNaN(b)) {
    return NaN;
  }
  const denom = toCents(b);
  if (denom === 0) {
    throw new Error('Modulo by zero');
  }
  return fromCents(toCents(a) % denom);
}

export function mul(amount: number, multiplier: number) {
  // Because some calculations are broken if we don't return NaN for payout
  if (Number.isNaN(amount) || Number.isNaN(multiplier)) {
    return NaN;
  }
  if (!Number.isFinite(multiplier)) {
    throw new Error('Invalid multiplier');
  }
  return fromCents(Math.floor(toCents(amount) * multiplier));
}

export function div(amount: number, denom: number) {
  // Because some calculations are broken if we don't return NaN for payout
  if (Number.isNaN(amount) || Number.isNaN(denom)) {
    return NaN;
  }
  if (!Number.isFinite(denom)) {
    throw new Error('Invalid denom');
  }
  if (denom === 0) {
    throw new Error('Division by zero');
  }
  return fromCents(Math.floor(toCents(amount) / denom));
}
