export interface Operation {
  id: number;
  dateTime: Date;
  type: OperationType;
  amount: number;
  status: OperationStatus;
  operationRef: string;
  provider: string;
  customerLogin: string;
  customerFirstName: string;
  customerLastName: string;
}

export enum OperationType {
  Unknown = 0,
  BetPlaced,
  BetPaid,
  Deposit,
  Withdrawal,
  Correction
}

export enum OperationStatus {
  Unknown = 'Unknown',
  WaitingAdministratorValidation = 'WaitingAdministratorValidation',
  Initiated = 'Initiated',
  Validated = 'Validated',
  Cancelled = 'Cancelled',
  Error = 'Error'
}
