import { Component, ChangeDetectionStrategy, Input, ChangeDetectorRef, OnChanges } from '@angular/core';
import { EventCategoriesService } from '@honoregaming/events';

@Component({
  selector: 'hg-entrypoint-icon',
  templateUrl: './entrypoint-icon.component.html',
  styleUrls: ['./entrypoint-icon.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class EntrypointIconComponent implements OnChanges {
  @Input()
  entryPointId: number;

  entryPointIconSrc: string;

  constructor(private eventCategoriesService: EventCategoriesService, private cdRef: ChangeDetectorRef) {}

  ngOnChanges() {
    this.eventCategoriesService.getEntryPoints().subscribe(
      e => {
        const epTarget = e.find(ep => ep.id === this.entryPointId);
        if (epTarget) {
          this.entryPointIconSrc =
            this.entryPointId === 8038
              ? 'https://storage-prod.sporty-tech.net/icons/virtual-instant-league.svg'
              : epTarget.iconUrl;
        }

        this.cdRef.markForCheck();
      },
      _err => {}
    );
  }
}
