import { Injectable } from '@angular/core';
import { DestroySubject } from '@honoregaming/core';
import { SmarticoService } from '../smartico/smartico.service';
import { ITelemetryService } from './telemetry-service.model';

@Injectable()
export class SmarticoTelemetryService extends DestroySubject implements ITelemetryService {
  constructor(private readonly smarticoService: SmarticoService) {
    super();
  }

  trackPageView(_: string, __: string): void {
    if (!this.smarticoService.isEnabled) {
      return;
    }
  }

  trackEvent(_: string, __: any): void {
    if (!this.smarticoService.isEnabled) {
      return;
    }
  }
}
