import {
  Input,
  ComponentFactoryResolver,
  ViewContainerRef,
  AfterViewInit,
  Directive,
  ChangeDetectorRef,
  Output,
  EventEmitter,
  Type
} from '@angular/core';
import { registeredTemplates, RegisteredTemplatesType } from '../template.registration';

// eslint-disable-next-line @angular-eslint/directive-selector
@Directive({ selector: 'hg-template' })
export class TemplateDirective implements AfterViewInit {
  constructor(
    private cfr: ComponentFactoryResolver,
    private viewContainerRef: ViewContainerRef,
    private cdRef: ChangeDetectorRef
  ) {}

  @Input()
  inputs: any[];

  @Input()
  type: RegisteredTemplatesType;

  @Output()
  error = new EventEmitter<boolean>();

  @Output() close = new EventEmitter<unknown>();

  ngAfterViewInit() {
    const fact = this.cfr.resolveComponentFactory(registeredTemplates[this.type] as Type<unknown>);

    if (fact !== undefined) {
      const ref = this.viewContainerRef.createComponent<any>(fact);
      Object.assign(ref.instance, this.inputs);
      if (ref.instance.error && ref.instance.error instanceof EventEmitter) {
        ref.instance.error.subscribe(() => this.error.emit(true));
      }
      if (ref.instance.close && ref.instance.close instanceof EventEmitter) {
        ref.instance.close.subscribe(val => this.close.emit(val));
      }

      this.cdRef.detectChanges();
    }
  }
}
