import { Component, OnInit, ChangeDetectionStrategy, ChangeDetectorRef, Inject, OnDestroy } from '@angular/core';
import {
  AuthService,
  CustomerService,
  CustomerState,
  ICaptchaService,
  captchaServiceToken
} from '@honoregaming/customer-core';
import { Router } from '@angular/router';
import { finalize, takeUntil } from 'rxjs/operators';
import { DestroySubject, hasFlag } from '@honoregaming/core';
import { CustomerOperatorConfiguration, customerOperatorConfigurationToken } from '@honoregaming/customer-core';
import { SecurityPolicy } from '@honoregaming/types';
import { MessageService } from '@honoregaming/ui';
import { ValidationCodeBlockedComponent } from 'projects/customer/customer/src/app/popins/validation-code-blocked/validation-code-blocked.component';

@Component({
  selector: 'hg-account-unlock',
  templateUrl: './account-unlock.component.html',
  styleUrls: ['./account-unlock.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class AccountUnlockComponent extends DestroySubject implements OnInit, OnDestroy {
  isValidated: boolean;
  validationCode: ValidationCodeDigit5 = {
    digit1: null,
    digit2: null,
    digit3: null,
    digit4: null,
    digit5: null
  };
  validationCodeReseted: boolean = null;
  isConnected: boolean;
  loadingValidate: boolean;
  loadingReset: boolean;
  error: boolean;
  resetValidationCodeError: boolean;
  securityPolicy: SecurityPolicy;

  recaptchaLegend: string;

  login: string;

  constructor(
    private authService: AuthService,
    private customerService: CustomerService,
    private cdRef: ChangeDetectorRef,
    private router: Router,
    private messageService: MessageService,
    @Inject(captchaServiceToken) private captchaService: ICaptchaService,
    @Inject(customerOperatorConfigurationToken) private customerOperatorConfiguration: CustomerOperatorConfiguration
  ) {
    super();
  }

  ngOnInit() {
    this.authService.me$.pipe(takeUntil(this.destroy$)).subscribe(x => {
      this.isConnected = !!x;
      this.login = x.login;
      this.cdRef.markForCheck();
    });

    this.captchaService
      .applyCaptcha('#acount-unlock-button')
      .pipe(
        finalize(() => {
          this.cdRef.markForCheck();
        })
      )
      .subscribe(() => {
        this.recaptchaLegend = this.captchaService.getLegend();
      });
  }

  ngOnDestroy(): void {
    this.captchaService.clearCaptcha();
  }

  validate() {
    if (this.loadingValidate) {
      return;
    }
    this.validationCodeReseted = false;
    this.loadingValidate = true;
    this.error = false;
    this.resetValidationCodeError = false;
    var validationCode = Object.values(this.validationCode).join('');
    this.customerService
      .unlockAccount(validationCode)
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.loadingValidate = false;
          this.cdRef.markForCheck();
        })
      )
      .subscribe(
        () => {
          this.authService
            .getMe()
            .pipe(takeUntil(this.destroy$))
            .subscribe(x => {
              this.isValidated = hasFlag(x.state, CustomerState.LoginValidated);
              if (
                this.isValidated &&
                !this.customerOperatorConfiguration.knowYourCustomerConfiguration?.customerAccessLimitationConfiguration
                  ?.blockDeposit
              ) {
                this.router.navigate(['myaccount', 'deposit']);
              } else if (
                this.isValidated &&
                this.customerOperatorConfiguration.knowYourCustomerConfiguration?.customerAccessLimitationConfiguration
                  ?.blockDeposit
              ) {
                this.router.navigate(['myaccount', 'informations']);
              }
            });
        },
        _ => {
          this.error = true;
        }
      );
  }

  public resetValidationCode() {
    if (this.loadingReset) {
      return;
    }

    this.loadingReset = true;
    this.error = false;
    this.resetValidationCodeError = false;

    this.captchaService
      .validateCaptcha()
      .pipe(takeUntil(this.destroy$))
      .subscribe(token => this.submitResetValidationCode(token));
  }

  private submitResetValidationCode(recaptchaToken: string) {
    this.loadingReset = true;
    this.customerService
      .resetValidationCode(recaptchaToken, true)
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.loadingReset = false;
          this.cdRef.markForCheck();
        })
      )
      .subscribe(
        () => {
          this.validationCodeReseted = true;
          this.cdRef.markForCheck();
        },
        err => {
          this.resetValidationCodeError = true;
          if (err.error.code === -1) {
            this.messageService.sendComponentMessage(ValidationCodeBlockedComponent, {
              endRestrictionDate: err.error.additionalData.endRestrictionDate
            });
          }
        }
      );
  }

  isValidationCodeNotValid() {
    return Object.values(this.validationCode).join('').length !== 5 || this.loadingValidate;
  }
}

export interface ValidationCodeDigit5 {
  digit1?: number;
  digit2?: number;
  digit3?: number;
  digit4?: number;
  digit5?: number;
}
