import { Inject, Injectable } from '@angular/core';
import { Router } from '@angular/router';
import { authServiceToken, IAuthService } from '@honoregaming/authentication';
import { Template } from '@honoregaming/types';
import { TelemetryService } from './telemetry.service';

export interface BannerClickPayload {
  name?: string;
  id?: string | number;
  page: string;
  position?: number;
  url?: string | null;
}

@Injectable()
export class BannerService {
  constructor(
    @Inject(authServiceToken) private readonly authService: IAuthService,
    private readonly router: Router,
    private readonly telemetryService: TelemetryService
  ) {}

  trackSlideClick(slide: Template, position: number): void {
    if (!slide || !this.isImageBanner(slide)) {
      return;
    }

    this.trackClick({
      name: slide.name,
      id: slide.id,
      position,
      page: this.resolveBannerPage(),
      url: slide.link ?? null
    });
  }

  trackClick(payload: BannerClickPayload): void {
    this.telemetryService.trackEvent('banner_click', {
      banner_name: payload.name,
      banner_id: payload.id,
      banner_position: payload.position ?? null,
      banner_page: payload.page,
      banner_url: payload.url ?? null,
      is_logged: this.authService.isAuthenticated()
    });
  }

  private isImageBanner(slide: Template): boolean {
    return !!(slide.images?.desktop || slide.images?.mobile);
  }

  private resolveBannerPage(): string {
    const url: string = this.router.url.split('?')[0].split('#')[0];
    const segments: string[] = url.split('/').filter(Boolean);

    if (segments.length === 0 || segments[0] === 'sports') {
      if (segments.length <= 1) {
        return 'home';
      }
      if (segments[1] === 'live') {
        return segments.includes('event') ? 'live_event' : 'live_lobby';
      }
      if (segments[1] === 'event') {
        return 'prematch_event';
      }
      return 'prematch_lobby';
    }

    return segments[0];
  }
}
