import { Component, ChangeDetectionStrategy, Output, EventEmitter, Inject } from '@angular/core';
import { operatorConfigurationToken, OperatorConfiguration } from '@honoregaming/configuration';
import { DestroySubject } from '@honoregaming/core';

@Component({
  selector: 'hg-account-kyc-validated',
  templateUrl: './account-kyc-validated.component.html',
  styleUrls: ['./account-kyc-validated.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class AccountKYCValidatedComponent extends DestroySubject {
  @Output()
  backEvent = new EventEmitter();

  operatorName = this.operatorConfiguration.name;

  constructor(@Inject(operatorConfigurationToken) private operatorConfiguration: OperatorConfiguration) {
    super();
  }

  back() {
    this.backEvent.emit();
  }
}
