import { HttpParams } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { DateTime } from 'luxon';

@Injectable({
  providedIn: 'root'
})
export class QueryBuilderService {
  buildHttpParams(params: Dictionary): HttpParams {
    return Object.entries(params)
      .filter(([_, value]) => value !== undefined && value !== null && (!Array.isArray(value) || value.length > 0))
      .reduce((queryParams, [key, value]) => {
        if (Array.isArray(value)) {
          value.forEach(v => (queryParams = queryParams.append(key, v instanceof DateTime ? v.toUTC().toString() : v)));

          return queryParams;
        }

        return queryParams.append(key, value instanceof DateTime ? value.toUTC().toString() : value);
      }, new HttpParams());
  }
}

interface Dictionary {
  [name: string]: any;
}
