import { Component, ChangeDetectionStrategy, Input, ElementRef, OnChanges, Inject } from '@angular/core';
import { Observable } from 'rxjs';
import { HttpClient } from '@angular/common/http';
import { Cacheable } from '@honoregaming/core';
import { DOCUMENT } from '@angular/common';

@Component({
  selector: 'hg-inline-svg',
  template: '',
  styleUrls: ['./inline-svg.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class InlineSvgComponent implements OnChanges {
  @Input() src: string;

  svgColor: string = '';

  constructor(
    private httpClient: HttpClient,
    private element: ElementRef,
    @Inject(DOCUMENT) private document: Document
  ) {}

  ngOnChanges() {
    if (this.src) {
      this.loadSvg(this.src).subscribe(svg => {
        const elem = this.element.nativeElement;
        elem.innerHTML = svg;
        this.updateSvgStyle(elem);
      });
    }
  }

  @Cacheable()
  private loadSvg(src: string): Observable<string> {
    return this.httpClient.get(src, { responseType: 'text' });
  }

  updateSvgStyle(svgElement: HTMLElement) {
    const element = this.document?.querySelector('.dynamic-color');
    const styleElement = svgElement?.querySelector('style');
    const svgElements = svgElement.querySelectorAll('path, g, line, circle, rect, polygon, ellipse');

    if (element) {
      const style = window.getComputedStyle(element);
      this.svgColor = style.fill;
    }

    if (styleElement) {
      let styleContent = styleElement.textContent || '';
      styleContent = styleContent.replace(/#f60/g, this.svgColor);
      styleElement.textContent = styleContent;
    }

    svgElements.forEach(element => {
      const fillValue = element.getAttribute('fill');
      if (fillValue === '#f60') {
        element.setAttribute('fill', this.svgColor);
      }

      const strokeValue = element.getAttribute('stroke');
      if (strokeValue === '#f60') {
        element.setAttribute('stroke', this.svgColor);
      }
    });
  }
}
