export function getUtcNow(): Date {
  const date = new Date();

  return new Date(
    Date.UTC(
      date.getUTCFullYear(),
      date.getUTCMonth(),
      date.getUTCDate(),
      date.getUTCHours(),
      date.getUTCMinutes(),
      date.getUTCSeconds()
    )
  );
}

export function happenBefore(from: Date, target: Date, delayInMs: number) {
  return target.getTime() - from.getTime() <= delayInMs;
}

export function delayBetween(from: Date, target: Date) {
  return target.getTime() - from.getTime();
}
