import { Injectable } from '@angular/core';
import { Event, NavigationError, NavigationStart, Router } from '@angular/router';
import { IError } from 'projects/core/hg-core/src/lib/errors/error.interface';
import { filter } from 'rxjs/operators';

@Injectable()
export class RoutingEventsService {
  constructor(private router: Router) {}

  public listen(actions: ErrorAction): void {
    this.router.events
      .pipe(
        filter((event: Event) => {
          return event instanceof NavigationError || event instanceof NavigationStart;
        })
      )
      .subscribe((navEvent: NavigationError | NavigationStart) => {
        if (navEvent instanceof NavigationError) {
          const action = actions[(navEvent.error as IError).type || navEvent.error.constructor.name];
          if (action) {
            action();
          }
        }
      });
  }
}

export interface ErrorAction {
  [errorType: string]: () => void;
}
