import { Component, OnInit, ChangeDetectionStrategy, ChangeDetectorRef } from '@angular/core';
import { Async, AsyncTrigger, DestroySubject } from '@honoregaming/core';
import { I18nService } from '@honoregaming/i18n';
import { ContentService } from '@honoregaming/templating';
import { MediaService, Media } from '@honoregaming/ui';
import { takeUntil } from 'rxjs/operators';

@Component({
  selector: 'hg-promotions',
  templateUrl: './promotions.component.html',
  styleUrls: ['./promotions.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class PromotionsComponent extends DestroySubject implements OnInit {
  content: string;
  style: string;
  isDesktop: boolean = false;

  @AsyncTrigger()
  languageTrigger = this.i18nService.languageChanged$;

  constructor(
    private contentService: ContentService,
    private cdRef: ChangeDetectorRef,
    private i18nService: I18nService,
    private mediaService: MediaService
  ) {
    super();
  }

  ngOnInit() {
    this.loadContent();
    this.isDesktop = this.mediaService.media >= Media.lg;
  }

  @Async()
  loadContent() {
    this.contentService
      .getContent('promotions')
      .pipe(takeUntil(this.destroy$))
      .subscribe(resource => {
        this.content = resource.content;
        this.style = resource.style;
        this.cdRef.markForCheck();
      });
  }
}
