import { Directive, Inject, Input, OnInit, TemplateRef, ViewContainerRef } from '@angular/core';
import { take, takeUntil } from 'rxjs/operators';
import { DestroySubject } from '@honoregaming/core';
import { operatorConfigurationToken, OperatorConfiguration } from '@honoregaming/configuration';
import { EventsService } from '@honoregaming/events';
import { BetCategoryType } from '@honoregaming/types';

export interface IfDisplaySportsPoolBannerContext {
  $implicit: 'mobile' | 'desktop';
}

@Directive({
  selector: '[hgIfDisplaySportsPoolBanner]'
})
export class IfDisplaySportsPoolBannerDirective extends DestroySubject implements OnInit {
  @Input('hgIfDisplaySportsPoolBanner') format: 'mobile' | 'desktop' = 'mobile';

  static ngTemplateContextGuard(
    _directive: IfDisplaySportsPoolBannerDirective,
    _context: unknown
  ): _context is IfDisplaySportsPoolBannerContext {
    return true;
  }

  constructor(
    private readonly templateRef: TemplateRef<IfDisplaySportsPoolBannerContext>,
    private readonly viewContainer: ViewContainerRef,
    private readonly eventsService: EventsService,
    @Inject(operatorConfigurationToken) private readonly operatorConfiguration: OperatorConfiguration
  ) {
    super();
  }

  ngOnInit(): void {
    const hasSportsPool: boolean = this.operatorConfiguration.betCategories.includes(BetCategoryType.SportsPool);
    const displayBanner: boolean = this.operatorConfiguration.sportsPoolConfiguration?.displayBanner;
    const bannerUrl: string = this.operatorConfiguration.sportsPoolConfiguration?.bannerImages?.[this.format]?.url;

    if (!hasSportsPool || !displayBanner || !bannerUrl) {
      return;
    }

    this.eventsService
      .getSportsPoolNextCount()
      .pipe(takeUntil(this.destroy$), take(1))
      .subscribe((count: number) => {
        if (count > 0) {
          this.viewContainer.createEmbeddedView(this.templateRef, { $implicit: this.format }).markForCheck();
        }
      });
  }
}
