import {
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  Inject,
  OnInit,
  Optional,
  PLATFORM_ID
} from '@angular/core';
import { isPlatformBrowser } from '@angular/common';
import { takeUntil } from 'rxjs/operators';
import { globalConfiguration } from '@honoregaming/configuration';
import { DestroySubject } from '@honoregaming/core';
import { GeoblockingService } from '@honoregaming/customer-core';
import { Media, MediaService } from '@honoregaming/ui';
import { ClientInfoResponse, ClientInfoService } from '../../services/client-info.service';

@Component({
  selector: 'hg-geo-block',
  templateUrl: './geo-block.component.html',
  styleUrls: ['./geo-block.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class GeoBlockComponent extends DestroySubject implements OnInit {
  private static readonly MOBILE_BACKGROUND: string = '/assets/geoblock/background-mobile.png';
  private static readonly DESKTOP_BACKGROUND: string = '/assets/geoblock/background-desktop.png';

  // The operator configuration.json is not loaded when geo-blocked: everything comes from the geoblocking endpoint.
  desktopLogoPath?: string = this.geoblockingService.geoblocking
    ? `${globalConfiguration.assetsPath}${this.geoblockingService.geoblocking.key}/logo.png`
    : undefined;
  backgroundPath: string = GeoBlockComponent.MOBILE_BACKGROUND;
  ipAddress?: string;
  supportEmail?: string = this.geoblockingService.geoblocking?.supportEmail;
  supportPhone?: string = this.geoblockingService.geoblocking?.supportPhone;

  constructor(
    private readonly clientInfoService: ClientInfoService,
    private readonly cdRef: ChangeDetectorRef,
    private readonly geoblockingService: GeoblockingService,
    @Inject(PLATFORM_ID) private readonly platformId: Object,
    @Optional() private readonly mediaService: MediaService
  ) {
    super();
  }

  ngOnInit(): void {
    // Skip on SSR: X-Forwarded-For would carry the render server IP, not the real client's.
    if (!isPlatformBrowser(this.platformId)) {
      return;
    }

    this.watchBackgroundImage();
    this.loadClientInfo();
  }

  private watchBackgroundImage(): void {
    if (!this.mediaService) {
      return;
    }

    this.mediaService.media$.pipe(takeUntil(this.destroy$)).subscribe((media: Media) => {
      this.backgroundPath =
        media >= Media.md ? GeoBlockComponent.DESKTOP_BACKGROUND : GeoBlockComponent.MOBILE_BACKGROUND;
      this.cdRef.markForCheck();
    });
  }

  private loadClientInfo(): void {
    this.clientInfoService
      .getClientInfo()
      .pipe(takeUntil(this.destroy$))
      .subscribe((response: ClientInfoResponse) => {
        this.ipAddress = response.ipAddress;
        this.cdRef.markForCheck();
      });
  }
}
