import { ChangeDetectorRef, Directive, EventEmitter, Output } from '@angular/core';
import { BetSlipBetLinesService } from '../../services';
import { HttpErrorResponse } from '@angular/common/http';
import { Router } from '@angular/router';
import { EMPTY, from } from 'rxjs';
import { finalize, catchError, takeUntil, delay, switchMap, tap, filter } from 'rxjs/operators';
import { DestroySubject, DialogService } from '@honoregaming/core';
import { BetCategoryType } from '@honoregaming/types';
import { BetCodeErrorCode, BetCodeFailures } from '../../models';

@Directive()
export abstract class BetCodeBaseComponent extends DestroySubject {
  @Output() closeMenu = new EventEmitter<void>();

  betCode: string;
  loadingState: LoadingState = LoadingState.Loaded;
  errorState: ErrorState | BetCodeFailures = ErrorState.None;

  constructor(
    protected readonly dialogService: DialogService,
    protected readonly cdRef: ChangeDetectorRef,
    protected readonly router: Router,
    protected readonly betSlipBetLinesService: BetSlipBetLinesService
  ) {
    super();
  }

  getBetFromQrCode(): void {
    if (!this.betCode.startsWith('https')) {
      return this.getBetFromBetCode();
    }

    const tempArr: string[] = this.betCode.split('/');
    const shareCode: string = tempArr[tempArr.length - 1];
    const tempCode: string[] = shareCode.split(/[A-Z]/);
    this.betCode = tempCode[tempCode.length - 1];

    return this.getBetFromBetCode();
  }

  getBetFromBetCode(): void {
    this.errorState = ErrorState.None;
    this.loadingState = LoadingState.SearchLoading;

    this.betSlipBetLinesService
      .rehydrateFromBetCode(this.betCode)
      .pipe(
        takeUntil(this.destroy$),
        catchError((err: HttpErrorResponse) => {
          this.errorState = this.getErrorStateFromHttpError(err);
          return EMPTY;
        }),
        tap(result => {
          if (result.failure) {
            this.errorState = this.getErrorStateFromFailure(result.failure);
          }
        }),
        filter(result => !result.failure),
        switchMap(result =>
          from(
            this.router.navigate([result.betCategory === BetCategoryType.DrawGame ? '/draw-games' : '/sports'])
          ).pipe(
            delay(0),
            tap(() => {
              this.betCode = '';
              this.cdRef.markForCheck();
              this.dialogService.toggleDialog('betslip', true);
              this.closeMenu.emit();
            })
          )
        ),
        finalize(() => {
          this.loadingState = LoadingState.Loaded;
          this.cdRef.markForCheck();
        })
      )
      .subscribe();
  }

  private getErrorStateFromFailure(failure: BetCodeFailures): BetCodeFailures | ErrorState {
    const knownFailures: BetCodeFailures[] = [
      BetCodeFailures.NoBetFound,
      BetCodeFailures.BetCodeContainsOddsBoost,
      BetCodeFailures.BetCodeExpired
    ];

    return knownFailures.includes(failure) ? failure : ErrorState.SearchError;
  }

  private getErrorStateFromHttpError(err: HttpErrorResponse): BetCodeFailures {
    switch (err.error?.code) {
      case BetCodeErrorCode.BetCodeExpired:
        return BetCodeFailures.BetCodeExpired;
      case BetCodeErrorCode.BetCodeContainsOddsBoost:
        return BetCodeFailures.BetCodeContainsOddsBoost;
      default:
        return BetCodeFailures.NoBetFound;
    }
  }
}

export enum ErrorState {
  None = 'none',
  SearchError = 'searchError'
}

export enum LoadingState {
  Loaded = 'loaded',
  SearchLoading = 'searchLoading',
  ScanLoading = 'scanLoading'
}
