export class DateExtensions {}

declare global {
  interface Date {
    addDays(days: number, useThis?: boolean): Date;
    addWeeks(weeks: number, useThis?: boolean): Date;
    addMonths(months: number, useThis?: boolean): Date;
    addYears(years: number, useThis?: boolean): Date;
    today(): Date;
    isToday(): boolean;
    clone(): Date;
    isAnotherMonth(date: Date): boolean;
    isWeekend(): boolean;
    isSameDate(date: Date): boolean;
  }
}

Date.prototype.addDays = function (days: number): Date {
  if (!days) {
    return this;
  }
  const date = this;
  date.setDate(date.getDate() + days);
  return date;
};

Date.prototype.addWeeks = function (weeks: number): Date {
  const date = this;
  return date.addDays(weeks * 7);
};

Date.prototype.addMonths = function (months: number): Date {
  const date = this;
  return new Date(date.setMonth(date.getMonth() + months));
};

Date.prototype.addYears = function (years: number): Date {
  const date = this;
  return new Date(date.setFullYear(date.getFullYear() + years));
};

Date.prototype.today = function (): Date {
  return new Date();
};

Date.prototype.isToday = function (): boolean {
  const today = new Date();
  return this.isSameDate(today);
};

Date.prototype.clone = function (): Date {
  return new Date(+this);
};

Date.prototype.isAnotherMonth = function (date: Date): boolean {
  return date && this.getMonth() !== date.getMonth();
};

Date.prototype.isWeekend = function (): boolean {
  return this.getDay() === 0 || this.getDay() === 6;
};

Date.prototype.isSameDate = function (date: Date): boolean {
  return (
    date &&
    this.getFullYear() === date.getFullYear() &&
    this.getMonth() === date.getMonth() &&
    this.getDate() === date.getDate()
  );
};
