import { Pipe, PipeTransform } from '@angular/core';
import { globalConfiguration } from '@honoregaming/configuration';
@Pipe({
  name: 'hgVirtualTeamImageLink',
  pure: false
})
export class VirtualTeamImageLink implements PipeTransform {
  transform(teamName: string): any {
    return `${globalConfiguration.virtualTeamsFlagsBaseUrl}${teamName}.png`;
  }
}
