import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { globalConfiguration } from '@honoregaming/configuration';
import { Observable } from 'rxjs';
import { EventWithEventBetTypes, InstantGame, Match } from '@honoregaming/types';
import { Cacheable, CacheableVaryByKey } from '@honoregaming/core';
import { I18nService } from '@honoregaming/i18n';

@Injectable({ providedIn: 'root' })
export class TopMatchsInstantGamesService {
  @CacheableVaryByKey()
  userLanguage: string;

  constructor(private httpClient: HttpClient, private i18nService: I18nService) {
    this.i18nService.languageChanged$.subscribe(l => (this.userLanguage = l));
  }

  @Cacheable()
  getTopMatchs(): Observable<EventWithEventBetTypes<Match>[]> {
    return this.httpClient.get<EventWithEventBetTypes<Match>[]>(
      `${globalConfiguration.apiEventsBaseUrl}events/sports/mostplayed?${this.userLanguage}`
    );
  }

  @Cacheable()
  getTopInstantGames(): Observable<InstantGame[]> {
    return this.httpClient.get<[]>(`${globalConfiguration.apiEventsBaseUrl}instantgames/mostplayed`);
  }
}
