import { Injectable, Inject } from '@angular/core';
import { map } from 'rxjs/operators';
import { Observable, of, BehaviorSubject } from 'rxjs';
import { localeResources, registerStLocale, Format } from '../localeResources';
import { formatDate, formatNumber, formatCurrency, formatPercent } from '@angular/common';
import { CookieStorageService } from '@honoregaming/core';
import { roundNumber, scopeToken, Scope } from '@honoregaming/core';
import { resourcesProviderToken, IResourcesProviderService } from './resources-provider.service';
import { OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';

// TODO: abstraire cette partie pour que le préfix ne soit pas tjr cus (ex: pour l'admin ca devrait être adm)
const USER_LANGUAGE_KEY = 'cus_language';
const USER_FORMAT_KEY = 'cus_format';

@Injectable()
export class I18nService {
  currentLanguageCode: string = null;
  fallbackLanguageCode: string = 'en'; // Default fallback language
  currentLocaleFormats: Format = null;
  currentTimezoneOffset: string;
  private languageChangedSubject$ = new BehaviorSubject<string>(this.currentLanguageCode);
  languageChanged$ = this.languageChangedSubject$.asObservable();
  private localeChangedSubject$ = new BehaviorSubject<Format>(this.currentLocaleFormats);
  localeChanged$ = this.localeChangedSubject$.asObservable();

  constructor(
    private storageService: CookieStorageService,
    @Inject(resourcesProviderToken) private resourcesProviderService: IResourcesProviderService,
    @Inject(operatorConfigurationToken) private operatorConfiguration: OperatorConfiguration,
    @Inject(scopeToken) private scope: Scope
  ) {}

  init() {
    this.currentLanguageCode = this.storageService.getItem(USER_LANGUAGE_KEY);
    this.currentLocaleFormats = this.storageService.getItem(USER_FORMAT_KEY);
    if (this.scope === Scope.Agent || this.scope === Scope.Viewer) {
      this.currentTimezoneOffset = (<any>this.operatorConfiguration).timezoneOffset;
    }
    this.languageChangedSubject$.next(this.currentLanguageCode);
    this.localeChangedSubject$.next(this.currentLocaleFormats);
  }

  public setLanguage(languageCode: string): Observable<void> {
    if (this.currentLanguageCode === languageCode) {
      return of();
    }

    return this.resourcesProviderService.getLocaleResources(languageCode).pipe(
      map((resources: any) => {
        localeResources.formats = resources.formats;
        localeResources.formats.currencyAsPrefix = localeResources.formats.currencyFormat.indexOf('¤') === 0;
        localeResources.translations = resources.translations;
        registerStLocale(languageCode, localeResources.formats);
        this.currentLanguageCode = languageCode;
        this.currentLocaleFormats = localeResources.formats;
        this.languageChangedSubject$.next(this.currentLanguageCode);
        this.localeChangedSubject$.next(this.currentLocaleFormats);
        this.storageService.setItem(USER_LANGUAGE_KEY, languageCode);
      })
    );
  }

  public translate(key: string, ...values: string[]): Observable<string> {
    return this.languageChangedSubject$.pipe(
      map(() => {
        const keys = key.split('|');
        let resource = null;
        let i = 0;
        let actualKey: string;
        while (!resource && (actualKey = keys[i++])) {
          resource = localeResources.translations[actualKey];
        }

        if (resource === undefined) {
          return `TRANSLATION FOR ${key} NOT FOUND !!!!`;
        }

        if (!values || values.length === 0) {
          return resource;
        }

        values.forEach((v, i) => {
          resource = resource.replace(new RegExp('\\{' + i + '\\}', 'g'), v);
        });

        return resource;
      })
    );
  }

  public translateSync(key: string, ...values: string[]): string {
    const keys = key.split('|');
    let resource = null;
    let i = 0;
    let actualKey: string;
    while (!resource && (actualKey = keys[i++])) {
      resource = localeResources.translations[actualKey];
    }

    if (resource === undefined) {
      return `TRANSLATION FOR ${key} NOT FOUND !!!!`;
    }

    if (!values || values.length === 0) {
      return resource;
    }

    values.forEach((v, i) => {
      resource = resource.replace(new RegExp('\\{' + i + '\\}', 'g'), v);
    });

    return resource;
  }

  public translationKeyExistsSync(key: string): boolean {
    return localeResources.translations[key] !== undefined;
  }

  public translateWithFallbackSync(key: string, fallback: string): string {
    const keys = key.split('|');
    let resource = null;
    let i = 0;
    let actualKey: string;
    while (!resource && (actualKey = keys[i++])) {
      resource = localeResources.translations[actualKey];
    }

    if (resource === undefined && fallback === undefined) {
      return `TRANSLATION FOR ${key} NOT FOUND !!!!`;
    }

    if (resource === undefined && fallback !== undefined) {
      return fallback;
    }

    return resource;
  }

  public formatDate(date: string): Observable<string> {
    return this.languageChangedSubject$.pipe(
      map(() =>
        formatDate(
          date,
          localeResources.formats ? localeResources.formats.dateFormat : null,
          this.currentLanguageCode,
          this.currentTimezoneOffset
        )
      )
    );
  }

  public getMonthsNames(): Observable<string[]> {
    return this.languageChangedSubject$.pipe(map(() => localeResources.formats.monthResources.split(',')));
  }

  public getShortMonthsNamesSync(): string[] {
    return localeResources.formats.monthResources.split(',').map(x => (x.length > 5 ? x.slice(0, 3) : x));
  }

  public getWeekDaysNames(): Observable<string[]> {
    return this.languageChangedSubject$.pipe(map(() => localeResources.formats.dayResources.split(',')));
  }

  public formatLongDate(date: string): Observable<string> {
    return this.languageChangedSubject$.pipe(
      map(() =>
        formatDate(
          date,
          localeResources.formats ? localeResources.formats.longDateFormat : null,
          this.currentLanguageCode,
          this.currentTimezoneOffset
        )
      )
    );
  }

  public formatLongUtcDate(date: string): Observable<string> {
    return this.languageChangedSubject$.pipe(
      map(() =>
        formatDate(
          date,
          localeResources.formats ? localeResources.formats.longDateFormat : null,
          this.currentLanguageCode,
          'UTC'
        )
      )
    );
  }

  public formatTextDate(date: string): Observable<string> {
    return this.languageChangedSubject$.pipe(
      map(() =>
        formatDate(
          date,
          localeResources.formats ? localeResources.formats.textDateFormat : null,
          this.currentLanguageCode,
          this.currentTimezoneOffset
        )
      )
    );
  }

  public formatShortTextDate(date: string): Observable<string> {
    return this.languageChangedSubject$.pipe(
      map(() =>
        formatDate(
          date,
          localeResources.formats ? localeResources.formats.shortTextDateFormat : null,
          this.currentLanguageCode,
          this.currentTimezoneOffset
        )
      )
    );
  }

  public formatShortDate(date: string): Observable<string> {
    return this.languageChangedSubject$.pipe(
      map(() =>
        formatDate(
          date,
          localeResources.formats ? localeResources.formats.shortDateFormat : null,
          this.currentLanguageCode,
          this.currentTimezoneOffset
        )
      )
    );
  }

  public formatShortDateSync(date: string): string {
    return formatDate(
      date,
      localeResources.formats ? localeResources.formats.shortDateFormat : null,
      this.currentLanguageCode,
      this.currentTimezoneOffset
    );
  }

  public formatMonthDate(date: string): Observable<string> {
    return this.languageChangedSubject$.pipe(
      map(() =>
        formatDate(
          date,
          localeResources.formats ? localeResources.formats.monthDateFormat : null,
          this.currentLanguageCode,
          this.currentTimezoneOffset
        )
      )
    );
  }

  public formatMonthDateSync(date: string): string {
    return formatDate(
      date,
      localeResources.formats ? localeResources.formats.monthDateFormat : null,
      this.currentLanguageCode,
      this.currentTimezoneOffset
    );
  }

  public formatTimeSync(time: string): string {
    return formatDate(
      time,
      localeResources.formats ? localeResources.formats.timeFormat : null,
      this.currentLanguageCode,
      this.currentTimezoneOffset
    );
  }

  public formatTime(time: string): Observable<string> {
    return this.languageChangedSubject$.pipe(
      map(() =>
        formatDate(
          time,
          localeResources.formats ? localeResources.formats.timeFormat : null,
          this.currentLanguageCode,
          this.currentTimezoneOffset
        )
      )
    );
  }

  public formatLongTime(time: string): Observable<string> {
    return this.languageChangedSubject$.pipe(
      map(() =>
        formatDate(
          time,
          localeResources.formats ? localeResources.formats.longTimeFormat : null,
          this.currentLanguageCode,
          this.currentTimezoneOffset
        )
      )
    );
  }

  public formatPercent(percent: string): string {
    return formatPercent(
      parseFloat(percent),
      this.currentLanguageCode || this.operatorConfiguration.localization.defaultLanguage,
      `1.0-1`
    );
  }

  public formatCurrency(value: number, withSymbol: boolean = false, forceDecimals: boolean = null): Observable<string> {
    const decimals = forceDecimals ? 2 : Math.max(this.operatorConfiguration.currency.numberOfDecimals, 0);
    value = roundNumber(value, decimals);
    return this.languageChangedSubject$.pipe(
      map(() =>
        formatCurrency(
          value,
          this.currentLanguageCode,
          withSymbol ? this.operatorConfiguration.currency.symbol : '',
          null,
          `1.${decimals}-${decimals}`
        ).trim()
      )
    );
  }

  public formatCurrencySync(value: number, withSymbol: boolean = false): string {
    const decimals = Math.max(this.operatorConfiguration.currency.numberOfDecimals, 0);
    value = roundNumber(value, this.operatorConfiguration.currency.numberOfDecimals);
    return formatCurrency(
      value,
      this.currentLanguageCode,
      withSymbol ? this.operatorConfiguration.currency.symbol : '',
      null,
      `1.${decimals}-${decimals}`
    ).trim();
  }

  public formatNumber(decimal: number, withDecimal: boolean = true, digitsInfo?: string): Observable<string> {
    return this.languageChangedSubject$.pipe(map(() => this.formatNumberSync(decimal, withDecimal, digitsInfo)));
  }

  public formatNumberSync(decimal: number, withDecimal: boolean = true, digitsInfo?: string): string {
    if (!withDecimal) {
      return formatNumber(decimal, this.currentLanguageCode, '1.0-0');
    }

    return formatNumber(decimal, this.currentLanguageCode, digitsInfo);
  }

  formatIntegerNumber(number: any, digitCount: number): string {
    let result = number && number.toString().length > 0 && Number.isInteger(+number) ? number.toString() : '';
    if (result && result.length < digitCount) {
      result = '0'.repeat(digitCount - result.length) + result;
    }

    return result;
  }

  public unformatNumber(number: string): number {
    if (this.currentLocaleFormats) {
      number = number
        .replace(' ', '')
        .replace(this.currentLocaleFormats.thousandSeparator, '')
        .replace(this.currentLocaleFormats.decimalSeparator, '.');
      return parseFloat(number);
    } else {
      if (isNaN(+number)) {
        return NaN;
      } else {
        return +number;
      }
    }
  }
}
