import { Inject, Injectable } from '@angular/core';
import { Observable, of } from 'rxjs';
import { filter, map, switchMap, take } from 'rxjs/operators';
import { BetLine, FreeBetCoupon, FreeBetCouponBetSlip, IBetValidationService } from '@honoregaming/betslip';
import { MessageService } from '@honoregaming/ui';
import { AuthService, FreeBetService } from '@honoregaming/customer-core';
import { BalanceNotEnoughComponent } from '@honoregaming/customer-ui';
import { BetCategoryType, BetSlipMode } from '@honoregaming/types';
import { OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';

@Injectable({ providedIn: 'root' })
export class BetValidationService implements IBetValidationService {
  constructor(
    private readonly authService: AuthService,
    private readonly messageService: MessageService,
    private readonly freeBetService: FreeBetService,
    @Inject(operatorConfigurationToken) private readonly operatorConfig: OperatorConfiguration
  ) {}

  canPlaceBet(
    betTotalStake: number,
    _betCategory: BetCategoryType,
    freeBetBalance?: number,
    showMessage: boolean = true
  ): Observable<{ result: boolean; reason?: string }> {
    return this.authService.me$.pipe(
      take(1),
      map(me => {
        const isFreeBet: boolean = freeBetBalance != null;
        const balance: number = isFreeBet ? freeBetBalance : me?.balance ?? 0;

        if (balance < betTotalStake) {
          if (showMessage) {
            this.showBalanceNotEnoughMessage(isFreeBet);
          }
          return { result: false };
        }

        return { result: true };
      })
    );
  }

  private showBalanceNotEnoughMessage(isFreeBet: boolean): void {
    this.messageService.sendComponentMessage(BalanceNotEnoughComponent, {
      titleTranslation: 'POPIN.BALANCE_NOT_ENOUGH.TITLE',
      bodyTranslation: isFreeBet ? 'POPIN.FREE_BALANCE_NOT_ENOUGH' : 'POPIN.BALANCE_NOT_ENOUGH',
      isFreeBet
    });
  }

  canUseFreeBetCoupons(
    betSlipMode: BetSlipMode,
    betCategoryType: BetCategoryType,
    completeMyBetCouponId?: number
  ): Observable<{ result: boolean; coupons?: FreeBetCoupon[] }> {
    if (betSlipMode === BetSlipMode.Systems) {
      return of({ result: false });
    }
    if (
      betCategoryType === BetCategoryType.SportsFixedOdds ||
      betCategoryType === BetCategoryType.VirtualFixedOdds ||
      betCategoryType === BetCategoryType.SportsPool
    ) {
      return this.freeBetService.getFreeBetCouponsByType(true, betCategoryType, completeMyBetCouponId).pipe(
        filter(x => !!x),
        take(1),
        switchMap(coupons => {
          if (coupons.length === 0) {
            return of([] as FreeBetCoupon[]);
          }
          if (!this.validateFreeBetCouponsIntegrity(coupons)) {
            return this.freeBetService.forceRefreshFreeBetCoupon(true, betCategoryType);
          }
          return of(coupons);
        }),
        map(coupons => {
          if (coupons.length === 0) {
            return { result: false };
          } else {
            return { result: true, coupons };
          }
        })
      );
    }

    return of({ result: false });
  }

  private validateFreeBetCouponsIntegrity(coupons: FreeBetCoupon[]) {
    const now = new Date();

    for (const coupon of coupons) {
      if (coupon.expirationDate <= now) {
        return false;
      }
    }

    return true;
  }

  canUseLeftoverBalance(
    betCategoryType: BetCategoryType,
    betLines: BetLine[],
    freeBetModeEnabled: boolean,
    freeBetCoupon?: FreeBetCouponBetSlip
  ): Observable<{ result: boolean; amount: number }> {
    if (freeBetCoupon && freeBetModeEnabled) {
      let leftOverFreeBetEnabled = this.operatorConfig.freeBetsConfiguration?.leftOverFreeBetEnabled ?? false;

      if (
        leftOverFreeBetEnabled &&
        (betCategoryType === BetCategoryType.SportsFixedOdds || betCategoryType === BetCategoryType.VirtualFixedOdds) &&
        freeBetCoupon.useLeftOver
      ) {
        return of({ result: true, amount: freeBetCoupon.balance });
      } else {
        return of({ result: false, amount: 0 });
      }
    } else if (freeBetModeEnabled) {
      return of({ result: false, amount: 0 });
    }

    return this.authService.me$.pipe(
      take(1),
      map(me => {
        if (
          me?.balance > 0 &&
          this.operatorConfig.operatorFeatures.indexOf('LeftoverBalance') !== -1 &&
          (betCategoryType === BetCategoryType.SportsFixedOdds ||
            betCategoryType === BetCategoryType.VirtualFixedOdds) &&
          me.balance < Math.max(...betLines.map(l => l.baseAmount))
        ) {
          return { result: true, amount: me.balance };
        }
        return { result: false, amount: 0 };
      })
    );
  }
}
