import { Event } from '../event.model';
import { HorseRaceRunner } from './horse-race.runner.model';
import { HorseRacingRaceCategoryType } from './horseracing-category.enum';

export interface HorseRace extends Event {
  runners: HorseRaceRunner[];
  runnersCount?: number;
  meeting: HorseRaceMeeting;
  number: number;
  category: HorseRacingRaceCategoryType;
  horseRaceState: HorseRaceStateType;
  distance: number;
  pricesTotal: number;
  dataSourceId: number;
  raceConditionDescription: string;
}

export interface HorseRaceMeeting {
  number: number;
  name: string;
  date: Date;
}

export enum HorseRaceStateType {
  Unknown = 'Unknown',
  Programmed = 'Programmed',
  Undisputed = 'Undisputed',
  InSale = 'InSale',
  SaleStopped = 'SaleStopped',
  Start = 'Start',
  Started = 'Started',
  TemporaryArrived = 'TemporaryArrived',
  DefinitiveArrived = 'DefinitiveArrived',
  Inquiry = 'Inquiry',
  Reported = 'Reported',
  Cancelled = 'Cancelled',
  PaymentAuthorized = 'PaymentAuthorized',
  PaymentStopped = 'PaymentStopped',
  Closed = 'Closed'
}
