import { BetLine } from '../models';
import {
  HorseRacingFormulaKeyType,
  HorseRaceEventBetType,
  BetCategoryType,
  HorseRacingFlexi
} from '@honoregaming/types';
import { getMultipleForHorseRacing } from './bet-slip.utils';
import { horseRaceBetTypesConfiguration } from '@honoregaming/core';

export function setSpot(betLine: BetLine, eventBetType: HorseRaceEventBetType, spotEnabled: boolean): BetLine {
  const betLineToUpdate = {
    ...betLine,
    quickPick: spotEnabled
  };

  if (betLineToUpdate.quickPick) {
    betLineToUpdate.baseList = new Array(betLine.selectionLength).fill('Y');
  } else {
    betLineToUpdate.baseList = [];
  }

  betLineToUpdate.formula = computeFormula(betLineToUpdate, eventBetType);
  return betLineToUpdate;
}

export function setSelectionLength(
  betLine: BetLine,
  eventBetType: HorseRaceEventBetType,
  selectionLength: number
): BetLine {
  const betLineToUpdate = {
    ...betLine,
    selectionLength: selectionLength,
    multiValue: selectionLength
  };

  if (
    betLineToUpdate.formula.key === HorseRacingFormulaKeyType.PartWheel ||
    betLineToUpdate.formula.key === HorseRacingFormulaKeyType.Wheel
  ) {
    betLineToUpdate.baseList = [];
    betLineToUpdate.associatedList = null;
  }

  if (betLineToUpdate.quickPick) {
    betLineToUpdate.baseList = new Array(betLineToUpdate.selectionLength).fill('Y');
  }

  betLineToUpdate.formula = computeFormula(betLineToUpdate, eventBetType);
  return betLineToUpdate;
}

export function addToBaseList(betLine: BetLine, eventBetType: HorseRaceEventBetType, ...itemsToAdd: string[]): BetLine {
  const betLineToUpdate = {
    ...betLine,
    baseList: [...betLine.baseList, ...itemsToAdd]
  };

  betLineToUpdate.formula = computeFormula(betLineToUpdate, eventBetType);
  return betLineToUpdate;
}

export function addToAssociatedList(betLine: BetLine, eventBetType: HorseRaceEventBetType, itemToAdd: string): BetLine {
  const betLineToUpdate = {
    ...betLine,
    associatedList: [...betLine.associatedList, itemToAdd]
  };

  betLineToUpdate.formula = computeFormula(betLineToUpdate, eventBetType);
  return betLineToUpdate;
}

export function removeLastFromBaseList(betLine: BetLine, eventBetType: HorseRaceEventBetType): BetLine {
  const betLineToUpdate = {
    ...betLine,
    baseList: betLine.baseList.slice(0, -1)
  };

  betLineToUpdate.formula = computeFormula(betLineToUpdate, eventBetType);
  return betLineToUpdate;
}

export function removeLastFromAssociatedList(betLine: BetLine, eventBetType: HorseRaceEventBetType): BetLine {
  const betLineToUpdate = {
    ...betLine,
    associatedList: betLine.associatedList.slice(0, -1)
  };

  betLineToUpdate.formula = computeFormula(betLineToUpdate, eventBetType);
  return betLineToUpdate;
}

export function initializeAssociatedList(betLine: BetLine, eventBetType: HorseRaceEventBetType): BetLine {
  const betLineToUpdate = {
    ...betLine,
    associatedList: []
  };

  betLineToUpdate.formula = computeFormula(betLineToUpdate, eventBetType);
  return betLineToUpdate;
}

export function clearAssociatedList(betLine: BetLine, eventBetType: HorseRaceEventBetType): BetLine {
  const betLineToUpdate = {
    ...betLine,
    associatedList: null
  };

  betLineToUpdate.formula = computeFormula(betLineToUpdate, eventBetType);
  return betLineToUpdate;
}

export function computeFormula(betLine: BetLine, eventBetType: HorseRaceEventBetType) {
  if (betLine.associatedList) {
    return eventBetType.formulas.find(f => f.key === HorseRacingFormulaKeyType.PartWheel);
  } else {
    if (betLine.baseList.indexOf('X') >= 0) {
      return eventBetType.formulas.find(f => f.key === HorseRacingFormulaKeyType.Wheel);
    } else {
      return betLine.baseList.length > betLine.selectionLength
        ? eventBetType.formulas.find(f => f.key === HorseRacingFormulaKeyType.Combined)
        : eventBetType.formulas.find(f => f.key === HorseRacingFormulaKeyType.Unit);
    }
  }
}

export function computeAmountForHorseRacing(
  betLine: BetLine,
  isDefault?: boolean
): { betLine: BetLine; amount: number } {
  if (
    betLine.betCategoryType !== BetCategoryType.HorseRacingMutualInternationalPool &&
    betLine.betCategoryType !== BetCategoryType.HorseRacingMutualOperatorPool
  ) {
    return null;
  }

  const multiple = getMultipleForHorseRacing(
    betLine.selectionLength,
    betLine.runners.filter(r => !r.nonRunner).length,
    betLine.baseList.filter(x => x !== 'X').length,
    betLine.associatedList?.length || 0,
    betLine.formula.key,
    horseRaceBetTypesConfiguration[betLine.betTypeId].isOrdered,
    betLine.allOrders
  );

  let amount: number = null;

  const betLineToUpdate: BetLine = {
    ...betLine
  };

  if (multiple || isDefault) {
    const multipleAmount = (isDefault ? 1 : multiple) * betLineToUpdate.baseStake;

    amount = multipleAmount * betLineToUpdate.multiplier;
    betLineToUpdate.multipliers = [];
    if (betLineToUpdate.flexi === HorseRacingFlexi.Flexi50) {
      if (betLineToUpdate.baseAmount <= multipleAmount * 0.5) {
        betLineToUpdate.multipliers.push({ value: 0.5, label: 'Flexi 50%' });
      }
    } else if (betLineToUpdate.flexi === HorseRacingFlexi.Flexi50_25) {
      if (betLineToUpdate.baseAmount <= multipleAmount * 0.25) {
        betLineToUpdate.multipliers.push({ value: 0.25, label: 'Flexi 25%' });
      }
      if (betLineToUpdate.baseAmount <= multipleAmount * 0.5) {
        betLineToUpdate.multipliers.push({ value: 0.5, label: 'Flexi 50%' });
      }
    } else if (betLineToUpdate.flexi === HorseRacingFlexi.Flexi50_25_10) {
      if (betLineToUpdate.baseAmount <= multipleAmount * 0.1) {
        betLineToUpdate.multipliers.push({ value: 0.1, label: 'Flexi 10%' });
      }
      if (betLineToUpdate.baseAmount <= multipleAmount * 0.25) {
        betLineToUpdate.multipliers.push({ value: 0.25, label: 'Flexi 25%' });
      }
      if (betLineToUpdate.baseAmount <= multipleAmount * 0.5) {
        betLineToUpdate.multipliers.push({ value: 0.5, label: 'Flexi 50%' });
      }
    }

    let multipliers = betLineToUpdate.allowedMultipliers ?? [1, 2, 5, 10, 20, 50, 100, 1000]; // maybe move these default values to backend ?
    multipliers.forEach(m => {
      if (
        m * multipleAmount >= betLineToUpdate.baseAmount &&
        !betLineToUpdate.multipliers?.some(e => e.value == m) &&
        (!betLineToUpdate.maximumAmount || betLineToUpdate.maximumAmount >= multipleAmount * m)
      ) {
        betLineToUpdate.multipliers.push({ value: m, label: m.toString() });
      }
    });
  } else {
    betLineToUpdate.multipliers = [{ value: 1, label: '1' }];
    betLineToUpdate.multiplier = 1;
  }

  betLineToUpdate.totalStake = amount;
  return { betLine: betLineToUpdate, amount: amount };
}
