import { animate, AnimationEvent, state, style, transition, trigger } from '@angular/animations';
import {
  Component,
  ChangeDetectionStrategy,
  Input,
  ChangeDetectorRef,
  ElementRef,
  ViewChild,
  AfterViewInit
} from '@angular/core';

@Component({
  selector: 'hg-marquee',
  templateUrl: './marquee.component.html',
  styleUrls: ['./marquee.component.scss'],
  animations: [
    trigger('scrollLeft', [
      state('scroll', style({ left: '-{{directionOffset}}px' }), { params: { directionOffset: 0 } }),
      state('reset', style({ left: '*' })),
      transition('* => scroll', [animate('{{transitionParams}}')]),
      transition('scroll => reset', [animate(0)])
    ])
  ],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class MarqueeComponent implements AfterViewInit {
  @Input()
  public message: string;

  @ViewChild('hgScrollParent') hgScrollParent: ElementRef;
  @ViewChild('hgScrollRef') hgScrollRef: ElementRef;

  transitionCurve: string = 's cubic-bezier(0.17, 0.01, 0.82, 0.96)';
  transitionOption: string;

  internalState: 'scroll' | 'reset';
  scrollEnabled: boolean = false;

  internalWrapperWidth: number;
  internalSpanWidth: number;
  internalScrollWidth: number;
  defaultGapInPixels: number = 60; // gap between duplicated content
  travelDurationSpeedByPixels: number = 4;

  afterViewInit: boolean;

  constructor(private cdRef: ChangeDetectorRef) {}

  ngAfterViewInit(): void {
    if (this.hgScrollParent && this.hgScrollRef) {
      this.internalWrapperWidth = this.hgScrollParent.nativeElement.offsetWidth;
      this.internalSpanWidth = this.hgScrollRef.nativeElement.offsetWidth;

      // We set the translation of 100px to 4seconds.
      let totalDuration = Math.ceil((this.travelDurationSpeedByPixels * this.internalSpanWidth) / 100);
      this.transitionOption = `${totalDuration}${this.transitionCurve}`;

      if (this.internalWrapperWidth < this.internalSpanWidth) {
        this.internalState = 'scroll';
        this.internalScrollWidth = this.internalSpanWidth + this.defaultGapInPixels;

        // Delay the first scroll
        setTimeout(() => {
          this.scrollEnabled = true;
          this.cdRef.markForCheck();
        }, 2000);
      }
    }

    this.afterViewInit = true;
    this.cdRef.markForCheck();
  }

  onScrollDone(event: AnimationEvent) {
    switch (event.toState) {
      case 'scroll':
        setTimeout(() => {
          this.internalState = 'reset';
          this.cdRef.markForCheck();
        }, 3000);
        break;
      case 'reset':
        this.internalState = 'scroll';
        this.cdRef.markForCheck();
    }
  }
}
