export interface Operation {
  id: number;
  dateTime: Date;
  type: OperationType;
  detail?: OperationDetail;
  amount: number;
  taxAmount?: number;
  freeAmount: number;
  freeSpinAmount: number;
  loyaltyPoints: number;
  status: OperationStatus;
  operationRef: string;
  provider: string;
  statusDetail: StatusDetail;
  comment: string;
  data: OperationData;
  batchActionName?: string;
  freeSpin?: boolean;
  method?: string;
}

export interface OperationData {
  withdrawalNumber: string;
}

export enum OperationType {
  Unknown = 'Unknown',
  BetPlaced = 'BetPlaced',
  BetPaid = 'BetPaid',
  Deposit = 'Deposit',
  Withdrawal = 'Withdrawal',
  Correction = 'Correction',
  InstantGameTransaction = 'InstantGameTransaction',
  Loyalty = 'Loyalty',
  Bonus = 'Bonus',
  Charity = 'Charity',
  SimulatedBet = 'SimulatedBet',
  SessionTax = 'SessionTax',
  TournamentPrize = 'TournamentPrize'
}

export enum OperationDetail {
  Unknown = 'Unknown',
  ReferralTransaction = 'ReferralTransaction',
  ReferralRegistration = 'ReferralRegistration',
  BonusFirstTimeDeposit = 'BonusFirstTimeDeposit',
  BonusNextTimeDeposit = 'BonusNextTimeDeposit',
  BatchAction = 'BatchAction',
  CasinoCashDrop = 'CasinoCashDrop',
  CasinoFreeSpinRain = 'CasinoFreeSpinRain',
  FreeSpinDistribution = 'FreeSpinDistribution'
}

export enum OperationStatus {
  WaitingAdministratorValidation = 'WaitingAdministratorValidation',
  Initiated = 'Initiated',
  Canceled = 'Cancelled',
  Validated = 'Validated',
  Processed = 'Processed',
  InternalInitiated = 'InternalInitiated'
}

export enum StatusDetail {
  Cancel,
  IncorrectPin,
  IncorrectCode,
  InsufficientFund,
  Expired
}
