import { ITelemetryService } from './telemetry-service.model';
import { Injectable, Inject, PLATFORM_ID } from '@angular/core';
import { isPlatformBrowser } from '@angular/common';
import { take, tap } from 'rxjs/operators';
import { CustomerOperatorConfiguration, customerOperatorConfigurationToken } from '../../models';
import { AuthService } from '../auth.service';
import { BetCategoryType } from '@honoregaming/types';

@Injectable()
export class GeniusSportTelemetryService implements ITelemetryService {
  isBrowser = isPlatformBrowser(this.platformId);
  configuration = this.operatorConfig.telemetryConfiguration.geniusSport;

  routeByBetCategories = {
    [BetCategoryType[BetCategoryType.SportsFixedOdds]]: 'sports',
    [BetCategoryType[BetCategoryType.InstantGame]]: 'instant-games',
    [BetCategoryType[
      (BetCategoryType.HorseRacingMutualOperatorPool, BetCategoryType.HorseRacingMutualInternationalPool)
    ]]: 'horseracing'
  };

  constructor(
    @Inject(customerOperatorConfigurationToken) private operatorConfig: CustomerOperatorConfiguration,
    private authService: AuthService,
    @Inject(PLATFORM_ID) private platformId
  ) {}

  trackPageView(name: string, path: string): void {
    const instantGamePath =
      this.operatorConfig.betCategoriesPathConfiguration?.instantGamesConfiguration?.path ?? 'instant-games';
    this.routeByBetCategories[BetCategoryType[BetCategoryType.InstantGame]] = instantGamePath;
    const defaultRoute =
      this.routeByBetCategories[BetCategoryType[this.operatorConfig.features.defaultBetCategory]] ?? 'sports';

    if (name === '/' + defaultRoute && path === '/' + defaultRoute) {
      this.addScript('homepage');
    }
  }

  trackEvent(name: string, properties: any): void {
    if (this.isBrowser) {
      this.authService.me$
        .pipe(
          take(1),
          tap(me => {
            if (me) {
              switch (name) {
                case 'sign_up_complete': {
                  this.addScript('regconfirm', 'AccountID=' + me.id);
                  break;
                }

                case 'login': {
                  this.addScript('loggedin', 'AccountID=' + me.id);
                  break;
                }

                case 'firstTimeDeposit': {
                  this.addScript('firstdepositconfirm', 'AccountID=' + me.id + '&Stake=' + properties.amount);
                  break;
                }

                case 'deposit': {
                  this.addScript(
                    'depositconfirm',
                    'AccountID=' + me.id + '&TransactionID=' + properties.id + '&Amount=' + properties.amount
                  );
                  break;
                }

                case 'bet_placed': {
                  this.addScript(
                    'betconfirm',
                    'AccountID=' + me.id + '&Stake=' + properties.bet.amounts.summary.totalStakeWithTax ||
                      properties.bet.amounts.summary.totalStake
                  );
                  break;
                }

                case 'self_exclusion': {
                  this.addScript('exclusion');
                  break;
                }
              }
            }

            switch (name) {
              case 'sign_up_started': {
                this.addScript('regstart');
                break;
              }

              case 'privacy_consent': {
                if (!properties) {
                  this.addScript('cookie_exclusion');
                }
                break;
              }
            }
          })
        )
        .subscribe();
    }
  }

  addScript(path: string, parameters?: string) {
    const existingScript = document.getElementById('geniusSport-script');
    if (existingScript) {
      existingScript.parentNode.removeChild(existingScript);
    }

    const script = document.createElement('script');
    script.id = 'geniusSport-script';
    script.async = true;
    script.defer = true;
    script.src = 'https://zz.connextra.com/dcs/tagController/tag/' + this.configuration.clientId + '/' + path;

    if (parameters) {
      script.src += '?' + parameters;
    }

    let parent = document.getElementsByTagName('script')[0];
    parent.parentNode.insertBefore(script, parent);
  }
}
