import { Component, ChangeDetectionStrategy, Input, OnChanges } from '@angular/core';

@Component({
  selector: 'hg-penalty-result',
  templateUrl: './penalty-result.component.html',
  styleUrls: ['./penalty-result.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class PenaltyResultComponent implements OnChanges {
  @Input()
  result: any;

  parsedResult: { selectionResult: number[] };

  constructor() {}

  ngOnChanges() {
    this.parsedResult = JSON.parse(this.result);
  }
}
