import { HttpClient, HttpHeaders } from '@angular/common/http';
import { Inject, Injectable } from '@angular/core';
import { Observable } from 'rxjs';
import { OperatorConfiguration, globalConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';
import { SecurityPolicy, CountryCode } from '@honoregaming/types';
import { switchMap, take, tap } from 'rxjs/operators';
import { AuthService } from './auth.service';
import { TelemetryService } from './telemetry/telemetry.service';
import { Cacheable, CookieStorageService } from '@honoregaming/core';
import { ASESSION, EXTERNAL_AFFILIATE_TOKEN } from 'projects/customer/customer/src/app/constants/affiliate.constant';
import { S2S_TRACKER_NAME, S2S_CLICK_ID } from 'projects/customer/customer/src/app/constants/s2s.constant';
import { IncomeSourceType } from 'projects/core/hg-types/models/enums/income-source-type.enum';
import { CreateCustomerResponse } from '../models/create-customer-response.model';
import { SESSION_IDENTIFIER, TrackingEventType } from '../models';
import { TrackingService } from './tracking.service';

@Injectable()
export class CustomerService {
  constructor(
    private httpClient: HttpClient,
    private authService: AuthService,
    private storageService: CookieStorageService,
    private telemetryService: TelemetryService,
    private trackingService: TrackingService,
    @Inject(operatorConfigurationToken) private operatorConfiguration: OperatorConfiguration
  ) {}

  signup(
    login: string,
    password: string,
    referrerCode: string = null,
    profile: Map<string, string> = null,
    recaptchaToken: string = null
  ): Observable<CreateCustomerResponse> {
    let header: HttpHeaders = new HttpHeaders();

    const affiliateSessionId: string = this.storageService.getItem(ASESSION);
    if (affiliateSessionId) {
      header = header.set(ASESSION, affiliateSessionId);
    }

    const visitorSessionId: string = this.storageService.getItem(SESSION_IDENTIFIER);
    if (visitorSessionId) {
      header = header.set(SESSION_IDENTIFIER, visitorSessionId);
    }

    const externalAffiliateToken: string = this.storageService.getItem(EXTERNAL_AFFILIATE_TOKEN);
    if (externalAffiliateToken) {
      header = header.set(EXTERNAL_AFFILIATE_TOKEN, externalAffiliateToken);
    }

    const s2sTrackerName: string = this.storageService.getItem(S2S_TRACKER_NAME);
    if (s2sTrackerName) {
      header = header.set(S2S_TRACKER_NAME, encodeURIComponent(s2sTrackerName));
    }

    const s2sCapturedClickId: string = this.storageService.getItem(S2S_CLICK_ID);
    if (s2sCapturedClickId) {
      header = header.set(S2S_CLICK_ID, encodeURIComponent(s2sCapturedClickId));
    }

    return this.httpClient.post<CreateCustomerResponse>(
      `${globalConfiguration.apiBaseUrl}profile`,
      {
        login,
        password,
        referrerCode,
        profile,
        recaptchaToken
      },
      { headers: header }
    );
  }

  checkLoginAvailibity(login: string, password: string, referrerCode: string = null, email: string): Observable<{}> {
    var sessionId = this.storageService.getItem(ASESSION);
    let header = new HttpHeaders();
    if (sessionId) {
      header = header.set(ASESSION, sessionId);
    }
    return this.httpClient.post<{}>(
      `${globalConfiguration.apiBaseUrl}profile/check-infos`,
      {
        login,
        password,
        referrerCode,
        email
      },
      { headers: header }
    );
  }

  @Cacheable()
  getSecurityPolicy(): Observable<SecurityPolicy> {
    return this.httpClient.get<SecurityPolicy>(
      `${globalConfiguration.staticAssetsPath}${this.operatorConfiguration.commercialCode}/security-policy.json`
    );
  }

  @Cacheable()
  getCountryCodes(): Observable<CountryCode[]> {
    return this.httpClient.get<CountryCode[]>(`${globalConfiguration.assetsPath}country-codes/country-codes.json`);
  }

  validate(validationCode: string): Observable<void> {
    return this.authService.me$.pipe(
      take(1),
      switchMap(me =>
        this.httpClient.post<void>(`${globalConfiguration.apiBaseUrl}profile/validate`, { validationCode }).pipe(
          tap(() => {
            this.telemetryService.trackEvent('sign_up_complete', { accountId: me.id });

            this.trackingService
              .trackEvent({
                eventType: TrackingEventType.NewRegistrationCustomer
              })
              .subscribe();
          })
        )
      )
    );
  }

  resetValidationCode(recaptchaToken: string = null, mfaScope: boolean = false) {
    return this.httpClient.post(`${globalConfiguration.apiBaseUrl}profile/reset-validationcode`, {
      recaptchaToken,
      mfaScope
    });
  }

  changePassword(oldPassword: string, newPassword: string, validationCode?: string) {
    return this.httpClient.post(`${globalConfiguration.apiBaseUrl}profile/changePassword`, {
      oldPassword,
      newPassword,
      validationCode
    });
  }

  getResetCode(login: string, recaptchaToken: string = null) {
    return this.httpClient.post(`${globalConfiguration.apiBaseUrl}profile/lost-password`, {
      login,
      recaptchaToken
    });
  }

  resetPassword(login: string, validationCode: string, newPassword?: string) {
    return this.httpClient.post(`${globalConfiguration.apiBaseUrl}profile/reset-password`, {
      login,
      validationCode,
      newPassword
    });
  }

  resetCheckValidationCode(login: string, validationCode: string) {
    return this.httpClient.post(`${globalConfiguration.apiBaseUrl}profile/reset-check-validationcode`, {
      login,
      validationCode
    });
  }

  acceptGCU() {
    return this.httpClient
      .put(`${globalConfiguration.apiBaseUrl}profile/accept-gcu`, null)
      .pipe(switchMap(() => this.authService.getMe()));
  }

  updateCustomerProfile(
    country: string,
    phoneNumber: string,
    birthdate: Date,
    city: string,
    gender: string,
    state: string,
    street: string,
    firstName: string,
    middleName: string,
    lastName: string,
    email: string,
    incomeSource: IncomeSourceType,
    zipCode: string,
    nationality: string,
    politicallyExposedPerson?: boolean,
    validationCode?: string
  ) {
    return this.httpClient.put(`${globalConfiguration.apiBaseUrl}profile`, {
      country,
      phoneNumber,
      birthdate,
      city,
      gender,
      state,
      street,
      firstName,
      lastName,
      email,
      middleName,
      incomeSource,
      zipCode,
      nationality,
      politicallyExposedPerson,
      validationCode
    });
  }

  updateEmail(email: string, validationCode?: string) {
    return this.httpClient.put(`${globalConfiguration.apiBaseUrl}profile/email`, { email, validationCode });
  }

  finishIdentityCustomerValidation() {
    return this.httpClient.put(`${globalConfiguration.apiBaseUrl}profile/status`, {});
  }

  unlockAccount(validationCode: string): Observable<void> {
    return this.authService.me$.pipe(
      take(1),
      switchMap(me =>
        this.httpClient.post<void>(`${globalConfiguration.apiBaseUrl}profile/unlock-account`, {
          login: me.login,
          validationCode
        })
      )
    );
  }

  getCaptcha(targetElement: string): Observable<{ transactionIdentifier: string; script: string }> {
    return this.httpClient.get<{ transactionIdentifier: string; script: string }>(
      `${globalConfiguration.apiBaseUrl}operatordata/captcha?targetElement=${encodeURIComponent(targetElement)}`
    );
  }

  checkIfCustomerExists(login: string, recaptchaToken: string = null): Observable<boolean> {
    return this.httpClient.post<boolean>(`${globalConfiguration.apiBaseUrl}profile/check-exists`, {
      login,
      recaptchaToken
    });
  }

  getExternalKYCValidationUrl(): Observable<string> {
    return this.httpClient.get<string>(`${globalConfiguration.apiBaseUrl}profile/kyc-informations`);
  }

  toggleHideBalance(newHideBalance: boolean): Observable<void> {
    return this.httpClient.put<void>(`${globalConfiguration.apiBaseUrl}profile/hide-balance`, {
      hideBalance: newHideBalance
    });
  }
}
