import { ITelemetryService } from './telemetry-service.model';
import { Injectable, Inject, PLATFORM_ID } from '@angular/core';

import { DOCUMENT, isPlatformBrowser } from '@angular/common';
import { CustomerOperatorConfiguration, customerOperatorConfigurationToken } from '../../models';
declare var esk;

@Injectable()
export class EsKimiTelemetryService implements ITelemetryService {
  isBrowser = isPlatformBrowser(this.platformId);
  configuration = this.operatorConfig.telemetryConfiguration.eskimi;

  constructor(
    @Inject(customerOperatorConfigurationToken) private operatorConfig: CustomerOperatorConfiguration,
    @Inject(DOCUMENT) document: Document,
    @Inject(PLATFORM_ID) private platformId
  ) {
    if (!this.isBrowser) return;
    if ((window as any).esk) return;
    let n: any = ((window as any).esk = function () {
      n.callMethod ? n.callMethod.apply(n, arguments) : n.queue.push(arguments);
    });
    if (!(window as any).___esk) (window as any).___esk = n;
    n.push = n;
    n.loaded = true;
    n.queue = [];
    let script = document.createElement('script');
    script.async = true;
    script.src = 'https://dsp-media.eskimi.com/assets/js/e/gtr.min.js?_=0.0.0.6';
    let parent = document.getElementsByTagName('script')[0];
    parent.parentNode.insertBefore(script, parent);
    esk('init', this.configuration.trackingId);
  }

  trackPageView(_name: string, _path: string): void {}

  trackEvent(name: string, _: any): void {
    if (!this.isBrowser) return;
    esk('event', 'custom_event', name);
  }
}
