import { Injectable, Inject } from '@angular/core';
import { ActivatedRouteSnapshot, CanActivate } from '@angular/router';
import { operatorConfigurationToken, OperatorConfiguration } from '@honoregaming/configuration';

@Injectable()
export class FeaturesGuard implements CanActivate {
  constructor(@Inject(operatorConfigurationToken) private operatorConfiguration: OperatorConfiguration) {}

  canActivate(route: ActivatedRouteSnapshot): boolean {
    const featureName = route.data ? (route.data.featureName as string) : null;

    if (featureName == null || this.operatorConfiguration.operatorFeatures == null) {
      return false;
    }

    if (this.operatorConfiguration.operatorFeatures.indexOf(featureName) === -1) {
      return false;
    }

    return true;
  }
}
