import { Injectable } from '@angular/core';
import {
  EventStateDetailsType,
  MatchScoreType,
  OVERTIME_STATE_DETAILS,
  REGULATION_PERIOD_SCORE_TYPES,
  RegulationTimeScore,
  Score,
  SportsPoolGameMatch
} from '@honoregaming/types';

@Injectable({
  providedIn: 'root'
})
export class SportsScoresService {
  isOvertimeStateDetails(stateDetails?: EventStateDetailsType): boolean {
    return !!stateDetails && OVERTIME_STATE_DETAILS.has(stateDetails);
  }

  hasOvertimeScore(scores?: Score[]): boolean {
    return !!scores?.some(
      score => score.type !== MatchScoreType.Unknown && !REGULATION_PERIOD_SCORE_TYPES.has(score.type)
    );
  }

  getRegulationTimeScore(scores?: Score[]): RegulationTimeScore | undefined {
    const regulationScores: Score[] = scores?.filter(score => REGULATION_PERIOD_SCORE_TYPES.has(score.type)) ?? [];
    if (!regulationScores.length) {
      return undefined;
    }

    const homeTeamScore: number = regulationScores.reduce((total, score) => total + Number(score.homeTeamScore), 0);
    const awayTeamScore: number = regulationScores.reduce((total, score) => total + Number(score.awayTeamScore), 0);

    return { homeTeamScore: homeTeamScore.toString(), awayTeamScore: awayTeamScore.toString() };
  }

  computeDisplayedScore(
    gameMatch: SportsPoolGameMatch,
    isRegulationTimeOver: boolean
  ): RegulationTimeScore | undefined {
    const { homeTeamScore, awayTeamScore, scores } = gameMatch;
    if (!homeTeamScore || !awayTeamScore) {
      return undefined;
    }

    if (isRegulationTimeOver) {
      const regulationTimeScore: RegulationTimeScore | undefined = this.getRegulationTimeScore(scores);
      if (regulationTimeScore) {
        return regulationTimeScore;
      }
    }

    return { homeTeamScore, awayTeamScore };
  }
}
