import { Component, OnInit, ChangeDetectionStrategy, ChangeDetectorRef } from '@angular/core';
import { timer } from 'rxjs';
import { switchMap, takeUntil } from 'rxjs/operators';
import { DestroySubject } from '@honoregaming/core';
import { ToasterService } from '@honoregaming/ui';

@Component({
  selector: 'hg-toaster',
  templateUrl: './toaster.component.html',
  styleUrls: ['./toaster.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class ToasterComponent extends DestroySubject implements OnInit {
  message = '';
  visible: boolean = false;
  public animClass: 'fade-in' | 'fade-out' | '' = '';
  showProgress: boolean = false;
  action: (() => void) | null = null;
  toastType: 'add' | 'remove' | null = null;
  toastId: string | null = null;

  constructor(private readonly toasterService: ToasterService, private readonly cdRef: ChangeDetectorRef) {
    super();
  }

  ngOnInit(): void {
    this.toasterService.toast$
      .pipe(
        switchMap(raw => {
          const msg = typeof raw === 'string' ? { text: raw } : raw;

          this.message = msg.text;
          this.action = msg.action ?? null;
          this.toastType = msg.type ?? null;
          this.toastId = msg.id ?? null;
          this.showProgress = false;
          this.cdRef.detectChanges();
          this.showProgress = true;
          this.visible = true;
          this.animClass = 'fade-in';
          this.cdRef.detectChanges();
          return timer(3000);
        }),
        takeUntil(this.destroy$)
      )
      .subscribe(() => {
        this.animClass = 'fade-out';
        this.cdRef.detectChanges();

        setTimeout(() => {
          this.visible = false;
          this.cdRef.detectChanges();
        }, 400);
      });
  }

  onActionClick(): void {
    if (this.action) {
      this.action();
    }
    this.visible = false;
  }
}
