import { InjectionToken } from '@angular/core';
import { BetLine, BetLineChangeReason } from '@honoregaming/betslip';
import { Observable } from 'rxjs';

export interface ITemplatingBetSlipService {
  $lines: Observable<{ reason: BetLineChangeReason; lines: BetLine[] }>;

  addBetLine(betLine: BetLine): boolean;
  removeBetLine(betLine: BetLine);
}

export const templatingBetSlipServiceToken = new InjectionToken<ITemplatingBetSlipService>('TemplatingBetSlipService');
