import {
  Component,
  OnInit,
  ChangeDetectionStrategy,
  Inject,
  ElementRef,
  ChangeDetectorRef,
  Input
} from '@angular/core';
import { DOCUMENT } from '@angular/common';
import { takeUntil } from 'rxjs/operators';
import { globalConfiguration, operatorConfigurationToken, OperatorConfiguration } from '@honoregaming/configuration';
import { I18nService } from '@honoregaming/i18n';
import { DestroySubject, Scope, scopeToken } from '@honoregaming/core';
import { Language } from '@honoregaming/types';

@Component({
  selector: 'hg-language-selector',
  templateUrl: './language-selector.component.html',
  styleUrls: ['./language-selector.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class LanguageSelectorComponent extends DestroySubject implements OnInit {
  @Input() position: 'right' | 'center' = 'right';
  @Input() inFooter: boolean = false;

  languages: Language[] = [];
  currentLanguage?: Language;

  opened: boolean = false;

  private clickListenerFunction?: EventListenerOrEventListenerObject;

  constructor(
    private readonly i18nService: I18nService,
    private readonly element: ElementRef,
    private readonly cdRef: ChangeDetectorRef,
    @Inject(DOCUMENT) private readonly document: Document,
    @Inject(operatorConfigurationToken) private readonly operatorConfiguration: OperatorConfiguration,
    @Inject(scopeToken) public readonly scope: Scope
  ) {
    super();
  }

  ngOnInit(): void {
    this.languages = this.buildLanguages();

    this.i18nService.languageChanged$.pipe(takeUntil(this.destroy$)).subscribe(() => {
      this.moveLanguageToFront(this.i18nService.currentLanguageCode);
    });
  }

  changeLanguage(language: Language): void {
    this.opened = false;
    this.document.removeEventListener('click', this.clickListenerFunction);
    this.currentLanguage = language;

    this.languages.splice(this.languages.indexOf(this.currentLanguage), 1);
    this.languages.unshift(this.currentLanguage);

    this.i18nService.setLanguage(language.code).subscribe(() => {
      if (this.inFooter) {
        window.scrollTo(0, 0);
      }
      this.cdRef.detectChanges();
    });
  }

  toggleLanguagesSelector(): void {
    this.opened = !this.opened;
    if (this.opened) {
      this.clickListenerFunction = this.closeSelectorOnFocusOut.bind(this);
      setTimeout(() => this.document.addEventListener('click', this.clickListenerFunction), 0);
    }
  }

  trackByCode(_index: number, language: Language): string {
    return language.code;
  }

  private buildLanguages(): Language[] {
    if (this.scope === Scope.Affiliate) {
      return ['fr', 'en'].map(code => this.toLanguage(code));
    }
    return this.operatorConfiguration.localization.languages.map(code => this.toLanguage(code));
  }

  private toLanguage(code: string): Language {
    return { code, flagUrl: `${globalConfiguration.flagsBaseUrl}${code}.svg` };
  }

  private moveLanguageToFront(code: string): void {
    const found: Language | undefined = this.languages.find((language: Language) => language.code === code);
    if (!found) {
      return;
    }
    this.currentLanguage = found;
    this.languages.splice(this.languages.indexOf(found), 1);
    this.languages.unshift(found);
    this.cdRef.markForCheck();
  }

  private closeSelectorOnFocusOut(ev: MouseEvent): void {
    if (!(<Node>this.element.nativeElement).contains(<Node>ev.target)) {
      this.opened = false;
      this.document.removeEventListener('click', this.clickListenerFunction);
      this.cdRef.markForCheck();
    }
  }
}
