import {
  Component,
  ChangeDetectionStrategy,
  Input,
  Output,
  EventEmitter,
  OnChanges,
  SimpleChanges
} from '@angular/core';
import { MenuShortcut, TelemetryService } from '@honoregaming/customer-core';
import { Router } from '@angular/router';
import { I18nService } from '@honoregaming/i18n';

@Component({
  selector: 'hg-mobile-menu-shortcut',
  templateUrl: './mobile-menu-shortcut.component.html',
  styleUrls: ['./mobile-menu-shortcut.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class MobileMenuShortcutComponent implements OnChanges {
  @Input()
  menuShortcut: MenuShortcut;
  @Input()
  canBeActive: boolean;
  @Input()
  hasNew: boolean;

  @Output()
  shortcutSelected = new EventEmitter<void>();

  isActive: boolean;

  constructor(private router: Router, private telemetryService: TelemetryService, private i18nService: I18nService) {}

  ngOnChanges(changes: SimpleChanges) {
    if (changes.canBeActive || changes.menuShortcut) {
      this.isActive =
        this.canBeActive &&
        this.router.isActive(this.router.createUrlTree([this.menuShortcut.action.url]), {
          paths: 'subset',
          queryParams: 'subset',
          fragment: 'ignored',
          matrixParams: 'ignored'
        });
    }
  }

  selectShortcut(): void {
    this.telemetryService.trackEvent('burger_menu_click', {
      menu_item_name: this.menuShortcut.type,
      menu_item_label: this.i18nService.translateSync(this.menuShortcut.text),
      menu_item_position: this.menuShortcut.order,
      has_badge: this.hasNew
    });

    if (this.menuShortcut.action.url.length) {
      this.router.navigate([this.menuShortcut.action.url]);
    }
    this.shortcutSelected.emit();
  }
}
