import { Component } from '@angular/core';
import { AppUpdate } from '@ionic-native/app-update/ngx';
import { appConfiguration } from '@honoregaming/configuration';
import { ApplicationStateService } from '../services';

// for lazy-loading purpose
@Component({
  template: '',
  providers: [AppUpdate]
})
export class NativeImportComponent {
  constructor(private appUpdate: AppUpdate, private appState: ApplicationStateService) {}

  checkForUpdate(appName: string) {
    appConfiguration.ready.then(() => {
      const updateUrl = `https://storage-prod.sporty-tech.net/android/${
        appConfiguration.operatorKey
      }/${appName}/update${appConfiguration.flavor ? '-' + appConfiguration.flavor : ''}.xml`;
      this.appUpdate.checkAppUpdate(updateUrl).then(x => {
        if (x.code === 201) {
          // new version available
          this.appState.updateAvailable();
        }
      });
    });
  }
}
