import { Injectable, Injector, Inject, Type } from '@angular/core';
import { of } from 'rxjs';
import { switchMap, takeUntil } from 'rxjs/operators';
import { PrivacyConfiguration, TelemetryConfiguration } from '@honoregaming/configuration';
import { ApplicationStateService, DestroySubject } from '@honoregaming/core';
import { ITelemetryService } from './telemetry-service.model';
import { FacebookPixelTelemetryService } from './facebook-pixel.telemetry.service';
import { GoogleAnalyticsTelemetryService } from './google-analytics.telemetry.service';
import { E2PixelTelemetryService } from './e2-pixel.telemetry.service';
import { ExoClickPixelTelemetryService } from './exoclick-pixel.telemetry.service';
import { EsKimiTelemetryService } from './eskimi.telemetry.service';
import { SportRadarTelemetryService } from './sportradar.telemetry.service';
import { ClarityTelemetryService } from './clarity.telemetry.service';
import { RoigenPixelTelemetryService } from './roigen.telemetry.service';
import { HotjarPixelTelemetryService } from './hotjar-pixel.telemetry.service';
import { GeniusSportTelemetryService } from './genius-sport.telemetry.service';
import { SmartLookTelemetryService } from './smartlook.telemetry.service';
import { GoogleTagManagerTelemetryService } from './google-tag-manager.telemetry.service';
import { PrivacyService } from './../privacy.service';
import { customerOperatorConfigurationToken, CustomerOperatorConfiguration } from '../../models';
import { CriteoTelemetryService } from './criteo.telemetry.service';
import { SmarticoTelemetryService } from './smartico.telemetry.service';
import { EgwTelemetryService } from './egw.telemetry.service';

@Injectable()
export class TelemetryService extends DestroySubject implements ITelemetryService {
  private innerTelemetryServices: ITelemetryService[] = [];
  private queue = [];
  private ready: boolean = false;

  private readonly TELEMETRY_SERVICE_MAP: ReadonlyArray<[keyof TelemetryConfiguration, Type<unknown>]> = [
    ['facebook', FacebookPixelTelemetryService],
    ['google', GoogleAnalyticsTelemetryService],
    ['e2', E2PixelTelemetryService],
    ['exoclick', ExoClickPixelTelemetryService],
    ['eskimi', EsKimiTelemetryService],
    ['sportRadar', SportRadarTelemetryService],
    ['clarity', ClarityTelemetryService],
    ['roigen', RoigenPixelTelemetryService],
    ['hotjar', HotjarPixelTelemetryService],
    ['geniusSport', GeniusSportTelemetryService],
    ['smartlook', SmartLookTelemetryService],
    ['googleTagManager', GoogleTagManagerTelemetryService],
    ['criteo', CriteoTelemetryService],
    ['egw', EgwTelemetryService]
  ];

  constructor(
    private readonly injector: Injector,
    public readonly appState: ApplicationStateService,
    private readonly privacyService: PrivacyService,
    @Inject(customerOperatorConfigurationToken) private readonly operatorConfiguration: CustomerOperatorConfiguration
  ) {
    super();
    appState.isReady$
      .pipe(
        switchMap(() => this.privacyService.privacyConfiguration$ ?? of(null)),
        takeUntil(this.destroy$)
      )
      .subscribe(privacyConfiguration => {
        this.loadTelemetryServices(privacyConfiguration);
      });
  }

  loadTelemetryServices(privacyConfiguration: PrivacyConfiguration): void {
    this.ready = false;
    this.innerTelemetryServices = [];

    if (this.isAnalyticsAllowed(privacyConfiguration)) {
      this.innerTelemetryServices = this.resolveEnabledServices();
    }

    if (this.operatorConfiguration.smarticoConfiguration?.enabled) {
      this.innerTelemetryServices.push(this.injector.get(SmarticoTelemetryService));
    }

    this.ready = true;
    this.emptyQueue();
  }

  trackPageView(name: string, path: string): void {
    if (this.ready) {
      this.innerTelemetryServices.forEach(telemetryService => telemetryService.trackPageView(name, path));
    } else {
      this.queue.push({ name: 'trackPageView', arguments });
    }
  }

  trackEvent(name: string, properties: unknown = {}): void {
    if (this.ready) {
      this.innerTelemetryServices.forEach(telemetryService => telemetryService.trackEvent(name, properties));
    } else {
      this.queue.push({ name: 'trackEvent', arguments });
    }
  }

  private isAnalyticsAllowed(privacyConfiguration: PrivacyConfiguration): boolean {
    const consentsRequired: {
      analytics: boolean;
    } = this.operatorConfiguration.privacyConfiguration?.consents;
    if (!consentsRequired) return true;

    return !!(consentsRequired.analytics && privacyConfiguration?.consents?.analytics);
  }

  private resolveEnabledServices(): ITelemetryService[] {
    const telemetry: TelemetryConfiguration = this.operatorConfiguration.telemetryConfiguration;
    return this.TELEMETRY_SERVICE_MAP.filter(([key]) => telemetry?.[key]?.enabled).map(([, serviceToken]) =>
      this.injector.get<ITelemetryService>(serviceToken)
    );
  }

  private emptyQueue(): void {
    this.queue.forEach(x => this[x.name](...x.arguments));
    this.queue = [];
  }
}
