import { Injectable } from '@angular/core';
import { Observable, Subject } from 'rxjs';

@Injectable({
  providedIn: 'root'
})
export class DialogService {
  dialogsSubjects: { name: string; subject: Subject<boolean> }[] = [];

  registerDialog(name: string): Observable<boolean> {
    const subjectIndex = this.dialogsSubjects.findIndex(d => d.name === name);
    if (subjectIndex !== -1) {
      return this.dialogsSubjects[subjectIndex].subject.asObservable();
    }

    const subject = new Subject<boolean>();
    this.dialogsSubjects.push({ name: name, subject: subject });

    return subject.asObservable();
  }

  toggleDialog(name: string, open?: boolean) {
    const subjectIndex = this.dialogsSubjects.findIndex(d => d.name === name);
    if (subjectIndex !== -1) {
      this.dialogsSubjects[subjectIndex].subject.next(open);
    }
  }
}
