import { ChangeDetectionStrategy, Component, EventEmitter, Input, Output } from '@angular/core';
import { BetSlipMode } from '@honoregaming/types';

@Component({
  selector: 'hg-toggle-bet-slip-mode',
  templateUrl: './toggle-bet-slip-mode.component.html',
  styleUrls: ['./toggle-bet-slip-mode.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class ToggleBetSlipModeComponent {
  @Input() mode: BetSlipMode = BetSlipMode.Simple;
  @Input() availableBetSlipMode: BetSlipMode[] = [];
  @Input() disabledBetSlipMode: BetSlipMode[] = [];
  @Input() disabled: boolean = false;
  @Input() betBuilderModeLabel: string = '';
  @Output() modeChange = new EventEmitter<BetSlipMode>();

  BetSlipMode = BetSlipMode;

  constructor() {}

  setMode(mode: BetSlipMode): void {
    if (
      !this.disabled &&
      this.mode !== mode &&
      (mode === BetSlipMode.Simple || this.availableBetSlipMode.indexOf(mode) > -1) &&
      !this.disabledBetSlipMode.includes(mode)
    ) {
      this.modeChange.emit(mode);
    }
  }
}
