import {
  Component,
  OnInit,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Injector,
  Input,
  Output,
  EventEmitter,
  ViewChildren,
  QueryList,
  ElementRef,
  Inject,
  PLATFORM_ID,
  NgZone,
  HostBinding
} from '@angular/core';
import { isPlatformBrowser } from '@angular/common';
import { Router } from '@angular/router';
import { ITemplateService, templateServiceToken } from '../../services/template.service';
import { EventsService } from '@honoregaming/events';
import { DestroySubject, getDateInBrowserTimeZone, Scope, scopeToken } from '@honoregaming/core';
import { takeUntil } from 'rxjs/operators';
import { forkJoin, of } from 'rxjs';
import { EventWithEventBetTypes, HorseRace, HorseRaceEventBetType, Template } from '@honoregaming/types';
import type { BannerService } from 'projects/customer/hg-core/src/lib/services/telemetry/banner.service';
import { isInternalLink, toInternalUrl } from '../../helper';

@Component({
  selector: 'hg-slider',
  templateUrl: './slider.component.html',
  styleUrls: ['./slider.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class SliderComponent extends DestroySubject implements OnInit {
  @ViewChildren('slideElements')
  slideRefs: QueryList<ElementRef>;

  @HostBinding('class.noslide') noSlide: boolean = false;

  @Input()
  css: string;

  @Input()
  slideTimer: number;

  @Input()
  slidesAnchor: string;

  @Output()
  slidesLoaded = new EventEmitter<boolean>();

  slides: Template[];
  Array = Array;
  currentIndex: number;
  swipeCoord: [number, number];
  swipeTime: number;
  timerInterval: any;
  navNumber = 0;

  private bannerService: BannerService | null = null;

  constructor(
    private eventsService: EventsService,
    @Inject(PLATFORM_ID) private platId,
    private zone: NgZone,
    private cdRef: ChangeDetectorRef,
    private readonly injector: Injector,
    private readonly router: Router,
    @Inject(scopeToken) private readonly scope: Scope,
    @Inject(templateServiceToken) private templateService: ITemplateService
  ) {
    super();
  }

  ngOnInit() {
    if (this.scope === Scope.Customer) {
      import('projects/customer/hg-core/src/lib/services/telemetry/banner.service').then(bannerModule => {
        this.bannerService = this.injector.get(bannerModule.BannerService);
      });
    }

    const slidesObs = this.templateService.getTemplatesForAnchor(this.slidesAnchor);
    const nextQuinteObs =
      this.slidesAnchor === 'horse-banner-slide'
        ? this.eventsService.getNextQuinte(true, getDateInBrowserTimeZone())
        : of(null);

    forkJoin([slidesObs, nextQuinteObs])
      .pipe(takeUntil(this.destroy$))
      .subscribe(
        ([slides, nextQuinte]: [Template[], EventWithEventBetTypes<HorseRace, HorseRaceEventBetType> | null]) => {
          if (!nextQuinte) {
            slides = slides.filter(x => x.type !== 'horse-racing-template');
          }

          this.handleSlides(slides);
          this.startOrRestartTimer();
          this.cdRef.markForCheck();
          if (slides.length > 1) {
            setTimeout(() => this.initPreviousNext(), 0);
          }
        }
      );
  }

  private handleSlides(templates: Template[]) {
    const slides: Template[] = templates.filter(item => item.images || item.inputs !== null);

    this.slides = slides.length < 5 && slides.length !== 1 ? [...slides, ...slides] : slides;
    this.navNumber = slides.length;

    if (this.slides.length < 1) {
      this.noSlide = true;
    }

    this.currentIndex = 0;
    this.slidesLoaded.emit(!this.noSlide);
  }

  removeSlide(slide: { type: string; inputs: any }) {
    this.handleSlides(this.slides.filter(x => x !== slide));
  }

  initPreviousNext(): void {
    const sliderArray = this.slideRefs.toArray();
    this.addClassesWithoutTransition(
      sliderArray[(this.currentIndex + sliderArray.length - 1) % sliderArray.length]?.nativeElement,
      'prev'
    );
    this.addClassesWithoutTransition(
      sliderArray[(this.currentIndex + sliderArray.length + 1) % sliderArray.length]?.nativeElement,
      'next'
    );
    this.addClassesWithoutTransition(
      sliderArray[(this.currentIndex + sliderArray.length + 2) % sliderArray.length]?.nativeElement,
      'next-next'
    );
    this.addClassesWithoutTransition(
      sliderArray[(this.currentIndex + sliderArray.length - 2) % sliderArray.length]?.nativeElement,
      'prev-prev'
    );
  }

  startOrRestartTimer() {
    if (isPlatformBrowser(this.platId) && this.slideTimer && this.slides.length > 1) {
      this.zone.runOutsideAngular(() => {
        clearInterval(this.timerInterval);

        this.timerInterval = setInterval(
          () => this.zone.run(() => this.navTo((this.currentIndex + 1) % this.slides.length)),
          this.slideTimer * 1e3
        );
      });
    }
  }

  initialTransformActive = 0;
  initialTransformNext = 0;
  initialTransformPrev = 0;
  slideWidth = 0;

  swipe(e: TouchEvent, event: 'start' | 'end' | 'move'): void {
    if (this.slides.length <= 1) {
      return;
    }

    const coord: [number, number] = [e.changedTouches[0].pageX, e.changedTouches[0].pageY];
    const time = new Date().getTime();

    if (event === 'start') {
      this.swipeCoord = coord;
      this.swipeTime = time;
      this.slideWidth = this.getSlideByClass('slider__item--active').getBoundingClientRect().width;
      this.slideRefs.forEach(x => (x.nativeElement.style.transition = 'all 0s'));
      this.initialTransformActive = new DOMMatrixReadOnly(
        getComputedStyle(this.getSlideByClass('slider__item--active')).transform
      ).m41;
      this.initialTransformNext = new DOMMatrixReadOnly(getComputedStyle(this.getSlideByClass('next')).transform).m41;
      this.initialTransformPrev = new DOMMatrixReadOnly(getComputedStyle(this.getSlideByClass('prev')).transform).m41;
    } else if (event === 'end') {
      this.slideRefs.forEach(x => (x.nativeElement.style.transition = ''));
      this.slideRefs.forEach(x => (x.nativeElement.style.transform = ''));
      const direction = [coord[0] - this.swipeCoord[0], coord[1] - this.swipeCoord[1]];
      const duration = time - this.swipeTime;
      // swipe duration is long enought (1s), distance is long enought (30px) and horizontal enought (~20° max)
      if (duration > 100 && Math.abs(direction[0]) > 30 && Math.abs(direction[0]) > Math.abs(direction[1] * 3)) {
        if (direction[0] > 0) {
          this.navTo(this.currentIndex === 0 ? this.slides.length - 1 : this.currentIndex - 1, true);
        } else {
          this.navTo((this.currentIndex + 1) % this.slides.length);
        }
      }
    } else if (event === 'move') {
      let translate = Math.max(Math.min(coord[0] - this.swipeCoord[0], this.slideWidth), -this.slideWidth);
      this.getSlideByClass('slider__item--active').style.transform = `translateX(${
        translate + this.initialTransformActive
      }px)`;
      this.getSlideByClass('prev').style.transform = `translateX(${translate + this.initialTransformPrev}px)`;
      this.getSlideByClass('next').style.transform = `translateX(${translate + this.initialTransformNext}px)`;
    }
  }

  getSlideByClass = (className: string): HTMLElement =>
    this.slideRefs.filter(x => x.nativeElement.classList.contains(className))[0].nativeElement;

  // Fake scoped to enable redraw with assignation without being treeshaked
  // tslint:disable-next-line:member-ordering
  fakeScope = {};
  tryNav(event: Event, index: number, back: boolean) {
    if (this.currentIndex !== index) {
      event.stopPropagation();
      event.stopImmediatePropagation();
      event.preventDefault();
      this.navTo(index, back);
      return;
    }

    const slide: Template = this.slides[index];

    this.bannerService?.trackSlideClick(slide, (index % this.navNumber) + 1);
    if (this.canRouteInternally(slide)) {
      event.preventDefault();
      this.router.navigateByUrl(toInternalUrl(slide.link));
    }
  }

  private canRouteInternally(slide: Template): boolean {
    return this.isImageBanner(slide) && !!slide?.link && isInternalLink(slide.link);
  }

  private isImageBanner(slide: Template): boolean {
    return !!(slide?.images?.desktop || slide?.images?.mobile);
  }

  navTo(index: number, back = false) {
    if (this.currentIndex === index) {
      return;
    }

    this.startOrRestartTimer();

    const prevClass = back ? 'next' : 'prev';
    const nextClass = back ? 'prev' : 'next';
    const classes = ['next', 'prev', 'next-next', 'prev-prev'];

    const sliderArray = this.slideRefs.toArray();

    const next = sliderArray[index];

    if (
      [1, sliderArray.length - 1].indexOf((this.currentIndex - index + sliderArray.length) % sliderArray.length) > -1
    ) {
      // mobile or only step (so full transition of 4 slides)
      setTimeout(() => {
        this.slideRefs.forEach(x => {
          if (x.nativeElement.classList.contains('next-next') && back) {
            x.nativeElement.classList.add('notransition');
          } else {
            x.nativeElement.classList.remove('notransition');
          }
          classes.forEach(c => x.nativeElement.classList.remove(c));
        });
        sliderArray[(index + sliderArray.length - 1) % sliderArray.length].nativeElement.classList.add('prev');
        sliderArray[(index + sliderArray.length + 1) % sliderArray.length].nativeElement.classList.add('next');
        sliderArray[(index + sliderArray.length - 2) % sliderArray.length].nativeElement.classList.add('prev-prev');
        sliderArray[(index + sliderArray.length + 2) % sliderArray.length].nativeElement.classList.add('next-next');
        if (!back) {
          sliderArray[(index + sliderArray.length + 2) % sliderArray.length].nativeElement.classList.add(
            'notransition'
          );
        } else {
          sliderArray[(index + sliderArray.length - 2) % sliderArray.length].nativeElement.classList.add(
            'notransition'
          );
        }
      });
    } else {
      // More than one step transition, so desktop and at least 2 slides transition
      sliderArray.forEach(x => {
        this.removeClassesWithoutTransition(x.nativeElement, ...classes);
      });

      this.addClassesWithoutTransition(next.nativeElement, nextClass);
      this.addClassesWithoutTransition(
        sliderArray[(index + sliderArray.length - 1) % sliderArray.length].nativeElement,
        'prev'
      );
      this.addClassesWithoutTransition(
        sliderArray[(index + sliderArray.length + 1) % sliderArray.length].nativeElement,
        'next'
      );
      this.addClassesWithoutTransition(next.nativeElement, nextClass);
    }

    setTimeout(() => {
      const cur = sliderArray[this.currentIndex];
      this.currentIndex = index;
      next.nativeElement.classList.remove(nextClass);
      cur.nativeElement.classList.add(prevClass);
      this.cdRef.markForCheck();
    });
  }

  private addClassesWithoutTransition(element: HTMLElement, ...cssClasses: string[]) {
    if (element) {
      element.classList.add('slider__item--notransition');
      element.classList.add(...cssClasses);
      // assignation to make the browser update the element position before next animation loop
      this.fakeScope = element.offsetWidth;
      element.classList.remove('slider__item--notransition');
    }
  }

  private removeClassesWithoutTransition(element: HTMLElement, ...cssClasses: string[]) {
    if (element) {
      element.classList.add('slider__item--notransition');
      element.classList.remove(...cssClasses);
      // assignation to make the browser update the element position before next animation loop
      this.fakeScope = element.offsetWidth;
      element.classList.remove('slider__item--notransition');
    }
  }
}
