import { Component, ChangeDetectionStrategy, Input, OnChanges } from '@angular/core';

@Component({
  selector: 'hg-addition-result',
  templateUrl: './addition-result.component.html',
  styleUrls: ['./addition-result.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class AdditionResultComponent implements OnChanges {
  @Input()
  result: any;

  serializedResult: any;

  constructor() {}

  ngOnChanges() {
    this.serializedResult = JSON.parse(this.result);
  }
}
