import { Component, OnInit, ChangeDetectionStrategy, ChangeDetectorRef, Inject, OnDestroy } from '@angular/core';
import {
  AuthService,
  CustomerService,
  CustomerState,
  ICaptchaService,
  captchaServiceToken
} from '@honoregaming/customer-core';
import { DestroySubject, hasFlag } from '@honoregaming/core';
import { finalize, takeUntil } from 'rxjs/operators';

@Component({
  selector: 'hg-account-validation',
  templateUrl: './account-validation.component.html',
  styleUrls: ['./account-validation.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class AccountValidationComponent extends DestroySubject implements OnInit, OnDestroy {
  isValidated: boolean;
  validationCode: string;
  validationCodeReseted: boolean = null;
  loadingValidateCustomer: boolean;
  loadingValidationCode: boolean;
  recaptchaLegend: string;

  constructor(
    private authService: AuthService,
    private customerService: CustomerService,
    private cdRef: ChangeDetectorRef,
    @Inject(captchaServiceToken) private captchaService: ICaptchaService
  ) {
    super();
  }

  ngOnInit() {
    this.authService.me$
      .pipe(takeUntil(this.destroy$))
      .subscribe(x => (this.isValidated = hasFlag(x.state, CustomerState.LoginValidated)));

    this.captchaService
      .applyCaptcha('#account-reset-validationcode-button')
      .pipe(
        finalize(() => {
          this.cdRef.markForCheck();
        })
      )
      .subscribe(() => {
        this.recaptchaLegend = this.captchaService.getLegend();
      });
  }

  ngOnDestroy(): void {
    this.captchaService.clearCaptcha();
  }

  validate() {
    if (this.loadingValidateCustomer) {
      return;
    }

    this.loadingValidateCustomer = true;

    this.customerService
      .validate(this.validationCode)
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.loadingValidateCustomer = false;
          this.cdRef.markForCheck();
        })
      )
      .subscribe(() => {
        this.authService.getMe().subscribe(x => {
          this.isValidated = hasFlag(x.state, CustomerState.LoginValidated);
          this.cdRef.markForCheck();
        });
      });
  }

  public resetValidationCode() {
    if (this.loadingValidationCode) {
      return;
    }

    this.loadingValidationCode = true;

    this.captchaService
      .validateCaptcha()
      .pipe(takeUntil(this.destroy$))
      .subscribe(token => this.submitResetValidationCode(token));
  }

  private submitResetValidationCode(recaptchaToken: string) {
    this.loadingValidationCode = true;
    this.customerService
      .resetValidationCode(recaptchaToken)
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.loadingValidationCode = false;
          this.cdRef.markForCheck();
        })
      )
      .subscribe(() => {
        this.validationCodeReseted = true;
        this.cdRef.markForCheck();
      });
  }
}
