import { Inject, Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { globalConfiguration } from '@honoregaming/configuration';
import { LocalStorageService, natifToken } from '@honoregaming/core';
import { Plugins, PushNotification, PushNotificationToken, PushNotificationActionPerformed } from '@capacitor/core';
import { SwPush } from '@angular/service-worker';
import { customerOperatorConfigurationToken, CustomerOperatorConfiguration } from '../models';
const { PushNotifications } = Plugins;

const pushSubscriptionIdStorageKey = 'push:subscriptionid';

@Injectable({ providedIn: 'root' })
export class NotificationService {
  private pushSubscriptionId: number;
  private registrationEventReceived: boolean;

  constructor(
    private httpClient: HttpClient,
    @Inject(customerOperatorConfigurationToken) private operatorConfiguration: CustomerOperatorConfiguration,
    @Inject(natifToken) private isNatif: boolean,
    private swPush: SwPush,
    private storageService: LocalStorageService
  ) {
    this.pushSubscriptionId = this.storageService.getItem(pushSubscriptionIdStorageKey);
  }

  registerPushInformations() {
    if (this.operatorConfiguration.notificationsConfiguration?.enabled) {
      if (this.isNatif) {
        this.registerNativePushInformations();
      } else {
        this.registerWebPushInformations();
      }
    }
  }

  clearSubscription() {
    if (this.pushSubscriptionId) {
      this.httpClient
        .delete(`${globalConfiguration.apiBaseUrl}notifications/subscriptions/${this.pushSubscriptionId}`)
        .subscribe(() => {
          this.storageService.removeItem(pushSubscriptionIdStorageKey);
          this.pushSubscriptionId = null;
        });
    }
  }

  mapSubscriptionToCustomer() {
    if (this.pushSubscriptionId) {
      this.httpClient
        .post(`${globalConfiguration.apiBaseUrl}notifications/subscriptions/${this.pushSubscriptionId}/map`, {})
        .subscribe(() => {});
    }
  }

  private registerNativePushInformations() {
    if (!this.pushSubscriptionId) {
      PushNotifications.requestPermission().then(result => {
        if (result.granted) {
          PushNotifications.register();
        }
      });
    }

    // On success, we should be able to receive notifications
    PushNotifications.addListener('registration', (token: PushNotificationToken) => {
      if (!this.registrationEventReceived) {
        this.registrationEventReceived = true;
        this.httpClient
          .post<number>(`${globalConfiguration.apiBaseUrl}notifications/register/native`, { token: token.value })
          .subscribe(subscriptionId => {
            this.storageService.setItem(pushSubscriptionIdStorageKey, subscriptionId);
            this.pushSubscriptionId = subscriptionId;
          });
      }
    });

    PushNotifications.addListener('registrationError', (error: any) => {
      console.log(error);
    });

    // Show us the notification payload if the app is open on our device
    PushNotifications.addListener('pushNotificationReceived', (notification: PushNotification) => {
      console.log(notification);
    });

    // Method called when tapping on a notification
    PushNotifications.addListener(
      'pushNotificationActionPerformed',
      (notification: PushNotificationActionPerformed) => {
        console.log(notification);
      }
    );
  }

  private registerWebPushInformations() {
    if (!this.pushSubscriptionId && this.swPush.isEnabled) {
      this.swPush
        .requestSubscription({
          serverPublicKey: this.operatorConfiguration.notificationsConfiguration.serverPublicKey
        })
        .then(pushSubscription => {
          this.httpClient
            .post<number>(`${globalConfiguration.apiBaseUrl}notifications/register/web`, pushSubscription)
            .subscribe(subscriptionId => {
              this.storageService.setItem(pushSubscriptionIdStorageKey, subscriptionId);
              this.pushSubscriptionId = subscriptionId;
            });
        })
        .catch(err => console.log('Could not subscribe to notifications', err));
    }
  }
}
