import {
  AfterViewInit,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  ElementRef,
  EventEmitter,
  HostBinding,
  HostListener,
  Inject,
  Input,
  OnDestroy,
  OnInit,
  Optional,
  Output,
  PLATFORM_ID,
  TemplateRef,
  ViewChild,
  ViewContainerRef
} from '@angular/core';
import { filter, finalize, take, takeUntil } from 'rxjs/operators';
import { combineLatest } from 'rxjs';
import { animate, style, transition, trigger } from '@angular/animations';
import { AnimateDirective, Media, MediaService, MessageService } from '@honoregaming/ui';
import {
  Amounts,
  BetLine,
  BetLineChangeReason,
  BetLineFailure,
  BetSlipType,
  BettingError,
  BetValidatedContext,
  CreateBetCodeFailure,
  CreateBetFailures,
  CreateBetResponse,
  CreateSimulatedBetFailures,
  CreateSimulatedBetResponse,
  FreeBetCouponBetSlip
} from '../../models';
import { BetSlipConfiguration, BetSlipService } from '../../services/bet-slip.service';
import { BetSlipClearComponent } from '../bet-slip-clear/bet-slip-clear.component';
import { BetSlipSimulateComponent } from '../bet-slip-simulate/bet-slip-simulate.component';
import { BetSlipSimulateResultComponent } from '../bet-slip-simulate-result/bet-slip-simulate-result.component';
import {
  BroadcastingService,
  CompleteMyBetService,
  CustomerIdentity,
  DestroySubject,
  DialogService,
  kioskToken,
  Scope,
  scopeToken,
  sub
} from '@honoregaming/core';
import {
  BetCategoryType,
  BetCodeGenerated,
  BetLineStateType,
  BetSlipMode,
  CompleteMyBetInfo
} from '@honoregaming/types';
import { InstantGameTransaction } from '../../models/instant-game-transaction.model';
import { OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';
import { authServiceToken, IAuthService } from '@honoregaming/authentication';
import { isPlatformBrowser } from '@angular/common';
import { IdentifiedRetailServiceToken, IIdentifiedRetailService } from '../../services/identified-retail.interface';
import { orderFreeBetCouponsForBetSlip, BetSlipBetBuilderService, BetSlipBetLinesService } from '@honoregaming/betslip';
import { BetSlipFreebetTutorialComponent } from '../bet-slip-freebet-tutorial/bet-slip-freebet-tutorial.component';
import { BetSlipFreebetService } from '../../services/bet-slip-freebet.service';
import { I18nService } from '@honoregaming/i18n';
import {
  ITransactionPopupService,
  TransactionMode,
  transactionPopupServiceToken
} from '../../services/transaction-popup.interface';
import { betValidationServiceToken, IBetValidationService } from '../../services/bet-validation.interface';

@Component({
  selector: 'hg-bet-slip',
  templateUrl: './bet-slip.component.html',
  styleUrls: ['./bet-slip.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
  animations: [
    trigger('empty', [
      transition('void => *', [
        style({ height: '0', padding: '0', transform: 'scale(0)' }),
        animate('.1s ease-out', style({ height: '*', padding: '50px 0', transform: 'scale(1)' }))
      ])
    ]),
    trigger('removed', [
      transition('* => void', [animate('.1s ease-out', style({ transform: 'scale(0)', height: '0' }))]),
      transition('void => *', [
        style({ height: '0', transform: 'scale(0)' }),
        animate('.1s ease-out', style({ transform: 'scale(1)', height: '*' }))
      ])
    ])
  ]
})
export class BetSlipComponent extends DestroySubject implements OnInit, AfterViewInit, OnDestroy {
  @Output()
  betSlipCleared = new EventEmitter();

  @Output()
  public betCodeGenerated = new EventEmitter<BetCodeGenerated>();

  @Input()
  betValidatedTemplate: TemplateRef<any>;

  @Input() betSlipActive: boolean;

  @Input() isIdentifiedRetailMode: boolean;

  @Input()
  freeBalance: number;

  @Input()
  balance: number = 0;

  @Input()
  hideBalance: boolean;

  @Input()
  allowedToCopyLastBetSlipSelection: boolean = true;

  @ViewChild(AnimateDirective)
  counter: AnimateDirective;

  @ViewChild('actionButton', { static: false }) actionButton!: ElementRef;

  @HostBinding('class')
  get currentBetCategoryName() {
    return this.betSlipConfiguration?.betCategory.toLocaleLowerCase();
  }

  @HostBinding('class.betslip-customer') betslipCustomerStyle: boolean = this.userScope === Scope.Customer;

  isAgent: boolean = this.userScope === Scope.Agent;

  betLinesNumber: number;
  betLines: BetLine[] = [];
  instantGameTransactions: InstantGameTransaction[] = [];
  mode: BetSlipMode;
  type: BetSlipType = BetSlipType.Real;

  BetSlipMode = BetSlipMode;
  BetSlipType = BetSlipType;

  amounts: Amounts;
  acceptOddChange: boolean;

  isAndroid: boolean;
  heightForAndroid = false;
  userAgent: string;
  hasNewBetLines = false;
  hasOnlyPendingBetLines = false;

  customerBehalfIdentity?: CustomerIdentity;

  lastBetSelectionPerBetCategory: {
    [betCategoryType: string]: { betLines: BetLine[]; amounts: number[]; mode: BetSlipMode };
  } = {};
  canCopy = false;

  @HostBinding('class.bet-validated-open')
  betValidated: boolean;

  betValidatedContext: BetValidatedContext = null;

  placingBet = false;
  gettingCode = false;
  betSlipFailure: string;
  betSlipFailureType: CreateBetFailures | CreateSimulatedBetFailures;
  betSlipFailureData: any;
  betSlipValidationFailure: string;
  isSimpleModeDisabled: boolean = false;
  disabledModes: BetSlipMode[] = [];

  betSlipConfiguration: BetSlipConfiguration | undefined;
  BetCategoryType = BetCategoryType;

  canBeCashedout: boolean;

  userNeedToBeLoggedIn = false;
  userStatus: 'connected' | 'disconnected';

  currency = this.operatorConfiguration.currency.symbol;
  applyTaxToFreeBets = this.operatorConfiguration.freeBetsConfiguration?.applyTax;

  hasUnavailableBetLines: boolean;

  freeBetCoupons: FreeBetCouponBetSlip[] = [];
  selectedFreeBetCoupon: FreeBetCouponBetSlip | null = null;
  freeBetCouponsCanBeUsedCount: number;

  multiCouponActive: boolean = this.operatorConfiguration.freeBetsConfiguration?.multiCouponEnabled;

  public isHorseRacesCardMode: boolean =
    this.operatorConfiguration.features.horseRacingFeatures.horseRacesCardMode == true;

  bonusCard: ElementRef;
  isBonusScrolledIntoTopView: boolean = false;
  isBonusScrolledIntoBottomView: boolean = false;
  hasScrolled: boolean;
  isSimulatedModeEnabled: boolean = false;
  displaySimulateBetSlipBackground: boolean =
    !this.isAgent && this.operatorConfiguration.themeCustomizationConfiguration?.displaySimulateBetSlipBackground;
  completeMyBetInfo: CompleteMyBetInfo | null = null;

  useAlternativeDisplayForTax: boolean = this.operatorConfiguration.onlineConfiguration?.useAlternativeDisplayForTax;
  showTaxInformations: boolean = false;

  hasBetBuilderBetLines: boolean = false;
  hasBetBuilderErrors: boolean = false;
  isBetBuilderFreebetAllowed: boolean = false;
  betBuilderModeLabel: string = '';

  isLoadingLastSelection: boolean = false;
  isLoadingOddsEventIds: number[] = [];

  enablePopupMethodDeposit: boolean = this.operatorConfiguration.depositConfiguration?.enablePopupMethod;
  hasInsufficientBalance: boolean = false;
  missingBalance: number = 0;

  private resizeObserver: ResizeObserver;

  Scope = Scope;

  @ViewChild('bonusCard', { read: ElementRef }) set content(content: ElementRef) {
    if (content) {
      this.bonusCard = content;
      this.checkIsBonusIntoView(this.mediaService.media);
    }
    this.cdRef.detectChanges();
  }

  @HostListener('window:scroll', ['$event'])
  isScrolledIntoView() {
    this.checkIsBonusIntoView(this.mediaService.media);
  }

  @HostListener('scroll', ['$event'])
  onHostScrollonMobile() {
    this.checkIsBonusIntoView(this.mediaService.media);
  }

  @HostListener('window:beforeunload')
  beforeUnload() {
    this.tryCloseBetValidation();
  }

  constructor(
    private readonly cdRef: ChangeDetectorRef,
    private readonly messageService: MessageService,
    private readonly bcService: BroadcastingService,
    private readonly betSlipService: BetSlipService,
    private readonly betSlipFreebetService: BetSlipFreebetService,
    private readonly completeMyBetService: CompleteMyBetService,
    private readonly dialogService: DialogService,
    private readonly viewRef: ViewContainerRef,
    private readonly i18nService: I18nService,
    private readonly betSlipBetBuilderService: BetSlipBetBuilderService,
    private readonly betSlipBetLinesService: BetSlipBetLinesService,
    @Inject(betValidationServiceToken) private readonly betValidationService: IBetValidationService,
    @Inject(PLATFORM_ID) private readonly platformId,
    @Inject(operatorConfigurationToken) private readonly operatorConfiguration: OperatorConfiguration,
    @Inject(scopeToken) public readonly userScope: Scope,
    @Inject(authServiceToken) private readonly authService: IAuthService,
    @Inject(kioskToken) public readonly isKiosk: boolean,
    @Optional() protected readonly mediaService: MediaService,
    @Optional()
    @Inject(IdentifiedRetailServiceToken)
    private readonly identifiedRetailService: IIdentifiedRetailService,
    @Optional()
    @Inject(transactionPopupServiceToken)
    private readonly transactionPopupService: ITransactionPopupService
  ) {
    super();
  }

  onClose() {
    this.dialogService.toggleDialog('betslip', false);
  }

  ngOnInit() {
    if (!this.betValidatedTemplate) {
      throw new Error('BetSlip component needs a BetValidatedTemplate');
    }

    this.authService.status$.pipe(takeUntil(this.destroy$)).subscribe(status => {
      // On page refresh, force refresh of current Coupons
      if (this.userStatus !== status && status === 'connected') {
        this.betSlipService.refreshFreeBetCoupons();
      }

      this.userStatus = status;

      if (this.userStatus === 'connected') {
        this.userNeedToBeLoggedIn = false;
        this.betSlipService.configureLeftoverBalanceBetlines();
      } else {
        if (this.betSlipConfiguration) {
          this.betSlipService.configureBetSlipFreeBet(false);
        }

        this.betSlipService.configureLeftoverBalanceBetlines(true);

        this.betSlipService.setIsBusy(false);
      }

      this.cdRef.markForCheck();
    });

    this.acceptOddChange = this.betSlipService.acceptOddChange;

    this.betSlipService.$configuration.pipe(takeUntil(this.destroy$)).subscribe(conf => {
      const firstInit = !this.betSlipConfiguration;
      this.betSlipConfiguration = conf;
      this.lastBetSelectionPerBetCategory = this.betSlipService.getLastBetSelectionPerBetCategory();

      this.canCopy =
        this.allowedToCopyLastBetSlipSelection &&
        this.lastBetSelectionPerBetCategory[this.betSlipConfiguration.betCategory] &&
        !this.canPlaceBet();

      // Handle redirection : remove coupons when disconnected; else done in status$.pipe
      if (this.userStatus === 'disconnected' && firstInit) {
        this.betSlipService.configureBetSlipFreeBet(false);
      }
      this.cdRef.markForCheck();
    });

    this.betSlipService.$lines.pipe(takeUntil(this.destroy$)).subscribe(x => {
      if (this.betSlipFailureType != CreateBetFailures.OutdatedNonRunners) {
        this.betSlipFailure = undefined;
      }
      if (x.lines.length && this.betValidated && x.reason !== BetLineChangeReason.OddChange) {
        this.betValidated = false;
      }
      this.instantGameTransactions = x.instantGameTransactions;
      this.betLines = [...x.lines];
      this.betLinesNumber =
        this.betSlipConfiguration.betCategory === BetCategoryType.InstantGame
          ? this.instantGameTransactions?.length || 0
          : x.lines.length;

      if (this.counter) {
        this.counter.animate('new');
      }

      this.hasUnavailableBetLines =
        (this.betSlipConfiguration.betCategory === BetCategoryType.SportsFixedOdds ||
          this.betSlipConfiguration.betCategory === BetCategoryType.VirtualFixedOdds ||
          this.betSlipConfiguration.betCategory === BetCategoryType.HorseRacingMutualInternationalPool ||
          this.betSlipConfiguration.betCategory === BetCategoryType.HorseRacingMutualOperatorPool) &&
        this.betLines.some(b => !b.bettingAllowed || (b.failure && !b.newStake) || !b.active);
      this.hasNewBetLines = x.lines.some((line: BetLine) => !line.isBetCompletion);
      this.hasOnlyPendingBetLines = x.lines.every(
        (line: BetLine) => !line.state || line.state === BetLineStateType.Pending
      );
      this.canBeCashedout = this.isBetSlipCompatibleWithCashout();
      this.disabledModes = this.betSlipBetLinesService.disabledModes;
      this.handleBetBuilderLinesChanges();
      this.checkIsBonusIntoView(this.mediaService.media);
      this.checkSimulatedMode();
      this.cdRef.markForCheck();
    });

    this.betSlipService.$amounts.pipe(takeUntil(this.destroy$)).subscribe(x => {
      this.amounts = x;
      this.checkInsufficientBalance();
      this.cdRef.markForCheck();
    });

    this.betSlipService.$mode.pipe(takeUntil(this.destroy$)).subscribe(x => {
      this.mode = x;
      this.betSlipFailure = undefined;
      this.canBeCashedout = this.isBetSlipCompatibleWithCashout();

      this.checkIsBonusIntoView(this.mediaService.media);
      this.cdRef.markForCheck();
    });

    combineLatest([this.betSlipService.$mode, this.betSlipService.$configuration, this.betSlipService.$lines])
      .pipe(takeUntil(this.destroy$))
      .subscribe(x => {
        const [mode, conf, betLines] = x;

        if (mode === BetSlipMode.Simple && betLines?.lines?.length) {
          if (conf.betCategory === BetCategoryType.SportsFixedOdds) {
            if ((this.operatorConfiguration.betSlipModeSimpleConfiguration?.allowSingleBetOnSports ?? true) === false) {
              this.isSimpleModeDisabled = true;
            }
          }

          if (conf.betCategory === BetCategoryType.VirtualFixedOdds) {
            if (
              (this.operatorConfiguration.betSlipModeSimpleConfiguration?.allowSingleBetOnVirtual ?? true) === false
            ) {
              this.isSimpleModeDisabled = true;
            }
          }
        } else {
          this.isSimpleModeDisabled = false;
        }
      });

    this.betSlipFreebetService.$freeBetCoupons
      .pipe(
        takeUntil(this.destroy$),
        filter(() => !!this.betSlipConfiguration)
      )
      .subscribe((coupons: FreeBetCouponBetSlip[]) => {
        if (this.betSlipConfiguration.canUseFreeBet) {
          this.freeBetCoupons = orderFreeBetCouponsForBetSlip(coupons);
          this.freeBetCouponsCanBeUsedCount = this.completeMyBetInfo?.freebetCouponId
            ? 1
            : this.freeBetCoupons.filter((coupon: FreeBetCouponBetSlip) => coupon.canBeUsed === true).length;
          if (this.amounts.useFreeBet && !this.selectedFreeBetCoupon && this.mandatoryCoupon?.canBeUsed) {
            this.onFreeBetCouponSelectionChanges(this.mandatoryCoupon);
          } else if (this.selectedFreeBetCoupon && this.shouldUnselectCoupon()) {
            this.onFreeBetCouponSelectionChanges(null);
          }
        } else {
          this.betSlipService.configureBetSlipFreeBet(false);
        }
        this.cdRef.markForCheck();
      });

    this.bcService
      .register('display-gcu-message-error')
      .pipe(takeUntil(this.destroy$))
      .subscribe((res: boolean) => {
        if (!res) {
          this.betSlipFailureType = undefined;
          this.betSlipFailure = undefined;
          this.cdRef.markForCheck();
        }
      });

    this.mediaService?.media$.pipe(takeUntil(this.destroy$)).subscribe(x => {
      this.checkIsBonusIntoView(x);
    });

    this.completeMyBetService.completeMyBetInfo$
      .pipe(takeUntil(this.destroy$))
      .subscribe((completeMyBetInfo: CompleteMyBetInfo | null) => {
        this.completeMyBetInfo = completeMyBetInfo;
        this.cdRef.markForCheck();
      });

    this.betSlipService.unLock();
    this.detectAndroid();

    this.type = this.betSlipService.getCurrentBetSlipType();
    this.isBetBuilderFreebetAllowed = this.betSlipBetBuilderService.isFreebetAllowed;
    this.listenOnBetBuilderLoadingChanges();
    this.listenOnBalanceChanges();
    this.checkSimulatedMode();
  }

  ngAfterViewInit() {
    if (this.viewRef) {
      this.resizeObserver = new ResizeObserver(() => this.checkIsBonusIntoView(this.mediaService.media));
      this.resizeObserver.observe(this.viewRef.element.nativeElement);
    }
  }

  get showPaymentTax(): boolean {
    return (
      (!!this.amounts.summary.paymentTax || !!this.amounts.paymentTax?.showTaxDetail) &&
      (!this.amounts.useFreeBet || (this.amounts.useFreeBet && this.applyTaxToFreeBets)) &&
      !!this.betLines.length &&
      this.betSlipConfiguration?.betCategory !== BetCategoryType.HorseRacingMutualInternationalPool &&
      this.betSlipConfiguration?.betCategory !== BetCategoryType.DrawGame &&
      this.betSlipConfiguration?.betCategory !== BetCategoryType.SportsPool &&
      this.betSlipConfiguration?.betCategory !== BetCategoryType.HorseRacingMutualOperatorPool
    );
  }

  get displayBetCodeButton(): boolean {
    return (
      this.betSlipConfiguration.betCodeAvailable &&
      ((this.mode === BetSlipMode.Simple && this.betLines.length >= 1) ||
        this.mode === BetSlipMode.Multiple ||
        this.mode === BetSlipMode.Systems) &&
      this.type === BetSlipType.Real &&
      this.hasOnlyPendingBetLines
    );
  }

  get displayPaymentTax(): boolean {
    return (
      (!!this.amounts.summary.paymentTax || this.amounts.paymentTax?.showTaxDetail) &&
      (!this.amounts.useFreeBet || (this.amounts.useFreeBet && this.applyTaxToFreeBets)) &&
      !!this.betLines.length &&
      this.betSlipConfiguration?.betCategory !== BetCategoryType.HorseRacingMutualInternationalPool &&
      this.betSlipConfiguration?.betCategory !== BetCategoryType.DrawGame &&
      this.betSlipConfiguration?.betCategory !== BetCategoryType.HorseRacingMutualOperatorPool
    );
  }

  get displayAlternativeTaxInformations(): boolean {
    return (
      this.useAlternativeDisplayForTax &&
      (!!this.amounts.summary?.bettingTax || this.amounts.bettingTax?.showTaxDetail || this.displayPaymentTax) &&
      this.totalTaxes > 0
    );
  }

  get mandatoryCoupon(): FreeBetCouponBetSlip | null {
    return !this.multiCouponActive
      ? this.freeBetCoupons[0]
      : this.completeMyBetInfo?.freebetCouponId
      ? this.freeBetCoupons.find((coupon: FreeBetCouponBetSlip) => coupon.id === this.completeMyBetInfo.freebetCouponId)
      : null;
  }

  get totalTaxes(): number {
    return (this.amounts.summary?.paymentTax ?? 0) + (this.amounts.summary?.bettingTax ?? 0);
  }

  removeUnavailableBetLines(): void {
    if (this.hasUnavailableBetLines) {
      const notAvailableBetlines = this.betLines.filter(
        b => !b.bettingAllowed || (b.failure && !b.newStake) || !b.active
      );
      if (notAvailableBetlines?.length) {
        notAvailableBetlines.forEach(betLine => {
          this.onBetLineRemove(betLine);
        });
      }
    }

    this.checkIsBonusIntoView(this.mediaService.media);
  }

  clearBetSlip() {
    const forceCouponsRefresh: boolean = this.amounts.useFreeBet && !!this.completeMyBetInfo?.betId;
    this.messageService
      .sendComponentMessage(BetSlipClearComponent, {
        betCategory: this.betSlipConfiguration.betCategory.toLowerCase()
      })
      .closed.subscribe((res: boolean) => {
        if (res) {
          this.betSlipService.toggleFreeBetMode(false, forceCouponsRefresh);
          this.changeBetSlipType(BetSlipType.Real);
        }
      });
  }

  onBetSlipChange(changes: { amount: number; line: BetLine | number }) {
    const useLeftOver: boolean = this.betLines.some(b => b.leftoverBalanceAmount);
    if (
      (this.userScope === Scope.Customer || this.userScope === Scope.Kiosk) &&
      (this.betSlipConfiguration.betCategory === BetCategoryType.SportsFixedOdds ||
        this.betSlipConfiguration.betCategory === BetCategoryType.VirtualFixedOdds) &&
      !useLeftOver
    ) {
      this.betSlipService.saveLastBetStakePerBetCategory(changes.amount);
    }
    this.betSlipService.updateBetLine(changes.line, changes.amount);
    this.checkIsBonusIntoView(this.mediaService.media);
    this.checkSimulatedMode();
  }

  onBetLineRemove(betLine: BetLine) {
    this.betSlipBetLinesService.toggleBetLine(betLine, false);
    this.checkIsBonusIntoView(this.mediaService.media);
    this.checkSimulatedMode();
    if (!this.betLines?.length) {
      this.dialogService.toggleDialog('betslip', false);
    }
  }

  onRemoveInstantGameTransaction(index: number) {
    this.betSlipService.removeInstantGameTransaction(index);
    this.checkIsBonusIntoView(this.mediaService.media);
  }

  onTransactionChange(multiplier: number, index: number) {
    this.betSlipService.updateInstantGameTransaction(multiplier, index);
    this.checkIsBonusIntoView(this.mediaService.media);
  }

  onFreeBetCouponSelectionChanges(coupon: FreeBetCouponBetSlip | null) {
    const hasChange: boolean = coupon?.id !== this.selectedFreeBetCoupon?.id;
    if (hasChange && (!coupon || coupon.isBetCompletion || coupon.canBeUsed)) {
      this.selectedFreeBetCoupon = coupon;
      this.betSlipService.onFreeBetCouponChange(this.selectedFreeBetCoupon);
      this.cdRef.markForCheck();
    }
  }

  isBetSlipCompatibleWithCashout(): boolean {
    return (
      this.betSlipConfiguration.betCategory === BetCategoryType.SportsFixedOdds &&
      this.mode !== BetSlipMode.Systems &&
      !this.amounts?.useFreeBet &&
      this.betLines.every(
        bl =>
          bl.active &&
          bl.bettingAllowed &&
          this.operatorConfiguration.cashoutConfiguration?.betTypesPerEntryPoints[bl.entryPointId]?.findIndex(
            bt => bt === bl.betTypeId
          ) > -1 &&
          bl.betCategoryType === BetCategoryType.SportsFixedOdds &&
          bl.eventBetTypeItemId
      ) &&
      this.type === BetSlipType.Real
    );
  }

  canPlaceBet() {
    return this.betSlipService.isBetSlipValid(
      this.amounts?.useFreeBet ? this.selectedFreeBetCoupon?.balance ?? 0 : this.balance
    );
  }

  canGetBetCode() {
    return this.betSlipService.isBetSlipValid(
      this.amounts?.useFreeBet ? this.selectedFreeBetCoupon?.balance ?? 0 : this.balance
    );
  }

  needToApplyNewOdds() {
    return this.betLines.some(l => !!l.newOdds && l.odds !== l.newOdds);
  }

  applyNewOdds() {
    this.checkIsBonusIntoView(this.mediaService.media);
    this.betSlipService.applyNewOdds();
  }

  acceptOddChangeChange() {
    this.betSlipService.setAcceptOddChange(this.acceptOddChange);
  }

  toggleFreeBetMode(useFreeBet: boolean) {
    if (useFreeBet && this.betSlipFreebetService.shouldDisplayTutorial()) {
      this.openFreebetTutorial();
    }
    this.betSlipService.toggleFreeBetMode(useFreeBet);

    if (!useFreeBet && !!this.selectedFreeBetCoupon) {
      this.onFreeBetCouponSelectionChanges(null);
    }

    this.canBeCashedout = this.isBetSlipCompatibleWithCashout();
  }

  openFreebetTutorial(): void {
    this.messageService
      .sendComponentMessage(BetSlipFreebetTutorialComponent, {}, { canBeDismissed: false, displayClose: false })
      .closed.pipe(takeUntil(this.destroy$))
      .subscribe(() => this.betSlipFreebetService.validateTutorial());
  }

  placeBet() {
    this.betSlipFailureType = undefined;

    if (this.placingBet || this.isLoadingOddsEventIds.length || this.isLoadingLastSelection) {
      return;
    }

    if (this.userStatus !== 'connected') {
      this.userNeedToBeLoggedIn = true;
      this.dialogService.toggleDialog('betslip', false);
      this.dialogService.toggleDialog('login', true);
      const sub = this.dialogService.registerDialog('login').subscribe(x => {
        if (!x) {
          this.dialogService.toggleDialog('betslip', true);
          sub.unsubscribe();
        }
      });
    } else if (this.canPlaceBet()) {
      this.betSlipFailure = undefined;
      this.betSlipValidationFailure = undefined;
      this.placingBet = true;
      this.betSlipService
        .placeBet(this.customerBehalfIdentity)
        .pipe(
          finalize(() => {
            this.placingBet = false;
            this.cdRef.markForCheck();
          })
        )
        .subscribe(
          betPlacedResponse => {
            if (betPlacedResponse.result) {
              if (this.type === BetSlipType.Simulate) {
                this.displayBetSlipSimulatedResult(betPlacedResponse.response as CreateSimulatedBetResponse);
                return;
              }

              this.betValidated = true;

              this.betSlipService.saveLastSelection(this.betSlipConfiguration.betCategory);

              if (this.betSlipConfiguration.betCategory === BetCategoryType.InstantGame) {
                this.betValidatedContext = {
                  betCategoryType: this.betSlipConfiguration.betCategory,
                  maxPayout: null,
                  totalOdds: null,
                  betsNumber: 1,
                  totalStake: betPlacedResponse.response?.ticket.totalStake,
                  ticket: betPlacedResponse.response?.ticket
                };
              } else {
                this.betValidatedContext = {
                  betCategoryType: this.betSlipConfiguration.betCategory,
                  betsNumber: this.mode === BetSlipMode.Simple ? this.betLines.length : null,
                  maxPayout: betPlacedResponse.response.ticket?.maxPayout ?? this.amounts.summary.maxPayout,
                  totalOdds: this.getTotalOdds(),
                  totalStake: this.amounts.summary.totalStakeWithTax || this.amounts.summary.totalStake,
                  ticket: betPlacedResponse.response?.ticket,
                  betSystemId:
                    this.betSlipConfiguration.betCategory === BetCategoryType.SportsFixedOdds
                      ? (<CreateBetResponse>betPlacedResponse.response)?.betSystemsIds?.[0]
                      : null,
                  canBeSimulated: this.isSimulatedModeEnabled,
                  useFreebet: this.amounts.useFreeBet,
                  hideBetCode: !this.hasOnlyPendingBetLines,
                  isBetCompletion: !!this.completeMyBetInfo?.betId
                };
              }
            } else {
              this.betSlipValidationFailure = betPlacedResponse.reason;
            }
          },
          (err: BettingError) => {
            [this.betSlipFailure, this.betSlipFailureData] =
              this.type === BetSlipType.Simulate
                ? this.getSimulatedBetFailure(err.failure as CreateSimulatedBetFailures, err.data)
                : this.getFailure(err.failure as CreateBetFailures, err.data);
            this.betSlipFailureType =
              this.type === BetSlipType.Simulate
                ? (err.failure as CreateSimulatedBetFailures)
                : (err.failure as CreateBetFailures);
            if (this.type === BetSlipType.Real && this.betSlipFailureType === CreateBetFailures.OutdatedNonRunners) {
              this.betSlipService.refreshEvent();
            } else {
              this.showBetLineFailuresError(err);
            }
          }
        );
    }
  }

  changeMode(mode: BetSlipMode) {
    if (!this.disabledModes.includes(mode)) {
      this.betSlipBetLinesService.changeMode(mode);
    }
  }

  getBetCode(betSystemId?: number): void {
    if (!betSystemId && !this.canGetBetCode()) {
      return;
    }

    this.betSlipFailure = undefined;
    this.gettingCode = true;

    const resolvedBetSystemId: number = betSystemId ?? this.betValidatedContext?.betSystemId;

    this.betSlipService
      .getBetCode(resolvedBetSystemId, this.getDecimalTotalOdds())
      .pipe(
        finalize(() => {
          this.gettingCode = false;
          this.cdRef.markForCheck();
        })
      )
      .subscribe({
        next: code => this.onBetCodeSuccess(code),
        error: (err: BettingError) => this.onBetCodeError(err)
      });
  }

  private onBetCodeSuccess(code: { code: string }): void {
    const { betCategory } = this.betSlipConfiguration;
    const payload: BetCodeGenerated = this.buildBetCodePayload(code.code, betCategory);

    if (payload) {
      this.betCodeGenerated.emit(payload);
    }
  }

  private buildBetCodePayload(code: string, betCategory: BetCategoryType): BetCodeGenerated {
    const basePayload: BetCodeGenerated = { code, betCategory };

    switch (betCategory) {
      case BetCategoryType.SportsFixedOdds:
        return {
          ...basePayload,
          totalOdds: this.getTotalOdds(),
          ...this.getOddsBoostPayload()
        };

      case BetCategoryType.DrawGame:
        return {
          ...basePayload,
          drawGameEventsName: this.getUniqueEventNames()
        };
    }
  }

  private getUniqueEventNames(): string[] {
    return [
      ...this.betLines
        .map(betLine => betLine.eventName)
        .filter((name, index, self): name is string => !!name && self.indexOf(name) === index)
    ];
  }

  private onBetCodeError(err: BettingError): void {
    this.cdRef.markForCheck();

    if (this.isCreateBetCodeFailure(err.failure)) {
      [this.betSlipFailure, this.betSlipFailureData] = this.getCreateBetCodeFailure(
        err.failure as CreateBetCodeFailure,
        err.data
      );
    } else if (err.failure === CreateBetFailures.BetLineFailures) {
      this.showBetLineFailuresError(err);
    } else {
      [this.betSlipFailure, this.betSlipFailureData] = this.getFailure(err.failure as CreateBetFailures, err.data);
    }
  }

  private isCreateBetCodeFailure(failure: unknown): boolean {
    return (
      failure === CreateBetCodeFailure.MaxPayoutReached ||
      failure === CreateBetCodeFailure.MaximumNumberOfBetLinesReached ||
      failure === CreateBetCodeFailure.IllegalMinimumOdds ||
      failure === CreateBetCodeFailure.IllegalMaximumOdds
    );
  }

  private getOddsBoostPayload(): { isOddsBoost: boolean; oddsBoostName: string | null } {
    const isSingleWithBoost: boolean = this.betLines.length === 1 && !!this.betLines[0].oddsBoostId;
    return {
      isOddsBoost: isSingleWithBoost,
      oddsBoostName: isSingleWithBoost ? this.betLines[0].oddsBoost.name : null
    };
  }

  closeBetValidation(params: { keepSelection: boolean; isSimulate: boolean }) {
    this.canCopy =
      this.allowedToCopyLastBetSlipSelection &&
      this.lastBetSelectionPerBetCategory[this.betSlipConfiguration.betCategory] &&
      !params.keepSelection;
    const deactivateFreebetMode: boolean = !!this.selectedFreeBetCoupon;
    this.betSlipService.unLock();

    if (!params.keepSelection) {
      this.betSlipService.clear();
    } else {
      this.betSlipService.clearCompleteMyBetSelection();
    }

    if (deactivateFreebetMode) {
      this.betSlipService.toggleFreeBetMode(false);
      this.betSlipService.refreshFreeBetCoupons();
    }

    this.betValidatedContext = null;
    this.betValidated = false;

    if (params.isSimulate) {
      this.changeBetSlipType(BetSlipType.Simulate);
      return;
    }

    this.dialogService.toggleDialog('betslip', false);
  }

  // Used to ensure that the closing of the bet validation dialog is handled correctly if the user navigate without manual closing action
  private tryCloseBetValidation(): void {
    if (this.betValidated) {
      this.closeBetValidation({ keepSelection: false, isSimulate: false });
    }
  }

  private getFailure(failure: CreateBetFailures, data: any): [string, any[]] {
    switch (failure) {
      case CreateBetFailures.BetSystemCannotHaveBetLinesWithSameEvent:
        return ['MULTIPLE_BETLINE_SAME_EVENT', []];
      case CreateBetFailures.SystemNotAuthorizedDueToNumberOfBetLines:
        return ['TOO_MANY_LINES', []];
      case CreateBetFailures.MaximumNumberOfBetLinesReached:
        return ['MAXIMUM_BETLINES_REACHED', [data.maximumNumberOfBetLines]];
      case CreateBetFailures.MaximumPayoutReached:
        return [
          data.useFreeBet ? 'MAXIMUM_FREEBET_PAYOUT_REACHED' : 'MAXIMUM_PAYOUT_REACHED',
          [this.i18nService.formatCurrencySync(data.maximumPayout, true)]
        ];
      case CreateBetFailures.InvalidFreeBetStake:
        return ['INVALID_FREEBET_STAKES', []];
      case CreateBetFailures.FreeBetStakeMustBeAllFreeBetBalance:
        return ['MUST_USE_ALL_FREEBET_BALANCE', []];
      case CreateBetFailures.InsufficientFunds:
        return ['INSUFFICIENT_FUNDS', []];
      case CreateBetFailures.IllegalMinimumOdds:
        return ['ILLEGAL_MINIMUM_ODDS', [this.i18nService.formatNumberSync(data.minimumOdds, true, '1.2-2')]];
      case CreateBetFailures.IncompatibleStake:
        return ['INCOMPATIBLE_STAKE', [data]];
      case CreateBetFailures.CustomerHasNotAcceptedGCU:
        return ['NEED_TO_ACCEPT_GCU', []];
      case CreateBetFailures.TooManyRequests:
        return ['TOO_MANY_REQUESTS', []];
      case CreateBetFailures.IllegalMaximumOdds:
        return ['ILLEGAL_MAXIMUM_ODDS', [this.i18nService.formatNumberSync(data.maximumOdds, true, '1.2-2')]];
      case CreateBetFailures.BetTypeMaximumAmountExceededError:
        return ['BETTYPE_MAXIMUM_AMOUNT_EXCEEDED', []];
      case CreateBetFailures.AgentLimitReached:
        return ['AGENT_LIMIT_REACHED', []];
      case CreateBetFailures.CheckMultipleError:
        return ['INVALID_BET', []];
      case CreateBetFailures.RaceStarted:
        return ['RACE_STARTED', []];
      case CreateBetFailures.CustomerLimitationExceeded:
        return ['LIMIT_REACHED', []];
      case CreateBetFailures.CustomerSelfExcluded:
        return ['EXCLUDED', []];
      case CreateBetFailures.CustomerBettingNotAllowed:
        return ['BETTING_NOT_ALLOWED', []];
      case CreateBetFailures.CustomerIdentityNotValidated:
        return ['IDENTITY_NOT_VALIDATED', []];
      case CreateBetFailures.EventExpectedStartHasPassed:
        return [this.isDrawGameError() ? 'DRAW_GAME_NOT_AVAILABLE' : 'EVENT_NOT_AVAILABLE', []];
      case CreateBetFailures.BetSystemSimpleNotAllowed:
        return ['BET_SYSTEM_SIMPLE_NOT_ALLOWED', []];
      case CreateBetFailures.CompletionNotAllowed:
      case CreateBetFailures.CompletionNotAllowedForUser:
      case CreateBetFailures.CompletionNotAllowedInvalidBetState:
      case CreateBetFailures.CompletionNotAllowedInvalidEventState:
      case CreateBetFailures.CompletionNotAllowedInvalidEventType:
      case CreateBetFailures.CompletionNotAllowedPendingSettlement:
      case CreateBetFailures.CompletionNotAllowedBetBuilder:
        return ['COMPLETION_NOT_ALLOWED', []];
      case CreateBetFailures.CompletionNotAllowedOngoing:
        return ['ONGOING_COMPLETION_NOT_ALLOWED', []];
      case CreateBetFailures.CompletionNotAllowedPreEvent:
        return ['PREEVENT_COMPLETION_NOT_ALLOWED', []];
      case CreateBetFailures.CompletionNotAllowedLive:
        return ['LIVE_COMPLETION_NOT_ALLOWED', []];
      case CreateBetFailures.CompletionNotAllowedCoupons:
        return ['FREEBET_COMPLETION_NOT_ALLOWED', []];
      case CreateBetFailures.UnavailableManualOddsBoost:
        return ['FUNBET_NOT_AVAILABLE', []];
      case CreateBetFailures.ManualOddsBoostHasExpired:
        return ['ODDBOOST_NOT_AVAILABLE', []];
      case CreateBetFailures.RequestOddsIsDifferentThanDataBaseOdds:
        return ['ODDS_OTHER_THAN_DB_ODDS', []];
      case CreateBetFailures.FreeBetInvalidStake:
        return [
          data.minimumStake ? 'MINIMUM_FREEBET_STAKE_AMOUNT' : 'MAXIMUM_FREEBET_STAKE_AMOUNT',
          [this.i18nService.formatCurrencySync(data.minimumStake ?? data.maximumStake)]
        ];
      case CreateBetFailures.GameSessionOpened:
        return ['GAME_SESSION_OPENED', []];
      default:
        return ['GENERIC', []];
    }
  }

  private getSimulatedBetFailure(failure: CreateSimulatedBetFailures, data: any): [string, any[]] {
    switch (failure) {
      case CreateSimulatedBetFailures.MaximumPayoutReached:
        return ['MAXIMUM_PAYOUT_REACHED', [this.i18nService.formatCurrencySync(data.maximumPayout, true)]];
      case CreateSimulatedBetFailures.InsufficientFunds:
        return ['INSUFFICIENT_FUNDS', []];
      case CreateSimulatedBetFailures.IllegalMinimumOdds:
        return ['ILLEGAL_MINIMUM_ODDS', [this.i18nService.formatNumberSync(data.minimumOdds, true, '1.2-2')]];
      case CreateSimulatedBetFailures.IllegalMaximumOdds:
        return ['ILLEGAL_MAXIMUM_ODDS', [this.i18nService.formatNumberSync(data.maximumOdds, true, '1.2-2')]];
      case CreateSimulatedBetFailures.CustomerLimitationExceeded:
        return ['LIMIT_REACHED', []];
      case CreateSimulatedBetFailures.CustomerSelfExcluded:
        return ['EXCLUDED', []];
      case CreateSimulatedBetFailures.CustomerBettingNotAllowed:
        return ['BETTING_NOT_ALLOWED', []];
      case CreateSimulatedBetFailures.CustomerIdentityNotValidated:
        return ['IDENTITY_NOT_VALIDATED', []];
      case CreateSimulatedBetFailures.CustomerHasNotAcceptedGCU:
        return ['NEED_TO_ACCEPT_GCU', []];
      case CreateSimulatedBetFailures.InstantGameNotFound:
      case CreateSimulatedBetFailures.BetLineFailures:
      case CreateSimulatedBetFailures.MissingCorrectScore:
        return ['SIMULATED_MODE', []];
      case CreateSimulatedBetFailures.MaximumNumberOfBetLinesReached:
        return ['MAXIMUM_BETLINES_REACHED', [data.maximumNumberOfBetLines]];
      default:
        return ['GENERIC', []];
    }
  }

  private getCreateBetCodeFailure(failure: CreateBetCodeFailure, data: any): [string, any] {
    switch (failure) {
      case CreateBetCodeFailure.MaxPayoutReached:
        return ['MAXIMUM_PAYOUT_REACHED', [this.i18nService.formatCurrencySync(data.maximumPayout, true)]];
      case CreateBetCodeFailure.MaximumNumberOfBetLinesReached:
        return ['MAXIMUM_NUMBER_OF_BETLINES_REACHED', [data.maximumNumberOfBetLines]];
      case CreateBetCodeFailure.IllegalMinimumOdds:
        return ['ILLEGAL_MINIMUM_ODDS', [this.i18nService.formatNumberSync(data.minimumOdds, true, '1.2-2')]];
      case CreateBetCodeFailure.IllegalMaximumOdds:
        return ['ILLEGAL_MAXIMUM_ODDS', [this.i18nService.formatNumberSync(data.maximumOdds, true, '1.2-2')]];
      default:
        return ['GENERIC', []];
    }
  }

  // Unselect coupon when it can't be used or MustUseAllBalance is active : Stake < Balance (except in case of bet completion)
  private shouldUnselectCoupon(): boolean {
    return (
      !this.amounts.useFreeBet ||
      !this.freeBetCoupons.find(
        (coupon: FreeBetCouponBetSlip) => coupon.id === this.selectedFreeBetCoupon.id && coupon.canBeUsed
      ) ||
      (this.selectedFreeBetCoupon.freeBetRule.mustUseAllBalance &&
        this.amounts.summary.totalStakeWithTax !== this.selectedFreeBetCoupon.balance &&
        this.completeMyBetInfo?.freebetCouponId != this.selectedFreeBetCoupon.id)
    );
  }

  onFailureMessageClick() {
    if (
      (this.type === BetSlipType.Real && this.betSlipFailureType === CreateBetFailures.CustomerHasNotAcceptedGCU) ||
      (this.type === BetSlipType.Simulate &&
        this.betSlipFailureType === CreateSimulatedBetFailures.CustomerHasNotAcceptedGCU)
    ) {
      this.bcService.broadcast('display-gcu-popin');
    }
  }

  getTotalOdds(): string {
    let totalOdds: string = null;
    if (this.mode === BetSlipMode.Multiple) {
      totalOdds = this.betLines.reduce((sum, l) => sum * l.odds, 1).toFixed(2);
    } else if (this.mode === BetSlipMode.Simple && this.betLines.length === 1 && this.betLines[0].odds) {
      totalOdds = this.betLines[0].odds.toFixed(2);
    }

    return totalOdds;
  }

  getDecimalTotalOdds(): number | null {
    var totalOdds = this.getTotalOdds();
    if (!!totalOdds) {
      return parseFloat(totalOdds);
    }
    return null;
  }

  copyLastSelection() {
    if (!this.isLoadingLastSelection && !this.isLoadingOddsEventIds.length) {
      this.isLoadingLastSelection = true;
      this.checkIsBonusIntoView(this.mediaService.media);
      this.bcService.broadcast('bet_slip_copy_last_selection');
      this.betSlipBetLinesService
        .copyLastSelection(this.betSlipConfiguration.betCategory)
        .pipe(
          takeUntil(this.destroy$),
          finalize(() => {
            this.isLoadingLastSelection = false;
            this.cdRef.markForCheck();
          })
        )
        .subscribe();
    }
  }

  detectAndroid() {
    if (isPlatformBrowser(this.platformId)) {
      this.userAgent = navigator.userAgent.toLowerCase();
      this.isAndroid = this.userAgent.indexOf('android') > -1;

      if (this.isAndroid) {
        this.heightForAndroid = true;
      }
    }
  }

  showBetLineFailuresError(err: BettingError) {
    if (!err.betLinesFailures?.length) {
      return;
    }

    for (const lineFailure of err.betLinesFailures) {
      for (const reason of lineFailure.reason) {
        switch (reason.failure) {
          case BetLineFailure.MaximumRiskReached:
            this.betSlipFailureData = err.betLinesFailures
              .map(x => x.reason.find(y => y.failure === BetLineFailure.MaximumRiskReached)?.data)
              .filter(Boolean)
              .sort((a, b) => a - b)[0];

            let message = '';
            if (
              this.mode === BetSlipMode.Multiple ||
              (this.mode === BetSlipMode.Simple && this.betLines.length === 1)
            ) {
              message = 'STAKE_TOO_HIGH.NEW_STAKE_CURRENCY';
            } else {
              message = 'STAKE_TOO_HIGH.NEW_STAKES';
            }
            this.betSlipFailure = !!this.betSlipFailureData ? message : 'STAKE_TOO_HIGH';
            return;
          case BetLineFailure.OfflineEvent:
            this.betSlipFailure = this.isDrawGameError() ? 'DRAW_GAME_NOT_AVAILABLE' : 'EVENT_NOT_AVAILABLE';
            return;
          case BetLineFailure.OfflineEventBetType:
            this.betSlipFailure = 'EVENTBETTYPE_NOT_AVAILABLE';
            return;
          case BetLineFailure.FixedOddsChanged:
            this.betSlipFailure = 'FIXED_ODDS_CHANGED';
            return;
        }
      }
    }
  }

  isDrawGameError(): boolean {
    return this.betLines.length > 0 ? this.betLines[0].betCategoryType === BetCategoryType.DrawGame : false;
  }

  checkIsBonusIntoView(x: Media) {
    if (x < Media.lg) {
      if (this.viewRef && this.viewRef.element.nativeElement) {
        const hostScrollTop = this.viewRef.element.nativeElement.scrollTop;
        const hostScrollBottom = hostScrollTop + this.viewRef.element.nativeElement.clientHeight <= window.innerHeight;
        this.isBonusScrolledIntoTopView = hostScrollBottom;

        this.isBonusScrolledIntoBottomView =
          this.viewRef.element.nativeElement.offsetHeight + this.viewRef.element.nativeElement.scrollTop >=
          this.viewRef.element.nativeElement.scrollHeight - 100;
      } else {
        this.isBonusScrolledIntoBottomView = false;
      }
    } else {
      if (this.bonusCard && this.actionButton) {
        const rect = this.actionButton?.nativeElement.getBoundingClientRect();
        this.isBonusScrolledIntoTopView = rect.top >= 0;
        this.isBonusScrolledIntoBottomView = rect.bottom < window.innerHeight;
      } else {
        this.isBonusScrolledIntoTopView = false;
        this.isBonusScrolledIntoBottomView = false;
      }
    }

    this.cdRef.markForCheck();
  }

  jumpToActionButton(): void {
    const element = this.actionButton.nativeElement;
    const container = this.viewRef.element.nativeElement as HTMLElement;
    const offset = 40;
    this.hasScrolled = false;

    if (!this.hasScrolled) {
      this.hasScrolled = true;
      const elementRect = element.getBoundingClientRect();
      const containerRect = container.getBoundingClientRect();
      const containerPosition =
        elementRect.bottom - containerRect.top + container.scrollTop - container.clientHeight + offset + offset;
      const windowPosition = elementRect.bottom + window.scrollY - window.innerHeight + offset;

      if (this.mediaService.media < Media.lg) {
        container.scrollTo({
          top: containerPosition,
          behavior: 'smooth'
        });
      } else {
        window.scrollTo({
          top: windowPosition,
          behavior: 'smooth'
        });
      }
    }
  }

  changeBetSlipType(type: BetSlipType) {
    this.type = type;
    this.betSlipService.changeType(this.type);
    this.betSlipService.toggleFreeBetMode(false);
    this.canBeCashedout = this.isBetSlipCompatibleWithCashout();

    if (type === BetSlipType.Real || localStorage.getItem('betslip:simulate_modal:valid')) {
      return;
    }

    this.messageService.sendComponentMessage(
      BetSlipSimulateComponent,
      {},
      { canBeDismissed: false, displayClose: false }
    );
  }

  checkCustomerIdentity() {
    this.identifiedRetailService.checkCustomerIdentity().subscribe(result => {
      if (result.success) {
        this.customerBehalfIdentity = result.customerBehalfIdentity;
        this.identifiedRetailService.saveCustomerIdentity(this.customerBehalfIdentity);
        this.placeBet();
      }
    });
  }

  ngOnDestroy() {
    super.ngOnDestroy();

    if (this.resizeObserver) {
      this.resizeObserver.disconnect();
    }
    this.tryCloseBetValidation();
  }

  checkSimulatedMode() {
    this.isSimulatedModeEnabled =
      this.operatorConfiguration.bettingConfiguration?.allowSimulatedMode &&
      this.betLines.length > 0 &&
      !this.betLines.some(betLine => !betLine.canBeSimulated || betLine.isBetBuilder) &&
      !this.isAgent;

    if (this.type === BetSlipType.Simulate && !this.isSimulatedModeEnabled) {
      this.changeBetSlipType(BetSlipType.Real);
    }
  }

  displayBetSlipSimulatedResult(simulatedBetPlacedResponse: CreateSimulatedBetResponse) {
    this.messageService
      .sendComponentMessage(
        BetSlipSimulateResultComponent,
        { simulatedBetPlacedResponse: simulatedBetPlacedResponse },
        {
          canBeDismissed: false,
          displayClose: false,
          className: 'simulated-mode'
        }
      )
      .closed.subscribe(keepSelection => {
        this.closeBetValidation({ keepSelection: keepSelection, isSimulate: keepSelection });
      });
  }

  displayTaxInformations(): void {
    this.showTaxInformations = !this.showTaxInformations;
  }

  get showDepositButton(): boolean {
    return (
      this.enablePopupMethodDeposit &&
      this.userStatus === 'connected' &&
      this.hasInsufficientBalance &&
      !this.amounts?.useFreeBet
    );
  }

  get showBalanceButton(): boolean {
    return this.showDepositButton && this.mediaService.media < Media.lg;
  }

  openDepositPopup(): void {
    this.transactionPopupService?.open(TransactionMode.Deposit);
  }

  private checkInsufficientBalance(): void {
    if (!this.amounts || !this.betSlipConfiguration || !this.enablePopupMethodDeposit) {
      this.hasInsufficientBalance = false;
      return;
    }

    const totalStake: number = this.amounts.summary?.totalStakeWithTax || (this.amounts.summary?.totalStake ?? 0);
    const freeBetBalance: number | undefined = this.amounts.useFreeBet
      ? this.selectedFreeBetCoupon?.balance
      : undefined;

    this.betValidationService
      .canPlaceBet(totalStake, this.betSlipConfiguration.betCategory, freeBetBalance, false)
      .pipe(take(1), takeUntil(this.destroy$))
      .subscribe(({ result }) => {
        this.hasInsufficientBalance = !result;
        this.missingBalance = result ? 0 : sub(totalStake, this.balance);
        this.cdRef.markForCheck();
      });
  }

  private handleBetBuilderLinesChanges(): void {
    this.hasBetBuilderBetLines = this.betSlipBetBuilderService.hasBetBuilderBetLines;
    this.hasBetBuilderErrors = this.hasBetBuilderBetLines && this.betSlipBetBuilderService.hasBetBuilderErrors;
    this.betBuilderModeLabel = this.betSlipBetBuilderService.betBuilderModeLabel;
    if (this.amounts?.useFreeBet && this.hasBetBuilderBetLines && !this.isBetBuilderFreebetAllowed) {
      this.toggleFreeBetMode(false);
    }
  }

  private listenOnBalanceChanges(): void {
    this.authService.balance$?.pipe(takeUntil(this.destroy$)).subscribe((balance: number) => {
      this.balance = balance;
      this.checkInsufficientBalance();
      this.cdRef.markForCheck();
    });
  }

  private listenOnBetBuilderLoadingChanges(): void {
    this.betSlipBetBuilderService.isLoadingOddsEventIds$
      .pipe(takeUntil(this.destroy$))
      .subscribe((isLoadingOddsEventIds: number[]) => {
        this.isLoadingOddsEventIds = isLoadingOddsEventIds;
        this.cdRef.markForCheck();
      });
  }
}
