import { NotificationInfos } from './notifications-infos.model';
import { PaymentAccount } from './payment-account.model';
import { CustomerProfile } from './customer-profile.model';

export interface Me {
  id: number;
  login: string;
  state: CustomerState;
  balance: number;
  freeBalance: number;
  loyaltyBalance: number;
  referralBalance: number;
  hasAcceptedGcu: boolean;
  referrerActive: boolean;
  customerPaymentAccounts: PaymentAccount[];
  superReferrerState: CustomerSuperReferrerState;
  superReferrerActive: boolean;
  depositsAllowed: boolean;
  withdrawalsAllowed: boolean;
  notificationInformations?: NotificationInfos;
  profile?: CustomerProfile;
  selfExclusionEndDate?: Date;
  responsibleGamblingDeposit?: number;
  responsibleGamblingSportStake?: number;
  responsibleGamblingHorseRacingStake?: number;
  responsibleGamblingVirtualStake?: number;
  responsibleGamblingDrawGameStake?: number;
  responsibleGamblingInstantGameStake?: number;
  isLocked: boolean;
  mustChangePassword: boolean;
  reference: string;
  completeMyBetAllowed: boolean;
  externalTokens?: Record<'ZendeskToken' | 'SmarticoUserHash', string>;
  hideBalance?: boolean;
}

export enum CustomerState {
  None = 0,
  // tslint:disable-next-line:no-bitwise
  LoginValidated = 1 << 0,
  // tslint:disable-next-line:no-bitwise
  IdentityValidated = 1 << 1,
  // tslint:disable-next-line:no-bitwise
  Validated = LoginValidated | IdentityValidated,
  Blacklisted = 1 << 2
}

export enum CustomerSuperReferrerState {
  None = 'None',
  WaitingForValidation = 'WaitingForValidation',
  Validated = 'Validated',
  Refused = 'Refused'
}
