import { HttpEvent, HttpHandler, HttpInterceptor, HttpRequest, HttpErrorResponse } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { Observable } from 'rxjs';
import { catchError } from 'rxjs/operators';
import { ConnectionErrorComponent } from '../popins/connection-error/connection-error.component';
import { MessageService } from '@honoregaming/ui';

@Injectable()
export class ConnectionErrorInterceptor implements HttpInterceptor {
  constructor(private messageService: MessageService) {}
  public intercept(req: HttpRequest<any>, next: HttpHandler): Observable<HttpEvent<any>> {
    return next.handle(req).pipe(
      catchError(e => {
        // status 504 is what the sw return when it get an 0
        if (
          e instanceof HttpErrorResponse &&
          (e.status === 0 || e.status === 504) &&
          req.url.indexOf('/operatordata/content') === -1
        ) {
          this.messageService.sendComponentMessage(ConnectionErrorComponent);
        }
        throw e;
      })
    );
  }
}
