import { Inject, Injectable } from '@angular/core';
import { BetCategoryType } from '@honoregaming/types';
import {
  CustomerOperatorConfiguration,
  customerOperatorConfigurationToken,
  HorseRacingMenuLink,
  MenuShortcut
} from '@honoregaming/customer-core';
import {
  EnabledDisabledMode,
  OperatorConfiguration,
  operatorConfigurationToken,
  TicketStateCheckerMode
} from '@honoregaming/configuration';
import { BetCategoryConfigurationService, kioskToken } from '@honoregaming/core';

@Injectable({
  providedIn: 'root'
})
export class MenuCustomizationService {
  private readonly shortcutsMenuAnchor = 'shortcuts-burger-menu';
  private readonly horseRacingMenuAnchor = 'horseracing-desktop-menu-links';

  private categoriesByShortcutType: { [key: string]: BetCategoryType[] } = {
    sports: [BetCategoryType.SportsFixedOdds],
    [this.betCategoryConfigurationService.getInstantGamesBetCategoryPath()]: [BetCategoryType.InstantGame],
    virtual: [BetCategoryType.VirtualFixedOdds],
    horseracing: [BetCategoryType.HorseRacingMutualOperatorPool, BetCategoryType.HorseRacingMutualInternationalPool],
    'draw-games': [BetCategoryType.DrawGame],
    sportspool: [BetCategoryType.SportsPool]
  };
  private featureByShortcutType: { [key: string]: string } = {
    'odds-boost': 'OddsBoost',
    'manual-odds-boosts': 'ManualOdds'
  };

  private promotionShortcut: MenuShortcut = {
    type: 'promotion',
    action: {
      url: '/about/promotions'
    },
    iconUrl: 'promotions',
    text: 'NAV.PROMOTIONS',
    order: '5'
  };

  constructor(
    private betCategoryConfigurationService: BetCategoryConfigurationService,
    @Inject(customerOperatorConfigurationToken) private customerOperatorConfiguration: CustomerOperatorConfiguration,
    @Inject(operatorConfigurationToken) public operatorConfiguration: OperatorConfiguration,
    @Inject(kioskToken) public isKiosk: boolean
  ) {}

  get mobileShortcuts(): MenuShortcut[] {
    if (!this.customerOperatorConfiguration.customization[this.shortcutsMenuAnchor]) {
      return [];
    }
    const shortcutsLinks: MenuShortcut[] = this.customerOperatorConfiguration.customization[
      this.shortcutsMenuAnchor
    ].filter(
      (menuShortcut: MenuShortcut) =>
        this.isEnabledCategory(menuShortcut.type) ||
        this.isEnabledFeature(menuShortcut.type) ||
        this.isBetCodeEnabled(menuShortcut.type) ||
        this.isOtherType(menuShortcut.type)
    );

    if (
      (shortcutsLinks.length === 5 || shortcutsLinks.length === 2) &&
      this.customerOperatorConfiguration.contentsConfiguration?.hasPromotions
    ) {
      shortcutsLinks.push(this.promotionShortcut);
    }
    return shortcutsLinks;
  }

  getHorseRacingMenuLinks(oldConfig: HorseRacingMenuLink[] = []): HorseRacingMenuLink[] {
    const links: HorseRacingMenuLink[] =
      this.customerOperatorConfiguration.customization?.[this.horseRacingMenuAnchor] ?? oldConfig;

    return links.filter((link: HorseRacingMenuLink) => this.isHorseRacingLinkVisible(link));
  }

  private isHorseRacingLinkVisible(link: HorseRacingMenuLink): boolean {
    switch (link.requiresFeature) {
      case 'results':
        return !!this.operatorConfiguration.horseRacesResultsConfiguration?.horseRacesResults?.customerOnline;
      case 'coupons':
        return this.operatorConfiguration.features?.horseRacingFeatures?.couponMode === EnabledDisabledMode.Enabled;
      case 'streaming':
        return this.operatorConfiguration.features?.horseRacingFeatures?.streamingMode === EnabledDisabledMode.Enabled;
      default:
        return true;
    }
  }

  private isEnabledCategory(type: string): boolean {
    return (
      this.categoriesByShortcutType[type] &&
      this.operatorConfiguration.betCategories.some(x => this.categoriesByShortcutType[type].indexOf(x) !== -1)
    );
  }

  private isEnabledFeature(type: string): boolean {
    return (
      this.featureByShortcutType[type] &&
      this.operatorConfiguration.operatorFeatures?.indexOf(this.featureByShortcutType[type]) > -1 &&
      (type !== 'manual-odds-boosts' || !this.isKiosk)
    );
  }

  private isBetCodeEnabled(type: string): boolean {
    return (
      type === 'ticket-betcode' &&
      (this.customerOperatorConfiguration.betCodeConfiguration?.isBetCodeCheckerEnabled ||
        this.customerOperatorConfiguration.features.ticketStateCheckerMode !== TicketStateCheckerMode.Disabled)
    );
  }

  private isOtherType(type: string): boolean {
    return type !== 'ticket-betcode' && !this.categoriesByShortcutType[type] && !this.featureByShortcutType[type];
  }
}
