import {
  Component,
  ChangeDetectionStrategy,
  HostBinding,
  Input,
  Output,
  EventEmitter,
  ChangeDetectorRef,
  Inject
} from '@angular/core';
import { EventCategoriesNavigationComponent } from '../event-categories-navigation.component';
import { EventCategoriesService } from '@honoregaming/events';
import { ActivatedRoute, Router } from '@angular/router';
import { scopeToken, Scope } from '@honoregaming/core';
import { EventCategory } from '@honoregaming/types';
import { I18nService } from '@honoregaming/i18n';

@Component({
  selector: 'hg-draw-games-ui-mobile-event-categories-navigation',
  templateUrl: './event-categories-navigation.component.html',
  styleUrls: ['./event-categories-navigation.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class MobileEventCategoriesNavigationComponent extends EventCategoriesNavigationComponent {
  @HostBinding('class.open')
  @Input()
  open = true;

  @Input()
  showClose = true;

  @Output()
  close = new EventEmitter<void>();

  constructor(
    i18nService: I18nService,
    route: ActivatedRoute,
    eventCategoriesService: EventCategoriesService,
    cdRef: ChangeDetectorRef,
    @Inject(scopeToken) public scope: Scope,
    router: Router
  ) {
    super(i18nService, route, eventCategoriesService, cdRef, scope, router);
  }

  onNavigateClick(entrypoint: EventCategory) {
    this.navigate(entrypoint);
    this.close.emit();
  }
}
