import { Component, ChangeDetectionStrategy, Output, EventEmitter, Input, HostBinding } from '@angular/core';
import { BetSlipService } from '../../services/bet-slip.service';
import { DialogService } from '@honoregaming/core';
import { BetCategoryType } from '@honoregaming/types';

@Component({
  selector: 'hg-bet-slip-clear',
  templateUrl: './bet-slip-clear.component.html',
  styleUrls: ['./bet-slip-clear.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class BetSlipClearComponent {
  @HostBinding('class')
  @Input()
  betCategory: BetCategoryType;

  @Output()
  close = new EventEmitter<boolean>();

  constructor(private betSlipService: BetSlipService, private dialogService: DialogService) {}

  clear() {
    this.betSlipService.clear();
    this.close.emit(true);
    this.dialogService.toggleDialog('betslip', false);
  }
}
