import { CustomerState } from '@honoregaming/customer-core';

export interface Provider {
  configuration: any;
  useBrowserRedirection: boolean;
  providerId: number;
  parentProviderId?: number;
  parentProviderName: string;
  displayName: string;
  providerName: string;
  requiredStateForDeposit: CustomerState;
  requiredStateForWithdraw: CustomerState;
  minWithdraw: number;
  maxWithdraw: number;
  minDeposit: number;
  maxDeposit: number;
  voucherLength: number;
  logoPath: string;
  depositStatus: PaymentProviderStatus;
  withdrawalStatus: PaymentProviderStatus;
  canUseDifferentAccount: boolean;
  canUseOtpValidation: boolean;
  banks: Bank[];
  partnerId?: number;
  active: boolean;
  needCustomerFirstName: boolean;
  needCustomerLastName: boolean;
  isDepositTaxActive?: boolean;
  isWithdrawalTaxActive?: boolean;
}

export interface InnerProvider {
  name: string;
  logoPath: string;
}

export interface Bank {
  identifier: string;
  name: string;
  type: BankAccountType;
  active: boolean;
  bankAccountPattern: string;
  bankVerificationNumberPattern: string;
  bankVerificationNumberAvailable: boolean;
}

export enum BankAccountType {
  Other = 'Other',
  Nuban = 'Nuban'
}

export enum PaymentMethodType {
  Other = 'Other',
  Bank = 'Bank',
  Account = 'Account'
}

export enum PaymentProviderStatus {
  Disabled = 'Disabled',
  Online = 'Online',
  Offline = 'Offline',
  Upcoming = 'Upcoming'
}
