import { Injectable, Inject } from '@angular/core';
import {
  EventBetType,
  EventBetTypeGroupedByBetType,
  BetTypeGroup,
  SelectableEventBetTypeItem,
  Match
} from '@honoregaming/types';
import { hasFlag } from '@honoregaming/core';
import { operatorConfigurationToken, OperatorConfiguration, Feature } from '@honoregaming/configuration';

/**
 * String constants for stats sub-filters.
 *
 * PlayerStats and TeamStats share the same enum value (1 << 9 = 512)
 * because the API returns 512 for both. TypeScript's reverse mapping
 * is last-write-wins, so BetTypeGroup[512] always yields "TeamStats".
 *
 * These explicit constants guarantee correct, stable string values
 * without relying on enum reverse lookups.
 */
export const STATS_FILTER = {
  Player: 'PlayerStats',
  Team: 'TeamStats'
} as const;

export type StatsSubFilter = typeof STATS_FILTER[keyof typeof STATS_FILTER];

/**
 * Responsible for grouping, filtering, and transforming EventBetType data
 * into the structures consumed by the event detail view.
 */
@Injectable({
  providedIn: 'root'
})
export class EventBetTypeGroupingService {
  private static readonly CONTEXT_GROUPED_BET_TYPE_IDS = new Set([10110, 10088, 12001, 22001]);

  private static readonly FILTER_ORDER_SOCCER: readonly string[] = [
    BetTypeGroup[BetTypeGroup.Result],
    BetTypeGroup[BetTypeGroup.TeamStats],
    BetTypeGroup[BetTypeGroup.PlayerStats],
    BetTypeGroup[BetTypeGroup.TeamGoal],
    BetTypeGroup[BetTypeGroup.Total],
    BetTypeGroup[BetTypeGroup.GoalGap],
    BetTypeGroup[BetTypeGroup.Score]
  ];

  constructor(
    @Inject(operatorConfigurationToken)
    private readonly operatorConfiguration: OperatorConfiguration
  ) {}

  /**
   * Groups a flat list of EventBetTypes into display groups keyed by betTypeId
   * (with context-aware splitting for certain bet-type IDs).
   */
  groupEventBetTypes(eventBetTypes: EventBetType[], event: Match): EventBetTypeGroupedByBetType[] {
    return eventBetTypes.reduce<EventBetTypeGroupedByBetType[]>(
      (groups: EventBetTypeGroupedByBetType[], ebt: EventBetType) => {
        const mapped: EventBetType = this.cloneEventBetType(ebt);

        if (!mapped.eventBetTypeItems?.length) {
          return groups;
        }

        const existingIndex: number = this.findGroupIndex(groups, ebt);

        if (existingIndex === -1) {
          groups.push(this.createGroup(ebt, mapped, event));
        } else {
          groups[existingIndex].eventBetTypes.push(mapped);
        }

        return groups;
      },
      []
    );
  }

  /**
   * Creates a shallow clone of an EventBetType with deep-cloned items.
   * Keeps the object shape explicit so nothing leaks by reference.
   */
  cloneEventBetType(ebt: EventBetType): EventBetType {
    return {
      id: ebt.id,
      name: ebt.name,
      active: ebt.active,
      bettingAllowed: ebt.bettingAllowed,
      canBeSimulated: ebt.canBeSimulated,
      betTypeId: ebt.betTypeId,
      baseAmount: ebt.baseAmount,
      minimumAmountIncrement: ebt.minimumAmountIncrement,
      maximumAmount: ebt.maximumAmount,
      displayPriority: ebt.displayPriority,
      isAsian: ebt.isAsian,
      betTypeGroup: ebt.betTypeGroup,
      hasExplanations: ebt.hasExplanations,
      isCollapsed: ebt.isCollapsed,
      isManual: ebt.isManual,
      allowBetBuilder: ebt.allowBetBuilder,
      eventBetTypeItems: ebt.eventBetTypeItems?.map((item: SelectableEventBetTypeItem) => ({ ...item }))
    };
  }

  createGroup(ebt: EventBetType, mapped: EventBetType, event: Match): EventBetTypeGroupedByBetType {
    return {
      betTypeId: ebt.betTypeId,
      betTypeContext: ebt.betTypeContext,
      displayPriority: ebt.displayPriority,
      groupName: mapped.name,
      eventBetTypes: [mapped],
      betTypeGroup: ebt.betTypeGroup,
      hasExplanations: ebt.hasExplanations,
      isCollapsed: ebt.isCollapsed,
      isManual: ebt.isManual,
      canBeCashedout: this.canBeCashedOut(ebt, event),
      canBeSimulated: this.operatorConfiguration.bettingConfiguration?.allowSimulatedMode && ebt.canBeSimulated,
      allowBetBuilder: ebt.allowBetBuilder
    };
  }

  canBeCashedOut(ebt: EventBetType, event: Match): boolean {
    if (!ebt.active || !ebt.bettingAllowed || ebt.isManual) {
      return false;
    }

    if (!this.operatorConfiguration.operatorFeatures.includes(Feature.Cashout)) {
      return false;
    }

    return (
      this.operatorConfiguration.cashoutConfiguration?.betTypesPerEntryPoints[event.entryPointId]?.includes(
        ebt.betTypeId
      ) ?? false
    );
  }

  /**
   * Builds the ordered list of filter labels from a flat bet-type array.
   */
  buildFilters(entryPointId: number, eventBetTypes: EventBetType[]): string[] {
    const filterSet = new Set<string>();

    for (const ebt of eventBetTypes) {
      if (!ebt.betTypeGroup || !ebt.eventBetTypeItems?.length) {
        continue;
      }

      for (const key in BetTypeGroup) {
        if (hasFlag(ebt.betTypeGroup, +key)) {
          filterSet.add(BetTypeGroup[ebt.betTypeGroup]);
        }
      }
    }

    const filters: string[] = Array.from(filterSet);

    return entryPointId === 101 ? this.reorderFilters(filters) : filters;
  }

  /**
   * Filters grouped bet types by the active filter and optional sub-filter.
   */
  filterGroups(
    groups: EventBetTypeGroupedByBetType[],
    activeFilter: BetTypeGroup,
    isBetBuilderToggled: boolean
  ): EventBetTypeGroupedByBetType[] {
    if (!activeFilter && !isBetBuilderToggled) {
      return groups;
    }

    return groups.filter(
      (eventBetTypeGroupedByBetType: EventBetTypeGroupedByBetType) =>
        (!activeFilter || hasFlag(eventBetTypeGroupedByBetType.betTypeGroup, activeFilter)) &&
        (!isBetBuilderToggled || eventBetTypeGroupedByBetType.allowBetBuilder)
    );
  }

  /**
   * Returns bet-type IDs whose items carry a homeOrAway value,
   * i.e. groups that should render with the team-based template.
   */
  getBetTypeIdsWithHomeOrAway(groups: EventBetTypeGroupedByBetType[]): Set<number> {
    const ids: number[] = groups
      .filter((group: EventBetTypeGroupedByBetType) =>
        group.eventBetTypes.some((ebt: EventBetType) => ebt.eventBetTypeItems?.some(item => item.homeOrAway != null))
      )
      .map((group: EventBetTypeGroupedByBetType) => group.betTypeId);

    return new Set(ids);
  }

  findInsertionIndex(groups: EventBetTypeGroupedByBetType[], priority: number): number {
    return groups.findIndex((group: EventBetTypeGroupedByBetType) => group.displayPriority > priority);
  }

  isEventBetTypeItemToggleable(
    eventBetType: EventBetType,
    eventBetTypeItem: SelectableEventBetTypeItem,
    isLoadingOdds: boolean
  ): boolean {
    const MIN_ODDS: number = 1;

    return (
      (eventBetTypeItem.odds ?? 0) > MIN_ODDS &&
      !!eventBetType.active &&
      !!eventBetType.bettingAllowed &&
      !!eventBetTypeItem.active &&
      !!eventBetTypeItem.bettingAllowed &&
      !eventBetTypeItem.completionDisabled &&
      !isLoadingOdds
    );
  }

  private findGroupIndex(groups: EventBetTypeGroupedByBetType[], ebt: EventBetType): number {
    if (ebt.isManual) {
      return -1;
    }

    return groups.findIndex((group: EventBetTypeGroupedByBetType) => {
      if (group.betTypeId !== ebt.betTypeId) {
        return false;
      }
      return (
        !EventBetTypeGroupingService.CONTEXT_GROUPED_BET_TYPE_IDS.has(ebt.betTypeId) ||
        group.betTypeContext === ebt.betTypeContext
      );
    });
  }

  private reorderFilters(filters: string[]): string[] {
    return filters.slice().sort((a, b) => {
      const indexA: number = EventBetTypeGroupingService.FILTER_ORDER_SOCCER.indexOf(a);
      const indexB: number = EventBetTypeGroupingService.FILTER_ORDER_SOCCER.indexOf(b);

      // Both known → compare by defined order
      if (indexA !== -1 && indexB !== -1) {
        return indexA - indexB;
      }

      // Only one known → it comes first
      if (indexA !== -1) {
        return -1;
      }
      if (indexB !== -1) {
        return 1;
      }

      // Neither known → preserve original order (stable sort)
      return 0;
    });
  }
}
