import { Component, ChangeDetectionStrategy, Input, OnChanges } from '@angular/core';
import { BetCategoryType } from '@honoregaming/types';

const ICON_BY_ID: Record<number, string> = {
  1: 'hg-horse',
  2: 'hg-horse',
  3: 'hg-sports',
  6: 'hg-sports-pool',
  4: 'hg-draw-games',
  7: 'hg-draw-games',
  5: 'hg-virtualgames',
  8: 'hg-casino'
};

const ICON_BY_TYPE: Partial<Record<BetCategoryType, string>> = {
  [BetCategoryType.HorseRacingMutualInternationalPool]: 'hg-horse',
  [BetCategoryType.HorseRacingMutualOperatorPool]: 'hg-horse',
  [BetCategoryType.SportsFixedOdds]: 'hg-sports',
  [BetCategoryType.DrawGame]: 'hg-draw-games',
  [BetCategoryType.VirtualFixedOdds]: 'hg-virtualgames',
  [BetCategoryType.SportsPool]: 'hg-sports-pool',
  [BetCategoryType.InstantGame]: 'hg-casino'
};

@Component({
  selector: 'hg-bet-category-icon',
  templateUrl: './bet-category-icon.component.html',
  styleUrls: ['./bet-category-icon.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class BetCategoryIconComponent implements OnChanges {
  @Input() betCategoryId?: number;
  @Input() betCategoryType?: BetCategoryType;

  icon?: string;

  ngOnChanges(): void {
    this.icon = this.betCategoryId == null ? ICON_BY_TYPE[this.betCategoryType] : ICON_BY_ID[this.betCategoryId];
  }
}
