import { AfterViewInit, Directive, ElementRef } from '@angular/core';

@Directive({
  // eslint-disable-next-line @angular-eslint/directive-selector
  selector: 'img'
})
export class ImageAltDirective implements AfterViewInit {
  constructor(private element: ElementRef) {}

  ngAfterViewInit(): void {
    if (!this.element.nativeElement.hasAttribute('alt')) {
      const alt = ('Image ' + this.element.nativeElement.src.split('/').pop()?.split('.')[0]).trim();
      this.element.nativeElement.alt = alt;
    }
  }
}
