export interface AppConfiguration {
  ready: Promise<unknown>;
  appId: string;
  operatorKey: string;
  flavor: string;
  hideHorseRacing: boolean;
}

export let appConfiguration = {} as AppConfiguration;

export let appConfigurationResolve: (value?: void | PromiseLike<void>) => void;

appConfiguration.ready = new Promise(res => {
  appConfigurationResolve = res;
});
