import { Injectable, Optional } from '@angular/core';
import { CookieAttributes, getJSON, remove, set } from 'js-cookie';
import { Inject, PLATFORM_ID } from '@angular/core';
import { isPlatformBrowser } from '@angular/common';
import { REQUEST } from '@nguniversal/express-engine/tokens';

@Injectable({ providedIn: 'root' })
export class CookieStorageService {
  private localStore: { [key: string]: any } = {};

  constructor(
    @Inject(PLATFORM_ID) private platformId,
    @Optional()
    @Inject(REQUEST)
    private req: any
  ) {}

  getItem(name: string) {
    if (isPlatformBrowser(this.platformId)) {
      return getJSON(name) || this.localStore[name];
    } else {
      if (this.localStore[name]) {
        return this.localStore[name];
      }

      try {
        return JSON.parse(this.req.cookies[name]);
      } catch (err) {
        let cookie;
        if (this.req && this.req.cookies) {
          cookie = this.req.cookies[name];
        }
        return cookie;
      }
    }
  }

  setItem(name: string, value: any, options?: CookieAttributes) {
    if (isPlatformBrowser(this.platformId)) {
      set(name, value, options);
    }
    this.localStore[name] = value;
  }

  removeItem(name, options?: CookieAttributes) {
    if (isPlatformBrowser(this.platformId)) {
      remove(name, options);
    } else {
      delete this.localStore[name];
    }
  }
}
