import { Component, ChangeDetectionStrategy, Input, OnChanges } from '@angular/core';
import {
  RouletteItem,
  RouletteItemColor,
  RouletteItemColorGroupInsa,
  RouletteItemColorInsa
} from '@honoregaming/types';
import { rouletteItemColorGroups, rouletteItemColors } from '@honoregaming/ui';

@Component({
  selector: 'hg-roulette-result',
  templateUrl: './roulette-result.component.html',
  styleUrls: ['./roulette-result.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class RouletteResultComponent implements OnChanges {
  @Input()
  result: any;

  @Input()
  insaGames: boolean = false;

  colors = rouletteItemColors;
  colorGroups = rouletteItemColorGroups;

  serializedResult: RouletteItem;

  constructor() {}

  ngOnChanges() {
    this.serializedResult = JSON.parse(this.result);
    if (this.insaGames) {
      this.serializedResult.color =
        RouletteItemColor[RouletteItemColorInsa[this.serializedResult.color || this.serializedResult[0].color]];
      this.serializedResult.colorGroup =
        RouletteItemColorGroupInsa[
          RouletteItemColorGroupInsa[this.serializedResult.colorGroup || this.serializedResult[0].colorGroup]
        ];
    }
  }
}
