import { ITelemetryService } from './telemetry-service.model';
import { Injectable, Inject, PLATFORM_ID } from '@angular/core';
import { customerOperatorConfigurationToken, CustomerOperatorConfiguration } from '../../models';
import { DOCUMENT, isPlatformBrowser } from '@angular/common';

@Injectable()
export class ExoClickPixelTelemetryService implements ITelemetryService {
  constructor(
    @Inject(customerOperatorConfigurationToken) operatorConfig: CustomerOperatorConfiguration,
    @Inject(DOCUMENT) document,
    @Inject(PLATFORM_ID) private platformId
  ) {
    if (isPlatformBrowser(this.platformId)) {
      const script = document.createElement('script');
      script.src = 'https://a.exoclick.com/tag_gen.js';
      script.setAttribute('type', 'application/javascript');
      script.setAttribute('data-goal', `${operatorConfig.telemetryConfiguration.exoclick.trackingId}`);
      document.body.appendChild(script);
    }
  }

  trackPageView(_name: string, _path: string): void {}

  trackEvent(_name: string, _properties: any): void {}
}
