import { Component, ChangeDetectionStrategy, Input, EventEmitter, Inject, Output, OnInit } from '@angular/core';
import { operatorConfigurationToken, OperatorConfiguration } from '@honoregaming/configuration';
import { SelectedSportsPoolGameItem } from '@honoregaming/types';
import { BetLine, BetLineAmount } from '../../../models';

interface MatchBetGroup {
  id: number;
  eventName: string;
  shortNames: string;
}

const SHORTNAME_ORDER: string[] = ['1', 'X', '2'];

@Component({
  selector: 'hg-sports-pool-bet-line',
  templateUrl: './sports-pool-bet-line.component.html',
  styleUrls: ['./sports-pool-bet-line.component.scss', '../bet-line-content.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class SportsPoolBetLineComponent implements OnInit {
  @Input() betLine!: BetLine;
  @Input() amount!: BetLineAmount;

  @Output() remove = new EventEmitter<void>();
  @Output() betLineChange = new EventEmitter<BetLine>();

  currency: string = this.operatorConfiguration.currency.symbol;
  betsGroupedByMatch: MatchBetGroup[] = [];
  showDetails: boolean = false;

  constructor(@Inject(operatorConfigurationToken) private readonly operatorConfiguration: OperatorConfiguration) {}

  ngOnInit(): void {
    this.betsGroupedByMatch = this.groupBetsByMatch(this.betLine.selectedSportsPoolGameItems);
  }

  onRemove(): void {
    this.remove.emit();
  }

  toggleDisplayDetails(): void {
    this.showDetails = !this.showDetails;
  }

  trackByEventName(_index: number, group: MatchBetGroup): string {
    return group.eventName;
  }

  private groupBetsByMatch(items: SelectedSportsPoolGameItem[]): MatchBetGroup[] {
    const grouped: Record<number, { eventName: string; shortNames: Set<string> }> = {};

    for (const { eventId, eventName, shortName } of items) {
      grouped[eventId] ??= { eventName, shortNames: new Set() };
      grouped[eventId].shortNames.add(shortName);
    }

    return Object.entries(grouped)
      .sort(([firstKey]: [string, unknown], [secondKey]: [string, unknown]) => +firstKey - +secondKey)
      .map(([key, { eventName, shortNames }]: [string, { eventName: string; shortNames: Set<string> }]) => ({
        id: +key,
        eventName,
        shortNames: SHORTNAME_ORDER.filter((name: string) => shortNames.has(name)).join('/')
      }));
  }
}
