import { Injectable, Inject } from '@angular/core';
import { CanLoad, Route } from '@angular/router';
import { operatorConfigurationToken, OperatorConfiguration } from '@honoregaming/configuration';
import { BetCategoryType } from '@honoregaming/types';
import { BetCategoriesError } from '../errors';

@Injectable()
export class BetCategoriesGuard implements CanLoad {
  constructor(@Inject(operatorConfigurationToken) private operatorConfiguration: OperatorConfiguration) {}
  canLoad(route: Route): boolean {
    const routeBetCategories = route.data ? (route.data.betCategories as BetCategoryType[]) : null;

    if (routeBetCategories == null) {
      throw new BetCategoriesError('BetCategories must be defined for this route');
    }

    if (!this.operatorConfiguration.betCategories.some(x => routeBetCategories.indexOf(x) !== -1)) {
      throw new BetCategoriesError('UnAuthorized route betCategories');
    }

    return true;
  }
}
