import { NgModule } from '@angular/core';
import { Routes, RouterModule } from '@angular/router';
import { BetHistoryComponent } from './containers/bet-history/bet-history.component';
import { DepositComponent } from './containers/deposit/deposit.component';
import { InformationsComponent } from './containers/informations/informations.component';
import { WithdrawalComponent } from './containers/withdrawal/withdrawal.component';
import { PaymentInfoComponent } from './containers/payment-info/payment-info.component';
import { AccountValidationComponent } from './containers/account-validation/account-validation.component';
import { RegistrationComponent } from './containers/registration/registration.component';
import { OperationsHistoryComponent } from './containers/operations-history/operations-history.component';
import { LostPasswordComponent } from './containers/lost-password/lost-password.component';
import { Step1Component } from './containers/registration/step1/step1.component';
import { Step2Component } from './containers/registration/step2/step2.component';
import { InstantGameHistoryComponent } from './containers/instant-game-history/instant-game-history.component';
import { DepositListComponent } from './containers/deposit-list/deposit-list.component';
import { WithdrawalListComponent } from './containers/withdrawal-list/withdrawal-list.component';
import { WithdrawProviderLoaderComponent } from './components/withdraw-provider-loader/withdraw-provider-loader.component';
import { TransactionCancelComponent } from './containers/transaction-cancel/transaction-cancel.component';
import { TransactionFailComponent } from './containers/transaction-fail/transaction-fail.component';
import { TransactionSuccessComponent } from './containers/transaction-success/transaction-success.component';
import { LayoutComponent } from './components/layout/layout.component';
import { AccountNavigationComponent } from './components/account-navigation/account-navigation.component';
import { ReferralComponent } from './containers/referral/referral.component';
import { LoyaltyComponent } from './containers/loyalty/loyalty.component';
import { BetCategoriesGuard, FeaturesGuard } from '@honoregaming/core';
import { DirectMessageComponent } from './containers/direct-message/direct-message.component';
import { DirectMessageGuard } from 'projects/customer/hg-core/src/lib/guards/direct-message.guard';
import { DepositProviderLoaderComponent } from './components/deposit-provider-loader/deposit-provider-loader.component';
import { ResponsibleGamblingComponent } from './containers/responsible-gambling/responsible-gambling.component';
import { AccountUnlockComponent } from './containers/account-unlock/account-unlock.component';
import { PartnersComponent } from './containers/partners/partners.component';
import { ResetPasswordComponent } from './containers/reset-password/reset-password.component';
import { AccountKYCValidatedComponent } from './containers/account-kyc-validated/account-kyc-validated.component';
import { ContentPageComponent } from 'projects/customer/hg-about/src/lib/containers/content-page/content-page.component';
import { FreebetCouponsComponent } from './containers/freebet-coupons/freebet-coupons.component';
import { SimulateBetsHistoryComponent } from './containers/simulate-bets-history/simulate-bets-history.component';
import { SimulateModeGuard } from 'projects/customer/hg-core/src/lib/guards/simulate-mode.guard';
import { SportsPoolBetsHistoryComponent } from './containers/sports-pool-bets-history/sports-pool-bets-history.component';
import { SportsPoolBetComponent } from './containers/sports-pool-bet/sports-pool-bet.component';
import { BetCategoryType } from '@honoregaming/types';

const routes: Routes = [
  {
    path: '',
    component: LayoutComponent,
    children: [
      { path: '', component: AccountNavigationComponent },
      {
        path: 'deposit',
        component: DepositComponent,
        children: [
          { path: '', component: DepositListComponent },
          { path: ':provider', component: DepositProviderLoaderComponent }
        ]
      },
      {
        path: 'loyalty',
        component: LoyaltyComponent,
        canActivate: [FeaturesGuard],
        data: { featureName: 'Loyalty' }
      },
      {
        path: 'loyalty/:path',
        component: ContentPageComponent,
        canActivate: [FeaturesGuard],
        data: { featureName: 'Loyalty' }
      },
      { path: 'informations', component: InformationsComponent },
      { path: 'reset-password', component: ResetPasswordComponent },
      { path: 'referral', component: ReferralComponent },
      { path: 'operations-history', component: OperationsHistoryComponent },
      {
        path: 'withdrawal',
        component: WithdrawalComponent,
        children: [
          { path: '', component: WithdrawalListComponent },
          { path: ':provider', component: WithdrawProviderLoaderComponent }
        ]
      },
      { path: 'payment-info', component: PaymentInfoComponent },
      {
        path: 'history',
        component: BetHistoryComponent,
        canActivate: [FeaturesGuard],
        data: { featureName: 'BetHistory' }
      },
      {
        path: 'instant-games-history',
        component: InstantGameHistoryComponent,
        canActivate: [FeaturesGuard],
        data: { featureName: 'BetHistory' }
      },
      {
        path: 'simulate-bets-history',
        component: SimulateBetsHistoryComponent,
        canActivate: [SimulateModeGuard, FeaturesGuard],
        data: { featureName: 'BetHistory' }
      },
      {
        path: 'sportspool-history',
        component: SportsPoolBetsHistoryComponent,
        canActivate: [FeaturesGuard],
        canLoad: [BetCategoriesGuard],
        data: { featureName: 'BetHistory', betCategories: [BetCategoryType.SportsPool] }
      },
      {
        path: 'sportspool-history/:betId',
        component: SportsPoolBetComponent,
        canActivate: [FeaturesGuard],
        canLoad: [BetCategoriesGuard],
        data: { featureName: 'BetHistory', betCategories: [BetCategoryType.SportsPool] }
      },
      { path: 'freebets-coupons', component: FreebetCouponsComponent },
      { path: 'account-validation', component: AccountValidationComponent },
      {
        path: 'direct-message',
        component: DirectMessageComponent,
        canActivate: [FeaturesGuard, DirectMessageGuard],
        data: { featureName: 'DirectMessage' }
      },
      {
        path: 'responsible-gambling',
        component: ResponsibleGamblingComponent
      },
      {
        path: 'partners',
        component: PartnersComponent,
        canActivate: [FeaturesGuard],
        data: { featureName: 'Partner' }
      },
      {
        path: 'kyc-validated',
        component: AccountKYCValidatedComponent,
        canActivate: [FeaturesGuard],
        data: { featureName: 'KYC' }
      }
    ]
  },
  {
    path: 'unlock',
    component: AccountUnlockComponent,
    canActivate: [FeaturesGuard],
    data: { featureName: 'CustomerAccountLockManagement', 'sidebar-content': 'none' }
  },
  {
    path: 'registration',
    component: RegistrationComponent,
    data: { allowAnonymous: true, denyAuthenticated: true, 'sidebar-content': 'none' },
    children: [
      { path: '', redirectTo: 'step1', pathMatch: '' },
      { path: 'step1', component: Step1Component, data: { step: 1, allowAnonymous: true, denyAuthenticated: true } },
      { path: 'step2', component: Step2Component, data: { step: 2, allowAnonymous: true, denyAuthenticated: true } }
    ]
  },
  {
    path: 'lost-password',
    component: LostPasswordComponent,
    data: { allowAnonymous: true, denyAuthenticated: true, 'sidebar-content': 'none' }
  },
  {
    path: 'transaction-cancel',
    component: TransactionCancelComponent,
    data: { 'sidebar-content': 'none' }
  },
  {
    path: 'transaction-fail',
    component: TransactionFailComponent,
    data: { 'sidebar-content': 'none' }
  },
  {
    path: 'transaction-success',
    component: TransactionSuccessComponent,
    data: { 'sidebar-content': 'none' }
  }
];

@NgModule({
  imports: [RouterModule.forChild(routes)],
  exports: [RouterModule]
})
export class HgAccountRoutingModule {}
