import { DOCUMENT } from '@angular/common';
import { Inject, Injectable } from '@angular/core';
import { globalConfiguration, OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';
import { LocalStorageService } from '@honoregaming/core';

@Injectable({ providedIn: 'root' })
export class ThemeSwitcherService {
  constructor(
    private readonly localStorageService: LocalStorageService,
    @Inject(DOCUMENT) private readonly document: Document,
    @Inject(operatorConfigurationToken) private readonly operatorConfiguration: OperatorConfiguration
  ) {}

  // commercialCode is only passed when the operator configuration is not loaded (e.g. geo-blocked customer).
  public init(commercialCode?: string): void {
    this.loadStyle(this.resolveThemeKey(commercialCode ?? this.operatorConfiguration.commercialCode));
  }

  loadStyle(operatorKey: string): void {
    const head: HTMLHeadElement = this.document.getElementsByTagName('head')[0];

    const themeLink = this.document.getElementById('operator-theme') as HTMLLinkElement;
    if (themeLink) {
      themeLink.href = `${operatorKey}.css`;
    } else {
      const style: HTMLLinkElement = this.document.createElement('link');
      style.id = 'operator-theme';
      style.rel = 'stylesheet';
      style.href = `${operatorKey}.css`;

      head.appendChild(style);
    }

    this.localStorageService.setItem('theme-key', operatorKey);
  }

  private resolveThemeKey(commercialCode: string): string {
    if (globalConfiguration.showThemesSelector !== true) {
      return commercialCode;
    }

    return this.localStorageService.getItem('theme-key') || 'UY';
  }
}
