import {
  Component,
  ChangeDetectionStrategy,
  Input,
  Inject,
  ElementRef,
  ChangeDetectorRef,
  OnChanges,
  Output,
  EventEmitter
} from '@angular/core';
import {
  NG_VALUE_ACCESSOR,
  ControlValueAccessor,
  NG_VALIDATORS,
  Validator,
  AbstractControl,
  ValidationErrors
} from '@angular/forms';
import { LoginPolicy } from '@honoregaming/types';
import { DOCUMENT } from '@angular/common';
import { SessionStorageService } from '@honoregaming/core';

const currentPolicyStorageKey = 'policy_current';

const gambiaPrefix = '+220';
const gambiaMissingDigitsByFirstDigit: { [firstDigit: string]: string } = {
  2: '87',
  4: '87',
  7: '87',
  3: '83',
  5: '83',
  9: '89',
  6: '86',
  8: '86'
};

@Component({
  selector: 'hg-login-input',
  templateUrl: './login-input.component.html',
  styleUrls: ['./login-input.component.scss'],
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: LoginInputComponent,
      multi: true
    },
    {
      provide: NG_VALIDATORS,
      useExisting: LoginInputComponent,
      multi: true
    }
  ],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class LoginInputComponent implements ControlValueAccessor, Validator, OnChanges {
  @Input()
  loginPolicies: LoginPolicy[];
  @Input()
  placeholder: string;
  @Output()
  loginChange = new EventEmitter<string>();

  internalPolicies: LoginPolicy[];

  innerValue = null;
  opened = false;
  currentPolicy: LoginPolicy;

  private changed = new Array<(v: string) => void>();
  private touched = new Array<() => void>();
  private lastValue;
  private clickListenerFunction: any;
  disabled: boolean;

  constructor(
    @Inject(DOCUMENT) private document: any,
    private element: ElementRef,
    private cdRef: ChangeDetectorRef,
    private sessionStorage: SessionStorageService
  ) {}

  ngOnChanges(): void {
    if (this.loginPolicies) {
      this.internalPolicies = [...this.loginPolicies];

      const currentPolicyPrefix = this.sessionStorage.getItem(currentPolicyStorageKey);
      if (this.internalPolicies && this.internalPolicies[0]) {
        let selectedPolicy = this.internalPolicies[0];

        if (currentPolicyPrefix) {
          const internalPolicy = this.internalPolicies.find(p => p.prefix === currentPolicyPrefix);
          if (internalPolicy) {
            selectedPolicy = internalPolicy;
          }
        }

        this.changePolicy(selectedPolicy);
      }
    }
  }

  get value(): string {
    if (this.currentPolicy) {
      if (this.currentPolicy?.mode === 'External') {
        return this.innerValue ? this.innerValue : '';
      }

      if (this.currentPolicy.prefix) {
        return this.currentPolicy.prefix + this.completeNumber(this.currentPolicy.prefix, this.innerValue);
      }
    }

    return this.innerValue;
  }

  private completeNumber(prefix: string, number: string | null): string {
    if (!number) {
      return '';
    }

    if (prefix === gambiaPrefix && /^\d{7}$/.test(number)) {
      const missingDigits: string = gambiaMissingDigitsByFirstDigit[number.charAt(0)];
      if (missingDigits) {
        return missingDigits + number;
      }
    }

    return number;
  }

  set value(value: string) {
    if (this.loginChange) {
      this.loginChange.emit(value);
    }

    if (this.currentPolicy && this.currentPolicy.prefix) {
      if (value && value.toString().indexOf(this.currentPolicy.prefix) === 0) {
        value = value.toString().trim().substring(this.currentPolicy.prefix.length, value.length);
      }
    }

    this.innerValue = value?.trim();
  }

  writeValue(value: any, fromInner = false): void {
    this.value = value;
    if (this.currentPolicy && this.currentPolicy.prefix) {
      if (this.innerValue && this.innerValue.toString().indexOf(this.currentPolicy.prefix) === 0) {
        this.innerValue = this.innerValue
          .toString()
          .substring(this.currentPolicy.prefix.length, this.innerValue.length);
      }
    }

    if (!fromInner && this.lastValue !== this.value) {
      this.lastValue = this.value;
    }

    this.cdRef.markForCheck();
  }

  innerWriteValue(value: any) {
    if (this.innerValue !== undefined) {
      this.writeValue(value, true);

      if (this.lastValue !== this.value) {
        this.changed.forEach(f => f(this.value));
        this.lastValue = this.value;
      }
    }
  }

  registerOnChange(fn: any): void {
    this.changed.push(fn);
  }

  registerOnTouched(fn: any): void {
    this.touched.push(fn);
  }

  touch() {
    this.touched.forEach(f => f());
  }

  setDisabledState(isDisabled: boolean) {
    this.disabled = isDisabled;
    this.cdRef.markForCheck();
  }

  validate(control: AbstractControl): ValidationErrors {
    if (this.currentPolicy && this.currentPolicy.pattern) {
      const regexWithZeroAllowed = new RegExp(
        `${this.currentPolicy.pattern.replace(`^\\${this.currentPolicy.prefix}`, `^\\${this.currentPolicy.prefix}0?`)}`
      );
      const regex = new RegExp(this.currentPolicy.pattern);
      const isValidWithZeroAllowed = regexWithZeroAllowed.test(control.value);
      const isValid = regex.test(control.value);

      if (isValidWithZeroAllowed && !isValid) {
        //trigger ngModelChange without updating the input value
        this.changed.forEach(f => f(this.value.replace(`${this.currentPolicy.prefix}0`, this.currentPolicy.prefix)));
        return;
      }

      if (!isValid) {
        return { valid: false, loginPolicy: 'REGEXFAILED' };
      }
    }

    return null;
  }

  registerOnValidatorChange?(_fn: () => void): void {}

  togglePoliciesSelector() {
    this.opened = !this.opened;
    if (this.opened) {
      this.clickListenerFunction = this.closeSelectorOnFocusOut.bind(this);
      setTimeout(() => this.document.addEventListener('click', this.clickListenerFunction), 0);
    }
  }

  changePolicy(policy: LoginPolicy) {
    this.opened = false;
    this.currentPolicy = policy;
    this.sessionStorage.setItem(currentPolicyStorageKey, this.currentPolicy.prefix);

    const index = this.internalPolicies.indexOf(policy);
    this.internalPolicies.splice(0, 0, this.internalPolicies.splice(index, 1)[0]);
    this.innerWriteValue(this.value);
  }

  private closeSelectorOnFocusOut(ev: MouseEvent) {
    if (!(<Node>this.element.nativeElement).contains(<Node>ev.target)) {
      this.opened = false;
      this.document.removeEventListener('click', this.clickListenerFunction);
      this.cdRef.markForCheck();
    }
  }
}
