import {
  Component,
  OnChanges,
  ChangeDetectionStrategy,
  Input,
  ViewContainerRef,
  Injector,
  HostListener,
  OnInit,
  Inject,
  Output,
  EventEmitter,
  PLATFORM_ID
} from '@angular/core';
import { DOCUMENT, isPlatformServer } from '@angular/common';
import { addScopedStyle } from '../../helper';
import { ITemplateService, templateServiceToken } from '../../services/template.service';
import { registeredTemplates } from '../../template.registration';
import { take, takeUntil } from 'rxjs/operators';
import { MessageService } from '@honoregaming/ui';
import { Router } from '@angular/router';
import { I18nService } from '@honoregaming/i18n';
import { DestroySubject } from '@honoregaming/core';

@Component({
  selector: 'hg-raw-template',
  template: ``,
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class RawTemplateComponent extends DestroySubject implements OnInit, OnChanges {
  document: Document;
  currentLanguageCode: string = this.i18nService.currentLanguageCode;

  constructor(
    private viewContainerRef: ViewContainerRef,
    injector: Injector,
    @Inject(templateServiceToken) private templateService: ITemplateService,
    private messageService: MessageService,
    private router: Router,
    private i18nService: I18nService,
    @Inject(PLATFORM_ID) private plateformId
  ) {
    super();

    this.document = injector.get(DOCUMENT);
  }

  @Input()
  html: string | { [key: string]: string };

  @Input()
  css: string;

  @Output() contentLoaded: EventEmitter<void> = new EventEmitter();

  ngOnInit() {
    this.ngOnChanges();

    this.i18nService.languageChanged$.pipe(takeUntil(this.destroy$)).subscribe(l => {
      if (this.html && this.currentLanguageCode !== l) {
        this.currentLanguageCode = l;

        const element = this.addElement();
        addScopedStyle(this.css, this.document, element, isPlatformServer(this.plateformId));
      }
    });
  }

  ngOnChanges() {
    if (this.html) {
      const element = this.addElement();
      addScopedStyle(this.css, this.document, element, isPlatformServer(this.plateformId));

      Array.from(element.querySelectorAll<HTMLImageElement>('img[delayed-bgcolor]')).forEach(elem => {
        elem.onload = _ev => {
          elem.parentElement.style.setProperty('--bgcolor', elem.getAttribute('delayed-bgcolor'));
        };
      });
    }

    this.contentLoaded.emit();
  }

  private addElement(): HTMLElement {
    const element = this.viewContainerRef.element.nativeElement as HTMLElement;
    if (typeof this.html === 'string') {
      element.innerHTML = this.addAttributesToImages(this.html);
    } else {
      element.innerHTML = this.addAttributesToImages(this.html[this.i18nService.currentLanguageCode]);
    }

    return element;
  }

  @HostListener('click', ['$event'])
  public onClick(event: any) {
    const target = event.target as HTMLElement;
    let maxDepth = 5;

    const checkNodeAndParents = (localTarget: HTMLElement) => {
      if (localTarget.tagName === 'A') {
        const link = localTarget.getAttribute('href');
        if (localTarget.hasAttribute('local') || (!link.startsWith('http') && !link.startsWith('//'))) {
          this.router.navigate([link]);
          event.preventDefault();
        }
      } else if (localTarget.tagName === 'HG-POPIN') {
        this.handleClickOnPopinElement(localTarget);
        event.preventDefault();
      } else if (--maxDepth) {
        checkNodeAndParents(localTarget.parentElement);
      }
    };
    checkNodeAndParents(target);
  }

  private handleClickOnPopinElement(element: HTMLElement) {
    this.templateService
      .getTemplatesForAnchor(element.getAttribute('anchor'))
      .pipe(take(1))
      .subscribe(a => {
        if (!!a && a.length) {
          this.messageService.sendComponentMessage(registeredTemplates[a[0].type], a[0].inputs);
        }
      });
  }

  addAttributesToImages(html: string): string {
    const parser = new DOMParser();
    const document = parser.parseFromString(html, 'text/html');

    const images = document.querySelectorAll('img');
    images.forEach(img => {
      if (!img.hasAttribute('alt')) {
        const src = img.getAttribute('src') || '';
        const fileName = ('Image ' + src.split('/').pop()?.split('.')[0]).trim();

        img.setAttribute('alt', fileName);
      }

      if (!img.hasAttribute('loading')) {
        img.setAttribute('loading', 'lazy');
      }
    });

    return document.body.innerHTML;
  }
}
