import {
  Component,
  OnInit,
  ChangeDetectionStrategy,
  OnDestroy,
  ChangeDetectorRef,
  ViewChild,
  HostBinding,
  Output,
  EventEmitter
} from '@angular/core';
import { takeUntil } from 'rxjs/operators';
import { BetSlipService } from '../../services/bet-slip.service';
import { AnimateDirective } from '@honoregaming/ui';
import { DestroySubject } from '@honoregaming/core';
import { combineLatest } from 'rxjs';
import { BetCategoryType, BetSlipMode } from '@honoregaming/types';
import { BetLine, BetSlipLinesInfo } from '../../models';

@Component({
  selector: 'hg-bet-slip-icon',
  templateUrl: './bet-slip-icon.component.html',
  styleUrls: ['./bet-slip-icon.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class BetSlipIconComponent extends DestroySubject implements OnInit, OnDestroy {
  @ViewChild(AnimateDirective)
  counter: AnimateDirective;
  betLinesNumber: number;
  totalOdds: string;
  showTotalOdds: boolean;

  @Output() hasBetLines = new EventEmitter<boolean>();

  @HostBinding('class')
  get currentBetCategoryName() {
    return this.currentBetCategory?.toLocaleLowerCase();
  }
  private currentBetCategory: BetCategoryType;

  constructor(private betSlipService: BetSlipService, private cdRef: ChangeDetectorRef) {
    super();
  }

  ngOnInit() {
    combineLatest([this.betSlipService.$lines, this.betSlipService.$mode])
      .pipe(takeUntil(this.destroy$))
      .subscribe(([betSlipLinesInfo, betSlipMode]: [BetSlipLinesInfo, BetSlipMode]) => {
        if (betSlipLinesInfo.instantGameTransactions.length > 0) {
          this.betLinesNumber = betSlipLinesInfo.instantGameTransactions.length;
        } else {
          this.betLinesNumber = betSlipLinesInfo.lines.length;
          if (betSlipLinesInfo.lines.every((betLine: BetLine) => betLine.odds)) {
            this.totalOdds = betSlipLinesInfo.lines
              .reduce((sum: number, betLine: BetLine) => sum * betLine.odds, 1)
              .toFixed(2);
            this.showTotalOdds =
              (betSlipMode === BetSlipMode.Simple && this.betLinesNumber === 1) ||
              (betSlipMode === BetSlipMode.Multiple &&
                (this.betLinesNumber > 1 || (this.betLinesNumber == 1 && betSlipLinesInfo.lines[0].isBetBuilder)) &&
                this.totalOdds.length < 7);
          } else {
            this.showTotalOdds = false;
          }
        }

        this.cdRef.markForCheck();

        if (this.counter) {
          this.counter.animate('new');
        }

        this.hasBetLines.emit(this.betLinesNumber > 0);
      });

    this.betSlipService.$configuration
      .pipe(takeUntil(this.destroy$))
      .subscribe(c => (this.currentBetCategory = c.betCategory));
  }
}
