import {
  Component,
  ChangeDetectionStrategy,
  Input,
  Output,
  EventEmitter,
  Inject,
  OnInit,
  ChangeDetectorRef
} from '@angular/core';
import { Router } from '@angular/router';
import { takeUntil } from 'rxjs/operators';
import { OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';
import { BroadcastingService, DestroySubject, LocalStorageService } from '@honoregaming/core';
import { CustomerDirectMessageConfiguration } from '@honoregaming/customer-core';
import { DirectMessageWidgetState, DirectMessageWidgetView } from '../../enums/direct-message-widget-view.enum';
import { DirectMessageTrackingService } from '../../services/direct-message-tracking.service';

@Component({
  selector: 'hg-direct-message-widget',
  templateUrl: './direct-message-widget.component.html',
  styleUrls: ['./direct-message-widget.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class DirectMessageWidgetComponent extends DestroySubject implements OnInit {
  @Input() newDirectMessagesCount?: number;
  @Input() configuration!: CustomerDirectMessageConfiguration;

  @Output() navigateEvent = new EventEmitter<void>();
  @Output() closeEvent = new EventEmitter<void>();

  widgetView: DirectMessageWidgetView = DirectMessageWidgetView.Button;

  DirectMessageWidgetView = DirectMessageWidgetView;

  readonly LOCAL_STORAGE_KEY: string = 'direct_message:widget:state';

  constructor(
    private readonly router: Router,
    private readonly localStorage: LocalStorageService,
    private readonly broadcastingService: BroadcastingService,
    private readonly directMessageTrackingService: DirectMessageTrackingService,
    private readonly cdRef: ChangeDetectorRef,
    @Inject(operatorConfigurationToken) public readonly operatorConfiguration: OperatorConfiguration
  ) {
    super();
  }

  ngOnInit(): void {
    this.initializeWidgetView();
    this.listenForOpenDirectMessageWindow();
  }

  navigate(): void {
    this.navigateEvent.emit();
    if (this.operatorConfiguration.directMessageConfiguration.onPageChatBubble) {
      this.openWidgetWindow();
    } else {
      this.navigateToDirectMessagePage();
    }
  }

  hide(): void {
    this.localStorage.setItem(this.LOCAL_STORAGE_KEY, DirectMessageWidgetState.Close);
    this.closeEvent.emit();
  }

  reduceWindow(): void {
    this.widgetView = DirectMessageWidgetView.Button;
    this.localStorage.setItem(this.LOCAL_STORAGE_KEY, DirectMessageWidgetState.Reduce);
    this.directMessageTrackingService.trackMinimize();
  }

  private initializeWidgetView(): void {
    const directMessageWidgetState: DirectMessageWidgetState = this.localStorage.getItem(this.LOCAL_STORAGE_KEY);
    if (directMessageWidgetState === DirectMessageWidgetState.Open) {
      this.widgetView = DirectMessageWidgetView.Window;
    }
  }

  private openWidgetWindow(): void {
    this.widgetView = DirectMessageWidgetView.Window;
    this.localStorage.setItem(this.LOCAL_STORAGE_KEY, DirectMessageWidgetState.Open);
  }

  private navigateToDirectMessagePage(): void {
    this.router.navigate(['/myaccount/direct-message'], { replaceUrl: true });
  }

  private listenForOpenDirectMessageWindow(): void {
    this.broadcastingService
      .register('open-direct-message-window')
      .pipe(takeUntil(this.destroy$))
      .subscribe(() => {
        this.widgetView = DirectMessageWidgetView.Window;
        this.cdRef.markForCheck();
      });
  }
}
