import { Pipe, PipeTransform } from '@angular/core';
import { BetLine } from '@honoregaming/betslip';

@Pipe({
  name: 'hgSelection'
})
export class SelectionPipe implements PipeTransform {
  transform(betLine: BetLine): string {
    let selection = '';

    if (betLine.combinations?.length) {
      selection += '[';
    }

    if (!!betLine.baseList) {
      selection += betLine.baseList.join('-');
    }

    if (!!betLine.extraList) {
      selection += `/${betLine.extraList.join('-')}`;
    }

    if (betLine.combinations?.length) {
      selection += ']';
    }

    return selection;
  }
}
