import { Component, ChangeDetectionStrategy, Input, Inject, OnInit, OnChanges } from '@angular/core';
import { DestroySubject } from '@honoregaming/core';
import { operatorConfigurationToken, OperatorConfiguration } from '@honoregaming/configuration';
import { I18nService } from '@honoregaming/i18n';
import { takeUntil } from 'rxjs/internal/operators/takeUntil';

@Component({
  selector: 'hg-currency',
  templateUrl: './currency.component.html',
  styleUrls: ['./currency.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class CurrencyComponent extends DestroySubject implements OnInit, OnChanges {
  @Input() value: number;
  @Input() forceDecimals?: boolean;
  @Input() isFreebet: boolean = false;
  @Input() isFreeSpin: boolean = false;
  @Input() displaySymbol = true;
  @Input() hideValue: boolean = false;
  @Input() id: string = '';

  currency = this.operatorConfiguration.currency.symbol;
  billionNumber: number;

  currencyAsPrefix: boolean;

  constructor(
    @Inject(operatorConfigurationToken) private operatorConfiguration: OperatorConfiguration,
    private i18nService: I18nService
  ) {
    super();
  }

  ngOnInit() {
    this.i18nService.localeChanged$
      .pipe(takeUntil(this.destroy$))
      .subscribe(l => (this.currencyAsPrefix = l.currencyAsPrefix));
  }

  ngOnChanges() {
    this.billionNumber = this.value >= 1000000000 ? Math.floor(this.value / 1000000000) : 0;
  }
}
