import { Injectable } from '@angular/core';
import { BetBuilderService, BetLinesMapperService, DestroySubject } from '@honoregaming/core';
import { BetSlipService } from './bet-slip.service';
import { BetLine, BetSlipLinesInfo } from '../models';
import {
  BetBuilderError,
  BetBuilderErrorInfo,
  betBuilderErrorsKey,
  BetBuilderEventItemIds,
  BetBuilderLine,
  BetBuilderOdds,
  BetBuilderOddsResult,
  BetCategoryType,
  BetLineHistory,
  BetSlipMode,
  BetSystemHistory,
  BetSystemType,
  BetTypeKey,
  EventBetType,
  Match,
  SelectableEventBetTypeItem
} from '@honoregaming/types';
import { finalize, map, switchMap, take, takeUntil, tap } from 'rxjs/operators';
import { BettingApiService } from './betting.api.service';
import { BehaviorSubject, Observable, of, timer } from 'rxjs';
import { I18nService } from '@honoregaming/i18n';
import { BetBuilderOddsResponse } from '../models/api/bet-builder.response';
import { BetBuilderRequestInfo } from '../models/api/bet-builder.request';

@Injectable({
  providedIn: 'root'
})
export class BetSlipBetBuilderService extends DestroySubject {
  private isLoadingOddsEventIdsSubject$ = new BehaviorSubject<number[]>([]);
  private betBuilderEventsOddsCache: BetBuilderOddsResult[] = [];
  private cacheDurationInMs: number = 600000;

  constructor(
    private readonly betSlipService: BetSlipService,
    private readonly betBuilderService: BetBuilderService,
    private readonly bettingApiService: BettingApiService,
    private readonly i18nService: I18nService,
    private readonly betLinesMapperService: BetLinesMapperService
  ) {
    super();
    this.subscribeToBetSlipChanges();
    this.handleCacheRefresh();
  }

  get isLoadingOddsEventIds$(): Observable<number[]> {
    return this.isLoadingOddsEventIdsSubject$.asObservable();
  }

  get isFreebetAllowed(): boolean {
    return this.betBuilderService.isFreebetAllowed;
  }

  get hasBetBuilderBetLines(): boolean {
    return this.betBuilderService.hasBetBuilderBetLines;
  }

  get hasBetBuilderErrors(): boolean {
    return this.betBuilderService.hasBetBuilderErrors;
  }

  get betBuilderModeLabel(): string {
    return this.hasBetBuilderBetLines && this.betSlipService.betLinesValue.length === 1
      ? this.betBuilderService.productName
      : '';
  }

  getSimpleBetLinesByMatchId(skippedMatchId?: number): Map<number, BetLine[]> {
    const simpleBetLinesByMatchId: Map<number, BetLine[]> = new Map<number, BetLine[]>();
    this.betSlipService.betLinesValue
      .filter((betLine: BetLine) => !betLine.isBetBuilder && (!skippedMatchId || betLine.eventId !== skippedMatchId))
      .forEach((betLine: BetLine) => {
        const matchBetLines: BetLine[] | undefined = simpleBetLinesByMatchId.get(betLine.eventId);
        if (!matchBetLines) {
          simpleBetLinesByMatchId.set(betLine.eventId, [betLine]);
        } else {
          simpleBetLinesByMatchId.set(betLine.eventId, [...matchBetLines, betLine]);
        }
      });
    return simpleBetLinesByMatchId;
  }

  getBetBuilderErrorMessage(betLines: BetLine[]): string | null {
    if (!betLines.length) {
      return null;
    }

    let prioritizedErrorInfo: BetBuilderErrorInfo | undefined =
      this.betLinesMapperService.betLinesToBetBuilderErrorInfo(betLines);
    const errorKey: string | null = prioritizedErrorInfo
      ? betBuilderErrorsKey[prioritizedErrorInfo.betBuilderError]
      : null;
    return errorKey
      ? this.i18nService.translateSync(
          `BET-SLIP.BETTING_ERROR.BETBUILDER_${errorKey}`,
          this.betBuilderService.productName,
          prioritizedErrorInfo.betBuilderErrorParameters?.length
            ? prioritizedErrorInfo.betBuilderErrorParameters[0]
            : this.betBuilderService.getErrorParameter(prioritizedErrorInfo.betBuilderError)?.toString()
        )
      : null;
  }

  // Create a betBuilderBetLine from simpleBetLines or update existing one with newly selected ebti
  createOrUpdateBetBuilderBetLine(
    match: Match,
    eventBetType: EventBetType,
    eventBetTypeItem: SelectableEventBetTypeItem,
    simpleBetLines: BetLine[]
  ): Observable<BetLine> {
    const existingBetBuilderBetLine: BetLine | undefined = this.betBuilderService.getMatchBetBuilderBetLine(match.id);
    const updatedBetBuilderBetLine: BetLine = existingBetBuilderBetLine
      ? { ...existingBetBuilderBetLine, betBuilderLines: existingBetBuilderBetLine.betBuilderLines ?? [] }
      : this.betLinesMapperService.createBetBuilderBetLine(match, eventBetType);

    if (eventBetTypeItem.selected) {
      const existingBetBuilderLines: BetBuilderLine[] =
        this.betLinesMapperService.betLinesToBetBuilderLines(simpleBetLines);
      const newBetBuilderLine: BetBuilderLine = this.betLinesMapperService.createBetBuilderLine(
        match,
        eventBetType,
        eventBetTypeItem
      );
      updatedBetBuilderBetLine.betBuilderLines.push(...existingBetBuilderLines, newBetBuilderLine);
    } else {
      updatedBetBuilderBetLine.betBuilderLines = updatedBetBuilderBetLine.betBuilderLines.filter(
        (betBuilderLine: BetBuilderLine) => betBuilderLine.eventBetTypeItemId !== eventBetTypeItem.id
      );
    }

    updatedBetBuilderBetLine.betBuilderLines = this.validateBetBuilderLinesCount(
      updatedBetBuilderBetLine.betBuilderLines
    );

    if (
      (eventBetTypeItem.selected && this.isValidBetBuilderLines(updatedBetBuilderBetLine.betBuilderLines)) ||
      (!eventBetTypeItem.selected && this.isEligibleBetBuilderLines(updatedBetBuilderBetLine.betBuilderLines))
    ) {
      return this.getEventBetBuilderOdds(updatedBetBuilderBetLine);
    }

    return of(
      this.setBetBuilderBetLineOdds(updatedBetBuilderBetLine, true, {
        odds: 0,
        betBuilderError: this.hasContradictoryBetBuilderLines(updatedBetBuilderBetLine.betBuilderLines)
          ? BetBuilderError.ContradictorySelection
          : undefined
      })
    );
  }

  removeBetBuilderLine(matchId: number, betBuilderLine: BetBuilderLine): void {
    const updatedBetBuilderBetLine: BetLine | null = this.betBuilderService.deleteBetBuilderLine(
      matchId,
      betBuilderLine.eventBetTypeItemId
    );
    const isBetBuilderLinesEligible: boolean =
      updatedBetBuilderBetLine && this.isEligibleBetBuilderLines(updatedBetBuilderBetLine.betBuilderLines);

    if (updatedBetBuilderBetLine && updatedBetBuilderBetLine.betBuilderLines.length === 1) {
      this.changeBetBuilderBetLineToSimple(updatedBetBuilderBetLine);
      return;
    }

    if (isBetBuilderLinesEligible) {
      this.getEventBetBuilderOdds(updatedBetBuilderBetLine)
        .pipe(take(1))
        .subscribe((updatedBetLine: BetLine) => this.betSlipService.updateBetLine(updatedBetLine));
      return;
    }

    if (updatedBetBuilderBetLine && updatedBetBuilderBetLine.betBuilderLines.length > 1 && !isBetBuilderLinesEligible) {
      this.betSlipService.updateBetLine(updatedBetBuilderBetLine);
      return;
    }
  }

  canBeInBetBuilderMode(existingMatchBetLines: BetLine[], allowBetBuilder: boolean): boolean {
    return !existingMatchBetLines.length || this.betBuilderService.hasBetBuilderBetLines || allowBetBuilder;
  }

  tryChangeBetSlipMode(mode: BetSlipMode, markAsPersistent?: boolean): boolean {
    switch (mode) {
      case BetSlipMode.Simple:
        return this.tryChangeToSimpleMode(markAsPersistent);
      case BetSlipMode.Multiple:
        return this.tryChangeToMultipleMode();
    }
    return false;
  }

  tryChangeToMultipleMode(skippedMatchId?: number): boolean {
    const simpleBetLinesByMatchId: Map<number, BetLine[]> = this.getSimpleBetLinesByMatchId(skippedMatchId);
    if (simpleBetLinesByMatchId.size && this.hasMatchWithMultipleLines(simpleBetLinesByMatchId)) {
      this.changeSimpleBetLinesToBetBuilder(simpleBetLinesByMatchId);
      return true;
    }
    return false;
  }

  // Map bet builder bet lines to simple bet lines then add new bet lines to the bet slip and delete previous one
  // Delete previous bet line should be skipped to ensure creation of expected bet lines when linked betting parameter is activated
  changeBetBuilderBetLineToSimple(betBuilderBetLine: BetLine): void {
    const simpleBetLines: BetLine[] = this.betLinesMapperService.betBuilderBetLineToSimpleBetLines(betBuilderBetLine);
    simpleBetLines.forEach((simpleBetLine: BetLine) => {
      this.betSlipService.addBetLine(simpleBetLine, undefined, true);
    });
    this.betSlipService.removeBetLine(betBuilderBetLine);
  }

  // On rebet get bet builder odds then replace bet lines
  rebet(betSystem: BetSystemHistory): Observable<{ success: boolean; betCategory?: BetCategoryType }> {
    const betBuilderEventsItemIds: BetBuilderEventItemIds[] = this.betSystemHistoryToEventsItemIds(betSystem);
    const betBuilderRequestInfo: BetBuilderRequestInfo = this.buildRequestInfos(betBuilderEventsItemIds);
    return betBuilderRequestInfo.betBuilderOddsObs.pipe(
      tap((betBuilderOddsResponse: BetBuilderOddsResponse) => this.addOddsToCache(betBuilderOddsResponse)),
      switchMap((betBuilderOddsResponse: BetBuilderOddsResponse) =>
        this.betSlipService.replaceBetLines(
          betSystem,
          BetSystemType.Multiple,
          betBuilderOddsResponse.betBuilderOddsResults.concat(betBuilderRequestInfo.cachedBetBuilderOdds)
        )
      )
    );
  }

  private setIsLoadingOddsEventIds(isLoadingOddsEventIds: number[]) {
    this.isLoadingOddsEventIdsSubject$.next(isLoadingOddsEventIds);
  }

  private tryChangeToSimpleMode(markAsPersistent?: boolean): boolean {
    const betBuilderBetLines: BetLine[] = this.betBuilderService.betBuilderBetLines;
    if (betBuilderBetLines.length) {
      this.changeBetBuilderLinesToSimple();
      this.betSlipService.changeMode(BetSlipMode.Simple, markAsPersistent);
      return true;
    }
    return false;
  }

  private changeSimpleBetLinesToBetBuilder(simpleBetLinesByMatchId: Map<number, BetLine[]>): void {
    const betBuilderBetLines: BetLine[] = [];
    simpleBetLinesByMatchId.forEach((betLines: BetLine[]) => {
      if (betLines.length > 1) {
        const betBuilderBetLine: BetLine = this.betLinesMapperService.simpleBetLinesToBetBuilderBetLine(betLines);
        const isBetBuilderLinesValid: boolean = this.isValidBetBuilderLines(betBuilderBetLine.betBuilderLines);
        betLines.forEach((simpleBetLine: BetLine) => this.betSlipService.removeBetLine(simpleBetLine));
        if (isBetBuilderLinesValid) {
          betBuilderBetLines.push(betBuilderBetLine);
        } else {
          this.betSlipService.addBetLine(betBuilderBetLine);
        }
      }
    });

    this.getBetBuilderOdds(betBuilderBetLines)
      .pipe(take(1))
      .subscribe((updatedBetBuilderBetLines: BetLine[]) =>
        updatedBetBuilderBetLines.forEach((updatedBetBuilderBetLine: BetLine) =>
          this.betSlipService.addBetLine(updatedBetBuilderBetLine)
        )
      );
  }

  private changeBetBuilderLinesToSimple(): void {
    const betBuilderBetLines: BetLine[] = this.betBuilderService.betBuilderBetLines;
    betBuilderBetLines.forEach((betBuilderBetLine: BetLine) => this.changeBetBuilderBetLineToSimple(betBuilderBetLine));
  }

  private hasMatchWithMultipleLines(simpleBetLinesByMatchId: Map<number, BetLine[]>): boolean {
    return Array.from(simpleBetLinesByMatchId.values()).some((betLines: BetLine[]) => betLines.length > 1);
  }

  // Update bet builder service cache on bet slip changes to facilitate read access
  // If some betbuilder lines was deleted fetch odds of betbuilder lines previously flagged with max count error
  private subscribeToBetSlipChanges(): void {
    this.betSlipService.$lines
      .pipe(
        takeUntil(this.destroy$),
        switchMap((changes: BetSlipLinesInfo) => {
          const betLinesWithMaximumCountError: BetLine[] = this.filterByMaximumBetBuilderCountError(changes.lines);
          if (
            betLinesWithMaximumCountError.length &&
            changes.lines.filter((betLine: BetLine) => betLine.isBetBuilder)?.length <=
              this.betBuilderService.maxBetBuildersCount
          ) {
            return this.getBetBuilderOdds(betLinesWithMaximumCountError, true).pipe(
              tap((updatedBetBuilderBetLines: BetLine[]) =>
                updatedBetBuilderBetLines.forEach((updatedBetBuilderBetLine: BetLine) =>
                  this.betSlipService.updateBetLine(updatedBetBuilderBetLine)
                )
              )
            );
          } else {
            this.betBuilderService.setBetBuilderBetLines(changes.lines);
            return of(changes);
          }
        })
      )
      .subscribe();
  }

  private filterByMaximumBetBuilderCountError(betLines: BetLine[]): BetLine[] {
    return betLines.filter((betLine: BetLine) =>
      betLine.betBuilderLines?.some(
        (betBuilderLine: BetBuilderLine) => betBuilderLine.betBuilderError === BetBuilderError.MaximumBetBuilderCount
      )
    );
  }

  private hasContradictoryBetBuilderLines(betBuilderLines: BetBuilderLine[]): boolean {
    return betBuilderLines.some(
      (betBuilderLine: BetBuilderLine) => betBuilderLine.betBuilderError === BetBuilderError.ContradictorySelection
    );
  }

  private isEligibleBetBuilderLines(betBuilderLines: BetBuilderLine[]): boolean {
    return (
      betBuilderLines &&
      betBuilderLines.length > 1 &&
      betBuilderLines.every(
        (betBuilderLine: BetBuilderLine) => betBuilderLine.betBuilderError !== BetBuilderError.IneligibleSelection
      )
    );
  }

  private isValidBetBuilderLines(betBuilderLines: BetBuilderLine[]): boolean {
    return (
      betBuilderLines &&
      betBuilderLines.length > 1 &&
      betBuilderLines.every(
        (betBuilderLine: BetBuilderLine) =>
          !betBuilderLine.betBuilderError || betBuilderLine.betBuilderError === BetBuilderError.OddsTooLow
      )
    );
  }

  private getEventBetBuilderOdds(betBuilderBetLine: BetLine): Observable<BetLine> {
    return this.getBetBuilderOdds([betBuilderBetLine]).pipe(
      map(
        (betLines: BetLine[]) =>
          betLines.find((betLine: BetLine) => betLine.eventId === betBuilderBetLine.eventId) as BetLine
      )
    );
  }

  private getBetBuilderOdds(betBuilderBetLines: BetLine[], skipCache: boolean = false): Observable<BetLine[]> {
    const betBuilderEventsItemIds: BetBuilderEventItemIds[] =
      this.betLinesMapperService.betBuilderBetLinesToEventsItemIds(betBuilderBetLines);
    const betBuilderRequestInfo: BetBuilderRequestInfo = this.buildRequestInfos(betBuilderEventsItemIds, skipCache);
    this.setIsLoadingOddsEventIds(
      betBuilderEventsItemIds.map((betBuilderEventItemId: BetBuilderEventItemIds) => betBuilderEventItemId.eventId)
    );
    return betBuilderRequestInfo.betBuilderOddsObs.pipe(
      take(1),
      finalize(() => this.setIsLoadingOddsEventIds([])),
      tap((betBuilderOddsResponse: BetBuilderOddsResponse) => this.addOddsToCache(betBuilderOddsResponse)),
      map((betBuilderOddsResponse: BetBuilderOddsResponse) =>
        this.setBetBuilderBetLinesOdds(
          betBuilderOddsResponse.betBuilderOddsResults.concat(betBuilderRequestInfo.cachedBetBuilderOdds),
          betBuilderBetLines
        )
      )
    );
  }

  private setBetBuilderBetLinesOdds(
    betBuilderEventsOdds: BetBuilderOddsResult[],
    betBuilderBetLines: BetLine[]
  ): BetLine[] {
    return betBuilderEventsOdds.map((betBuilderEventOdds: BetBuilderOddsResult) => {
      const betBuilderBetLine: BetLine = this.findBetLine(betBuilderEventOdds.eventId, betBuilderBetLines) as BetLine;
      return this.setBetBuilderBetLineOdds(
        betBuilderBetLine,
        !!betBuilderEventOdds.betBuilderOdds.betBuilderError,
        betBuilderEventOdds.betBuilderOdds
      );
    });
  }

  private setBetBuilderBetLineOdds(
    betBuilderBetLine: BetLine,
    hasError: boolean,
    betBuilderOdds: BetBuilderOdds
  ): BetLine {
    return {
      ...betBuilderBetLine,
      betBuilderLines: betBuilderBetLine.betBuilderLines?.map((betBuilderLine: BetBuilderLine) => ({
        ...betBuilderLine,
        betBuilderError: hasError ? betBuilderOdds.betBuilderError ?? betBuilderLine.betBuilderError : undefined,
        betBuilderErrorParameters: betBuilderOdds.betBuilderErrorParameters
      })),
      odds: betBuilderOdds.odds
    };
  }

  private validateBetBuilderLinesCount(betBuilderLines: BetBuilderLine[]): BetBuilderLine[] {
    const maxItemsCount: number | undefined = this.betBuilderService.maxItemsCount;
    const maxScorersCount: number | undefined = this.betBuilderService.maxScorersCount;

    if (maxItemsCount && betBuilderLines.length > maxItemsCount) {
      return betBuilderLines.map((betBuilderLine: BetBuilderLine) => ({
        ...betBuilderLine,
        betBuilderError: betBuilderLine.betBuilderError ?? BetBuilderError.MaximumItemsCount
      }));
    }

    if (
      maxScorersCount &&
      betBuilderLines.filter((betBuilderLine: BetBuilderLine) => betBuilderLine.betTypeId === BetTypeKey.Scorer)
        .length > maxScorersCount
    ) {
      return betBuilderLines.map((betBuilderLine: BetBuilderLine) => ({
        ...betBuilderLine,
        betBuilderError:
          betBuilderLine.betBuilderError ?? betBuilderLine.betTypeId === BetTypeKey.Scorer
            ? BetBuilderError.MaximumGoalScorersCount
            : undefined
      }));
    }
    return betBuilderLines;
  }

  private buildRequestInfos(
    betBuilderEventsItemIds: BetBuilderEventItemIds[],
    skipCache: boolean = false
  ): BetBuilderRequestInfo {
    const cachedBetBuilderOdds: BetBuilderOddsResult[] = !skipCache
      ? this.getCachedBetBuilderOdds(betBuilderEventsItemIds)
      : [];
    const betBuilderEventsItemIdsToFetch: BetBuilderEventItemIds[] = this.getBetBuilderEventsItemIdsToFetch(
      betBuilderEventsItemIds,
      cachedBetBuilderOdds
    );
    const existingBetBuilderBetLinesCount: number = this.betSlipService.betLinesValue.filter(
      (betLine: BetLine) =>
        betLine.isBetBuilder &&
        !betBuilderEventsItemIdsToFetch.some(
          (betBuilderEventItemIds: BetBuilderEventItemIds) => betBuilderEventItemIds.eventId === betLine.eventId
        )
    ).length;
    const betBuilderOddsObs: Observable<BetBuilderOddsResponse> = betBuilderEventsItemIdsToFetch.length
      ? this.bettingApiService.getBetBuilderOdds(betBuilderEventsItemIdsToFetch, existingBetBuilderBetLinesCount)
      : of({ betBuilderOddsResults: [] });
    return {
      cachedBetBuilderOdds,
      betBuilderOddsObs
    };
  }

  private getCachedBetBuilderOdds(betBuilderEventsItemIds: BetBuilderEventItemIds[]): BetBuilderOddsResult[] {
    return betBuilderEventsItemIds.reduce(
      (betBuilderEventsOdds: BetBuilderOddsResult[], betBuilderEventItemIds: BetBuilderEventItemIds) => {
        const cachedBetBuilderEventOdds: BetBuilderOddsResult | undefined = this.betBuilderEventsOddsCache.find(
          (cachedBetBuilderEventOdds: BetBuilderOddsResult) =>
            betBuilderEventItemIds.eventId === cachedBetBuilderEventOdds.eventId &&
            betBuilderEventItemIds.eventBetTypeItemIds.length ===
              cachedBetBuilderEventOdds.eventBetTypeItemIds.length &&
            betBuilderEventItemIds.eventBetTypeItemIds.every((eventBetTypeItemId: number) =>
              cachedBetBuilderEventOdds.eventBetTypeItemIds.includes(eventBetTypeItemId)
            )
        );
        if (cachedBetBuilderEventOdds) {
          betBuilderEventsOdds.push(cachedBetBuilderEventOdds);
        }
        return betBuilderEventsOdds;
      },
      []
    );
  }

  private getBetBuilderEventsItemIdsToFetch(
    betBuilderEventsItemIds: BetBuilderEventItemIds[],
    cachedBetBuilderOdds: BetBuilderOddsResult[]
  ): BetBuilderEventItemIds[] {
    return betBuilderEventsItemIds.filter(
      (betBuilderEventItemIds: BetBuilderEventItemIds) =>
        !cachedBetBuilderOdds.some(
          (cachedBetBuilderOdds: BetBuilderOddsResult) =>
            cachedBetBuilderOdds.eventId === betBuilderEventItemIds.eventId
        )
    );
  }

  private findBetLine(matchId: number, betBuilderBetLines: BetLine[]): BetLine | undefined {
    return betBuilderBetLines.find((betBuilderBetLine: BetLine) => betBuilderBetLine.eventId === matchId);
  }

  private betSystemHistoryToEventsItemIds(betSystem: BetSystemHistory): BetBuilderEventItemIds[] {
    return betSystem.betLines
      .filter((betLine: BetLineHistory) => !!betLine.betBuilderLines?.length)
      .map((betLine: BetLineHistory) => {
        const eventBetTypeItemIds: number[] = betLine.betBuilderLines.map(
          (betBuilderLine: BetBuilderLine) => betBuilderLine.eventBetTypeItemId
        );
        return {
          eventId: betLine.eventId,
          eventBetTypeItemIds
        };
      });
  }

  private addOddsToCache(betBuilderOddsResponse: BetBuilderOddsResponse): void {
    this.betBuilderEventsOddsCache.push(...betBuilderOddsResponse.betBuilderOddsResults);
  }

  private handleCacheRefresh(): void {
    timer(0, this.cacheDurationInMs)
      .pipe(
        tap(() => (this.betBuilderEventsOddsCache = [])),
        takeUntil(this.destroy$)
      )
      .subscribe();
  }
}
