import { Component, ChangeDetectionStrategy, Input, OnChanges } from '@angular/core';

@Component({
  selector: 'hg-spin-and-win-result',
  templateUrl: './spin-and-win-result.component.html',
  styleUrls: ['./spin-and-win-result.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class SpinAndWinResultComponent implements OnChanges {
  @Input()
  result: any;

  serializedResult: { number: number; position: number; respins: number };

  constructor() {}

  ngOnChanges() {
    this.serializedResult = JSON.parse(this.result);
  }
}
