import { ChangeDetectionStrategy, ChangeDetectorRef, Component, Inject, OnInit } from '@angular/core';
import { AccountService } from '../../services/account.service';
import { DestroySubject, BetCategoryConfigurationService } from '@honoregaming/core';
import {
  BetCategoryFilterData,
  BetCategoryType,
  BetLineType,
  BetState,
  BetSystemHistory,
  BetSystemType,
  CompleteMyBetResponse
} from '@honoregaming/types';
import { take, takeUntil, catchError, tap, filter, switchMap } from 'rxjs/operators';
import { BetSlipBetLinesService, BetSlipService, BettingApiService, CreateBetCodeRequest } from '@honoregaming/betslip';
import { RebetClearComponent, ShareCodeComponent } from '@honoregaming/customer-ui';
import { GenericContentComponent, MessageService } from '@honoregaming/ui';
import { I18nService } from '@honoregaming/i18n';
import {
  AuthService,
  CodeType,
  CustomerOperatorConfiguration,
  customerOperatorConfigurationToken,
  TelemetryService
} from '@honoregaming/customer-core';
import { combineLatest, Observable, of, Subject } from 'rxjs';
import { CashoutDemandComponent } from '../cashout-demand/cashout-demand.component';
import { Router } from '@angular/router';
import { SelectValue, AccountFilter } from '../../models/account-filters.model';

@Component({
  selector: 'hg-bet-history',
  templateUrl: './bet-history.component.html',
  styleUrls: ['./bet-history.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class BetHistoryComponent extends DestroySubject implements OnInit {
  history: { betSystem: BetSystemHistory; isGettingBetCode?: boolean }[] = [];
  loading = false;
  skip = 0;
  take = 5;
  plus = false;
  hasMore = true;
  BetSystemType = BetSystemType;
  BetState = BetState;
  BetLineType = BetLineType;
  states: SelectValue[] = [{ value: BetState.Pending }, { value: BetState.Won }, { value: BetState.Lost }];
  betCategories: BetCategoryType[] = null;
  authorizedToReplayDrawGame: boolean = false;

  currentFilter: AccountFilter = {
    state: BetState.Pending
  };

  betCategoriesFilterData: BetCategoryFilterData[] = [];
  BetCategoryType = BetCategoryType;

  private readonly loadHistory$: Subject<void> = new Subject<void>();

  constructor(
    private accountService: AccountService,
    private bettingApiService: BettingApiService,
    private messageService: MessageService,
    private cdRef: ChangeDetectorRef,
    private i18nService: I18nService,
    private betSlipService: BetSlipService,
    private authService: AuthService,
    private router: Router,
    private telemetryService: TelemetryService,
    private betCategoryConfigurationService: BetCategoryConfigurationService,
    private betSlipBetLinesService: BetSlipBetLinesService,
    @Inject(customerOperatorConfigurationToken) private operatorConfiguration: CustomerOperatorConfiguration
  ) {
    super();
  }

  ngOnInit() {
    if (
      this.operatorConfiguration.betCategories.filter(
        (x: BetCategoryType) =>
          x === BetCategoryType.HorseRacingMutualInternationalPool ||
          x === BetCategoryType.HorseRacingMutualOperatorPool
      ).length > 1
    ) {
      this.betCategories = this.operatorConfiguration.betCategories.filter(
        x => x !== BetCategoryType.HorseRacingMutualInternationalPool
      );
    } else {
      this.betCategories = this.operatorConfiguration.betCategories;
    }

    this.betCategories = this.betCategories.filter(
      (betCategory: BetCategoryType) =>
        betCategory !== BetCategoryType.InstantGame && betCategory !== BetCategoryType.SportsPool
    );
    this.betCategories.push(null);
    this.betCategoriesFilterData = this.betCategoryConfigurationService.historyBetCategoriesFilterData;
    this.subscribeToLoadHistory();
    this.authorizedToReplayDrawGame =
      this.operatorConfiguration?.drawGameConfiguration?.allowsCustomerToReplayLastDrawGameSelection;
  }

  loadMore(): void {
    if (this.loading || !this.hasMore) {
      return;
    }

    this.skip += this.take;
    this.loadHistory$.next();
  }

  filter(filter: AccountFilter): void {
    this.skip = 0;
    this.hasMore = true;
    this.history = [];
    // Copy: the filters component mutates and re-emits the very same object reference
    this.currentFilter = { ...filter };
    this.loadHistory$.next();
  }

  onRebet(betSystem: BetSystemHistory) {
    if (this.betSlipService.hasBets()) {
      this.messageService.sendComponentMessage(RebetClearComponent).closed.subscribe(result => {
        if (!!result) {
          this.rebet(betSystem);
        }
      });
    } else {
      this.rebet(betSystem);
    }
  }

  onCompleteMyBet(betSystemHistory: BetSystemHistory): void {
    this.betSlipService
      .initCompleteMyBet(betSystemHistory)
      .pipe(
        takeUntil(this.destroy$),
        catchError(() => of(null)),
        filter((completeMyBetResponse: CompleteMyBetResponse | null) => !completeMyBetResponse),
        tap(() => {
          this.messageService.sendComponentMessage(
            GenericContentComponent,
            {
              title: this.i18nService.translateSync('MY_BETS.COMPLETE_MY_BET.ERROR_TITLE'),
              text: this.i18nService.translateSync('MY_BETS.COMPLETE_MY_BET.ERROR_BODY'),
              isError: true
            },
            {
              canBeDismissed: false,
              displayClose: true
            }
          );
        })
      )
      .subscribe();
  }

  private rebet(betSystem: BetSystemHistory): void {
    this.telemetryService.trackEvent('rebet');
    this.betSlipBetLinesService
      .rebet(betSystem)
      .pipe(takeUntil(this.destroy$))
      .subscribe(result => {
        if (result && result.success) {
          if (result.betCategory === BetCategoryType.SportsFixedOdds) {
            this.router.navigate(['/sports']);
          } else {
            this.router.navigate(['/draw-games']);
          }
        }
      });
  }

  onGetBetCode(request: { betCodeRequest: CreateBetCodeRequest; totalOdds: string }) {
    this.telemetryService.trackEvent('getBetCodeFromMyAccount');

    const betSystem = this.history.find(bs => bs.betSystem.id === request.betCodeRequest.betSystemId);
    if (betSystem) {
      betSystem.isGettingBetCode = true;

      this.bettingApiService
        .getBetCode(request.betCodeRequest)
        .pipe(takeUntil(this.destroy$))
        .subscribe(betCode => {
          betSystem.isGettingBetCode = false;
          this.cdRef.markForCheck();

          const isOddsBoost =
            betSystem.betSystem.betLines.length === 1 && !!betSystem.betSystem.betLines[0].oddsBoostId;
          const isManualOddsBoost =
            betSystem.betSystem.betLines.length === 1 && !!betSystem.betSystem.betLines[0].manualOddsBoostId;

          const codeNameObservable = this.i18nService.translate('BETCODE.BETCODE');
          const shareUrl = `${this.operatorConfiguration.global.customerUrl}/?betcode=${betCode.code}`;

          const shareMessageObservable = this.i18nService.translate(
            isOddsBoost || isManualOddsBoost
              ? isOddsBoost
                ? 'BETCODE.SHARE_ODDSBOOST_MESSAGE'
                : 'BETCODE.SHARE_MANUALODDSBOOST_MESSAGE'
              : 'BETCODE.SHARE_MESSAGE_TEMPLATE',
            request.totalOdds,
            betCode.code,
            this.operatorConfiguration.name,
            shareUrl,
            isOddsBoost || isManualOddsBoost
              ? isOddsBoost
                ? betSystem.betSystem.betLines[0].oddsBoostName
                : betSystem.betSystem.betLines[0].manualOddsBoostName
              : null
          );

          combineLatest([codeNameObservable, shareMessageObservable])
            .pipe(take(1))
            .subscribe(([codeName, shareMessage]) => {
              this.messageService.sendComponentMessage(ShareCodeComponent, {
                code: betCode.code,
                codeName: codeName,
                codeType: CodeType.BetCode,
                shareMessageTemplate: shareMessage + (isOddsBoost ? ' 🚀' : ' 🏆')
              });
            });
        });
    }
  }

  public onCashout(betSystemId: number) {
    const betSystemIndex = this.history.findIndex(bs => bs.betSystem.id === betSystemId);
    if (betSystemIndex > -1) {
      const betSystem = this.history[betSystemIndex].betSystem;

      this.messageService
        .sendComponentMessage(
          CashoutDemandComponent,
          {
            betSystemId: betSystem.id,
            amount: betSystem.cashoutAmount
          },
          { canBeDismissed: false, displayClose: false }
        )
        .closed.subscribe(result => {
          if (result) {
            this.history.splice(betSystemIndex, 1);
            this.authService.getBalance().pipe(takeUntil(this.destroy$)).subscribe();
            this.cdRef.markForCheck();
          }
        });
    }
  }

  private subscribeToLoadHistory(): void {
    this.loadHistory$
      .pipe(
        tap(() => this.startLoading()),
        // switchMap cancels the pending request, so a response from a previous
        // filter can never be appended to the list of the newly selected one
        switchMap(() => this.getHistory()),
        takeUntil(this.destroy$)
      )
      .subscribe((betsHistory: BetSystemHistory[]) => this.handleResponse(betsHistory));
  }

  private getHistory(): Observable<BetSystemHistory[]> {
    return this.accountService
      .getBetsHistory(
        this.skip,
        this.take,
        this.currentFilter.state as BetState,
        this.currentFilter.month,
        this.currentFilter.option as BetCategoryType
      )
      .pipe(catchError(() => of<BetSystemHistory[]>([])));
  }

  private startLoading(): void {
    this.loading = true;
    this.cdRef.markForCheck();
  }

  private handleResponse(betsHistory: BetSystemHistory[]): void {
    if (betsHistory.length - this.take < 0) {
      this.hasMore = false;
    }

    this.history = this.history.concat(betsHistory.map(betSystem => ({ betSystem })));
    this.loading = false;
    this.cdRef.markForCheck();
  }
}
