import { isPlatformServer } from '@angular/common';
import { Component, ChangeDetectionStrategy, PLATFORM_ID, Inject, OnDestroy } from '@angular/core';
import { MobileNavService } from 'projects/customer/customer/src/app/services/mobile-nav.service';

@Component({
  selector: 'hg-layout',
  templateUrl: './layout.component.html',
  styleUrls: ['./layout.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class LayoutComponent implements OnDestroy {
  isServer = isPlatformServer(this.platformId);
  constructor(@Inject(PLATFORM_ID) private platformId, private mobileNavService: MobileNavService) {}
  ngOnDestroy() {
    this.mobileNavService.updateDisplayHeaderMyBets(true);
    this.mobileNavService.clickOnBurgerMenu(false);
  }
}
