import { DOCUMENT } from '@angular/common';
import {
  Component,
  OnInit,
  ChangeDetectionStrategy,
  Inject,
  ChangeDetectorRef,
  HostBinding,
  AfterViewChecked
} from '@angular/core';
import { MobileNavService } from '../../services/mobile-nav.service';
import { takeUntil } from 'rxjs/operators';
import { DestroySubject } from '@honoregaming/core';

@Component({
  selector: 'hg-welcome-tutorial',
  templateUrl: './welcome-tutorial.component.html',
  styleUrls: ['./welcome-tutorial.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class WelcomeTutorialComponent extends DestroySubject implements OnInit, AfterViewChecked {
  @HostBinding('class.step-three-four') isStepSthreeOrFour = false;
  @HostBinding('class.final-step') isFinalStep = false;

  tutorialStepsStorage = 'tutorial_steps';
  tutorialStep: number;

  constructor(
    private cdRef: ChangeDetectorRef,
    private mobileNavService: MobileNavService,
    @Inject(DOCUMENT) private document: any
  ) {
    super();
  }

  ngOnInit() {
    this.tutorialStep = +localStorage.getItem(this.tutorialStepsStorage);
    this.isStepSthreeOrFour = this.tutorialStep === 3 || this.tutorialStep === 4;
    this.isFinalStep = this.tutorialStep === 5;

    if (
      localStorage.getItem(this.tutorialStepsStorage) === 'NaN' ||
      localStorage.getItem(this.tutorialStepsStorage) === '0' ||
      !localStorage.getItem(this.tutorialStepsStorage)
    ) {
      localStorage.setItem(this.tutorialStepsStorage, '0');
    }

    this.mobileNavService.tutorialUpdate.pipe(takeUntil(this.destroy$)).subscribe(step => {
      this.tutorialStep = step;
      if (this.tutorialStep === 3 || this.tutorialStep === 4) {
        this.isStepSthreeOrFour = this.tutorialStep === 3 || this.tutorialStep === 4;
      } else if (this.tutorialStep === 5) {
        this.isFinalStep = this.tutorialStep === 5;
      } else if (this.tutorialStep > 5) {
        this.releaseBody();
      } else {
        this.isStepSthreeOrFour = false;
      }

      this.cdRef.markForCheck();
    });

    this.cdRef.markForCheck();
  }

  ngAfterViewChecked() {
    this.fixBody();
  }

  clickToNextStep() {
    localStorage[this.tutorialStepsStorage] = parseInt(localStorage[this.tutorialStepsStorage]) + 1;
    this.tutorialStep = Number(localStorage.getItem(this.tutorialStepsStorage));
    this.mobileNavService.updateStepTutorial(this.tutorialStep);

    this.cdRef.markForCheck();
  }

  skipTutorial() {
    localStorage[this.tutorialStepsStorage] = parseInt('6');
    this.tutorialStep = Number(localStorage.getItem(this.tutorialStepsStorage));
  }

  fixBody(onlyInXs = false) {
    onlyInXs
      ? this.document.documentElement.classList.add('hidden-in-xs')
      : this.document.documentElement.classList.add('hidden');
  }

  releaseBody() {
    this.document.documentElement.classList.remove('hidden-in-xs');
    this.document.documentElement.classList.remove('hidden');
  }
}
