import { Injectable } from '@angular/core';
import { globalConfiguration } from '@honoregaming/configuration';
import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';

@Injectable({
  providedIn: 'root'
})
export class WidgetsService {
  constructor(private httpClient: HttpClient) {}

  addWidgetView(widgetType: string): Observable<{}> {
    return this.httpClient.post<{}>(globalConfiguration.apiBaseUrl + `widgets/${widgetType}`, {});
  }

  addWidgetErrorView(widgetType: string): Observable<{}> {
    return this.httpClient.post<{}>(globalConfiguration.apiBaseUrl + `widgets/${widgetType}/error`, {});
  }
}
