import { DOCUMENT, isPlatformBrowser } from '@angular/common';
import { Inject, Injectable, PLATFORM_ID } from '@angular/core';
import { take, tap } from 'rxjs/operators';
import { CriteoConfiguration } from '@honoregaming/configuration';
import { BetCategoryConfigurationService, CookieStorageService } from '@honoregaming/core';
import { CustomerOperatorConfiguration, customerOperatorConfigurationToken, SESSION_IDENTIFIER } from '../../models';
import { AuthService } from '../auth.service';
import { ITelemetryService } from './telemetry-service.model';

declare var window: any;
declare var criteo_q: any;

@Injectable()
export class CriteoTelemetryService implements ITelemetryService {
  private readonly isBrowser: boolean = isPlatformBrowser(this.platformId);
  private readonly configuration?: CriteoConfiguration = this.operatorConfig.telemetryConfiguration.criteo;
  private readonly headElementIdentifier: string = 'criteo-head';

  private readonly hasHomePageCasino: boolean = this.operatorConfig.onlineConfiguration?.homePageCasino ?? false;
  private readonly instantGamesBetCategoryPath: string =
    this.betCategoryConfigurationService.getInstantGamesBetCategoryPath();

  private deviceType?: 't' | 'm' | 'd';
  private visitorId?: string;

  constructor(
    private readonly authService: AuthService,
    private readonly storageService: CookieStorageService,
    private readonly betCategoryConfigurationService: BetCategoryConfigurationService,
    @Inject(customerOperatorConfigurationToken) private readonly operatorConfig: CustomerOperatorConfiguration,
    @Inject(DOCUMENT) private readonly document: Document,
    @Inject(PLATFORM_ID) private readonly platformId: Object
  ) {
    this.initialize();
  }

  trackPageView(_name: string, _path: string): void {
    if (!this.canSendEvents()) {
      return;
    }

    const hasViewedHomePage: boolean =
      _path === '/' ||
      (!this.hasHomePageCasino && _path === '/sports') ||
      (this.hasHomePageCasino && _path === `/${this.instantGamesBetCategoryPath}`);

    if (!hasViewedHomePage) {
      return;
    }

    this.authService.me$
      .pipe(
        take(1),
        tap(me => {
          const defaultEvents: unknown[] = this.getDefaultEvents(me?.id);
          criteo_q?.push(...defaultEvents, { event: 'viewHome' });
        })
      )
      .subscribe();
  }

  trackEvent(name: string, properties: any): void {
    if (!this.canSendEvents() || (name !== 'sign_up_complete' && name !== 'firstTimeDeposit' && name !== 'deposit')) {
      return;
    }

    this.authService.me$
      .pipe(
        take(1),
        tap(me => {
          const defaultEvents: unknown[] = this.getDefaultEvents(me?.id);

          if (name === 'sign_up_complete') {
            criteo_q?.push(...defaultEvents, { event: 'lead', type: 'Signup' });
          } else if (name === 'firstTimeDeposit') {
            criteo_q?.push(...defaultEvents, {
              event: 'trackTransaction',
              id: properties.id,
              item: [{ id: 'firstDeposit', price: properties.amount, quantity: 1 }],
              currency: this.operatorConfig.currency.symbol
            });
          } else if (name === 'deposit') {
            criteo_q?.push(...defaultEvents, {
              event: 'trackTransaction',
              id: properties.id,
              item: [{ id: 'deposit', price: properties.amount, quantity: 1 }],
              currency: this.operatorConfig.currency.symbol
            });
          }
        })
      )
      .subscribe();
  }

  private isInitialized(): boolean {
    return (
      !this.isBrowser || !this.configuration?.enabled || !!this.document.getElementById(this.headElementIdentifier)
    );
  }

  private canSendEvents(): boolean {
    return this.isBrowser && criteo_q != null;
  }

  private initialize(): void {
    if (this.isInitialized()) {
      return;
    }

    window['criteo_q'] = window['criteo_q'] || [];

    this.deviceType = /iPad/.test(navigator.userAgent)
      ? 't'
      : /Mobile|iP(hone|od)|Android|BlackBerry|IEMobile|Silk/.test(navigator.userAgent)
      ? 'm'
      : 'd';

    this.visitorId = this.storageService.getItem(SESSION_IDENTIFIER);

    const headElement: HTMLScriptElement = this.document.createElement('script');
    headElement.id = this.headElementIdentifier;
    headElement.type = 'text/javascript';
    headElement.src = `//dynamic.criteo.com/js/ld/ld.js?a=${this.configuration?.partnerId}`;
    headElement.async = true;
    this.document.head.appendChild(headElement);
  }

  private getDefaultEvents(userId?: number): unknown[] {
    this.visitorId ??= this.storageService.getItem(SESSION_IDENTIFIER);
    return [
      { event: 'setAccount', account: this.configuration?.partnerId },
      { event: 'setSiteType', type: this.deviceType },
      ...(!!userId ? [{ event: 'setCustomerId', id: userId }] : []),
      ...(!!this.visitorId ? [{ event: 'setRetailerVisitorId', id: this.visitorId }] : [])
    ];
  }
}
