import { DOCUMENT } from '@angular/common';
import { AfterViewInit, Component, ElementRef, Inject, Input, QueryList, ViewChildren } from '@angular/core';
import {
  AbstractControl,
  ControlValueAccessor,
  NG_VALIDATORS,
  NG_VALUE_ACCESSOR,
  ValidationErrors,
  Validator
} from '@angular/forms';

@Component({
  selector: 'hg-input-boxes',
  templateUrl: './input-boxes.component.html',
  styleUrls: ['./input-boxes.component.scss'],
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: InputBoxesComponent,
      multi: true
    },
    {
      provide: NG_VALIDATORS,
      useExisting: InputBoxesComponent,
      multi: true
    }
  ]
})
export class InputBoxesComponent implements ControlValueAccessor, Validator, AfterViewInit {
  @Input() size: number;
  @Input() keepFocus: boolean;
  @Input() type: string = 'text';

  @ViewChildren('input') boxes: QueryList<ElementRef>;

  disabled: boolean;
  value: string;

  ctrlPressed: boolean = false;

  constructor(@Inject(DOCUMENT) private document: Document) {}

  ngAfterViewInit() {
    this.boxes.first.nativeElement.focus();
  }

  keypress(boxIndex: number, event: any) {
    setTimeout(() => {
      if (event.inputType !== 'deleteContentBackward') {
        this.boxes.find((_e, i) => i === boxIndex + 1)?.nativeElement.focus();
      }
      this.computeValue();
    }, 0);
  }

  keyup(event: KeyboardEvent) {
    if (event.key === 'Control') {
      this.ctrlPressed = false;
    }
  }

  keydown(boxIndex: number, event: KeyboardEvent) {
    if (event.key === 'Control') {
      this.ctrlPressed = true;
    }
    if (event.key === 'Backspace' && (<any>event.currentTarget).value === '') {
      setTimeout(() => {
        const previousBox = this.boxes.find((_e, i) => i === boxIndex - 1)?.nativeElement;
        if (previousBox) {
          previousBox.focus();
          previousBox.value = '';
        }
      }, 0);

      this.computeValue();
    } else if (event.key !== 'Backspace') {
      const input = event.target as EventTarget & { value: string; selectionStart: number; selectionEnd: number };
      const target = input.value + event.key;
      if (
        this.type === 'number' &&
        !this.ctrlPressed &&
        ((target.length > 1 && input.selectionEnd === input.selectionStart) || event.key > '9' || event.key < '0')
      ) {
        event.stopPropagation();
        event.preventDefault();
        return false;
      }
    }
  }

  blur() {
    setTimeout(() => {
      if (this.keepFocus) {
        let index = -1;
        this.boxes.find((item, i) => {
          if (item.nativeElement === this.document.activeElement) {
            index = i;
            return true;
          }

          return false;
        });

        if (index === -1) {
          setTimeout(() => {
            this.boxes.first.nativeElement.focus();
          }, 0);
        } else {
          let firstEmptyBoxIndex: number;
          const box = this.boxes.find((item, i) => {
            if (item.nativeElement.value === '') {
              firstEmptyBoxIndex = i;
              return true;
            }

            return false;
          });
          if (box && index !== firstEmptyBoxIndex - 1) {
            setTimeout(() => {
              box.nativeElement.focus();
            }, 0);
          }
        }
      }
    }, 0);
  }

  paste(event: ClipboardEvent) {
    for (let index = 0; index < this.boxes.length; index++) {
      const nativeElement = this.boxes.find((_e, i) => i === index)?.nativeElement;
      nativeElement.value = '';
    }

    const pastedString = event.clipboardData.getData('text');
    let delay = 0;

    for (let index = 0; index < this.boxes.length; index++) {
      setTimeout(() => {
        const nativeElement = this.boxes.find((_e, i) => i === index)?.nativeElement;
        nativeElement.value = pastedString[index];
        nativeElement.focus();
        this.computeValue();
      }, delay);
      delay = delay + 200;
    }
  }

  computeValue() {
    this.value = '';
    if (this.boxes) {
      for (let index = 0; index < this.boxes.length; index++) {
        this.value += this.boxes.find((_e, i) => i === index)?.nativeElement.value;
      }

      this.changed.forEach(f => f(this.value));
    }
  }

  private changed = new Array<(v: string) => void>();
  private touched = new Array<() => void>();

  writeValue(value: string): void {
    if (this.boxes) {
      for (let index = 0; index < this.boxes.length; index++) {
        const nativeElement = this.boxes.find((_e, i) => i === index)?.nativeElement;
        nativeElement.value = value ? value[index] : '';
      }

      this.computeValue();
    }
  }

  registerOnChange(fn: any): void {
    this.changed.push(fn);
  }

  registerOnTouched(fn: any): void {
    this.touched.push(fn);
  }

  setDisabledState?(isDisabled: boolean): void {
    this.disabled = isDisabled;
    if (!this.disabled) {
      setTimeout(() => {
        this.boxes.first.nativeElement.focus();
      }, 0);
    }
  }

  validate(_control: AbstractControl): ValidationErrors {
    if (!!this.value && this.value.length === this.size) {
      return null;
    }

    return { valid: false };
  }

  registerOnValidatorChange?(_fn: () => void): void {}
}
