import { HttpEvent, HttpHandler, HttpInterceptor, HttpRequest } from '@angular/common/http';
import { Injectable, Inject } from '@angular/core';
import { Observable } from 'rxjs';
import { globalConfiguration, appConfiguration } from '@honoregaming/configuration';
import { natifToken } from '../services/tokens';

@Injectable()
export class HonoreOperatorInterceptor implements HttpInterceptor {
  constructor(@Inject(natifToken) private isNatif: boolean) {}
  public intercept(req: HttpRequest<any>, next: HttpHandler): Observable<HttpEvent<any>> {
    if (
      this.isNatif &&
      (req.url.startsWith(globalConfiguration.apiBaseUrl) ||
        req.url.startsWith(globalConfiguration.apiAuthenticationBaseUrl) ||
        req.url.startsWith(globalConfiguration.apiBettingBaseUrl) ||
        req.url.startsWith(globalConfiguration.apiEventsBaseUrl) ||
        req.url.startsWith(globalConfiguration.apiPaymentProviderBaseUrl))
    ) {
      req = req.clone({
        headers: req.headers.append('Honore-Operator', appConfiguration.operatorKey)
      });
    }
    return next.handle(req);
  }
}
