import { Component, ChangeDetectionStrategy, OnInit, ChangeDetectorRef, Inject } from '@angular/core';
import { Location } from '@angular/common';
import { catchError, finalize, takeUntil } from 'rxjs/operators';
import { of } from 'rxjs';
import { AnchorType, AuthService, CustomerService } from '@honoregaming/customer-core';
import { Async, DestroySubject } from '@honoregaming/core';
import { ContentService } from '@honoregaming/templating';
import { globalConfiguration } from '@honoregaming/configuration';
import { customerOperatorConfigurationToken, CustomerOperatorConfiguration } from '@honoregaming/customer-core';
import { ProfilePolicy, SecurityPolicy } from '@honoregaming/types';
import { AccountService } from '../../services/account.service';

@Component({
  selector: 'hg-registration',
  templateUrl: './registration.component.html',
  styleUrls: ['./registration.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class RegistrationComponent extends DestroySubject implements OnInit {
  AnchorType = AnchorType;
  profilePolicyRequirements?: ProfilePolicy;
  securityPolicy?: SecurityPolicy;
  step: number = 0;
  fullSteps?: number;
  mobileLogoPath: string = globalConfiguration.assetsPath + this.operatorConfiguration.key + '/mobile-logo.png';

  hasSlides?: boolean;
  content?: string;
  style?: string;
  isLoadingContent: boolean = false;

  constructor(
    private readonly cdRef: ChangeDetectorRef,
    private readonly accountService: AccountService,
    private readonly location: Location,
    protected readonly authService: AuthService,
    private readonly customerService: CustomerService,
    private readonly contentService: ContentService,
    @Inject(customerOperatorConfigurationToken) private readonly operatorConfiguration: CustomerOperatorConfiguration
  ) {
    super();
  }

  ngOnInit() {
    this.accountService.registerStep.pipe(takeUntil(this.destroy$)).subscribe(x => {
      this.step = x;
      this.cdRef.markForCheck();
    });

    this.customerService.getSecurityPolicy().subscribe(x => {
      this.profilePolicyRequirements = x.profilePolicyRequirements;
      this.profilePolicyRequirements ? (this.fullSteps = 3) : (this.fullSteps = 2);

      if (this.operatorConfiguration.onlineConfiguration?.disableSmsValidationOnRegistration) {
        this.fullSteps--;
      }
    });
  }

  onSlidesLoaded(hasSlides: boolean): void {
    this.hasSlides = hasSlides;

    if (!hasSlides) {
      this.loadContent();
    }

    this.cdRef.markForCheck();
  }

  @Async()
  private loadContent(): void {
    this.isLoadingContent = true;
    this.contentService
      .getContent('register')
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.isLoadingContent = false;
          this.cdRef.markForCheck();
        }),
        catchError(_ => of(null))
      )
      .subscribe(resource => {
        this.content = resource?.content;
        this.style = resource?.style;
      });
  }

  goBack() {
    if (this.step === 0) {
      this.location.back();
    } else {
      this.accountService.clickRegisterStep(0);
      this.accountService.registerStep.pipe(takeUntil(this.destroy$)).subscribe(x => {
        this.step = x;
        this.cdRef.markForCheck();
      });
    }
  }

  logout() {
    if (this.authService.isAuthenticated()) {
      this.authService.logout();
      this.cdRef.markForCheck();
    }
  }
}
