import { HttpClient } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { Observable } from 'rxjs';
import { tap } from 'rxjs/operators';
import { globalConfiguration } from '@honoregaming/configuration';
import { GeoblockingResponse } from '../models';

@Injectable({ providedIn: 'root' })
export class GeoblockingService {
  private _geoblocking?: GeoblockingResponse;

  public get geoblocking(): GeoblockingResponse | undefined {
    return this._geoblocking;
  }

  constructor(private readonly httpClient: HttpClient) {}

  // Reachable even when the customer is geo-blocked: the endpoint has no RestrictByIpFilter.
  public load(): Observable<GeoblockingResponse> {
    return this.httpClient
      .get<GeoblockingResponse>(`${globalConfiguration.apiBaseUrl}operatordata/geo`)
      .pipe(tap((response: GeoblockingResponse) => (this._geoblocking = response)));
  }
}
