import { Injectable } from '@angular/core';
import { Observable, Subject } from 'rxjs';

export type ToastInput = string | { text: string; action?: () => void; type?: 'add' | 'remove'; id?: string };

@Injectable({
  providedIn: 'root'
})
export class ToasterService {
  private readonly toastSubject: Subject<ToastInput> = new Subject<ToastInput>();
  toast$: Observable<ToastInput> = this.toastSubject.asObservable();

  show(message: ToastInput): void {
    this.toastSubject.next(message);
  }
}
