import { Inject, Injectable } from '@angular/core';
import {
  DepositTax,
  OperatorConfiguration,
  operatorConfigurationToken,
  Tax,
  WithdrawalTax
} from '@honoregaming/configuration';
import { div, mul, sub } from '@honoregaming/core';
import { RoundingMethodType, TaxSummary } from '@honoregaming/types';
import { ceilNumber, floorNumber, preciseFloatingPointNumber, realRoundNumber } from './helpers';

@Injectable({
  providedIn: 'root'
})
export class TaxesService {
  constructor(@Inject(operatorConfigurationToken) private operatorConfiguration: OperatorConfiguration) {}

  getDepositTaxConfiguration(): DepositTax | undefined {
    return this.operatorConfiguration.depositTax;
  }

  getWithdrawalTaxConfiguration(): WithdrawalTax | undefined {
    return this.operatorConfiguration.withdrawalTax;
  }

  computeTaxSummary(tax: Tax, baseAmount: number): TaxSummary {
    const numberOfDecimals: number = this.operatorConfiguration.currency.numberOfDecimals;
    var amountWithoutTax = tax.inverse ? div(baseAmount, 1 + tax.rate) : mul(baseAmount, 1 - tax.rate);

    if (tax.roundingMethod === RoundingMethodType.Up) {
      amountWithoutTax = ceilNumber(amountWithoutTax, numberOfDecimals);
    } else if (tax.roundingMethod === RoundingMethodType.Down) {
      amountWithoutTax = floorNumber(amountWithoutTax, numberOfDecimals);
    } else {
      amountWithoutTax = realRoundNumber(amountWithoutTax, numberOfDecimals);
    }

    return {
      amountWithoutTax: preciseFloatingPointNumber(amountWithoutTax),
      taxAmount: sub(baseAmount, amountWithoutTax)
    };
  }
}
