import { Component, ChangeDetectionStrategy, Input, EventEmitter, Inject, Output } from '@angular/core';
import { operatorConfigurationToken, OperatorConfiguration } from '@honoregaming/configuration';
import { BetLine, BetLineAmount } from '../../../models';

@Component({
  selector: 'hg-draw-games-bet-line',
  templateUrl: './draw-games-bet-line.component.html',
  styleUrls: ['./draw-games-bet-line.component.scss', '../bet-line-content.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class DrawGamesBetLineComponent {
  @Input()
  betLine: BetLine;
  @Input()
  amount: BetLineAmount;
  @Input()
  showIndividualNewStakeMessage: boolean = false;

  @Output()
  amountChange = new EventEmitter<number>();
  @Output()
  remove = new EventEmitter<void>();
  @Output()
  betLineChange = new EventEmitter<BetLine>();

  currency = this.operatorConfiguration.currency.symbol;

  constructor(@Inject(operatorConfigurationToken) private operatorConfiguration: OperatorConfiguration) {}

  onAmountChange(amount: number) {
    this.amountChange.emit(amount);
  }

  onRemove() {
    this.remove.emit();
  }

  setMultiplier(multiplier: number) {
    this.betLineChange.next({
      ...this.betLine,
      multiplier: multiplier
    });
  }
}
