import { Component, ChangeDetectionStrategy, OnInit, Input } from '@angular/core';
import { rouletteResultItems, RouletteItemColor, RouletteItemSize } from '../../../constants/roulette-result-items';

@Component({
  selector: 'hg-roulette-item',
  templateUrl: './roulette-item.component.html',
  styleUrls: ['./roulette-item.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class RouletteItemComponent implements OnInit {
  @Input() number!: number;
  @Input() size!: RouletteItemSize;
  @Input() optionalWidth?: RouletteItemSize;

  color?: RouletteItemColor;

  constructor() {}

  ngOnInit(): void {
    this.color = rouletteResultItems.find(item => item.number === this.number).color;
  }
}
