import { ITelemetryService } from './telemetry-service.model';
import { Injectable, Inject, PLATFORM_ID } from '@angular/core';

import { DOCUMENT, isPlatformBrowser } from '@angular/common';
import { CustomerOperatorConfiguration, customerOperatorConfigurationToken } from '../../models';

declare var window: any;
declare var smartlook: any;
declare var api: any;

@Injectable()
export class SmartLookTelemetryService implements ITelemetryService {
  isBrowser = isPlatformBrowser(this.platformId);

  constructor(
    @Inject(customerOperatorConfigurationToken) private operatorConfig: CustomerOperatorConfiguration,
    @Inject(DOCUMENT) private document: Document,
    @Inject(PLATFORM_ID) private platformId
  ) {
    this.initialize();
  }

  initialize(): void {
    if (this.isLoaded()) {
      console.warn(
        'Tried to initialize a Pixel instance while another is already active. Please call `remove()` before initializing a new instance.'
      );
      return;
    }

    if (this.operatorConfig.telemetryConfiguration.smartlook?.enabled) {
      this.addPixelScript(this.operatorConfig.telemetryConfiguration.smartlook.clientId);
    }
  }

  trackPageView(_name: string, _path: string): void {}

  trackEvent(_: string, __: any): void {}

  private addPixelScript(clientId: string): void {
    if (!isPlatformBrowser(this.platformId)) {
      return;
    }

    const pixelCode = `
  window.smartlook||(function(d) {
    var o=smartlook=function(){ o.api.push(arguments)},h=d.getElementsByTagName('head')[0];
    var c=d.createElement('script');o.api=new Array();c.async=true;c.type='text/javascript';
    c.charset='utf-8';c.src='https://web-sdk.smartlook.com/recorder.js';h.appendChild(c);
    })(document);
    smartlook('init', '${clientId}', { region: 'eu' });`;

    const scriptElement = this.document.createElement('script');
    scriptElement.id = 'smartlook-script';
    scriptElement.type = 'text/javascript';
    scriptElement.innerHTML = pixelCode;
    this.document.body.appendChild(scriptElement);
  }

  private isLoaded(): boolean {
    if (isPlatformBrowser(this.platformId)) {
      const pixelElement = this.document.getElementById('smartlook-script');
      return !!pixelElement;
    }

    return false;
  }
}
