import { ChangeDetectionStrategy, Component, EventEmitter, Output } from '@angular/core';
import { Media, MediaService } from '@honoregaming/ui';

@Component({
  selector: 'hg-bet-slip-freebet-tutorial',
  templateUrl: './bet-slip-freebet-tutorial.component.html',
  styleUrls: ['./bet-slip-freebet-tutorial.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class BetSlipFreebetTutorialComponent {
  @Output()
  close = new EventEmitter();

  currentTutorialStep = 0;

  constructor(private mediaService: MediaService) {}

  closeTutorial() {
    this.close.emit({ disableReleaseBody: this.mediaService.media < Media.lg });
  }

  goToStep(index: number): void {
    if (index === 3) {
      this.closeTutorial();
    }
    this.currentTutorialStep = index;
  }
}
