import {
  Component,
  ChangeDetectionStrategy,
  Inject,
  HostBinding,
  ElementRef,
  ChangeDetectorRef,
  PLATFORM_ID,
  HostListener,
  OnDestroy
} from '@angular/core';
import { isPlatformBrowser } from '@angular/common';

@Component({
  selector: 'hg-scroller-icon',
  templateUrl: './scroller-icon.component.html',
  styleUrls: ['./scroller-icon.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class ScrollerIconComponent implements OnDestroy {
  @HostBinding('class.visible')
  public isVisible: boolean;

  public timer: NodeJS.Timeout;

  @HostListener('window:touchmove', ['$event'])
  touchMoveOnMobile(event) {
    if (event.touches) {
      if (event.targetTouches.length == 1 && window.scrollY > 100) {
        this.setVisible();
      } else {
        this.isVisible = false;
      }
      event.stopPropagation();
    }
  }

  // we use this event to cover the swipe action to the top of the page
  @HostListener('window:touchend', ['$event'])
  touchEndOnMobile(event) {
    setTimeout(() => {
      if (window.scrollY <= 100) {
        this.isVisible = false;
        this.cdRef.markForCheck();
        event.stopPropagation();
      }
    }, 500);
  }

  @HostListener('window:wheel', ['$event'])
  onWindowScroll(event) {
    if (window.scrollY > 200) {
      this.setVisible();
    } else {
      this.isVisible = false;
    }
    event.stopPropagation();
  }

  constructor(
    @Inject(PLATFORM_ID) private platformId,
    private elementRef: ElementRef,
    private cdRef: ChangeDetectorRef
  ) {}

  ngOnDestroy(): void {
    clearTimeout(this.timer);
  }

  public scrollToTop(): void {
    if (isPlatformBrowser(this.platformId)) {
      this.isVisible = false;
      window.scroll({
        top: 0,
        left: 0,
        behavior: 'smooth'
      });
    }
  }

  public setVisible(): void {
    setTimeout(() => {
      this.isVisible =
        this.elementRef.nativeElement.parentNode.getBoundingClientRect().bottom > document.documentElement.clientHeight;
      this.cdRef.markForCheck();

      if (this.isVisible) {
        clearTimeout(this.timer);
        this.timer = setTimeout(() => {
          this.isVisible = false;
          this.cdRef.markForCheck();
        }, 4000);
      }
    });
  }
}
