import { Injectable } from '@angular/core';
import { CanActivate, ActivatedRouteSnapshot, CanActivateChild, RouterStateSnapshot, Router } from '@angular/router';
import { Observable } from 'rxjs';
import { map, take } from 'rxjs/operators';
import { AuthService } from '../services';
import { CustomerState } from '../models';
import { hasFlag } from '@honoregaming/core';
@Injectable()
export class ValidateGuard implements CanActivate, CanActivateChild {
  constructor(private authService: AuthService, private router: Router) {}
  canActivate(_route: ActivatedRouteSnapshot, state: RouterStateSnapshot): Observable<boolean> {
    const isValidationPage =
      state.url.indexOf('step2') !== -1 || state.url.indexOf('step1') !== -1 || state.url.indexOf('unlock') !== -1;
    const isHelpPage = state.url.indexOf('about/content/help') !== -1;
    const isResetPasswordPage = state.url.indexOf('/myaccount/reset-password') !== -1;
    const isRulesPage = state.url.indexOf('about/content/rules') !== -1;

    return this.authService.me$.pipe(
      take(1),
      map(x => {
        if (!x) {
          return true;
        }
        if (x.state === CustomerState.Blacklisted && (isHelpPage || isRulesPage)) {
          return true;
        }
        const isLocked = x.isLocked;
        if (x.isLocked && (isHelpPage || isRulesPage)) {
          return true;
        }

        if (x.mustChangePassword && isResetPasswordPage) {
          return true;
        }

        if (x.mustChangePassword && !isResetPasswordPage && !isHelpPage && !isRulesPage) {
          this.router.navigate(['myaccount', 'reset-password']);
          return false;
        }

        const isValidated = hasFlag(x.state, CustomerState.LoginValidated);
        if (isLocked && !isValidationPage && !isHelpPage && isValidated) {
          this.router.navigate(['myaccount', 'unlock']);
          return false;
        }
        if (isValidated && !isValidationPage) {
          return true;
        }
        if (!isValidated && !isValidationPage && !isHelpPage && !isRulesPage) {
          this.router.navigate(['myaccount', 'registration', 'step2']);
          return false;
        }
        if (!isValidated && isValidationPage) {
          return true;
        }
        return true;
      })
    );
  }
  canActivateChild(
    childRoute: ActivatedRouteSnapshot,
    state: RouterStateSnapshot
  ): boolean | Observable<boolean> | Promise<boolean> {
    return this.canActivate(childRoute, state);
  }
}
