import {
  OnInit,
  ChangeDetectorRef,
  Optional,
  HostBinding,
  Input,
  Output,
  EventEmitter,
  Directive,
  Inject
} from '@angular/core';
import { I18nService } from '@honoregaming/i18n';
import { EventCategory } from '@honoregaming/types';
import { takeUntil, mergeMap, map, skip, finalize } from 'rxjs/operators';
import { MediaService, Media } from '@honoregaming/ui';
import { of, forkJoin, merge, Subscription } from 'rxjs';
import { DestroySubject, AsyncTrigger, Async, Scope } from '@honoregaming/core';
import { ActivatedRoute } from '@angular/router';
import { EventCategoriesService, EventsService } from '@honoregaming/events';
import { OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';

@Directive()
export class EventCategoriesNavigationComponent extends DestroySubject implements OnInit {
  // TODO : emit instead of navigate (child component should never know url)
  @HostBinding('class.open')
  @Input()
  open = false;

  @Output()
  close = new EventEmitter<void>();

  @Output()
  navigated = new EventEmitter<void>();

  @Output()
  toggleMenuEvent = new EventEmitter<{}>();

  @Output() closeMenu = new EventEmitter<void>();

  loading = false;

  hasOddsBoostFeature = this.operatorConfiguration.operatorFeatures.indexOf('OddsBoost') !== -1;
  hasManualOddsFeature = this.operatorConfiguration.operatorFeatures.indexOf('ManualOdds') !== -1;

  hasOddsBoosts = false;
  hasManualOdds = false;

  allCountriesCount: number;

  entryPoints: {
    root: EventCategory;
    eventCategories: EventCategory[];
    loadingEventCategories: boolean;
  }[];
  currentEntryPoint: {
    root: EventCategory;
    eventCategories: EventCategory[];
    topCategories?: EventCategory[];
    loadingEventCategories: boolean;
  };
  selectedEventCategory: EventCategory;
  favoriteCategories: { parentId?: number; category: EventCategory; rootCategoryId?: number }[] = [];

  @AsyncTrigger()
  languageTrigger = this.i18nService.languageChanged$;
  lang: string;

  Scopes = Scope;

  constructor(
    public eventCategoriesService: EventCategoriesService,
    protected eventsService: EventsService,
    @Optional() private mediaService: MediaService,
    protected cdRef: ChangeDetectorRef,
    public i18nService: I18nService,
    protected route: ActivatedRoute,
    public scope: Scope,
    @Inject(operatorConfigurationToken) public operatorConfiguration: OperatorConfiguration
  ) {
    super();
  }

  queryParamsSubscription: Subscription;

  ngOnInit() {
    this.loadEntryPoints();

    if (this.hasManualOddsFeature && this.scope === Scope.Customer) {
      this.getManualOddsBoosts();
    }

    if (this.hasOddsBoostFeature && this.scope === Scope.Customer) {
      this.getOddsBoosts();
    }

    this.languageTrigger.pipe(takeUntil(this.destroy$)).subscribe(lang => {
      this.lang = lang;
      this.cdRef.markForCheck();
    });

    if (this.queryParamsSubscription) {
      this.queryParamsSubscription.unsubscribe();
    }

    this.queryParamsSubscription = this.route.queryParams.subscribe(_ => {
      if (this.route.snapshot['_routerState'].url === '/sports') {
        this.clear();
      }
    });
  }

  getManualOddsBoosts() {
    this.eventsService
      .getManualOddsBoosts()
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.cdRef.markForCheck();
        })
      )
      .subscribe(manualOddsBoosts => {
        if (manualOddsBoosts?.result?.length ?? 0 > 0) {
          this.hasManualOdds = true;
        }
      });
  }

  getOddsBoosts() {
    this.eventsService
      .getOddsBoosts(this.lang)
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.cdRef.markForCheck();
        })
      )
      .subscribe(oddsBoosts => {
        if (oddsBoosts && oddsBoosts.length > 0) {
          this.hasOddsBoosts = true;
        }
      });
  }

  @Async()
  loadEntryPoints() {
    forkJoin([
      this.eventCategoriesService.getEntryPointsForRootEventCategories([3, 9]), // TODO: rendre paramétrable
      this.eventCategoriesService.getFavoriteCategories()
    ])
      .pipe(takeUntil(merge(this.destroy$, this.i18nService.languageChanged$.pipe(skip(1)))))
      .subscribe(([entryPoints, categories]) => {
        this.entryPoints = entryPoints
          .filter(ep => ep.eventsCount)
          .map(ep => {
            return { root: ep, eventCategories: null, loadingEventCategories: false };
          });

        this.favoriteCategories = categories.map(x => ({
          category: x,
          parentId: null,
          rootCategoryId: this.getRootCategoryId(x.path)
        }));

        if (!this.favoriteCategories.length && !this.currentEntryPoint) {
          this.currentEntryPoint = this.entryPoints[0];
        }

        if (this.currentEntryPoint) {
          this.currentEntryPoint = this.entryPoints.filter(x => x.root.id === this.currentEntryPoint.root.id)[0];
          this.toggleEntryPoint(this.currentEntryPoint);
        } else {
          const sportId = this.route.firstChild?.snapshot?.params?.sport;
          if (sportId) {
            const entryPoint = this.entryPoints.filter(x => x.root.id === +sportId);
            if (entryPoint.length === 1) {
              this.currentEntryPoint = entryPoint[0];
              this.toggleEntryPoint(this.currentEntryPoint);
            }
          }
        }
        this.loadDefaultCategoriesForEntryPoint(this.entryPoints[0].root.id);
        this.cdRef.markForCheck();
      });
  }

  private getRootCategoryId(categoryPath: string): number {
    const parentCategoryIds = categoryPath?.split('/').filter(i => i) ?? [];
    return parentCategoryIds.length > 0 ? +parentCategoryIds[0] : null;
  }

  toggleEntryPoint(entryPoint: {
    root: EventCategory;
    eventCategories: EventCategory[];
    loadingEventCategories: boolean;
  }) {
    if (this.currentEntryPoint === entryPoint && entryPoint.eventCategories) {
      return;
    }

    this.currentEntryPoint = entryPoint;

    if (!entryPoint.eventCategories) {
      this.loadCategoriesForEntryPoint();
    }
  }

  @Async()
  loadCategoriesForEntryPoint() {
    if (this.currentEntryPoint) {
      this.currentEntryPoint.loadingEventCategories = true;

      // scope currentEntryPoint
      const currentEntryPoint = this.currentEntryPoint;
      this.eventCategoriesService
        .getCategoriesForEntryPoint(this.currentEntryPoint.root.id)
        .pipe(
          mergeMap(eventCategories =>
            this.mediaService
              ? this.mediaService.media$.pipe(map(media => ({ eventCategories, media })))
              : of({ eventCategories, media: Media.lg })
          )
        )
        .pipe(takeUntil(merge(this.destroy$, this.i18nService.languageChanged$.pipe(skip(1)))))
        .subscribe(({ eventCategories, media }) => {
          currentEntryPoint.topCategories = [...eventCategories].sort((x, y) => (x.priority < y.priority ? -1 : 1));
          currentEntryPoint.topCategories.length =
            currentEntryPoint.topCategories.length > 8 ? 8 : currentEntryPoint.topCategories.length;

          if (eventCategories.length > 6) {
            eventCategories = eventCategories
              .filter(c => currentEntryPoint.topCategories.indexOf(c) === -1)
              .sort((x, y) => {
                return x.name.localeCompare(y.name, undefined, { numeric: true });
              });

            if (media <= Media.md && this.scope !== Scope.Customer) {
              eventCategories.length = eventCategories.length > 6 ? 6 : eventCategories.length;
            }
          } else {
            currentEntryPoint.topCategories = null;
          }

          if (currentEntryPoint.topCategories?.length) {
            currentEntryPoint.topCategories.forEach(tc => {
              tc.subCategories = [...tc.subCategories].sort((x, y) => {
                if (x.priority === y.priority) {
                  return x.name.localeCompare(y.name, undefined, { numeric: true });
                } else {
                  return x.priority < y.priority ? -1 : 1;
                }
              });
            });
          }

          if (eventCategories?.length) {
            eventCategories.forEach(ec => {
              ec.subCategories = [...ec.subCategories].sort((x, y) => {
                if (x.priority === y.priority) {
                  return x.name.localeCompare(y.name, undefined, { numeric: true });
                } else {
                  return x.priority < y.priority ? -1 : 1;
                }
              });
            });
          }

          currentEntryPoint.eventCategories = eventCategories;
          currentEntryPoint.loadingEventCategories = false;
          this.cdRef.markForCheck();
        });
    }
  }

  loadDefaultCategoriesForEntryPoint(id: number) {
    this.eventCategoriesService
      .getCategoriesForEntryPoint(id)
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.cdRef.markForCheck();
        })
      )
      .subscribe(result => {
        this.allCountriesCount = result.length;
      });
  }

  clear() {
    this.currentEntryPoint = null;
    this.selectedEventCategory = null;
    this.close.emit();
    this.cdRef.markForCheck();
  }

  onNavigate() {
    this.navigated.emit();
    this.toggleMenuEvent.emit();
  }
}
