import { Component, ChangeDetectionStrategy, Input, Output, EventEmitter, Inject } from '@angular/core';
import { I18nService } from '@honoregaming/i18n';
import { BetLine, BetLineAmount, FreeBetCouponBetSlip } from '../../../models';
import { getBetLineAmountErrorAndCode } from '../../../utils';
import { Scope, scopeToken } from '@honoregaming/core';

@Component({
  selector: 'hg-odds-boost-bet-line',
  templateUrl: './odds-boost-bet-line.component.html',
  styleUrls: ['./odds-boost-bet-line.component.scss', '../bet-line-content.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class OddsBoostBetLineComponent {
  @Input()
  betLine: BetLine;
  @Input()
  amount: BetLineAmount;
  @Input()
  showIndividualNewStakeMessage: boolean = false;
  @Input()
  acceptOddChange: boolean;

  @Input()
  useFreeBet: boolean = false;

  @Input()
  balance: number = 0;

  @Input()
  selectedFreeBetCoupon: FreeBetCouponBetSlip;

  @Output()
  amountChange = new EventEmitter<number>();
  @Output()
  remove = new EventEmitter<void>();

  errorMessage?: string;
  errorCode?: string;

  constructor(private i18nService: I18nService, @Inject(scopeToken) private userScope: Scope) {}

  onAmountChange(amount: number) {
    this.amountChange.emit(amount);
  }

  onRemove() {
    this.remove.emit();
  }

  isValidAmount() {
    ({ error: this.errorMessage, code: this.errorCode } = getBetLineAmountErrorAndCode(
      this.i18nService,
      this.amount.amount,
      this.betLine.leftoverBalanceAmount || this.betLine.baseAmount,
      this.betLine.leftoverBalanceAmount || this.betLine.maximumAmount,
      this.betLine.leftoverBalanceAmount || this.betLine.minimumAmountIncrement,
      this.showIndividualNewStakeMessage ? this.betLine.newStake : null,
      this.amount.payout,
      this.useFreeBet,
      this.useFreeBet ? this.selectedFreeBetCoupon?.balance ?? 0 : this.balance,
      this.userScope
    ));
    return !this.errorMessage;
  }
}
