import { isPlatformBrowser } from '@angular/common';
import { Component, ChangeDetectionStrategy, OnInit, Inject, PLATFORM_ID, Output, EventEmitter } from '@angular/core';
import { Router } from '@angular/router';
import { globalConfiguration, OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';
import { BroadcastingService, DestroySubject } from '@honoregaming/core';

@Component({
  selector: 'hg-app-banner',
  templateUrl: './app-banner.component.html',
  styleUrls: ['./app-banner.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class AppBannerComponent extends DestroySubject implements OnInit {
  displayforAndroid = false;
  displayforIos = false;
  storageName = 'appBannerDisplay';
  currentOperatorKey = this.operatorConfiguration.key;
  storagePath = globalConfiguration.assetsPath.split('/apps/')[0];

  @Output()
  closeBanner = new EventEmitter<boolean>();

  constructor(
    @Inject(PLATFORM_ID) private platformId,
    @Inject(operatorConfigurationToken) private operatorConfiguration: OperatorConfiguration,
    private router: Router,
    private broadcastingService: BroadcastingService
  ) {
    super();
  }
  ngOnInit() {
    this.detectUserAgent();
    localStorage.setItem(this.storageName, JSON.stringify(false));
  }

  detectUserAgent() {
    if (isPlatformBrowser(this.platformId)) {
      if (/iPad|iPhone|iPod/.test(navigator.userAgent)) {
        this.displayforIos = true;
      } else {
        this.displayforAndroid = true;
      }
    }
  }

  close() {
    localStorage.setItem(this.storageName, JSON.stringify(true));
    this.broadcastingService.broadcast('mobile-banner-closed');

    this.closeBanner.emit(JSON.parse(localStorage.getItem(this.storageName)));
  }

  download() {
    if (this.displayforIos) {
      this.router.navigate(['/about/content/ios-add-shortcut']);
    } else {
      window.location.href =
        this.storagePath + '/android/' + this.currentOperatorKey + '/customer/' + this.currentOperatorKey + '.apk';
    }
  }
}
