import { Inject, Injectable, PLATFORM_ID } from '@angular/core';
import { DOCUMENT } from '@angular/common';
import { isPlatformBrowser } from '@angular/common';

@Injectable({
  providedIn: 'root'
})
export class CanonicalService {
  private isBrowser: boolean = isPlatformBrowser(this.platformId);

  constructor(
    @Inject(DOCUMENT) private readonly document: Document,
    @Inject(PLATFORM_ID) private readonly platformId: Object
  ) {}

  updateCanonicalUrl(routePath: string): void {
    if (!this.isBrowser) {
      return;
    }

    const baseDomain: string = this.document.location.origin;
    const cleanPath: string = routePath.split('?')[0].split('#')[0];
    const fullCanonicalUrl: string = `${baseDomain}${cleanPath === '/' ? '' : cleanPath}`;
    let link: HTMLLinkElement | null = this.document.querySelector('link[rel="canonical"]');

    if (!link) {
      link = this.document.createElement('link');
      link.setAttribute('rel', 'canonical');
      this.document.head.appendChild(link);
    }

    link.setAttribute('href', fullCanonicalUrl);
  }
}
