import { registerLocaleData } from '@angular/common';

export interface LocaleResources {
  translations?: Translations;
  formats?: Format;
  betTypeTranslations?: { [id: number]: string };
}

export interface Format {
  dateFormat: string;
  longDateFormat: string;
  textDateFormat: string;
  shortTextDateFormat: string;
  shortDateFormat: string;
  monthDateFormat: string;
  timeFormat: string;
  longTimeFormat: string;
  decimalSeparator: string;
  thousandSeparator: string;
  currencyFormat: string;
  numberFormat: string;
  shortDayResources: string;
  dayResources: string;
  monthResources: string;
  currencyAsPrefix: boolean;
}

export interface Translations {
  [key: string]: string;
}

export const localeResources: LocaleResources = {};

export function registerStLocale(locale: string, format: Format) {
  // Mapping from :
  // https://github.com/angular/angular/blob/0cb4f12a7a57087ec4e8329a04d5dfc430764b45/packages/common/src/i18n/locale_data.ts#L39
  registerLocaleData([
    locale, // LocaleId
    [['AM', 'PM'], undefined, undefined], // DayPeriodsFormat
    undefined, // DayPeriodsStandalone
    [
      // DaysFormat
      undefined,
      format.dayResources.split(','),
      undefined,
      format.shortDayResources.split(',')
    ],
    undefined, // DaysStandalone
    [
      // MonthsFormat
      undefined,
      undefined,
      format.monthResources.split(',')
    ],
    undefined, // MonthsStandalone
    undefined, // [undefined, undefined, undefined], // Eras
    1, // FirstDayOfWeek
    undefined, // [6, 0], // WeekendRange
    undefined, // ['dd/MM/y', 'd MMM y', 'd MMMM y', 'EEEE d MMMM y'], // DateFormat
    undefined, // ['HH:mm', 'HH:mm:ss', 'HH:mm:ss z', 'HH:mm:ss zzzz'], // TimeFormat
    undefined, // ['{1} {0}', "{1} 'à' {0}", undefined, undefined], // DateTimeFormat
    [format.decimalSeparator, format.thousandSeparator, undefined, '%'], // NumberSymbols
    [format.numberFormat, '#,##0%', format.currencyFormat, undefined], // NumberFormats
    undefined, // CurrencySymbol
    undefined, // CurrencyName
    undefined, // Currencies
    undefined // PluralCase
  ]);
}
