import { ChangeDetectionStrategy, Component, Inject, Input, OnInit } from '@angular/core';
import { FreeBetCouponBetSlip, FreeSpinInstantGame } from '@honoregaming/betslip';
import { globalConfiguration, OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';
import { BetCategoryConfigurationService } from '@honoregaming/core';
import { BetCategoryType, InstantGameProvider, FreeBetCouponState } from '@honoregaming/types';

@Component({
  selector: 'hg-freespin-coupon',
  templateUrl: './freespin-coupon.component.html',
  styleUrls: ['./freespin-coupon.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class FreespinCouponComponent implements OnInit {
  @Input() freespinCoupon: FreeBetCouponBetSlip;

  imageUrl: string;

  // Available Images Count - 1 To handle Modulo = 0
  availableImageCount: number = 27;
  customerAssetPath: string = 'assets/freebets/';
  assetExtension: string = '.jpg';

  baseAssetsPath = this.operatorConfiguration.instantGamesConfiguration.insaGamesAssetsPath;
  instantGamesBetCategoryPath = this.betCategoryConfigurationService.getInstantGamesBetCategoryPath();

  // Types
  BetCategoryType = BetCategoryType;
  gameUrl: string;
  assetsPath: string;
  game: FreeSpinInstantGame;
  FreeBetCouponState = FreeBetCouponState;

  constructor(
    private betCategoryConfigurationService: BetCategoryConfigurationService,
    @Inject(operatorConfigurationToken) private operatorConfiguration: OperatorConfiguration
  ) {}

  ngOnInit(): void {
    const regex = new RegExp(/^(https?:\/\/[^\/]+)/); // Permet de matcher l'url de base
    const matches = regex.exec(globalConfiguration.assetsPath);
    this.assetsPath = matches ? matches[0] : '';
    this.game = this.freespinCoupon.freeSpinInfos.instantGame;

    switch (this.game.provider) {
      case InstantGameProvider.InsaGames:
        this.gameUrl = `/${this.instantGamesBetCategoryPath}` + this.game.url;
        this.imageUrl = `${this.baseAssetsPath}${this.game.name.toLowerCase()}/thumbnail.png`;
        break;
      case InstantGameProvider.EveryMatrix:
        this.imageUrl = this.game.imageUrl;
        this.gameUrl = `/${this.instantGamesBetCategoryPath}` + this.game.url;
        break;
      case InstantGameProvider.GameTech:
        this.imageUrl = !this.game.imageUrl?.startsWith('http')
          ? `${this.assetsPath}/instant-game-providers/${this.game.imageUrl}`
          : this.game.imageUrl;
        break;
      case InstantGameProvider.AviatorLlc:
        this.imageUrl = this.game.imageUrl;
        this.gameUrl = `/${this.instantGamesBetCategoryPath}` + this.game.url;
        break;
      case InstantGameProvider.BoomingGames:
        this.imageUrl = this.game.imageUrl;
        this.gameUrl = `/${this.instantGamesBetCategoryPath}` + this.game.url;
        break;
      default:
        break;
    }

    if (!this.imageUrl) {
      this.getCouponImage();
    }
  }

  private getCouponImage() {
    const moduloIndex = (this.freespinCoupon.id % this.availableImageCount) + 1;
    this.imageUrl = this.customerAssetPath + moduloIndex + this.assetExtension;
  }
}
