import { Directive, OnChanges, Input, SimpleChanges, ElementRef } from '@angular/core';

@Directive({
  selector: '[hgGoalAnimation]'
})
export class GoalAnimationDirective implements OnChanges {
  @Input() public hgGoalAnimation: any;
  @Input() public hgGoalAnimationPosition: 'left' | 'right';
  @Input() public hgGoalAnimationSkip: boolean;

  constructor(private elementRef: ElementRef) {}

  ngOnChanges(changes: SimpleChanges) {
    if (this.hgGoalAnimationSkip) {
      (this.elementRef.nativeElement as HTMLElement).classList.remove('blinking');
      return;
    }

    if (
      changes.hgGoalAnimation &&
      changes.hgGoalAnimation.previousValue !== undefined &&
      changes.hgGoalAnimation.currentValue !== changes.hgGoalAnimation.previousValue
    ) {
      (this.elementRef.nativeElement as HTMLElement).classList.add('blinking');
      const imageGoalAnimation = document.createElement('object');
      imageGoalAnimation.type = 'image/svg+xml';
      imageGoalAnimation.classList.add(
        'goal-animation-simulated-mode',
        `goal-animation-simulated-mode--${this.hgGoalAnimationPosition}`
      );
      imageGoalAnimation.data = 'assets/goal-animation-simulated-mode.svg';
      (this.elementRef.nativeElement as HTMLElement).insertAdjacentElement('beforebegin', imageGoalAnimation);
      setTimeout(() => {
        (this.elementRef.nativeElement as HTMLElement).classList.remove('blinking');
        imageGoalAnimation.remove();
      }, 1500);
    }
  }
}
