import {
  Component,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Input,
  Output,
  EventEmitter,
  OnChanges,
  OnInit,
  Inject,
  TemplateRef
} from '@angular/core';
import { takeUntil } from 'rxjs/operators';
import { CreateBetCodeRequest } from '@honoregaming/betslip';
import { OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';
import {
  DestroySubject,
  getUtcNow,
  happenBefore,
  BetLinesMapperService,
  BetBuilderService,
  BetHistoryService,
  add
} from '@honoregaming/core';
import {
  BetCategoryType,
  BetLineHistory,
  BetLineStateType,
  BetState,
  BetSystemHistory,
  BetSystemType,
  EventStateType,
  ManualOddsBoostBetLineDetail,
  OddsBoostBetLineDetail,
  PreEventOrLiveType,
  Score
} from '@honoregaming/types';

const PERIOD_SCORE_PATTERN = /^Period[1-9]|^PeriodOvertime/;
const DEFAULT_VISIBLE_LINES = 3;

@Component({
  selector: 'hg-match-bet-system',
  templateUrl: './match-bet-system.component.html',
  styleUrls: ['./match-bet-system.component.scss', '../generic-bet-system.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class MatchBetSystemComponent extends DestroySubject implements OnInit, OnChanges {
  @Input() betSystem!: BetSystemHistory;
  @Input() shouldDisplayBetCodeButton: boolean;
  @Input() isGettingBetCode: boolean;
  @Input() canRebet: boolean;
  @Input() hideSection: boolean;
  @Input() isTicket: boolean = false;

  @Output() getBetCode = new EventEmitter<{ betCodeRequest: CreateBetCodeRequest; totalOdds: string }>();
  @Output() cashout = new EventEmitter<number>();
  @Output() rebet = new EventEmitter<BetSystemHistory>();
  @Output() completeMyBet = new EventEmitter<void>();

  isOddsBoost: boolean = false;
  isManualOddsBoost: boolean = false;
  firstEventDate?: Date;
  allBetLinesArePending: boolean = false;
  containsPreEventWithExpectedStartInPast: boolean = false;
  totalOdds: string | null = null;
  visibleBetLines: BetLineHistory[] = [];
  displayRebet: boolean = false;
  betBuilderModeLabel: string = '';
  betLinesVisible: boolean = true;
  reducedFormatApplies: boolean = false;

  BetLineStateType = BetLineStateType;
  BetSystemType = BetSystemType;
  EventStateType = EventStateType;
  BetState = BetState;

  private limitNumber: number = DEFAULT_VISIBLE_LINES;
  private readonly betHistoryReducedFormatEnabled: boolean = this.betHistoryService.reducedFormatEnabled;

  constructor(
    private readonly betLinesMapperService: BetLinesMapperService,
    private readonly betBuilderService: BetBuilderService,
    private readonly betHistoryService: BetHistoryService,
    private readonly cdRef: ChangeDetectorRef,
    @Inject(operatorConfigurationToken) private readonly operatorConfiguration: OperatorConfiguration
  ) {
    super();
    this.betLinesVisible = !this.betHistoryReducedFormatEnabled || this.betHistoryService.expandedFormat;
  }

  ngOnInit(): void {
    this.subscribeToExpandedFormat();
  }

  ngOnChanges(): void {
    const { betSystem } = this;

    if (!betSystem?.betLines) {
      return;
    }

    const { betLines } = betSystem;
    const now: Date = getUtcNow();

    if (betLines.length > this.limitNumber) {
      betSystem.isCollapsed = false;
    }

    this.allBetLinesArePending = betLines.every(bl => this.isBetLinePendingAndStarted(bl, now));

    this.containsPreEventWithExpectedStartInPast = betLines.some(
      (bl: BetLineHistory) =>
        bl.preEventOrLive === PreEventOrLiveType.PreEvent && happenBefore(now, new Date(bl.eventDate), 0)
    );

    this.isOddsBoost = !!betLines[0]?.oddsBoostDetails;
    this.isManualOddsBoost = !!betLines[0]?.manualOddsBoostDetails;
    this.firstEventDate = this.computeFirstEventDate(betLines[0]);

    this.displayRebet = this.computeDisplayRebet(betSystem, betLines, now);

    this.betBuilderModeLabel =
      betLines.length === 1 && betLines[0].betBuilderLines?.length ? this.betBuilderService.productName : '';

    this.totalOdds = this.computeTotalOdds();
    this.computeAllScores(betLines);

    this.reducedFormatApplies = this.betHistoryReducedFormatEnabled && betSystem.type === BetSystemType.Multiple;
    this.visibleBetLines = this.reducedFormatApplies ? betLines : betLines.slice(0, this.limitNumber);
  }

  onGetBetCode(betSystemId: number): void {
    const { betLines, type, totalStake, betCategory, bettingTaxAmount } = this.betSystem;
    const eventBetTypeItemIds: number[] = this.betLinesMapperService.betLinesHistoryToEventBetTypeItemIds(betLines);
    const oddsBoostId: number | undefined = betLines.find(bl => !!bl.oddsBoostId)?.oddsBoostId;
    const manualOddsBoostId: number | undefined = betLines.find(bl => !!bl.manualOddsBoostId)?.manualOddsBoostId;
    const hasBetBuilderBetLines: boolean = betLines.some((bl: BetLineHistory) => !!bl.betBuilderLines?.length);

    this.getBetCode.emit({
      betCodeRequest: {
        betSystemId,
        betSystemType: type,
        totalStake: add(totalStake ?? 0, bettingTaxAmount ?? 0),
        betCategory,
        eventBetTypeItemIds,
        oddsBoostId,
        manualOddsBoostId,
        hasBetBuilderBetLines
      },
      totalOdds: this.totalOdds
    });
  }

  onRebet(): void {
    this.rebet.emit(this.betSystem);
  }

  onCompleteMyBet(): void {
    this.completeMyBet.emit();
  }

  onCashout(): void {
    this.cashout.emit(this.betSystem.id);
  }

  toggleBetLines(): void {
    this.betLinesVisible = !this.betLinesVisible;
  }

  showMore(): void {
    this.betSystem.isCollapsed = !this.betSystem.isCollapsed;
    this.limitNumber = this.betSystem.isCollapsed ? this.betSystem.betLines.length : DEFAULT_VISIBLE_LINES;
    this.visibleBetLines = this.betSystem.betLines.slice(0, this.limitNumber);
  }

  trackByIndex(index: number): number {
    return index;
  }

  getBetLineTemplate(
    betLine: BetLineHistory,
    base: TemplateRef<unknown>,
    oddsBoost: TemplateRef<unknown>,
    manualOddsBoost: TemplateRef<unknown>
  ): TemplateRef<unknown> {
    if (betLine.manualOddsBoostDetails) return manualOddsBoost;
    if (betLine.oddsBoostDetails) return oddsBoost;
    return base;
  }

  private subscribeToExpandedFormat(): void {
    // Reduced format relies on the header toggle, which is not rendered when the section is hidden
    if (!this.betHistoryReducedFormatEnabled || this.hideSection) {
      this.betLinesVisible = true;
      return;
    }

    if (this.betSystem.type !== BetSystemType.Multiple) {
      this.betLinesVisible = true;
      return;
    }

    this.betHistoryService.expandedFormat$.pipe(takeUntil(this.destroy$)).subscribe(expandedFormat => {
      this.betLinesVisible = expandedFormat;
      this.cdRef.markForCheck();
    });
  }

  private isBetLinePendingAndStarted(bl: BetLineHistory, now: Date): boolean {
    return (
      bl.state === BetLineStateType.Pending &&
      this.allBoostDetailsStarted(bl.manualOddsBoostDetails, now) &&
      this.allBoostDetailsStarted(bl.oddsBoostDetails, now)
    );
  }

  private allBoostDetailsStarted(
    details: OddsBoostBetLineDetail[] | ManualOddsBoostBetLineDetail[] | undefined,
    now: Date
  ): boolean {
    return !details || details.every(detail => happenBefore(new Date(detail.expectedStart), now, 0));
  }

  private computeDisplayRebet(betSystem: BetSystemHistory, betLines: BetLineHistory[], now: Date): boolean {
    return (
      this.canRebet &&
      this.operatorConfiguration.operatorFeatures.includes('Rebet') &&
      betSystem.betCategory === BetCategoryType.SportsFixedOdds &&
      betLines.some(
        bl =>
          this.isBetLinePendingAndStarted(bl, now) &&
          !(bl.preEventOrLive === PreEventOrLiveType.PreEvent && happenBefore(now, new Date(bl.eventDate), 0))
      )
    );
  }

  private computeFirstEventDate(firstBetLine: BetLineHistory): Date | undefined {
    const details: ManualOddsBoostBetLineDetail[] | OddsBoostBetLineDetail[] =
      firstBetLine?.manualOddsBoostDetails ?? firstBetLine?.oddsBoostDetails;
    if (!details?.length) return undefined;

    return details.reduce((earliest, current) => (current.expectedStart < earliest.expectedStart ? current : earliest))
      .expectedStart;
  }

  private computeTotalOdds(): string | null {
    const { type, betLines } = this.betSystem;

    if (type === BetSystemType.Multiple) {
      return betLines.reduce((sum, l) => sum * l.odds, 1).toFixed(2);
    }

    if (type === BetSystemType.Simple && betLines.length === 1 && betLines[0].odds) {
      return betLines[0].odds.toFixed(2);
    }

    return null;
  }

  private computeAllScores(betLines: BetLineHistory[]): void {
    if (!betLines.length) return;

    if (betLines[0].oddsBoostDetails) {
      for (const line of betLines) {
        for (const detail of line.oddsBoostDetails) {
          this.computeScores(detail);
        }
      }
    } else {
      for (const line of betLines) {
        this.computeScores(line);
      }
    }
  }

  private computeScores(betLine: BetLineHistory | OddsBoostBetLineDetail): void {
    if (betLine.entryPointId !== 101) {
      betLine.homeScore = Number(betLine.homeTeamScore);
      betLine.awayScore = Number(betLine.awayTeamScore);
      return;
    }

    const matchScores: Score[] = betLine.scores.filter(score => PERIOD_SCORE_PATTERN.test(score.type));
    if (!matchScores.length) return;

    betLine.homeScore =
      matchScores.reduce((acc, s) => acc + (+s.homeTeamScore || 0), 0) || Number(betLine.homeTeamScore) || 0;
    betLine.awayScore =
      matchScores.reduce((acc, s) => acc + (+s.awayTeamScore || 0), 0) || Number(betLine.awayTeamScore) || 0;
  }
}
