import { mul, div, mod } from '@honoregaming/core';

export function ppcm(a: number, b: number): number {
  return div(mul(a, b), pgcd(a, b));
}

export function ppcmArr(v: number[]): number {
  if (v.length < 2) {
    return -1;
  }
  let result = ppcm(v[0], v[1]);
  for (let i = 2; i < v.length; i++) {
    result = ppcm(result, v[i]);
  }

  return result;
}

export function pgcd(a: number, b: number): number {
  return b === 0 ? a : pgcd(b, mod(a, b));
}
