import { InjectionToken } from '@angular/core';
import { SecurityPolicy } from '@honoregaming/types';
import { Observable } from 'rxjs';

export interface ICaptchaService {
  loadCaptcha(securityPolicy: SecurityPolicy): void;
  applyCaptcha(targetElement: string): Observable<void>;
  validateCaptcha(): Observable<string>;
  getLegend(): string;
  clearCaptcha(): void;
}

export const captchaServiceToken = new InjectionToken<ICaptchaService>('ICaptchaService');
