import {
  Component,
  OnInit,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  ViewChild,
  Inject,
  OnDestroy,
  Optional
} from '@angular/core';
import {
  CustomerService,
  ICaptchaService,
  NavigationService,
  PasswordService,
  captchaServiceToken
} from '@honoregaming/customer-core';
import { ResetPasswordFailures } from './models/failures.enum';
import { NgForm } from '@angular/forms';
import { finalize, map, switchMap, takeUntil } from 'rxjs/operators';
import { HttpErrorResponse } from '@angular/common/http';
import { PasswordPolicy, SecurityPolicy } from '@honoregaming/types';
import { ApplicationStateService, AsyncTrigger, DestroySubject } from '@honoregaming/core';
import { I18nService } from '@honoregaming/i18n';
import { Media, MediaService } from '@honoregaming/ui';

@Component({
  selector: 'hg-lost-password',
  templateUrl: './lost-password.component.html',
  styleUrls: ['./lost-password.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class LostPasswordComponent extends DestroySubject implements OnInit, OnDestroy {
  login: string;
  loginWithoutPrefix: string;
  resetLogin: string;
  validationCode: string;
  newPassword: string;
  confirmPassword: string;
  changeDone = false;
  securityPolicy: SecurityPolicy;
  loadingSendCode: boolean;
  loadingValidateCode: boolean;
  loadingCustomer: boolean;
  customerNotFound: boolean;
  showPasswordValue = false;
  showConfirmPasswordValue = false;
  redirectToLoginPanel = false;

  codeFormError: boolean;
  codeFormRestrictionDate: Date;
  resetFormError: boolean;
  resetFormTooMany: boolean = false;
  codeSentAnyway: boolean = false;
  codevalidated: boolean = false;

  passwordPolicyRequirements: PasswordPolicy;
  hasDigit: boolean;
  hasNonLetterOrDigit: boolean;
  hasLowerCharacter: boolean;
  hasUppercharacter: boolean;
  hasPasswordLength: boolean;
  hasConsecutiveNumberSequence: boolean;
  hasConsecutiveLetterSequence: boolean;
  hasSameCharacterRepeated: boolean;
  isEqualToLogin: boolean;
  requiredLength: number;
  requireLowercase: boolean;
  requireUppercase: boolean;
  requireDigit: boolean;
  requireNonLetterOrDigit: boolean;
  preventConsecutiveSequence: boolean;
  preventSameCharacterRepeated: boolean;
  preventEqualToLogin: boolean;
  codeRequestedSuccessfully: boolean;
  prefixes: string[];

  passwordLengthError = false;
  passwordDigitError = false;
  passwordLowercaseError = false;
  passwordNonLetterOrError = false;
  passwordUppercaseError = false;

  isLoading = true;
  content: string;
  style: string;
  step = 1;
  fullSteps = 3;
  codeLength = 5;

  @ViewChild('formReset')
  resetForm: NgForm;

  @ViewChild('formCode')
  codeForm: NgForm;

  recaptchaLegend: string;

  @AsyncTrigger()
  languageTrigger = this.i18nService.languageChanged$;

  constructor(
    private readonly customerService: CustomerService,
    private readonly cdRef: ChangeDetectorRef,
    private readonly i18nService: I18nService,
    private readonly navigationService: NavigationService,
    @Optional() private readonly mediaService: MediaService,
    @Inject(captchaServiceToken) private readonly captchaService: ICaptchaService,
    private readonly appState: ApplicationStateService,
    private readonly passwordService: PasswordService
  ) {
    super();
  }

  ngOnInit() {
    this.appState.isReady$
      .pipe(
        switchMap(() => this.customerService.getSecurityPolicy()),
        takeUntil(this.destroy$),
        map(policy => {
          this.securityPolicy = policy;
          this.cdRef.markForCheck();
        }),
        switchMap(() => {
          return this.captchaService.applyCaptcha('#ask-reset-button,#already-has-code');
        })
      )
      .subscribe(_ => {
        this.recaptchaLegend = this.captchaService.getLegend();
        this.cdRef.markForCheck();
      });

    this.customerService.getSecurityPolicy().subscribe(x => {
      this.securityPolicy = x;
      this.passwordPolicyRequirements = this.securityPolicy.passwordPolicyRequirements;
      this.prefixes = this.securityPolicy.loginPoliciesRequirements.map(r => r.prefix);
      this.requireLowercase = this.passwordPolicyRequirements.requireLowercase;
      this.requireUppercase = this.passwordPolicyRequirements.requireUppercase;
      this.requireDigit = this.passwordPolicyRequirements.requireDigit;
      this.requiredLength = this.passwordPolicyRequirements.requiredLength;
      this.requireNonLetterOrDigit = this.passwordPolicyRequirements.requireNonLetterOrDigit;
      this.preventConsecutiveSequence = this.passwordPolicyRequirements.preventConsecutiveSequence;
      this.preventSameCharacterRepeated = this.passwordPolicyRequirements.preventSameCharacterRepeated;
      this.preventEqualToLogin = this.passwordPolicyRequirements.preventEqualToLogin;
      this.cdRef.markForCheck();
    });

    this.mediaService?.media$.subscribe(x => {
      this.redirectToLoginPanel = x <= Media.md;
    });
  }

  ngOnDestroy(): void {
    this.captchaService.clearCaptcha();
  }

  alreadyHasCode(login: string) {
    if (!login || this.loadingCustomer) {
      return;
    }

    this.loadingCustomer = true;
    this.login = login;

    this.captchaService
      .validateCaptcha()
      .pipe(takeUntil(this.destroy$))
      .subscribe(token => this.submitCheckIfCustomerExists(token));
  }

  submitCheckIfCustomerExists(recaptchaToken: string) {
    this.codeFormError = false;
    this.customerNotFound = false;
    this.codeFormRestrictionDate = null;
    this.codeSentAnyway = false;
    this.codeRequestedSuccessfully = false;

    this.customerService
      .checkIfCustomerExists(this.login, recaptchaToken)
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.loadingCustomer = false;
          this.cdRef.markForCheck();
        })
      )
      .subscribe(
        r => {
          if (r) {
            this.step = 2;
            this.resetFormTooMany = false;
            this.changeDone = false;
            this.resetLogin = this.login;
          } else {
            this.customerNotFound = true;
          }
        },
        error => this.handleError(error)
      );
  }

  requestResetCode(login: string) {
    if (!login || this.loadingSendCode) {
      return;
    }

    this.loadingSendCode = true;
    this.login = login;
    this.loginWithoutPrefix = this.getLoginOnly();

    this.captchaService
      .validateCaptcha()
      .pipe(takeUntil(this.destroy$))
      .subscribe(token => this.submitRequestResetCode(token));
  }

  private submitRequestResetCode(recaptchaToken: string) {
    this.codeFormError = false;
    this.customerNotFound = false;
    this.codeFormRestrictionDate = null;
    this.codeSentAnyway = false;
    this.codeRequestedSuccessfully = false;

    this.customerService
      .getResetCode(this.login, recaptchaToken)
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.loadingSendCode = false;
          this.cdRef.markForCheck();
        })
      )
      .subscribe(
        () => {
          this.step = 2;
          this.resetFormTooMany = false;
          this.changeDone = false;
          this.resetLogin = this.login;
          this.codeRequestedSuccessfully = true;
          this.cdRef.markForCheck();
        },
        error => this.handleError(error)
      );
  }

  validateCode() {
    if (this.loadingValidateCode) {
      return;
    }

    this.resetFormError = false;
    this.loadingValidateCode = true;

    this.customerService
      .resetCheckValidationCode(this.resetLogin, this.validationCode)
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.cdRef.markForCheck();
          this.loadingValidateCode = false;
        })
      )
      .subscribe(
        () => {
          this.step = 3;
          this.codevalidated = true;
          this.cdRef.markForCheck();
        },
        error => this.handleError(error)
      );
  }

  resetPassword() {
    if (this.loadingValidateCode) {
      return;
    }

    this.codevalidated = false;
    this.resetFormError = false;
    this.codeSentAnyway = false;
    this.loadingValidateCode = true;

    this.customerService
      .resetPassword(this.resetLogin, this.validationCode, this.newPassword)
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.cdRef.markForCheck();
          this.loadingValidateCode = false;
        })
      )
      .subscribe(
        () => {
          this.changeDone = true;

          if (this.redirectToLoginPanel) {
            setTimeout(() => {
              this.goToLoginPanel();
            }, 4000);
          }

          this.cdRef.markForCheck();
        },
        error => this.handleError(error)
      );
  }

  handleError(error: HttpErrorResponse) {
    this.captchaService.clearCaptcha();
    this.captchaService.applyCaptcha('#ask-reset-button,#already-has-code').subscribe();

    if (error.status === 404) {
      if (this.resetForm) {
        this.resetForm.controls['resetLogin']?.setErrors({ loginPolicy: 'NOTFOUND' });
      } else {
        this.codeForm.controls['login']?.setErrors({ loginPolicy: 'NOTFOUND' });
      }
    } else if (error.status === 400) {
      const failure: ResetPasswordFailures = error.error.code;
      switch (failure) {
        case ResetPasswordFailures.IncorrectValidationCode:
        case ResetPasswordFailures.ExpiredValidationCode:
          this.resetForm.controls['validationCode'].setErrors({
            validationCode: ResetPasswordFailures[failure].toUpperCase()
          });
          break;
        case ResetPasswordFailures.PasswordRequireDigit:
          this.passwordDigitError = true;
          break;
        case ResetPasswordFailures.PasswordRequiredLength:
          this.passwordLengthError = true;
          break;
        case ResetPasswordFailures.PasswordRequireLowercase:
          this.passwordLowercaseError = true;
          break;
        case ResetPasswordFailures.PasswordRequireNonLetterOrDigit:
          this.passwordNonLetterOrError = true;
          break;
        case ResetPasswordFailures.PasswordRequireUppercase:
          this.passwordUppercaseError = true;
          this.resetForm.controls['newPassword'].setErrors({
            passwordPolicy: ResetPasswordFailures[failure].toUpperCase()
          });
          break;
        case ResetPasswordFailures.ValidationCodeTooManyAttempts:
          this.resetFormTooMany = true;
          break;
        case ResetPasswordFailures.CustomerNotFound:
          this.resetForm.controls['resetLogin']?.setErrors({ loginPolicy: 'NOTFOUND' });
          break;
      }
    } else if (error.status === 500) {
      this.codeSentAnyway = true;
    } else if (error.error?.additionalData?.endRestrictionDate != null) {
      this.codeFormRestrictionDate = new Date(error.error.additionalData.endRestrictionDate);
    } else {
      if (this.resetForm) {
        this.resetFormError = true;
      } else {
        this.codeFormError = true;
      }
    }

    this.cdRef.markForCheck();
  }

  checkPasswordRules(password: string) {
    const result = this.passwordService.checkPassword(password, this.loginWithoutPrefix);

    this.hasConsecutiveLetterSequence = result.hasConsecutiveLetterSequence;
    this.hasDigit = result.hasDigital;
    this.hasLowerCharacter = result.hasLowerCharacter;
    this.hasUppercharacter = result.hasUppercharacter;
    this.hasConsecutiveNumberSequence = result.hasConsecutiveNumberSequence;
    this.hasSameCharacterRepeated = result.hasSameCharacterRepeated;
    this.isEqualToLogin = result.isEqualToLogin;
    this.hasPasswordLength = result.hasPasswordLength;
    this.hasNonLetterOrDigit = result.hasNonLetterOrDigit;

    this.cdRef.markForCheck();
  }

  getLoginOnly(): string {
    const prefix = this.prefixes?.find(p => this.login.startsWith(p));

    if (prefix) {
      return this.login.replace(prefix, '');
    }

    return this.login;
  }

  goToLoginPanel() {
    this.navigationService.goToMyAccount();
  }
}
