import { Injectable } from '@angular/core';
import { fromEvent, merge, Subject, Observable, Subscription } from 'rxjs';
import { throttleTime } from 'rxjs/operators';

@Injectable()
export class IdleService {
  constructor() {}

  private timeout$ = new Subject<void>();
  private timeout;

  private subscription: Subscription;

  startWatching(idleTime: number): Observable<void> {
    this.startTimer(idleTime);
    const activity = merge(
      fromEvent(window, 'mousemove', { passive: true }),
      fromEvent(window, 'keypress', { passive: true }),
      fromEvent(window, 'touchstart', { passive: true })
    );

    this.subscription = activity.pipe(throttleTime(5000)).subscribe(() => {
      this.stopTimer();
      this.startTimer(idleTime);
    });

    return this.timeout$.asObservable();
  }

  public stopWatching() {
    this.stopTimer();
    this.subscription?.unsubscribe();
  }

  private startTimer(timeout: number) {
    this.timeout = setTimeout(() => this.timeout$.next(), timeout);
  }

  private stopTimer() {
    clearTimeout(this.timeout);
  }
}
