import { add, sub, div, mul, mod } from '../../utils/currency.utils';

type AbstractConstructor<T = {}> = abstract new (...args: any[]) => T;

export function CurrencyMathMixin<TBase extends AbstractConstructor>(Base: TBase) {
  abstract class CurrencyMath extends Base {
    add = add;
    sub = sub;
    div = div;
    mul = mul;
    mod = mod;
  }

  return CurrencyMath;
}
