import { Component, ChangeDetectionStrategy, Input, OnInit, ChangeDetectorRef } from '@angular/core';
import {
  IsDrawGameWithPrizes,
  IsDrawGameWithOptions,
  GetMissingZerosPrefix,
  GetNumberOfDigitsPerWinningNumber,
  FormatMariageSelectionWithXSeparator,
  DestroySubject
} from '@honoregaming/core';
import { EventsService } from '@honoregaming/events';
import { I18nService } from '@honoregaming/i18n';
import { BetLineHistory } from '@honoregaming/types';
import { DrawGameBorletteBetType } from '@honoregaming/types';
import { takeUntil } from 'rxjs/operators';

@Component({
  selector: 'hg-draw-game-bettype-selection',
  templateUrl: './draw-game-bettype-selection.component.html',
  styleUrls: ['./draw-game-bettype-selection.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class DrawGameBettypeSelectionComponent extends DestroySubject implements OnInit {
  @Input()
  baseList: any[];

  @Input()
  extraList: number[];

  @Input()
  selectionDigest: string;

  @Input()
  totalStake: number;

  @Input()
  quickPick: boolean;

  @Input()
  betLine: BetLineHistory;

  @Input()
  associatedEventsIds: BetLineHistory;

  drawGameWithPrizesResults: boolean = false;
  drawGameWithOptionsResults: boolean = false;
  selectedOption: string = '';
  associatedDrawGameName?: string = '';
  associatedDrawGameDate?: Date;

  constructor(
    private eventsService: EventsService,
    private cdRef: ChangeDetectorRef,
    private readonly i18nService: I18nService
  ) {
    super();
  }

  ngOnInit() {
    this.drawGameWithOptionsResults = IsDrawGameWithOptions(this.betLine.betTypeId);
    this.drawGameWithPrizesResults = IsDrawGameWithPrizes(this.betLine.betTypeId);

    if (this.drawGameWithPrizesResults || this.drawGameWithOptionsResults) {
      let numberPlayed = this.baseList[0].toString();

      if (this.drawGameWithOptionsResults) {
        numberPlayed = this.baseList[0].toString().split('/')[0].trim();
        this.selectedOption = this.selectionDigest.split('/')[1].trim();
      } else if (this.betLine.betTypeId === DrawGameBorletteBetType.Mariage) {
        // baselist contains the lowest number between number played and it's reverse value
        // selection digest always contains number played
        numberPlayed = this.betLine.selectionDigest.trim();
      } else if (this.betLine.betTypeId === DrawGameBorletteBetType.DoubChans) {
        this.getAssociatedDrawGameInfo(+this.selectionDigest.split('&')[1].split(' ')[1]);
      }

      let targetDigitNumber = GetNumberOfDigitsPerWinningNumber(this.betLine.betTypeId);
      if (this.betLine.betTypeId === DrawGameBorletteBetType.Loto6) {
        this.baseList = [
          this.formatNumber(this.baseList[0].toString(), targetDigitNumber),
          this.formatNumber(this.baseList[1].toString(), targetDigitNumber),
          this.formatNumber(this.baseList[2].toString(), targetDigitNumber)
        ];
      } else if (this.betLine.betTypeId === DrawGameBorletteBetType.DoubChans) {
        this.baseList = [
          this.formatNumber(this.baseList[0].toString(), targetDigitNumber),
          this.formatNumber(this.baseList[1].toString(), targetDigitNumber)
        ];
      } else {
        let digestWithMissingZeros = this.formatNumber(numberPlayed, targetDigitNumber);
        if (this.betLine.betTypeId === DrawGameBorletteBetType.Mariage) {
          digestWithMissingZeros = FormatMariageSelectionWithXSeparator(digestWithMissingZeros);
        }

        this.baseList[0] = digestWithMissingZeros;
      }
    }
  }

  formatNumber(number: string, targetDigitNumber: number): string {
    return GetMissingZerosPrefix(Number(number), targetDigitNumber) + +number;
  }

  getAssociatedDrawGameInfo(id: number): void {
    this.eventsService
      .getEventFromCacheOrService(id)
      .pipe(takeUntil(this.destroy$))
      .subscribe(x => {
        if (x?.name) {
          this.associatedDrawGameName = x.name;
          this.associatedDrawGameDate = x.expectedStart;
        } else {
          this.associatedDrawGameName = this.i18nService.translateSync('DRAW_GAMES.UNAVAILABLE');
        }

        this.cdRef.markForCheck();
      });
  }
}
