import { EventStateDetailsType, SelectableEventBetTypeItem, SportsPoolBet } from '@honoregaming/types';
import { EventBetType } from '../event-bet-type.model';
import { MatchData, Score } from '../match';
import { Match } from '../match.model';

export interface SportsPoolGame {
  id: number;
  name: string;
  expectedStart: Date;
  expectedEnd: Date;
  previousId?: number;
  nextId?: number;
  matchPositions: SportsPoolGameMatch[];
  details: SportsPoolGameDetails;
  entryPointId: number;
  eventBetTypeId: number;
  hasOnGoingGame: boolean;
}

export interface SportsPoolGameMatch {
  eventBetType: EventBetType;
  event: Match;
  position: number;
  id: number;
  reserved: boolean;
  homeTeamScore?: string;
  awayTeamScore?: string;
  scores?: Score[];
  data?: MatchData;
  eligible: boolean;
  cancelled: boolean;
  delayed: boolean;
}

export interface SportsPoolGameDetails {
  name: string;
  baseAmount: number;
  matchCount: number;
  reservedMatchCount: number;
  maximumDoubleCount: number;
  maximumTripleCount: number;
  poolAmount: number;
  poolRepartitions: PoolRepartition[];
}

export enum SportsPoolGameState {
  Undisputed,
  InProgress,
  Finished
}

export interface SportsPoolGameResult {
  id: number;
  name: string;
  detailsName: string;
  poolAmount: number;
  expectedStart: Date;
  matchCount: number;
  inProgress: boolean;
  hasOnGoingGame: boolean;
  winnersCount: number;
  totalWinnings: number;
}

export interface SelectedSportsPoolGameItem {
  id: number;
  odds: number;
  betTypeItemId: number;
  matchId: number;
  shortName: string;
  matchPosition: number;
  eventName: string;
  eventId: number;
}

export interface SportsPoolResultsResponse {
  pagination: {
    pageIndex: number;
    offset: number;
    hasMore: boolean;
  };
  items: SportsPoolGameResult[];
}

export enum SportsPoolFlashType {
  Random = 'Random',
  BiggestDistribution = 'BiggestDistribution',
  LowestOdds = 'LowestOdds',
  HighestOdds = 'HighestOdds'
}

export interface PoolRepartition {
  prize: number;
  winningMatchesCount: number;
  winnersCount?: number;
}

export interface SportsPoolGameMatchLive {
  id: number;
  homeTeamScore: string;
  awayTeamScore: string;
  isLive: boolean;
  stateDetails?: EventStateDetailsType;
  scores?: Score[];
  data?: MatchData;
}

export interface SportsPoolHistoryGameDetail {
  game: SportsPoolGame;
  bet: SportsPoolBet;
  previousId: number;
  nextId: number;
}

export interface ToggleSportsPoolGameBetEvent {
  eventBetTypeItem: SelectableEventBetTypeItem;
  event: Event;
  matchPosition: SportsPoolGameMatch;
}
