import { ChangeDetectionStrategy, ChangeDetectorRef, Component, Inject, OnInit, Optional } from '@angular/core';
import { Router } from '@angular/router';
import { finalize, map, take, takeUntil } from 'rxjs/operators';
import {
  configureFreeBetCouponForBetSlip,
  FreeBetCoupon,
  FreeBetCouponBetSlip,
  orderFreeBetCoupons
} from '@honoregaming/betslip';
import { OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';
import { BetCategoryConfigurationService, DestroySubject } from '@honoregaming/core';
import { FreeBetService } from '@honoregaming/customer-core';
import { BetCategoryFilterData, BetCategoryType, FreeBetCouponState, FreeBetSortOption } from '@honoregaming/types';
import { Media, MediaService } from '@honoregaming/ui';

@Component({
  selector: 'hg-freebet-coupons',
  templateUrl: './freebet-coupons.component.html',
  styleUrls: ['./freebet-coupons.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class FreebetCouponsComponent extends DestroySubject implements OnInit {
  selectedBetCategory: BetCategoryType = BetCategoryType.SportsFixedOdds;
  selectedCouponStates: FreeBetCouponState[] = [FreeBetCouponState.Open];
  freeBetCoupons: FreeBetCouponBetSlip[] = [];
  filteredFreebetCoupons: FreeBetCouponBetSlip[] = [];

  loading: boolean = true;
  error: boolean = false;
  limitDisplayCoupon: number = 6;
  maxDisplayCoupon: number = 6;
  couponsToDisplayLeft: number = 0;
  hasFetchAllStates: boolean = false;
  betCategoriesFilterData: BetCategoryFilterData[] = [];
  sortOptions: string[] = Object.values(FreeBetSortOption);
  selectedSortOption: FreeBetSortOption | null = null;

  BetCategoryType = BetCategoryType;
  FreeBetCouponState = FreeBetCouponState;

  constructor(
    private readonly freeBetService: FreeBetService,
    private readonly cdRef: ChangeDetectorRef,
    private readonly router: Router,
    private readonly betCategoryConfigurationService: BetCategoryConfigurationService,
    @Inject(operatorConfigurationToken) private readonly operatorConfiguration: OperatorConfiguration,
    @Optional() private readonly mediaService: MediaService
  ) {
    super();
  }

  ngOnInit(): void {
    if (!this.operatorConfiguration.freeBetsConfiguration?.multiCouponEnabled) {
      this.router.navigate(['myaccount']);
    }

    this.maxDisplayCoupon = this.mediaService?.media < Media.lg ? 6 : 9;
    this.betCategoriesFilterData = this.betCategoryConfigurationService.couponsBetCategoriesFilterData;
    this.loadCoupons();
  }

  updateSelectedCategory(betCategory: BetCategoryType | string): void {
    this.selectedBetCategory = betCategory as BetCategoryType;
    // Reset to default states when category is updated
    this.updateSelectedStates([FreeBetCouponState.Open]);
  }

  // Reload coupons only the first time a selected state is not the default one
  updateSelectedStates(couponStates: FreeBetCouponState[] = []): void {
    this.selectedCouponStates = couponStates;
    if (
      !this.hasFetchAllStates &&
      (!this.selectedCouponStates.length || !this.selectedCouponStates.includes(FreeBetCouponState.Open))
    ) {
      this.loadCoupons(false);
      this.hasFetchAllStates = true;
    }

    this.sortOptions = Object.values(FreeBetSortOption);
    if (this.selectedCouponStates.includes(FreeBetCouponState.Expired)) {
      this.sortOptions = this.sortOptions.filter(
        (sortOption: FreeBetSortOption) => sortOption !== FreeBetSortOption.Expiration
      );
      this.selectedSortOption = null;
    }
    this.applyFiltersAndSort();
  }

  viewMoreCoupons(): void {
    this.limitDisplayCoupon += this.maxDisplayCoupon;
    this.couponsToDisplayLeft = this.couponsToDisplayLeft - this.maxDisplayCoupon;
  }

  sortFilteredCoupons(sortOption: string): void {
    this.selectedSortOption = sortOption as FreeBetSortOption;
    this.filteredFreebetCoupons = orderFreeBetCoupons(this.filteredFreebetCoupons, this.selectedSortOption);
    this.cdRef.markForCheck();
  }

  isSelectedStates(freebetCouponsStates: FreeBetCouponState[]): boolean {
    return freebetCouponsStates.every((couponsState: FreeBetCouponState) =>
      this.selectedCouponStates.includes(couponsState)
    );
  }

  private loadCoupons(forBetting: boolean = true): void {
    this.loading = true;
    this.freeBetService
      .forceRefreshFreeBetCoupon(forBetting)
      .pipe(
        take(1),
        takeUntil(this.destroy$),
        map((coupons: FreeBetCoupon[]) =>
          coupons.map((coupon: FreeBetCoupon) => configureFreeBetCouponForBetSlip(coupon))
        ),
        finalize(() => {
          this.loading = false;
          this.cdRef.markForCheck();
        })
      )
      .subscribe((betSlipFreebetCoupons: FreeBetCouponBetSlip[]) => {
        this.freeBetCoupons = betSlipFreebetCoupons;
        this.error = false;
        this.applyFiltersAndSort();
      });
  }

  private applyFiltersAndSort(): void {
    const filteredCoupons: FreeBetCouponBetSlip[] = this.freeBetCoupons.filter((coupon: FreeBetCouponBetSlip) =>
      this.isDisplayedCoupon(coupon)
    );
    this.filteredFreebetCoupons = orderFreeBetCoupons(filteredCoupons, this.selectedSortOption);
    this.limitDisplayCoupon = this.maxDisplayCoupon;
    this.couponsToDisplayLeft = this.filteredFreebetCoupons.length - this.limitDisplayCoupon;
    this.cdRef.markForCheck();
  }

  private isDisplayedCoupon(coupon: FreeBetCoupon): boolean {
    return this.isDisplayedCouponCategory(coupon) && this.isDisplayedCouponState(coupon);
  }

  // Virtual and SportsPool are considered as the sport category for coupons display
  private isDisplayedCouponCategory(coupon: FreeBetCoupon): boolean {
    if (!this.selectedBetCategory) {
      return true;
    }

    const categories: BetCategoryType[] = coupon.freeBetRule.betCategories;

    if (categories.includes(this.selectedBetCategory)) {
      return true;
    }

    const SPORTS_FIXED_ODDS_RELATED: ReadonlySet<BetCategoryType> = new Set([
      BetCategoryType.VirtualFixedOdds,
      BetCategoryType.SportsPool
    ]);

    return (
      this.selectedBetCategory === BetCategoryType.SportsFixedOdds &&
      categories.some(cat => SPORTS_FIXED_ODDS_RELATED.has(cat))
    );
  }

  private isDisplayedCouponState(coupon: FreeBetCoupon): boolean {
    return !this.selectedCouponStates.length || this.selectedCouponStates.includes(coupon.state);
  }
}
