import { Component, OnInit, ChangeDetectionStrategy, ChangeDetectorRef } from '@angular/core';
import { I18nService } from '@honoregaming/i18n';
import { AuthService, FreeBetService } from '@honoregaming/customer-core';
import { filter, finalize, switchMap, takeUntil } from 'rxjs/operators';
import { DestroySubject } from '@honoregaming/core';
import { MessageService } from '@honoregaming/ui';
import { LoyaltyRedeemableConfirmationComponent } from '@honoregaming/customer-ui';
import { Loyalty, LoyaltyRedeemable, LoyaltyRedeemableItemCode, LoyaltyRedeemableType } from '@honoregaming/types';
import { LoyaltyService } from '../../services/loyalty.service';
import { HttpErrorResponse } from '@angular/common/http';
import { LoyaltyFailure } from '../../models/loyalty-failure.model';
import { forkJoin, of } from 'rxjs';

@Component({
  selector: 'hg-loyalty',
  templateUrl: './loyalty.component.html',
  styleUrls: ['./loyalty.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class LoyaltyComponent extends DestroySubject implements OnInit {
  loading = false;
  isBuyingRedeemable = false;
  loyalty: Loyalty;
  loyaltyRedeemables: LoyaltyRedeemable[] = [];
  loyaltyChangeItemCodes: LoyaltyRedeemableItemCode[] = [];
  nextStatusMessage: string;
  LoyaltyRedeemableType = LoyaltyRedeemableType;
  loyaltyPointsBar: number;

  constructor(
    private i18nService: I18nService,
    private authService: AuthService,
    private loyaltyService: LoyaltyService,
    private messageService: MessageService,
    private cdRef: ChangeDetectorRef,
    private freeBetService: FreeBetService
  ) {
    super();
  }

  ngOnInit(): void {
    this.loading = true;
    this.loyaltyService
      .getLoyalty()
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.loading = false;
          this.cdRef.markForCheck();
        })
      )
      .subscribe(loyaltyResponse => {
        this.loyalty = loyaltyResponse.loyalty;
        this.loyaltyRedeemables = loyaltyResponse.loyaltyRedeemables;
        this.loyaltyChangeItemCodes = loyaltyResponse.changeItemCodes;
        this.loyaltyPointsBar = this.loyalty.nextStatus?.threshold | this.loyalty.monthlyPoints;

        if (!this.loyalty.nextStatus) {
          this.nextStatusMessage = this.i18nService.translateSync(
            'LOYALTY.CONGRATULATIONS',
            this.loyalty.currentStatus?.name
          );
        } else {
          const missingPoints = this.loyalty.nextStatus.threshold - this.loyalty.monthlyPoints;
          this.nextStatusMessage = this.i18nService.translateSync(
            'LOYALTY.MORE_TO_REACH',
            this.i18nService.formatNumberSync(missingPoints, false).toString(),
            this.loyalty.nextStatus.name
          );
        }
      });
  }

  buyRedeemable(loyaltyRedeemable: LoyaltyRedeemable): void {
    if (this.isBuyingRedeemable) {
      return;
    }

    this.messageService
      .sendComponentMessage(LoyaltyRedeemableConfirmationComponent, {
        loyaltyRedeemable: loyaltyRedeemable
      })
      .closed.pipe(
        takeUntil(this.destroy$),

        filter(result => !!result),
        switchMap(_ => {
          this.isBuyingRedeemable = true;
          this.cdRef.markForCheck();

          return this.loyaltyService.claimLoyaltyRedeemable(loyaltyRedeemable.id);
        }),
        switchMap(itemCode => {
          if (itemCode) {
            this.loyaltyChangeItemCodes.push(itemCode);
          }

          const postClaimObservables = [];

          if (loyaltyRedeemable.type == LoyaltyRedeemableType.Item) {
            postClaimObservables.push(
              this.messageService.sendComponentMessage(LoyaltyRedeemableConfirmationComponent, {
                changed: true,
                itemCode: itemCode.code
              }).closed
            );
          } else if (loyaltyRedeemable.type === LoyaltyRedeemableType.FreeBetBundle) {
            postClaimObservables.push(this.freeBetService.forceRefreshFreeBetCoupon());
          } else {
            postClaimObservables.push(of());
          }

          return forkJoin(postClaimObservables);
        }),
        finalize(() => {
          this.updateLoyaltyBalance();
          this.isBuyingRedeemable = false;
          this.cdRef.markForCheck();
        })
      )
      .subscribe(
        _ => {},
        (err: HttpErrorResponse) => {
          if (err.error?.code === LoyaltyFailure.RedeemableNotAllowed) {
            this.messageService.sendI18nMessage('LOYALTY.REDEEMABLE_ERROR.NOT_ALLOWED');
          }
        }
      );
  }

  private updateLoyaltyBalance() {
    this.authService
      .getBalance()
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.cdRef.markForCheck();
        })
      )
      .subscribe(balances => {
        if (balances) {
          this.loyalty.totalPoints = balances.loyaltyBalance;
        }
      });
  }

  getNextIcon(icon: string) {
    return icon.replace('.png', '-preview.png');
  }
}
