import { ChangeDetectionStrategy, Component, ChangeDetectorRef, OnInit } from '@angular/core';
import { Observable, of, Subject } from 'rxjs';
import { catchError, switchMap, takeUntil, tap } from 'rxjs/operators';
import {
  InstantGameTransaction,
  InstantGameState,
  InstantGameName,
  BetLineType,
  BetCategoryFilterData,
  BetCategoryType
} from '@honoregaming/types';
import { DestroySubject, BetCategoryConfigurationService } from '@honoregaming/core';

import { AccountService } from '../../services/account.service';
import { SelectValue, AccountFilter } from '../../models/account-filters.model';

@Component({
  selector: 'hg-instant-game-history',
  templateUrl: './instant-game-history.component.html',
  styleUrls: ['./instant-game-history.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class InstantGameHistoryComponent extends DestroySubject implements OnInit {
  history: InstantGameTransaction[] = [];
  loading: boolean = false;
  skip: number = 0;
  take: number = 5;
  hasMore: boolean = true;

  InstantGameName = InstantGameName;
  BetLineType = BetLineType;
  states: SelectValue[] = [{ value: InstantGameState.Won }, { value: InstantGameState.Lost }];
  currentFilter: AccountFilter = {};
  betCategoriesFilterData: BetCategoryFilterData[] = [];
  BetCategoryType = BetCategoryType;

  private readonly loadHistory$: Subject<void> = new Subject<void>();

  constructor(
    private readonly accountService: AccountService,
    private readonly betCategoryConfigurationService: BetCategoryConfigurationService,
    private readonly cdRef: ChangeDetectorRef
  ) {
    super();
  }

  ngOnInit(): void {
    this.betCategoriesFilterData = this.betCategoryConfigurationService.historyBetCategoriesFilterData;
    this.subscribeToLoadHistory();
  }

  loadMore(): void {
    if (this.loading || !this.hasMore) {
      return;
    }

    this.skip += this.take;
    this.loadHistory$.next();
  }

  filter(filter: AccountFilter): void {
    this.skip = 0;
    this.hasMore = true;
    this.history = [];
    // Copy: the filters component mutates and re-emits the very same object reference
    this.currentFilter = { ...filter };
    this.loadHistory$.next();
  }

  private subscribeToLoadHistory(): void {
    this.loadHistory$
      .pipe(
        tap(() => this.startLoading()),
        // switchMap cancels the pending request, so a response from a previous
        // filter can never be appended to the list of the newly selected one
        switchMap(() => this.getHistory()),
        takeUntil(this.destroy$)
      )
      .subscribe((transactionsHistory: InstantGameTransaction[]) => this.handleResponse(transactionsHistory));
  }

  private getHistory(): Observable<InstantGameTransaction[]> {
    return this.accountService
      .getInstantGameTransactionsHistory(
        this.skip,
        this.take,
        this.currentFilter.state as InstantGameState,
        this.currentFilter.month
      )
      .pipe(catchError(() => of<InstantGameTransaction[]>([])));
  }

  private startLoading(): void {
    this.loading = true;
    this.cdRef.markForCheck();
  }

  private handleResponse(transactionsHistory: InstantGameTransaction[]): void {
    if (transactionsHistory.length - this.take < 0) {
      this.hasMore = false;
    }

    this.history = this.history.concat(transactionsHistory);
    this.loading = false;
    this.cdRef.markForCheck();
  }
}
