import { HttpClient } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { globalConfiguration } from '@honoregaming/configuration';
import { GetCustomerLoyaltyResponse, LoyaltyRedeemableItemCode } from '@honoregaming/types';

@Injectable({
  providedIn: 'root'
})
export class LoyaltyService {
  constructor(private httpClient: HttpClient) {}

  getLoyalty() {
    return this.httpClient.get<GetCustomerLoyaltyResponse>(`${globalConfiguration.apiBaseUrl}loyalty`);
  }

  claimLoyaltyRedeemable(redeemableId: number) {
    return this.httpClient.post<LoyaltyRedeemableItemCode>(
      `${globalConfiguration.apiBaseUrl}loyalty/redeemable/${redeemableId}`,
      null
    );
  }
}
