import { DOCUMENT } from '@angular/common';
import {
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  EventEmitter,
  HostBinding,
  Inject,
  Input,
  OnChanges,
  OnInit,
  Optional,
  Output,
  SimpleChanges
} from '@angular/core';
import { ActivatedRoute, NavigationEnd, Router } from '@angular/router';
import { Observable, of, Subscription } from 'rxjs';
import { filter, take, takeUntil } from 'rxjs/operators';
import { OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';
import { BetCategoryConfigurationService, DestroySubject, DialogService, kioskToken } from '@honoregaming/core';
import {
  AuthService,
  CustomerOperatorConfiguration,
  customerOperatorConfigurationToken,
  Me,
  SmarticoService,
  TelemetryService
} from '@honoregaming/customer-core';
import { I18nService } from '@honoregaming/i18n';
import { Media, MediaService, MessageService } from '@honoregaming/ui';
import { NavBarService } from 'projects/customer/customer/src/app/services';
import { MobileNavService } from 'projects/customer/customer/src/app/services/mobile-nav.service';
import { LoginComponent } from '../login/login.component';

@Component({
  selector: 'hg-mobile-navigation-menu',
  templateUrl: './mobile-navigation-menu.component.html',
  styleUrls: ['./mobile-navigation-menu.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class MobileNavigationMenuComponent extends DestroySubject implements OnInit, OnChanges {
  @HostBinding('class') class = 'mobile-navigation-menu';
  @HostBinding('class.login-panel-opened') @Input() isBurgerOpened: boolean;
  @HostBinding('class.tuto-step-one-two') isStepOneOrTwo = false;

  hasWelcomeTutorial = this.operatorConfiguration.onlineConfiguration?.welcomeTutorial;
  showSportsPoolEventCounter: boolean = this.operatorConfiguration.sportsPoolConfiguration?.showEventCounterOnCustomer;

  tutorialStepsStorage = 'tutorial_steps';

  defaultStateBurgerIcon = false;

  open = false;
  categoryOpen = false;

  links: any[];
  lang: string;
  burgerBack: string;
  routeSelected: string;
  me: Me;
  tutorialStep: number;

  @Input()
  anchor: string;

  @Output()
  public navigated = new EventEmitter<number>();

  @Output() clickOnBurger = new EventEmitter<boolean>();

  private mobileNavigationMenuLinksSubscription?: Subscription;

  instantGamesBetCategoryPath = this.betCategoryConfigurationService.getInstantGamesBetCategoryPath();
  isLoginDialogOpen = false;

  constructor(
    private readonly router: Router,
    private readonly route: ActivatedRoute,
    private readonly authService: AuthService,
    private readonly dialogService: DialogService,
    private readonly i18nService: I18nService,
    private readonly navBarService: NavBarService,
    private readonly messageService: MessageService,
    private readonly mobileNavService: MobileNavService,
    private readonly cdRef: ChangeDetectorRef,
    private readonly telemetryService: TelemetryService,
    private readonly betCategoryConfigurationService: BetCategoryConfigurationService,
    private readonly smarticoService: SmarticoService,
    @Inject(operatorConfigurationToken) public readonly operatorConfiguration: OperatorConfiguration,
    @Inject(customerOperatorConfigurationToken)
    private readonly customerOperatorConfiguration: CustomerOperatorConfiguration,
    @Inject(DOCUMENT) private readonly document: Document,
    @Inject(kioskToken) public readonly isKiosk: boolean,
    @Optional() private readonly mediaService: MediaService
  ) {
    super();
  }

  ngOnInit(): void {
    this.tutorialStep = Number(localStorage.getItem(this.tutorialStepsStorage));
    this.isStepOneOrTwo = this.tutorialStep === 1 || this.tutorialStep === 2;

    if (this.tutorialStep === 3 || this.tutorialStep === 4) {
      this.isBurgerOpened = true;
      this.clickOnBurger.emit(this.isBurgerOpened);
    }

    this.i18nService.languageChanged$.pipe(takeUntil(this.destroy$)).subscribe(lang => {
      this.lang = lang;
      this.cdRef.markForCheck();
    });

    this.authService.me$.pipe(takeUntil(this.destroy$)).subscribe(me => {
      this.me = me;
      this.cdRef.markForCheck();
    });

    this.dialogService
      .registerDialog('login')
      .pipe(takeUntil(this.destroy$))
      .subscribe(open => {
        this.isLoginDialogOpen = open;
        open ? (this.routeSelected = '/myaccount/history') : this.detectChangedRoute();
        this.cdRef.markForCheck();
      });

    this.dialogService
      .registerDialog('categories')
      .pipe(takeUntil(this.destroy$))
      .subscribe(open => {
        this.categoryOpen = open === undefined ? !this.categoryOpen : open;
        this.cdRef.markForCheck();
      });

    this.router.events.pipe(filter(x => x instanceof NavigationEnd)).subscribe(() => {
      this.detectChangedRoute();

      if (!this.isBurgerOpened) {
        this.defaultStateBurgerIcon = false;
      }

      this.cdRef.markForCheck();
    });

    this.mobileNavService.tutorialUpdate.pipe(takeUntil(this.destroy$)).subscribe(step => {
      this.tutorialStep = step;
      this.isStepOneOrTwo = step === 1 || step === 2;

      if (this.tutorialStep === 3) {
        this.isBurgerOpened = true;
        this.clickOnBurger.emit(this.isBurgerOpened);
      } else if (this.tutorialStep >= 5) {
        this.closeMenu();
      }

      this.cdRef.markForCheck();
    });

    this.detectChangedRoute();
    this.getMobileNavigationMenuLinks();
  }

  ngOnChanges(changes: SimpleChanges) {
    this.getMobileNavigationMenuLinks();

    if (changes.isBurgerOpened?.currentValue && !changes.isBurgerOpened?.previousValue) {
      this.isBurgerOpened = true;
      this.defaultStateBurgerIcon = true;
      this.clickOnBurger.emit(this.isBurgerOpened);
      this.cdRef.markForCheck();
    }
  }

  detectChangedRoute() {
    if (this.router.url === '/sports') {
      this.routeSelected = '/sports';
    } else if (this.router.url.startsWith(`/${this.instantGamesBetCategoryPath}/category`)) {
      this.routeSelected = `/${this.instantGamesBetCategoryPath}`;
    } else if (this.router.url.startsWith('/myaccount')) {
      this.routeSelected = '/myaccount/history';
    } else {
      this.routeSelected = this.route.snapshot['_routerState'].url;
    }
  }

  isLinkActive(url: string): boolean {
    if (this.isBurgerOpened || !url) {
      return false;
    }

    const route: string = this.routeSelected;
    const isAccountPage: boolean = route.startsWith('/myaccount');
    const matches = (link: string) =>
      route === link ||
      route.startsWith(link + '?') ||
      route.startsWith(link + '/') ||
      (isAccountPage && link.startsWith('/myaccount'));

    if (!matches(url)) {
      return false;
    }

    const hasMoreSpecificMatch: boolean = (this.links ?? []).some(link => {
      const otherUrl: string | undefined = link?.action?.url;
      return !!otherUrl && otherUrl.length > url.length && matches(otherUrl);
    });

    return !hasMoreSpecificMatch;
  }

  fixBody(onlyInXs = false) {
    onlyInXs
      ? this.document.documentElement.classList.add('hidden-in-xs')
      : this.document.documentElement.classList.add('hidden');
  }

  getMobileNavigationMenuLinks() {
    this.mobileNavigationMenuLinksSubscription?.unsubscribe();
    this.mobileNavigationMenuLinksSubscription = this.authService.me$.pipe(takeUntil(this.destroy$)).subscribe(me => {
      if (this.customerOperatorConfiguration.customization[this.anchor]) {
        this.links = this.customerOperatorConfiguration.customization[this.anchor].map(x => {
          if (x.connected && x.notconnected) {
            return me ? x.connected : x.notconnected;
          } else {
            return x;
          }
        });
      }
      this.cdRef.markForCheck();
    });
  }

  handleAction(
    action: { url?: string; dialog?: string },
    name: string | { [key: string]: string },
    shouldTranslateName: boolean,
    position: number
  ): void {
    const navScope: string | undefined = action.url?.replace(/^\//, '').split('/')[0];
    const navItemName: string = shouldTranslateName ? name[this.lang] ?? this.translate(name.toString()) : name;
    const pageOrigin: string | undefined = this.router.url.replace(/^\//, '').split('/')[0];
    this.telemetryService.trackEvent('navbar_click', {
      nav_scope: navScope,
      nav_item_name: navItemName,
      nav_item_position: position,
      page_origin: pageOrigin
    });

    if (action || action.url) {
      if (action.url === '/sports') {
        this.telemetryService.trackEvent('top-bets');
      }
      if (this.router.url === action?.url && this.isLoginDialogOpen) {
        this.dialogService.toggleDialog('login', false);
      }

      if (action.url.startsWith('/myaccount/') && this.anchor === 'instant-games-nav-links' && this.me) {
        this.router.navigateByUrl('/myaccount/instant-games-history');
      } else {
        if (action.url.startsWith('/myaccount/')) {
          this.navBarService.clickOnNavBarMyBetsNavigation(true);
          this.navBarService.clickOnNavBarMyBets(true);
          this.openLoginPanel(action.url);
        } else {
          this.router.navigateByUrl(action.url);
        }
      }
    } else if (action.dialog) {
      this.dialogService.toggleDialog(action.dialog, true);
    }

    this.closeMenu(false);

    const isGamificationWidgetOpen$: Observable<boolean> = this.smarticoService.isEnabled
      ? this.smarticoService.isGamificationWidgetOpen$
      : of(false);
    isGamificationWidgetOpen$.pipe(take(1), takeUntil(this.destroy$)).subscribe(isOpen => {
      if (isOpen) {
        this.smarticoService.closeGamificationWidget();
      } else {
        window.scrollTo({ top: 0, behavior: 'smooth' });
      }
    });
  }

  openLoginPanel(url: string) {
    this.mediaService.media$.pipe(take(1)).subscribe(x => {
      if (x >= Media.lg) {
        this.messageService.sendComponentMessage(LoginComponent);
      }
    });
    if (this.me) {
      this.router.navigateByUrl(url);
    } else {
      this.dialogService.toggleDialog('login', true);
    }
  }

  closeMenu(isFromNavbar = false) {
    this.clickOnBurger.emit(false);
    if (isFromNavbar) {
      this.defaultStateBurgerIcon = true;
    }
  }

  burgerClick() {
    this.smarticoService.closeGamificationWidget();
    this.isBurgerOpened = !this.isBurgerOpened;
    this.defaultStateBurgerIcon = true;
    this.clickOnBurger.emit(this.isBurgerOpened);
    this.dialogService.toggleDialog('login', false);
    if (this.burgerBack) {
      this.router.navigateByUrl(this.burgerBack);
    } else {
      this.categoryOpen = !this.categoryOpen;
    }
  }

  clickToNextStep(step: number) {
    if (this.tutorialStep <= 5 && this.hasWelcomeTutorial) {
      localStorage[this.tutorialStepsStorage] = parseInt(localStorage[this.tutorialStepsStorage]) + 1;
      this.mobileNavService.updateStepTutorial(step);

      if (localStorage[this.tutorialStepsStorage] === 3) {
        this.burgerClick();
      }
    }
  }

  translate(key: string): string {
    return this.i18nService.translateSync(key);
  }
}
