import { animate, style, transition, trigger } from '@angular/animations';
import {
  Component,
  ChangeDetectionStrategy,
  Inject,
  Input,
  OnChanges,
  ChangeDetectorRef,
  Optional,
  Output,
  EventEmitter,
  OnInit
} from '@angular/core';
import { Bonus, OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';
import { DestroySubject, kioskToken } from '@honoregaming/core';
import { AnimateDirective, Media, MediaService } from '@honoregaming/ui';
import { takeUntil } from 'rxjs/operators';

@Component({
  selector: 'hg-bonus',
  templateUrl: './bonus.component.html',
  styleUrls: ['./bonus.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
  animations: [
    trigger('empty', [
      transition('void => *', [
        style({ height: '0', padding: '0', transform: 'scale(0)' }),
        animate('.1s ease-out', style({ height: '*', padding: '50px 0', transform: 'scale(1)' }))
      ])
    ]),
    trigger('removed', [
      transition('* => void', [animate('.1s ease-out', style({ transform: 'scale(0)', height: '0' }))]),
      transition('void => *', [
        style({ height: '0', transform: 'scale(0)' }),
        animate('.1s ease-out', style({ transform: 'scale(1)', height: '*' }))
      ])
    ])
  ]
})
export class BonusComponent extends DestroySubject implements OnChanges, OnInit {
  @Input() nextBonus: Bonus & { linesToAdd: number; percentage: string; minimalOdds: number; minimumStake: number };
  @Input() currentBonus: Bonus & { minimumStake: number };
  @Input() maxBonusReach = false;
  @Input() betSlipActive = false;
  @Input() isBonusScrolledIntoTopView: boolean;
  @Input() isBonusScrolledIntoBottomView: boolean;
  @Input() betLinesNumber: number;
  @Input() counter: AnimateDirective;
  @Input() isAgent: boolean;
  @Input() stake: number;
  @Input() isBetCompletion = false;

  @Output() jumpToActionButton = new EventEmitter();

  displayIcon: boolean;

  percent = 0;
  constructor(
    @Inject(operatorConfigurationToken) private operatorConfiguration: OperatorConfiguration,
    private cdRef: ChangeDetectorRef,
    @Optional() protected mediaService: MediaService,
    @Inject(kioskToken) public isKiosk: boolean
  ) {
    super();
  }

  ngOnInit(): void {
    this.mediaService.media$.pipe(takeUntil(this.destroy$)).subscribe(x => {
      x <= Media.md ? (this.displayIcon = true) : (this.displayIcon = false);
      this.cdRef.markForCheck();
    });
  }

  ngOnChanges(): void {
    let orderedBonus = this.operatorConfiguration.multipleBonus?.bonus.sort((a, b) =>
      a.linesNumber < b.linesNumber ? -1 : 1
    );
    if (this.currentBonus) {
      let index = orderedBonus.findIndex(x => x.linesNumber == this.currentBonus.linesNumber);
      this.percent = Math.floor(((index + 1) * 100) / orderedBonus.length);
    } else {
      this.percent = 0;
    }

    if (this.counter) {
      this.counter.animate('new');
    }

    this.cdRef.markForCheck();
  }

  jumpToMyBetButton() {
    this.jumpToActionButton.next();
    this.isBonusScrolledIntoTopView = true;
    this.isBonusScrolledIntoBottomView = true;
  }
}
