import { HttpClient, HttpHeaders, HttpParams } from '@angular/common/http';
import { Inject, Injectable, NgZone } from '@angular/core';
import { Router } from '@angular/router';
import {
  throwError as _throw,
  BehaviorSubject,
  EMPTY,
  Observable,
  of,
  ReplaySubject,
  Subject,
  Subscription,
  timer
} from 'rxjs';
import { catchError, finalize, map, switchMap, take, tap } from 'rxjs/operators';
import { IAuthService } from '@honoregaming/authentication';
import { globalConfiguration } from '@honoregaming/configuration';
import { LocalStorageService, Scope, scopeToken, SessionStorageService } from '@honoregaming/core';
import { JwtToken, Me, SESSION_IDENTIFIER } from '../models';
import { NotificationService } from './notification.service';
import { ITelemetryService, telemetryServiceToken } from './telemetry/telemetry-service.model';

const rememberMeKey = 'jwt_rememberMe';
const loginKey = 'jwt_login';
const accessKey = 'jwt_access';
const refreshKey = 'jwt_refresh';
const expirationKey = 'jwt_expiration';
const sessionIdKey = 'jwt_sessionId';

@Injectable()
export class AuthService implements IAuthService {
  private accessToken: string;
  private sessionId: string;
  private expiration: Date;
  private refreshToken: string;
  private refreshSubscription: Subscription;
  private meSubject = new ReplaySubject<Me | undefined>(1);

  private statusSubject = new BehaviorSubject<'connected' | 'disconnected'>('disconnected');
  status$ = this.statusSubject.asObservable();
  me$ = this.meSubject.asObservable();
  balance$ = this.meSubject.pipe(map(me => me?.balance ?? 0));

  private refreshInterval;

  constructor(
    private readonly httpClient: HttpClient,
    private readonly storageService: LocalStorageService,
    private readonly router: Router,
    private readonly zone: NgZone,
    private readonly notificationService: NotificationService,
    private readonly sessionStorageService: SessionStorageService,
    @Inject(telemetryServiceToken) private readonly telemetryService: ITelemetryService,
    @Inject(scopeToken) public readonly scope: Scope
  ) {}

  getStorageService() {
    return this.scope === Scope.Customer ? this.storageService : this.sessionStorageService;
  }

  startRefreshAuthTimer() {
    this.expiration = new Date(this.getStorageService().getItem(expirationKey));
    this.accessToken = this.getStorageService().getItem(accessKey);
    this.refreshToken = this.getStorageService().getItem(refreshKey);
    this.sessionId = this.getStorageService().getItem(sessionIdKey);
    if (this.accessToken) {
      this.statusSubject.next('connected');
    }

    this.getMe().subscribe();

    if (this.expiration) {
      this.refreshTimer();
    }
  }

  tryRefresh() {
    if (this.accessToken && this.expiration > new Date()) {
      return of(this.accessToken);
    }

    return this.refresh();
  }

  getUserRemembered(): any {
    return this.getStorageService().getItem(loginKey);
  }

  isUserRemembered(): any {
    return this.getStorageService().getItem(rememberMeKey);
  }

  login(
    login: string,
    password: string,
    rememberMe: boolean,
    withRefresh: boolean = false,
    customerId?: string
  ): Observable<JwtToken> {
    let header = new HttpHeaders();
    header = this.storageService.getItem(SESSION_IDENTIFIER)
      ? header.set(SESSION_IDENTIFIER, this.storageService.getItem(SESSION_IDENTIFIER))
      : header;

    return this.httpClient
      .post<JwtToken>(
        `${globalConfiguration.apiBaseUrl}authentication/token`,
        {
          login,
          password,
          rememberMe,
          withRefresh,
          customerId
        },
        { headers: header }
      )
      .pipe(
        switchMap(x => {
          this.accessToken = x.access_token;
          this.getStorageService().setItem(accessKey, x.access_token);
          this.refreshToken = x.refresh_token;
          this.getStorageService().setItem(refreshKey, x.refresh_token);
          const expirationDate = new Date();
          expirationDate.setSeconds(expirationDate.getSeconds() + x.expiresIn);
          this.expiration = expirationDate;
          this.getStorageService().setItem(expirationKey, this.expiration);
          this.getStorageService().setItem(rememberMeKey, rememberMe);
          this.sessionId = x.session_id;
          this.getStorageService().setItem(sessionIdKey, x.session_id);
          this.notificationService.mapSubscriptionToCustomer();
          return this.getMe(true).pipe(
            map(_ => {
              this.statusSubject.next('connected');
              this.telemetryService.trackEvent('login', { login });
              if (rememberMe) {
                this.getStorageService().setItem(loginKey, login);
              } else {
                this.getStorageService().removeItem(loginKey);
              }
              this.refreshTimer();
              this.zone.runOutsideAngular(() => {
                this.refreshInterval = setInterval(() => {
                  this.zone.run(() => this.getBalance().subscribe());
                }, 120000);
              });
              return x;
            })
          );
        })
      );
  }

  loginWithSessionId(sessionId: string): Observable<JwtToken> {
    return this.httpClient
      .get<JwtToken>(`${globalConfiguration.apiBaseUrl}authentication/login-from-session?sessionId=${sessionId}`)
      .pipe(
        switchMap(x => {
          this.accessToken = x.access_token;
          this.getStorageService().setItem(accessKey, x.access_token);
          this.refreshToken = x.refresh_token;
          this.getStorageService().setItem(refreshKey, x.refresh_token);
          const expirationDate = new Date();
          expirationDate.setSeconds(expirationDate.getSeconds() + x.expiresIn);
          this.expiration = expirationDate;
          this.getStorageService().setItem(expirationKey, this.expiration);
          this.sessionId = x.session_id;
          this.getStorageService().setItem(sessionIdKey, x.session_id);
          this.notificationService.mapSubscriptionToCustomer();
          return this.getMe(true).pipe(
            map(_ => {
              this.statusSubject.next('connected');
              this.telemetryService.trackEvent('login', { sessionId });
              this.getStorageService().removeItem(loginKey);
              this.refreshTimer();
              this.zone.runOutsideAngular(() => {
                this.refreshInterval = setInterval(() => {
                  this.zone.run(() => this.getBalance().subscribe());
                }, 120000);
              });
              return x;
            })
          );
        })
      );
  }

  getToken(): Observable<string> {
    if (!this.isAuthenticated()) {
      return _throw('not authenticated');
    }

    if (this.accessToken && this.expiration > new Date()) {
      return of(this.accessToken);
    }

    return this.refresh();
  }

  getSessionId(): Observable<string> {
    if (!this.isAuthenticated() || !this.accessToken || this.expiration < new Date()) {
      return _throw('not authenticated');
    }

    return of(this.sessionId);
  }

  getMe(onLogin: boolean = false): Observable<Me> {
    if (!this.accessToken) {
      this.meSubject.next(null);
      return of(null);
    }

    let params = new HttpParams().set('onLogin', onLogin);

    return this.httpClient.get<Me>(`${globalConfiguration.apiBaseUrl}authentication/me`, { params: params }).pipe(
      tap(
        x => this.meSubject.next(x),
        _e => this.meSubject.next(null)
      )
    );
  }

  logout(): void {
    this.httpClient
      .post(
        `${globalConfiguration.apiBaseUrl}authentication/logout`,
        {},
        {
          headers: {
            Authorization: `Bearer ${this.accessToken}`
          }
        }
      )
      .subscribe();

    this.accessToken = null;
    this.sessionId = null;
    this.refreshToken = null;
    this.expiration = null;
    this.getStorageService().removeItem(accessKey);
    this.getStorageService().removeItem(refreshKey);
    this.getStorageService().removeItem(expirationKey);
    this.getStorageService().removeItem(sessionIdKey);
    this.meSubject.next(null);
    this.statusSubject.next('disconnected');
    this.router.navigateByUrl('/');
    this.notificationService.clearSubscription();
    clearInterval(this.refreshInterval);
  }

  // tslint:disable-next-line: member-ordering
  private currentRefreshRequest: Subject<string>;
  refresh(): Observable<string> {
    if (this.currentRefreshRequest) {
      return this.currentRefreshRequest.asObservable();
    }

    if (!this.refreshToken) {
      return of(null);
    }

    this.currentRefreshRequest = new Subject<string>();
    let headers = new HttpHeaders();
    headers = headers.set('Content-Type', 'application/json; charset=utf-8');

    return this.httpClient
      .post<JwtToken>(`${globalConfiguration.apiBaseUrl}authentication/refresh`, `"${this.refreshToken}"`, {
        headers
      })
      .pipe(
        map(x => {
          this.accessToken = x.access_token;
          this.getStorageService().setItem(accessKey, x.access_token);
          this.refreshToken = x.refresh_token;
          this.getStorageService().setItem(refreshKey, x.refresh_token);
          const expirationDate = new Date();
          expirationDate.setSeconds(expirationDate.getSeconds() + x.expiresIn);
          this.expiration = expirationDate;
          this.getStorageService().setItem(expirationKey, this.expiration);
          this.sessionId = x.session_id;
          this.getStorageService().setItem(sessionIdKey, this.sessionId);
          this.refreshTimer();
          this.currentRefreshRequest.next(this.accessToken);
          if (this.statusSubject.value !== 'connected') {
            this.statusSubject.next('connected');
          }
          return this.accessToken;
        }),
        finalize(() => {
          this.currentRefreshRequest.complete();
          this.currentRefreshRequest = null;
        }),
        catchError(_err => {
          this.logout();
          this.currentRefreshRequest.next(null);
          return of(null);
        })
      );
  }

  isAuthenticated(): boolean {
    return !!this.refreshToken;
  }

  private refreshTimer() {
    if (this.refreshSubscription) {
      this.refreshSubscription.unsubscribe();
    }
    this.zone.runOutsideAngular(
      () =>
        (this.refreshSubscription = timer(this.expiration).subscribe(() =>
          this.zone.run(() => this.refresh().subscribe())
        ))
    );
  }

  getBalance(): Observable<{
    balance: number;
    freeBalance: number;
    loyaltyBalance: number;
  }> {
    return this.httpClient
      .get<{
        balance: number;
        freeBalance: number;
        loyaltyBalance: number;
      }>(`${globalConfiguration.apiBaseUrl}profile/balance`, {})
      .pipe(
        switchMap(x => {
          return this.meSubject.pipe(
            take(1),
            map(me => {
              me = { ...me, ...x };
              this.meSubject.next(me);
              return x;
            })
          );
        })
      );
  }

  addToBalance(stake: number): Observable<Me> {
    return this.meSubject.pipe(
      take(1),
      switchMap(me => {
        if (!me) {
          return EMPTY;
        }
        me = { ...me, balance: me.balance + stake };
        this.meSubject.next(me);
        return of(me);
      })
    );
  }

  setBalance(balance: number): Observable<Me> {
    return this.meSubject.pipe(
      take(1),
      switchMap(me => {
        if (!me) {
          return EMPTY;
        }
        me = { ...me, balance: balance };
        this.meSubject.next(me);
        return of(me);
      })
    );
  }

  checkPassword(password: string): Observable<boolean> {
    return this.httpClient.post<boolean>(`${globalConfiguration.apiBaseUrl}authentication/check-password`, {
      password
    });
  }

  checkIp(): Observable<boolean> {
    return this.httpClient.get<boolean>(`${globalConfiguration.apiBaseUrl}authentication/ip`).pipe(
      map(() => true),
      catchError(() => of(false))
    );
  }

  mfaCodeRequest(): Observable<boolean> {
    return this.httpClient.post<boolean>(`${globalConfiguration.apiBaseUrl}authentication/send-mfa-code`, null);
  }

  refreshMe(me: Me) {
    this.meSubject.next(me);
  }
}
