import { ErrorHandler } from '@angular/core';

declare var window;

export class HgErrorHandler extends ErrorHandler {
  logInConsole = !this.production;

  constructor(private production) {
    super();

    if (typeof window !== 'undefined') {
      window.HgLogErrorInConsole = () => {
        this.logInConsole = true;
        console.log('%c Enabling error logging in console', 'background: #1991EB; color: white;');
      };
    }
  }

  public handleError(err: any): void {
    if (this.logInConsole) {
      console.error(err);
    }

    // exclude network related error:
    if (
      [
        `Gateway Timeout`,
        `Cannot start a HubConnection`,
        `Failed to fetch`,
        `La requête a expiré`,
        `NetworkError when attempting to fetch resource.`,
        `Error: Cannot send data if the connection is not in the 'Connected' State`
      ].some(e => err.message?.indexOf?.(e) > -1)
    ) {
      return;
    }
  }
}

export function hgErrorHandlerFactory(production: boolean) {
  return new HgErrorHandler(production);
}
