import { HttpClient, HttpHeaders } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { Observable } from 'rxjs';
import { globalConfiguration } from '@honoregaming/configuration';
import { CookieStorageService } from '@honoregaming/core';
import { SESSION_IDENTIFIER } from '@honoregaming/customer-core';
import { ABACKLINK, AKEY, ASESSION } from '../constants/affiliate.constant';
import { UTM_CAMPAIGN, UTM_MEDIUM, UTM_SOURCE } from '../constants/utm.constant';
import { S2S_CLICK_ID, S2S_TRACKER_NAME } from '../constants/s2s.constant';

@Injectable({ providedIn: 'root' })
export class VisitorService {
  constructor(private httpClient: HttpClient, private storageService: CookieStorageService) {}

  sendVisitor(): Observable<{}> {
    let header = new HttpHeaders();

    // Affiliate
    header = !!this.storageService.getItem(AKEY) ? header.set(AKEY, this.storageService.getItem(AKEY)) : header;
    header = !!this.storageService.getItem(ASESSION)
      ? header.set(ASESSION, this.storageService.getItem(ASESSION))
      : header;
    header = !!this.storageService.getItem(ABACKLINK)
      ? header.set(ABACKLINK, this.storageService.getItem(ABACKLINK))
      : header;

    // Marketing
    header = !!this.storageService.getItem(SESSION_IDENTIFIER)
      ? header.set(SESSION_IDENTIFIER, this.storageService.getItem(SESSION_IDENTIFIER))
      : header;
    header = !!this.storageService.getItem(UTM_SOURCE)
      ? header.set(UTM_SOURCE, encodeURIComponent(this.storageService.getItem(UTM_SOURCE)))
      : header;
    header = !!this.storageService.getItem(UTM_MEDIUM)
      ? header.set(UTM_MEDIUM, encodeURIComponent(this.storageService.getItem(UTM_MEDIUM)))
      : header;
    header = !!this.storageService.getItem(UTM_CAMPAIGN)
      ? header.set(UTM_CAMPAIGN, encodeURIComponent(this.storageService.getItem(UTM_CAMPAIGN)))
      : header;
    header = !!this.storageService.getItem(S2S_TRACKER_NAME)
      ? header.set(S2S_TRACKER_NAME, encodeURIComponent(this.storageService.getItem(S2S_TRACKER_NAME)))
      : header;
    header = !!this.storageService.getItem(S2S_CLICK_ID)
      ? header.set(S2S_CLICK_ID, encodeURIComponent(this.storageService.getItem(S2S_CLICK_ID)))
      : header;

    return this.httpClient.post<{}>(
      `${globalConfiguration.apiBaseUrl}visitor`,
      {},
      {
        headers: header
      }
    );
  }
}
