import { Injectable, Inject } from '@angular/core';
import { Event, NavigationEnd, NavigationError, NavigationStart, Router } from '@angular/router';
import { filter } from 'rxjs/operators';
import { BetCategoriesError } from '@honoregaming/core';
import { operatorConfigurationToken, OperatorConfiguration } from '@honoregaming/configuration';
import { AuthenticationError, ValidatedError } from '../errors';
import { TelemetryService } from './telemetry/telemetry.service';
import { SeoService } from './seo.service';
import { CanonicalService } from './canonical.service';
import { ValidatedErrorMessage } from '../enums';

@Injectable()
export class RoutingEventsService {
  constructor(
    private readonly router: Router,
    private readonly telemetryService: TelemetryService,
    private readonly seoService: SeoService,
    private readonly canonicalService: CanonicalService,
    @Inject(operatorConfigurationToken) private readonly operatorConfiguration: OperatorConfiguration
  ) {}

  public listen(): void {
    this.router.events
      .pipe(
        filter((event: Event) => {
          return event instanceof NavigationError || event instanceof NavigationStart || event instanceof NavigationEnd;
        })
      )
      .subscribe((navEvent: NavigationError | NavigationStart | NavigationEnd) => {
        if (navEvent instanceof NavigationError) {
          if (navEvent.error instanceof BetCategoriesError) {
            if (
              this.operatorConfiguration.betCategories.indexOf(
                this.operatorConfiguration.features.defaultBetCategory
              ) !== 1
            ) {
              this.router.navigate(['/']);
            } else {
              console.error('no authorized route found');
            }
          } else if (navEvent.error instanceof AuthenticationError) {
            this.router.navigate(['sports']);
          } else if (navEvent.error instanceof ValidatedError) {
            if (navEvent.error.message === ValidatedErrorMessage.Locked) {
              this.router.navigate(['myaccount', 'unlock']);
            } else {
              this.router.navigate(['myaccount', 'registration', 'step2']);
            }
          }
        } else if (navEvent instanceof NavigationStart) {
          this.telemetryService.trackPageView(navEvent.url, navEvent.url);
        } else if (navEvent instanceof NavigationEnd) {
          this.seoService.updateSeoInformation();
          this.canonicalService.updateCanonicalUrl(navEvent.urlAfterRedirects);
        }
      });
  }
}
