import {
  Component,
  OnInit,
  ChangeDetectionStrategy,
  Output,
  EventEmitter,
  Input,
  ViewContainerRef,
  ViewChild,
  ComponentFactoryResolver,
  HostBinding
} from '@angular/core';

@Component({
  selector: 'hg-message',
  templateUrl: './message.component.html',
  styleUrls: ['./message.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class MessageComponent implements OnInit {
  @Output()
  close = new EventEmitter<any>();

  @Output()
  click = new EventEmitter();

  @Input()
  message: string;

  @Input()
  displayClose = true;
  @Input()
  maxWidthValue?: number;

  @Input()
  component: { component: any; props: any };

  @Input() messageId?: string;

  @ViewChild('template', { read: ViewContainerRef, static: true })
  container: ViewContainerRef;

  @HostBinding('style.max-width')
  maxWidth: string = this.maxWidthValue + 'px';

  constructor(private resolver: ComponentFactoryResolver) {}

  ngOnInit() {
    this.maxWidth = this.maxWidthValue + 'px';
    if (this.component) {
      const factory = this.resolver.resolveComponentFactory(this.component.component);
      if (factory !== undefined) {
        const ref = this.container.createComponent(factory);
        if (this.component.props) {
          Object.assign(ref.instance, this.component.props);
        }
        if ((ref.instance as any).close) {
          (ref.instance as any).close.subscribe(val => this.close.emit(val));
        }
      }
    }
  }

  onMessageClick() {
    this.click.emit();
  }
}
