import { Inject, Injectable } from '@angular/core';
import { DestroySubject, LocalStorageService } from '@honoregaming/core';
import { PrivacyConfiguration } from '@honoregaming/configuration';
import { BehaviorSubject, Observable } from 'rxjs';
import { CustomerOperatorConfiguration, customerOperatorConfigurationToken } from '../models';

const PrivacyConfigurationKey = 'jwt_privacyConfiguration';

@Injectable()
export class PrivacyService extends DestroySubject {
  privacyConfigurationSubject$: BehaviorSubject<PrivacyConfiguration>;
  privacyConfiguration$: Observable<PrivacyConfiguration>;

  private _privacyConfiguration: PrivacyConfiguration;

  constructor(
    private localStorageService: LocalStorageService,
    @Inject(customerOperatorConfigurationToken) private customerOperatorConfiguration: CustomerOperatorConfiguration
  ) {
    super();
  }

  public initializePrivacyConfiguration(): PrivacyConfiguration {
    this._privacyConfiguration = this.localStorageService.getItem(PrivacyConfigurationKey);
    var isPrivacyActive = !!this.customerOperatorConfiguration.privacyConfiguration;

    if (isPrivacyActive) {
      if (this._privacyConfiguration) {
        this.privacyConfigurationSubject$ = new BehaviorSubject(this._privacyConfiguration);
        this.resetPrivacyConfiguration();
      } else {
        this.privacyConfigurationSubject$ = new BehaviorSubject(null);
      }
    } else {
      var newPc = {} as PrivacyConfiguration;
      newPc.consents = {} as any;
      newPc.consents.analytics = true;
      this.privacyConfigurationSubject$ = new BehaviorSubject(newPc);
    }
    this.privacyConfiguration$ = this.privacyConfigurationSubject$.asObservable();

    return this._privacyConfiguration;
  }

  resetPrivacyConfiguration() {
    const now = new Date();
    const consentExpiration = new Date(now.setMonth(now.getMonth() - 6));

    const storedDate = this._privacyConfiguration?.date ? new Date(this._privacyConfiguration?.date) : null;

    if (storedDate <= consentExpiration) {
      this.localStorageService.removeItem(PrivacyConfigurationKey);
      this._privacyConfiguration = null;
      this.privacyConfigurationSubject$.next(null);
    }
  }

  setPrivacyConfiguration(privacyConfiguration: PrivacyConfiguration) {
    privacyConfiguration.date = new Date().toString();
    this.localStorageService.setItem(PrivacyConfigurationKey, privacyConfiguration);
    this._privacyConfiguration = privacyConfiguration;

    this.privacyConfigurationSubject$.next(privacyConfiguration);
  }
}
