import { BetLine } from '../models';
import { BetCategoryType, BetSlipMode, BetSystemType, HorseRacingFormulaKeyType } from '@honoregaming/types';
import { BettingTax, PaymentTax } from '@honoregaming/configuration';
import { I18nService } from '@honoregaming/i18n';
import {
  areClose,
  floorNumber,
  preciseFloatingPointNumber,
  roundNumber,
  Scope,
  mod,
  sub,
  add,
  div,
  mul
} from '@honoregaming/core';

export const MAXIMUM_SYSTEM_AMOUNTS = 6;

function getCombinations(betLineNumbers: number[], k: number, start = 0, initialStuff = [], result = []) {
  if (initialStuff.length >= k) {
    result.push(initialStuff);
  } else {
    for (let i = start; i < betLineNumbers.length; ++i) {
      getCombinations(betLineNumbers, k, i + 1, initialStuff.concat(betLineNumbers[i]), result);
    }
  }
}

export function getAllCombinations(betlineNumbers: number[], k: number): number[][] {
  const result = [];
  getCombinations(betlineNumbers, k, 0, [], result);
  return result;
}

export function getCasesNumber(k: number, n: number): number {
  if (k > n) {
    const temp = k;
    k = n;
    n = temp;
  }

  return factorial(n) / (factorial(n - k) * factorial(k));
}

export function factorial(input: number, limit?: number): number {
  let result = 1;
  if (!limit) {
    limit = 1;
  }

  for (let i = input; i >= limit; i--) {
    result = result * i;
  }

  return result;
}

export function getBetLineIndex(betLineToFind: BetLine, betLines: BetLine[]): number {
  if (betLineToFind.number) {
    return betLines.findIndex(value => betLineToFind.number === value.number);
  }

  if (
    betLineToFind.betCategoryType === BetCategoryType.HorseRacingMutualOperatorPool ||
    betLineToFind.betCategoryType === BetCategoryType.HorseRacingMutualInternationalPool
  ) {
    return betLines.findIndex(value => {
      return (
        value.eventBetTypeId === betLineToFind.eventBetTypeId && betLineToFind.betCategoryType === value.betCategoryType
      );
    });
  }

  if (betLineToFind.betCategoryType === BetCategoryType.DrawGame) {
    // Duplicate selections are allowed for other draw-games
    return -1;
  }

  if (betLineToFind.oddsBoostId) {
    return betLines.findIndex(value => {
      return value.oddsBoostId === betLineToFind.oddsBoostId;
    });
  }

  if (betLineToFind.manualOddsBoostId) {
    return betLines.findIndex(value => {
      return value.manualOddsBoostId === betLineToFind.manualOddsBoostId;
    });
  }

  if (betLineToFind.eventBetTypeItemId) {
    return betLines.findIndex(value => {
      return (
        value.eventBetTypeId === betLineToFind.eventBetTypeId &&
        value.eventBetTypeItemId === betLineToFind.eventBetTypeItemId &&
        betLineToFind.betCategoryType === value.betCategoryType
      );
    });
  }

  return betLines.findIndex(value => {
    return (
      value.eventBetTypeId === betLineToFind.eventBetTypeId &&
      value.baseList === betLineToFind.baseList &&
      value.extraList === betLineToFind.extraList &&
      betLineToFind.betCategoryType === value.betCategoryType
    );
  });
}

export function getDrawGameBetLineToUpdateIndex(betLineToFind: BetLine, betLines: BetLine[]): number {
  if (betLineToFind.entryPointId === 9003) {
    return betLines.findIndex(value => {
      return betLineToFind.eventBetTypeId === value.eventBetTypeId;
    });
  } else {
    return betLines.findIndex(value => {
      return (
        betLineToFind.eventBetTypeId === value.eventBetTypeId &&
        betLineToFind.betCategoryType === value.betCategoryType &&
        betLineToFind.baseList === value.baseList &&
        betLineToFind.extraList === value.extraList
      );
    });
  }
}

export function hasDuplicatedItems(items: any[]) {
  const uniq = items.reduce((a, b) => {
    a[b] = (a[b] || 0) + 1;
    return a;
  }, {});

  const duplicates = Object.keys(uniq).filter(a => uniq[a] > 1);

  return duplicates.length > 0;
}

export function combinaison(n: number, k: number): number {
  let result = n;
  for (let i = 1; i < k; i++) {
    result = result * (n - i);
  }

  return result;
}

export function getMultipleForHorseRacing(
  runnersNumberToSelect: number,
  runnersNumber: number,
  baseListLength: number,
  associatedListLength: number,
  formulaKey: HorseRacingFormulaKeyType,
  isOrderedBetType: boolean,
  allOrders: boolean
): number {
  if (formulaKey === HorseRacingFormulaKeyType.Unit || formulaKey === HorseRacingFormulaKeyType.Combined) {
    return getMultipleForUnitOrCombined(runnersNumberToSelect, baseListLength, allOrders);
  }

  if (formulaKey === HorseRacingFormulaKeyType.PartWheel) {
    return getMultipleForPartWheel(
      runnersNumberToSelect,
      baseListLength,
      associatedListLength,
      isOrderedBetType,
      allOrders
    );
  }

  if (formulaKey === HorseRacingFormulaKeyType.Wheel) {
    return getMultipleForWheel(runnersNumberToSelect, runnersNumber, baseListLength, isOrderedBetType, allOrders);
  }

  return null;
}

function getMultipleForUnitOrCombined(
  runnersNumberToSelect: number,
  baseListLength: number,
  allOrders: boolean
): number {
  if (baseListLength < runnersNumberToSelect) {
    return null;
  }

  if (baseListLength === runnersNumberToSelect) {
    if (allOrders) {
      return factorial(runnersNumberToSelect);
    } else {
      return 1;
    }
  }

  const c = combinaison(baseListLength, runnersNumberToSelect);
  if (allOrders) {
    return c;
  }
  return c / factorial(runnersNumberToSelect);
}

function getMultipleForPartWheel(
  runnersNumberToSelect: number,
  baseListLength: number,
  associatedListLength: number,
  isOrderedBetType: boolean,
  allOrders: boolean
): number {
  if (
    !baseListLength ||
    baseListLength > runnersNumberToSelect - 1 ||
    baseListLength + associatedListLength < runnersNumberToSelect
  ) {
    return null;
  }

  let value = 1;
  for (let i = baseListLength, j = 0; i < runnersNumberToSelect; i++, j++) {
    value *= associatedListLength - j;
  }

  if (allOrders) {
    return value * factorial(runnersNumberToSelect, runnersNumberToSelect - baseListLength + 1);
  } else if (!isOrderedBetType) {
    return value / factorial(runnersNumberToSelect - baseListLength);
  }

  return value;
}

function getMultipleForWheel(
  runnersNumberToSelect: number,
  runnersNumber: number,
  baseListLength: number,
  isOrderedBetType: boolean,
  allOrders: boolean
): number {
  if (!baseListLength || baseListLength > runnersNumberToSelect - 1) {
    return null;
  }

  let value = 1;
  for (let i = baseListLength, j = 0; i < runnersNumberToSelect; i++, j++) {
    value *= runnersNumber - baseListLength - j;
  }

  if (allOrders) {
    return value * factorial(runnersNumberToSelect, runnersNumberToSelect - baseListLength + 1);
  } else if (!isOrderedBetType) {
    return value / factorial(runnersNumberToSelect - baseListLength);
  }

  return value;
}

export function getBetLineAmountErrorAndCode(
  i18nService: I18nService,
  amount: number,
  baseAmount: number,
  maxAmount: number,
  increment: number,
  newStake?: number,
  maxPayout?: number,
  useFreeBet?: boolean,
  balance?: number,
  scope?: Scope
): { error?: string; code?: string } {
  let errorSuffix: string;
  let errorAmount: string;
  if (amount < baseAmount) {
    errorSuffix = 'MINIMIUM_STAKE_AMOUNT';
    errorAmount = i18nService.formatCurrencySync(baseAmount, true);
  } else if (amount > maxAmount) {
    errorSuffix = 'MAXIMUM_STAKE_AMOUNT';
    errorAmount = i18nService.formatCurrencySync(maxAmount, true);
  } else if (
    mod(amount, increment) !== 0 &&
    (scope === Scope.Customer && balance != null ? !areClose(amount, balance, 1e-2) : true)
  ) {
    errorSuffix = 'MULTIPLE_STAKE_AMOUNT';
    errorAmount = i18nService.formatNumberSync(increment, true, '1.2-2');
  } else if (!!newStake) {
    errorSuffix = 'STAKE_TOO_HIGH.NEW_STAKE';
    errorAmount = i18nService.formatCurrencySync(newStake, true);
  } else if (maxPayout !== null && (maxPayout === 0 || (amount >= maxPayout && !useFreeBet))) {
    [errorSuffix, errorAmount] =
      amount >= baseAmount
        ? ['UNPROFITABLE_BET', '']
        : ['STAKE_TOO_LOW.MAX_PAYOUT', i18nService.formatCurrencySync(maxPayout, true)];
  }

  if (errorSuffix) {
    return {
      error: i18nService.translateSync('BET-SLIP.BETTING_ERROR.' + errorSuffix, errorAmount),
      code: errorSuffix
    };
  }

  return { error: undefined, code: undefined };
}

export function getBetLineAmountError(
  i18nService: I18nService,
  amount: number,
  baseAmount: number,
  maxAmount: number,
  increment: number,
  newStake?: number,
  maxPayout?: number,
  useFreeBet?: boolean,
  balance?: number,
  scope?: Scope
): string | undefined {
  return getBetLineAmountErrorAndCode(
    i18nService,
    amount,
    baseAmount,
    maxAmount,
    increment,
    newStake,
    maxPayout,
    useFreeBet,
    balance,
    scope
  ).error;
}

export function computeBettingTaxAmounts(
  amount: number,
  tax: BettingTax,
  numberOfDecimals: number
): { amount: number; tax: number } {
  if (tax && amount > tax.threshold) {
    let baseAmount = amount;
    if (!tax.thresholdParticipateToTax) {
      baseAmount = amount - tax.threshold;
    }

    let amountWithoutTax = tax.inverse ? baseAmount / (1 + tax.rate) : baseAmount * (1 - tax.rate);

    if (!tax.thresholdParticipateToTax) {
      amountWithoutTax += tax.threshold;
    }

    amountWithoutTax = roundNumber(preciseFloatingPointNumber(amountWithoutTax), numberOfDecimals);

    return { amount: amountWithoutTax, tax: roundNumber(amount - amountWithoutTax, numberOfDecimals) };
  } else {
    return { amount: amount, tax: null };
  }
}

export function computePaymentTaxAmounts(
  stake: number,
  maxPayout: number,
  tax: PaymentTax,
  decimals: number
): { amount: number; tax: number } {
  // CreateBetHandler always floors the gross payout before applying the payment tax, even when taxBeforeRounding is enabled
  maxPayout = floorNumber(preciseFloatingPointNumber(maxPayout), decimals);
  let baseAmount = maxPayout;
  let netGain = sub(maxPayout, stake);
  var taxableNetGain = netGain;

  if (tax && maxPayout > tax.threshold && taxableNetGain > tax.threshold) {
    if (!tax.thresholdParticipateToTax) {
      if (tax.isOnNetGain) {
        taxableNetGain = sub(netGain, tax.threshold);
      }

      baseAmount = sub(maxPayout, tax.threshold);
    }

    let amountWithoutTax = tax.inverse
      ? div(baseAmount, 1 + tax.rate)
      : !tax.isOnNetGain
      ? mul(baseAmount, 1 - tax.rate)
      : sub(baseAmount, taxableNetGain * tax.rate);

    if (!tax.thresholdParticipateToTax) {
      amountWithoutTax = add(amountWithoutTax, tax.threshold);
    }

    if (tax.minimumStakeGain === true && amountWithoutTax < stake) {
      amountWithoutTax = Math.min(stake, maxPayout);
    }

    var amountWithoutTaxBeforeRounding = amountWithoutTax;
    amountWithoutTax = floorNumber(preciseFloatingPointNumber(amountWithoutTax), decimals);

    if (tax.roundingIncludedInTax === true) {
      return {
        amount: amountWithoutTax,
        tax: sub(maxPayout, amountWithoutTax)
      };
    }

    return {
      amount: amountWithoutTax,
      tax: sub(maxPayout, amountWithoutTaxBeforeRounding)
    };
  } else {
    return { amount: maxPayout, tax: null };
  }
}

export function convertBetSlipModeToBetSystemType(mode: BetSlipMode): BetSystemType {
  if (mode === BetSlipMode.Simple) {
    return BetSystemType.Simple;
  } else if (mode === BetSlipMode.Multiple) {
    return BetSystemType.Multiple;
  }

  return BetSystemType.System;
}

export function convertBetSystemTypeToBetSlipMode(type: BetSystemType): BetSlipMode {
  if (type === BetSystemType.Simple) {
    return BetSlipMode.Simple;
  } else if (type === BetSystemType.Multiple) {
    return BetSlipMode.Multiple;
  }

  return BetSlipMode.Systems;
}
