import {
  Component,
  OnInit,
  ChangeDetectionStrategy,
  Output,
  EventEmitter,
  ElementRef,
  ViewChild,
  ChangeDetectorRef,
  Input,
  Inject
} from '@angular/core';
import { DestroySubject } from '@honoregaming/core';
import { AuthService, CustomerService, Me, PasswordService } from '@honoregaming/customer-core';
import { PasswordPolicy, ProfilePolicy, SecurityPolicy } from '@honoregaming/types';
import { finalize, takeUntil } from 'rxjs/operators';
import { ChangeCustomerPasswordFailure } from '../../models/change-password-failure.model';
import { OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';
import { Router } from '@angular/router';
import { forkJoin } from 'rxjs';

@Component({
  selector: 'hg-account-update-password',
  templateUrl: './account-update-password.component.html',
  styleUrls: ['./account-update-password.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class AccountUpdatePasswordComponent extends DestroySubject implements OnInit {
  @ViewChild('updatePasswordElement') updateEmailElement: ElementRef;
  @Input() resetMode = false;

  securityPolicy: SecurityPolicy;
  profilePolicyRequirements: ProfilePolicy;
  passwordPolicyRequirements: PasswordPolicy;
  login: string;
  loginWithoutPrefix: string;
  email: string;
  errorMessage: string;
  password: string;
  oldPassword: string;
  newPassword: string;
  showCurrentPasswordValue = false;
  showPasswordValue = false;
  showConfirmPasswordValue = false;
  loading: boolean = false;
  success: boolean = false;
  changeDone = false;
  error: string;
  me: Me;
  hasDigital: boolean;
  hasNonLetterOrDigit: boolean;
  hasLowerCharacter: boolean;
  hasUppercharacter: boolean;
  hasPasswordLength: boolean;
  hasConsecutiveNumberSequence: boolean;
  hasConsecutiveLetterSequence: boolean;
  hasSameCharacterRepeated: boolean;
  isEqualToLogin: boolean;
  hiddenPassword: string;
  confirmPassword: string;
  newOldPassword: string;
  newConfirmPassword: string;
  requireLowercase: boolean;
  requireUppercase: boolean;
  requireDigit: boolean;
  requireNonLetterOrDigit: boolean;
  requiredLength: number;
  preventConsecutiveSequence: boolean;
  preventSameCharacterRepeated: boolean;
  preventEqualToLogin: boolean;
  maxLoginDuration: number;
  prefixes: string[];

  @Output()
  backEvent = new EventEmitter();
  showMfa: boolean;
  mfaCode: string;

  constructor(
    protected router: Router,
    private readonly customerService: CustomerService,
    private readonly cdRef: ChangeDetectorRef,
    private readonly authService: AuthService,
    @Inject(operatorConfigurationToken) private readonly operatorConfiguration: OperatorConfiguration,
    private readonly passwordService: PasswordService
  ) {
    super();
  }

  ngOnInit() {
    const meRequest = this.authService.getMe();
    const securityPolicyRequest = this.customerService.getSecurityPolicy();

    forkJoin([meRequest, securityPolicyRequest])
      .pipe(takeUntil(this.destroy$))
      .subscribe(([me, securityPolicy]) => {
        this.login = me.login;
        this.securityPolicy = securityPolicy;
        this.passwordPolicyRequirements = this.securityPolicy.passwordPolicyRequirements;
        this.profilePolicyRequirements = this.securityPolicy.profilePolicyRequirements;
        this.prefixes = this.securityPolicy.loginPoliciesRequirements.map(r => r.prefix);
        this.loginWithoutPrefix = this.getLoginWithoutPrefix();
        this.requireLowercase = this.passwordPolicyRequirements.requireLowercase;
        this.requireUppercase = this.passwordPolicyRequirements.requireUppercase;
        this.requireDigit = this.passwordPolicyRequirements.requireDigit;
        this.requiredLength = this.passwordPolicyRequirements.requiredLength;
        this.requireNonLetterOrDigit = this.passwordPolicyRequirements.requireNonLetterOrDigit;
        this.preventConsecutiveSequence = this.passwordPolicyRequirements.preventConsecutiveSequence;
        this.preventSameCharacterRepeated = this.passwordPolicyRequirements.preventSameCharacterRepeated;
        this.preventEqualToLogin = this.passwordPolicyRequirements.preventEqualToLogin;
        this.cdRef.markForCheck();
      });
    this.maxLoginDuration = this.operatorConfiguration.onlineConfiguration?.customerLoginMaximumDuration;
  }

  onChange(password: string, type: string) {
    const result = this.passwordService.checkPassword(password, this.loginWithoutPrefix);

    this.hasConsecutiveLetterSequence = result.hasConsecutiveLetterSequence;
    this.hasDigital = result.hasDigital;
    this.hasLowerCharacter = result.hasLowerCharacter;
    this.hasUppercharacter = result.hasUppercharacter;
    this.hasConsecutiveNumberSequence = result.hasConsecutiveNumberSequence;
    this.hasSameCharacterRepeated = result.hasSameCharacterRepeated;
    this.isEqualToLogin = result.isEqualToLogin;
    this.hasPasswordLength = result.hasPasswordLength;
    this.hasNonLetterOrDigit = result.hasNonLetterOrDigit;

    this.changeToAsterisk(password, type);
    this.cdRef.markForCheck();
  }

  getLoginWithoutPrefix(): string {
    const prefix = this.prefixes?.find(p => this.login.startsWith(p));

    if (prefix) {
      return this.login.replace(prefix, '');
    }

    return this.login;
  }

  changeToAsterisk(event: string, password: string) {
    this.error = null;
    let replaceRegex = /^[-'a-zA-ZÀ-ÖØ-öø-ÿ-Z0-9.!@?#"$%&:';()*\+,\/;\-=[\\\]\^_{|}<>~` ]+$/;

    if (password === 'old') {
      this.newOldPassword = event.replace(replaceRegex, '*').repeat(event.length);
    } else if (password === 'confirm') {
      this.newConfirmPassword = event.replace(replaceRegex, '*').repeat(event.length);
    } else if (password === 'new') {
      this.hiddenPassword = event.replace(replaceRegex, '*').repeat(event.length);
    }
  }

  submit() {
    if (this.operatorConfiguration.mfaConfiguration?.customerConfiguration?.updatePassword) {
      this.showMfa = true;
      this.cdRef.markForCheck();
    } else {
      this.sendSubmit();
    }
  }

  sendRequestWithMFA(code: string) {
    this.mfaCode = code;
    this.showMfa = false;
    this.sendSubmit();
  }

  sendSubmit() {
    this.loading = true;
    this.error = null;
    this.customerService
      .changePassword(this.oldPassword, this.newPassword, this.mfaCode)
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.showMfa = false;
          this.loading = false;
          this.cdRef.markForCheck();
        })
      )
      .subscribe(
        () => {
          this.reset();
          if (this.resetMode) {
            this.authService.refresh().subscribe();
            this.authService.getMe().subscribe(_ => {
              this.router.navigate(['/sports']);
            });
          }
        },
        err => {
          if (err.error && err.error.code) {
            if (err.error.code === ChangeCustomerPasswordFailure.WrongOldPassword) {
              this.error = 'ACCOUNT.CHANGE_PASSWORD.WRONG_OLD_PASSWORD';
            } else if (err.error.code === ChangeCustomerPasswordFailure.WrongValidationCode) {
              this.error = 'ACCOUNT.CHANGE_PASSWORD.WRONG_VALIDATION_CODE';
            } else if (err.error.code === ChangeCustomerPasswordFailure.SamePasswordReuseNotAllowed) {
              this.error = 'ACCOUNT.CHANGE_PASSWORD.SAME_PASSWORD_REUSE_NOT_ALLOWED';
            } else if (err.error.code === ChangeCustomerPasswordFailure.CannotEditAccountInformations) {
              this.error = 'ACCOUNT.CHANGE_PASSWORD.CANNOT_EDIT_ACCOUNT_INFORMATIONS';
            } else if (err.error.code === ChangeCustomerPasswordFailure.ResourceValidationMessageNotFound) {
              this.error = 'ACCOUNT.LOST_PASSWORD.ERROR.RESOURCES_VALIDATION_MESSAGE_NOT_FOUND';
            } else if (err.error.code === ChangeCustomerPasswordFailure.LimitReached) {
              this.error = 'ACCOUNT.LOST_PASSWORD.ERROR.LIMIT_REACHED';
            } else if (err.error.code === ChangeCustomerPasswordFailure.CommunicationProviderNotFound) {
              this.error = 'ACCOUNT.LOST_PASSWORD.ERROR.COMMUNICATION_PROVIDER_NOT_FOUND';
            } else if (
              err.error.code === ChangeCustomerPasswordFailure.MfaCodeExpired ||
              err.error.code === ChangeCustomerPasswordFailure.MfaCodeNotFound ||
              err.error.code === ChangeCustomerPasswordFailure.MfaCodeRefreshNeeded ||
              err.error.code === ChangeCustomerPasswordFailure.MfaCodeRequired ||
              err.error.code === ChangeCustomerPasswordFailure.MfaTypeInvalid
            ) {
              this.error = 'ACCOUNT.MFA.ERROR';
            }
          }

          this.error = this.error || 'COMMON_GENERIC_ERROR';
        }
      );
  }

  reset() {
    this.changeDone = true;
    this.oldPassword = null;
    this.newPassword = null;
    this.hiddenPassword = null;
    this.newOldPassword = null;
    this.newConfirmPassword = null;
    this.confirmPassword = null;
    this.hasNonLetterOrDigit = false;
    this.hasDigital = false;
    this.hasLowerCharacter = false;
    this.hasUppercharacter = false;
    this.hasPasswordLength = false;
  }

  back() {
    this.backEvent.emit(this.password);
  }
}
