import { Component, ChangeDetectionStrategy, Input, Output, EventEmitter } from '@angular/core';
import { Router } from '@angular/router';
import { BetSystemHistory } from '@honoregaming/types';
import { SportsPoolTopWinBetData } from 'projects/core/hg-types/models/top-win-bets';

@Component({
  selector: 'hg-sports-pool-bet-system',
  templateUrl: './sports-pool-bet-system.component.html',
  styleUrls: ['./sports-pool-bet-system.component.scss', '../generic-bet-system.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class SportsPoolBetSystemComponent {
  @Input() betSystem!: BetSystemHistory;
  @Input() data!: SportsPoolTopWinBetData;

  @Output() closeEvent = new EventEmitter<void>();

  constructor(private readonly router: Router) {}

  navigateSportsPoolGame(sportsPoolGameId: number): void {
    this.closeEvent.emit();
    this.router.navigate(['/sports-pool/results', sportsPoolGameId]);
  }
}
