// Shuffle using Fisher–Yates shuffle algorithm: https://en.wikipedia.org/wiki/Fisher–Yates_shuffle
export function shuffleArray<T>(array: T[]): T[] {
  let currentIndex = array.length;
  let randomIndex;

  // While there remain elements to shuffle...
  while (currentIndex != 0) {
    // Pick a remaining element...
    randomIndex = Math.floor(Math.random() * currentIndex);
    currentIndex--;

    // And swap it with the current element.
    [array[currentIndex], array[randomIndex]] = [array[randomIndex], array[currentIndex]];
  }

  return array;
}

export function getRandomFromArray(array: any[]) {
  return array[Math.floor(Math.random() * array.length)];
}

// Build a sequence of `count` consecutive numbers, e.g. range(3, 1) => [1, 2, 3]
export function range(count: number, start: number = 0): number[] {
  return Array.from(Array(Math.max(count, 0)), (_value, index) => index + start);
}

// Sort numbers in ascending order (Array.sort defaults to a lexicographic comparison)
export function sortNumbersAsc(numbers: number[]): number[] {
  return [...numbers].sort((first, second) => first - second);
}
