import { Component, ChangeDetectionStrategy, Input, OnInit } from '@angular/core';
import { I18nService } from '@honoregaming/i18n';
import { InstantGameState, InstantGameTransaction, InstantGameSelection, InstantGameName } from '@honoregaming/types';
import { ToasterService } from '@honoregaming/ui';
import { take } from 'rxjs/operators';

@Component({
  selector: 'hg-roulette-transaction',
  templateUrl: './roulette-transaction.component.html',
  styleUrls: ['./roulette-transaction.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class RouletteTransactionComponent implements OnInit {
  @Input()
  transaction: InstantGameTransaction;

  InstantGameName = InstantGameName;
  InstantGameState = InstantGameState;
  selection: InstantGameSelection[] = [];

  constructor(private toasterService: ToasterService, private i18n: I18nService) {}

  ngOnInit() {
    if (this.transaction.instantGameName === InstantGameName.Roulette) {
      this.selection = JSON.parse(this.transaction.result);
    }
  }

  contentCopied() {
    this.i18n
      .translate('ACCOUNT.COPIED.REFERENCE')
      .pipe(take(1))
      .subscribe(translation => this.toasterService.show(translation));
  }
}
