import { HttpClient } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { globalConfiguration } from '@honoregaming/configuration';
import { Cacheable } from '@honoregaming/core';
import { Observable, BehaviorSubject } from 'rxjs';

@Injectable({ providedIn: 'root' })
export class LiveEventsCountService {
  private liveCountChangedChangedSubject = new BehaviorSubject<number>(null);
  liveCountChangedChanged$ = this.liveCountChangedChangedSubject.asObservable();

  constructor(private httpClient: HttpClient) {}

  incrementListCount(increment: number) {
    this.liveCountChangedChangedSubject.next(increment);
  }

  @Cacheable()
  getLiveSportsEventsCount(): Observable<number> {
    return this.httpClient.get<number>(`${globalConfiguration.apiEventsBaseUrl}events/sports/live-count`);
  }
}
