import { Component, OnInit, ChangeDetectionStrategy, Input } from '@angular/core';
import { TicketHistory, TicketState } from '@honoregaming/types';

@Component({
  selector: 'hg-ticket-state',
  templateUrl: './ticket-state.component.html',
  styleUrls: ['./ticket-state.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class TicketStateComponent implements OnInit {
  @Input()
  ticketNumber: number;

  @Input()
  ticket: TicketHistory;

  TicketState = TicketState;

  summary: {
    totalStack: number;
    totalEarning: number;
  };

  constructor() {}

  ngOnInit() {
    this.summary = this.ticket.betSystems.reduce(
      (summary, betSystem) => {
        summary.totalStack += betSystem.totalStake;
        summary.totalEarning += betSystem.earning;
        return summary;
      },
      {
        totalStack: 0,
        totalEarning: 0
      }
    );
  }
}
