import { Component, ChangeDetectionStrategy, Input, Output, EventEmitter, OnInit } from '@angular/core';
import { NumbersSelectionToolBase } from '../base/numbers-selection-tool-base';
import { NumberItem } from '../base/model/number-item';

@Component({
  selector: 'hg-simple-numbers-selection-tool',
  templateUrl: './simple-numbers-selection-tool.component.html',
  styleUrls: ['./simple-numbers-selection-tool.component.scss', '../base/numbers-selection-tool.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class SimpleNumbersSelectionToolComponent extends NumbersSelectionToolBase implements OnInit {
  @Input() title: string;
  @Input() numbers: string[] = [];
  @Input() disabledNumbers?: string[];
  @Input() showSelectAll: boolean = true;
  @Output() close: EventEmitter<string[]> = new EventEmitter<string[]>();

  numberItems: NumberItem[] = [];

  constructor() {
    super();
  }

  ngOnInit(): void {
    this.numberItems = this.numbers.map(x => ({
      number: x,
      selected: false,
      disabled: this.disabledNumbers?.includes(x) ?? false
    }));
  }
}
