export interface Loyalty {
  currentStatus?: LoyaltyStatus;
  nextStatus?: LoyaltyStatus;
  monthlyPoints: number;
  totalPoints: number;
}

export interface LoyaltyStatus {
  name: string;
  icon: string;
  threshold: number;
}

export interface LoyaltyRedeemable {
  id: number;
  price: number;
  amount?: number;
  item?: string;
  type: LoyaltyRedeemableType;
}

export enum LoyaltyRedeemableType {
  Unknown = 'Unknown',
  Item = 'Item',
  CashBundle = 'CashBundle',
  FreeBetBundle = 'FreeBetBundle'
}

export interface LoyaltyRedeemableItemCode {
  item: string;
  code: string;
  expireDate: Date;
  date: Date;
  login?: string;
  price?: number;
}

export interface GetCustomerLoyaltyResponse {
  loyalty: Loyalty;
  loyaltyRedeemables: LoyaltyRedeemable[];
  changeItemCodes: LoyaltyRedeemableItemCode[];
}
