import { Component, OnInit, ChangeDetectionStrategy, Input, ChangeDetectorRef } from '@angular/core';
import { BetCategoryType, EventCategory } from '@honoregaming/types';
import { BetLine } from '../../../models';
import { EventCategoriesService } from '@honoregaming/events';

@Component({
  selector: 'hg-numbers-game-bet-line-header',
  templateUrl: './numbers-game-bet-line-header.component.html',
  styleUrls: ['./numbers-game-bet-line-header.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class NumbersGameBetLineHeaderComponent implements OnInit {
  @Input()
  betLine: BetLine;

  BetCategoryType = BetCategoryType;
  eventCategory: EventCategory;
  isLoading: boolean;

  constructor(private eventCategoriesService: EventCategoriesService, protected cdRef: ChangeDetectorRef) {}

  ngOnInit() {
    this.isLoading = true;
    this.eventCategoriesService.getEventCategory(this.betLine.entryPointId).subscribe(eventCategory => {
      this.eventCategory = eventCategory;
      this.isLoading = false;
      this.cdRef.markForCheck();
    });
  }
}
