import { Component, ChangeDetectionStrategy, Input, OnInit } from '@angular/core';

@Component({
  selector: 'hg-number-compact',
  templateUrl: './number-compact.component.html',
  styleUrls: ['./number-compact.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class NumberCompactComponent implements OnInit {
  @Input()
  value: number;
  compactNumber: string;

  constructor() {}

  ngOnInit() {
    this.compactNumber = this.getCompactNumber();
  }

  getCompactNumber(): string {
    var number = this.value;
    if (number >= 1000000 && number <= 999999999) {
      return number / 1000000 + 'M';
    } else if (number >= 1000000000 && number <= 999999999999) {
      return number / 1000000000 + 'B';
    } else return number.toString();
  }
}
