import { ChangeDetectionStrategy, Component } from '@angular/core';
import { I18nService } from '@honoregaming/i18n';

@Component({
  selector: 'hg-responsible-gambling',
  templateUrl: './responsible-gambling.component.html',
  styleUrls: ['./responsible-gambling.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class ResponsibleGamblingComponent {
  isSelfLimitation = true;
  alertOpened: boolean;
  errorMessage: string;
  hasError: boolean;

  constructor(private i18nService: I18nService) {}

  navigate(isSelfLimitation: boolean) {
    this.isSelfLimitation = isSelfLimitation;
  }

  close() {
    this.alertOpened = false;
    this.hasError = false;
  }

  requestSuccessed(successed: any) {
    this.alertOpened = true;
    if (successed?.errorMessageKey) {
      this.hasError = true;
      this.i18nService.translate(successed?.errorMessageKey).subscribe(x => {
        this.errorMessage = x;
      });
    }
  }
}
