import {
  EventBetType,
  EventBetTypeChangedModel,
  Match,
  EventChangedModel,
  OddsBoost,
  OddsBoostDetail
} from '@honoregaming/types';

export const roundNumber = (value: number, numberOfDecimals: number) => {
  const factor = Math.pow(10, numberOfDecimals);
  const valueToRound = value * factor;
  const flooredValue = Math.floor(valueToRound);

  if (Math.pow(valueToRound - flooredValue - 0.5, 2) > 1e-15) {
    return Math.round(valueToRound) / factor;
  }

  return (flooredValue % 2 === 0 ? flooredValue : flooredValue + 1) / factor;
};

export const realRoundNumber = (value: number, numberOfDecimals: number) => {
  const factor = Math.pow(10, numberOfDecimals);
  const valueToRound = value * factor;

  return Math.round(valueToRound) / factor;
};

export const floorNumber = (value: number, numberOfDecimals: number) => {
  const factor = Math.pow(10, numberOfDecimals);
  const valueToRound = value * factor;

  return Math.floor(valueToRound) / factor;
};

export const ceilNumber = (value: number, numberOfDecimals: number) => {
  const factor = Math.pow(10, numberOfDecimals);
  const valueToRound = value * factor;

  return Math.ceil(valueToRound) / factor;
};

// ------ https://floating-point-gui.de/
export const preciseFloatingPointNumber = (value: number, precisionDecimals: number = 7) => {
  const integerLength = Math.trunc(value).toString().length;
  return parseFloat(value.toPrecision(integerLength + precisionDecimals));
};

export class ConsoleFactory {
  private static scopes: { [scope: string]: { active: boolean; console: Console } } = {};
  public static create(scope: string): Console {
    if (!this.scopes[scope]) {
      this.scopes[scope] = {
        active: false,
        console: {
          ...console,
          log: (...args) => this.scopes[scope].active && console.log(...args),
          warn: (...args) => this.scopes[scope].active && console.warn(...args),
          error: (...args) => this.scopes[scope].active && console.error(...args)
        }
      };
    }
    return this.scopes[scope].console;
  }

  public static toggleScope(scope: string, enforce?: boolean) {
    if (this.scopes[scope]) {
      this.scopes[scope].active = enforce === undefined ? !this.scopes[scope] : enforce;
    }
  }
}

// override default console to hide
if (typeof window !== 'undefined') {
  window['toggleLogging'] = (scope: string, enforce?: boolean) => {
    ConsoleFactory.toggleScope(scope, enforce);
  };
}

const pushConsole = ConsoleFactory.create('push');

export function updateEventBetTypeAfterPush(
  eventBetType: EventBetType,
  eventBetTypeChangedModel: EventBetTypeChangedModel
) {
  if (eventBetTypeChangedModel.items) {
    for (const ebtiChanged of eventBetTypeChangedModel.items) {
      const ebtiIndex = eventBetType.eventBetTypeItems.findIndex(z => z.id === ebtiChanged.eventBetTypeItemId);

      if (ebtiIndex < 0) {
        continue;
      }

      eventBetType.eventBetTypeItems[ebtiIndex] = {
        ...eventBetType.eventBetTypeItems[ebtiIndex],
        odds: ebtiChanged.odds,
        bettingAllowed: ebtiChanged.bettingAllowed
      };
      pushConsole.warn(
        'updating ebti',
        eventBetType.eventBetTypeItems[ebtiIndex].id,
        ebtiChanged.bettingAllowed,
        ebtiChanged.odds
      );
    }

    eventBetType.eventBetTypeItems = [...eventBetType.eventBetTypeItems];
  }

  if (
    eventBetTypeChangedModel.bettingAllowed !== undefined &&
    eventBetTypeChangedModel.bettingAllowed !== null &&
    eventBetTypeChangedModel.bettingAllowed !== eventBetType.bettingAllowed
  ) {
    eventBetType.bettingAllowed = eventBetTypeChangedModel.bettingAllowed;
    pushConsole.error('setting bettingallowed to ebt', eventBetType.id, eventBetType.bettingAllowed);
  }
}

export function updateEventAfterPush(
  event: Match,
  eventBetTypes: EventBetType[],
  eventChangedModel: EventChangedModel
) {
  const patch: any = {};
  if (eventChangedModel.changes['awayTeamScore']) {
    patch.awayTeamScore = eventChangedModel.changes['awayTeamScore'];
  }
  if (eventChangedModel.changes['homeTeamScore']) {
    patch.homeTeamScore = eventChangedModel.changes['homeTeamScore'];
  }
  if (eventChangedModel.changes['scores']) {
    patch.scores = eventChangedModel.changes['scores'];
  }
  if (
    eventChangedModel.changes['liveBettingAllowed'] !== undefined ||
    eventChangedModel.changes['betStop'] !== undefined
  ) {
    if (eventChangedModel.changes['liveBettingAllowed'] !== undefined) {
      pushConsole.error('Received an liveBettingAllowed', eventChangedModel.changes['liveBettingAllowed']);
    }

    if (eventChangedModel.changes['betStop'] !== undefined) {
      pushConsole.error('Received an betStop', eventChangedModel.changes['betStop']);
    }
    const bettingAllowed =
      eventChangedModel.changes['liveBettingAllowed'] !== undefined
        ? eventChangedModel.changes['liveBettingAllowed']
        : !eventChangedModel.changes['betStop'];
    eventBetTypes?.forEach(ebt => {
      ebt.bettingAllowed = bettingAllowed;
    });
  }
  if (eventChangedModel.changes['data']) {
    pushConsole.warn('Received new data', eventChangedModel.changes['data']);
    patch.data = eventChangedModel.changes['data'];
  }
  if (eventChangedModel.changes['state']) {
    patch.state = eventChangedModel.changes['state'];
  }
  if (eventChangedModel.changes['stateDetails']) {
    patch.stateDetails = eventChangedModel.changes['stateDetails'];
  }
  if (eventChangedModel.changes['cards']) {
    patch.cards = eventChangedModel.changes['cards'];
  }
  if (eventChangedModel.changes['goals']) {
    patch.goals = eventChangedModel.changes['goals'];
  }

  return { ...event, ...patch };
}

export function updateOddsBoostAfterPush(oddsBoost: OddsBoost, changed: EventBetTypeChangedModel): boolean {
  let recomputeOdds = false;
  let recomputeState = false;

  oddsBoost.details.forEach(d => {
    if (d.eventBetType.id === changed.eventBetTypeId) {
      const targetEbti = changed.items.find(i => i.eventBetTypeItemId === d.eventBetTypeItem.id);
      if (targetEbti) {
        if (d.eventBetTypeItem.odds !== targetEbti.odds) {
          d.eventBetTypeItem.odds = targetEbti.odds;
          recomputeOdds = true;
        }

        if (d.eventBetTypeItem.bettingAllowed !== targetEbti.bettingAllowed) {
          d.eventBetTypeItem.bettingAllowed = targetEbti.bettingAllowed;
          recomputeState = true;
        }
      }

      if (changed.active !== null && d.eventBetType.active !== changed.active) {
        d.eventBetType.active = changed.active;
        recomputeState = true;
      }
      if (changed.bettingAllowed !== null && d.eventBetType.bettingAllowed !== changed.bettingAllowed) {
        d.eventBetType.bettingAllowed = changed.bettingAllowed;
        recomputeState = true;
      }
    }
  });

  if (recomputeOdds) {
    oddsBoost.initialFixedOdds = oddsBoost.details.reduce((a, b: OddsBoostDetail) => a * b.eventBetTypeItem.odds, 1);

    if (!!oddsBoost.multiplier) {
      oddsBoost.fixedOdds = oddsBoost.initialFixedOdds * oddsBoost.multiplier;
    }
  }

  if (recomputeState) {
    oddsBoost.active = !oddsBoost.details.some(
      d =>
        !d.eventBetType.active ||
        !d.eventBetType.bettingAllowed ||
        !d.eventBetTypeItem.bettingAllowed ||
        !d.eventBetTypeItem.active
    );
  }

  return recomputeOdds || recomputeState;
}

export function buildQueryString(params: { [key: string]: any }): string {
  return (
    '?' +
    Object.keys(params)
      .filter(x => params[x] !== undefined && params[x] !== null)
      .map(x =>
        params[x] instanceof Array
          ? params[x].map(i => `${x}=${i}`).join('&')
          : `${x}=${params[x] instanceof Date ? params[x].toISOString() : params[x]}`
      )
      .join('&')
  );
}

export function getBaseListMaximumLengthOffset(
  numberOfRunners: number,
  offset?: number,
  maximumRunnersToApplyOffset?: number
) {
  if ((!maximumRunnersToApplyOffset && offset) || numberOfRunners <= maximumRunnersToApplyOffset) {
    return offset;
  } else if (numberOfRunners > maximumRunnersToApplyOffset) {
    return 0;
  }
}

export function getInexactOrder(combination: string, separator: string): string {
  const currentOrder: (number | string)[] = combination.split(separator).map(value => {
    const parsed: number = +value;
    return isNaN(parsed) ? value : parsed;
  });

  const compare = (a: number | string, b: number | string): number =>
    typeof a === 'number' && typeof b === 'number' ? a - b : String(a).localeCompare(String(b));

  let ordered: (number | string)[] = [...currentOrder].sort(compare);
  if (ordered.every((value, index) => value === currentOrder[index])) {
    ordered = [...currentOrder].sort((a, b) => compare(b, a));
  }

  return ordered.join(separator);
}
