import { Injectable, Inject } from '@angular/core';
import { BehaviorSubject, Observable, merge } from 'rxjs';
import { map } from 'rxjs/operators';
import { I18nService } from './i18n.service';
import { OddsFormat, operatorConfigurationToken, OperatorConfiguration } from '@honoregaming/configuration';
import { CookieStorageService } from '@honoregaming/core';

const ODDS_FORMAT_KEY = 'cus_oddsformat';

@Injectable({
  providedIn: 'root'
})
export class OddsFormatService {
  currentFormat: OddsFormat = null;
  private oddsFormatChangedSubject$ = new BehaviorSubject<OddsFormat>(this.currentFormat);
  oddsFormatChanged$ = this.oddsFormatChangedSubject$.asObservable();

  constructor(
    private i18nService: I18nService,
    private storageService: CookieStorageService,
    @Inject(operatorConfigurationToken) private operatorConfiguration: OperatorConfiguration
  ) {
    this.currentFormat =
      storageService.getItem(ODDS_FORMAT_KEY) &&
      this.operatorConfiguration.odds.formats.indexOf(storageService.getItem(ODDS_FORMAT_KEY)) !== -1
        ? storageService.getItem(ODDS_FORMAT_KEY)
        : this.operatorConfiguration.odds.defaultFormat;
  }

  public setFormat(format: OddsFormat) {
    if (this.currentFormat !== format) {
      this.currentFormat = format;
      this.oddsFormatChangedSubject$.next(this.currentFormat);
      this.storageService.setItem(ODDS_FORMAT_KEY, format);
    }
  }

  public convertOdds(odds: number): Observable<string | number> {
    return merge(this.i18nService.languageChanged$, this.oddsFormatChanged$).pipe(
      map(() => this.convertOddsToFormat(odds, this.currentFormat))
    );
  }

  public convertOddsToFormat(odds: number, format: OddsFormat): string {
    switch (format) {
      case OddsFormat.Fractional:
        return this.decimalToFractional(odds);
      case OddsFormat.Moneyline:
        return this.decimalToMoneyline(odds);
      case OddsFormat.Decimal:
      default:
        let shouldDisplayDecimals = true;

        if (
          odds >= (this.operatorConfiguration.bettingConfiguration?.maximalOddsWithDecimals ?? 10) &&
          odds % 1 === 0 // Check if this is a fixed number and not a number with some decimals
        ) {
          shouldDisplayDecimals = false;
        }

        return this.i18nService.formatNumberSync(odds, shouldDisplayDecimals);
    }
  }

  public decimalToFractional(odds: number): string {
    const gcd = function (a: number, b: number): number {
      if (b < 0.01) {
        return a;
      }

      return gcd(b, Math.floor(a % b));
    };

    const stringOdds = odds.toString();
    const length = stringOdds.length - 1 - stringOdds.indexOf('.');

    const fraction = +(odds - 1).toFixed(length);

    let denominator = Math.pow(10, length);
    let numerator = +(fraction * denominator).toFixed(length);

    const divisor = gcd(numerator, denominator);

    numerator /= divisor;
    denominator /= divisor;

    return `${numerator}/${denominator}`;
  }

  public decimalToMoneyline(odds: number): string {
    if (odds >= 2.0) {
      return '+' + this.i18nService.formatNumberSync((odds - 1) * 100);
    } else {
      return this.i18nService.formatNumberSync(-100 / (odds - 1));
    }
  }
}
