import { HttpClient } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { globalConfiguration } from '@honoregaming/configuration';
import { PaginatedResponse } from '@honoregaming/types';
import { Partner } from '../models/partner.model';
import { Cacheable } from '@honoregaming/core';

@Injectable({
  providedIn: 'root'
})
export class PartnerService {
  constructor(private httpClient: HttpClient) {}

  @Cacheable()
  getCustomerPartners() {
    return this.httpClient.get<PaginatedResponse<Partner>>(`${globalConfiguration.apiBaseUrl}partners`);
  }

  updateAuthorizedPartner(partnerId: number) {
    return this.httpClient.put(`${globalConfiguration.apiBaseUrl}partners`, {
      partnerId: partnerId
    });
  }
}
