import { DOCUMENT, isPlatformBrowser } from '@angular/common';
import { Inject, Injectable, NgZone, PLATFORM_ID } from '@angular/core';
import { NavigationEnd, Router } from '@angular/router';
import { Plugins, PushNotificationActionPerformed, PushNotificationToken } from '@capacitor/core';
import { BehaviorSubject, combineLatest, from, merge, Observable, ReplaySubject, Subject } from 'rxjs';
import {
  distinctUntilChanged,
  filter,
  map,
  shareReplay,
  switchMap,
  take,
  takeUntil,
  withLatestFrom
} from 'rxjs/operators';
import { appConfiguration, SmarticoConfiguration } from '@honoregaming/configuration';
import { DestroySubject, natifToken } from '@honoregaming/core';
import { I18nService } from '@honoregaming/i18n';
import { SmarticoNavigationItem } from '@honoregaming/types';
import { CustomerOperatorConfiguration, customerOperatorConfigurationToken, Me } from '../../models';
import {
  AchRelatedGame,
  DeepLink,
  DeepLinkParams,
  DpType,
  ExternalCallbackKey,
  PushClientPlatform,
  SmarticoSDK,
  UserPublicProperties
} from '../../models/smartico-sdk.model';
import { AuthService } from '../auth.service';

const { PushNotifications } = Plugins;

declare var window: any;
declare var _smartico: SmarticoSDK | undefined;

@Injectable()
export class SmarticoService extends DestroySubject {
  private readonly isBrowser: boolean = isPlatformBrowser(this.platformId);
  private readonly configuration?: SmarticoConfiguration = this.customerOperatorConfiguration.smarticoConfiguration;
  private readonly instantGamesPath: string = `/${
    this.customerOperatorConfiguration.betCategoriesPathConfiguration?.instantGamesConfiguration?.path ??
    'instant-games'
  }`;
  private readonly headElementIdentifier: string = 'smartico-head';
  private readonly linkElementIdentifier: string = 'smartico-link';

  private readonly smarticoSubject: ReplaySubject<SmarticoSDK> = new ReplaySubject<SmarticoSDK>(1);
  readonly smartico$: Observable<SmarticoSDK> = this.smarticoSubject.asObservable();

  private readonly identifiedSmarticoSubject: BehaviorSubject<SmarticoSDK | null> =
    new BehaviorSubject<SmarticoSDK | null>(null);
  readonly identifiedSmartico$: Observable<SmarticoSDK | null> = this.identifiedSmarticoSubject.asObservable();

  private readonly deepLinkSubject = new Subject<string>();
  private readonly deepLink$ = this.deepLinkSubject.asObservable();

  private isGamificationWidgetOpenSubject: BehaviorSubject<boolean> = new BehaviorSubject<boolean>(false);
  readonly isGamificationWidgetOpen$: Observable<boolean> = this.isGamificationWidgetOpenSubject.asObservable();

  private readonly userPublicPropertiesSubject: BehaviorSubject<UserPublicProperties | null> =
    new BehaviorSubject<UserPublicProperties | null>(null);
  readonly userPublicProperties$: Observable<UserPublicProperties | null> =
    this.userPublicPropertiesSubject.asObservable();

  readonly avatarUrl$: Observable<string | null> = this.userPublicProperties$.pipe(
    withLatestFrom(this.identifiedSmartico$),
    map(([, smartico]) => smartico?.api.getUserProfile().avatar_url ?? null),
    distinctUntilChanged(),
    takeUntil(this.destroy$),
    shareReplay(1)
  );

  readonly missionsCount$: Observable<number> = this.userPublicProperties$.pipe(
    withLatestFrom(this.identifiedSmartico$),
    switchMap(([, smartico]) => from(smartico?.api.getMissions() ?? [])),
    map(missions => missions.filter(mission => !mission.is_completed && mission.is_opted_in).length),
    distinctUntilChanged(),
    takeUntil(this.destroy$),
    shareReplay(1)
  );

  private readonly onlineCreativesSuspensionRequestSubject: BehaviorSubject<boolean> = new BehaviorSubject<boolean>(
    false
  );
  private readonly onlineCreativesSuspensionRequest$: Observable<boolean> =
    this.onlineCreativesSuspensionRequestSubject.asObservable();

  constructor(
    private readonly authService: AuthService,
    private readonly i18nService: I18nService,
    private readonly router: Router,
    private readonly zone: NgZone,
    @Inject(customerOperatorConfigurationToken)
    private readonly customerOperatorConfiguration: CustomerOperatorConfiguration,
    @Inject(DOCUMENT) private readonly document: Document,
    @Inject(PLATFORM_ID) private readonly platformId: Object,
    @Inject(natifToken) private readonly isNatif: boolean
  ) {
    super();
  }

  ngOnDestroy(): void {
    super.ngOnDestroy();
    if (this.isNatif) {
      PushNotifications.removeAllListeners();
    }
  }

  get isEnabled(): boolean {
    return this.isBrowser && !!this.configuration?.enabled;
  }

  get showSelector(): boolean {
    return this.isEnabled && (this.configuration?.visibleNavigationItems?.length ?? 0) > 0;
  }

  get showMissions(): boolean {
    return (
      this.isEnabled && (this.configuration?.visibleNavigationItems?.includes(SmarticoNavigationItem.Missions) ?? false)
    );
  }

  get showMyAccount(): boolean {
    return this.isEnabled && (this.configuration?.showMyAccount ?? false);
  }

  get showLevelProgression(): boolean {
    return this.isEnabled && (this.configuration?.showLevelProgression ?? false);
  }

  initialize(): void {
    if (!this.isEnabled) {
      this.completeSubjects();
      return;
    }

    if (!!this.document.getElementById(this.headElementIdentifier)) {
      return;
    }

    if (this.isNatif) {
      window._smartico_allow_localhost = true;
    }

    window.__smarticoDPCustom = (dp: DeepLink): boolean => {
      return this.zone.run(() => this.handleDeepLink(dp));
    };

    if (this.configuration?.widgetBetweenHeaderAndNavbarOnMobile) {
      const linkElement: HTMLLinkElement = this.document.createElement('link');
      linkElement.id = this.linkElementIdentifier;
      linkElement.rel = 'stylesheet';
      linkElement.type = 'text/css';
      linkElement.href = 'smartico.css';
      this.document.head.appendChild(linkElement);
    }

    const headElement: HTMLScriptElement = this.document.createElement('script');
    headElement.id = this.headElementIdentifier;
    headElement.type = 'text/javascript';
    headElement.src = this.configuration?.scriptLocation ?? '';
    headElement.onload = () => {
      _smartico?.init(this.configuration?.labelKey ?? '', { brand_key: this.configuration?.brandKey ?? '' });

      if (_smartico) {
        this.smarticoSubject.next(_smartico);

        this.setupUserChanges();
        this.setupDeepLinkHandling();
        this.setupGamificationWidgetClosing();
        this.setupOnlineCreativesSuspension();

        _smartico.on(ExternalCallbackKey.IDENTIFY, () => {
          if (!this.configuration?.popupsEnabled) {
            _smartico?.suspendPopups(true);
          }
          this.identifiedSmarticoSubject.next(_smartico ?? null);
          this.userPublicPropertiesSubject.next(_smartico?.getPublicProps() ?? null);
          if (this.isNatif) {
            this.registerNativePush();
          } else {
            _smartico?.requestPushPermissions();
          }
        });

        _smartico.on(ExternalCallbackKey.USER_PROPS_CHANGE, () => {
          this.userPublicPropertiesSubject.next(_smartico?.getPublicProps() ?? null);
        });

        _smartico.on(ExternalCallbackKey.GF_STARTING, () => {
          this.isGamificationWidgetOpenSubject.next(true);
        });

        _smartico.on(ExternalCallbackKey.GF_CLOSING, () => {
          this.isGamificationWidgetOpenSubject.next(false);
        });

        _smartico.on(ExternalCallbackKey.ACH_GAME_OPENING, (game: AchRelatedGame) => {
          if (!game.game_public_meta.link.startsWith(this.instantGamesPath)) {
            game.game_public_meta.link = `${this.instantGamesPath}${game.game_public_meta.link}`;
          }
        });

        _smartico.on(ExternalCallbackKey.LOGOUT, () => {
          if (this.isNatif) {
            PushNotifications.removeAllListeners();
          }
          this.identifiedSmarticoSubject.next(null);
          this.userPublicPropertiesSubject.next(null);
        });
      } else {
        this.completeSubjects();
      }
    };
    headElement.onerror = () => {
      console.error('Smartico SDK failed to load');
      this.completeSubjects();
    };

    this.document.head.appendChild(headElement);
  }

  executeDeepLink(type: DpType, params?: DeepLinkParams): void {
    if (this.isEnabled) {
      const deepLink = `dp:${type}${params ? '&' + new URLSearchParams(params).toString() : ''}`;
      this.executeRawDeepLink(deepLink);
    }
  }

  suspendOnlineCreatives(): void {
    if (this.isEnabled) {
      this.onlineCreativesSuspensionRequestSubject.next(true);
    }
  }

  resumeOnlineCreatives(): void {
    if (this.isEnabled) {
      this.onlineCreativesSuspensionRequestSubject.next(false);
    }
  }

  closeGamificationWidget(): void {
    if (this.isEnabled && this.isGamificationWidgetOpenSubject.value) {
      this.executeDeepLink(DpType.GfClose);
    }
  }

  isNavigationItemVisible(item: SmarticoNavigationItem): boolean {
    return this.configuration?.visibleNavigationItems?.includes(item) ?? false;
  }

  private executeRawDeepLink(deepLink: string): void {
    this.deepLinkSubject.next(deepLink);
  }

  private registerNativePush(): void {
    PushNotifications.requestPermission().then(result => {
      if (result.granted) {
        PushNotifications.register();
      }
    });
    PushNotifications.addListener('registration', (token: PushNotificationToken) => {
      this.identifiedSmartico$
        .pipe(
          filter((smartico): smartico is SmarticoSDK => !!smartico),
          take(1),
          takeUntil(this.destroy$)
        )
        .subscribe(smartico => {
          smartico.registerNativePushToken(token.value, PushClientPlatform.NATIVE_ANDROID, appConfiguration.appId);
        });
    });
    PushNotifications.addListener(
      'pushNotificationActionPerformed',
      (notification: PushNotificationActionPerformed) => {
        if (notification.actionId !== 'tap' || !notification.notification.data?.action?.startsWith('dp:')) {
          return;
        }
        this.executeRawDeepLink(notification.notification.data.action);
      }
    );
  }

  private setupUserChanges(): void {
    combineLatest([this.smartico$, this.authService.me$, this.i18nService.languageChanged$])
      .pipe(takeUntil(this.destroy$))
      .subscribe(([smartico, user, language]) => {
        if (!!user) {
          window._smartico_user_id = user.id.toString();
          window._smartico_user_hash = user.externalTokens?.['SmarticoUserHash'] ?? undefined;
          window._smartico_language = language;
        } else {
          const oldUserId: number | undefined = window._smartico_user_id;
          window._smartico_user_id = undefined;
          window._smartico_user_hash = undefined;
          window._smartico_language = undefined;
          if (oldUserId) {
            smartico.logout();
          }
        }
      });
  }

  private setupDeepLinkHandling(): void {
    this.deepLink$
      .pipe(
        switchMap(deepLink =>
          this.identifiedSmartico$.pipe(
            filter((smartico): smartico is SmarticoSDK => !!smartico),
            take(1),
            map(smartico => ({ smartico, deepLink }))
          )
        ),
        takeUntil(this.destroy$)
      )
      .subscribe(({ smartico, deepLink }) => {
        smartico.dp(deepLink);
      });
  }

  private setupGamificationWidgetClosing(): void {
    this.router.events
      .pipe(
        filter((event): event is NavigationEnd => event instanceof NavigationEnd),
        withLatestFrom(this.isGamificationWidgetOpen$),
        filter(([, isOpened]) => isOpened),
        takeUntil(this.destroy$)
      )
      .subscribe(_ => this.closeGamificationWidget());
  }

  private setupOnlineCreativesSuspension(): void {
    const triggers$: Observable<string> = merge(
      this.identifiedSmartico$.pipe(
        filter((smartico): smartico is SmarticoSDK => !!smartico),
        map(() => this.router.url)
      ),
      this.authService.me$.pipe(map(() => this.router.url)),
      this.router.events.pipe(
        filter((event): event is NavigationEnd => event instanceof NavigationEnd),
        map(event => event.url)
      ),
      this.onlineCreativesSuspensionRequest$.pipe(map(() => this.router.url))
    );

    triggers$
      .pipe(
        withLatestFrom(this.identifiedSmartico$, this.authService.me$, this.onlineCreativesSuspensionRequest$),
        filter((tuple): tuple is [string, SmarticoSDK, Me, boolean] => !!tuple[1] && !!tuple[2]),
        map(([url, smartico, user, suspensionRequested]) => ({
          smartico,
          shouldSuspend: this.shouldSuspendOnlineCreatives(url, user, suspensionRequested)
        })),
        distinctUntilChanged((a, b) => a.shouldSuspend === b.shouldSuspend),
        takeUntil(this.destroy$)
      )
      .subscribe(({ smartico, shouldSuspend }) => {
        if (this.configuration?.popupsEnabled) {
          smartico.suspendPopups(shouldSuspend);
        }
        smartico.suspendInbox(shouldSuspend);
        smartico.suspendMiniGames(shouldSuspend);
      });
  }

  private shouldSuspendOnlineCreatives(url: string, user: Me, suspensionRequested: boolean): boolean {
    return (
      suspensionRequested ||
      !user.hasAcceptedGcu ||
      url.startsWith('/sports/') ||
      url.startsWith(`${this.instantGamesPath}/`) ||
      url.includes('deposit') ||
      url.includes('withdrawal')
    );
  }

  private handleDeepLink(dp: DeepLink): boolean {
    switch (dp.action) {
      case DpType.HgGo: {
        const to: string = dp.params?.to?.replace(/^\/instant-games/, this.instantGamesPath) ?? '';
        if (to !== '') {
          this.router.navigateByUrl(to);
        }
        return true;
      }

      default:
        return false;
    }
  }

  private completeSubjects(): void {
    this.smarticoSubject.complete();
    this.identifiedSmarticoSubject.complete();
    this.userPublicPropertiesSubject.complete();
    this.deepLinkSubject.complete();
    this.isGamificationWidgetOpenSubject.complete();
  }
}
