import { Component, EventEmitter, Input, Output } from '@angular/core';

@Component({
  selector: 'hg-agent-ask-question-with-input',
  templateUrl: './ask-question-with-input.component.html',
  styleUrls: ['./ask-question-with-input.component.scss']
})
export class AskQuestionWithInputComponent {
  @Input()
  public title: string;

  @Input()
  public text: string;

  @Input()
  public inputLabel: string;

  value: string;

  @Output()
  close = new EventEmitter<{ success: boolean; value: any }>();
}
