import {
  Component,
  ChangeDetectionStrategy,
  Input,
  OnInit,
  Output,
  EventEmitter,
  ChangeDetectorRef
} from '@angular/core';
import { NumbersSelectionToolBase } from '../base/numbers-selection-tool-base';
import { NumberItem } from '../base/model/number-item';
import { I18nService } from '@honoregaming/i18n';
import { finalize, takeUntil } from 'rxjs/operators';
import { EventsService } from '@honoregaming/events';

@Component({
  selector: 'hg-recommended-numbers-selection-tool',
  templateUrl: './recommended-numbers-selection-tool.component.html',
  styleUrls: ['./recommended-numbers-selection-tool.component.scss', '../base/numbers-selection-tool.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class RecommendedNumbersSelectionToolComponent extends NumbersSelectionToolBase implements OnInit {
  @Input() title: string;
  @Input() searchPlaceholder: string;
  @Input() defaultSearchNumber?: number;
  @Input() disabledNumbers?: string[];
  @Input() showSelectAll: boolean = false;
  @Input() betTypeId: number;
  @Input() drawGameRuleIds: number[] = [];
  @Input() recommendedNumbersCount: number;
  @Input() formatNumber: (value: string) => string;
  @Output() close: EventEmitter<string[]> = new EventEmitter<string[]>();

  loading: boolean = false;
  numberItems: NumberItem[] = [];
  searchNumber?: number;
  message: string;

  constructor(
    private i18nService: I18nService,
    private eventsService: EventsService,
    private cdRef: ChangeDetectorRef
  ) {
    super();
  }

  ngOnInit(): void {
    this.searchNumber = this.defaultSearchNumber;
    this.search();
  }

  search(): void {
    this.numberItems = [];

    if (Number.isInteger(this.searchNumber)) {
      this.loading = true;
      this.eventsService
        .getDrawGamesRecommendedNumbers(
          this.betTypeId,
          this.drawGameRuleIds,
          +this.searchNumber,
          this.recommendedNumbersCount
        )
        .pipe(
          takeUntil(this.destroy$),
          finalize(() => {
            this.loading = false;
            this.message =
              this.numberItems.length > 0
                ? this.i18nService
                    .translateSync('DRAW_GAMES.LABEL.RECOMMENDEDNUMBERS.FOUNDNUMBERS')
                    .replace('{0}', `<strong>${this.searchNumber}</strong>`)
                : this.i18nService.translateSync('DRAW_GAMES.LABEL.RECOMMENDEDNUMBERS.NONUMBER');
            this.cdRef.markForCheck();
          })
        )
        .subscribe((list: number[]) => {
          this.numberItems = list.map(x => ({
            number: this.formatNumber(String(x)),
            selected: false,
            disabled: this.disabledNumbers?.includes(this.formatNumber(String(x))) ?? false
          }));
        });
    } else {
      this.message = this.i18nService.translateSync('DRAW_GAMES.LABEL.RECOMMENDEDNUMBERS.INFO');
    }
  }
}
