import { Component, ChangeDetectionStrategy, Input, OnChanges } from '@angular/core';

@Component({
  selector: 'hg-treasure-island-result',
  templateUrl: './treasure-island-result.component.html',
  styleUrls: ['./treasure-island-result.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class TreasureIslandResultComponent implements OnChanges {
  @Input()
  result: any;

  serializedResult: any;

  constructor() {}

  ngOnChanges() {
    this.serializedResult = JSON.parse(this.result);
  }
}
