import { ChangeDetectionStrategy, ChangeDetectorRef, Component, OnInit } from '@angular/core';
import { Partner } from '../../models/partner.model';
import { PartnerService } from '../../services/partner.service';
import { DestroySubject } from '@honoregaming/core';
import { finalize, takeUntil } from 'rxjs/operators';

@Component({
  selector: 'hg-partners',
  templateUrl: './partners.component.html',
  styleUrls: ['./partners.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class PartnersComponent extends DestroySubject implements OnInit {
  hasError: boolean;
  partners: Partner[] = [];
  isLoading: boolean = false;
  hasMore: boolean;
  test = true;
  alertOpened: boolean;

  constructor(private partnerService: PartnerService, private cdref: ChangeDetectorRef) {
    super();
  }

  ngOnInit() {
    this.load();
  }

  load() {
    this.isLoading = true;
    this.hasError = false;
    this.partnerService
      .getCustomerPartners()
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.isLoading = false;
          this.cdref.markForCheck();
        })
      )
      .subscribe(
        partners => {
          this.partners = partners.items;
          this.hasMore = partners.pagination.hasMore;
        },
        _ => (this.hasError = true)
      );
  }

  updateAuthorizedPartner(partnerId: number) {
    this.partnerService
      .updateAuthorizedPartner(partnerId)
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.alertOpened = true;
          this.cdref.markForCheck();
        })
      )
      .subscribe(
        () => (this.hasError = false),
        _ => (this.hasError = true)
      );
  }

  close() {
    this.alertOpened = false;
    this.hasError = false;
  }
}
