import { Component, ChangeDetectionStrategy, Input } from '@angular/core';
import { SelectableEventBetTypeItem } from '@honoregaming/types';
import { BroadcastingService, ApplicationEvent } from '@honoregaming/core';

@Component({
  selector: 'hg-racing-roulette-color3',
  templateUrl: './racing-roulette-color3.component.html',
  styleUrls: ['./racing-roulette-color3.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class RacingRouletteColor3Component {
  @Input()
  eventBetTypeItems: SelectableEventBetTypeItem[];

  constructor(private broadcastingService: BroadcastingService) {}

  // TODO : remove code duplication
  addOrRemoveItemToSelection(betTypeItemId: number) {
    const eventBetTypeItem = this.eventBetTypeItems.find(vr => vr.betTypeItemId === betTypeItemId);

    if (eventBetTypeItem) {
      eventBetTypeItem.selected = !eventBetTypeItem.selected;

      if (eventBetTypeItem.selected) {
        this.broadcastingService.broadcast(ApplicationEvent.SelectionItemAdded, eventBetTypeItem);
      } else {
        this.broadcastingService.broadcast(ApplicationEvent.SelectionItemRemoved, eventBetTypeItem);
      }

      this.eventBetTypeItems = [...this.eventBetTypeItems];
    }
  }
}
