import {
  Component,
  ChangeDetectionStrategy,
  Input,
  Output,
  EventEmitter,
  SimpleChanges,
  OnChanges,
  Inject,
  TemplateRef
} from '@angular/core';
import { trigger, transition, animate, style } from '@angular/animations';
import { operatorConfigurationToken, OperatorConfiguration } from '@honoregaming/configuration';
import { BetLine, BetLineAmount, BetSlipType } from '../../models';
import { BetCategoryType, EventType } from '@honoregaming/types';
import { getCasesNumber, MAXIMUM_SYSTEM_AMOUNTS } from '../../utils';
import { ppcmArr } from '../../helpers';
import { DialogService } from '@honoregaming/core';

@Component({
  selector: 'hg-bet-slip-systems-mode',
  templateUrl: './bet-slip-systems-mode.component.html',
  styleUrls: [
    './bet-slip-systems-mode.component.scss',
    '../bet-lines/bet-line.scss',
    '../bet-lines/bet-line-content.scss'
  ],
  changeDetection: ChangeDetectionStrategy.OnPush,
  animations: [
    trigger('removed', [
      transition('* => void', [animate('0.1s ease-out', style({ transform: 'scale(0)', height: '0' }))])
    ])
  ]
})
export class BetSlipSystemsModeComponent implements OnChanges {
  @Input()
  betLines: BetLine[] = [];
  @Input()
  amounts: BetLineAmount[] = [];
  @Input()
  betLineTemplate: TemplateRef<any>;
  @Input()
  acceptOddChange: boolean;
  @Input()
  predefinedStakes: number[];
  @Input()
  betCategory: BetCategoryType;
  @Input()
  betSlipType: BetSlipType;

  @Output()
  betSlipChange = new EventEmitter<{ amount: number; line: number }>();
  @Output()
  betLineRemove = new EventEmitter<BetLine>();

  internalAmounts: {
    index: number;
    value: number | BetLineAmount;
    betsNumber: number;
    baseAmount: number;
    increment: number;
  }[] = [];
  currency = this.operatorConfiguration.currency.symbol;
  internalBets: BetLine[];
  baseAmount: number;
  EventType = EventType;
  BetCategoryType = BetCategoryType;

  constructor(
    @Inject(operatorConfigurationToken) private operatorConfiguration: OperatorConfiguration,
    private dialogService: DialogService
  ) {}

  trackByFn(index, _line: BetLine) {
    return index;
  }

  ngOnChanges(_changes: SimpleChanges) {
    this.internalBets = this.betLines.map(x => ({ ...x }));
    this.baseAmount = Math.max(...this.betLines.map(bl => bl.baseAmount));
    const lines = this.amounts.map((blAmount, i) => {
      return {
        index: i,
        value: blAmount.amount || 0,
        betsNumber: getCasesNumber(this.betLines.length - i, this.betLines.length),
        baseAmount: Math.max(...this.betLines.map(l => l.baseAmount)),
        increment:
          this.betLines.length === 1
            ? this.betLines[0].minimumAmountIncrement
            : ppcmArr(this.betLines.map(b => b.minimumAmountIncrement))
      };
    });

    this.internalAmounts =
      lines.length <= MAXIMUM_SYSTEM_AMOUNTS
        ? lines
        : [
            ...lines.slice(0, MAXIMUM_SYSTEM_AMOUNTS / 2),
            ...lines.slice(lines.length - MAXIMUM_SYSTEM_AMOUNTS / 2, lines.length)
          ];
  }

  onAmountChange(amount: number, index: number) {
    this.internalAmounts.find(a => a.index === index).value = amount;
    this.betSlipChange.emit({ amount, line: index });
  }

  onBetLineRemove(betLine: BetLine) {
    this.betLineRemove.emit(betLine);
  }

  toggleBetSlip() {
    this.dialogService.toggleDialog('betslip', false);
  }
}
