import { Component, ChangeDetectionStrategy, Input, Output, EventEmitter } from '@angular/core';
import { BetLine, BetSlipType } from '@honoregaming/betslip';
import { DialogService } from '@honoregaming/core';
import { BetBuilderLine, EventType } from '@honoregaming/types';
import { animate, style, transition, trigger } from '@angular/animations';

@Component({
  selector: 'hg-bet-lines-multiple-mode',
  templateUrl: './bet-lines-multiple-mode.component.html',
  styleUrls: ['./bet-lines-multiple-mode.component.scss', '../bet-line.scss', '../bet-line-content.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
  animations: [
    trigger('removed', [
      transition('* => void', [animate('0.1s ease-out', style({ transform: 'scale(0)', height: '0' }))])
    ])
  ]
})
export class BetLinesMultipleModeComponent {
  @Input() betLines: BetLine[] = [];
  @Input() isCompletedLines = false;
  @Input() betSlipType: BetSlipType;
  @Input() acceptOddChange: boolean;
  @Input() isLoadingOddsEventIds: number[] = [];

  @Output() betLineRemove = new EventEmitter<BetLine>();
  @Output() betBuilderLineRemove = new EventEmitter<{ betLine: BetLine; betBuilderLine: BetBuilderLine }>();

  EventType = EventType;

  constructor(private dialogService: DialogService) {}

  trackByFn(index, _line: BetLine) {
    return index;
  }

  toggleBetSlip() {
    this.dialogService.toggleDialog('betslip', false);
  }

  onBetLineRemove(betLine: BetLine) {
    this.betLineRemove.emit(betLine);
  }

  onBetBuilderLineRemove(betLine: BetLine, betBuilderLine: BetBuilderLine): void {
    this.betBuilderLineRemove.emit({ betLine, betBuilderLine });
  }
}
