import { ITelemetryService } from './telemetry-service.model';
import { Injectable, Inject, PLATFORM_ID } from '@angular/core';

import { isPlatformBrowser } from '@angular/common';
import { buildQueryString } from '@honoregaming/core';
import { CustomerOperatorConfiguration, customerOperatorConfigurationToken } from '../../models';

@Injectable()
export class RoigenPixelTelemetryService implements ITelemetryService {
  isBrowser = isPlatformBrowser(this.platformId);
  configuration = this.operatorConfig.telemetryConfiguration.roigen;
  conversionPixel: HTMLImageElement;

  constructor(
    @Inject(customerOperatorConfigurationToken) private operatorConfig: CustomerOperatorConfiguration,
    @Inject(PLATFORM_ID) private platformId
  ) {
    if (this.isBrowser) {
      this.conversionPixel = document.createElement('img');
      this.conversionPixel.width = 1;
      this.conversionPixel.height = 1;

      let parent = document.getElementsByTagName('script')[0];
      parent.parentNode.insertBefore(this.conversionPixel, parent);
    }
  }

  trackPageView(_name: string, _path: string): void {}

  trackEvent(name: string, _properties: any): void {
    if (this.isBrowser) {
      switch (name) {
        case 'firstTimeDeposit': {
          let query = {
            et: 'deposit'
          };

          this.conversionPixel.src = `${this.configuration.serverUrl}/conversion.gif${buildQueryString(query)}`;
          break;
        }
        case 'deposit': {
          let query = {
            et: 'deposit'
          };

          this.conversionPixel.src = `${this.configuration.serverUrl}/conversion.gif${buildQueryString(query)}`;
          break;
        }
        case 'sign_up_started': {
          let query = {
            et: 'registration'
          };

          this.conversionPixel.src = `${this.configuration.serverUrl}/conversion.gif${buildQueryString(query)}`;
          break;
        }
      }
    }
  }
}
