import {
  Component,
  ChangeDetectionStrategy,
  Input,
  ChangeDetectorRef,
  Output,
  EventEmitter,
  ViewChildren,
  QueryList,
  ElementRef,
  AfterViewInit,
  OnDestroy
} from '@angular/core';
import { FreeBetCouponBetSlip } from '@honoregaming/betslip';
import { BetSlipMode } from '@honoregaming/types';

@Component({
  selector: 'hg-bet-slip-freebet-coupons',
  templateUrl: './bet-slip-freebet-coupons.component.html',
  styleUrls: ['./bet-slip-freebet-coupons.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class BetSlipFreebetCouponsComponent implements AfterViewInit, OnDestroy {
  @Input() freeBetCoupons: FreeBetCouponBetSlip[] = [];
  @Input() betSlipBetCategory: string;
  @Input() mode: BetSlipMode;
  @Input() multiCouponActive: boolean;
  @Input() completeMyBetCouponId: number | undefined;
  @Input() selectedCoupon: FreeBetCouponBetSlip | null = null;

  @Output() selectionChanges = new EventEmitter<FreeBetCouponBetSlip>();

  @ViewChildren('slideElements')
  slideElements: QueryList<ElementRef> | undefined;

  BetSlipMode = BetSlipMode;

  currentIndex: number = 0;
  translate: number = 0;
  startX: number = 0;
  startY: number = 0;
  scrollDirection: 'x' | 'y' | null = null;
  xScrollDirection: 'left' | 'right' | null = null;
  isDragging: boolean = false;

  private touchMoveHandlers: Array<(e: TouchEvent) => void> = [];

  constructor(private cdRef: ChangeDetectorRef) {}

  ngAfterViewInit(): void {
    this.tryToggleMandatoryCoupon();
    this.slideElements?.forEach(slideElement => {
      const handler: (e: TouchEvent) => void = this.handleTouchMoveEvent.bind(this);
      this.touchMoveHandlers.push(handler);
      // Set passive to false, this permit to use '.preventDefault' on touchmove event
      slideElement.nativeElement.addEventListener('touchmove', handler, { passive: false });
    });
  }

  ngOnDestroy(): void {
    this.slideElements?.forEach((slideElement, index) => {
      slideElement.nativeElement.removeEventListener('touchmove', this.touchMoveHandlers[index]);
    });
  }

  trackByCoupon(_, freebetCoupon: FreeBetCouponBetSlip): number {
    return freebetCoupon.id;
  }

  tryToggleMandatoryCoupon(): void {
    const mandatoryCouponIndex: number =
      this.completeMyBetCouponId || !this.multiCouponActive
        ? 0
        : this.freeBetCoupons.findIndex(coupon => coupon.canBeUsed);
    if (mandatoryCouponIndex > -1) {
      this.toggleCoupon(this.freeBetCoupons[mandatoryCouponIndex]);
      this.navToCoupon(mandatoryCouponIndex);
      this.cdRef.markForCheck();
    }
  }

  toggleCoupon(coupon: FreeBetCouponBetSlip) {
    if (
      !this.completeMyBetCouponId &&
      coupon.canBeUsed &&
      coupon.bettingRequirementsProgression === coupon.bettingRequirementsQuantity
    ) {
      this.updateSelectedCoupon(this.selectedCoupon?.id === coupon.id ? null : coupon);
    }
  }

  navToCoupon(index: number): void {
    if (this.currentIndex !== index) {
      this.currentIndex = index;
      this.translate = -this.currentIndex * 100;
      this.updateSliderPosition();
    }
  }

  goToPrevious(): void {
    if (this.currentIndex > 0) {
      this.currentIndex--;
      this.translate += 100;
      this.updateSliderPosition();
    }
  }

  goToNext(): void {
    if (this.currentIndex < this.freeBetCoupons.length - 1) {
      this.currentIndex++;
      this.translate -= 100;
      this.updateSliderPosition();
    }
  }

  startDragging(event: TouchEvent): void {
    event.stopImmediatePropagation();
    this.startX = event.touches[0].clientX;
    this.startY = event.touches[0].clientY;
  }

  stopDragging(event: TouchEvent): void {
    event.stopImmediatePropagation();
    this.startX = 0;
    this.startY = 0;
    this.scrollDirection = null;
    this.xScrollDirection = null;
  }

  private updateSelectedCoupon(coupon: FreeBetCouponBetSlip | null) {
    this.selectionChanges.emit(coupon);
  }

  private handleTouchMoveEvent(event: TouchEvent): void {
    if (this.completeMyBetCouponId) {
      return;
    }
    const deltaX: number = event.touches[0].clientX - this.startX;
    const deltaY: number = event.touches[0].clientY - this.startY;
    if (this.scrollDirection == null) {
      this.scrollDirection = Math.abs(deltaY) > Math.abs(deltaX) ? 'y' : 'x';
    }
    if (this.scrollDirection === 'x') {
      event.preventDefault();
      this.applyXDirection(deltaX);
    }
  }

  private applyXDirection(deltaX: number): void {
    if (deltaX > 30 && this.xScrollDirection !== 'right') {
      this.xScrollDirection = 'right';
      this.goToPrevious();
    } else if (deltaX < -30 && this.xScrollDirection !== 'left') {
      this.xScrollDirection = 'left';
      this.goToNext();
    }
  }

  private updateSliderPosition(): void {
    this.slideElements?.forEach(
      slideElement => (slideElement.nativeElement.style.transform = `translateX(${this.translate}%)`)
    );
  }
}
