import { EventEmitter } from '@angular/core';
import { NumberItem } from './model/number-item';
import { DestroySubject } from '@honoregaming/core';

export abstract class NumbersSelectionToolBase extends DestroySubject {
  title: string;
  close: EventEmitter<string[]>;
  numberItems: NumberItem[];

  constructor() {
    super();
  }

  add(numbers: string[]): void {
    this.close.emit(numbers);
  }

  selectItem(item: NumberItem): void {
    item.selected = !item.selected;
    this.numberItems = [...this.numberItems];
  }
}
