import { DOCUMENT } from '@angular/common';
import {
  ChangeDetectorRef,
  Component,
  ComponentFactoryResolver,
  Inject,
  OnInit,
  ViewChild,
  ViewContainerRef
} from '@angular/core';
import { Router } from '@angular/router';
import { AuthService } from '@honoregaming/authentication';
import { globalConfiguration, OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';
import { LocalStorageService } from '@honoregaming/core';
import { MessageService, PopinComponent } from '@honoregaming/ui';
import { Subscription } from 'rxjs';

@Component({
  selector: 'hg-kiosk-login',
  templateUrl: './kiosk-login.component.html',
  styleUrls: ['./kiosk-login.component.scss']
})
export class KioskLoginComponent implements OnInit {
  logoPath = globalConfiguration.assetsPath + this.operatorConfiguration.key + '/logo-kiosk.png';
  operatorName = this.operatorConfiguration.name;
  sessionId = this.localStorageService.getItem('vsid');

  @ViewChild('messageContainer', { read: ViewContainerRef, static: true })
  container: ViewContainerRef;
  code: string;
  codeLength = 5;
  isLoading = false;
  loginError = false;
  private messageCloseSubscription: Subscription;

  constructor(
    @Inject(DOCUMENT) private document: any,
    @Inject(operatorConfigurationToken) private operatorConfiguration: OperatorConfiguration,
    private cdRef: ChangeDetectorRef,
    private localStorageService: LocalStorageService,
    private authService: AuthService,
    private router: Router,
    private messageService: MessageService,
    private resolver: ComponentFactoryResolver
  ) {}

  ngOnInit() {
    this.messageService.message$.subscribe(msg => {
      const factory = this.resolver.resolveComponentFactory(PopinComponent);
      if (factory !== undefined) {
        const compRef = this.container.createComponent(factory);
        compRef.instance.message = msg.msg;
        this.messageCloseSubscription = compRef.instance.close.subscribe(val => {
          this.cleanMessages();
          msg.onclosed(val);
        });
      }

      this.fixBody();
    });

    this.messageService.component$.subscribe(component => {
      const factory = this.resolver.resolveComponentFactory(PopinComponent);
      this.cleanMessages();

      if (factory !== undefined) {
        const compRef = this.container.createComponent(factory);
        compRef.instance.component = component;
        compRef.instance.options = component.options;
        this.messageCloseSubscription = compRef.instance.close.subscribe(val => {
          this.cleanMessages();
          component.onclosed(val);
        });
      }

      this.fixBody();
      this.cdRef.markForCheck();
    });
  }

  submit() {
    if (this.code && this.code.length === this.codeLength) {
      this.isLoading = false;
      this.loginError = false;

      this.isLoading = true;

      this.authService.login({ code: this.code, sessionId: this.sessionId }).subscribe(
        _ => {
          this.router.navigate(['/']);
        },
        () => {
          this.isLoading = false;
          this.loginError = true;
          setTimeout(() => {
            this.loginError = false;
            this.code = '';
          }, 2000);
        }
      );
    }
  }

  private cleanMessages() {
    this.container.clear();
    this.releaseBody();

    if (this.messageCloseSubscription) {
      this.messageCloseSubscription.unsubscribe();
    }
  }

  fixBody(onlyInXs = false) {
    onlyInXs
      ? this.document.documentElement.classList.add('hidden-in-xs')
      : this.document.documentElement.classList.add('hidden');
  }

  releaseBody() {
    this.document.documentElement.classList.remove('hidden-in-xs');
    this.document.documentElement.classList.remove('hidden');
  }
}
