import {
  Component,
  ChangeDetectionStrategy,
  Input,
  EventEmitter,
  Output,
  OnChanges,
  ElementRef,
  ViewChild
} from '@angular/core';
import {
  EventBetTypeItem,
  SelectableEventBetTypeItem,
  EventStateType,
  Match,
  PreEventOrLiveType,
  EventBetType
} from '@honoregaming/types';
import { trigger, transition, animate, style } from '@angular/animations';
import { Subscription } from 'rxjs';
import { EventsService } from '@honoregaming/events';

@Component({
  selector: 'hg-event-with-event-bet-type',
  templateUrl: './event-with-event-bet-type.component.html',
  styleUrls: ['./event-with-event-bet-type.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
  animations: [
    trigger('disabled', [
      transition('void => *', [
        style({ opacity: '0', transform: 'scale(0)' }),
        animate('0.1s ease-in', style({ opacity: '1', transform: 'scale(1)' }))
      ]),
      transition('* => void', animate('0.1s ease-in', style({ opacity: '0', transform: 'scale(0)' })))
    ])
  ]
})
export class EventWithEventBetTypeComponent implements OnChanges {
  @Input() event: Match;
  @Input() eventBetType: EventBetType;
  @Input() showEntrypoint: boolean;
  @Input() isVirtual: boolean;
  @Input() showEntryPointName: boolean;
  @Input() isAboutToStart: boolean;
  @Input() isStreamed: boolean;
  @Input() showTimer: boolean;
  @Input() isLoadingOdds: boolean = false;

  @Output() betSelectionChanged = new EventEmitter<{
    item: EventBetTypeItem;
    selected: boolean;
  }>();

  disabled: boolean;
  subscription: Subscription;

  @ViewChild('betsElement') betsElement: ElementRef;

  isExpanded: boolean = false;

  constructor(private readonly eventsService: EventsService) {}

  ngOnChanges() {
    this.disabled =
      (this.event.preEventOrLive === PreEventOrLiveType.PreEvent &&
        this.event.state !== EventStateType.AboutToStart &&
        this.event.state !== EventStateType.Undisputed &&
        this.event.state !== EventStateType.Delayed) ||
      (this.event.preEventOrLive === PreEventOrLiveType.Live && this.event.state !== EventStateType.Started);
  }

  toggleBet(item: SelectableEventBetTypeItem) {
    if (
      !item.odds ||
      item.odds <= 1 ||
      !item.active ||
      !item.bettingAllowed ||
      item.completionDisabled ||
      !this.eventBetType.active ||
      !this.eventBetType.bettingAllowed ||
      this.disabled ||
      this.isLoadingOdds
    ) {
      return;
    }

    this.betSelectionChanged.emit({
      item: item,
      selected: !item.selected
    });
  }

  trackEventBetTypeItem(_index, eventBetTypeItem: EventBetTypeItem) {
    return eventBetTypeItem.id;
  }

  toggleExpand() {
    this.isExpanded = !this.isExpanded;
    if (!this.isExpanded) {
      this.betsElement.nativeElement.scrollIntoView({ block: 'start' });
    }
  }

  trackLastEvent(eventId: number): void {
    this.eventsService.trackLastEvent(eventId, this.event.entryPointId);
  }
}
