import {
  Component,
  OnInit,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Input,
  Output,
  EventEmitter,
  Inject
} from '@angular/core';
import { ContentService } from '../services/content.service';
import { finalize, skip, takeUntil } from 'rxjs/operators';
import { I18nService } from '@honoregaming/i18n';
import { Async, AsyncTrigger, DestroySubject, Scope, scopeToken } from '@honoregaming/core';
import { merge } from 'rxjs';

@Component({
  selector: 'hg-content',
  templateUrl: './content.component.html',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class ContentComponent extends DestroySubject implements OnInit {
  content: string;
  title: string;
  style: string;
  @Input()
  name: string;
  @Input()
  placeholderValues: string[];
  @Output()
  public titleChanged = new EventEmitter<string>();
  @Output()
  public noContent = new EventEmitter();

  @AsyncTrigger()
  languageTrigger = this.i18nService.languageChanged$;

  constructor(
    protected readonly contentService: ContentService,
    protected readonly cdRef: ChangeDetectorRef,
    protected readonly i18nService: I18nService,
    @Inject(scopeToken) public scope: Scope
  ) {
    super();
  }

  @Async()
  ngOnInit() {
    this.loadContent();
  }

  @Async()
  loadContent() {
    var languageCode = null;

    if (this.scope === Scope.Affiliate) {
      languageCode = this.i18nService.currentLanguageCode;
    }

    this.contentService
      .getContent(this.name, languageCode)
      .pipe(
        takeUntil(merge(this.i18nService.languageChanged$.pipe(skip(1)), this.destroy$)),
        finalize(() => {
          this.titleChanged.emit(this.title);
        })
      )
      .subscribe(
        resource => {
          this.placeholderValues?.forEach((v, i) => {
            resource.title = resource.title.replace(new RegExp('\\{' + i + '\\}', 'g'), v);
            resource.content = resource.content.replace(new RegExp('\\{' + i + '\\}', 'g'), v);
          });

          this.content = resource.content;
          this.style = resource.style;
          this.title = resource.title;

          this.cdRef.markForCheck();
        },
        _ => {
          this.noContent.emit();
        }
      );
  }
}
