import { Component, ChangeDetectionStrategy, Input } from '@angular/core';
import { take } from 'rxjs/operators';
import { I18nService } from '@honoregaming/i18n';
import { InstantGameTransaction } from '@honoregaming/types';
import { ToasterService } from '@honoregaming/ui';

@Component({
  selector: 'hg-instant-game-transaction',
  templateUrl: './instant-game-transaction.component.html',
  styleUrls: ['./instant-game-transaction.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class InstantGameTransactionComponent {
  @Input() transaction!: InstantGameTransaction;
  @Input() gameName?: string;

  constructor(private readonly toasterService: ToasterService, private readonly i18n: I18nService) {}

  contentCopied(): void {
    this.i18n
      .translate('ACCOUNT.COPIED.REFERENCE')
      .pipe(take(1))
      .subscribe(translation => this.toasterService.show(translation));
  }
}
