import {
  AfterViewInit,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  ComponentFactoryResolver,
  Inject,
  OnInit,
  ViewContainerRef
} from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { combineLatest, merge, of } from 'rxjs';
import { skip, take, takeUntil } from 'rxjs/operators';
import { Feature, OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';
import { AuthService, Me } from '@honoregaming/customer-core';
import { DestroySubject, getUtcNow } from '@honoregaming/core';
import { providersLoaders } from '@honoregaming/payment-providers';
import { CustomerGameAccountLimitationScope } from '@honoregaming/types';
import { AccountService } from '../../services/account.service';
import { ResponsibleGamblingService } from '../../services/responsible-gambling.service';
import { DepositProvider } from '../../models/deposit-provider.model';
import { PaymentProviderStatus, Provider } from '../../models/provider.model';
import { SelfLimitation } from '../../models/self-limitation.model';

@Component({
  selector: 'hg-deposit-provider-loader',
  template: '',
  styles: [''],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class DepositProviderLoaderComponent extends DestroySubject implements OnInit, AfterViewInit {
  uniqueProvider: boolean = false;
  provider?: Provider;
  canDoDeposit: boolean = true;

  private isViewInitialized: boolean = false;
  private providerName!: string;

  constructor(
    private readonly vcr: ViewContainerRef,
    private readonly cdRef: ChangeDetectorRef,
    private readonly resolver: ComponentFactoryResolver,
    private readonly route: ActivatedRoute,
    private readonly router: Router,
    private readonly accountService: AccountService,
    private readonly authService: AuthService,
    private readonly responsibleGamblingService: ResponsibleGamblingService,
    @Inject(operatorConfigurationToken) private readonly operatorConfiguration: OperatorConfiguration
  ) {
    super();
  }

  ngOnInit(): void {
    this.route.params.pipe(takeUntil(this.destroy$)).subscribe(params => {
      this.providerName = params.provider;
      if (this.isViewInitialized) {
        this.loadProvider();
      }
    });
  }

  ngAfterViewInit(): void {
    this.isViewInitialized = true;
    this.loadProvider();
  }

  private loadProvider(): void {
    const hasResponsibleGambling: boolean =
      this.operatorConfiguration.operatorFeatures?.includes(Feature.ResponsibleGambling) ?? false;

    const responsibleGamblingObservable = hasResponsibleGambling
      ? this.responsibleGamblingService.getLimitations()
      : of([]);

    combineLatest([responsibleGamblingObservable, this.authService.me$, this.accountService.getPaymentProviders()])
      .pipe(take(1), takeUntil(merge(this.destroy$, this.route.params.pipe(skip(1)))))
      .subscribe(([limitations, me, providersResponse]) => {
        if (hasResponsibleGambling) {
          this.canDoDeposit = this.evaluateDepositEligibility(me, limitations);
        }

        const activeProviders: Provider[] = providersResponse.providers.filter(
          (provider: Provider) => provider.depositStatus !== PaymentProviderStatus.Disabled
        );

        this.uniqueProvider = activeProviders.length === 1;
        this.provider = activeProviders.find(provider => provider.providerName.toLowerCase() === this.providerName);

        if (!this.canDoDeposit || !this.provider || this.provider.depositStatus === PaymentProviderStatus.Offline) {
          this.router.navigate(['../'], { relativeTo: this.route });
          return;
        }

        this.loadDynamicComponent(this.provider, providersResponse.customerDepositPredefinedAmount);
      });
  }

  private evaluateDepositEligibility(me: Me, limitations: SelfLimitation[]): boolean {
    const isExcluded: boolean = me.selfExclusionEndDate ? new Date(me.selfExclusionEndDate) > getUtcNow() : false;

    const depositLimit = limitations?.find(
      limitation => limitation.scope === CustomerGameAccountLimitationScope.Deposit
    );
    const depositLimitReached: boolean = me.responsibleGamblingDeposit === depositLimit?.amount;

    return !isExcluded && !depositLimitReached;
  }

  private loadDynamicComponent(provider: Provider, customerDepositPredefinedAmount: number[]): void {
    const providerLoader = this.resolveProviderLoader(provider);

    providerLoader().then(module => {
      this.vcr.clear();

      const componentType = provider.partnerId ? module.depositPartner : module.deposit;
      const factory = this.resolver.resolveComponentFactory<DepositProvider>(componentType);
      const componentRef = this.vcr.createComponent(factory);

      componentRef.instance.provider = provider;
      componentRef.instance.uniqueProvider = this.uniqueProvider;
      componentRef.instance.customerDepositPredefinedAmount = customerDepositPredefinedAmount;

      this.cdRef.markForCheck();
    });
  }

  private resolveProviderLoader(provider: Provider): () => Promise<any> {
    const loader = providersLoaders[provider.parentProviderName] ?? providersLoaders[provider.providerName];

    if (loader) {
      return loader;
    }

    return provider.banks ? providersLoaders['Bank'] : providersLoaders['Generic'];
  }
}
