import { Component, ChangeDetectionStrategy, Input, Output, EventEmitter } from '@angular/core';
import { BetBuilderLine, BetCategoryType } from '@honoregaming/types';
import { BetLine, BetSlipType } from '../../../models';

@Component({
  selector: 'hg-match-bet-line-header',
  templateUrl: './match-bet-line-header.component.html',
  styleUrls: ['./match-bet-line-header.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class MatchBetLineHeaderComponent {
  @Input() betLine: BetLine;
  @Input() betSlipType: BetSlipType;
  @Input() isLoadingOddsEventIds: number[] = [];

  @Output() betBuilderLineRemove: EventEmitter<BetBuilderLine> = new EventEmitter<BetBuilderLine>();

  BetCategoryType = BetCategoryType;
  BetSlipType = BetSlipType;

  constructor() {}

  onBetBuilderLineRemove(betBuilderLine: BetBuilderLine): void {
    this.betBuilderLineRemove.emit(betBuilderLine);
  }
}
