import { Component, ChangeDetectionStrategy, Input, Output, EventEmitter } from '@angular/core';
import { OperatorContact } from '@honoregaming/configuration';

@Component({
  selector: 'hg-footer-help-contact-item',
  templateUrl: './footer-help-contact-item.component.html',
  styleUrls: ['./footer-help-contact-item.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class FooterHelpContactItemComponent {
  @Input() contact?: OperatorContact;

  @Output() actionClicked = new EventEmitter<void>();

  constructor() {}

  emitActionClick(event: Event): void {
    event.preventDefault();
    this.actionClicked.emit();
  }
}
