import { Component, ChangeDetectionStrategy, Output, EventEmitter, Input } from '@angular/core';
import { FreeBetCouponBetSlip, FreeBetRuleBettingValidation } from '@honoregaming/betslip';

@Component({
  selector: 'hg-freebet-coupon-rules',
  templateUrl: './freebet-coupon-rules.component.html',
  styleUrls: ['./freebet-coupon-rules.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class FreebetCouponRulesComponent {
  @Input() freebetCoupon!: FreeBetCouponBetSlip;
  @Input() isBetSlipView: boolean = false;
  @Input() currentValidationRules: FreeBetRuleBettingValidation | undefined;

  @Output() rulesToggled: EventEmitter<void> = new EventEmitter<void>();

  constructor() {}

  toggleRules(event: Event): void {
    event?.stopPropagation();
    this.rulesToggled.emit();
  }
}
