import { Component, ChangeDetectionStrategy, Input, Output, EventEmitter } from '@angular/core';
import { CreateBetCodeRequest } from '@honoregaming/betslip';
import { BetSystemHistory, BetCategoryType } from '@honoregaming/types';

@Component({
  selector: 'hg-bet-system',
  templateUrl: './bet-system.component.html',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class BetSystemComponent {
  @Input()
  betSystem: BetSystemHistory;

  @Input()
  shouldDisplayBetCodeButton: boolean;

  @Input()
  hideSection: boolean = false;

  @Input()
  isGettingBetCode: boolean;

  @Input()
  canRebet: boolean;

  @Input() authorizedToReplayDrawGame: boolean = false;

  @Output()
  getBetCode = new EventEmitter<{ betCodeRequest: CreateBetCodeRequest; totalOdds: string }>();

  @Output()
  cashout = new EventEmitter<number>();

  @Output()
  rebet = new EventEmitter<BetSystemHistory>();

  @Output()
  completeMyBet = new EventEmitter<BetSystemHistory>();

  @Input()
  isTicket: boolean = false;

  BetCategoryType = BetCategoryType;

  public onGetBetCode(request: { betCodeRequest: CreateBetCodeRequest; totalOdds: string }) {
    this.getBetCode.emit(request);
  }

  public onCashout(betSystemId: number) {
    this.cashout.emit(betSystemId);
  }

  public onRebet(betSystem: BetSystemHistory) {
    this.rebet.emit(betSystem);
  }

  onCompleteMyBet(): void {
    this.completeMyBet.emit(this.betSystem);
  }
}
