import { ValidatorFn, AbstractControl, NG_VALIDATORS, Validator } from '@angular/forms';
import { Directive, Input } from '@angular/core';
import { PasswordPolicy } from '@honoregaming/types';
import { PasswordService } from '@honoregaming/customer-core';

@Directive({
  selector: '[hgPasswordPolicy]',
  providers: [
    {
      provide: NG_VALIDATORS,
      useExisting: PasswordPolicyRequirementValidatorDirective,
      multi: true
    }
  ]
})
export class PasswordPolicyRequirementValidatorDirective implements Validator {
  // tslint:disable-next-line:no-input-rename reason: input is named as the selector
  @Input('hgPasswordPolicy')
  passwordPolicy: PasswordPolicy;

  @Input('hgPasswordPolicyLogin')
  login: string;

  @Input('hgPasswordPolicyLoginWithoutPrefix')
  loginWithoutPrefix: string;

  constructor(private readonly passwordService: PasswordService) {}

  validate(control: AbstractControl): { [key: string]: any } {
    return this.passwordPolicy
      ? passwordPolicyRequirementValidator(this.passwordPolicy, this.loginWithoutPrefix, this.passwordService)(control)
      : null;
  }
}

function passwordPolicyRequirementValidator(
  policy: PasswordPolicy,
  loginOnly: string,
  passwordService: PasswordService
): ValidatorFn {
  return (control: AbstractControl): { [key: string]: any } => {
    const password: string = control.value;
    if (!policy) {
      return null;
    }

    const {
      hasConsecutiveLetterSequence,
      hasDigital,
      hasLowerCharacter,
      hasUppercharacter,
      hasConsecutiveNumberSequence,
      hasSameCharacterRepeated,
      isEqualToLogin,
      hasPasswordLength,
      hasNonLetterOrDigit
    } = passwordService.checkPassword(password, loginOnly);

    if (!hasPasswordLength) {
      return { passwordPolicy: 'PASSWORDREQUIREDLENGTH' };
    }

    if (policy.requireDigit && !hasDigital) {
      return { passwordPolicy: 'PASSWORDREQUIREDIGIT' };
    }

    if (policy.requireLowercase && !hasLowerCharacter) {
      return { passwordPolicy: 'PASSWORDREQUIRELOWERCASE' };
    }

    if (policy.requireNonLetterOrDigit && !hasNonLetterOrDigit) {
      return { passwordPolicy: 'PASSWORDREQUIRENONLETTERORDIGIT' };
    }

    if (policy.requireUppercase && !hasUppercharacter) {
      return { passwordPolicy: 'PASSWORDREQUIREUPPERCASE' };
    }

    const loweredPassword = password.toLocaleLowerCase();

    if (policy.preventConsecutiveSequence && loweredPassword.length && hasConsecutiveNumberSequence) {
      return { passwordPolicy: 'PASSWORDPREVENTCONSECUTIVENUMBERSEQUENCE' };
    }

    if (policy.preventConsecutiveSequence && loweredPassword.length && hasConsecutiveLetterSequence) {
      return { passwordPolicy: 'PASSWORDPREVENTCONSECUTIVELETTERSEQUENCE' };
    }

    if (policy.preventEqualToLogin && isEqualToLogin) {
      return { passwordPolicy: 'PASSWORDPREVENTSAMEASLOGIN' };
    }

    if (policy.preventSameCharacterRepeated && hasSameCharacterRepeated) {
      return { passwordPolicy: 'PASSWORDPREVENTSAMECHARACTERREPEATED' };
    }

    return null;
  };
}
