import { NgModule, ModuleWithProviders } from '@angular/core';
import { TimePipe } from './pipes/time.pipe';
import { DatePipe } from './pipes/date.pipe';
import { NumberPipe } from './pipes/number.pipe';
import { CurrencyPipe } from './pipes/currency.pipe';
import { I18nInterceptor } from './interceptors/i18n.interceptor';
import { I18nPipe } from './pipes/i18n.pipe';
import { I18nService } from './services/i18n.service';
import { CommonModule } from '@angular/common';
import { PercentPipe } from './pipes/percent.pipe';
import { AgePipe } from './pipes/age.pipe';
import { BooleanPipe } from './pipes/boolean.pipe';
import { WeightPipe } from './pipes/weight.pipe';
import { LongDatePipe } from './pipes/longdate.pipe';
import { LongTimePipe } from './pipes/longtime.pipe';
import { TextDatePipe } from './pipes/textdate.pipe';
import { ShortTextDatePipe } from './pipes/shorttextdate.pipe';
import { OddsFormatPipe } from './pipes/odds-format.pipe';
import { HTTP_INTERCEPTORS } from '@angular/common/http';
import { ShortDatePipe } from './pipes/shortdate.pipe';
import { MonthDatePipe } from './pipes/month-date.pipe';
import { CountDownFormatPipe } from './pipes/countdown-format.pipe';
import { LongCountDownFormatPipe } from './pipes/longcountdown-format.pipe';
import { DayDatePipe } from './pipes/day-date.pipe';

@NgModule({
  imports: [CommonModule],
  declarations: [
    I18nPipe,
    DatePipe,
    LongDatePipe,
    TextDatePipe,
    ShortTextDatePipe,
    DayDatePipe,
    TimePipe,
    LongTimePipe,
    OddsFormatPipe,
    NumberPipe,
    CurrencyPipe,
    PercentPipe,
    AgePipe,
    BooleanPipe,
    WeightPipe,
    ShortDatePipe,
    MonthDatePipe,
    CountDownFormatPipe,
    LongCountDownFormatPipe
  ],
  exports: [
    I18nPipe,
    DatePipe,
    LongDatePipe,
    DayDatePipe,
    TextDatePipe,
    ShortTextDatePipe,
    TimePipe,
    LongTimePipe,
    NumberPipe,
    CurrencyPipe,
    OddsFormatPipe,
    PercentPipe,
    AgePipe,
    BooleanPipe,
    WeightPipe,
    ShortDatePipe,
    MonthDatePipe,
    CountDownFormatPipe,
    LongCountDownFormatPipe
  ]
})
export class HgI18nModule {
  static forRoot(): ModuleWithProviders<HgI18nModule> {
    return {
      ngModule: HgI18nModule,
      providers: [
        {
          provide: HTTP_INTERCEPTORS,
          useClass: I18nInterceptor,
          multi: true
        },
        I18nService
      ]
    };
  }
}
