import {
  Component,
  OnInit,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Input,
  Output,
  EventEmitter
} from '@angular/core';
import { Router } from '@angular/router';
import { DrawGameBetSlipService } from '@honoregaming/betslip';
import { DestroySubject } from '@honoregaming/core';
import { DrawGamesService } from '@honoregaming/draw-games-ui';
import { EventsService } from '@honoregaming/events';
import { BetSystemHistory, DrawGame, DrawGameBorletteBetType } from '@honoregaming/types';
import { finalize, takeUntil } from 'rxjs/operators';

@Component({
  selector: 'hg-draw-games-replay',
  templateUrl: './draw-games-replay.component.html',
  styleUrls: ['./draw-games-replay.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class DrawGamesReplayComponent extends DestroySubject implements OnInit {
  @Input() authorized: boolean = false;
  @Input() betSystemHistory?: BetSystemHistory;
  @Input() navigateUrl?: string;
  @Output() close: EventEmitter<void> = new EventEmitter();

  loading: boolean = false;
  step: number = 0;
  isDoubChans: boolean = false;
  doubChansName?: string;
  isSelectionValid: boolean = false;
  drawGames: DrawGame[] = [];
  doubChansDrawGames: DrawGame[] = [];
  displayedDrawGames: DrawGame[] = [];
  selectedDrawGamesIds: number[] = [];
  step1SelectedDrawGamesIds: number[] = [];
  defaultSelectedDrawGamesIds: number[] = [];

  constructor(
    private eventsService: EventsService,
    private cdRef: ChangeDetectorRef,
    private drawGameBetSlipService: DrawGameBetSlipService,
    private drawGamesService: DrawGamesService,
    private router: Router
  ) {
    super();
  }

  ngOnInit(): void {
    this.loading = true;
    this.eventsService
      .getNextDrawGamesEvents()
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.loading = false;
          this.cdRef.markForCheck();
        })
      )
      .subscribe(events => {
        this.init(this.drawGamesService.filterAndSortDrawGames(events));
      });
  }

  init(events: DrawGame[]): void {
    this.drawGames = events.filter(x =>
      this.drawGameBetSlipService.canReplayEvent(x, this.authorized, events, this.betSystemHistory, true)
    );

    if (
      this.drawGameBetSlipService.canReplaybetType(
        DrawGameBorletteBetType.DoubChans,
        this.authorized,
        this.betSystemHistory
      )
    ) {
      this.doubChansDrawGames = this.drawGames.filter(x =>
        x.eventBetTypes.some(y => y.betTypeId === DrawGameBorletteBetType.DoubChans)
      );
      if (this.doubChansDrawGames.length > 0) {
        this.doubChansName = this.doubChansDrawGames
          .map(x => x.eventBetTypes.find(y => y.betTypeId === DrawGameBorletteBetType.DoubChans)?.name)
          .find(x => x != null);
      }
    }

    if (
      !this.drawGameBetSlipService.canReplayOtherThanBetType(
        DrawGameBorletteBetType.DoubChans,
        this.authorized,
        this.betSystemHistory
      )
    ) {
      this.drawGames = [];
    }

    if (this.drawGames.length > 0) {
      this.displayedDrawGames = this.drawGames;
      this.step = this.doubChansDrawGames.length > 0 ? 1 : 0;
    } else if (this.doubChansDrawGames.length > 0) {
      this.isDoubChans = true;
      this.displayedDrawGames = this.doubChansDrawGames;
    }
  }

  updateDrawGamesSelection(selection: number[]): void {
    this.selectedDrawGamesIds = selection;
    this.checkSelectionValidity();
  }

  checkSelectionValidity(): void {
    this.isSelectionValid = this.isDoubChans
      ? this.selectedDrawGamesIds.length === 2
      : this.selectedDrawGamesIds.length > 0;
  }

  back(): void {
    this.step = 1;
    this.isDoubChans = false;
    this.displayedDrawGames = this.drawGames;
    this.selectedDrawGamesIds = this.step1SelectedDrawGamesIds;
    this.defaultSelectedDrawGamesIds = this.selectedDrawGamesIds;
    this.checkSelectionValidity();
  }

  next(): void {
    this.step = 2;
    this.isDoubChans = true;
    this.displayedDrawGames = this.doubChansDrawGames;
    this.step1SelectedDrawGamesIds = this.selectedDrawGamesIds;
    this.selectedDrawGamesIds = [];
    this.defaultSelectedDrawGamesIds = [];
    this.checkSelectionValidity();
  }

  add(): void {
    if (!this.isDoubChans || this.step === 2) {
      const ids = this.isDoubChans ? this.step1SelectedDrawGamesIds : this.selectedDrawGamesIds;
      for (let id of ids) {
        const drawGame = this.drawGames.find(x => x.id === id);
        this.drawGameBetSlipService.replayEvent(
          drawGame,
          this.authorized,
          [DrawGameBorletteBetType.DoubChans],
          undefined,
          this.betSystemHistory
        );
      }
    }

    if (this.isDoubChans) {
      const firstDrawGame = this.doubChansDrawGames.find(x => x.id === this.selectedDrawGamesIds[0]);
      const secondDrawGame = this.doubChansDrawGames.find(x => x.id === this.selectedDrawGamesIds[1]);

      this.drawGameBetSlipService.replayDoubChans(
        firstDrawGame.expectedStart > secondDrawGame.expectedStart ? firstDrawGame : secondDrawGame,
        firstDrawGame.expectedStart > secondDrawGame.expectedStart ? secondDrawGame : firstDrawGame,
        this.authorized,
        this.betSystemHistory
      );
    }

    if (this.navigateUrl) {
      this.router.navigate([this.navigateUrl]);
    }

    this.close.emit();
  }
}
