import {
  Component,
  ChangeDetectionStrategy,
  Output,
  EventEmitter,
  Input,
  OnInit,
  ChangeDetectorRef
} from '@angular/core';
import { CreateSimulatedBetResponse, ICreateSimulatedBetEventResponse } from '@honoregaming/betslip';
import { BetLineStateType } from '@honoregaming/types';

@Component({
  selector: 'hg-bet-slip-simulate-result',
  templateUrl: './bet-slip-simulate-result.component.html',
  styleUrls: ['./bet-slip-simulate-result.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class BetSlipSimulateResultComponent implements OnInit {
  @Input() simulatedBetPlacedResponse: CreateSimulatedBetResponse;

  @Output()
  close = new EventEmitter();

  BetLineStateType = BetLineStateType;

  totalPaidAmount: number = 0;
  isResultDisplayed: boolean = false;
  playouts: any = [];
  liveInterval: NodeJS.Timeout;
  liveTimeLeft: number;
  livePercentageProgress: number;
  liveMinuteDisplayed: number;

  constructor(private cdr: ChangeDetectorRef) {}

  ngOnInit(): void {
    this.setPlayouts();
  }

  setPlayouts() {
    this.simulatedBetPlacedResponse.events.forEach(event => {
      this.playouts.push({
        home: {
          goals: event.playout.homeCompetitorGoals,
          halfTimeScore: event.playout.homeCompetitorHalfTimeScore,
          finalScore: event.playout.homeCompetitorScore,
          name: event.homeCompetitorName,
          scoreAtGivenTime: 0
        },
        away: {
          goals: event.playout.awayCompetitorGoals,
          halfTimeScore: event.playout.awayCompetitorHalfTimeScore,
          finalScore: event.playout.awayCompetitorScore,
          name: event.awayCompetitorName,
          scoreAtGivenTime: 0
        },
        bets: this.getBetLinesEvent(event),
        eventRef: event.reference
      });
    });
    this.startLiveTimer();
  }

  startLiveTimer() {
    const MATCH_DURATION = 90;
    const ROUND_DURATION = 10;

    this.liveTimeLeft = MATCH_DURATION - 0;
    this.livePercentageProgress = (100 * (MATCH_DURATION - this.liveTimeLeft)) / MATCH_DURATION;
    this.liveMinuteDisplayed = Math.round((this.livePercentageProgress / 100) * MATCH_DURATION);
    this.liveInterval = setInterval(() => {
      if (this.liveTimeLeft > 0) {
        this.liveTimeLeft--;
        this.livePercentageProgress = (100 * (MATCH_DURATION - this.liveTimeLeft)) / MATCH_DURATION;
        this.liveMinuteDisplayed = Math.round((this.livePercentageProgress / 100) * MATCH_DURATION);
        this.playouts.forEach(playout => {
          playout.home.goals.forEach(goal => {
            if (goal === this.liveMinuteDisplayed) {
              playout.home.scoreAtGivenTime++;
            }
          });
          playout.away.goals.forEach(goal => {
            if (goal === this.liveMinuteDisplayed) {
              playout.away.scoreAtGivenTime++;
            }
          });
        });
      } else {
        this.liveTimeLeft = 0;
        this.cdr.markForCheck();
        clearInterval(this.liveInterval);
        this.liveInterval = undefined;
        this.displayResults();
      }
      this.cdr.detectChanges();
    }, (1000 * ROUND_DURATION) / MATCH_DURATION);
  }

  displayResults(force: boolean = false) {
    if (force) {
      clearInterval(this.liveInterval);
      this.setPlayoutsFinalScore();
    }

    this.calculateTotalPaidAmount();
    this.isResultDisplayed = true;
  }

  setPlayoutsFinalScore() {
    this.playouts.forEach(playout => {
      playout.home.scoreAtGivenTime = playout.home.finalScore;
      playout.away.scoreAtGivenTime = playout.away.finalScore;
    });
  }

  calculateTotalPaidAmount() {
    this.simulatedBetPlacedResponse.bets.forEach(bet => {
      if (!bet.paidAmount) {
        return;
      }
      this.totalPaidAmount += bet.paidAmount;
    });
  }

  getBetLinesEvent(event: ICreateSimulatedBetEventResponse): any[] {
    let bets = [];
    this.simulatedBetPlacedResponse.bets.filter(bet => {
      bet.betLines.filter(betLine => {
        if (betLine.eventRef === event.reference) {
          bets.push(betLine);
        }
      });
    });
    return bets;
  }
}
