import { Inject, Injectable } from '@angular/core';
import { Feature, OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';
import { BetCategoryFilterData, BetCategoryType } from '@honoregaming/types';

@Injectable()
export class BetCategoryConfigurationService {
  constructor(@Inject(operatorConfigurationToken) private operatorConfiguration: OperatorConfiguration) {}

  getInstantGamesBetCategoryPath(): string {
    return (
      this.operatorConfiguration.betCategoriesPathConfiguration?.instantGamesConfiguration?.path ?? 'instant-games'
    );
  }

  get historyBetCategoriesFilterData(): BetCategoryFilterData[] {
    if (this.operatorConfiguration.operatorFeatures.indexOf(Feature.BetHistory) === -1) {
      return [];
    }

    const betCategoriesFilterData: BetCategoryFilterData[] = [
      {
        category: BetCategoryType.SportsFixedOdds,
        id: 'ProfilePage_MyBets_SportsHistory',
        icon: 'hg-my-bets-trophy',
        label: 'BET_CATEGORIES.SPORTSFIXEDODDS',
        navigationPath: '/myaccount/history'
      },
      {
        category: BetCategoryType.InstantGame,
        id: 'ProfilePage_MyBets_CasinoHistory',
        icon: 'hg-casino-token',
        label: 'BET_CATEGORIES.INSTANTGAME',
        navigationPath: '/myaccount/instant-games-history'
      }
    ];

    // Simulate is considered as a bet category within history page
    if (this.operatorConfiguration.bettingConfiguration?.allowSimulatedMode) {
      betCategoriesFilterData.push({
        category: 'Simulate',
        id: 'ProfilePage_MyBets_SimulatedHistory',
        icon: 'hg-simulate',
        label: 'ACCOUNT.MY_BETS.SIMULATED',
        navigationPath: '/myaccount/simulate-bets-history'
      });
    }

    if (this.operatorConfiguration.betCategories.includes(BetCategoryType.SportsPool)) {
      betCategoriesFilterData.push({
        category: BetCategoryType.SportsPool,
        id: 'ProfilePage_MyBets_SportsPoolHistory',
        icon: 'hg-sports-pool',
        label: 'ACCOUNT.SPORTS_POOL',
        navigationPath: '/myaccount/sportspool-history'
      });
    }

    return betCategoriesFilterData;
  }

  get couponsBetCategoriesFilterData(): BetCategoryFilterData[] {
    return this.operatorConfiguration.freeBetsConfiguration?.multiCouponEnabled
      ? [
          {
            category: BetCategoryType.SportsFixedOdds,
            id: 'Freebet_Filter_Sports',
            icon: 'hg-free-bet',
            label: 'BET_CATEGORIES.SPORTSFIXEDODDS'
          },
          {
            category: BetCategoryType.InstantGame,
            id: 'Freebet_Filter_Casino',
            icon: 'hg-casino-token',
            label: 'BET_CATEGORIES.INSTANTGAME'
          }
        ]
      : [];
  }
}
