import { Injectable } from '@angular/core';
import {
  Amounts,
  BetLine,
  CreateBetBetLineRequest,
  CreateBetRequest,
  CreateSimulatedBetRequest,
  CreateSportsPoolGameBetRequest,
  getCasesNumber,
  SimulatedBet,
  SportsPoolGameBetLineMatch,
  SportsPoolGameBetRequest
} from '@honoregaming/betslip';
import { BetBuilderLine, BetSlipMode, BetSystemType, HorseRaceRunner } from '@honoregaming/types';

@Injectable({
  providedIn: 'root'
})
export class BetComputingService {
  public computeRequest(
    betLines: BetLine[],
    mode: BetSlipMode,
    amounts: Amounts,
    betCode?: string,
    acceptOddsChange: boolean = false,
    useFreeBet: boolean = false,
    customerId: number | null = null,
    freebetCouponId: number = null,
    completeMyBetId: number | null = null
  ): CreateBetRequest {
    const request: CreateBetRequest = {
      maxPayout: amounts.summary.maxPayout,
      bettingTax: amounts.summary.bettingTax,
      totalStake: amounts.summary.totalStakeWithTax,
      freeBetCouponId: freebetCouponId,
      acceptOddsChange,
      useFreeBet,
      customerId,
      completeMyBetId,
      betLines: this.buildCreateBetBetLinesRequest(betLines, mode, amounts),
      type: null,
      betSystems: null,
      betCode
    };

    if (mode === BetSlipMode.Simple) {
      request.type = BetSystemType.Simple;

      amounts.values.forEach((a, i) => {
        request.betLines[i].stake = Number(a.amount.toFixed(2));
      });
    } else if (mode === BetSlipMode.Multiple) {
      request.type = BetSystemType.Multiple;
    } else {
      request.type = BetSystemType.System;
      request.betSystems = [];

      const betLineNumbers = request.betLines.map(l => l.number);
      amounts.values.forEach((a, i) => {
        if (a.amount) {
          request.betSystems.push({
            k: betLines.length - i,
            n: betLines.length,
            betLineNumbers: betLineNumbers,
            systemStake: a.amount,
            totalStake: Number((getCasesNumber(betLines.length - i, betLines.length) * a.amount).toFixed(2)),
            isFreeBet: useFreeBet
          });
        }
      });
    }

    return request;
  }

  public computeSportsPoolRequest(
    betLines: BetLine[],
    amounts: Amounts,
    freebetCouponId: number = null
  ): CreateSportsPoolGameBetRequest {
    const bets = [];
    betLines.forEach((betline: BetLine, index: number) => {
      // Create a Map where:
      // key   = matchPositionId
      // value = the aggregated SportsPoolGameBetLineMatch for that matchPosition
      const map = new Map<number, SportsPoolGameBetLineMatch>();
      // Iterate over each selected item
      for (const item of betline.selectedSportsPoolGameItems) {
        // If we have not yet created an entry for this matchPosition
        if (!map.has(item.matchId)) {
          // Initialize a new group for this matchPosition
          map.set(item.matchId, {
            matchPositionId: item.matchId,
            eventBetTypeItemIds: []
          });
        }
        // At this point we are guaranteed the entry exists
        // Push the item's id into the corresponding eventBetTypeItemIds array
        map.get(item.matchId)!.eventBetTypeItemIds.push(item.id);
      }
      // Convert the Map values into an array for the final result
      const matches = Array.from(map.values());
      const bet: SportsPoolGameBetRequest = {
        betLine: {
          number: index + 1,
          eventBetTypeId: betline.eventBetTypeId,
          selection: {
            flashType: betline.flashType,
            matches: matches
          }
        },
        stake: amounts.values[index].amount
      };

      bets.push(bet);
    });

    const request: CreateSportsPoolGameBetRequest = {
      bets: bets,
      bettingTax: amounts.summary.bettingTax,
      freeBetCouponId: freebetCouponId
    };

    return request;
  }

  public computeSimulateRequest(betLines: BetLine[], mode: BetSlipMode, amounts: Amounts): CreateSimulatedBetRequest {
    const bets = [];
    if (mode === BetSlipMode.Multiple) {
      const bet: SimulatedBet = {
        betLines: betLines.reduce((lines, l, i) => {
          const line: CreateBetBetLineRequest = {
            number: i + 1,
            oddsBoostId: l.oddsBoostId,
            manualOddsBoostId: l.manualOddsBoostId,
            eventId: l.eventId,
            eventBetTypeId: l.eventBetTypeId,
            eventBetTypeItemId: l.eventBetTypeItemId,
            fixedOdds: l.odds,
            maxOdds: l.maxOdds,
            quickPick: l.quickPick,
            baseList: l.baseList,
            extraList: l.extraList,
            combinations: l.combinations,
            associatedList: l.associatedList,
            allOrders: l.allOrders,
            multiValue: l.multiValue,
            nonRunners: null,
            replacementHorse: l.replacementHorse,
            stakeMultiplier: l.multiplier,
            key: l.formula?.key,
            baseAmount: l.baseStake,
            option: l.option,
            stake: null
          };

          lines.push(line);

          return lines;
        }, []),
        stake: amounts.summary.totalStake
      };

      bets.push(bet);
    } else if (mode === BetSlipMode.Simple) {
      betLines.forEach((betline: any, index: number) => {
        const bet: SimulatedBet = {
          betLines: [
            {
              number: index + 1,
              oddsBoostId: betline.oddsBoostId,
              manualOddsBoostId: betline.manualOddsBoostId,
              eventId: betline.eventId,
              eventBetTypeId: betline.eventBetTypeId,
              eventBetTypeItemId: betline.eventBetTypeItemId,
              fixedOdds: betline.odds,
              maxOdds: betline.maxOdds,
              quickPick: betline.quickPick,
              baseList: betline.baseList,
              extraList: betline.extraList,
              combinations: betline.combinations,
              associatedList: betline.associatedList,
              allOrders: betline.allOrders,
              multiValue: betline.multiValue,
              nonRunners: null,
              replacementHorse: betline.replacementHorse,
              stakeMultiplier: betline.multiplier,
              key: betline.formula?.key,
              baseAmount: betline.baseStake,
              option: betline.option,
              stake: null
            }
          ],
          stake: amounts.values[index].amount
        };

        bets.push(bet);
      });
    }
    const request: CreateSimulatedBetRequest = {
      bets: bets
    };

    return request;
  }

  private buildCreateBetBetLinesRequest(
    betLines: BetLine[],
    mode: BetSlipMode,
    amounts: Amounts
  ): CreateBetBetLineRequest[] {
    const createBetBetLineRequest: CreateBetBetLineRequest[] = [];
    let index: number = 1;
    for (const betLine of betLines) {
      if (
        (mode === BetSlipMode.Systems || mode === BetSlipMode.Multiple || amounts.values[index - 1]) &&
        !betLine.isBetCompletion
      ) {
        if (!betLine.isBetBuilder || !betLine.betBuilderLines?.length) {
          createBetBetLineRequest.push(this.buildCreateBetBetLineRequest(index, betLine));
        } else {
          betLine.betBuilderLines.forEach((betBuilderLine: BetBuilderLine, betBuilderLineIndex: number) => {
            createBetBetLineRequest.push(
              this.buildCreateBetBetLineRequest(index + betBuilderLineIndex, betLine, betBuilderLine)
            );
          });
          index += betLine.betBuilderLines.length - 1;
        }
      }
      index++;
    }

    return createBetBetLineRequest;
  }

  private buildCreateBetBetLineRequest(
    index: number,
    betLine: BetLine,
    betBuilderLine?: BetBuilderLine
  ): CreateBetBetLineRequest {
    const createBetBetLineRequest: CreateBetBetLineRequest = {
      number: index,
      oddsBoostId: betLine.oddsBoostId,
      manualOddsBoostId: betLine.manualOddsBoostId,
      eventId: betLine.eventId,
      eventBetTypeId: betBuilderLine ? betBuilderLine.eventBetTypeId : betLine.eventBetTypeId,
      eventBetTypeItemId: betBuilderLine ? betBuilderLine.eventBetTypeItemId : betLine.eventBetTypeItemId,
      fixedOdds: betLine.odds,
      maxOdds: betLine.maxOdds,
      quickPick: betLine.quickPick,
      baseList: betLine.baseList,
      extraList: betLine.extraList,
      combinations: betLine.combinations,
      associatedList: betLine.associatedList,
      allOrders: betLine.allOrders,
      multiValue: betLine.multiValue,
      nonRunners: null,
      replacementHorse: betLine.replacementHorse,
      stakeMultiplier: betLine.multiplier,
      key: betLine.formula?.key,
      baseAmount: betLine.baseStake,
      option: betLine.option,
      stake: null,
      associatedDrawGamesIds: betLine.associatedDrawGamesIds,
      isBetBuilder: !!betBuilderLine
    };

    if (betLine.runners) {
      createBetBetLineRequest.nonRunners = betLine.runners
        .filter((horseRaceRunner: HorseRaceRunner) => horseRaceRunner.nonRunner)
        .map((horseRaceRunner: HorseRaceRunner) => horseRaceRunner.number);
    }
    return createBetBetLineRequest;
  }
}
