import { InjectionToken } from '@angular/core';
import { Observable } from 'rxjs';
import { PrintConfiguration } from '@honoregaming/types';

export interface IPrinterService {
  connectToPrinter(): Observable<boolean>;
  isPrinterAvailable(): Observable<boolean>;
  print(
    templateModel: HTMLElement,
    printConfiguration: PrintConfiguration,
    propertyBag: Map<string, any>
  ): Observable<boolean>;
  scan(): Observable<string>;
}

export const printerServiceToken = new InjectionToken<IPrinterService>('PrinterService');
