import { DOCUMENT, isPlatformBrowser } from '@angular/common';
import { HttpClient } from '@angular/common/http';
import { Inject, Injectable, PLATFORM_ID } from '@angular/core';
import { Title } from '@angular/platform-browser';
import {
  OperatorConfiguration,
  OperatorSeo,
  globalConfiguration,
  operatorConfigurationToken
} from '@honoregaming/configuration';
import { Cacheable } from '@honoregaming/core';
import { Observable } from 'rxjs';
import { getRootFromPath } from '../utils/url.utils';
import { I18nService } from '@honoregaming/i18n';

@Injectable({ providedIn: 'root' })
export class SeoService {
  private isBrowser = isPlatformBrowser(this.platformId);
  constructor(
    private http: HttpClient,
    @Inject(DOCUMENT) private document: Document,
    @Inject(PLATFORM_ID) private platformId,
    private title: Title,
    @Inject(operatorConfigurationToken) private operatorConfiguration: OperatorConfiguration,
    private readonly i18nService: I18nService
  ) {}

  @Cacheable()
  private getSeoForRoot(root: string): Observable<OperatorSeo> {
    return this.http.get<OperatorSeo>(
      `${globalConfiguration.staticAssetsPath}${this.operatorConfiguration.commercialCode}/seo_${root}.json`
    );
  }

  public updateSeoInformation() {
    if (!this.isBrowser) return;

    let root = getRootFromPath(
      this.document.location.pathname,
      this.operatorConfiguration.betCategoriesPathConfiguration?.instantGamesConfiguration?.path ?? 'instant-games'
    );
    this.getSeoForRoot(root).subscribe(seo => {
      if (this.document.location.pathname.startsWith('/about/charities')) {
        this.title.setTitle(this.i18nService.translateSync('NAV.CHARITY'));
      } else {
        this.title.setTitle(seo.title);
      }
      if (seo.description) {
        let description: HTMLMetaElement = this.document.querySelector('meta[name="description"]');
        if (!description) {
          description = this.document.createElement('meta');
          description.name = 'description';
          document.querySelector('head').appendChild(description);
        }

        description.content = seo.description;
      }

      if (seo.keywords) {
        let keywords: HTMLMetaElement = this.document.querySelector('meta[name="keywords"]');
        if (!keywords) {
          keywords = this.document.createElement('meta');
          keywords.name = 'keywords';
          this.document.querySelector('head').appendChild(keywords);
        }

        keywords.content = seo.keywords;
      }
    });
  }
}
