import { Input, HostBinding, ViewChild, OnChanges, SimpleChanges, Directive } from '@angular/core';
import { AnimateDirective } from '@honoregaming/ui';
import { EventBetTypeItem } from '@honoregaming/types';

@Directive()
export abstract class EventBetTypeItemComponentBase implements OnChanges {
  @Input()
  eventBetTypeItem!: EventBetTypeItem;

  @Input()
  enableShortName = false;

  @Input()
  noName = false;

  @Input()
  displayBetsDistributions = true;

  @Input()
  noOdds = false;

  @HostBinding('class.short')
  get applyShort() {
    return this.enableShortName || !this.eventBetTypeItem.longName;
  }

  @HostBinding('class.selected')
  @Input()
  selected = false;

  @Input()
  disabled = false;

  @Input()
  inactive = false;

  @ViewChild(AnimateDirective, { static: false })
  odd: AnimateDirective;

  isDisabled: boolean = false;

  ngOnChanges(changes: SimpleChanges): void {
    if (
      !this.noOdds &&
      !this.disabled &&
      !this.inactive &&
      changes.eventBetTypeItem &&
      !changes.eventBetTypeItem.firstChange
    ) {
      const previousOdds = changes['eventBetTypeItem'].previousValue.odds;
      const currentOdds = changes['eventBetTypeItem'].currentValue.odds;
      if (currentOdds > previousOdds) {
        this.odd?.animate('up');
      } else if (currentOdds < previousOdds) {
        this.odd?.animate('down');
      }
    }

    if (changes.disabled || changes.eventBetTypeItem) {
      this.isDisabled = this.disabled || !this.eventBetTypeItem.odds || this.eventBetTypeItem.odds <= 1;
    }
  }
}
