import { Component, ChangeDetectionStrategy, Input, OnChanges } from '@angular/core';
import { BetLine } from '../../../models';
import { getCombinationsMultiplier } from '@honoregaming/core';

@Component({
  selector: 'hg-race-bet-line-header',
  templateUrl: './race-bet-line-header.component.html',
  styleUrls: ['./race-bet-line-header.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class RaceBetLineHeaderComponent implements OnChanges {
  @Input()
  betLine: BetLine;

  minOdds: number;
  maxOdds: number;
  getCombinationsMultiplier = getCombinationsMultiplier;

  constructor() {}

  ngOnChanges() {
    if (getCombinationsMultiplier(this.betLine.combinations) > 1) {
      const odds = this.betLine.combinations.map(x => x.fixedOdds);
      this.minOdds = Math.min(...odds);
      this.maxOdds = Math.max(...odds);
    }
  }
}
