import { Injectable } from '@angular/core';
import {
  EventBetType,
  EventBetTypeGroupedByBetType,
  EventWithEventBetTypes,
  HomeOrAway,
  Match,
  SelectableEventBetTypeItem,
  SelectedItem
} from '@honoregaming/types';
import { CompleteMyBetService } from '@honoregaming/core';

@Injectable({
  providedIn: 'root'
})
export class EventsMapperService {
  constructor(private readonly completeMyBetService: CompleteMyBetService) {}

  /**
   * Updates the selected state of all bet type items across a list of events.
   *
   * For each event, filters the selected items by eventId, then iterates through
   * all event bet types and their items to mark each item as selected/unselected
   * and compute whether bet completion is disabled.
   *
   * Note: Object references are intentionally broken (spread) to trigger Angular's
   * change detection.
   */
  updateEventsWithEventBetTypesSelectedItems(
    events: EventWithEventBetTypes<Match>[],
    selectedItems: SelectedItem[]
  ): void {
    for (let i = 0; i < events.length; i++) {
      const eventSelectedItems: SelectedItem[] = selectedItems.filter(
        (bet: SelectedItem) => bet.eventId === events[i].id
      );
      for (let j = 0; j < events[i].eventBetTypes?.length; j++) {
        for (let k = 0; k < events[i].eventBetTypes[j].eventBetTypeItems?.length; k++) {
          const selectedItem: SelectedItem | undefined = eventSelectedItems?.find(
            (bet: SelectedItem) => events[i].eventBetTypes[j].eventBetTypeItems[k].id === bet.eventBetTypeItemId
          );
          events[i] = { ...events[i] };
          events[i].eventBetTypes[j] = { ...events[i].eventBetTypes[j] };
          events[i].eventBetTypes[j].eventBetTypeItems[k].selected = !!selectedItem;
          events[i].eventBetTypes[j].eventBetTypeItems[k].completionDisabled =
            this.completeMyBetService.isCompletionDisabled(
              eventSelectedItems,
              selectedItem,
              events[i],
              events[i].eventBetTypes[j].eventBetTypeItems[k].odds
            );
        }
      }
    }
  }

  /**
   * Updates the selection state of event bet type items within grouped bet types.
   *
   * Compares each item's current state against the provided selected items and only
   * creates new object references where values actually changed. Groups, event bet types,
   * and items that remain unchanged preserve their original references, enabling
   * Angular's OnPush change detection to skip unnecessary re-renders.
   *
   * Returns the original array reference if no items changed at all.
   */
  updateEventBetTypesGroupedByBetType(
    eventBetTypesGroupedByBetType: EventBetTypeGroupedByBetType[],
    selectedItems: SelectedItem[],
    isLoadingOdds: boolean,
    match?: Match
  ): EventBetTypeGroupedByBetType[] {
    const eventSelectedItems: SelectedItem[] = match
      ? selectedItems.filter((bet: SelectedItem) => bet.eventId === match.id)
      : [];

    const selectedMap: Map<number, SelectedItem> = new Map(
      eventSelectedItems.map((bet: SelectedItem) => [bet.eventBetTypeItemId, bet])
    );

    let anyGroupChanged: boolean = false;

    const result: EventBetTypeGroupedByBetType[] = eventBetTypesGroupedByBetType.map(
      (group: EventBetTypeGroupedByBetType) => {
        let groupChanged: boolean = false;

        const updatedEventBetTypes: EventBetType[] = group.eventBetTypes.map((eventBetType: EventBetType) => {
          let ebtChanged: boolean = false;

          const updatedItems: SelectableEventBetTypeItem[] = eventBetType.eventBetTypeItems.map(
            (item: SelectableEventBetTypeItem) => {
              const selectedItem: SelectedItem | undefined = selectedMap.get(item.id);
              const newSelected: boolean = !!selectedItem;
              const newCompletionDisabled: boolean = this.completeMyBetService.isCompletionDisabled(
                eventSelectedItems,
                selectedItem,
                match,
                item.odds
              );
              const newDisabled: boolean =
                !eventBetType.bettingAllowed || !item.bettingAllowed || newCompletionDisabled || isLoadingOdds;
              const newInactive: boolean = !eventBetType.active || !item.active;

              if (
                item.selected === newSelected &&
                item.completionDisabled === newCompletionDisabled &&
                (item as any).disabled === newDisabled &&
                (item as any).inactive === newInactive
              ) {
                return item;
              }

              ebtChanged = true;
              return {
                ...item,
                selected: newSelected,
                completionDisabled: newCompletionDisabled,
                disabled: newDisabled,
                inactive: newInactive
              };
            }
          );

          if (!ebtChanged) {
            return eventBetType;
          }

          groupChanged = true;
          return { ...eventBetType, eventBetTypeItems: updatedItems };
        });

        if (!groupChanged) {
          return group;
        }

        anyGroupChanged = true;
        return { ...group, eventBetTypes: updatedEventBetTypes };
      }
    );

    return anyGroupChanged ? result : eventBetTypesGroupedByBetType;
  }

  /**
   * Populates teamGroupedItemsByBetType by organizing bet items into Home/Away groups
   * for specific bet types that require team-based templating (e.g., team scorers).
   *
   * This method:
   * 1. Iterates through betTypeIdsUsingTeamTemplate (bet types that need team grouping)
   * 2. Finds the corresponding event bet type items from eventBetTypesGroupedByBetType
   * 3. Groups those items by Home/Away using buildTeamGroupedItems()
   * 4. Stores the result indexed by betTypeId for template lookup
   *
   * Result structure: { betTypeId: { Home: [...items], Away: [...items] } }
   */
  populateRecordTeamList(
    betTypeIdsUsingTeamTemplate: number[],
    eventBetTypesGroupedByBetType: EventBetTypeGroupedByBetType[]
  ): Record<number, Record<HomeOrAway, EventBetType[]>> {
    return betTypeIdsUsingTeamTemplate.reduce((acc, betTypeId) => {
      // Find the event bet type matching this betTypeId from the grouped structure
      const matchingEventBetTypes: EventBetType[] = eventBetTypesGroupedByBetType.find(
        (ebt: EventBetTypeGroupedByBetType) => ebt.betTypeId === betTypeId
      )?.eventBetTypes;

      // Only process if we found items for this bet type
      if (matchingEventBetTypes && matchingEventBetTypes.length > 0) {
        acc[betTypeId] = this.buildTeamGroupedItems(matchingEventBetTypes);
      }

      return acc;
    }, {} as Record<number, Record<HomeOrAway, EventBetType[]>>);
  }

  /**
   * Groups bet type items by their homeOrAway property (Home or Away).
   *
   * This is used for bet types like team scorers where items need to be
   * displayed separately for home vs away team (e.g., home team goalscorers
   * in one column, away team goalscorers in another).
   */
  private buildTeamGroupedItems(eventBetTypes: EventBetType[]): Record<HomeOrAway, EventBetType[]> {
    return eventBetTypes.reduce((acc, eventBetType) => {
      const home: EventBetType = <EventBetType>{ ...eventBetType, eventBetTypeItems: [] };
      const away: EventBetType = <EventBetType>{ ...eventBetType, eventBetTypeItems: [] };

      eventBetType.eventBetTypeItems.forEach(eventBetTypeItem => {
        // Skip items without a homeOrAway designation
        if (!eventBetTypeItem.homeOrAway) {
          return;
        }

        if (eventBetTypeItem.homeOrAway === HomeOrAway.Home) {
          home.eventBetTypeItems.push(eventBetTypeItem);
        } else {
          away.eventBetTypeItems.push(eventBetTypeItem);
        }
      });

      // Add item to the appropriate Home or Away array (creating array if needed)
      if (home.eventBetTypeItems.length) {
        acc[HomeOrAway.Home] = [...(acc[HomeOrAway.Home] ?? []), home];
      }
      if (away.eventBetTypeItems.length) {
        acc[HomeOrAway.Away] = [...(acc[HomeOrAway.Away] ?? []), away];
      }

      return acc;
    }, {} as Record<HomeOrAway, EventBetType[]>);
  }
}
