import { Component, EventEmitter, Input, Output } from '@angular/core';

@Component({
  selector: 'hg-event-bet-type-picker',
  styleUrls: ['./event-bet-type-picker.component.scss'],
  templateUrl: 'event-bet-type-picker.component.html'
})
export class EventBetTypePickerComponent {
  @Input() eventBetTypeList: { name: string; betTypeId: number; betTypeContext?: string }[] = [];
  @Input() primaryTypeQuantity: number = 4;
  @Output() activeBetTypeChange: EventEmitter<{ betTypeId: number; betTypeContext?: string }> = new EventEmitter();

  @Input() activeBetType: { name: string; betTypeId: number; betTypeContext?: string };
  opened: boolean;

  constructor() {}

  updateActiveBetType(betType: { name: string; betTypeId: number; betTypeContext?: string }) {
    this.activeBetType = betType;
    this.activeBetTypeChange.emit({ betTypeId: betType.betTypeId, betTypeContext: betType.betTypeContext });
  }

  openWindow(opened: boolean) {
    this.opened = opened;
  }
}
