import { ChangeDetectionStrategy, ChangeDetectorRef, Component, Input, OnInit } from '@angular/core';
import { takeUntil } from 'rxjs/operators';
import { DestroySubject } from '@honoregaming/core';
import { SmarticoService } from '@honoregaming/customer-core';

@Component({
  selector: 'hg-account-avatar',
  templateUrl: './account-avatar.component.html',
  styleUrls: ['./account-avatar.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class AccountAvatarComponent extends DestroySubject implements OnInit {
  @Input() public width!: number;

  public isLoading: boolean = this.smarticoService.isEnabled;
  public avatarUrl: string | null = null;

  constructor(private readonly cdRef: ChangeDetectorRef, private readonly smarticoService: SmarticoService) {
    super();
  }

  ngOnInit(): void {
    if (!this.smarticoService.showMyAccount) {
      return;
    }

    this.smarticoService.avatarUrl$.pipe(takeUntil(this.destroy$)).subscribe(avatarUrl => {
      this.avatarUrl = avatarUrl;
      this.cdRef.markForCheck();
    });
  }

  onAvatarImageError(): void {
    this.avatarUrl = null;
    this.cdRef.markForCheck();
  }
}
