import { NgModule } from '@angular/core';
import { Routes, RouterModule } from '@angular/router';
import { BetCategoriesGuard, FeaturesGuard, MaintenanceComponent } from '@honoregaming/core';
import { BetCategoryType } from '@honoregaming/types';
import { LayoutComponent } from './components/layout/layout.component';
import { ValidateGuard, AuthenticationGuard, KioskGuard } from '../../../hg-core/src/public_api';
import { KioskLoginComponent } from './components/kiosk-login/kiosk-login.component';
import { GeoBlockComponent } from './components/geo-block/geo-block.component';
import { Feature } from '@honoregaming/configuration';

const routes: Routes = [
  {
    path: '',
    component: LayoutComponent,
    canActivateChild: [ValidateGuard, KioskGuard],
    children: [
      // Some "main" routes are defined below in the registerApplicationRoutes function
      // because they depend on the operator configuration
      {
        path: 'sports',
        loadChildren: () => import('../../../hg-sports/src/lib/hg-sports.module').then(m => m.HgSportsEventModule),
        data: { betCategories: [BetCategoryType.SportsFixedOdds] },
        canLoad: [BetCategoriesGuard]
      },
      { path: 'referral', redirectTo: 'myaccount/registration/step1' },
      {
        path: 'myaccount',
        loadChildren: () => import('../../../hg-account/src/lib/hg-account.module').then(m => m.HgAccountModule),
        canActivateChild: [AuthenticationGuard]
      },
      {
        path: 'about',
        loadChildren: () => import('../../../hg-about/src/lib/hg-about.module').then(m => m.HgAboutModule),
        data: {
          'sidebar-content': 'none'
        }
      },
      {
        path: 'horseracing',
        loadChildren: () =>
          import('../../../hg-horseracing/src/lib/hg-horseracing.module').then(m => m.HgHorseracingModule),
        data: {
          betCategories: [
            BetCategoryType.HorseRacingMutualInternationalPool,
            BetCategoryType.HorseRacingMutualOperatorPool
          ]
        },
        canLoad: [BetCategoriesGuard]
      },
      {
        path: 'horseracing-about',
        loadChildren: () =>
          import('../../../hg-horseracing/src/lib/about/hg-horseracing-about.module').then(
            m => m.HgHorseracingAboutModule
          )
      },
      {
        path: 'draw-games',
        loadChildren: () =>
          import('../../../hg-draw-games/src/lib/hg-draw-games.module').then(m => m.HgDrawGamesModule),
        data: { 'sidebar-content': 'none', betCategories: [BetCategoryType.DrawGame], featureName: Feature.DrawGame },
        canLoad: [BetCategoriesGuard],
        canActivate: [FeaturesGuard]
      },
      {
        path: 'virtual',
        loadChildren: () => import('../../../hg-virtual/src/lib/hg-virtual.module').then(m => m.HgVirtualModule),
        data: { 'sidebar-content': 'none', betCategories: [BetCategoryType.VirtualFixedOdds] },
        canLoad: [BetCategoriesGuard]
      },
      {
        path: 'sports-pool',
        loadChildren: () =>
          import('../../../hg-sports-pool/src/lib/hg-sports-pool.module').then(m => m.HgSportsPoolModule),
        data: { 'sidebar-content': 'none', betCategories: [BetCategoryType.SportsPool] },
        canLoad: [BetCategoriesGuard]
      },
      { path: 'update-password', redirectTo: 'myaccount/reset-password' }
    ]
  },
  { path: 'maintenance', component: MaintenanceComponent },
  { path: 'geo', component: GeoBlockComponent },
  { path: 'login', component: KioskLoginComponent, canActivate: [KioskGuard] },
  {
    path: 'landing',
    canActivate: [AuthenticationGuard],
    data: {
      allowAnonymous: true,
      denyAuthenticated: true
    },
    loadChildren: () => import('../../../hg-landing/src/lib/hg-landing.module').then(m => m.HgLandingModule)
  },
  { path: '**', redirectTo: 'sports', pathMatch: 'full' }
];

@NgModule({
  imports: [
    RouterModule.forRoot(routes, {
      scrollPositionRestoration: 'top',
      paramsInheritanceStrategy: 'always'
    })
  ],
  exports: [RouterModule]
})
export class AppRoutingModule {}
