import { Component, OnInit, ChangeDetectionStrategy, Output, EventEmitter } from '@angular/core';
import { DestroySubject, LocalStorageService } from '@honoregaming/core';
import { DirectMessageWidgetState } from 'projects/customer/hg-direct-message/src/lib/enums/direct-message-widget-view.enum';

@Component({
  selector: 'hg-account-update-options',
  templateUrl: './account-update-options.component.html',
  styleUrls: ['./account-update-options.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class AccountUpdateOptionsComponent extends DestroySubject implements OnInit {
  readonly LOCAL_STORAGE_KEY_DM: string = 'direct_message:widget:state';

  loading: boolean = false;
  enableChatButtonAtLogin?: boolean;

  @Output() backEvent = new EventEmitter();

  constructor(private readonly localStorageService: LocalStorageService) {
    super();
  }

  ngOnInit(): void {
    const directMessageWidgetState: DirectMessageWidgetState = this.localStorageService.getItem(
      this.LOCAL_STORAGE_KEY_DM
    );
    this.enableChatButtonAtLogin =
      directMessageWidgetState !== DirectMessageWidgetState.Close || !directMessageWidgetState;
  }

  submit(): void {
    this.loading = true;

    if (this.enableChatButtonAtLogin) {
      this.localStorageService.setItem(this.LOCAL_STORAGE_KEY_DM, DirectMessageWidgetState.Reduce);
    } else {
      this.localStorageService.setItem(this.LOCAL_STORAGE_KEY_DM, DirectMessageWidgetState.Close);
    }

    this.back();
  }

  updateChatButtonAtLogin(): void {
    this.enableChatButtonAtLogin = !this.enableChatButtonAtLogin;
  }

  back(): void {
    this.backEvent.emit();
  }
}
