import { Component, ChangeDetectionStrategy, Input, Output, EventEmitter } from '@angular/core';
import { NumberItem } from '../model/number-item';

@Component({
  selector: 'hg-numbers-selection-tool-base',
  templateUrl: './numbers-selection-tool-base.component.html',
  styleUrls: ['./numbers-selection-tool-base.component.scss', '../numbers-selection-tool.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class NumbersSelectionToolBaseComponent {
  @Input() title: string;
  @Input() numberItems: NumberItem[] = [];
  @Input() showSelectAll: boolean = true;
  @Output() added: EventEmitter<string[]> = new EventEmitter<string[]>();

  constructor() {}

  add(): void {
    this.added.emit(this.numberItems.filter(x => !x.disabled && x.selected).map(x => x.number));
  }

  get selectionCount(): number {
    return this.numberItems.filter(x => x.selected && !x.disabled).length;
  }

  get areAllSelected(): boolean {
    return this.selectionCount > 0 && this.selectionCount === this.numberItems.filter(x => !x.disabled).length;
  }

  selectAll(): void {
    const selected = !this.areAllSelected;
    for (const item of this.numberItems.filter(x => !x.disabled)) {
      item.selected = selected;
    }
  }
}
