import {
  Component,
  ChangeDetectionStrategy,
  HostBinding,
  Optional,
  ChangeDetectorRef,
  Input,
  Inject,
  PLATFORM_ID,
  OnInit,
  ViewChild,
  HostListener,
  ElementRef,
  SimpleChanges,
  OnChanges,
  AfterViewChecked,
  Output,
  EventEmitter
} from '@angular/core';
import { EventCategoriesService, EventsService } from '@honoregaming/events';
import { MediaService } from '@honoregaming/ui';
import { I18nService } from '@honoregaming/i18n';
import { ActivatedRoute, NavigationEnd, Router } from '@angular/router';
import { kioskToken, Scope, scopeToken } from '@honoregaming/core';
import { DOCUMENT, isPlatformServer } from '@angular/common';
import { EventCategoriesNavigationComponent } from 'projects/core/hg-sports-ui/src/lib/components/event-categories-navigation/event-categories-navigation.component';
import { OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';
import { MobileNavService } from 'projects/customer/customer/src/app/services/mobile-nav.service';
import { takeUntil } from 'rxjs/operators';

@Component({
  selector: 'hg-mobile-menu-event-categories-navigation',
  templateUrl: './mobile-menu-event-categories-navigation.component.html',
  styleUrls: ['./mobile-menu-event-categories-navigation.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class MobileMenuEventCategoriesNavigationComponent
  extends EventCategoriesNavigationComponent
  implements OnInit, OnChanges, AfterViewChecked
{
  @HostBinding('class') class = 'desktop-navigation-menu';

  @Input()
  showLiveEntry = false;

  @Input()
  availableBetChecker = false;

  @Output()
  betCheckerToggle = new EventEmitter<boolean>();

  Scope = Scope;
  isServer = isPlatformServer(this.platformId);

  displayEventCategories = true;
  displayTopCategories = true;
  displayTopCompetition = true;

  tutorialStep: number;
  tutorialStepsStorage = 'tutorial_steps';
  displayBetChecker = false;

  @ViewChild('slideArrowLeft', { static: false }) slideArrowLeft!: ElementRef;
  @ViewChild('slideArrowRight', { static: false }) slideArrowRight!: ElementRef;
  @ViewChild('slideElement', { static: false }) slideElement!: ElementRef;
  @ViewChild('parent', { static: false }) parent!: ElementRef;

  onResize(event) {
    if (event && this.slideElement) {
      this.checkInitialSize();
    }
  }

  @HostListener('scroll', ['$event'])
  scrollHandler(event: any) {
    if (event && this.slideElement) {
      this.checkScrollingSize(event);
    }
  }

  constructor(
    @Inject(scopeToken) scope: Scope,
    eventsService: EventsService,
    public eventCategoriesService: EventCategoriesService,
    @Optional() mediaService: MediaService,
    cdRef: ChangeDetectorRef,
    i18nService: I18nService,
    route: ActivatedRoute,
    private router: Router,
    private mobileNavService: MobileNavService,
    @Inject(PLATFORM_ID) private platformId,
    @Inject(operatorConfigurationToken) public operatorConfiguration: OperatorConfiguration,
    @Inject(DOCUMENT) private document: any,
    @Inject(kioskToken) public isKiosk: boolean
  ) {
    super(eventCategoriesService, eventsService, mediaService, cdRef, i18nService, route, scope, operatorConfiguration);
  }

  ngOnInit() {
    super.ngOnInit();
    this.checkInitialSize();
    this.tutorialStep = Number(localStorage.getItem(this.tutorialStepsStorage));

    this.mobileNavService.tutorialUpdate.pipe(takeUntil(this.destroy$)).subscribe(step => {
      this.tutorialStep = step;
      this.cdRef.markForCheck();
    });

    if (this.currentEntryPoint) {
      //for update the currentEntryPoint when any url changes on event category navigation
      this.router.events.subscribe(e => {
        if (e instanceof NavigationEnd) {
          if (this.route.snapshot['_routerState'].url === '/sports') {
            this.currentEntryPoint = null;
          }

          this.route.firstChild?.paramMap.subscribe(_ => {
            var sportId = this.route.firstChild?.snapshot?.params?.sport;

            if (
              (sportId && this.currentEntryPoint) ||
              (this.route.firstChild?.snapshot?.params?.sport &&
                Object.keys(this.route.firstChild?.snapshot?.params).length === 1)
            ) {
              var entryPoint = this.entryPoints?.filter(x => x.root.id === +sportId);
              if (entryPoint?.length === 1) {
                this.currentEntryPoint = entryPoint[0];
                this.toggleEntryPoint(this.currentEntryPoint);
              }
            } else {
              this.currentEntryPoint = null;
            }
            this.cdRef.markForCheck();
          });
        }
      });
    }
  }

  ngAfterViewChecked(): void {
    let scrollWidth = this.slideElement?.nativeElement.scrollWidth;
    if (this.tutorialStep === 4) {
      this.slideElement.nativeElement.scroll(scrollWidth, 0);
    }
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes.isBurgerOpened) {
      this.currentEntryPoint = null;
    }
  }

  navigate() {
    this.currentEntryPoint = null;
    this.closeMenu.emit();
  }

  checkScrollingSize(event: any) {
    const position = Math.round(event.currentTarget.scrollLeft + event.currentTarget.offsetWidth);
    const width = event.currentTarget.scrollWidth;

    if (position === width) {
      this.slideArrowRight.nativeElement.style.display = 'none';
    } else if (event.currentTarget.scrollLeft === 0) {
      this.slideArrowLeft.nativeElement.style.display = 'none';
    } else {
      this.slideArrowLeft.nativeElement.style.display = 'flex';
      this.slideArrowRight.nativeElement.style.display = 'flex';
    }
  }

  checkInitialSize() {
    if (this.slideElement) {
      if (this.slideElement.nativeElement.scrollWidth <= window.screen.width) {
        this.slideArrowRight.nativeElement.style.display = 'none';
        this.slideArrowLeft.nativeElement.style.display = 'none';
      } else {
        this.slideArrowRight.nativeElement.style.display = 'flex';
      }
    }
  }

  onNextPosition() {
    this.slideElement.nativeElement.scrollLeft += 200;
    this.slideArrowLeft.nativeElement.style.display = 'flex';
  }

  onPreviousPosition() {
    this.slideElement.nativeElement.scrollLeft -= 200;
    this.slideArrowRight.nativeElement.style.display = 'flex';
  }

  scrollToEntryPoints() {
    setTimeout(() => {
      this.parent?.nativeElement.scrollIntoView({ behavior: 'smooth', block: 'start', inline: 'nearest' });
      this.fixBody();
    });
  }

  fixBody(onlyInXs = false) {
    onlyInXs
      ? this.document.documentElement.classList.add('hidden-in-xs')
      : this.document.documentElement.classList.add('hidden');
  }

  toggleDisplayBetChecker(active = false) {
    if (active) {
      this.currentEntryPoint = null;
      this.displayBetChecker = true;
      this.betCheckerToggle.emit(true);
    } else if (this.displayBetChecker) {
      this.displayBetChecker = false;
      this.betCheckerToggle.emit(false);
    }
  }
}
