import {
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  ComponentFactory,
  ComponentFactoryResolver,
  ComponentRef,
  ElementRef,
  HostBinding,
  HostListener,
  Inject,
  NgZone,
  OnDestroy,
  OnInit,
  QueryList,
  Type,
  ViewChild,
  ViewChildren,
  ViewContainerRef
} from '@angular/core';
import { combineLatest, of } from 'rxjs';
import { finalize, take, takeUntil } from 'rxjs/operators';
import { Feature, OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';
import { AuthService, Me } from '@honoregaming/customer-core';
import { AccountService } from '@honoregaming/account';
import { DestroySubject, getUtcNow, LocalStorageService } from '@honoregaming/core';
import { providersLoaders } from '@honoregaming/payment-providers';
import { CustomerGameAccountLimitationScope } from '@honoregaming/types';
import { Media, MediaService } from '@honoregaming/ui';
import {
  TransactionMode,
  TransactionPopupData,
  TransactionPopupService,
  TRANSACTION_POPUP_DATA
} from 'projects/customer/hg-core/src/lib/services/transaction-popup.service';
import { PaymentAccount } from 'projects/customer/hg-core/src/lib/models';
import { CustomerWithdrawalInformation } from '../../models/customer-withdrawal-information.model';
import { DepositProvider } from '../../models/deposit-provider.model';
import { BankWithdrawProvider, WithdrawProvider } from '../../models/withdraw-provider.model';
import { PaymentProviderStatus, Provider } from '../../models/provider.model';
import { ResponsibleGamblingService } from '../../services/responsible-gambling.service';
import { SelfLimitation } from '../../models/self-limitation.model';
import { PaymentProviderResponse } from '../../models/payment-provider-response.model';

const CLOSE_ANIMATION_DURATION_MOBILE_MS = 300;
const CLOSE_ANIMATION_DURATION_DESKTOP_MS = 200;

type TransactionProvider = DepositProvider | WithdrawProvider;

interface PaymentProviderModule {
  deposit: Type<DepositProvider>;
  depositPartner?: Type<DepositProvider>;
  withdraw: Type<WithdrawProvider>;
}

@Component({
  selector: 'hg-transaction-popup',
  templateUrl: './transaction-popup.component.html',
  styleUrls: ['./transaction-popup.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class TransactionPopupComponent extends DestroySubject implements OnInit, OnDestroy {
  TransactionMode = TransactionMode;
  PaymentProviderStatus = PaymentProviderStatus;

  providersList: Provider[] = [];
  providerSelected?: Provider;
  private providerHostRef?: ViewContainerRef;
  private providerComponentRef?: ComponentRef<TransactionProvider>;

  @HostBinding('id') get hostId(): string {
    return `${this.data.mode.charAt(0).toUpperCase()}${this.data.mode.slice(1)}_Popup`;
  }

  @ViewChild('providerHost', { read: ViewContainerRef })
  set providerHost(vcr: ViewContainerRef) {
    if (vcr && vcr !== this.providerHostRef) {
      this.providerHostRef = vcr;

      if (this.providerSelected) {
        this.loadDynamicComponent(this.providerSelected);
      }
    }
  }

  @ViewChildren('providerItem') providerItems?: QueryList<ElementRef<HTMLElement>>;

  private providersContentRef?: ElementRef<HTMLElement>;
  private contentResizeObserver?: ResizeObserver;

  @ViewChild('providersContent')
  set providersContent(ref: ElementRef<HTMLElement> | undefined) {
    if (ref === this.providersContentRef) {
      return;
    }

    this.providersContentRef = ref;
    this.observeContentResize();
  }

  @ViewChild('providersListRef') providersListRef?: ElementRef<HTMLElement>;

  isDraggingList: boolean = false;
  private hasDraggedList: boolean = false;
  private dragStartX: number = 0;
  private dragStartScrollLeft: number = 0;

  isProviderLoading: boolean = false;
  isTransactionSuccess: boolean = false;
  isClosing: boolean = false;
  hasContentScroll: boolean = false;
  hasSubmit: boolean = false;
  transactionStateActive: boolean = false;
  isLoading: boolean = true;
  depositsNotAllowed: boolean = false;
  canDeposit: boolean = true;
  depositSelectionDetailsText?: string;
  showMinimumAmountsInDeposits: boolean =
    !!this.operatorConfiguration.onlineConfiguration?.showMinimumAmountsInDeposits;
  showMaximumAmountsInDeposits: boolean =
    !!this.operatorConfiguration.onlineConfiguration?.showMaximumAmountsInDeposits;

  withdrawalsNotAllowed: boolean = false;
  withdrawalInformation?: CustomerWithdrawalInformation;

  private customerDepositPredefinedAmount: number[] = [];
  private customerWithdrawalPredefinedAmount: number[] = [];
  private customerPaymentAccounts: PaymentAccount[] = [];
  private currentBalance: number = 0;
  private loadGeneration: number = 0;

  constructor(
    private readonly cdRef: ChangeDetectorRef,
    private readonly resolver: ComponentFactoryResolver,
    private readonly accountService: AccountService,
    private readonly popupService: TransactionPopupService,
    private readonly authService: AuthService,
    private readonly responsibleGamblingService: ResponsibleGamblingService,
    private readonly localStorageService: LocalStorageService,
    private readonly mediaService: MediaService,
    private readonly zone: NgZone,
    @Inject(operatorConfigurationToken) private readonly operatorConfiguration: OperatorConfiguration,
    @Inject(TRANSACTION_POPUP_DATA) public readonly data: TransactionPopupData
  ) {
    super();
  }

  ngOnInit(): void {
    if (this.data.mode === TransactionMode.Deposit) {
      this.initializeDepositState();
    } else {
      this.initializeWithdrawalState();
    }

    this.listenAuthStatus();
  }

  ngOnDestroy(): void {
    super.ngOnDestroy();
    this.contentResizeObserver?.disconnect();
  }

  get canSubmit(): boolean {
    return this.providerComponentRef?.instance.canSubmit ?? false;
  }

  @HostListener('window:resize')
  onWindowResize(): void {
    this.updateContentScrollState();
  }

  onProvidersListMouseDown(event: MouseEvent): void {
    const element: HTMLElement | undefined = this.providersListRef?.nativeElement;
    const isDesktop: boolean = this.mediaService.media >= Media.md;

    if (!element || !isDesktop) {
      return;
    }

    this.isDraggingList = true;
    this.hasDraggedList = false;
    this.dragStartX = event.pageX;
    this.dragStartScrollLeft = element.scrollLeft;
  }

  @HostListener('document:mousemove', ['$event'])
  onDocumentMouseMove(event: MouseEvent): void {
    const element: HTMLElement | undefined = this.providersListRef?.nativeElement;

    if (!this.isDraggingList || !element) {
      return;
    }

    const delta: number = event.pageX - this.dragStartX;

    if (Math.abs(delta) > 5) {
      this.hasDraggedList = true;
    }

    element.scrollLeft = this.dragStartScrollLeft - delta;
  }

  @HostListener('document:mouseup')
  onDocumentMouseUp(): void {
    this.isDraggingList = false;
  }

  close(): void {
    if (this.isClosing) {
      return;
    }

    this.isClosing = true;
    this.cdRef.markForCheck();

    const isDesktop: boolean = this.mediaService.media >= Media.md;
    const duration: number = isDesktop ? CLOSE_ANIMATION_DURATION_DESKTOP_MS : CLOSE_ANIMATION_DURATION_MOBILE_MS;

    setTimeout(() => this.popupService.close(), duration);
  }

  submitTransaction(): void {
    const instance: TransactionProvider | undefined = this.providerComponentRef?.instance;

    if (!instance) {
      return;
    }

    if (this.data.mode === TransactionMode.Deposit) {
      (instance as DepositProvider).submitDeposit();
      return;
    }

    (instance as WithdrawProvider).submitWithdraw();
  }

  selectProvider(provider: Provider): void {
    if (this.hasDraggedList) {
      this.hasDraggedList = false;
      return;
    }

    this.providerSelected = provider;
    this.localStorageService.setItem('transaction:provider', this.providerSelected.providerName);
    this.isTransactionSuccess = false;
    this.isProviderLoading = true;
    this.loadDynamicComponent(provider);
    this.scrollToSelectedProvider(provider);
  }

  isActiveProvider(provider: Provider): boolean {
    return (
      this.transactionStateActive &&
      this.getProviderStatus(provider) === PaymentProviderStatus.Online &&
      provider.active
    );
  }

  private getProviderStatus(provider: Provider): PaymentProviderStatus {
    return this.data.mode === TransactionMode.Deposit ? provider.depositStatus : provider.withdrawalStatus;
  }

  private listenAuthStatus(): void {
    this.authService.status$.pipe(takeUntil(this.destroy$)).subscribe(status => {
      if (status === 'disconnected') {
        this.close();
      }
    });
  }

  private scrollToSelectedProvider(provider: Provider): void {
    setTimeout(() => {
      if (!this.providerItems) {
        return;
      }

      const index: number = this.providersList.indexOf(provider);
      const element: HTMLElement = this.providerItems.toArray()[index]?.nativeElement;

      element?.scrollIntoView({ block: 'center', inline: 'center', behavior: 'smooth' });
    });
  }

  private initializeDepositState(): void {
    const hasResponsibleGambling: boolean =
      this.operatorConfiguration.operatorFeatures?.includes(Feature.ResponsibleGambling) ?? false;

    const responsibleGamblingObservable = hasResponsibleGambling
      ? this.responsibleGamblingService.getLimitations()
      : of([]);

    combineLatest([
      responsibleGamblingObservable,
      this.authService.me$,
      this.accountService.getPaymentProviders(),
      this.accountService.getGlobalDepositState()
    ])
      .pipe(
        take(1),
        takeUntil(this.destroy$),
        finalize(() => {
          this.isLoading = false;
          this.cdRef.markForCheck();
        })
      )
      .subscribe(([limitations, me, providersResponse, depositStateActive]) => {
        if (hasResponsibleGambling) {
          this.canDeposit = this.evaluateDepositEligibility(me, limitations);
        }

        if (!this.canDeposit) {
          this.depositsNotAllowed = true;
          return;
        }

        this.applyDepositProviders(providersResponse, depositStateActive);
      });
  }

  private initializeWithdrawalState(): void {
    combineLatest([
      this.authService.me$,
      this.accountService.getPaymentProviders(),
      this.accountService.getGlobalWithdrawalState(),
      this.accountService.getWithdrawalInformation()
    ])
      .pipe(
        take(1),
        takeUntil(this.destroy$),
        finalize(() => {
          this.isLoading = false;
          this.cdRef.markForCheck();
        })
      )
      .subscribe(([me, providersResponse, withdrawalStateActive, withdrawalInformation]) => {
        this.applyWithdrawalInformation(withdrawalInformation);

        if (this.withdrawalsNotAllowed) {
          return;
        }

        this.customerPaymentAccounts = me.customerPaymentAccounts ?? [];
        this.currentBalance = me.balance;
        this.applyWithdrawalProviders(providersResponse, withdrawalStateActive);
      });
  }

  private evaluateDepositEligibility(me: Me, limitations: SelfLimitation[]): boolean {
    const isExcluded: boolean = me.selfExclusionEndDate ? new Date(me.selfExclusionEndDate) > getUtcNow() : false;

    const depositLimit: SelfLimitation = limitations?.find(
      (limitation: SelfLimitation) => limitation.scope === CustomerGameAccountLimitationScope.Deposit
    );
    const depositLimitReached: boolean = me.responsibleGamblingDeposit === depositLimit?.amount;

    return !isExcluded && !depositLimitReached && me.depositsAllowed;
  }

  private applyDepositProviders(providersResponse: PaymentProviderResponse, depositStateActive: boolean): void {
    this.transactionStateActive = depositStateActive;
    this.customerDepositPredefinedAmount = providersResponse.customerDepositPredefinedAmount ?? [];
    this.providersList = this.sortInactiveProvidersLast(
      providersResponse.providers.filter(
        (provider: Provider) => provider.depositStatus !== PaymentProviderStatus.Disabled
      )
    );

    this.selectDefaultProvider();
  }

  private applyWithdrawalInformation(withdrawalInformation: CustomerWithdrawalInformation): void {
    this.withdrawalInformation = withdrawalInformation;
    this.withdrawalsNotAllowed = !(withdrawalInformation.canDoWithdrawal && withdrawalInformation.withdrawalsAllowed);
  }

  private applyWithdrawalProviders(providersResponse: PaymentProviderResponse, withdrawalStateActive: boolean): void {
    this.transactionStateActive = withdrawalStateActive;
    this.customerWithdrawalPredefinedAmount = providersResponse.customerWithdrawalPredefinedAmount ?? [];
    this.providersList = this.sortInactiveProvidersLast(
      providersResponse.providers.filter(
        (provider: Provider) => provider.withdrawalStatus !== PaymentProviderStatus.Disabled
      )
    );

    this.selectDefaultProvider();
  }

  private sortInactiveProvidersLast(providers: Provider[]): Provider[] {
    return [...providers].sort(
      (providerA: Provider, providerB: Provider) =>
        Number(this.isActiveProvider(providerB)) - Number(this.isActiveProvider(providerA))
    );
  }

  private selectDefaultProvider(): void {
    const defaultProvider: Provider = this.resolveDefaultProvider();

    if (defaultProvider) {
      this.selectProvider(defaultProvider);
    }
  }

  private resolveDefaultProvider(): Provider | undefined {
    const savedProviderName: string = this.localStorageService.getItem('transaction:provider');
    const savedProvider: Provider = savedProviderName
      ? this.providersList.find(
          (provider: Provider) => provider.providerName === savedProviderName && this.isActiveProvider(provider)
        )
      : undefined;

    return savedProvider ?? this.providersList.find((provider: Provider) => this.isActiveProvider(provider));
  }

  private loadDynamicComponent(provider: Provider): void {
    if (!provider || !this.providerHostRef) {
      return;
    }

    const currentGeneration: number = ++this.loadGeneration;

    this.isProviderLoading = true;
    this.providerHostRef.clear();
    this.cdRef.markForCheck();

    const providerLoader: () => Promise<PaymentProviderModule> = this.resolveProviderLoader(provider);

    providerLoader().then((module: PaymentProviderModule) => {
      if (currentGeneration !== this.loadGeneration) {
        return;
      }

      this.providerComponentRef =
        this.data.mode === TransactionMode.Deposit
          ? this.createDepositComponent(module, provider)
          : this.createWithdrawComponent(module, provider);

      const instance: TransactionProvider = this.providerComponentRef.instance;

      instance.provider = provider;
      instance.uniqueProvider = this.providersList.length === 1;
      instance.isPopin = true;

      this.hasSubmit = instance.hasSubmit;
      this.isProviderLoading = false;
      this.cdRef.markForCheck();
      this.observeContentResize();
      setTimeout(() => this.updateContentScrollState());
    });
  }

  private createDepositComponent(module: PaymentProviderModule, provider: Provider): ComponentRef<DepositProvider> {
    const componentType: Type<DepositProvider> =
      provider.partnerId && module.depositPartner ? module.depositPartner : module.deposit;
    const factory: ComponentFactory<DepositProvider> =
      this.resolver.resolveComponentFactory<DepositProvider>(componentType);
    const componentRef: ComponentRef<DepositProvider> = this.providerHostRef.createComponent(factory);

    componentRef.instance.customerDepositPredefinedAmount = this.customerDepositPredefinedAmount;
    componentRef.instance.depositSuccess.pipe(takeUntil(this.destroy$)).subscribe(() => this.onTransactionSuccess());

    return componentRef;
  }

  private createWithdrawComponent(module: PaymentProviderModule, provider: Provider): ComponentRef<WithdrawProvider> {
    const factory: ComponentFactory<WithdrawProvider> = this.resolver.resolveComponentFactory<WithdrawProvider>(
      module.withdraw
    );
    const componentRef: ComponentRef<WithdrawProvider> = this.providerHostRef.createComponent(factory);
    const instance: WithdrawProvider = componentRef.instance;

    instance.maximumAmount = this.withdrawalInformation?.maxWithdrawalAmountAvailable;
    instance.withdrawalDelay = this.withdrawalInformation?.customerWithdrawalMinDelay ?? 0;
    instance.customerWithdrawalPredefinedAmount = this.customerWithdrawalPredefinedAmount;
    instance.currentBalance = this.currentBalance;

    if (provider.banks) {
      (instance as BankWithdrawProvider).customerPaymentAccounts = this.customerPaymentAccounts.filter(
        (account: PaymentAccount) =>
          account.providerName === provider.providerName && account.provider === provider.providerId
      );
    }

    instance.withdrawSuccess.pipe(takeUntil(this.destroy$)).subscribe(() => this.onTransactionSuccess());

    return componentRef;
  }

  private onTransactionSuccess(): void {
    this.isTransactionSuccess = true;
    this.cdRef.markForCheck();
    setTimeout(() => this.updateContentScrollState());
  }

  private observeContentResize(): void {
    this.contentResizeObserver?.disconnect();

    const element: HTMLElement | undefined = this.providersContentRef?.nativeElement;

    if (!element || typeof ResizeObserver === 'undefined') {
      return;
    }

    this.contentResizeObserver = new ResizeObserver(() => this.updateContentScrollState());
    this.contentResizeObserver.observe(element);

    const providerElement: HTMLElement | undefined = this.providerComponentRef?.location.nativeElement;

    if (providerElement) {
      this.contentResizeObserver.observe(providerElement);
    }
  }

  private updateContentScrollState(): void {
    const element: HTMLElement | undefined = this.providersContentRef?.nativeElement;
    const hasContentScroll: boolean = !!element && element.scrollHeight > element.clientHeight;

    if (hasContentScroll === this.hasContentScroll) {
      return;
    }

    // ResizeObserver runs outside the Angular zone — re-enter it only when the state actually changes
    this.zone.run(() => {
      this.hasContentScroll = hasContentScroll;
      this.cdRef.markForCheck();
    });
  }

  private resolveProviderLoader(provider: Provider): () => Promise<PaymentProviderModule> {
    const loader = providersLoaders[provider.parentProviderName] ?? providersLoaders[provider.providerName];

    if (loader) {
      return loader;
    }

    return provider.banks ? providersLoaders['Bank'] : providersLoaders['Generic'];
  }
}
