import { Inject, Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';
import { globalConfiguration, OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';
import { IResourcesProviderService, LocaleResources } from '@honoregaming/i18n';
import { environment } from '../environments/environment';
import { tap } from 'rxjs/operators';

declare var require: any;
let localTranslations = {};
if (!environment.production || environment.version === 'pr') {
  const files = require.context('.', true, /translations\/.*\.json$/i);
  files.keys().forEach(f => {
    var currentTranslation = files(f);
    for (var lang in currentTranslation) {
      if (!localTranslations[lang]) {
        localTranslations[lang] = {};
      }
      for (var key in currentTranslation[lang]) {
        localTranslations[lang][key] = currentTranslation[lang][key];
      }
    }
  });
}

@Injectable()
export class ResourcesProviderService implements IResourcesProviderService {
  constructor(
    private httpClient: HttpClient,
    @Inject(operatorConfigurationToken) private operatorConfiguration: OperatorConfiguration
  ) {}

  getLocaleResources(languageCode: string): Observable<LocaleResources> {
    return this.httpClient
      .get<LocaleResources>(
        `${globalConfiguration.staticAssetsPath}${this.operatorConfiguration.commercialCode}/localeresources/${languageCode}.json`
      )
      .pipe(tap(res => this.mergeDevelopmentRessources(res, languageCode)));
  }

  mergeDevelopmentRessources(ressources: LocaleResources, languageCode: string) {
    if (!environment.production || environment.version === 'pr') {
      Object.assign(ressources.translations, localTranslations[languageCode]);
    }
  }
}
