import { Component, ChangeDetectionStrategy, Input, Output, EventEmitter } from '@angular/core';
import { RegisteredTemplatesType } from 'projects/core/hg-templating/src/lib/template.registration';

export type TemplatePopinTemplateProp = { type: RegisteredTemplatesType; inputs: any };

@Component({
  selector: 'hg-template-popin',
  templateUrl: './template-popin.component.html',
  styleUrls: ['./template-popin.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class TemplatePopinComponent {
  @Input() template: TemplatePopinTemplateProp;
  @Output() close = new EventEmitter<unknown>();
}
