import { ChangeDetectionStrategy, Component, OnInit } from '@angular/core';
import { combineLatest, from, Observable } from 'rxjs';
import { filter, map, shareReplay, switchMap, take, takeUntil } from 'rxjs/operators';
import { DestroySubject } from '@honoregaming/core';
import { SmarticoService } from '@honoregaming/customer-core';
import { SmarticoNavigationItem } from '@honoregaming/types';
import {
  DeepLinkParams,
  DpType,
  SmarticoLevel,
  SmarticoSDK,
  UserPublicProperties
} from 'projects/customer/hg-core/src/lib/models/smartico-sdk.model';

type SmarticoUserProgression = {
  level: string;
  levelImage: string;
  points: number;
  requiredPoints: number;
  progressPercentage: number;
} | null;

@Component({
  selector: 'hg-smartico-account-block',
  templateUrl: './smartico-account-block.component.html',
  styleUrls: ['./smartico-account-block.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class SmarticoAccountBlockComponent extends DestroySubject implements OnInit {
  readonly isSmarticoEnabled: boolean = this.smarticoService.isEnabled;
  readonly showLevelProgression: boolean = this.smarticoService.showLevelProgression;

  smarticoUserProps$?: Observable<UserPublicProperties>;
  smarticoMissionsCount$?: Observable<number>;
  smarticoUserProgression$?: Observable<SmarticoUserProgression>;
  isSmarticoUserProfileReady: boolean = false;

  DPType: typeof DpType = DpType;
  SmarticoNavigationItem = SmarticoNavigationItem;

  constructor(private readonly smarticoService: SmarticoService) {
    super();
  }

  ngOnInit(): void {
    this.initSmarticoState();
  }

  executeDeepLink(type: DpType, params?: DeepLinkParams): void {
    this.smarticoService.executeDeepLink(type, params);
  }

  isNavigationItemVisible(item: SmarticoNavigationItem): boolean {
    return this.smarticoService.isNavigationItemVisible(item);
  }

  private initSmarticoState(): void {
    if (!this.smarticoService.isEnabled) {
      return;
    }
    const smartico$: Observable<SmarticoSDK> = this.smarticoService.identifiedSmartico$.pipe(
      filter((smartico): smartico is SmarticoSDK => !!smartico)
    );
    this.smarticoUserProps$ = this.smarticoService.userPublicProperties$.pipe(
      filter((userPublicProperties): userPublicProperties is UserPublicProperties => !!userPublicProperties),
      takeUntil(this.destroy$),
      shareReplay(1)
    );
    this.smarticoMissionsCount$ = this.smarticoService.missionsCount$;
    this.smarticoUserProgression$ = combineLatest([this.smarticoUserProps$, smartico$]).pipe(
      switchMap(([smarticoUserProps, smartico]) =>
        from(smartico.api.getLevels()).pipe(
          map(levels => {
            const sortedLevels: SmarticoLevel[] = levels.sort((a, b) => a.required_points - b.required_points);
            const userPoints: number = smarticoUserProps.ach_points_ever ?? 0;
            let currentLevelIndex: number = sortedLevels.findIndex(
              level => level.id === smarticoUserProps.ach_level_current_id
            );
            if (currentLevelIndex === -1) {
              const reversedIndex: number = [...sortedLevels]
                .reverse()
                .findIndex(level => level.required_points <= userPoints);
              currentLevelIndex = reversedIndex === -1 ? -1 : sortedLevels.length - 1 - reversedIndex;
            }
            if (currentLevelIndex === -1) {
              return null;
            }
            const currentLevel: SmarticoLevel = sortedLevels[currentLevelIndex];
            const nextLevel: SmarticoLevel = sortedLevels[currentLevelIndex + 1];
            const requiredPoints: number = nextLevel?.required_points ?? userPoints;
            return {
              level: currentLevel.name,
              levelImage: currentLevel.image,
              points: userPoints,
              requiredPoints: requiredPoints,
              progressPercentage: requiredPoints !== 0 ? (userPoints / requiredPoints) * 100 : 100
            };
          })
        )
      ),
      takeUntil(this.destroy$),
      shareReplay(1)
    );
    combineLatest([this.smarticoUserProps$, smartico$])
      .pipe(take(1), takeUntil(this.destroy$))
      .subscribe(() => (this.isSmarticoUserProfileReady = true));
  }
}
