import { NgModule } from '@angular/core';
import { AppComponent } from './app.component';
import { AppModule } from './app.module';
import { HTTP_INTERCEPTORS } from '@angular/common/http';
import { MediaService } from '@honoregaming/ui';
import { AutInterceptor, ConnectionErrorInterceptor } from 'projects/customer/hg-core/src/lib/interceptor';
import { BrowserAnimationsModule } from '@angular/platform-browser/animations';
import { IdleService, RoutingEventsService } from '@honoregaming/customer-core';
import { PushService, HonoreOperatorInterceptor, AppVersionInterceptor } from '@honoregaming/core';

@NgModule({
  imports: [AppModule, BrowserAnimationsModule],
  bootstrap: [AppComponent],
  providers: [
    RoutingEventsService,
    PushService,
    MediaService,
    IdleService,
    { provide: HTTP_INTERCEPTORS, useClass: AutInterceptor, multi: true },
    { provide: HTTP_INTERCEPTORS, useClass: ConnectionErrorInterceptor, multi: true },
    { provide: HTTP_INTERCEPTORS, useClass: HonoreOperatorInterceptor, multi: true },
    { provide: HTTP_INTERCEPTORS, useClass: AppVersionInterceptor, multi: true }
  ]
})
export class AppBrowserModule {
  constructor(routingEventsService: RoutingEventsService) {
    routingEventsService.listen();
  }
}
