import { AppComponent } from './app.component';
import { ServiceWorkerModule } from '@angular/service-worker';
import { AppRoutingModule } from './app.routing.module';
import { FormsModule } from '@angular/forms';
import { HgUiModule } from '@honoregaming/ui';
import {
  HgCoreModule,
  templatingBetSlipServiceToken,
  natifToken,
  scopeToken,
  Scope,
  prodToken,
  MaintenanceInterceptor,
  CookieStorageService,
  hgErrorHandlerFactory,
  MustChangePasswordInterceptor,
  scannerServiceToken,
  BetCategoryConfigurationService
} from '@honoregaming/core';
import {
  HgCoreModule as HgCustomerCoreModule,
  AuthService,
  PrivacyService,
  SESSION_IDENTIFIER,
  ScannerService,
  ServerTransition
} from '@honoregaming/customer-core';
import { HgI18nModule, resourcesProviderToken } from '@honoregaming/i18n';
import { HeaderComponent } from './components/header/header.component';
import { LayoutComponent } from './components/layout/layout.component';
import { SignUpComponent } from './components/signup/signup.component';
import { ContextualWidgetComponent } from './components/contextual-widget/contextual-widget.component';
import { OddsFormatSelectorComponent } from './components/odds-format-selector/odds-format-selector.component';
import { HttpClientModule, HTTP_INTERCEPTORS } from '@angular/common/http';
import { FooterComponent } from './components/footer/footer.component';
import { PrebootModule } from 'preboot';
import { BrowserModule, Title } from '@angular/platform-browser';
import { environment } from '../environments/environment';
import { HgTemplatingModule, eventServiceToken, templateServiceToken } from '@honoregaming/templating';
import { CustomerStateClassDirective } from './directives/customer-state-class.directive';
import { ResourcesProviderService } from './resources-provider.service';
import { TemplateService } from './templating.service';
import {
  customerOperatorConfigurationProviderFactory,
  customerOperatorConfigurationToken,
  CustomerOperatorConfiguration
} from '@honoregaming/customer-core';
import { operatorConfigurationToken } from '@honoregaming/configuration';
import { betValidationServiceToken, BetSlipService, transactionPopupServiceToken } from '@honoregaming/betslip';
import { BetValidationService } from './services/bet-validation.service';
import { TransactionPopupService } from 'projects/customer/hg-core/src/lib/services/transaction-popup.service';
import { authServiceToken } from '@honoregaming/authentication';
import { AcceptGcuComponent } from './popins/accept-gcu/accept-gcu.component';
import { HgCustomerUiModule } from '@honoregaming/customer-ui';
import { EventsService } from '@honoregaming/events';
import { NotificationComponent } from './popins/notification/notification.component';
import { PrivacyComponent } from './components/privacy/privacy.component';
import { UserBlockedComponent } from './popins/user-blocked/user-blocked.component';
import { filter, take } from 'rxjs/operators';
import { Guid } from 'guid-typescript';
import { ActivatedRoute, ActivatedRouteSnapshot, NavigationEnd, Router } from '@angular/router';
import { VisitorService } from './services/visitor.service';
import { ABACKLINK, AKEY, ASESSION, EXTERNAL_AFFILIATE_TOKEN, REF } from './constants/affiliate.constant';
import { NavBarService } from './services/nav-bar.service';
import { kioskToken } from '@honoregaming/core';
import { KioskLoginComponent } from './components/kiosk-login/kiosk-login.component';
import { HgAuthenticationModule, RoutingEventsService } from '@honoregaming/authentication';
import { LoyaltyStatusNotificationComponent } from './popins/loyalty-status-notification/loyalty-status-notification.component';
import { WonBetSystemsNotificationComponent } from './popins/won-bet-systems-notification/won-bet-systems-notification.component';
import { WonTournamentNotificationComponent } from './popins/won-tournament-notification/won-tournament-notification.component';
import { DOCUMENT, isPlatformServer } from '@angular/common';
import { ActiveSessionAlreadyExistsComponent } from './popins/session-already-active/session-already-active.component';
import { GeoBlockComponent } from './components/geo-block/geo-block.component';
import { ValidationCodeBlockedComponent } from './popins/validation-code-blocked/validation-code-blocked.component';
import { TemplatePopinComponent } from './popins/template/template-popin.component';
import { NegativeBalanceNotAllowedComponent } from './popins/negative-balance-not-allowed/negative-balance-not-allowed.component';
import { WelcomeTutorialComponent } from './components/welcome-tutorial/welcome-tutorial.component';
import { UTM_CAMPAIGN, UTM_MEDIUM, UTM_SOURCE } from './constants/utm.constant';
import { S2S_CLICK_ID, S2S_TRACKER_NAME } from './constants/s2s.constant';
// tslint:disable-next-line: no-submodule-imports
import { BarcodeScanner } from '@ionic-native/barcode-scanner/ngx';
import { CharityService } from 'projects/customer/hg-about/src/lib/services/charity.service';
import { HgDirectMessageModule } from 'projects/customer/hg-direct-message/src/public_api';

const eventSelectors: any[] = [
  { selector: 'input,textarea', events: ['keypress', 'keyup', 'keydown', 'input', 'change'] },
  { selector: 'select,option', events: ['change'] },
  { selector: 'input', events: ['keyup'], preventDefault: true, keyCodes: [13], freeze: true },
  { selector: 'form', events: ['submit'], preventDefault: true, freeze: true },
  { selector: 'input,textarea', events: ['focusin', 'focusout', 'mousedown', 'mouseup'], replay: false },
  { selector: 'button,hg-event-bet-type-item', events: ['click'], preventDefault: true, freeze: true }
];
@NgModule({
  imports: [
    AppRoutingModule,
    HttpClientModule,
    BrowserModule,
    ServerTransition.forRoot({ appId: 'hg-customer' }),
    FormsModule,
    HgUiModule,
    HgTemplatingModule,
    HgCustomerCoreModule.forRoot(),
    HgCoreModule.forRoot(),
    HgCustomerUiModule,
    HgI18nModule.forRoot(),
    PrebootModule.withConfig({ appRoot: 'hg-root', eventSelectors, replay: false }),
    ServiceWorkerModule.register('/ngsw-worker.js', { enabled: environment.production }),
    HgAuthenticationModule.forRoot(),
    HgDirectMessageModule
  ],
  declarations: [
    AppComponent,
    KioskLoginComponent,
    HeaderComponent,
    LayoutComponent,
    SignUpComponent,
    CustomerStateClassDirective,
    ContextualWidgetComponent,
    OddsFormatSelectorComponent,
    FooterComponent,
    AcceptGcuComponent,
    NotificationComponent,
    PrivacyComponent,
    UserBlockedComponent,
    NotificationComponent,
    LoyaltyStatusNotificationComponent,
    WonBetSystemsNotificationComponent,
    WonTournamentNotificationComponent,
    ActiveSessionAlreadyExistsComponent,
    GeoBlockComponent,
    TemplatePopinComponent,
    NegativeBalanceNotAllowedComponent,
    ValidationCodeBlockedComponent,
    WelcomeTutorialComponent
  ],
  providers: [
    customerOperatorConfigurationProviderFactory(),
    { provide: operatorConfigurationToken, useExisting: customerOperatorConfigurationToken },
    Title,
    { provide: HTTP_INTERCEPTORS, useClass: MaintenanceInterceptor, multi: true },
    { provide: HTTP_INTERCEPTORS, useClass: MustChangePasswordInterceptor, multi: true },
    { provide: eventServiceToken, useExisting: EventsService },
    { provide: resourcesProviderToken, useClass: ResourcesProviderService },
    { provide: templateServiceToken, useClass: TemplateService },
    { provide: natifToken, useValue: environment.natif },
    { provide: kioskToken, useValue: environment.kiosk },
    {
      provide: ErrorHandler,
      useFactory: hgErrorHandlerFactory,
      deps: [prodToken]
    },
    { provide: prodToken, useValue: environment.production },
    { provide: betValidationServiceToken, useExisting: BetValidationService },
    { provide: transactionPopupServiceToken, useExisting: TransactionPopupService },
    { provide: templatingBetSlipServiceToken, useExisting: BetSlipService },
    { provide: authServiceToken, useExisting: AuthService },
    { provide: scopeToken, useValue: environment.kiosk ? Scope.Kiosk : Scope.Customer },
    { provide: scannerServiceToken, useExisting: ScannerService },
    NavBarService,
    BarcodeScanner,
    BetCategoryConfigurationService,
    CharityService
  ]
})
export class AppModule {
  constructor(
    private privacyService: PrivacyService,
    private storageService: CookieStorageService,
    private activatedRoute: ActivatedRoute,
    private router: Router,
    @Inject(PLATFORM_ID) private platformId: any,
    @Inject(DOCUMENT) private document: any,
    private visitorService: VisitorService,
    private authService: AuthService,
    @Inject(customerOperatorConfigurationToken) private operatorConfiguration: CustomerOperatorConfiguration,
    routingEventsService: RoutingEventsService
  ) {
    if (isPlatformServer(this.platformId)) {
      return;
    }

    routingEventsService.listen({
      AuthenticationError: () => this.router.navigate(['login'])
    });
    this.router.events
      .pipe(
        filter(event => event instanceof NavigationEnd),
        take(1)
      )
      .subscribe((_: NavigationEnd) => {
        let guidSession = this.storageService.getItem(SESSION_IDENTIFIER)
          ? this.storageService.getItem(SESSION_IDENTIFIER)
          : this.storageService.getItem(ASESSION)
          ? this.storageService.getItem(ASESSION)
          : Guid.create().toString();

        if (!this.storageService.getItem(SESSION_IDENTIFIER)) {
          this.storageService.setItem(SESSION_IDENTIFIER, guidSession);
        }

        const shouldSendVisitor: boolean = this.trackVisitor(guidSession) || this.trackS2SClick();

        if (shouldSendVisitor) {
          this.visitorService.sendVisitor().pipe(take(1)).subscribe();
        }

        this.privacyService.privacyConfiguration$?.subscribe(x => {
          if (!!x && x.consents.analytics) {
            guidSession = this.storageService.getItem(SESSION_IDENTIFIER)
              ? this.storageService.getItem(SESSION_IDENTIFIER)
              : this.storageService.getItem(ASESSION);

            const shouldSendAffiliate = this.trackAffiliate(guidSession);

            if (shouldSendAffiliate) {
              this.visitorService.sendVisitor().pipe(take(1)).subscribe();
            }
          }
        });
      });
  }

  trackAffiliate(guidSession: string) {
    if (!this.authService.isAuthenticated()) {
      let newRoute = this.activatedRoute.snapshot;
      while (newRoute.firstChild) {
        newRoute = newRoute.firstChild;
      }

      const qpLowerCase = Object.keys(newRoute.queryParams).reduce((acc, key) => {
        acc[key.toLowerCase()] = newRoute.queryParams[key];
        return acc;
      }, {});

      const externalAffiliateToken: string = qpLowerCase[REF.toLowerCase()];
      const affiliateKey: string = qpLowerCase[AKEY.toLowerCase()];
      const originBacklink: string = this.document.referrer;

      const opt = { expires: 30 };

      if (externalAffiliateToken || affiliateKey) {
        if (externalAffiliateToken) {
          this.storageService.setItem(EXTERNAL_AFFILIATE_TOKEN, externalAffiliateToken, opt);
        }
        if (affiliateKey) {
          this.storageService.setItem(AKEY, affiliateKey, opt);
        }
        this.storageService.setItem(ASESSION, guidSession, opt);
        originBacklink ? this.storageService.setItem(ABACKLINK, originBacklink, opt) : null;

        return true;
      }
    }
    return false;
  }

  trackVisitor(guidSession: string) {
    let source = null;
    let medium = null;
    let campaign = null;

    let newRoute = this.activatedRoute.snapshot;
    while (newRoute.firstChild) {
      newRoute = newRoute.firstChild;
    }

    const qpLowerCase = Object.keys(newRoute.queryParams).reduce((acc, key) => {
      acc[key.toLowerCase()] = newRoute.queryParams[key];
      return acc;
    }, {});

    source = qpLowerCase[UTM_SOURCE.toLowerCase()];
    campaign = qpLowerCase[UTM_CAMPAIGN.toLowerCase()];
    medium = qpLowerCase[UTM_MEDIUM.toLowerCase()];

    if (source && campaign && medium) {
      this.storageService.setItem(SESSION_IDENTIFIER, guidSession);
      this.storageService.setItem(UTM_SOURCE, source);
      this.storageService.setItem(UTM_MEDIUM, medium);
      this.storageService.setItem(UTM_CAMPAIGN, campaign);
      return true;
    }

    return false;
  }

  trackS2SClick(): boolean {
    let newRoute: ActivatedRouteSnapshot = this.activatedRoute.snapshot;
    while (newRoute.firstChild) {
      newRoute = newRoute.firstChild;
    }

    const qpLowerCase = Object.keys(newRoute.queryParams).reduce((acc, key) => {
      acc[key.toLowerCase()] = newRoute.queryParams[key];
      return acc;
    }, {});

    for (const { clickIdParam, trackerName } of this.operatorConfiguration.s2STelemetryConfiguration
      ?.s2SClickIdParams ?? []) {
      const capturedClickId: string = qpLowerCase[clickIdParam.toLowerCase()];
      if (capturedClickId) {
        this.storageService.setItem(S2S_TRACKER_NAME, trackerName);
        this.storageService.setItem(S2S_CLICK_ID, capturedClickId);
        return true;
      }
    }
    return false;
  }
}
