import { NgModule, ModuleWithProviders } from '@angular/core';
import { CommonModule } from '@angular/common';
import { EqualsValidatorDirective } from './validators/equals-passwords.validator';
import { PasswordPolicyRequirementValidatorDirective } from './validators/password.validator';
import {
  AuthService,
  BannerService,
  CustomerService,
  NavigationService,
  PasswordService,
  TelemetryService
} from './services';
import { AuthenticationGuard } from './guards/authentication.guard';
import { ValidateGuard } from './guards/validate.guard';
import { KioskGuard } from './guards/kiosk.guard';
import { DistancePipe } from './pipes/distance.pipe';
import { appInitializerFactory } from './initializers/app.initializer';
import { HgI18nModule } from '@honoregaming/i18n';
import { ErrorComponent } from './containers/error/error.component';
import { GoogleAnalyticsTelemetryService } from './services/telemetry/google-analytics.telemetry.service';
import { FacebookPixelTelemetryService } from './services/telemetry/facebook-pixel.telemetry.service';
import { ConnectionErrorComponent } from './popins/connection-error/connection-error.component';
import { E2PixelTelemetryService } from './services/telemetry/e2-pixel.telemetry.service';
import { telemetryServiceToken } from './services/telemetry/telemetry-service.model';
import { NotificationService } from './services/notification.service';
import { PrivacyService } from './services/privacy.service';
import { DirectMessageGuard } from './guards/direct-message.guard';
import { ExoClickPixelTelemetryService } from './services/telemetry/exoclick-pixel.telemetry.service';
import { EsKimiTelemetryService } from './services/telemetry/eskimi.telemetry.service';
import { SportRadarTelemetryService } from './services/telemetry/sportradar.telemetry.service';
import { CaptchaService } from './services/captcha/captcha.service';
import { captchaServiceToken } from './services/captcha/captcha-service.model';
import { ReCaptchaV3Service } from './services/captcha/recaptchav3.captcha.service';
import { TurnstileCaptchaService } from './services/captcha/turnstile.captcha.service';
import { NoopCaptchaService } from './services/captcha/noop.captcha.service';
import { ClarityTelemetryService } from './services/telemetry/clarity.telemetry.service';
import { EvinaCaptchaService } from './services/captcha/evina.captcha.service';
import { FingerprintCaptchaService } from './services/captcha/fingerprint.captcha.service';
import { RoigenPixelTelemetryService } from './services/telemetry/roigen.telemetry.service';
import { FavoritesService } from './services/favorites.service';
import { HotjarPixelTelemetryService } from './services/telemetry/hotjar-pixel.telemetry.service';
import { SimulateModeGuard } from './guards/simulate-mode.guard';
import { GeniusSportTelemetryService } from './services/telemetry/genius-sport.telemetry.service';
import { SmartLookTelemetryService } from './services/telemetry/smartlook.telemetry.service';
import { GoogleTagManagerTelemetryService } from './services/telemetry/google-tag-manager.telemetry.service';
import { CriteoTelemetryService } from './services/telemetry/criteo.telemetry.service';
import { SmarticoService } from './services/smartico/smartico.service';
import { SmarticoTelemetryService } from './services/telemetry/smartico.telemetry.service';
import { EgwTelemetryService } from './services/telemetry/egw.telemetry.service';

@NgModule({
  imports: [CommonModule, HgI18nModule],
  declarations: [
    ConnectionErrorComponent,
    EqualsValidatorDirective,
    PasswordPolicyRequirementValidatorDirective,
    DistancePipe,
    ErrorComponent
  ],
  exports: [EqualsValidatorDirective, PasswordPolicyRequirementValidatorDirective, DistancePipe, ErrorComponent]
})
export class HgCoreModule {
  static forRoot(): ModuleWithProviders<HgCoreModule> {
    return {
      ngModule: HgCoreModule,
      providers: [
        AuthService,
        AuthenticationGuard,
        ValidateGuard,
        KioskGuard,
        DirectMessageGuard,
        SimulateModeGuard,
        CustomerService,
        NavigationService,
        appInitializerFactory,
        SmarticoService,
        GoogleAnalyticsTelemetryService,
        FacebookPixelTelemetryService,
        E2PixelTelemetryService,
        ExoClickPixelTelemetryService,
        EsKimiTelemetryService,
        SportRadarTelemetryService,
        ClarityTelemetryService,
        RoigenPixelTelemetryService,
        HotjarPixelTelemetryService,
        GeniusSportTelemetryService,
        SmartLookTelemetryService,
        GoogleTagManagerTelemetryService,
        CriteoTelemetryService,
        SmarticoTelemetryService,
        EgwTelemetryService,
        TelemetryService,
        {
          provide: telemetryServiceToken,
          useExisting: TelemetryService
        },
        BannerService,
        ReCaptchaV3Service,
        TurnstileCaptchaService,
        NoopCaptchaService,
        EvinaCaptchaService,
        FingerprintCaptchaService,
        FavoritesService,
        CaptchaService,
        {
          provide: captchaServiceToken,
          useExisting: CaptchaService,
          deps: [CustomerService]
        },
        NotificationService,
        PrivacyService,
        PasswordService
      ]
    };
  }
}
