import {
  Component,
  OnChanges,
  ChangeDetectionStrategy,
  Input,
  SimpleChanges,
  ViewChild,
  HostBinding,
  ChangeDetectorRef
} from '@angular/core';
import { BetLine } from '../../models';
import { AnimateDirective } from '@honoregaming/ui';

@Component({
  selector: 'hg-odds',
  templateUrl: './odds.component.html',
  styleUrls: ['./odds.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class OddsComponent implements OnChanges {
  @Input()
  betLine: BetLine;

  @Input()
  @HostBinding('class.long')
  long: boolean;

  @Input()
  acceptOddChange: boolean;

  @Input() isLoadingOdds: boolean = false;

  @ViewChild('newOdds')
  newOdds: AnimateDirective;

  showNewOdds = false;

  constructor(private cdRef: ChangeDetectorRef) {}

  ngOnChanges(changes: SimpleChanges) {
    const betLineChange = changes['betLine'];
    if (betLineChange && !betLineChange.firstChange) {
      const prev = betLineChange.previousValue as BetLine;
      const cur = betLineChange.currentValue as BetLine;
      if (!this.acceptOddChange) {
        if (cur.newOdds && cur.newOdds !== cur.odds) {
          setTimeout(() => {
            if ((!prev.newOdds && cur.newOdds > cur.odds) || cur.newOdds > prev.newOdds) {
              this.newOdds.animate('animate-up');
              this.newOdds.stopAnimation();
            } else if ((!prev.newOdds && cur.newOdds < cur.odds) || cur.newOdds < prev.newOdds) {
              this.newOdds.animate('animate-down');
              this.newOdds.stopAnimation();
            }
          });
        }
      } else {
        if (prev.eventBetTypeItemId && cur.eventBetTypeItemId && prev.eventBetTypeItemId === cur.eventBetTypeItemId) {
          if (prev.odds !== cur.odds) {
            if (prev.odds < cur.odds) {
              this.newOdds.animate('animate-up');
              this.newOdds.stopAnimation();
            } else {
              this.newOdds.animate('animate-down');
              this.newOdds.stopAnimation();
            }

            this.showNewOdds = true;
            this.cdRef.markForCheck();
            setTimeout(() => {
              this.showNewOdds = false;
              this.cdRef.markForCheck();
            }, 1.7e3); // animation time - transition time
          }
        }
      }
    }
  }
}
