import { HttpClient } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { globalConfiguration } from '@honoregaming/configuration';
import { InstantGame } from '@honoregaming/types';
import { Observable } from 'rxjs';

@Injectable()
export class FavoritesService {
  constructor(private httpClient: HttpClient) {}

  getInstantGameFavorite(): Observable<InstantGame[]> {
    return this.httpClient.get<InstantGame[]>(`${globalConfiguration.apiBaseUrl}favorites/instant-game/games`);
  }

  updateInstantGameFavorite(id: number, remove?: boolean) {
    return this.httpClient.put(`${globalConfiguration.apiBaseUrl}favorites/instant-game/${id}`, {
      remove
    });
  }
}
