import { InjectionToken } from '@angular/core';
import { CustomerIdentity } from '@honoregaming/core';
import { Observable } from 'rxjs';

export interface IIdentifiedRetailService {
  checkCustomerIdentity(): Observable<{ success: boolean; customerBehalfIdentity: CustomerIdentity }>;
  saveCustomerIdentity(customerIdentity: CustomerIdentity);
  getLastCustomerIdentity(): CustomerIdentity;
}

export const IdentifiedRetailServiceToken = new InjectionToken<IIdentifiedRetailService>('IdentifiedRetailService');
