import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { globalConfiguration } from '@honoregaming/configuration';
import { TicketHistory } from '@honoregaming/types';

@Injectable({ providedIn: 'root' })
export class TicketService {
  constructor(private httpClient: HttpClient) {}

  getTicketState(ticketNumber: string, pinCode: string) {
    return this.httpClient.post<TicketHistory>(globalConfiguration.apiBaseUrl + 'reporting/ticket', {
      ticketNumber: ticketNumber,
      pinCode: pinCode
    });
  }
}
