import { LoginComponent } from '../../../hg-customer-ui/src/lib/components/login/login.component';
import {
  Component,
  Optional,
  Inject,
  PLATFORM_ID,
  ChangeDetectorRef,
  NgZone,
  Injector,
  HostBinding,
  OnInit,
  ComponentFactoryResolver
} from '@angular/core';
import {
  IdleService,
  AuthService,
  TelemetryService,
  NotificationService,
  CustomerOperatorConfiguration,
  customerOperatorConfigurationToken
} from '@honoregaming/customer-core';
import { isPlatformBrowser, DOCUMENT, isPlatformServer } from '@angular/common';
import { EventReplayer } from 'preboot';
import { environment } from '../environments/environment';
import {
  BroadcastingService,
  ApplicationEvent,
  DialogService,
  ApplicationStateService,
  LocalStorageService
} from '@honoregaming/core';
import { MessageService, MediaService, Media } from '@honoregaming/ui';
import { BetPlaced } from '@honoregaming/betslip';
import { AppState, Plugins } from '@capacitor/core';
import { NotificationComponent as NotificationPopin } from './popins/notification/notification.component';
import { Router } from '@angular/router';
const { App } = Plugins;

@Component({
  selector: 'hg-root',
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.scss']
})
export class AppComponent implements OnInit {
  // Disable animation on older browser
  @HostBinding('@.disabled')
  public disableAnimations =
    isPlatformServer(this.platformId) || this.document.createElement('div').style['animation'] == null;

  public isServer = isPlatformServer(this.platformId);

  constructor(
    @Optional() idleService: IdleService,
    private authService: AuthService,
    @Inject(DOCUMENT) private document,
    private cdRef: ChangeDetectorRef,
    @Inject(PLATFORM_ID) private platformId: string,
    private appState: ApplicationStateService,
    private resolver: ComponentFactoryResolver,
    private injector: Injector,
    private replayer: EventReplayer,
    zone: NgZone,
    private broadcastingService: BroadcastingService,
    private messageService: MessageService,
    private dialogService: DialogService,
    private telemetryService: TelemetryService,
    @Optional() protected mediaService: MediaService,
    private localStorageService: LocalStorageService,
    private notificationService: NotificationService,
    @Inject(customerOperatorConfigurationToken) private operatorConfiguration: CustomerOperatorConfiguration,
    private router: Router
  ) {
    if (isPlatformBrowser(this.platformId)) {
      appState.isReady$.subscribe(() => {
        this.replayer.replayAll();
        if (idleService && !environment.kiosk) {
          idleService.startWatching(10 * 6e4).subscribe(() => {
            if (this.authService.isAuthenticated()) {
              this.authService.logout();
              zone.run(() => this.cdRef.markForCheck());
            } else if (this.router.url.indexOf('myaccount/registration') !== -1) {
              zone.run(() => this.router.navigate(['/']));
            }
          });
        }
      });
    }

    if (environment.natif) {
      import('projects/core/hg-core/src/lib/native-import/native-import.component').then(
        ({ NativeImportComponent }) => {
          let factory = this.resolver.resolveComponentFactory(NativeImportComponent);
          let instance = factory.create(this.injector).instance;
          instance.checkForUpdate('customer');
          setInterval(() => instance.checkForUpdate('customer'), 10 * 60e3);
        }
      );
    }
  }

  ngOnInit() {
    if (this.isServer) {
      return;
    }

    this.broadcastingService.register('displayLoginPopup').subscribe(() => {
      if (this.mediaService.media >= Media.lg) {
        this.messageService.sendComponentMessage(LoginComponent);
      } else {
        setTimeout(() => {
          this.dialogService.toggleDialog('login', true);
        });
      }
    });

    // In case of BetPlace, refresh the customer balance
    this.broadcastingService.register<BetPlaced>(ApplicationEvent.BetPlaced).subscribe(x => {
      this.telemetryService.trackEvent('bet_placed', x);
      this.authService.getBalance().subscribe();
    });

    App.addListener('appStateChange', (state: AppState) => {
      if (state.isActive) {
        this.authService.tryRefresh().subscribe({
          error: () => {
            this.authService.logout();
          }
        });
      }
    });

    this.appState.isReady$.subscribe(() => {
      let pushNotificationPopin = this.localStorageService.getItem('pushNotificationPopin');
      if (pushNotificationPopin === undefined && this.operatorConfiguration.notificationsConfiguration?.enabled) {
        this.messageService.sendComponentMessage(NotificationPopin).closed.subscribe(() => {
          this.localStorageService.setItem('pushNotificationPopin', true);
        });
      }
      this.notificationService.registerPushInformations();
    });
  }
}
