import { ChangeDetectionStrategy, Component, EventEmitter, Inject, Input, OnInit, Output } from '@angular/core';
import { I18nService } from '@honoregaming/i18n';
import { SelfLimitation } from '../../models/self-limitation.model';
import { OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';

@Component({
  selector: 'hg-responsible-gambling-self-modified-limitation-popin',
  templateUrl: './responsible-gambling-self-modified-limitation-popin.component.html',
  styleUrls: ['./responsible-gambling-self-modified-limitation-popin.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class ResponsibleGamblingSelfModifiedLimitationPopinComponent implements OnInit {
  @Input()
  modifiedLimitation: SelfLimitation;

  @Output()
  close = new EventEmitter();

  text: string;

  constructor(
    private i18nService: I18nService,
    @Inject(operatorConfigurationToken) private operatorConfiguration: OperatorConfiguration
  ) {}

  ngOnInit(): void {
    let amount = null;
    let startDate = new Date(this.modifiedLimitation.startDate);
    let hours = Math.floor((startDate.getTime() - new Date().getTime()) / (1000 * 60 * 60));

    this.i18nService.formatCurrency(this.modifiedLimitation.amount).subscribe(x => {
      amount = x;
    });

    this.i18nService
      .translate(
        'RESPONSIBLE_GAMBLING.SELF_MODIFIED_LIMITATION.TEXT',
        amount + ' ' + this.operatorConfiguration.currency.symbol,
        hours.toString()
      )
      .subscribe(x => {
        this.text = x;
      });
  }

  closePopup() {
    this.close.emit();
  }

  confirm() {
    this.close.emit();
  }
}
