import { HttpClient } from '@angular/common/http';
import { Inject, Injectable } from '@angular/core';
import { globalConfiguration, OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';
import { Scope, scopeToken } from '@honoregaming/core';
import { TableNumbersInput } from '@honoregaming/draw-games-ui';
import { DrawGame, TopEventsByDrawGame } from '@honoregaming/types';
import { BehaviorSubject, Observable, of } from 'rxjs';
import { map } from 'rxjs/operators';

const BORLETTE_TWIN_NUMBERS: string[] = ['00', '11', '22', '33', '44', '55', '66', '77', '88', '99'];
const BORLETTE_POINTE_NUMBERS: TableNumbersInput[] = [
  { key: '0', numbers: ['00', '10', '20', '30', '40', '50', '60', '70', '80', '90'] },
  { key: '1', numbers: ['01', '11', '21', '31', '41', '51', '61', '71', '81', '91'] },
  { key: '2', numbers: ['02', '12', '22', '32', '42', '52', '62', '72', '82', '92'] },
  { key: '3', numbers: ['03', '13', '23', '33', '43', '53', '63', '73', '83', '93'] },
  { key: '4', numbers: ['04', '14', '24', '34', '44', '54', '64', '74', '84', '94'] },
  { key: '5', numbers: ['05', '15', '25', '35', '45', '55', '65', '75', '85', '95'] },
  { key: '6', numbers: ['06', '16', '26', '36', '46', '56', '66', '76', '86', '96'] },
  { key: '7', numbers: ['07', '17', '27', '37', '47', '57', '67', '77', '87', '97'] },
  { key: '8', numbers: ['08', '18', '28', '38', '48', '58', '68', '78', '88', '98'] },
  { key: '9', numbers: ['09', '19', '29', '39', '49', '59', '69', '79', '89', '99'] },
  { key: '10', numbers: ['10', '70', '90'] },
  { key: '11', numbers: ['11', '71', '91'] },
  { key: '12', numbers: ['12', '72', '92'] },
  { key: '13', numbers: ['13', '73', '93'] },
  { key: '14', numbers: ['14', '74', '94'] },
  { key: '15', numbers: ['15', '75', '95'] },
  { key: '16', numbers: ['16', '76', '96'] },
  { key: '17', numbers: ['17', '77', '97'] },
  { key: '18', numbers: ['18', '78', '98'] },
  { key: '19', numbers: ['19', '79', '99'] },
  { key: '20', numbers: ['20', '80'] }
];

@Injectable({
  providedIn: 'root'
})
export class DrawGamesService {
  private nextDrawGamesDatesSubject: BehaviorSubject<Date[] | undefined>;
  $nextDrawGamesDatesEvent: Observable<Date[] | undefined>;

  private nextSingleDrawGameDateSubject: BehaviorSubject<Date | undefined>;
  $nextSingleDrawGameDateEvent: Observable<Date | undefined>;

  constructor(
    @Inject(scopeToken) public userScope: Scope,
    @Inject(operatorConfigurationToken) private operatorConfiguration: OperatorConfiguration,
    private httpClient: HttpClient
  ) {
    this.nextDrawGamesDatesSubject = new BehaviorSubject([]);
    this.$nextDrawGamesDatesEvent = this.nextDrawGamesDatesSubject.asObservable();
    this.nextSingleDrawGameDateSubject = new BehaviorSubject(undefined);
    this.$nextSingleDrawGameDateEvent = this.nextSingleDrawGameDateSubject.asObservable();
  }

  getBorletteTwinNumbers(): string[] {
    return BORLETTE_TWIN_NUMBERS;
  }

  getBorlettePointeNumbers(): Observable<TableNumbersInput[]> {
    return of(this.userScope === Scope.Customer ? BORLETTE_POINTE_NUMBERS.slice(0, 17) : BORLETTE_POINTE_NUMBERS);
  }

  getBorletteTchalaNumbers(): Observable<TableNumbersInput[]> {
    return this.httpClient
      .get(
        (this.userScope === Scope.Customer
          ? `${globalConfiguration.staticAssetsPath}${this.operatorConfiguration.commercialCode}/`
          : `${globalConfiguration.assetsPath}`) + 'tchala/tchala-data.csv',
        { responseType: 'text' }
      )
      .pipe(
        map(data => {
          return data.split(/\r?\n/).map(line => {
            const lineData = line.split(';');
            return { key: lineData[0], numbers: lineData[1].split(',') };
          });
        })
      );
  }
  displayNextDrawGamesDates(nextDates: Date[] | undefined): void {
    this.nextDrawGamesDatesSubject.next(nextDates);
  }
  displayNextSingleDrawGameDate(nextDate: Date | undefined): void {
    this.nextSingleDrawGameDateSubject.next(nextDate);
  }

  filterAndSortDrawGames(drawGames: TopEventsByDrawGame[]): DrawGame[] {
    return drawGames
      .map(dg => dg.events)
      .reduce((prev, next) => prev.concat(next), [])
      .filter(e => e.eventCategoryId === 9001)
      .sort((a, b) => {
        if (a.displayPriority > b.displayPriority) {
          return 1;
        } else if (a.displayPriority < b.displayPriority) {
          return -1;
        }

        if (new Date(a.expectedStart) > new Date(b.expectedStart)) {
          return;
        } else if (new Date(a.expectedStart) < new Date(b.expectedStart)) {
          return -1;
        } else {
          return 0;
        }
      });
  }
}
