import {
  Component,
  ChangeDetectionStrategy,
  Input,
  Inject,
  ElementRef,
  ChangeDetectorRef,
  OnInit,
  Output,
  EventEmitter,
  ViewChild
} from '@angular/core';
import { DestroySubject } from '@honoregaming/core';
import { CountryCode } from '@honoregaming/types';
import { I18nService } from '@honoregaming/i18n';
import { DOCUMENT } from '@angular/common';
import { takeUntil } from 'rxjs/operators';
import { globalConfiguration } from '@honoregaming/configuration';

@Component({
  selector: 'hg-country-list',
  templateUrl: './country-list.component.html',
  styleUrls: ['./country-list.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class CountryListComponent extends DestroySubject implements OnInit {
  @ViewChild('countryList') countryListRef: ElementRef;
  @Input() countries: CountryCode[];
  @Input() placeholder: string;
  @Input() defaultCountryCode: string = null;
  @Output() countryChange = new EventEmitter<string>();

  opened = false;
  currentCountry: CountryCode;
  currentLanguageCode: string;
  defaultLanguageCode: string = 'en';

  private clickListenerFunction: any;
  disabled: boolean;

  constructor(
    @Inject(DOCUMENT) private document: Document,
    private element: ElementRef,
    private cdRef: ChangeDetectorRef,
    private i18nService: I18nService
  ) {
    super();
  }

  ngOnInit(): void {
    if (this.defaultCountryCode == null) {
      this.currentCountry = this.countries[0];
    } else {
      this.currentCountry = this.countries.find(e => e.iso3_code === this.defaultCountryCode);
    }
    this.countryChange.emit(this.currentCountry.iso3_code);

    this.i18nService.languageChanged$.pipe(takeUntil(this.destroy$)).subscribe(l => {
      this.currentLanguageCode = l;
      this.cdRef.markForCheck();
    });
  }

  toggleCountrySelector() {
    this.opened = !this.opened;
    if (this.opened) {
      this.clickListenerFunction = this.closeSelectorOnFocusOut.bind(this);
      setTimeout(() => {
        const selectedEl = this.document.getElementById('country-' + this.currentCountry?.iso3_code);
        const container = this.countryListRef?.nativeElement;

        this.document.addEventListener('click', this.clickListenerFunction);
        if (selectedEl && container) {
          const offsetTop = selectedEl.offsetTop;
          container.scrollTop = offsetTop - container.offsetHeight / 2 + selectedEl.offsetHeight / 2;
        }
      }, 0);
    }
  }

  private closeSelectorOnFocusOut(ev: MouseEvent) {
    if (!(<Node>this.element.nativeElement).contains(<Node>ev.target)) {
      this.opened = false;
      this.document.removeEventListener('click', this.clickListenerFunction);
      this.cdRef.markForCheck();
    }
  }

  getCountryIconUrl(country: CountryCode): string {
    return `${globalConfiguration.flagsBaseUrl}${country.iso2_code.toLowerCase()}.svg`;
  }

  getLabel(country: CountryCode): string {
    if (country.hasOwnProperty(this.currentLanguageCode)) {
      return country[this.currentLanguageCode];
    }
    return country[this.defaultLanguageCode];
  }

  changeCountry(country: CountryCode) {
    this.currentCountry = country;
    this.opened = !this.opened;
    this.countryChange.emit(this.currentCountry.iso3_code);
    this.cdRef.markForCheck();
  }
}
