import { Component, OnInit, ChangeDetectionStrategy, Input } from '@angular/core';
import { I18nService } from '@honoregaming/i18n';

@Component({
  selector: 'hg-toast',
  templateUrl: './toast.component.html',
  styleUrls: ['./toast.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class ToastComponent implements OnInit {
  @Input() content: string;
  @Input() contentParams: string[];

  message: string;

  constructor(private i18nService: I18nService) {}

  ngOnInit(): void {
    this.message = this.contentParams
      ? this.i18nService.translateSync(this.content, ...this.contentParams)
      : this.i18nService.translateSync(this.content);
  }
}
