import { Directive, TemplateRef, ViewContainerRef, OnInit, Input, Inject } from '@angular/core';
import { operatorConfigurationToken, OperatorConfiguration } from '@honoregaming/configuration';

@Directive({
  selector: '[hgIfFeature]'
})
export class IfFeatureDirective implements OnInit {
  @Input('hgIfFeature')
  feature: string;

  constructor(
    private templateRef: TemplateRef<any>,
    private viewContainer: ViewContainerRef,
    @Inject(operatorConfigurationToken) private operatorConfiguration: OperatorConfiguration
  ) {}

  ngOnInit() {
    if (this.operatorConfiguration.operatorFeatures?.indexOf(this.feature) > -1) {
      this.viewContainer.createEmbeddedView(this.templateRef);
    }
  }
}
