import { ITelemetryService } from './telemetry-service.model';
import { Injectable, Inject, PLATFORM_ID } from '@angular/core';

import { DOCUMENT, isPlatformBrowser } from '@angular/common';
import { CustomerOperatorConfiguration, customerOperatorConfigurationToken } from '../../models';
import { PrivacyService } from '../privacy.service';

@Injectable()
export class ClarityTelemetryService implements ITelemetryService {
  isBrowser = isPlatformBrowser(this.platformId);
  configuration = this.operatorConfig.telemetryConfiguration.clarity;

  constructor(
    @Inject(customerOperatorConfigurationToken) private operatorConfig: CustomerOperatorConfiguration,
    @Inject(DOCUMENT) document: Document,
    @Inject(PLATFORM_ID) private platformId,
    private privacyService: PrivacyService
  ) {
    if (!this.isBrowser) {
      return;
    }

    window['clarity'] =
      window['clarity'] ||
      function () {
        (window['clarity'].q = window['clarity'].q || []).push(arguments);
      };

    const script = document.createElement('script');
    script.async = true;
    script.src = 'https://www.clarity.ms/tag/' + this.configuration.clientId;

    let parent = document.getElementsByTagName('script')[0];
    parent.parentNode.insertBefore(script, parent);

    this.privacyService.privacyConfiguration$?.subscribe(x => {
      if (!!x && !x.consents?.analytics) {
        window['clarity']('consentv2', {
          ad_Storage: 'denied',
          analytics_Storage: 'granted'
        });
      }
    });
  }

  trackPageView(_name: string, _path: string): void {}

  trackEvent(_: string, __: any): void {}
}
