import { Component, ChangeDetectionStrategy, Input } from '@angular/core';
import { InstantGameTransaction, InstantGameName, InstantGameProvider } from '@honoregaming/types';

@Component({
  selector: 'hg-instantgame-transaction-result',
  templateUrl: './instantgame-transaction-result.component.html',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class InstantGameTransactionResultComponent {
  @Input() transaction!: InstantGameTransaction;

  InstantGameName = InstantGameName;

  isInsaGameTransaction(): boolean {
    return !(
      this.transaction.provider === InstantGameProvider.EveryMatrix ||
      this.transaction.provider === InstantGameProvider.GameTech ||
      this.transaction.provider === InstantGameProvider.AviatorLlc ||
      this.transaction.provider === InstantGameProvider.BoomingGames
    );
  }
}
