import { Component, ChangeDetectionStrategy, Inject, OnInit } from '@angular/core';
import { TicketStateCheckerMode } from '@honoregaming/configuration';
import { kioskToken } from '@honoregaming/core';
import { CustomerOperatorConfiguration, customerOperatorConfigurationToken } from '@honoregaming/customer-core';

@Component({
  selector: 'hg-bet-code-ticket-tabs',
  templateUrl: './bet-code-ticket-tabs.component.html',
  styleUrls: ['./bet-code-ticket-tabs.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class BetCodeTicketTabsComponent implements OnInit {
  isBetCodeCheckerEnabled: boolean = this.operatorConfiguration.betCodeConfiguration?.isBetCodeCheckerEnabled;
  ticketStateAvailable: boolean =
    this.operatorConfiguration.features.ticketStateCheckerMode !== TicketStateCheckerMode.Disabled;

  selectedTabs: TabsType = TabsType.BetCode;

  TabsType = TabsType;

  constructor(
    @Inject(customerOperatorConfigurationToken) public readonly operatorConfiguration: CustomerOperatorConfiguration,
    @Inject(kioskToken) public readonly isKiosk: boolean
  ) {}

  ngOnInit(): void {
    this.initSelectedTabs();
  }

  selectTabs(type: TabsType): void {
    this.selectedTabs = type;
  }

  private initSelectedTabs(): void {
    this.selectedTabs = !this.isKiosk && this.isBetCodeCheckerEnabled ? TabsType.BetCode : TabsType.Ticket;
  }
}

enum TabsType {
  BetCode,
  Ticket
}
