import { Component, ChangeDetectionStrategy, EventEmitter, Output, HostBinding } from '@angular/core';
import { Router } from '@angular/router';

@Component({
  selector: 'hg-balance-not-enough',
  templateUrl: './balance-not-enough.component.html',
  styleUrls: ['./balance-not-enough.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class BalanceNotEnoughComponent {
  @Output()
  close = new EventEmitter();

  @HostBinding('id') id = 'Error_BalanceNotEnough_Container';

  titleTranslation: string;
  bodyTranslation: string;
  isFreeBet: boolean;

  constructor(private router: Router) {}

  goToDeposit() {
    this.router.navigateByUrl('/myaccount/deposit');
    this.close.emit();
  }
}
