import { Component, ChangeDetectionStrategy, OnInit, HostBinding, ChangeDetectorRef } from '@angular/core';
import { takeUntil, take } from 'rxjs/operators';
import { DestroySubject } from '@honoregaming/core';
import { EventsService } from '@honoregaming/events';

@Component({
  selector: 'hg-sports-pool-next-counter',
  templateUrl: './sports-pool-next-counter.component.html',
  styleUrls: ['./sports-pool-next-counter.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class SportsPoolNextCounterComponent extends DestroySubject implements OnInit {
  public count: number = 0;

  constructor(private readonly eventsService: EventsService, private readonly cdRef: ChangeDetectorRef) {
    super();
  }

  ngOnInit(): void {
    this.fetchSportsPoolNextCount();
  }

  @HostBinding('class.hidden')
  get isHidden(): boolean {
    return this.count === 0;
  }

  private fetchSportsPoolNextCount(): void {
    this.eventsService
      .getSportsPoolNextCount()
      .pipe(takeUntil(this.destroy$), take(1))
      .subscribe(count => {
        this.count = count;
        this.cdRef.markForCheck();
      });
  }
}
