import { Component, OnInit, ChangeDetectionStrategy, Input } from '@angular/core';
import { BetBuilderService } from '@honoregaming/core';
import { ImageInfos } from '@honoregaming/types';

@Component({
  selector: 'hg-bet-builder-icon',
  templateUrl: './bet-builder-icon.component.html',
  styleUrls: ['./bet-builder-icon.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class BetBuilderIconComponent implements OnInit {
  @Input() accentColor: boolean = false;
  @Input() invertedColors: boolean = false;
  @Input() small: boolean = false;

  betBuilderLogo: ImageInfos | undefined;

  constructor(private betBuilderService: BetBuilderService) {}

  ngOnInit(): void {
    this.betBuilderLogo = this.betBuilderService.betBuilderConfiguration?.betBuilderLogo;
  }
}
