import { InjectionToken } from '@angular/core';

export enum TransactionMode {
  Deposit = 'Deposit',
  Withdraw = 'Withdraw'
}

export interface ITransactionPopupService {
  open(mode: TransactionMode): void;
  close(): void;
}

export const transactionPopupServiceToken = new InjectionToken<ITransactionPopupService>('TransactionPopupService');
