import { Pipe, PipeTransform, ChangeDetectorRef, OnDestroy } from '@angular/core';
import { I18nService } from '../services/i18n.service';
import { AsyncPipe } from '@angular/common';
import { Observable } from 'rxjs';
import { getUtcNow, differenceInCalendarDays } from '@honoregaming/core';

@Pipe({
  name: 'hgDate',
  pure: false
})
export class DatePipe implements PipeTransform, OnDestroy {
  async: AsyncPipe;
  previousKey: string;
  previousObservable: Observable<string>;

  constructor(private i18nService: I18nService, private cdRef: ChangeDetectorRef) {
    this.async = new AsyncPipe(this.cdRef);
  }

  transform(key: any): any {
    if (this.previousKey !== key) {
      this.previousKey = key;
      if (differenceInCalendarDays(new Date(key), getUtcNow()) == 0) {
        this.previousObservable = this.i18nService.translate('DATE.TODAY');
      } else if (differenceInCalendarDays(new Date(key), getUtcNow()) == 1) {
        this.previousObservable = this.i18nService.translate('DATE.TOMORROW');
      } else {
        this.previousObservable = this.i18nService.formatDate(key);
      }
    }
    return this.async.transform(this.previousObservable);
  }

  ngOnDestroy(): void {
    this.async.ngOnDestroy();
  }
}
