import { Component, ChangeDetectionStrategy, Input, HostBinding } from '@angular/core';
import { BetState, InstantGameState } from '@honoregaming/types';

@Component({
  selector: 'hg-bet-state',
  templateUrl: './bet-state.component.html',
  styleUrls: ['./bet-state.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class BetStateComponent {
  @Input()
  state: BetState | InstantGameState;

  @HostBinding('class')
  get className() {
    return this.state.toLocaleLowerCase();
  }
}
