import { delayBetween, sub } from '@honoregaming/core';
import { BetLine, FreeBetCoupon, FreeBetCouponBetSlip, FreeBetRuleBettingValidation } from '../models';
import {
  BetCategoryType,
  BetSlipMode,
  isInsaLeaguesEntryPoint,
  FreeBetSortOption,
  FreeBetCouponState
} from '@honoregaming/types';

// toDo:: Think about moving these utils to a coupons service

export function configureFreeBetCouponForBetSlip(freeBetCoupon: FreeBetCoupon): FreeBetCouponBetSlip {
  // Find configured values in BettingRequirements
  const bettingRequirements = freeBetCoupon.freeBetRule.bettingRequirements;
  const couponValidation = {
    ...freeBetCoupon,
    expirationDate: new Date(freeBetCoupon.expirationDate),
    canBeUsed: false,
    useLeftOver: false,
    restrictedToMultiple: false,
    expirationDateIsValid: false,
    balanceIsValid: false,
    bettingRequirementsProgression: 0,
    bettingRequirementsQuantity: 0
  } as FreeBetCouponBetSlip;

  if (!!freeBetCoupon.freeSpinInfos && !bettingRequirements) {
    return couponValidation;
  }

  const bettingValidationSimple = {} as FreeBetRuleBettingValidation;
  const bettingValidationMultiple = {} as FreeBetRuleBettingValidation;

  if (freeBetCoupon.freeBetRule.mustUseAllBalance) {
    bettingValidationSimple.mustUseAllBalanceIsValid = false;
    bettingValidationMultiple.mustUseAllBalanceIsValid = false;
  }

  if (!!bettingRequirements.bettingMinimumNumberOfBetLines && bettingRequirements.bettingMinimumNumberOfBetLines > 1) {
    couponValidation.restrictedToMultiple = true;
  }

  for (const [key, value] of Object.entries(bettingRequirements)) {
    if (value !== undefined) {
      bettingValidationMultiple[`${key}IsValid`] = false;

      if (
        key !== 'bettingMinimumNumberOfBetLines' &&
        key !== 'bettingBetLineMinimalOdds' &&
        key !== 'bettingBetLineMaximalOdds'
      ) {
        bettingValidationSimple[`${key}IsValid`] = false;
      }
    }
  }

  couponValidation.bettingValidationMultiple = bettingValidationMultiple;
  couponValidation.bettingValidationSimple = couponValidation.restrictedToMultiple
    ? ({ bettingMinimumNumberOfBetLinesIsValid: false } as FreeBetRuleBettingValidation)
    : bettingValidationSimple;

  return couponValidation;
}

export function resetFreeBetRuleRequirements(
  coupon: FreeBetCouponBetSlip,
  betSlipMode: BetSlipMode
): FreeBetCouponBetSlip {
  coupon.canBeUsed = false;
  coupon.useLeftOver = false;
  coupon.balanceIsValid = false;
  coupon.expirationDateIsValid = false;
  coupon.bettingRequirementsProgression = 0;
  coupon.bettingRequirementsQuantity =
    betSlipMode === BetSlipMode.Simple
      ? Object.keys(coupon.bettingValidationSimple)?.length ?? 0
      : Object.keys(coupon.bettingValidationMultiple)?.length ?? 0;

  for (const key of Object.keys(coupon.bettingValidationSimple)) {
    coupon.bettingValidationSimple[key] = false;
  }

  for (const key of Object.keys(coupon.bettingValidationMultiple)) {
    coupon.bettingValidationMultiple[key] = false;
  }

  return coupon;
}

export function freeBetCouponIsValidForBetting(
  coupon: FreeBetCoupon | FreeBetCouponBetSlip,
  isBetCompletion: boolean
): boolean {
  const now = new Date();

  if (!isBetCompletion && coupon.state !== FreeBetCouponState.Open) {
    return false;
  }

  if (!isBetCompletion && coupon.balance === 0) {
    return false;
  }

  if (!coupon.bettingAllowed || !coupon.freeBetRule.bettingAllowed) {
    return false;
  }

  if (coupon.expirationDate <= now) {
    return false;
  }

  return true;
}

export function orderFreeBetCoupons(
  coupons: FreeBetCouponBetSlip[],
  sortOption?: FreeBetSortOption
): FreeBetCouponBetSlip[] {
  const now = new Date();
  return coupons.sort((firstCoupon: FreeBetCouponBetSlip, secondCoupon: FreeBetCouponBetSlip) => {
    switch (sortOption) {
      case FreeBetSortOption.Amount:
        return sub(secondCoupon.balance, firstCoupon.balance);
      case FreeBetSortOption.Expiration:
        return compareCouponsExpiration(firstCoupon, secondCoupon, now);
      default:
        return secondCoupon.id - firstCoupon.id;
    }
  });
}

export function compareCouponsExpiration(firstCoupon: FreeBetCoupon, secondCoupon: FreeBetCoupon, now: Date): number {
  if (secondCoupon.state !== FreeBetCouponState.Open && firstCoupon.state === FreeBetCouponState.Open) {
    return -1;
  }
  if (secondCoupon.state === FreeBetCouponState.Open && firstCoupon.state !== FreeBetCouponState.Open) {
    return 1;
  }

  if (secondCoupon.expirationDate <= now && firstCoupon.expirationDate > now) {
    return -1;
  }
  if (secondCoupon.expirationDate > now && firstCoupon.expirationDate <= now) {
    return 1;
  }
  return delayBetween(secondCoupon.expirationDate, firstCoupon.expirationDate);
}

export function orderFreeBetCouponsForBetSlip(coupons: FreeBetCouponBetSlip[]): FreeBetCouponBetSlip[] {
  if (!coupons || coupons?.length == 0) {
    return [];
  }

  // copy in order to avoid mutating original array
  return [...coupons].sort((x: FreeBetCouponBetSlip, y: FreeBetCouponBetSlip) => {
    if (x.isBetCompletion) {
      return -1;
    }
    if (y.isBetCompletion) {
      return 1;
    }
    const delay: number = delayBetween(y.expirationDate, x.expirationDate);
    if (delay !== 0) {
      return delay;
    }
    return x.id - y.id;
  });
}

export function getMaxEventStartDate(betLines: BetLine[]) {
  const betLinesEventDate = betLines.map(l => {
    let expectedStart: Date = new Date();

    if (!!l.eventDate) {
      expectedStart = new Date(l.eventDate);
    } else if (l.betCategoryType === BetCategoryType.VirtualFixedOdds && isInsaLeaguesEntryPoint(l.entryPointId)) {
      // Hack : InsaLeagues don't have eventDate
      expectedStart = new Date();
    } else if (!!l.manualOddsBoost) {
      expectedStart = new Date(l.manualOddsBoost.expirationDate.toString());
    } else if (!!l.oddsBoost) {
      expectedStart = !!l.oddsBoost['nextEventDate'] ? new Date(l.oddsBoost['nextEventDate']) : new Date();
    }

    return expectedStart.getTime();
  });

  return new Date(Math.max(...betLinesEventDate));
}
