import { ChangeDetectionStrategy, Component, Inject, Input, OnInit } from '@angular/core';

import { Bonus, OperatorConfiguration, operatorConfigurationToken, PaymentTax } from '@honoregaming/configuration';
import { CurrencyMathMixin, DestroySubject } from '@honoregaming/core';
import { BetSystemHistory, BetState } from '@honoregaming/types';

@Component({
  selector: 'hg-bet-system-footer',
  templateUrl: './bet-system-footer.component.html',
  styleUrls: ['./bet-system-footer.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class BetSystemFooterComponent extends CurrencyMathMixin(DestroySubject) implements OnInit {
  @Input() betSystem!: BetSystemHistory;
  @Input() totalOdds?: string;

  BetState = BetState;
  shouldDisplayPaymentTax: boolean = false;
  hasReachedMaxMultipleBonus: boolean = false;
  showTaxInformations: boolean = false;
  useAlternativeDisplayForTax: boolean = this.operatorConfiguration.onlineConfiguration?.useAlternativeDisplayForTax;

  constructor(@Inject(operatorConfigurationToken) private readonly operatorConfiguration: OperatorConfiguration) {
    super();
  }

  ngOnInit(): void {
    this.shouldDisplayPaymentTax =
      this.operatorConfiguration.paymentTaxes?.some(
        (paymentTax: PaymentTax) =>
          paymentTax.showTaxDetail && paymentTax.betCategory && this.betSystem.betCategory === paymentTax.betCategory
      ) ?? false;

    this.hasReachedMaxMultipleBonus = this.computeHasReachedMaxMultipleBonus();
  }

  get paymentTaxRate(): number {
    const paymentTax: PaymentTax = this.operatorConfiguration.paymentTaxes?.find(
      (tax: PaymentTax) => tax.betCategory && this.betSystem.betCategory === tax.betCategory
    );
    return (paymentTax?.rate ?? 0) * 100;
  }

  get earningWithTax(): number {
    const earningBeforeTax: number = this.add(this.betSystem.earning, this.betSystem.paymentTaxAmount);

    // The earning includes the multiple bonus server-side, but the bonus is shown on its own line
    // (like the bet slip max payout, which excludes it), so we subtract it
    return this.betSystem.multipleBonusAmount
      ? this.sub(earningBeforeTax, this.betSystem.multipleBonusAmount)
      : earningBeforeTax;
  }

  displayTaxInformations(): void {
    this.showTaxInformations = !this.showTaxInformations;
  }

  private computeHasReachedMaxMultipleBonus(): boolean {
    const bonuses: Bonus[] = this.operatorConfiguration.multipleBonus?.bonus;

    if (!this.betSystem.multipleBonusCoefficient || !this.betSystem.multipleBonusAmount || !bonuses?.length) {
      return false;
    }

    const maxCoefficient: number = (Math.max(...bonuses.map(bonus => bonus.coefficient)) - 1) * 100;
    return Math.abs(maxCoefficient - this.betSystem.multipleBonusCoefficient) < 0.01;
  }
}
