import { ContentService } from '../../../../../../core/hg-templating/src/lib/services/content.service';
import { Component, OnInit, ChangeDetectionStrategy, ChangeDetectorRef, Inject } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { I18nService } from '@honoregaming/i18n';
import { Async, AsyncTrigger, DestroySubject } from '@honoregaming/core';
import { skip, takeUntil } from 'rxjs/operators';
import { merge } from 'rxjs';
import { CustomerOperatorConfiguration, customerOperatorConfigurationToken } from '@honoregaming/customer-core';

@Component({
  selector: 'hg-content-page',
  templateUrl: './content-page.component.html',
  styleUrls: ['./content-page.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class ContentPageComponent extends DestroySubject implements OnInit {
  content: string;
  title: string;
  style: string;
  contentKey: string;
  includeAllPromotions: boolean;
  showTableContents = false;
  generalItems: { link: string; translationKey: string; order?: number; imageUrl?: string; cssClassName?: string }[];

  @AsyncTrigger()
  languageTrigger = this.i18nService.languageChanged$;

  constructor(
    private route: ActivatedRoute,
    private contentService: ContentService,
    private cdRef: ChangeDetectorRef,
    private i18nService: I18nService,
    @Inject(customerOperatorConfigurationToken) private customerOperatorConfiguration: CustomerOperatorConfiguration
  ) {
    super();
  }

  ngOnInit() {
    this.generalItems = this.customerOperatorConfiguration.customization?.footer?.general;
    let internalLinks = this.generalItems?.map(t => t.link);

    this.route.params.subscribe(param => {
      if (param.path) {
        this.contentKey = param.path;

        this.includeAllPromotions = this.route.snapshot.data.includeAllPromotions;
        if (
          this.contentKey == 'about' ||
          this.contentKey == 'rules' ||
          this.contentKey == 'help' ||
          this.contentKey == 'play-responsibly' ||
          this.contentKey == 'horseracing-rules' ||
          this.contentKey == 'sports-betting-rules' ||
          this.contentKey == 'drawgames-rules' ||
          this.contentKey == 'virtual-rules'
        ) {
          this.showTableContents = true;
        }

        internalLinks?.forEach(t => {
          if ('/about/content/' + this.contentKey === t) {
            this.showTableContents = true;
          }
        });

        this.generalItems?.forEach(t => {
          if ('/about/content/' + this.contentKey === t.link) {
            this.showTableContents = true;
          }
        });

        this.loadContent();
        this.cdRef.markForCheck();
      }
    });
  }

  @Async()
  loadContent() {
    this.contentService
      .getContent(this.contentKey)
      .pipe(
        takeUntil(
          merge(this.destroy$, this.route.params.pipe(skip(1)), this.i18nService.languageChanged$.pipe(skip(1)))
        )
      )
      .subscribe(resource => {
        this.content = resource.content;
        this.style = resource.style;
        this.title = resource.title;

        this.cdRef.markForCheck();
      });
  }
}
