import { ChangeDetectionStrategy, Component, OnInit } from '@angular/core';
import { LocalStorageService } from '@honoregaming/core';
import { DirectMessageWidgetState } from 'projects/customer/hg-direct-message/src/lib/enums/direct-message-widget-view.enum';

@Component({
  selector: 'hg-direct-message-container',
  templateUrl: './direct-message.component.html',
  styleUrls: ['./direct-message.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class DirectMessageComponent implements OnInit {
  readonly LOCAL_STORAGE_KEY: string = 'direct_message:widget:state';

  constructor(private readonly localStorage: LocalStorageService) {}

  ngOnInit(): void {
    this.localStorage.setItem(this.LOCAL_STORAGE_KEY, DirectMessageWidgetState.Reduce);
  }
}
