import { Component, ChangeDetectionStrategy, ChangeDetectorRef, Inject } from '@angular/core';
import { TicketHistory } from '@honoregaming/types';
import { DestroySubject, IScannerService, kioskToken, natifToken, scannerServiceToken } from '@honoregaming/core';
import { TicketService } from '@honoregaming/customer-core';
import { finalize, takeUntil } from 'rxjs/operators';
import { TicketStateComponent } from '../ticket-state/ticket-state.component';
import { MessageService } from '@honoregaming/ui';

@Component({
  selector: 'hg-ticket-state-checker',
  templateUrl: './ticket-state-checker.component.html',
  styleUrls: ['./ticket-state-checker.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class TicketStateCheckerComponent extends DestroySubject {
  ticketNumber: string;
  pinCode: string;
  ticket: TicketHistory;
  component: { component: any; props: any };

  loading = false;
  notFound = false;
  error = false;
  loadingState: 'loaded' | 'searchLoading' | 'scanLoading' = 'loaded';

  constructor(
    private ticketService: TicketService,
    private cdRef: ChangeDetectorRef,
    @Inject(kioskToken) public isKiosk: boolean,
    @Inject(scannerServiceToken) private scannerService: IScannerService,
    @Inject(natifToken) public isNatif: boolean,
    private messageService: MessageService
  ) {
    super();
  }

  displayScan = this.isNatif;

  submit() {
    if (!this.ticketNumber || !this.pinCode || this.loading) {
      return;
    }

    this.loading = true;
    this.error = false;
    this.notFound = false;
    this.ticket = undefined;

    this.getTicket();
  }

  scanTicket(): void {
    this.loadingState = 'scanLoading';
    this.cdRef.markForCheck();

    this.scannerService.scan().subscribe(ticketNumber => {
      window.screen.orientation.lock('portrait-primary');

      if (ticketNumber) {
        if (ticketNumber.length === 20) {
          ticketNumber = ticketNumber.substring(0, 19);
        }

        this.splitTicketNumber(ticketNumber);
        this.cdRef.markForCheck();

        this.getTicket();
      } else {
        this.loadingState = 'loaded';
        this.cdRef.markForCheck();
      }
    });
  }

  getTicket() {
    if (this.loadingState === 'searchLoading') {
      return;
    }

    this.loadingState = 'searchLoading';
    this.ticketService
      .getTicketState(this.ticketNumber, this.pinCode)
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.loading = false;
          this.loadingState = 'loaded';
          this.cdRef.markForCheck();
        })
      )
      .subscribe(
        ticket => {
          if (!ticket) {
            this.notFound = true;
            return;
          }

          this.ticket = ticket;

          this.messageService.sendComponentMessage(TicketStateComponent, {
            ticketNumber: this.ticketNumber,
            ticket: this.ticket
          });
        },
        _err => {
          this.error = true;
        }
      );
  }

  private splitTicketNumber(value: string): void {
    const ticketNumber = value.substring(0, 16);
    const ticketPin = value.substring(16);

    this.ticketNumber = ticketNumber;
    this.pinCode = ticketPin;
  }
}
