import { BetSlipMode } from '@honoregaming/types';
import { div, sub } from '@honoregaming/core';
import { Amounts, BetLine, FreeBetCouponBetSlip } from '../models';
import { freeBetCouponIsValidForBetting, getMaxEventStartDate, resetFreeBetRuleRequirements } from '../utils';

export function validateFreeBetRule(
  coupon: FreeBetCouponBetSlip,
  betSlipMode: BetSlipMode,
  amounts: Amounts,
  betLines: BetLine[] = [],
  leftOverActive: boolean,
  multiCouponActive: boolean,
  isBetCompletion: boolean
): FreeBetCouponBetSlip {
  coupon = resetFreeBetRuleRequirements(coupon, betSlipMode);
  coupon.isBetCompletion = isBetCompletion;
  if (
    betLines.length > 0 &&
    freeBetCouponIsValidForBetting(coupon, isBetCompletion) &&
    betSlipMode !== BetSlipMode.Systems
  ) {
    const lastExpectedStart = getMaxEventStartDate(betLines);
    const maxBaseAmount = Math.max(...betLines.map(l => l.baseAmount));

    // MinAmount is also used to check for Leftover compatibility
    const minAmount = coupon.freeBetRule.bettingRequirements.bettingMinimalAmount ?? 0;

    // expirationDateIsValid
    if (multiCouponActive && !!coupon.expirationDate && lastExpectedStart <= new Date(coupon.expirationDate)) {
      coupon.expirationDateIsValid = true;
    }

    // balanceIsValid
    if (
      amounts.summary.totalStakeWithTax <= coupon.balance &&
      maxBaseAmount <= coupon.balance &&
      minAmount <= coupon.balance
    ) {
      coupon.useLeftOver = false;
      coupon.balanceIsValid = true;
    }
    // canUseLeftOver
    else if (
      leftOverActive &&
      (betSlipMode === BetSlipMode.Multiple || betLines.length === 1) &&
      (coupon.balance < maxBaseAmount || (!!minAmount && coupon.balance < minAmount))
    ) {
      coupon.useLeftOver = true;
      coupon.balanceIsValid = true;
    }

    // Balance is always valid during bet completion
    if (!coupon.balanceIsValid && isBetCompletion) {
      coupon.balanceIsValid = true;
    }

    if (coupon.bettingRequirementsQuantity > 0) {
      if (betSlipMode === BetSlipMode.Simple && !coupon.restrictedToMultiple) {
        coupon = validateFreeBetRuleSimple(coupon, amounts, betLines);
        coupon.bettingRequirementsProgression = Object.values(coupon.bettingValidationSimple).filter(x => x).length;
      } else if (betSlipMode === BetSlipMode.Multiple) {
        coupon = validateFreeBetRuleMultiple(coupon, amounts, betLines);
        coupon.bettingRequirementsProgression = Object.values(coupon.bettingValidationMultiple).filter(x => x).length;
      }
    }

    // Additional requirement : Expiration date should be valid when multi coupons is activated
    if (multiCouponActive) {
      coupon.bettingRequirementsQuantity++;
      if (coupon.expirationDateIsValid) {
        coupon.bettingRequirementsProgression++;
      }
    }

    coupon.canBeUsed =
      coupon.balanceIsValid &&
      (!multiCouponActive || coupon.expirationDateIsValid) &&
      coupon.bettingRequirementsProgression === coupon.bettingRequirementsQuantity &&
      !(coupon.restrictedToMultiple && betSlipMode === BetSlipMode.Simple);

    if (!coupon.balanceIsValid) {
      coupon.bettingRequirementsQuantity++;
    }
  }

  // Create new reference to ensure that changes will be correctly detected
  return { ...coupon };
}

export function validateFreeBetRuleSimple(
  coupon: FreeBetCouponBetSlip,
  amounts: Amounts,
  betLines: BetLine[]
): FreeBetCouponBetSlip {
  const bettingRequirements = coupon.freeBetRule.bettingRequirements;
  const betLinesSimple = betLines.filter(x => !x.combinations?.length);
  const betLinesCombination = betLines.filter(x => x.combinations?.length);

  const betLinesOdds: number[] = [
    ...betLinesSimple.map(x => x.odds),
    ...betLinesCombination.reduce((res, betline) => [...res, ...betline.combinations.map(x => x.fixedOdds)], [])
  ];

  const maxOdds = Math.max(...betLinesOdds);
  const minOdds = Math.min(...betLinesOdds);

  // mustUseAllBalanceIsValid => should have only one betline in betslip
  if (coupon.freeBetRule.mustUseAllBalance && betLines.length === 1) {
    const betline = betLines[0];

    if (betline.maximumAmount >= coupon.balance) {
      if (!bettingRequirements.bettingMaximalPayout) {
        coupon.bettingValidationSimple.mustUseAllBalanceIsValid = true;
      } else {
        const isCombination = !!betline.combinations?.length;

        if (
          isCombination &&
          div(coupon.balance, betline.combinations.length) * maxOdds <= bettingRequirements.bettingMaximalPayout
        ) {
          coupon.bettingValidationSimple.mustUseAllBalanceIsValid = true;
        } else if (
          !isCombination &&
          sub(coupon.balance * maxOdds, coupon.balance) <= bettingRequirements.bettingMaximalPayout
        ) {
          coupon.bettingValidationSimple.mustUseAllBalanceIsValid = true;
        }
      }
    }
  }

  // bettingMaximalPayoutIsValid
  if (
    bettingRequirements.bettingMaximalPayout > 0 &&
    amounts.values.every(x => x.payout <= bettingRequirements.bettingMaximalPayout)
  ) {
    coupon.bettingValidationSimple.bettingMaximalPayoutIsValid = true;
  }

  // bettingMinimalAmountIsValid
  if (
    bettingRequirements.bettingMinimalAmount > 0 &&
    (coupon.useLeftOver || amounts.values.every(x => x.amount >= bettingRequirements.bettingMinimalAmount))
  ) {
    coupon.bettingValidationSimple.bettingMinimalAmountIsValid = true;
  }

  // bettingMaximalAmountIsValid
  if (
    bettingRequirements.bettingMaximalAmount > 0 &&
    amounts.values.every(x => x.amount <= bettingRequirements.bettingMaximalAmount)
  ) {
    coupon.bettingValidationSimple.bettingMaximalAmountIsValid = true;
  }
  // bettingMinimalOddsIsValid
  if (bettingRequirements.bettingMinimalOdds > 0 && minOdds >= bettingRequirements.bettingMinimalOdds) {
    coupon.bettingValidationSimple.bettingMinimalOddsIsValid = true;
  }
  // bettingMaximalOddsIsValid
  if (bettingRequirements.bettingMaximalOdds > 0 && maxOdds <= bettingRequirements.bettingMaximalOdds) {
    coupon.bettingValidationSimple.bettingMaximalOddsIsValid = true;
  }

  return coupon;
}

export function validateFreeBetRuleMultiple(
  coupon: FreeBetCouponBetSlip,
  amounts: Amounts,
  betLines: BetLine[]
): FreeBetCouponBetSlip {
  const bettingRequirements = coupon.freeBetRule.bettingRequirements;

  const totalOdds = betLines.reduce((sum, l) => sum * l.odds, 1);
  const maximalAmountFloor = Math.min(...betLines.map(l => l.maximumAmount));

  // mustUseAllBalanceIsValid
  if (coupon.freeBetRule.mustUseAllBalance && maximalAmountFloor >= coupon.balance) {
    if (
      bettingRequirements.bettingMaximalPayout > 0 &&
      sub(coupon.balance * totalOdds, coupon.balance) <= bettingRequirements.bettingMaximalPayout
    ) {
      coupon.bettingValidationMultiple.mustUseAllBalanceIsValid = true;
    } else if (!bettingRequirements.bettingMaximalPayout) {
      coupon.bettingValidationMultiple.mustUseAllBalanceIsValid = true;
    }
  }

  // bettingMaximalPayoutIsValid
  if (
    bettingRequirements.bettingMaximalPayout > 0 &&
    amounts.summary.maxPayout <= bettingRequirements.bettingMaximalPayout
  ) {
    coupon.bettingValidationMultiple.bettingMaximalPayoutIsValid = true;
  }

  // bettingMinimalAmountIsValid
  if (
    bettingRequirements.bettingMinimalAmount > 0 &&
    (coupon.useLeftOver || amounts.summary.totalStakeWithTax >= bettingRequirements.bettingMinimalAmount)
  ) {
    coupon.bettingValidationMultiple.bettingMinimalAmountIsValid = true;
  }

  // bettingMaximalAmountIsValid
  if (
    bettingRequirements.bettingMaximalAmount > 0 &&
    amounts.summary.totalStakeWithTax <= bettingRequirements.bettingMaximalAmount
  ) {
    coupon.bettingValidationMultiple.bettingMaximalAmountIsValid = true;
  }

  // bettingMinimalOddsIsValid
  if (bettingRequirements.bettingMinimalOdds > 0 && totalOdds >= bettingRequirements.bettingMinimalOdds) {
    coupon.bettingValidationMultiple.bettingMinimalOddsIsValid = true;
  }

  // bettingMaximalOddsIsValid
  if (bettingRequirements.bettingMaximalOdds > 0 && totalOdds <= bettingRequirements.bettingMaximalOdds) {
    coupon.bettingValidationMultiple.bettingMaximalOddsIsValid = true;
  }

  // bettingMinimumNumberOfBetLinesIsValid
  if (
    bettingRequirements.bettingMinimumNumberOfBetLines > 0 &&
    betLines.length >= bettingRequirements.bettingMinimumNumberOfBetLines
  ) {
    coupon.bettingValidationMultiple.bettingMinimumNumberOfBetLinesIsValid = true;
  }

  // bettingBetLineMinimalOddsIsValid
  if (
    bettingRequirements.bettingBetLineMinimalOdds > 0 &&
    betLines.every(x => x.odds >= bettingRequirements.bettingBetLineMinimalOdds)
  ) {
    coupon.bettingValidationMultiple.bettingBetLineMinimalOddsIsValid = true;
  }

  // bettingBetLineMaximalOddsIsValid
  if (
    bettingRequirements.bettingBetLineMaximalOdds > 0 &&
    betLines.every(x => x.odds <= bettingRequirements.bettingBetLineMaximalOdds)
  ) {
    coupon.bettingValidationMultiple.bettingBetLineMaximalOddsIsValid = true;
  }

  return coupon;
}
