import { Injectable } from '@angular/core';
import { ActivatedRouteSnapshot } from '@angular/router';
import { BehaviorSubject, Observable } from 'rxjs';

@Injectable({
  providedIn: 'root'
})
export class MainRouterEventBroadcasterService {
  private snapshotsSubject: BehaviorSubject<ActivatedRouteSnapshot> = new BehaviorSubject(null);
  $snapshots: Observable<ActivatedRouteSnapshot> = this.snapshotsSubject.asObservable();

  public broadcastNewActivatedRouteSnapshot(snapshot: ActivatedRouteSnapshot) {
    this.snapshotsSubject.next(snapshot);
  }
}
