import { Inject, Injectable } from '@angular/core';
import { BetBuilderError, BetBuilderInfo, BetBuilderLine, defaultProductName, Images } from '@honoregaming/types';
import {
  BetBuilderConfiguration,
  OperatorConfiguration,
  operatorConfigurationToken
} from '@honoregaming/configuration';
import { LocalStorageService } from '@honoregaming/core';
import { BetLine } from '@honoregaming/betslip';
import { BehaviorSubject } from 'rxjs';

@Injectable({
  providedIn: 'root'
})
export class BetBuilderService {
  private storageKey = 'bet-builder';
  private betBuilderBetLinesByMatchId = new Map<number, BetLine>();
  private betBuilderInfoSubject$ = new BehaviorSubject<BetBuilderInfo>({});

  constructor(
    private readonly localStorageService: LocalStorageService,
    @Inject(operatorConfigurationToken) private operatorConfiguration: OperatorConfiguration
  ) {
    const storedBetBuilderInfo: BetBuilderInfo | undefined = this.getStoredBetBuilderInfo();
    if (storedBetBuilderInfo) {
      this.betBuilderInfoSubject$.next(storedBetBuilderInfo);
    }
  }

  get betBuilderConfiguration(): BetBuilderConfiguration | undefined {
    return this.operatorConfiguration.betBuilderConfiguration;
  }

  get productName(): string {
    return this.betBuilderConfiguration?.productName ?? defaultProductName;
  }

  get bannerImages(): Images | undefined {
    if (this.betBuilderConfiguration?.enableTutorial) {
      return this.betBuilderConfiguration.bannerImages;
    }
  }

  get betBuilderInfo(): BetBuilderInfo | undefined {
    return this.betBuilderInfoSubject$.value;
  }

  get betBuilderBetLines(): BetLine[] {
    return Array.from(this.betBuilderBetLinesByMatchId.values());
  }

  get isBetBuilderToggled(): boolean {
    return this.betBuilderInfoSubject$.value.isBetBuilderToggled ?? false;
  }

  get hasBetBuilderBetLines(): boolean {
    return !!this.betBuilderBetLinesByMatchId.size;
  }

  get hasBetBuilderErrors(): boolean {
    return this.betBuilderBetLines.some((line: BetLine) =>
      line.betBuilderLines.some((betBuilderLine: BetBuilderLine) => !!betBuilderLine.betBuilderError)
    );
  }

  get isFreebetAllowed(): boolean {
    const betBuilderConfiguration: BetBuilderConfiguration | undefined = this.betBuilderConfiguration;
    return (
      (betBuilderConfiguration &&
        betBuilderConfiguration.allowBetBuilder &&
        betBuilderConfiguration.authorizeFreebetCoupons) ??
      false
    );
  }

  get maxItemsCount(): number | undefined {
    const betBuilderConfiguration: BetBuilderConfiguration | undefined = this.betBuilderConfiguration;
    return betBuilderConfiguration?.maximumItemsCount;
  }

  get maxScorersCount(): number | undefined {
    const betBuilderConfiguration: BetBuilderConfiguration | undefined = this.betBuilderConfiguration;
    return betBuilderConfiguration?.maximumGoalScorersCount;
  }

  get maxBetBuildersCount(): number | undefined {
    const betBuilderConfiguration: BetBuilderConfiguration | undefined = this.betBuilderConfiguration;
    return betBuilderConfiguration?.maximumBetBuildersCount ?? 0;
  }

  get minValidOdds(): number {
    const betBuilderConfiguration: BetBuilderConfiguration | undefined = this.betBuilderConfiguration;
    return betBuilderConfiguration?.minimumItemOdds ?? 0;
  }

  getErrorParameter(betBuilderError?: BetBuilderError): number | undefined {
    switch (betBuilderError) {
      case BetBuilderError.MaximumItemsCount:
        return this.maxItemsCount;
      case BetBuilderError.MaximumGoalScorersCount:
        return this.maxScorersCount;
      case BetBuilderError.MaximumBetBuilderCount:
        return this.maxBetBuildersCount;
      case BetBuilderError.OddsTooLow:
        return this.minValidOdds;
      default:
        return;
    }
  }

  getMatchBetBuilderBetLine(matchId: number): BetLine | undefined {
    return this.betBuilderBetLinesByMatchId.get(matchId);
  }

  setBetBuilderBetLines(betLines: BetLine[]): void {
    this.betBuilderBetLinesByMatchId = new Map<number, BetLine>();
    betLines.forEach((betLine: BetLine) => {
      if (betLine.isBetBuilder) {
        this.setBetBuilderBetLine(betLine.eventId, betLine);
      }
    });
  }

  toggleBetBuilder(isBetBuilderToggled: boolean): void {
    this.setBetBuilderInfo({ ...this.betBuilderInfo, isBetBuilderToggled });
  }

  shouldDisplayBetBuilderTutorial(): boolean {
    return (
      this.betBuilderConfiguration?.allowBetBuilder &&
      this.betBuilderConfiguration?.enableTutorial &&
      !this.betBuilderInfo?.tutorialCompleted
    );
  }

  validateBetBuilderTutorial(): void {
    this.setBetBuilderInfo({ ...this.betBuilderInfo, tutorialCompleted: true });
  }

  deleteBetBuilderLine(matchId: number, eventBetTypeItemId: number): BetLine | null {
    const existingBetLine: BetLine | undefined = this.getMatchBetBuilderBetLine(matchId);
    if (!existingBetLine) {
      return null;
    }
    return {
      ...existingBetLine,
      betBuilderLines: existingBetLine.betBuilderLines.filter(
        (existingBetBuilderLine: BetBuilderLine) => existingBetBuilderLine.eventBetTypeItemId !== eventBetTypeItemId
      )
    };
  }

  private getStoredBetBuilderInfo(): BetBuilderInfo | undefined {
    return this.localStorageService.getItem(this.storageKey);
  }

  private setBetBuilderInfo(betBuilderInfo: BetBuilderInfo): void {
    this.betBuilderInfoSubject$.next(betBuilderInfo);
    this.localStorageService.setItem(this.storageKey, betBuilderInfo);
  }

  private setBetBuilderBetLine(matchId: number, betLine: BetLine): void {
    this.betBuilderBetLinesByMatchId.set(matchId, betLine);
  }
}
