import {
  Component,
  OnInit,
  forwardRef,
  Input,
  HostListener,
  ElementRef,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Inject
} from '@angular/core';
import { ControlValueAccessor, NG_VALUE_ACCESSOR } from '@angular/forms';
import {
  addMonths,
  setDate,
  daysInMonth,
  getDayOfWeekOffset,
  isSameDate,
  getDayOfYear,
  isSameDay,
  startOfDay
} from '@honoregaming/core';
import { I18nService } from '@honoregaming/i18n';
import { combineLatest } from 'rxjs';
import { DOCUMENT, AsyncPipe } from '@angular/common';

@Component({
  selector: 'hg-datepicker',
  templateUrl: './datepicker.component.html',
  styleUrls: ['./datepicker.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => DatepickerComponent),
      multi: true
    }
  ]
})
export class DatepickerComponent implements ControlValueAccessor, OnInit {
  @Input() showInput = true;

  weekDays: string[];
  calendarDate: Date;
  monthName: string;
  year: number;
  daysInMonth: Date[];
  dayOfWeekOffset: number[];
  showInputDatepicker = false;

  private _value: Date | [Date, Date];
  monthNames: string[];

  async: AsyncPipe;

  get value() {
    return this._value;
  }

  set value(val) {
    this._value = val;
    this.onChange(val);
    this.onTouched();
  }

  onChange = (_value: Date | [Date, Date]) => {};
  onTouched = () => {};

  @HostListener('document:click', ['$event'])
  handleClick(event: MouseEvent) {
    if (!this.elementRef.nativeElement.contains(event.target)) {
      this.showInputDatepicker = false;
    }
  }

  registerOnChange(fn: (value: Date) => void) {
    this.onChange = fn;
  }

  registerOnTouched(fn: () => void) {
    this.onTouched = fn;
  }

  writeValue(value: Date) {
    this.value = value;
    this.cdRef.markForCheck();
  }

  constructor(
    @Inject(DOCUMENT) private document,
    private elementRef: ElementRef,
    private i18Service: I18nService,
    private cdRef: ChangeDetectorRef
  ) {
    this.async = new AsyncPipe(this.cdRef);
  }

  ngOnInit() {
    combineLatest([this.i18Service.getMonthsNames(), this.i18Service.getWeekDaysNames()]).subscribe(
      ([months, days]) => {
        this.monthNames = months;
        this.weekDays = days.map(x => x[0]);
        this.setCalendarDate(startOfDay(new Date()));
        this.cdRef.markForCheck();
      }
    );
  }

  prev() {
    this.setCalendarDate(addMonths(this.calendarDate, -1));
  }

  next() {
    this.setCalendarDate(addMonths(this.calendarDate, 1));
  }

  clear() {
    this.value = undefined;
  }

  setCalendarDate(date: Date) {
    this.calendarDate = date;
    this.monthName = this.monthNames[this.calendarDate.getMonth()];
    this.year = this.calendarDate.getFullYear();
    this.daysInMonth = daysInMonth(this.calendarDate);
    this.dayOfWeekOffset = getDayOfWeekOffset(this.calendarDate);
  }

  setDay(dayOfMonth: Date) {
    const value = this.value as Date;
    const dayIsSameDayOfYear =
      this.value && getDayOfYear(value) === getDayOfYear(setDate(this.calendarDate, dayOfMonth.getDate()));
    this.value = !dayIsSameDayOfYear ? setDate(this.calendarDate, dayOfMonth.getDate()) : undefined;
    this.showInputDatepicker = false;
  }

  getDayClass(day: Date) {
    const cssClasses = [];

    if (isSameDay(day, new Date())) {
      cssClasses.push('today');
    }

    if (isSameDate(day, this.value as Date)) {
      cssClasses.push('selected-date');
    }
    return cssClasses;
  }

  dateToReadableString(value: Date) {
    if (!value) {
      return null;
    }
    return this.i18Service.formatDate(value.toString());
  }

  show() {
    this.showInputDatepicker = true;
    // Negative margin to avoid beeing out of screen
    setTimeout(() => {
      const datePicker = this.elementRef.nativeElement.querySelector('.datepicker') as HTMLElement;
      const offset = this.document.body.clientWidth - datePicker.getClientRects().item(0).right;
      if (offset < 0) {
        datePicker.style.marginLeft = offset + 'px';
      }
    });
  }
}
