import { Inject, Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';
import { globalConfiguration, OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';
import { Content } from '@honoregaming/types';
import { I18nService } from '@honoregaming/i18n';
import { QueryBuilderService } from 'projects/core/hg-core/src/lib/services/query-builder.service';

@Injectable({ providedIn: 'root' })
export class ContentService {
  constructor(
    private httpClient: HttpClient,
    @Inject(operatorConfigurationToken) private operatorConfiguration: OperatorConfiguration,
    private i18nService: I18nService,
    private queryBuilderService: QueryBuilderService
  ) {}

  getContent(key: string, languageCode: string = null): Observable<{ content: string; title: string; style: string }> {
    var queryString = this.queryBuilderService.buildHttpParams({ languageCode });

    return this.httpClient.get<{ content: string; title: string; style: string }>(
      globalConfiguration.apiBaseUrl + `operatordata/content/${key}`,
      { params: queryString }
    );
  }

  getFaqContents(): Observable<Content[]> {
    return this.httpClient.get<Content[]>(
      `${globalConfiguration.staticAssetsPath}${this.operatorConfiguration.commercialCode}/faq/${this.i18nService.currentLanguageCode}.json`
    );
  }
}
