import { Component, OnInit, ChangeDetectionStrategy, ChangeDetectorRef, Inject } from '@angular/core';
import { take, takeUntil } from 'rxjs/operators';
import { Feature } from '@honoregaming/configuration';
import { roundNumber, add, DestroySubject } from '@honoregaming/core';
import { CustomerOperatorConfiguration, customerOperatorConfigurationToken } from '@honoregaming/customer-core';
import { I18nService } from '@honoregaming/i18n';
import { BetCategoryType } from '@honoregaming/types';
import { ToasterService } from '@honoregaming/ui';
import { AccountService } from '../../services/account.service';
import { Operation, OperationDetail, OperationType, StatusDetail, OperationStatus } from '../../models/operation.model';
import { AccountFilter, SelectValue } from '../../models/account-filters.model';

interface OperationView {
  data: Operation;
  viewKey: string;
  showCashAmount: boolean;
  showFreeAmount: boolean;
  splitLabel: string | null;
  isBatchLabel: boolean;
  typeLabelKey: string;
  statusClass: string;
  statusIcon: string;
  statusKey: string;
  taxLabelKey: string | null;
  taxTotal: number | null;
  hasFooter: boolean;
  showInfoIcon: boolean;
  copyValue: string | null;
  isBet: boolean;
  isDepositOrWithdrawal: boolean;
  isCorrectionOrBonus: boolean;
  isCharity: boolean;
  depositWithdrawalRef: string;
  showLoyaltyAmount: boolean;
  loyaltyComment: string | null;
  loyaltyCommentPrefixKey: string | null;
}

@Component({
  selector: 'hg-operations-history',
  templateUrl: './operations-history.component.html',
  styleUrls: ['./operations-history.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class OperationsHistoryComponent extends DestroySubject implements OnInit {
  operationViews: OperationView[] = [];
  loading: boolean = false;
  hasMore: boolean = true;

  OperationType = OperationType;

  types: SelectValue[] = [];

  private operations: Operation[] = [];
  private skip: number = 0;
  private readonly pageSize: number = 10;
  private currentFilter: AccountFilter = {};
  private showTaxAmount: boolean = false;

  constructor(
    private readonly accountService: AccountService,
    private readonly cdRef: ChangeDetectorRef,
    private readonly toasterService: ToasterService,
    private readonly i18n: I18nService,
    @Inject(customerOperatorConfigurationToken)
    private readonly customerOperatorConfiguration: CustomerOperatorConfiguration
  ) {
    super();
  }

  ngOnInit(): void {
    this.types = this.buildOperationTypeFilters();
    this.i18n.languageChanged$.pipe(takeUntil(this.destroy$)).subscribe(() => {
      this.rebuildViews();
      this.cdRef.markForCheck();
    });
  }

  loadOperations(): void {
    this.loading = true;
    if (this.operations.length) {
      this.skip += this.pageSize;
    }

    this.accountService
      .getOperationsHistory(this.skip, this.pageSize, this.currentFilter.state, this.currentFilter.month)
      .pipe(takeUntil(this.destroy$))
      .subscribe((operations: Operation[]) => {
        if (operations.length - this.pageSize < 0) {
          this.hasMore = false;
        }
        this.operations = this.operations.length ? this.operations.concat(operations) : operations;

        this.rebuildViews();
        this.cdRef.markForCheck();
        this.loading = false;
      });
  }

  filter(filter: AccountFilter): void {
    this.skip = 0;
    this.hasMore = true;
    this.operations = [];
    this.operationViews = [];
    this.currentFilter = filter;
    this.showTaxAmount =
      (!!this.customerOperatorConfiguration.depositTax?.showTaxDetail && filter.state === OperationType.Deposit) ||
      (!!this.customerOperatorConfiguration.withdrawalTax?.showTaxDetail && filter.state === OperationType.Withdrawal);
    this.loadOperations();
  }

  contentCopied(): void {
    this.i18n
      .translate('ACCOUNT.COPIED.REFERENCE')
      .pipe(take(1))
      .subscribe(translation => this.toasterService.show(translation));
  }

  trackByOperation(_index: number, operationView: OperationView): string {
    return operationView.viewKey;
  }

  private rebuildViews(): void {
    this.operationViews = this.operations.reduce<OperationView[]>((views: OperationView[], operation: Operation) => {
      if (this.shouldSplitAmounts(operation)) {
        views.push(this.toView(operation, true, false, '1/2'), this.toView(operation, false, true, '2/2'));
      } else {
        views.push(this.toView(operation, !!operation.amount, !!operation.freeAmount, null));
      }

      return views;
    }, []);
  }

  private shouldSplitAmounts(operation: Operation): boolean {
    return (
      !!operation.amount &&
      !!operation.freeAmount &&
      operation.type !== OperationType.Deposit &&
      operation.type !== OperationType.Withdrawal &&
      operation.type !== OperationType.Loyalty &&
      operation.type !== OperationType.InstantGameTransaction
    );
  }

  private toView(
    operation: Operation,
    showCashAmount: boolean,
    showFreeAmount: boolean,
    splitLabel: string | null
  ): OperationView {
    const isBet: boolean = this.isBetOperation(operation);
    const isDepositOrWithdrawal: boolean = this.isDepositOrWithdrawal(operation);
    const isCharity: boolean = operation.type === OperationType.Charity;
    const isLoyalty: boolean = operation.type === OperationType.Loyalty;
    const hasComment: boolean = !!operation.comment;
    const hasTypeDetail: boolean = !!operation.detail && operation.detail !== OperationDetail.Unknown;

    const showInfoIcon: boolean = hasComment || isBet || isDepositOrWithdrawal;
    const showTax: boolean = this.showTaxAmount && !!operation.taxAmount;
    const showLoyaltyAmount: boolean =
      isLoyalty && (!!operation.freeAmount || !!operation.amount || !!operation.freeSpinAmount);
    const hasLoyaltyStatusPrefix: boolean =
      operation.statusDetail === StatusDetail.Cancel || operation.statusDetail === StatusDetail.Expired;

    return {
      data: operation,
      viewKey: `${operation.id}-${showFreeAmount && !showCashAmount ? 'free' : 'cash'}`,
      showCashAmount,
      showFreeAmount,
      splitLabel,
      isBatchLabel: operation.detail === OperationDetail.BatchAction,
      typeLabelKey: hasTypeDetail ? 'OPERATION.TYPEDETAIL.' + operation.detail : 'OPERATION.TYPE.' + operation.type,
      statusClass: this.statusClass(operation),
      statusIcon: this.statusIcon(operation),
      statusKey: 'OPERATION.STATUS.' + operation.status,
      taxLabelKey: showTax ? (operation.type === OperationType.Deposit ? 'COMMON.GROSS' : 'COMMON.NET') : null,
      taxTotal: showTax ? this.computeTaxAmount(operation.amount, operation.taxAmount) : null,
      hasFooter: showInfoIcon || isCharity || showLoyaltyAmount || showTax,
      showInfoIcon,
      copyValue: isCharity ? operation.id.toString() : operation.operationRef ?? null,
      isBet,
      isDepositOrWithdrawal,
      isCorrectionOrBonus: this.isCorrectionOrBonus(operation),
      isCharity,
      depositWithdrawalRef: isDepositOrWithdrawal ? this.buildDepositWithdrawalRef(operation) : '',
      showLoyaltyAmount,
      loyaltyComment: isLoyalty && hasComment ? operation.comment : null,
      loyaltyCommentPrefixKey:
        isLoyalty && hasComment && hasLoyaltyStatusPrefix ? 'OPERATION.COMMENT.' + operation.statusDetail : null
    };
  }

  private statusClass(operation: Operation): string {
    switch (operation.status) {
      case OperationStatus.Validated:
        return 'validated';
      case OperationStatus.Canceled:
        return 'canceled';
      default:
        return this.isWaiting(operation) ? 'waiting' : '';
    }
  }

  private statusIcon(operation: Operation): string {
    switch (operation.status) {
      case OperationStatus.Validated:
        return 'hg-checked';
      case OperationStatus.Canceled:
        return 'hg-close';
      default:
        return this.isWaiting(operation) ? 'hg-waiting' : '';
    }
  }

  private isWaiting(operation: Operation): boolean {
    return (
      operation.status === OperationStatus.Initiated ||
      operation.status === OperationStatus.InternalInitiated ||
      operation.status === OperationStatus.Processed ||
      operation.status === OperationStatus.WaitingAdministratorValidation
    );
  }

  private isBetOperation(operation: Operation): boolean {
    return (
      operation.type === OperationType.BetPlaced ||
      operation.type === OperationType.BetPaid ||
      operation.type === OperationType.InstantGameTransaction ||
      operation.type === OperationType.SimulatedBet
    );
  }

  private isDepositOrWithdrawal(operation: Operation): boolean {
    return operation.type === OperationType.Deposit || operation.type === OperationType.Withdrawal;
  }

  private isCorrectionOrBonus(operation: Operation): boolean {
    return operation.type === OperationType.Correction || operation.type === OperationType.Bonus;
  }

  private computeTaxAmount(amount: number, taxAmount: number): number {
    return roundNumber(add(amount, taxAmount), this.customerOperatorConfiguration.currency.numberOfDecimals);
  }

  private buildDepositWithdrawalRef(operation: Operation): string {
    const parts: string[] = [];

    if (operation.method) {
      parts.push(`${operation.method},`);
    }
    if (operation.provider) {
      parts.push(this.i18n.translateSync('OPERATION.PROVIDER.' + operation.provider));
    }
    if (operation.operationRef) {
      parts.push(`(Ref:${operation.operationRef})`);
    }
    if (operation.statusDetail) {
      const statusLabel: string = this.i18n.translateSync('ACCOUNT.MY_OPERATIONS.STATUS');
      const statusComment: string = this.i18n.translateSync('OPERATION.COMMENT.' + operation.statusDetail);
      parts.push(`${statusLabel}: ${statusComment}`);
    }
    if (operation.data?.withdrawalNumber) {
      const accountLabel: string = this.i18n.translateSync('OPERATION.ACCOUNT_NUMBER');
      parts.push(`${accountLabel}: ${operation.data.withdrawalNumber}`);
    }

    return parts.join(' ');
  }

  private buildOperationTypeFilters(): SelectValue[] {
    const conf: CustomerOperatorConfiguration = this.customerOperatorConfiguration;
    const hasFeature = (feature: string): boolean => conf.operatorFeatures.includes(feature);

    const rules: ReadonlyArray<[OperationType, boolean]> = [
      [OperationType.BetPlaced, true],
      [OperationType.BetPaid, true],
      [OperationType.Deposit, true],
      [OperationType.Withdrawal, true],
      [OperationType.Correction, true],
      [OperationType.Loyalty, hasFeature(Feature.Loyalty)],
      [OperationType.InstantGameTransaction, conf.betCategories.includes(BetCategoryType.InstantGame)],
      [OperationType.SimulatedBet, conf.bettingConfiguration?.allowSimulatedMode ?? false],
      [OperationType.Charity, hasFeature(Feature.Charity)],
      [OperationType.Bonus, true],
      [OperationType.SessionTax, hasFeature(Feature.GameSession)],
      [OperationType.TournamentPrize, hasFeature(Feature.Tournament)]
    ];

    return rules
      .filter(([, enabled]) => enabled)
      .map(([operationType]) => ({ label: operationType, value: OperationType[operationType] }));
  }
}
