import { isPlatformBrowser } from '@angular/common';
import { Component, ChangeDetectionStrategy, Inject, PLATFORM_ID } from '@angular/core';
import { kioskToken } from '@honoregaming/core';

@Component({
  selector: 'hg-connection-error',
  templateUrl: './connection-error.component.html',
  styleUrls: ['./connection-error.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class ConnectionErrorComponent {
  constructor(@Inject(PLATFORM_ID) private platformId, @Inject(kioskToken) public isKiosk) {}

  public reloadPage(): void {
    if (isPlatformBrowser(this.platformId)) {
      window.location.reload();
    }
  }
}
