import { Inject, Injectable, PLATFORM_ID } from '@angular/core';
import { CanActivate, CanActivateChild, ActivatedRouteSnapshot, Router } from '@angular/router';
import { AuthenticationError } from '../errors/authentication.error';
import { AuthService } from '../services';
import { BroadcastingService } from '@honoregaming/core';
import { isPlatformServer } from '@angular/common';

@Injectable()
export class AuthenticationGuard implements CanActivate, CanActivateChild {
  constructor(
    private readonly authService: AuthService,
    private readonly broadcastingService: BroadcastingService,
    private readonly router: Router,
    @Inject(PLATFORM_ID) private readonly platformId
  ) {}

  canActivate(route: ActivatedRouteSnapshot): boolean {
    if (isPlatformServer(this.platformId)) {
      return true;
    }

    const isAuthenticated = this.authService.isAuthenticated();

    if (route.data['denyAuthenticated'] && isAuthenticated) {
      this.router.createUrlTree(['/']);
    }

    if (route.data['allowAnonymous']) {
      return true;
    }

    if (!isAuthenticated) {
      this.broadcastingService.broadcast('displayLoginPopup');
      throw new AuthenticationError();
    }

    return isAuthenticated;
  }

  canActivateChild(route: ActivatedRouteSnapshot): boolean {
    return this.canActivate(route);
  }
}
