import {
  Component,
  OnInit,
  ChangeDetectionStrategy,
  Input,
  OnDestroy,
  OnChanges,
  ChangeDetectorRef,
  Inject,
  PLATFORM_ID,
  HostBinding,
  NgZone
} from '@angular/core';
import { isPlatformBrowser } from '@angular/common';
import { timer, Subscription } from 'rxjs';

interface LiveTimerData {
  remainingTimeInPeriod?: string;
  eventTime?: string;
  matchTimeExtended?: string;
  stoppageTime?: string;
  clockStopped?: string;
  stopped?: string;
}

type TimerDirection = 'up' | 'down';

@Component({
  selector: 'hg-live-timer',
  templateUrl: './live-timer.component.html',
  styleUrls: ['./live-timer.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class LiveTimerComponent implements OnInit, OnDestroy, OnChanges {
  @Input() data?: LiveTimerData;
  @Input() entryPointId?: number;

  @HostBinding('class.stopped') stopped: boolean = false;

  timeMin: number | null = null;
  timeSec: number | null = null;
  overtimeMin?: number;
  overtimeSec?: number;
  direction?: TimerDirection;

  private static readonly MAX_SECONDS: number = 59;
  private static readonly TICK_INTERVAL_MS: number = 1000;

  private readonly isBrowser: boolean;
  private timerSubscription?: Subscription;

  constructor(
    private readonly zone: NgZone,
    private readonly cdRef: ChangeDetectorRef,
    @Inject(PLATFORM_ID) private readonly platformId: Object
  ) {
    this.isBrowser = isPlatformBrowser(this.platformId);
  }

  ngOnInit(): void {
    this.updateTimeFromInput();
    if (this.isBrowser) {
      this.startTimer();
    }
  }

  ngOnChanges(): void {
    this.updateTimeFromInput();
  }

  ngOnDestroy(): void {
    this.timerSubscription?.unsubscribe();
  }

  private startTimer(): void {
    this.zone.runOutsideAngular(() => {
      this.timerSubscription = timer(0, LiveTimerComponent.TICK_INTERVAL_MS).subscribe(() => this.onTick());
    });
  }

  private onTick(): void {
    if (this.stopped) {
      return;
    }

    if (this.overtimeSec !== undefined) {
      this.tickOvertime();
    } else if (this.direction === 'up') {
      this.tickCountUp();
    } else {
      this.tickCountDown();
    }

    this.zone.run(() => this.cdRef.markForCheck());
  }

  private tickCountUp(): void {
    if (this.timeSec >= LiveTimerComponent.MAX_SECONDS) {
      this.timeSec = 0;
      this.timeMin++;
    }
    this.timeSec++;
  }

  private tickCountDown(): void {
    if (this.timeSec <= 0 && this.timeMin <= 0) {
      return;
    }
    if (this.timeSec <= 0) {
      this.timeSec = LiveTimerComponent.MAX_SECONDS;
      this.timeMin--;
    }
    this.timeSec--;
  }

  private tickOvertime(): void {
    if (this.overtimeSec >= LiveTimerComponent.MAX_SECONDS) {
      this.overtimeSec = 0;
      this.overtimeMin++;
    } else {
      this.overtimeSec++;
    }
  }

  private updateTimeFromInput(): void {
    if (!this.data) {
      return;
    }

    this.applyMainTime(this.data);
    this.applyOvertime(this.data);
    this.cdRef.markForCheck();
  }

  private applyMainTime(data: LiveTimerData): void {
    let rawMin: string | undefined;
    let rawSec: string | undefined;

    if (data.remainingTimeInPeriod) {
      this.direction = 'down';
      [rawMin, rawSec] = data.remainingTimeInPeriod.split(':');
    } else if (data.eventTime) {
      this.direction = 'up';
      [rawMin, rawSec] = data.eventTime.split(':');
    }

    this.stopped = data.clockStopped === 'true' || data.stopped === 'true';

    if (rawMin && rawSec) {
      this.timeMin = +rawMin;
      this.timeSec = +rawSec;
    } else {
      this.timeMin = null;
      this.timeSec = null;
      this.stopped = true;
    }
  }

  private applyOvertime(data: LiveTimerData): void {
    const overtime: string | undefined = data.matchTimeExtended || data.stoppageTime;

    if (overtime) {
      const [min, sec] = overtime.split(':');
      this.overtimeMin = +min;
      this.overtimeSec = +sec;
    } else {
      this.overtimeMin = undefined;
      this.overtimeSec = undefined;
    }
  }
}
