import { DOCUMENT, isPlatformBrowser } from '@angular/common';
import {
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  ComponentFactoryResolver,
  ElementRef,
  EventEmitter,
  Inject,
  Input,
  OnInit,
  Output,
  PLATFORM_ID,
  ViewChild,
  ViewContainerRef
} from '@angular/core';
import { ActivatedRoute, NavigationEnd, Router, RouterLinkActive } from '@angular/router';
import { combineLatest, Observable, Subscription } from 'rxjs';
import { filter, map, startWith, takeUntil, switchMap, tap } from 'rxjs/operators';
import { AccountService } from '@honoregaming/account';
import {
  FreeBetCoupon,
  FreeBetType,
  ITransactionPopupService,
  TransactionMode,
  transactionPopupServiceToken
} from '@honoregaming/betslip';
import { Feature, globalConfiguration } from '@honoregaming/configuration';
import {
  add,
  BetCategoryConfigurationService,
  DestroySubject,
  DialogService,
  kioskToken,
  LocalStorageService
} from '@honoregaming/core';
import {
  AuthService,
  CustomerOperatorConfiguration,
  customerOperatorConfigurationToken,
  CustomerStatus,
  FreeBetService,
  Me,
  NavigationService,
  operatorHasResult,
  SmarticoService,
  TelemetryService,
  UserInformationsService
} from '@honoregaming/customer-core';
import { EventCategoriesService } from '@honoregaming/events';
import { BetCategoryType, InsaLeagueEnum } from '@honoregaming/types';
import { Media, MediaService, MessageComponent, MessageService } from '@honoregaming/ui';
import { FREESPIN_PREFIX as FREESPIN_STORAGE_PREFIX } from '../../constants/coupons.constant';
import { HeaderMenuOrder } from '../../models/header-menu-order';

@Component({
  selector: 'hg-header',
  templateUrl: './header.component.html',
  styleUrls: ['./header.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class HeaderComponent extends DestroySubject implements OnInit {
  @Input() navigationDepth: number = 0;

  @Output() clickOnBack = new EventEmitter<boolean>();

  @ViewChild('messageContainer', { read: ViewContainerRef, static: true }) container?: ViewContainerRef;
  @ViewChild('themeSelectorTemplate', { read: ViewContainerRef, static: false })
  themeSelectorTemplate?: ViewContainerRef;
  @ViewChild('isLive', { read: ViewContainerRef, static: true }) isLive?: RouterLinkActive;
  @ViewChild('freebetCount') freebetCount?: ElementRef;
  @ViewChild('freebetCouponsCount') freebetCouponsCount?: ElementRef;

  Feature = Feature;
  BetCategoryType = BetCategoryType;
  Media = Media;
  FREEBET_BALANCE_KEY: string = 'fbc_balance';

  defaultBetCategory: BetCategoryType = this.operatorConfiguration.features.defaultBetCategory;
  headerMenuOrder = <HeaderMenuOrder>(this.operatorConfiguration.customization['header-menu-order'] || {});
  desktopLogoPath: string =
    globalConfiguration.assetsPath +
    this.operatorConfiguration.key +
    (this.isKiosk && this.operatorConfiguration.kioskConfiguration?.desktopLogoPath !== null
      ? '/' + this.operatorConfiguration.kioskConfiguration.desktopLogoPath
      : '/logo.png');
  mobileLogoPath: string =
    globalConfiguration.assetsPath +
    this.operatorConfiguration.key +
    (this.isKiosk && this.operatorConfiguration.kioskConfiguration?.mobileLogoPath !== null
      ? '/' + this.operatorConfiguration.kioskConfiguration.mobileLogoPath
      : '/mobile-logo.png');
  hasPromotions: boolean = this.operatorConfiguration.contentsConfiguration?.hasPromotions;
  hasNewInstantGames: boolean =
    !!this.operatorConfiguration.hasNew && this.operatorConfiguration.hasNew.includes('InstantGames');
  hasResult: boolean = operatorHasResult(this.operatorConfiguration);
  resultUrl: string = this.operatorConfiguration.headerCustomization?.liveScoreUrl;
  currency: string = this.operatorConfiguration.currency.symbol;
  displayBorlettePage: boolean = false;

  useExternalKYCValidation: boolean =
    this.operatorConfiguration.knowYourCustomerConfiguration?.useExternalKYCValidation || false;
  displayClock: boolean = this.operatorConfiguration.complianceConfiguration?.displayClock;
  freeBetMultiCouponActive: boolean = this.operatorConfiguration.freeBetsConfiguration?.multiCouponEnabled;
  displayLanguageSelector: boolean =
    this.operatorConfiguration.themeCustomizationConfiguration?.displayLanguageSelectorOnBetCategoryBanner;
  instantGamesBetCategoryPath: string = this.betCategoryConfigurationService.getInstantGamesBetCategoryPath();
  enablePopupMethodDeposit: boolean = this.operatorConfiguration.depositConfiguration?.enablePopupMethod;

  hasInsaLeagues: boolean = false;
  loginOpen: boolean = false;
  fromMobileDeposit: boolean = false;
  categoryOpen: boolean = false;
  showSearchIcon: boolean = true;
  closePopup: boolean = false;
  isBrowser: boolean = false;
  showNotificationKYC: boolean = false;
  showModalKYC: boolean = false;
  readonly showSmarticoSelector: boolean = this.smarticoService.showSelector;

  me?: Me;
  media?: Media;
  freeBetsWon?: number;
  freeBets?: number;
  actualFreeBalance?: number;
  current?: number;
  oldFreeBalance?: string;
  newFreeBalance?: string;
  actualFreeBetCoupons: FreeBetCoupon[] = [];
  newFreeBetCoupons: FreeBetCoupon[] = [];
  start: number = 0;
  stateKYC?: string;
  remainingDaysKYC?: number;

  private closeSubscription?: Subscription;
  private messageClickSubscription?: Subscription;
  private timeout;

  constructor(
    private readonly cdRef: ChangeDetectorRef,
    private readonly userInfoService: UserInformationsService,
    private readonly router: Router,
    private readonly route: ActivatedRoute,
    private readonly dialogService: DialogService,
    private readonly resolver: ComponentFactoryResolver,
    private readonly authService: AuthService,
    private readonly messageService: MessageService,
    private readonly mediaService: MediaService,
    private readonly navigationService: NavigationService,
    private readonly localStorageService: LocalStorageService,
    private readonly eventCategoriesService: EventCategoriesService,
    private readonly betCategoryConfigurationService: BetCategoryConfigurationService,
    private readonly freeBetService: FreeBetService,
    private readonly accountService: AccountService,
    private readonly smarticoService: SmarticoService,
    private readonly telemetryService: TelemetryService,
    @Inject(transactionPopupServiceToken) private readonly transactionPopupService: ITransactionPopupService,
    @Inject(DOCUMENT) private readonly document: Document,
    @Inject(PLATFORM_ID) private readonly platId: Object,
    @Inject(customerOperatorConfigurationToken) private readonly operatorConfiguration: CustomerOperatorConfiguration,
    @Inject(kioskToken) public readonly isKiosk: boolean
  ) {
    super();
  }

  ngOnInit(): void {
    this.mediaService.media$.pipe(takeUntil(this.destroy$)).subscribe(media => {
      this.media = media;
      this.displayThemeSelector();
    });

    this.authService.me$
      .pipe(
        takeUntil(this.destroy$),
        tap(me => {
          this.me = me;
          this.actualFreeBalance = this.freeBets;
          this.cdRef.markForCheck();
        }),
        filter(me => !!me),
        tap(me => {
          this.freeBets = me.freeBalance;
          if (me.profile.profileStatus !== CustomerStatus.ToBeVerified) {
            this.displayNotificationKYC(me);
          }
          this.displayModalKYC(me);
          const storageId: number | undefined = parseInt(localStorage.getItem('id'));
          this.storeFreeBalanceValue(me.freeBalance, me.id, storageId);
          if (isNaN(this.actualFreeBalance)) {
            this.actualFreeBalance = this.freeBets;
          }
          this.newFreeBalance = new Intl.NumberFormat('fr-FR').format(this.actualFreeBalance);
        }),
        switchMap(me => {
          const storageId: number | undefined = parseInt(localStorage.getItem('id'));
          return this.initFreeBetCoupons(me.id, storageId).pipe(map(_ => ({ me, storageId })));
        }),
        tap(({ me, storageId }: { me: Me; storageId: number | undefined }) => {
          if (me.id !== storageId) {
            this.localStorageService.setItem('id', me.id);
          }
          this.cdRef.markForCheck();
        })
      )
      .subscribe();

    this.isBrowser = isPlatformBrowser(this.platId);
    this.userInfoService.userMessage$.pipe(takeUntil(this.destroy$)).subscribe(this.onNewMessage.bind(this));
    this.dialogService
      .registerDialog('categories')
      .pipe(takeUntil(this.destroy$))
      .subscribe(open => {
        this.categoryOpen = open === undefined ? !this.categoryOpen : open;

        open ? this.fixBody(true) : this.releaseBody();
        this.cdRef.markForCheck();
      });

    this.messageService.header$.pipe(takeUntil(this.destroy$)).subscribe(response => {
      if (response.key === 'KYC') {
        this.me.profile.profileStatus = response.value;
        this.displayNotificationKYC(this.me, true);
        this.displayModalKYC(this.me, true);
        this.cdRef.markForCheck();
      }
    });

    this.eventCategoriesService
      .getEntryPoints()
      .pipe(takeUntil(this.destroy$))
      .subscribe(ep => {
        if (ep.some(e => e.id in InsaLeagueEnum)) {
          this.hasInsaLeagues = true;
        }
      });

    this.router.events
      .pipe(
        filter(event => event instanceof NavigationEnd),
        map((event: NavigationEnd) => event.url),
        startWith(this.router.url),
        takeUntil(this.destroy$)
      )
      .subscribe(() => {
        this.checkIfSportsIsActivated();
      });

    this.displayBorlettePage = this.operatorConfiguration?.onlineConfiguration?.displayBorlettePage ?? false;
  }

  displayThemeSelector() {
    if (globalConfiguration.showThemesSelector === true) {
      import('projects/customer/hg-theme-switcher/src/lib/components/theme-selector/theme-selector.component').then(
        ({ ThemeSelectorComponent }) => {
          this.themeSelectorTemplate?.clear();
          const factory = this.resolver.resolveComponentFactory(ThemeSelectorComponent);
          if (factory !== undefined) {
            this.themeSelectorTemplate.createComponent(factory);
            this.cdRef.markForCheck();
          }
        }
      );
    }
  }

  checkIfSportsIsActivated() {
    if (this.route.snapshot.firstChild.routeConfig.path === 'sports') {
      this.showSearchIcon = true;
    } else {
      this.showSearchIcon = false;
    }
  }

  onMyAccountClick() {
    this.router.navigate(['myaccount']);
  }

  openLoginPanel(fromMobileDeposit = false): void {
    this.fromMobileDeposit = fromMobileDeposit;
    this.telemetryService.trackEvent('login');
    this.dialogService.toggleDialog('login', true);
  }

  deposit(): void {
    this.smarticoService.closeGamificationWidget();
    if (this.enablePopupMethodDeposit) {
      this.transactionPopupService.open(TransactionMode.Deposit);
    } else {
      this.navigationService.goToDeposit();
    }
    this.trackEvent('deposit_button');
  }

  closeCategories() {
    setTimeout(() => this.dialogService.toggleDialog('categories', false), 500);
  }

  fixBody(onlyInXs = false) {
    onlyInXs
      ? this.document.documentElement.classList.add('hidden-in-xs')
      : this.document.documentElement.classList.add('hidden');
  }

  releaseBody() {
    this.document.documentElement.classList.remove('hidden-in-xs');
    this.document.documentElement.classList.remove('hidden');
  }

  onNewMessage(msg) {
    this.cleanMessages();
    const factory = this.resolver.resolveComponentFactory(MessageComponent);
    if (factory !== undefined) {
      const compRef = this.container?.createComponent(factory);
      if (compRef) {
        compRef.instance.message = msg;
        compRef.onDestroy(this.cleanMessages.bind(this));
        this.closeSubscription = compRef.instance.close.subscribe(this.cleanMessages.bind(this));
        this.messageClickSubscription = compRef.instance.click.subscribe(_x => {
          this.router.navigate(['myaccount', 'deposit']);
          clearTimeout(this.timeout);
          setTimeout(this.cleanMessages.bind(this), 500);
        });
      }
      this.timeout = setTimeout(this.cleanMessages.bind(this), 5e3);
    }
  }

  private cleanMessages() {
    this.container?.clear();
    if (this.closeSubscription) {
      this.closeSubscription.unsubscribe();
    }
    if (this.messageClickSubscription) {
      this.messageClickSubscription.unsubscribe();
    }
    clearTimeout(this.timeout);
  }

  close() {
    this.fromMobileDeposit = false;
  }

  signup() {
    this.telemetryService.trackEvent('create_account');
    this.navigationService.goToSignup();
  }

  private displayNotificationKYC(me: Me, force: boolean = false) {
    if (
      !this.operatorConfiguration.knowYourCustomerConfiguration ||
      !me ||
      !me.profile ||
      (this.router.url.includes('myaccount/registration') && !force)
    ) {
      return;
    }
    if (
      me.profile.profileStatus === CustomerStatus.Verified &&
      localStorage.getItem('kyc:banner:close') === CustomerStatus.Verified
    ) {
      return;
    }
    this.getRemainingDaysKYC(me);
    this.stateKYC = !me.profile?.profileStatus ? 'None' : me.profile.profileStatus;
    this.showNotificationKYC = true;
    if (this.stateKYC === CustomerStatus.Verified || this.stateKYC === CustomerStatus.ToBeVerified) {
      setTimeout(() => {
        localStorage.setItem('kyc:banner:close', this.stateKYC.toString());
        this.showNotificationKYC = false;
      }, 100);
    }
  }

  closeNotificationKYC() {
    localStorage.setItem('kyc:banner:close', this.stateKYC.toString());
    this.showNotificationKYC = false;
  }

  getRemainingDaysKYC(me: Me) {
    let numberOfDaysBeforeAutomaticRejection =
      this.operatorConfiguration.knowYourCustomerConfiguration?.customerAccessLimitationConfiguration
        .numberOfDaysBeforeAutomaticRejection;
    if (!this.operatorConfiguration.knowYourCustomerConfiguration) {
      numberOfDaysBeforeAutomaticRejection = 30;
    }

    const today = new Date();
    const registrationDate = new Date(me.profile?.registrationDate);
    this.remainingDaysKYC = Math.round(
      numberOfDaysBeforeAutomaticRejection - (today.getTime() - registrationDate.getTime()) / (1000 * 3600 * 24)
    );
  }

  private displayModalKYC(me: Me, force: boolean = false) {
    if (
      !this.operatorConfiguration.knowYourCustomerConfiguration ||
      !me ||
      !me.profile ||
      (this.router.url.includes('myaccount/registration') && !force) ||
      localStorage.getItem('kyc:modal:close') === (!me.profile?.profileStatus ? 'None' : me.profile.profileStatus)
    ) {
      return;
    }
    this.getRemainingDaysKYC(me);
    this.stateKYC = !me.profile?.profileStatus ? 'None' : me.profile.profileStatus;
    this.showModalKYC = true;
    if (this.stateKYC === CustomerStatus.Verified || this.stateKYC === CustomerStatus.ToBeVerified) {
      localStorage.removeItem('kyc:modal:close');
    }
  }

  closeModal(event: any) {
    if (event.target.className.includes('modal-close')) {
      localStorage.setItem('kyc:modal:close', this.stateKYC.toString());
      this.showModalKYC = false;
    }
  }

  validateAccount() {
    localStorage.setItem('kyc:modal:close', this.stateKYC.toString());
    this.showModalKYC = false;
    this.router.navigate(['myaccount/informations']);
  }

  storeFreeBalanceValue(freeBalance: number, customerId: number, storageId?: number) {
    if (customerId !== storageId) {
      this.localStorageService.setItem(this.FREEBET_BALANCE_KEY, freeBalance);
      this.actualFreeBalance = this.freeBets;
      this.freeBetsWon = 0;
    } else {
      this.oldFreeBalance = JSON.parse(localStorage.getItem(this.FREEBET_BALANCE_KEY));
      this.actualFreeBalance = parseFloat(this.oldFreeBalance);

      if (this.oldFreeBalance == null) {
        this.localStorageService.setItem(this.FREEBET_BALANCE_KEY, freeBalance);
      }

      this.freeBetsWon = parseFloat((freeBalance - this.actualFreeBalance).toFixed(2));

      if (this.freeBetsWon < 0) {
        this.localStorageService.setItem(this.FREEBET_BALANCE_KEY, freeBalance);
        this.freeBetsWon = 0;
        this.actualFreeBalance = this.freeBets;
      }
    }

    this.cdRef.markForCheck();
  }

  updateFreeBalance(type: FreeBetType) {
    this.closePopup = true;

    if (type === 'freeBetBalance' && this.actualFreeBalance !== this.freeBets) {
      this.counter(this.actualFreeBalance, this.freeBets, 1000);
      this.localStorageService.setItem(this.FREEBET_BALANCE_KEY, this.freeBets);
    }

    this.cdRef.markForCheck();
  }

  counter(start: number, end: number, duration: number) {
    let range = end - start;
    let increment = end > start ? 1 : -1;
    let step = Math.abs(Math.floor(duration / range));
    let timer = setInterval(() => {
      if (add(this.actualFreeBalance, increment) <= end) {
        this.actualFreeBalance = add(this.actualFreeBalance, increment);
      } else {
        this.actualFreeBalance = end;
      }
      this.newFreeBalance = new Intl.NumberFormat('fr-FR').format(this.actualFreeBalance);
      this.freebetCount.nativeElement.textContent = this.newFreeBalance;

      if (this.actualFreeBalance === end) {
        clearInterval(timer);
      }
    }, step);
  }

  private initFreeBetCoupons(
    customerId: number,
    storageId?: number
  ): Observable<[(string | number)[], FreeBetCoupon[]]> {
    this.freeBetService.initCouponsFromStorage(customerId, storageId);
    return combineLatest([this.freeBetService.storedFreeBetCouponsId$, this.freeBetService.openedFreebetCoupons$]).pipe(
      takeUntil(this.destroy$),
      tap(([storedCouponsId, actualCoupons]: [(number | string)[], FreeBetCoupon[]]) => {
        this.actualFreeBetCoupons = actualCoupons;
        this.newFreeBetCoupons = this.actualFreeBetCoupons.filter(
          (coupon: FreeBetCoupon) =>
            !storedCouponsId.includes(coupon.freeSpinInfos ? FREESPIN_STORAGE_PREFIX + coupon.id : coupon.id)
        );
      })
    );
  }

  handleGoBack() {
    if (this.media <= Media.md) {
      this.goBack();
    } else {
      this.router.navigate(['/']);
    }
  }

  public goBack() {
    sessionStorage['is_back'] = 'true';
    this.clickOnBack.emit();
    this.cdRef.markForCheck();
  }

  goToMyAccountInformation() {
    if (
      this.stateKYC === 'None' ||
      this.stateKYC === CustomerStatus.ToBeVerified ||
      this.stateKYC === CustomerStatus.WaitingForCustomer
    ) {
      this.accountService.editProfileInformationClicked();
      this.router.navigate(['myaccount/informations']);
    }
  }

  trackEvent(eventName: string): void {
    if (this.authService.isAuthenticated()) {
      this.telemetryService.trackEvent('header_click_loggedon', {
        shortcut_name: eventName,
        shortcut_device: this.mediaService?.media < Media.md ? 'Mobile' : 'Desktop',
        page: this.router.url
      });
    }
  }
}
