import { Component, ChangeDetectionStrategy, Output, EventEmitter } from '@angular/core';
import { Media, MediaService } from '@honoregaming/ui';

@Component({
  selector: 'hg-bet-slip-simulate',
  templateUrl: './bet-slip-simulate.component.html',
  styleUrls: ['./bet-slip-simulate.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class BetSlipSimulateComponent {
  isCheckboxSelected: boolean = false;
  @Output()
  close = new EventEmitter();

  constructor(private mediaService: MediaService) {}

  closeModal() {
    if (this.isCheckboxSelected) {
      localStorage.setItem('betslip:simulate_modal:valid', '1');
    }
    this.close.emit({ disableReleaseBody: this.mediaService.media < Media.lg });
  }
}
