import { ChangeDetectionStrategy, ChangeDetectorRef, Component, ElementRef, Inject, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { forkJoin } from 'rxjs';
import { finalize, takeUntil } from 'rxjs/operators';
import { BroadcastingService, DestroySubject } from '@honoregaming/core';
import {
  CustomerOperatorConfiguration,
  customerOperatorConfigurationToken,
  TelemetryService
} from '@honoregaming/customer-core';
import { I18nService } from '@honoregaming/i18n';
import { CustomerWithdrawalInformation } from '../../models/customer-withdrawal-information.model';
import { PaymentProviderStatus, Provider } from '../../models/provider.model';
import { AccountService } from '../../services/account.service';

@Component({
  selector: 'hg-withdrawal-list',
  templateUrl: './withdrawal-list.component.html',
  styleUrls: ['./withdrawal-list.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class WithdrawalListComponent extends DestroySubject implements OnInit {
  providers: Provider[] = [];
  loading: boolean = true;
  withdrawalStateActive: boolean = false;
  canDoWithdrawal: boolean = false;
  withdrawalInformation?: CustomerWithdrawalInformation;
  withdrawSelectionDetailsText?: string;

  readonly providerStatus: typeof PaymentProviderStatus = PaymentProviderStatus;

  showMinimumAmountsInWithdrawals: boolean =
    this.operatorConfiguration.onlineConfiguration?.showMinimumAmountsInWithdrawals;
  showMaximumAmountsInWithdrawals: boolean =
    this.operatorConfiguration.onlineConfiguration?.showMaximumAmountsInWithdrawals;

  constructor(
    private readonly router: Router,
    private readonly accountService: AccountService,
    private readonly cdRef: ChangeDetectorRef,
    private readonly activatedRoute: ActivatedRoute,
    private readonly bcService: BroadcastingService,
    private readonly i18nService: I18nService,
    private readonly telemetryService: TelemetryService,
    private readonly elementRef: ElementRef<HTMLElement>,
    @Inject(customerOperatorConfigurationToken) private readonly operatorConfiguration: CustomerOperatorConfiguration
  ) {
    super();
  }

  ngOnInit(): void {
    this.loadWithdrawSelectionDetailsText();
    this.loadWithdrawalData();
    this.registerScrollToTop();
  }

  trackWithdrawalProviderClicked(provider: Provider): void {
    this.telemetryService.trackEvent('withdrawal_provider_select', {
      provider_name: provider.displayName ?? provider.providerName
    });
  }

  private loadWithdrawSelectionDetailsText(): void {
    if (!this.i18nService.translationKeyExistsSync('ACCOUNT.WITHDRAW.SELECTION.DETAILS_TEXT')) {
      return;
    }

    this.i18nService
      .translate('ACCOUNT.WITHDRAW.SELECTION.DETAILS_TEXT')
      .pipe(takeUntil(this.destroy$))
      .subscribe((text: string) => {
        this.withdrawSelectionDetailsText = text;
        this.cdRef.markForCheck();
      });
  }

  private loadWithdrawalData(): void {
    forkJoin([
      this.accountService.getPaymentProviders(),
      this.accountService.getGlobalWithdrawalState(),
      this.accountService.getWithdrawalInformation()
    ])
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.loading = false;
          this.cdRef.markForCheck();
        })
      )
      .subscribe(([providersResponse, withdrawalStateActive, withdrawalInformation]) => {
        this.withdrawalStateActive = withdrawalStateActive;
        this.applyWithdrawalInformation(withdrawalInformation);
        this.setProviders(providersResponse.providers);
      });
  }

  private applyWithdrawalInformation(withdrawalInformation: CustomerWithdrawalInformation): void {
    this.withdrawalInformation = withdrawalInformation;
    this.canDoWithdrawal = withdrawalInformation.canDoWithdrawal && withdrawalInformation.withdrawalsAllowed;
  }

  private setProviders(providers: Provider[]): void {
    this.providers = providers.filter(provider => provider.withdrawalStatus !== PaymentProviderStatus.Disabled);

    const [singleProvider] = this.providers;
    if (
      this.providers.length === 1 &&
      this.canDoWithdrawal &&
      singleProvider.withdrawalStatus === PaymentProviderStatus.Online
    ) {
      this.router.navigate([singleProvider.providerName.toLowerCase()], { relativeTo: this.activatedRoute });
    }
  }

  private registerScrollToTop(): void {
    this.bcService
      .register('payment-provider-scroll-to-top')
      .pipe(takeUntil(this.destroy$))
      .subscribe(() => this.elementRef.nativeElement.scrollIntoView(true));
  }
}
