import { ITelemetryService } from './telemetry-service.model';
import { Injectable, Inject, PLATFORM_ID } from '@angular/core';
import { DOCUMENT, isPlatformBrowser } from '@angular/common';
import { customerOperatorConfigurationToken, CustomerOperatorConfiguration } from '../../models';
import { Router } from '@angular/router';

declare var window: any;
declare var gtag: any;

@Injectable()
export class GoogleAnalyticsTelemetryService implements ITelemetryService {
  isBrowser = isPlatformBrowser(this.platformId);

  constructor(
    @Inject(customerOperatorConfigurationToken) private operatorConfig: CustomerOperatorConfiguration,
    @Inject(DOCUMENT) document,
    @Inject(PLATFORM_ID) private platformId,
    private router: Router
  ) {
    if (this.isBrowser) {
      window.dataLayer = window.dataLayer || [];
      window.gtag = function () {
        window.dataLayer.push(arguments);
      };

      gtag('js', new Date());

      const script = document.createElement('script');
      script.src =
        'https://www.googletagmanager.com/gtag/js?id=' + operatorConfig.telemetryConfiguration.google.trackingId;
      document.body.appendChild(script);

      gtag('config', this.operatorConfig.telemetryConfiguration.google.trackingId, {
        page_path: this.router.url
      });
    }
  }

  trackPageView(name: string, path: string): void {
    if (this.isBrowser) {
      gtag('config', this.operatorConfig.telemetryConfiguration.google.trackingId, {
        page_title: name,
        page_path: path
      });
    }
  }

  trackEvent(name: string, properties: any): void {
    if (this.isBrowser) {
      gtag('event', name, properties);
    }
  }
}
