import { HttpClient } from '@angular/common/http';
import { Inject, Injectable } from '@angular/core';
import { BetPlaced, FreeBetCoupon } from '@honoregaming/betslip';
import { globalConfiguration, OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';
import { BetCategoryType, FreeBetCouponState } from '@honoregaming/types';
import { QueryBuilderService } from 'projects/core/hg-core/src/lib/services/query-builder.service';
import { BehaviorSubject, Observable, Subscription } from 'rxjs';
import { AuthService } from './auth.service';
import { filter, map, tap } from 'rxjs/operators';
import { ApplicationEvent, BroadcastingService, LocalStorageService } from '@honoregaming/core';
import { FREEBET_COUPONS_KEY, FREESPIN_PREFIX } from 'projects/customer/customer/src/app/constants/coupons.constant';
import { Router } from '@angular/router';

@Injectable({ providedIn: 'root' })
export class FreeBetService {
  private fetchFreeBetCouponsSubscription: Subscription;

  private storedFreeBetCouponsIdSubject = new BehaviorSubject<(number | string)[]>([]);
  storedFreeBetCouponsId$ = this.storedFreeBetCouponsIdSubject.asObservable();

  private freeBetCouponsSubject = new BehaviorSubject<FreeBetCoupon[]>([]);
  freeBetCoupons$ = this.freeBetCouponsSubject.asObservable();

  private isConnected = false;

  private isReadySubject = new BehaviorSubject(false);

  constructor(
    private httpClient: HttpClient,
    private queryBuilderService: QueryBuilderService,
    private authService: AuthService,
    private broadcastingService: BroadcastingService,
    private localStorageService: LocalStorageService,
    @Inject(operatorConfigurationToken) private operatorConfiguration: OperatorConfiguration,
    private router: Router
  ) {
    this.authService.status$.subscribe(status => {
      this.isConnected = status === 'connected';
      // Avoid duplicate request if refreshed page is freebets-coupons
      if (this.isConnected && !this.router.routerState.snapshot.url.includes('/freebets-coupons')) {
        this.refreshFreeBetCoupons();
      } else if (!this.isConnected) {
        this.cleanFreeBetCouponsData();
      }
    });

    // In case of BetPlace, refresh the customer's Coupons
    this.broadcastingService.register<BetPlaced>(ApplicationEvent.BetPlaced).subscribe(_ => {
      if (this.isConnected) {
        this.refreshFreeBetCoupons();
      } else {
        this.cleanFreeBetCouponsData();
      }
    });
  }

  get openedFreebetCoupons$(): Observable<FreeBetCoupon[]> {
    return this.freeBetCoupons$.pipe(
      map((coupons: FreeBetCoupon[]) =>
        coupons.filter((coupon: FreeBetCoupon) => coupon.state === FreeBetCouponState.Open)
      )
    );
  }

  get openedFreebetCouponsCount$(): Observable<number> {
    return this.openedFreebetCoupons$.pipe(
      map((coupons: FreeBetCoupon[]) =>
        this.operatorConfiguration.freeBetsConfiguration?.multiCouponEnabled ? coupons.length : 0
      )
    );
  }

  set isReadyState(isReady: boolean) {
    if (this.isReadySubject.value !== isReady) {
      this.isReadySubject.next(isReady);
    }
  }

  getFreeBetCouponsByType(
    forBetting: boolean = true,
    betCategoryType: BetCategoryType,
    completeMyBetCouponId?: number
  ): Observable<FreeBetCoupon[]> {
    // Force refresh coupons when a completion is started or cancelled to include or remove coupons with balance at 0.
    return completeMyBetCouponId ||
      this.freeBetCouponsSubject.value.some((coupon: FreeBetCoupon) => !coupon.balance && coupon.isBetCompletion)
      ? this.forceRefreshFreeBetCoupon(forBetting, betCategoryType, completeMyBetCouponId)
      : this.isReadySubject.asObservable().pipe(
          filter((isReady: boolean) => isReady),
          map(() => this.getFilteredCoupons(betCategoryType))
        );
  }

  updateStoredCoupons(): void {
    const localCouponsIds = this.localStorageService.getItem(FREEBET_COUPONS_KEY) ?? [];
    const requestCouponsId: (number | string)[] = this.freeBetCouponsSubject.value.map((coupon: FreeBetCoupon) =>
      coupon.freeSpinInfos ? FREESPIN_PREFIX + coupon.id : coupon.id
    );
    const fullCouponsIds = requestCouponsId.concat(localCouponsIds);
    const couponsId = fullCouponsIds.filter((id, index) => fullCouponsIds.indexOf(id) === index);

    this.localStorageService.setItem(FREEBET_COUPONS_KEY, couponsId);
    this.storedFreeBetCouponsIdSubject.next(couponsId);
  }

  initCouponsFromStorage(customerId: number, storageId?: number): void {
    if (storageId === customerId) {
      const storedCouponsId: (number | string)[] | undefined = this.localStorageService.getItem(FREEBET_COUPONS_KEY);
      if (storedCouponsId?.length) {
        this.storedFreeBetCouponsIdSubject.next(storedCouponsId);
      }
    } else {
      this.fetchFreeBetCouponsSubscription = this.loadFreeBetCoupons().subscribe(() => this.updateStoredCoupons());
    }
  }

  forceRefreshFreeBetCoupon(
    forBetting?: boolean,
    betCategoryType?: BetCategoryType,
    completeMyBetCouponId?: number
  ): Observable<FreeBetCoupon[]> {
    if (this.fetchFreeBetCouponsSubscription) {
      this.fetchFreeBetCouponsSubscription.unsubscribe();
    }

    return this.loadFreeBetCoupons(forBetting, completeMyBetCouponId).pipe(
      map(() => this.getFilteredCoupons(betCategoryType))
    );
  }

  private refreshFreeBetCoupons() {
    if (this.fetchFreeBetCouponsSubscription) {
      this.fetchFreeBetCouponsSubscription.unsubscribe();
    }
    this.fetchFreeBetCouponsSubscription = this.loadFreeBetCoupons(true).subscribe();
  }

  private getFilteredCoupons(betCategoryType?: BetCategoryType): FreeBetCoupon[] {
    if (!betCategoryType) {
      return this.freeBetCouponsSubject.value;
    }
    return this.freeBetCouponsSubject.value.filter(c => c.freeBetRule?.betCategories.indexOf(betCategoryType) > -1);
  }

  private loadFreeBetCoupons(forBetting: boolean = true, completeMyBetCouponId?: number) {
    return this.getFreeBetCoupons(forBetting, completeMyBetCouponId).pipe(
      map((coupons: FreeBetCoupon[]) =>
        coupons.map((coupon: FreeBetCoupon) => ({
          ...coupon,
          isBetCompletion: completeMyBetCouponId && completeMyBetCouponId === coupon.id
        }))
      ),
      tap((coupons: FreeBetCoupon[]) => {
        // Concat "inactive" coupons if it's not for betting purpose
        if (!forBetting) {
          this.updateAvailableCoupons(this.freeBetCouponsSubject.value.concat(coupons));
        } else {
          this.updateAvailableCoupons(coupons);
        }
        this.isReadyState = true;
      })
    );
  }

  private getFreeBetCoupons(forBetting: boolean, completeMyBetCouponId?: number): Observable<FreeBetCoupon[]> {
    const queryString = this.queryBuilderService.buildHttpParams({
      forBetting,
      completeMyBetCouponId
    });

    let query = this.httpClient.get<FreeBetCoupon[]>(`${globalConfiguration.apiBaseUrl}freebet`, {
      params: queryString
    });

    if (!this.operatorConfiguration.freeBetsConfiguration?.multiCouponEnabled) {
      query = query.pipe(
        map(coupons => {
          return coupons.filter(coupon => coupon.isDefaultCoupon);
        })
      );
    }

    return query;
  }

  private updateAvailableCoupons(freeBetCoupons: FreeBetCoupon[] = []) {
    this.freeBetCouponsSubject.next(freeBetCoupons);
  }

  private cleanFreeBetCouponsData() {
    this.updateAvailableCoupons();
    this.isReadyState = false;
  }
}
