import { ChangeDetectionStrategy, Component, Inject, Input } from '@angular/core';
import { OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';
import { Images } from '@honoregaming/types';

@Component({
  selector: 'hg-sports-pool-banner',
  templateUrl: './sports-pool-banner.component.html',
  styleUrls: ['./sports-pool-banner.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class SportsPoolBannerComponent {
  @Input() format: 'mobile' | 'desktop' = 'mobile';

  readonly route: string = '/sports-pool';
  readonly images: Images = this.operatorConfiguration.sportsPoolConfiguration?.bannerImages;

  constructor(@Inject(operatorConfigurationToken) private readonly operatorConfiguration: OperatorConfiguration) {}

  get imageUrl(): string {
    return this.images?.[this.format]?.url;
  }
}
