import { HttpEvent, HttpHandler, HttpInterceptor, HttpRequest } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { Observable } from 'rxjs';
import { globalConfiguration } from '@honoregaming/configuration';

@Injectable()
export class AppVersionInterceptor implements HttpInterceptor {
  public intercept(req: HttpRequest<any>, next: HttpHandler): Observable<HttpEvent<any>> {
    if (globalConfiguration.appVersion && this.isApiRequest(req.url)) {
      req = req.clone({
        headers: req.headers.append('App-Version', globalConfiguration.appVersion)
      });
    }
    return next.handle(req);
  }

  private isApiRequest(url: string): boolean {
    return [
      globalConfiguration.apiBaseUrl,
      globalConfiguration.apiAuthenticationBaseUrl,
      globalConfiguration.apiBettingBaseUrl,
      globalConfiguration.apiEventsBaseUrl,
      globalConfiguration.apiPaymentProviderBaseUrl,
      globalConfiguration.liveApiBaseUrl
    ].some(baseUrl => !!baseUrl && url.startsWith(baseUrl));
  }
}
