const currentBetCategoryStorageKey = 'betslip:betcategory';
const betSlipStorageKey = 'betslip:';
const lastBetStakePerBetCategoryStorageKey = 'betslip:lastBetStakePerBetCategory';

@Injectable({ providedIn: 'root' })
export class BetSlipService implements ITemplatingBetSlipService {
  private betSlipModeHandler: IBetSlipModeHandler;
  private persistedMode = false;

  private betSlipMode: BetSlipMode;
  private betSlipType: BetSlipType = BetSlipType.Real;
  private modeSubject: BehaviorSubject<BetSlipMode>;
  $mode: Observable<BetSlipMode>;
  private configuration: BetSlipConfiguration = {
    acceptOddChangeAvailable: null,
    availableBetSlipMode: null,
    betCategory: null,
    betCodeAvailable: null,
    canUseFreeBet: false,
    applyTaxToFreeBets: this.operatorConfiguration.freeBetsConfiguration?.applyTax,
    predefinedStakes: null
  };
  private configurationSubject: BehaviorSubject<BetSlipConfiguration>;
  $configuration: Observable<BetSlipConfiguration>;

  private amounts: Amounts = {
    summary: { maxPayout: 0, totalStake: 0, maxPayoutWithBonus: 0 },
    values: [],
    bonus: null,
    nextBonus: null,
    bettingTax: null,
    maxBonusReach: false,
    paymentTax: null,
    oddsCompatibleWithFreeBet: false,
    useFreeBet: false
  };
  private amountsSubject: BehaviorSubject<Amounts>;
  $amounts: Observable<Amounts>;

  private betLines: BetLine[];
  private refreshEventSubject: Subject<any>;
  $refreshEvent: Observable<any>;
  private instantGameTransactions: InstantGameTransaction[] = [];
  private linesSubject: BehaviorSubject<BetSlipLinesInfo>;
  $lines: Observable<BetSlipLinesInfo>;

  private isLocked = false;
  acceptOddChange = this.operatorConfiguration.bettingConfiguration?.acceptOddChange ?? true;

  private eventBetTypeChangedSubscription: Subscription;
  private eventChangedSubscription: Subscription;
  private manualOddsPushSubscription: Subscription;

  private betPlaced: boolean = false;

  private betCode?: string;

  private lastBetSelectionPerBetCategory: {
    [betCategoryType: string]: BetSelection;
  } = {};
  private individualBetInstantGames = [InstantGameName.GoldenLion, InstantGameName.TreasureIsland];

  private lastBetStakePerBetCategory: {
    [betCategoryType: string]: { amount: number };
  } = {};

  private isBusy = false;
  private betSystemTypeChangeNotification: boolean = false;

  constructor(
    private storageService: LocalStorageService,
    @Inject(betValidationServiceToken) private betValidationService: IBetValidationService,
    @Inject(operatorConfigurationToken) private operatorConfiguration: OperatorConfiguration,
    @Inject(scopeToken) private scope: Scope,
    private pushService: PushService,
    private bettingApiService: BettingApiService,
    private broadcastingService: BroadcastingService,
    private messageService: MessageService,
    private betSlipFreebetService: BetSlipFreebetService,
    private completeMyBetService: CompleteMyBetService,
    private betLinesMapperService: BetLinesMapperService
  ) {
    this.configuration.betCategory =
      this.storageService.getItem(currentBetCategoryStorageKey) || BetCategoryType.SportsFixedOdds;

    this.configurationSubject = new BehaviorSubject(null);
    this.$configuration = this.configurationSubject.asObservable();

    this.modeSubject = new BehaviorSubject(BetSlipMode.Simple);
    this.$mode = this.modeSubject.asObservable();

    this.linesSubject = new BehaviorSubject(null);
    this.$lines = this.linesSubject.asObservable();

    this.amountsSubject = new BehaviorSubject(this.amounts);
    this.$amounts = this.amountsSubject.asObservable();

    this.refreshEventSubject = new Subject();
    this.$refreshEvent = this.refreshEventSubject.asObservable();

    this.rehydrateBetSlip(this.configuration.betCategory);
  }

  get betLinesValue(): BetLine[] {
    return this.betLines;
  }

  get mode(): BetSlipMode {
    return this.modeSubject.value;
  }

  get isPersistedMode(): boolean {
    return this.persistedMode;
  }

  get disabledModes(): BetSlipMode[] {
    return Object.values(BetSlipMode).reduce((disabledModes: BetSlipMode[], mode: BetSlipMode) => {
      if (!this.canBeInMode(mode)) {
        disabledModes.push(mode);
      }
      return disabledModes;
    }, []);
  }

  get amountsValue(): Amounts {
    return this.amountsSubject.value;
  }

  canBeInMode(mode: BetSlipMode, newBetLines: BetLine[] = []): boolean {
    if (!this.configuration.availableBetSlipMode.includes(mode)) {
      return false;
    }

    const betSlipModeHandler = this.getBetSlipModeHandler(mode);
    return betSlipModeHandler.canBeInMode([...this.betLines, ...newBetLines]);
  }

  getLastSelection(betCategoryType: BetCategoryType): BetSelection | undefined {
    return this.lastBetSelectionPerBetCategory[betCategoryType];
  }

  hasItemIdPlaced(item: Pick<BetLine, 'eventBetTypeItemId' | 'oddsBoostId' | 'manualOddsBoostId'>): boolean {
    return this.betPlaced && this.betLinesMapperService.hasItemIdPlaced(this.betLines, item);
  }

  rehydrateBetSlip(betCategoryType: BetCategoryType) {
    const storageKey = betSlipStorageKey + betCategoryType.toLocaleLowerCase();

    const betSlipModel: BetSlipStorageModel = this.storageService.getItem(storageKey);

    if (!betSlipModel) {
      this.clear();
    } else {
      const date = new Date(betSlipModel.lastModified);
      date.setMinutes(date.getMinutes() + 10);
      if (date < new Date()) {
        this.clear();
      }
    }

    if (betCategoryType === BetCategoryType.SportsFixedOdds) {
      this.completeMyBetService.initCompleteMyBetFromStorage();
    } else {
      this.completeMyBetService.clearBetCompletion(false);
    }

    this.isLocked = false;
    this.betPlaced = false;

    this.betLines = betSlipModel?.betLines || [];
    this.amounts.values = betSlipModel?.amounts?.map(x => ({ amount: x })) || [];
    this.instantGameTransactions = betSlipModel?.instantGameTransactions || [];
    this.betSlipMode = betSlipModel?.mode || BetSlipMode.Simple;
    this.betSlipType = BetSlipType.Real;

    this.configureBetSlip();

    if (
      this.betSlipMode === BetSlipMode.Systems &&
      this.configuration.availableBetSlipMode.indexOf(BetSlipMode.Systems) !== -1
    ) {
      this.betSlipModeHandler = new BetSlipSystemsModeHandler(this.operatorConfiguration);
      this.betSlipMode = BetSlipMode.Systems;
    } else if (
      this.betSlipMode === BetSlipMode.Multiple &&
      this.configuration.availableBetSlipMode.indexOf(BetSlipMode.Multiple) !== -1
    ) {
      this.betSlipModeHandler = new BetSlipMultipleModeHandler(this.operatorConfiguration);
      this.betSlipMode = BetSlipMode.Multiple;
    } else {
      this.betSlipModeHandler = new BetSlipSimpleModeHandler(this.operatorConfiguration);
      this.betSlipMode = BetSlipMode.Simple;
    }
    if (this.completeMyBetService.completeMyBetInfo?.betId && this.amounts.values.length) {
      this.amounts.values = [this.amounts.values[0]];
    }
    this.betSlipModeHandler.initBetSlip(
      this.betLines,
      this.amounts,
      this.lastBetStakePerBetCategory?.[this.configuration.betCategory]?.amount,
      true,
      this.getDefaultBetSlipStake()
    );
    this.amounts.bettingTax = this.operatorConfiguration.bettingTaxes?.find(
      bt => !bt.betCategory || bt.betCategory === betCategoryType
    );
    this.amounts.paymentTax = this.operatorConfiguration.paymentTaxes?.find(
      bt => !bt.betCategory || bt.betCategory === betCategoryType
    );

    if (!this.betSlipModeHandler.canBeInMode(this.betLines)) {
      this.betSlipModeHandler = new BetSlipSimpleModeHandler(this.operatorConfiguration);
      this.betSlipMode = BetSlipMode.Simple;
      this.betSlipModeHandler.initBetSlip(
        this.betLines,
        this.amounts,
        this.lastBetStakePerBetCategory?.[this.configuration.betCategory]?.amount,
        undefined,
        this.getDefaultBetSlipStake()
      );
    }

    if (this.configuration.betCategory === BetCategoryType.SportsFixedOdds) {
      this.registerPush();
    }

    if (betCategoryType === BetCategoryType.SportsFixedOdds) {
      this.configuration.predefinedStakes =
        this.operatorConfiguration.global.predefinedStakes?.sportsFixedOddsPredefinedStakes;
    } else if (betCategoryType === BetCategoryType.VirtualFixedOdds) {
      this.configuration.predefinedStakes =
        this.operatorConfiguration.global.predefinedStakes?.virtualFixedOddsPredefinedStakes;
    } else {
      this.configuration.predefinedStakes = null;
    }

    if (
      this.configuration.betCategory === BetCategoryType.SportsFixedOdds ||
      this.configuration.betCategory === BetCategoryType.VirtualFixedOdds
    ) {
      this.lastBetStakePerBetCategory = this.getLastBetStakePerBetCategory();
    }

    this.modeSubject.next(this.betSlipMode);

    this.computeAmounts();
    this.linesSubject.next({
      reason: BetLineChangeReason.Cache,
      lines: this.betLines,
      instantGameTransactions: this.instantGameTransactions
    });

    this.computeLeftoverBalanceBetLines();
    this.amountsSubject.next(this.amounts);

    const now = new Date().getTime();
    const expiredBetLines = this.betLines.filter(
      bl => !bl.isBetCompletion && bl.eventDate && new Date(bl.eventDate).getTime() < now
    );
    if (expiredBetLines.length) {
      expiredBetLines.forEach(betLine => {
        this.removeBetLine(betLine);
      });
    }
  }

  saveBetSlip() {
    this.storageService.setItem(currentBetCategoryStorageKey, this.configuration.betCategory);
    const storageKey = betSlipStorageKey + this.configuration.betCategory.toLocaleLowerCase();
    const betSlipStorageModel: BetSlipStorageModel = {
      amounts: this.amounts.values.map(v => v.amount),
      betLines: this.betLines.map(x => {
        const line = { ...x };
        delete line.failure;

        return line;
      }),
      instantGameTransactions: this.instantGameTransactions,
      lastModified: new Date(),
      mode: this.betSlipMode,
      type: this.betSlipType
    };
    this.storageService.setItem(storageKey, betSlipStorageModel);
  }

  tryClearPlacedBet(): boolean {
    if (!this.betPlaced) {
      return false;
    }
    this.unLockAndClearBetSlip();
    return true;
  }

  createInstantGameTransaction(instantGameTransaction: InstantGameTransaction) {
    this.tryClearPlacedBet();

    if (!this.betLines || !this.betLines.length) {
      this.changeCurrentBetCategory(BetCategoryType.InstantGame);
    }

    if (this.configuration.betCategory === BetCategoryType.InstantGame) {
      if (instantGameTransaction.instantGame === InstantGameName.Addition) {
        if (this.instantGameTransactions.findIndex(x => x.instantGame != InstantGameName.Addition) !== -1) {
          this.messageService
            .sendComponentMessage(BetReplacementComponent, {}, { canBeDismissed: false, displayClose: true })
            .closed.subscribe(validationResult => {
              if (validationResult) {
                this.instantGameTransactions = [instantGameTransaction];

                this.linesSubject.next({
                  reason: BetLineChangeReason.BetAdd,
                  lines: this.betLines,
                  instantGameTransactions: this.instantGameTransactions
                });
                this.computeAmountForInstanGame();
              } else {
                return;
              }
            });
        } else {
          this.instantGameTransactions = this.instantGameTransactions.filter(
            i => i.instantGame === instantGameTransaction.instantGame
          );
          this.instantGameTransactions.push(instantGameTransaction);
        }
      } else if (this.individualBetInstantGames.indexOf(instantGameTransaction.instantGame) != -1) {
        if (this.instantGameTransactions.length > 0) {
          this.messageService
            .sendComponentMessage(BetReplacementComponent, {}, { canBeDismissed: false, displayClose: true })
            .closed.subscribe(validationResult => {
              if (validationResult) {
                this.instantGameTransactions = [instantGameTransaction];

                this.linesSubject.next({
                  reason: BetLineChangeReason.BetAdd,
                  lines: this.betLines,
                  instantGameTransactions: this.instantGameTransactions
                });
                this.computeAmountForInstanGame();
              } else {
                return;
              }
            });
        } else {
          this.instantGameTransactions = [instantGameTransaction];
        }
      } else {
        this.instantGameTransactions = this.instantGameTransactions.filter(
          i => i.instantGame === instantGameTransaction.instantGame
        );
        this.instantGameTransactions.push(instantGameTransaction);
      }

      this.linesSubject.next({
        reason: BetLineChangeReason.BetAdd,
        lines: this.betLines,
        instantGameTransactions: this.instantGameTransactions
      });
      this.computeAmountForInstanGame();
    }
  }

  addBetLine(betLine: BetLine, amount?: number, skipDeletePreviousBetLine: boolean = false): boolean {
    this.tryClearPlacedBet();

    if (this.isLocked) {
      return false;
    }

    if (
      betLine.betTypeId === DrawGameBorletteBetType.DoubChans &&
      (betLine.associatedDrawGamesIds?.length ?? 0) === 0
    ) {
      return false;
    }

    if (
      (!this.betLines ||
        !this.betLines.length ||
        betLine.betCategoryType === BetCategoryType.HorseRacingMutualInternationalPool ||
        betLine.betCategoryType === BetCategoryType.HorseRacingMutualOperatorPool ||
        betLine.betCategoryType === BetCategoryType.DrawGame) &&
      !(this.instantGameTransactions.length > 0)
    ) {
      // We want only 1 HorseRace BetSlip for both BetCategoryType
      if (betLine.betCategoryType === BetCategoryType.HorseRacingMutualOperatorPool) {
        this.changeCurrentBetCategory(BetCategoryType.HorseRacingMutualInternationalPool);
      } else {
        this.changeCurrentBetCategory(betLine.betCategoryType);
      }
    }

    if (
      betLine.betCategoryType !== this.configuration.betCategory &&
      !(
        (betLine.betCategoryType === BetCategoryType.HorseRacingMutualInternationalPool &&
          this.configuration.betCategory === BetCategoryType.HorseRacingMutualOperatorPool) ||
        (betLine.betCategoryType === BetCategoryType.HorseRacingMutualOperatorPool &&
          this.configuration.betCategory === BetCategoryType.HorseRacingMutualInternationalPool)
      )
    ) {
      return false;
    }

    if (this.isLocked) {
      return false;
    }

    if (this.betCode) {
      this.betCode = null;
    }

    if (
      !skipDeletePreviousBetLine &&
      ((this.scope === Scope.Customer &&
        this.operatorConfiguration.bettingConfiguration.onlineDeletePreviousBetLineIfSameEvent) ||
        ((this.scope === Scope.Agent || this.scope === Scope.Kiosk) &&
          this.operatorConfiguration.bettingConfiguration.retailDeletePreviousBetLineIfSameEvent)) &&
      this.configuration.betCategory === BetCategoryType.SportsFixedOdds
    ) {
      const currentEventIds = this.betLines.map(l => l.eventId);
      if (currentEventIds?.length > 0 && betLine.eventId && currentEventIds.includes(betLine.eventId)) {
        const previousBetLineOnSameEventId = this.betLines.find(bl => bl.eventId === betLine.eventId);
        this.removeBetLine(previousBetLineOnSameEventId);
      }
    }

    // Add number to betline
    betLine.number = this.getNewBetLineNumber();

    const itemIndex = getBetLineIndex(betLine, this.betLines);
    if (itemIndex === -1) {
      const isBetCompletion: boolean = !!this.completeMyBetService.completeMyBetInfo?.betId;
      this.betSlipModeHandler.addBetLine(
        betLine,
        this.betLines,
        this.amounts,
        isBetCompletion ? amount : this.lastBetStakePerBetCategory?.[this.configuration.betCategory]?.amount,
        this.getDefaultBetSlipStake(isBetCompletion)
      );
      if (this.betSlipMode === BetSlipMode.Simple && amount) {
        this.amounts.values[this.betLines.length - 1].amount = amount;
      }
      // Check if we need to automatically switch into Multiple mode
      if (
        this.betSlipMode === BetSlipMode.Simple &&
        this.configuration.availableBetSlipMode.indexOf(BetSlipMode.Multiple) !== -1 &&
        (!this.persistedMode || betLine.isBetBuilder)
      ) {
        const betSlipMultipleModeHandler = new BetSlipMultipleModeHandler(this.operatorConfiguration);
        if (betSlipMultipleModeHandler.canBeInMode(this.betLines)) {
          this.betSlipModeHandler = betSlipMultipleModeHandler;

          this.amounts = {
            ...this.amounts,
            summary: { maxPayout: 0, totalStake: 0, maxPayoutWithBonus: 0 },
            bonus: null,
            nextBonus: null
          };

          if (!isBetCompletion) {
            this.amounts.values = [];
          }
          this.betSlipModeHandler.initBetSlip(
            this.betLines,
            this.amounts,
            this.lastBetStakePerBetCategory?.[this.configuration.betCategory]?.amount,
            isBetCompletion,
            this.getDefaultBetSlipStake(isBetCompletion)
          );
          this.betSlipMode = BetSlipMode.Multiple;
          this.modeSubject.next(this.betSlipMode);
        }
      }

      // If the current selection can't be compatible with the current mode, switch to Simple mode
      if (
        !this.persistedMode &&
        !this.betSlipModeHandler.canBeInMode(this.betLines) &&
        !this.betSystemTypeChangeNotification &&
        this.configuration.betCategory !== BetCategoryType.SportsFixedOdds
      ) {
        this.switchToSimple();
      }

      this.computeLeftoverBalanceBetLines();
      this.computeFreeBetCouponBetLineAmount();

      const betLineWithComputedAmount = this.computeAmount(betLine);

      if (betLineWithComputedAmount) {
        this.betLines[this.betLines.length - 1] = betLineWithComputedAmount.betLine;

        const hasExplicitAmount = this.betSlipMode === BetSlipMode.Simple && !!amount;
        if (betLineWithComputedAmount.amount !== undefined && !hasExplicitAmount) {
          this.amounts.values[this.betLines.length - 1].amount = betLineWithComputedAmount.amount;
        }
      }

      this.linesSubject.next({
        reason: BetLineChangeReason.BetAdd,
        lines: this.betLines,
        instantGameTransactions: this.instantGameTransactions
      });
      this.computeAmounts();
      this.amountsSubject.next(this.amounts);

      this.computeFreeBetCouponsRequirements();

      this.saveBetSlip();

      if (this.configuration.betCategory === BetCategoryType.SportsFixedOdds) {
        this.registerPush();
      }

      return true;
    }

    return false;
  }

  switchToSimple() {
    this.betSlipModeHandler = new BetSlipSimpleModeHandler(this.operatorConfiguration);
    this.amounts = {
      ...this.amounts,
      summary: { maxPayout: 0, totalStake: 0, maxPayoutWithBonus: 0 },
      values: [],
      bonus: null,
      nextBonus: null
    };
    this.betSlipModeHandler.initBetSlip(
      this.betLines,
      this.amounts,
      this.lastBetStakePerBetCategory?.[this.configuration.betCategory]?.amount,
      undefined,
      this.getDefaultBetSlipStake()
    );
    this.betSlipMode = BetSlipMode.Simple;
    this.modeSubject.next(this.betSlipMode);
  }

  getNewBetLineNumber(): number {
    return this.betLines.length ? Math.max(...this.betLines.map(bl => bl.number)) + 1 : 1;
  }

  hasBets(): boolean {
    return !!this.betLines?.length || !!this.instantGameTransactions?.length;
  }

  initCompleteMyBet(betSystemHistory: BetSystemHistory): Observable<CompleteMyBetResponse | null> {
    // Use first betId by default, should be replaced by corresponding betId if completion is allowed with system type
    return !betSystemHistory.betsIds.length
      ? of(null)
      : this.bettingApiService.initCompleteMyBet(betSystemHistory.betsIds[0]).pipe(
          tap((completeMyBetResponse: CompleteMyBetResponse) => {
            if (completeMyBetResponse.completeMyBetLines.length !== betSystemHistory.betLines.length) {
              throw new Error();
            }
            this.unLock();
            this.changeCurrentBetCategory(BetCategoryType.SportsFixedOdds);
            this.clear();
            this.completeMyBetService.initCompleteMyBet(
              betSystemHistory.betsIds[0],
              betSystemHistory.isFreeBet,
              completeMyBetResponse.freebetCouponId
            );
            const amount: number = add(betSystemHistory.systemStake, betSystemHistory.bettingTaxAmount || 0);
            completeMyBetResponse.completeMyBetLines.forEach((completeMyBetLine: CompleteMyBetLine) => {
              const betLineHistory: BetLineHistory | undefined = betSystemHistory.betLines.find(
                history => history.eventBetTypeItemId === completeMyBetLine.eventBetTypeItemId
              );
              if (betLineHistory) {
                const newBetLine: BetLine = this.betLinesMapperService.betLineHistoryToBetLine(
                  betLineHistory,
                  betSystemHistory.betCategory,
                  amount
                );
                this.addBetLine(
                  {
                    ...newBetLine,
                    eventBetTypeId: completeMyBetLine.eventBetTypeId,
                    isBetCompletion: true
                  },
                  amount
                );
              }
            });

            this.changeMode(convertBetSystemTypeToBetSlipMode(BetSystemType.Multiple), false);
            this.amounts.useFreeBet = betSystemHistory.isFreeBet;
            // Select or reset selected freebetCouponId depends on completed betsystem coupon
            this.betSlipFreebetService.selectCoupon(completeMyBetResponse.freebetCouponId);
          })
        );
  }

  replaceBetLines(
    betSystem: BetSystemHistory,
    betSystemType: BetSystemType,
    betBuilderEventsOdds?: BetBuilderOddsResult[]
  ): Observable<{ success: boolean; betCategory?: BetCategoryType }> {
    if (
      betSystem.betCategory !== BetCategoryType.SportsFixedOdds &&
      betSystem.betCategory !== BetCategoryType.DrawGame
    ) {
      return of({ success: false });
    }

    const betLinesRebetables = betSystem.betLines?.filter(
      betLine =>
        betLine.state === BetLineStateType.Pending &&
        !(
          betLine.preEventOrLive === PreEventOrLiveType.PreEvent &&
          happenBefore(getUtcNow(), new Date(betLine.eventDate), 0)
        )
    );
    if (!betLinesRebetables?.length) {
      return of({ success: false });
    }

    const hasOddsBoost = betSystem.betLines.some(bl => !!bl.oddsBoostId);
    const hasManualOddsBoost = betSystem.betLines.some(bl => !!bl.manualOddsBoostId);

    if (hasOddsBoost) {
      const oddsBoostIds = betSystem.betLines.filter(bl => !!bl.oddsBoostId).map(bl => bl.oddsBoostId);

      return this.bettingApiService.getOddsBoostBetLinesToRebet(oddsBoostIds).pipe(
        map(oddsBoostsRebetBetLines => {
          if (!oddsBoostsRebetBetLines?.length) {
            return { success: false };
          }

          this.unLockAndClearBetSlip();
          const amount = add(betSystem.systemStake, betSystem.bettingTaxAmount || 0);

          this.changeMode(convertBetSystemTypeToBetSlipMode(betSystemType), true);
          this.persistedMode = true;

          oddsBoostsRebetBetLines.forEach(oddsBoostRebetBetLine => {
            const newBetLine = createOddsBoostBetLine(oddsBoostRebetBetLine.oddsBoost);
            this.addBetLine(newBetLine, amount);
          });

          if (this.betSlipMode === BetSlipMode.Multiple) {
            this.amounts.values = [{ amount: add(betSystem.totalStake, betSystem.bettingTaxAmount || 0) }];
          }

          return { success: true, betCategory: betSystem.betCategory };
        })
      );
    } else if (hasManualOddsBoost) {
      const manualOddsBoostIds = betSystem.betLines
        .filter(bl => !!bl.manualOddsBoostId)
        .map(bl => bl.manualOddsBoostId);

      return this.bettingApiService.getManualOddsBoostBetLinesToRebet(manualOddsBoostIds).pipe(
        map(manualOddsBoostsRebetBetLines => {
          if (!manualOddsBoostsRebetBetLines?.length) {
            return { success: false };
          }

          this.unLockAndClearBetSlip();
          // Use systemStake (per-line stake) so multiple funbets are not each charged the full total.
          // For a single funbet systemStake === totalStake, so legacy behaviour is unchanged.
          const amount = add(betSystem.systemStake, betSystem.bettingTaxAmount || 0);

          this.changeMode(convertBetSystemTypeToBetSlipMode(betSystemType), true);
          this.persistedMode = true;

          manualOddsBoostsRebetBetLines.forEach(manualOddsBoostRebetBetLine => {
            const newBetline = createManualOddsBoostBetLine(manualOddsBoostRebetBetLine.manualOddsBoost);
            this.addBetLine(newBetline, amount);
          });

          if (this.betSlipMode === BetSlipMode.Multiple) {
            this.amounts.values = [{ amount: add(betSystem.totalStake, betSystem.bettingTaxAmount || 0) }];
          }

          return { success: true, betCategory: betSystem.betCategory };
        })
      );
    } else {
      let request: Observable<RebetBetLine[]>;
      const eventBetTypeItemIds: number[] = this.betLinesMapperService.betLinesHistoryToEventBetTypeItemIds(
        betSystem.betLines
      );

      if (eventBetTypeItemIds?.length > 0 && eventBetTypeItemIds[0] !== undefined) {
        request = this.bettingApiService.getBetLinesToRebet(eventBetTypeItemIds, null);
      } else {
        request = this.bettingApiService.getBetLinesToRebet(null, betSystem.id);
      }

      return request.pipe(
        map(allowedBetLines => {
          if (!allowedBetLines?.length) {
            return { success: false };
          }

          this.unLockAndClearBetSlip();
          const amount = add(betSystem.systemStake, betSystem.bettingTaxAmount || 0);
          this.persistedMode = true;
          const betBuilderBetLinesEventIds: Set<number> = new Set<number>();

          allowedBetLines.forEach(betLine => {
            let newBetLine: BetLine;
            let shouldAddBetLine = true;

            if (betSystem.betCategory === BetCategoryType.DrawGame) {
              const drawGameBetLine = betLine as DrawGameRebetBetLine;

              const drawGameBetType = drawGameBetLine.event.eventBetTypes.find(
                ebt => ebt.betTypeId == drawGameBetLine.betTypeId
              );
              const drawGameBetTypeId = drawGameBetType.betTypeId;

              let baseList: string[] = null;
              let digestAsBaseList: string = null;

              if (
                drawGameBetTypeId === DrawGameBorletteBetType.Loto3 ||
                drawGameBetTypeId === DrawGameBorletteBetType.Loto4 ||
                drawGameBetTypeId === DrawGameBorletteBetType.Loto5 ||
                drawGameBetTypeId === DrawGameBorletteBetType.Loto6 ||
                drawGameBetTypeId === DrawGameBorletteBetType.DoubChans ||
                drawGameBetTypeId === DrawGameBorletteBetType.Borlette ||
                drawGameBetTypeId === DrawGameBorletteBetType.Mariage
              ) {
                drawGameBetType.baseAmount = drawGameBetLine.stake;

                const drawGameWithOptionsResults = IsDrawGameWithOptions(drawGameBetTypeId);
                const drawGameWithPrizesResults = IsDrawGameWithPrizes(drawGameBetTypeId);

                if (drawGameWithPrizesResults || drawGameWithOptionsResults) {
                  let numberPlayed = drawGameBetLine.baseList[0].toString();

                  if (drawGameWithOptionsResults) {
                    numberPlayed = drawGameBetLine.baseList[0].toString().split('/')[0].trim();
                  } else if (drawGameBetTypeId === DrawGameBorletteBetType.Mariage) {
                    numberPlayed = drawGameBetLine.baseList.map(i => i.toString()).join('');
                  }

                  let targetDigitNumber = GetNumberOfDigitsPerWinningNumber(drawGameBetTypeId);
                  let missingZerosPrefix = GetMissingZerosPrefix(Number(numberPlayed), targetDigitNumber);

                  digestAsBaseList = missingZerosPrefix + numberPlayed;
                } else {
                  baseList = drawGameBetLine.baseList.sort((a, b) => a - b).map(i => i.toString());
                }
              } else {
                baseList = drawGameBetLine.baseList.sort((a, b) => a - b).map(i => i.toString());
              }

              newBetLine = createBetLineWithSelection(
                drawGameBetLine.event,
                drawGameBetType,
                digestAsBaseList !== null ? [digestAsBaseList] : baseList,
                drawGameBetLine.extraList.map(i => i.toString()),
                BetCategoryType.DrawGame,
                drawGameBetLine.event.drawGameRule,
                undefined,
                undefined,
                drawGameBetLine.multiplier ?? 1,
                undefined,
                undefined,
                drawGameBetLine.option
              );

              shouldAddBetLine = drawGameBetTypeId !== DrawGameBorletteBetType.DoubChans;
            } else {
              const sportsBetLine = betLine as SportsFixedOddsRebetBetLine;
              const betLineHistory: BetLineHistory | undefined = this.betLinesMapperService.findBetLineHistory(
                betSystem,
                sportsBetLine.eventBetTypeItemId
              );

              if (!betLineHistory.betBuilderLines?.length) {
                newBetLine = this.betLinesMapperService.rebetToBetLine(
                  betLineHistory,
                  betSystem.betCategory,
                  sportsBetLine
                );
              } else if (!betBuilderBetLinesEventIds.has(betLineHistory.eventId)) {
                betBuilderBetLinesEventIds.add(betLineHistory.eventId);
                const betBuilderOdds: BetBuilderOdds | undefined = betBuilderEventsOdds?.find(
                  (betBuilderEventOdds: BetBuilderOddsResult) => betLineHistory.eventId === betBuilderEventOdds.eventId
                )?.betBuilderOdds;
                if (betBuilderOdds) {
                  newBetLine = this.betLinesMapperService.rebetToBetBuilderBetLine(
                    betBuilderOdds,
                    betLineHistory,
                    betSystem.betCategory,
                    sportsBetLine,
                    allowedBetLines as SportsFixedOddsRebetBetLine[]
                  );
                } else {
                  shouldAddBetLine = false;
                }
              } else {
                shouldAddBetLine = false;
              }
            }

            if (shouldAddBetLine) {
              this.addBetLine(newBetLine, amount);
            }
          });

          this.changeMode(convertBetSystemTypeToBetSlipMode(betSystemType), true);

          if (this.betSlipMode === BetSlipMode.Multiple) {
            this.amounts.values = [{ amount }];
          }

          if (this.betSlipMode === BetSlipMode.Systems && allowedBetLines.length === eventBetTypeItemIds.length) {
            this.amounts.values[betSystem.n - betSystem.k] = { amount };
          }

          return { success: true, betCategory: betSystem.betCategory };
        })
      );
    }
  }

  updateBetLine(betLine: BetLine | number, amount?: number) {
    if (this.isLocked || this.configuration.betCategory === BetCategoryType.InstantGame) {
      return;
    }

    let targetIndex: number = null;
    if (typeof betLine === 'number') {
      if (betLine >= 0 && betLine <= this.amounts.values.length) {
        targetIndex = betLine;
      }
    } else {
      let itemIndex = getBetLineIndex(betLine, this.betLines);
      if (betLine.eventType === EventType.DrawGame) {
        itemIndex = getDrawGameBetLineToUpdateIndex(betLine, this.betLines);
      }

      const targetBetLine = this.betLines[itemIndex];
      if (itemIndex !== -1) {
        targetIndex = itemIndex;
        this.betLines[targetIndex] = { ...betLine };
        this.betLines = [...this.betLines];

        const betLineWithComputedAmount = this.computeAmount(betLine, targetBetLine.baseAmount);

        if (betLineWithComputedAmount) {
          this.betLines[targetIndex] = betLineWithComputedAmount.betLine;
          if (betLineWithComputedAmount.amount !== undefined) {
            this.amounts.values[targetIndex].amount = betLineWithComputedAmount.amount;
          }
        }

        this.linesSubject.next({
          reason: BetLineChangeReason.BetUpdated,
          lines: this.betLines,
          instantGameTransactions: this.instantGameTransactions
        });
      }
    }

    if (
      targetIndex !== undefined &&
      targetIndex != null &&
      targetIndex >= 0 &&
      (targetIndex < this.amounts.values.length || this.betLines[targetIndex].isBetBuilder)
    ) {
      // We cannot update amount for HorseRacing (amounts are computed in computeHorseRaceBetLine method)
      if (
        (!!amount || this.betSlipMode === BetSlipMode.Systems) &&
        this.configuration.betCategory !== BetCategoryType.HorseRacingMutualOperatorPool &&
        this.configuration.betCategory !== BetCategoryType.HorseRacingMutualInternationalPool
      ) {
        this.amounts.values[targetIndex].amount = amount;
      }

      this.computeAmounts();
      this.amountsSubject.next(this.amounts);

      this.computeFreeBetCouponsRequirements();

      this.saveBetSlip();
    }
  }

  removeBetLine(betLine: BetLine, persistedMode: boolean = false, keepFreeBetModeOnEmpty: boolean = false): void {
    if (this.isLocked || this.configuration.betCategory === BetCategoryType.InstantGame) {
      return;
    }

    const itemIndex: number =
      betLine.eventType === EventType.DrawGame
        ? getDrawGameBetLineToUpdateIndex(betLine, this.betLines)
        : getBetLineIndex(betLine, this.betLines);

    if (this.betCode && betLine.active && !betLine.failure) {
      this.betCode = null;
    }

    if (itemIndex === -1) {
      return;
    }
    this.betSlipModeHandler.removeBetLine(betLine, this.betLines, this.amounts);
    this.handleModeTransitionAfterRemoval(persistedMode);
    if (this.betLines.length === 0) {
      this.persistedMode = false;
      if (this.configuration.canUseFreeBet && !keepFreeBetModeOnEmpty) {
        this.toggleFreeBetMode(false);
      }
    }

    this.linesSubject.next({
      reason: BetLineChangeReason.BetRemove,
      lines: this.betLines,
      instantGameTransactions: this.instantGameTransactions
    });

    this.recomputeAll(keepFreeBetModeOnEmpty);
    this.saveBetSlip();

    if (this.configuration.betCategory === BetCategoryType.SportsFixedOdds) {
      this.registerPush();
    }
  }

  private handleModeTransitionAfterRemoval(persistedMode: boolean = false): void {
    const shouldSwitchToMultiple: boolean =
      this.betSlipMode === BetSlipMode.Simple &&
      this.configuration.availableBetSlipMode.includes(BetSlipMode.Multiple) &&
      !this.persistedMode &&
      !persistedMode;

    if (shouldSwitchToMultiple) {
      const multipleModeHandler: BetSlipMultipleModeHandler = new BetSlipMultipleModeHandler(
        this.operatorConfiguration
      );
      if (multipleModeHandler.canBeInMode(this.betLines)) {
        this.switchMode(multipleModeHandler, BetSlipMode.Multiple);
        return;
      }
    }

    if (!this.betSlipModeHandler.canBeInMode(this.betLines)) {
      this.switchMode(new BetSlipSimpleModeHandler(this.operatorConfiguration), BetSlipMode.Simple);
    }
  }

  private switchMode(handler: IBetSlipModeHandler, mode: BetSlipMode): void {
    this.betSlipModeHandler = handler;
    this.amounts = {
      ...this.amounts,
      summary: { maxPayout: 0, totalStake: 0, maxPayoutWithBonus: 0 },
      values: [],
      bonus: null,
      nextBonus: null
    };
    this.betSlipModeHandler.initBetSlip(
      this.betLines,
      this.amounts,
      this.lastBetStakePerBetCategory?.[this.configuration.betCategory]?.amount,
      undefined,
      this.getDefaultBetSlipStake()
    );
    this.betSlipMode = mode;
    this.modeSubject.next(this.betSlipMode);
  }

  private recomputeAll(skipFreeBetCouponsRequirements: boolean = false): void {
    this.computeLeftoverBalanceBetLines();
    this.computeFreeBetCouponBetLineAmount();
    this.computeAmounts();
    this.amountsSubject.next(this.amounts);
    if (!skipFreeBetCouponsRequirements) {
      this.computeFreeBetCouponsRequirements();
    }
  }

  removeInstantGameTransaction(index: number) {
    if (this.isLocked || this.configuration.betCategory !== BetCategoryType.InstantGame) {
      return;
    }

    this.instantGameTransactions.splice(index, 1);

    this.linesSubject.next({
      reason: BetLineChangeReason.BetRemove,
      lines: this.betLines,
      instantGameTransactions: this.instantGameTransactions
    });

    this.saveBetSlip();
    this.computeAmountForInstanGame();
  }

  updateInstantGameTransaction(multiplier: number, index: number) {
    if (this.isLocked || this.configuration.betCategory !== BetCategoryType.InstantGame) {
      return;
    }

    this.instantGameTransactions[index].multiplier = multiplier;

    this.linesSubject.next({
      reason: BetLineChangeReason.BetUpdated,
      lines: this.betLines,
      instantGameTransactions: this.instantGameTransactions
    });

    this.saveBetSlip();
    this.computeAmountForInstanGame();
  }

  computeAmountForInstanGame() {
    var stakeAfterMultiplier = this.instantGameTransactions.reduce(
      (acc, cur) => add(acc, mul(cur.stake, cur.multiplier ?? 1)),
      0
    );
    this.betSlipModeHandler.computeBetSlipInstantGameSummary(stakeAfterMultiplier, this.amounts);
    this.amountsSubject.next(this.amounts);
  }

  handleLogout() {
    if (this.completeMyBetService.hasStoredCompletion) {
      this.clear(true);
      this.clearStoredBetSlip(BetCategoryType.SportsFixedOdds);
    }
  }

  // Clear betslip and add only newly added lines when keep selection is made after bet completion
  // To ensure that amounts and leftover are correctly recalculated
  clearCompleteMyBetSelection(): void {
    const mode: BetSlipMode = this.betSlipMode;
    const newBetLinesSelected: BetLine[] = this.betLines.filter((betLine: BetLine) => !betLine.isBetCompletion);
    this.completeMyBetService.clearBetCompletion();
    this.clear();
    newBetLinesSelected.forEach((betLine: BetLine) => this.addBetLine(betLine));
    this.changeMode(mode);
  }

  clear(onLogout?: boolean) {
    if (this.isLocked) {
      return;
    }

    this.betCode = null;
    this.betLines = [];
    this.instantGameTransactions = [];
    this.amounts = {
      ...this.amounts,
      summary: { maxPayout: 0, totalStake: 0, maxPayoutWithBonus: 0 },
      values: [],
      bonus: null,
      nextBonus: null,
      maxBonusReach: false
    };

    if (this.configuration.betCategory === BetCategoryType.SportsFixedOdds || onLogout) {
      this.completeMyBetService.clearBetCompletion();
    }

    if (this.configuration.canUseFreeBet) {
      this.toggleFreeBetMode(false);
    }

    this.changeMode(BetSlipMode.Simple);

    this.persistedMode = false;
    this.linesSubject.next({
      reason: BetLineChangeReason.Clear,
      lines: this.betLines,
      instantGameTransactions: this.instantGameTransactions
    });
    this.computeAmounts();
    this.amountsSubject.next(this.amounts);

    this.saveBetSlip();

    if (this.configuration.betCategory === BetCategoryType.SportsFixedOdds) {
      this.registerPush();
    }
  }

  unLock() {
    this.betPlaced = false;
    this.isLocked = false;
  }

  getIsBusy(): boolean {
    return this.isBusy;
  }

  setIsBusy(isBusy: boolean) {
    this.isBusy = isBusy;
  }

  placeBet(customerBehalfIdentity?: CustomerIdentity): Observable<{
    result: boolean;
    response?: CreateBetResponse | CreateInstantGameTransactionsResponse | CreateSimulatedBetResponse;
    reason?: string;
  }> {
    if (this.isBetSlipValid) {
      const canPlaceBet$: Observable<{ result: boolean; reason?: string }> = this.completeMyBetService.completeMyBetInfo
        ?.betId
        ? of({ result: true })
        : this.betValidationService.canPlaceBet(
            this.amounts.summary.totalStakeWithTax || this.amounts.summary.totalStake,
            this.configuration.betCategory,
            this.betSlipFreebetService.selectedCoupon?.balance
          );
      return canPlaceBet$.pipe(
        mergeMap(canPlaceBet => {
          if (canPlaceBet.result) {
            if (this.scope !== Scope.Customer && this.scope !== Scope.Kiosk && this.isBusy) {
              return of({
                result: false,
                reason: 'BETSLIP.BUSY'
              });
            }

            this.isLocked = true;
            this.isBusy = true;

            switch (this.configuration.betCategory) {
              case BetCategoryType.InstantGame:
                return this.placeInstantGameBet(customerBehalfIdentity);

              case BetCategoryType.SportsPool:
                return this.placeSportsPoolGameBet();

              default:
                return this.betSlipType === BetSlipType.Simulate
                  ? this.placeSimulateBet(customerBehalfIdentity)
                  : this.placeStandardBet(customerBehalfIdentity);
            }
          }

          return of(canPlaceBet);
        })
      );
    }

    return of({ result: false });
  }

  private placeStandardBet(customerBehalfIdentity?: CustomerIdentity): Observable<{
    result: boolean;
    response?: CreateBetResponse;
    reason?: string;
  }> {
    const copy: BetCopy = {
      betCategory: this.configuration.betCategory,
      betLines: this.betLines,
      betSlipMode: this.betSlipMode,
      amounts: this.amounts
    };

    return this.bettingApiService
      .placeBet(
        this.betLines,
        this.betSlipMode,
        this.amounts,
        this.acceptOddChange,
        this.amounts.useFreeBet,
        this.betCode,
        customerBehalfIdentity?.customerId,
        this.betSlipFreebetService.selectedCoupon?.id,
        this.completeMyBetService.completeMyBetInfo?.betId
      )
      .pipe(
        map(response => {
          this.betPlaced = true;
          this.broadcastingService.broadcast<BetPlaced>(ApplicationEvent.BetPlaced, {
            betCategory: copy.betCategory,
            bet: {
              betLines: copy.betLines,
              amounts: copy.amounts,
              betSlipMode: copy.betSlipMode,
              betResponse: response
            },
            customerBehalfIdentity
          });
          return { result: true, response };
        }),
        catchError(e => this.handleBetError(e))
      );
  }

  private placeSimulateBet(customerBehalfIdentity?: CustomerIdentity): Observable<{
    result: boolean;
    response?: CreateBetResponse;
    reason?: string;
  }> {
    const copy: BetCopy = {
      betCategory: this.configuration.betCategory,
      betLines: this.betLines,
      betSlipMode: this.betSlipMode,
      amounts: this.amounts
    };

    return this.bettingApiService.placeSimulateBet(this.betLines, this.betSlipMode, this.amounts).pipe(
      map(response => {
        this.betPlaced = true;
        this.broadcastingService.broadcast<BetPlaced>(ApplicationEvent.BetPlaced, {
          betCategory: copy.betCategory,
          bet: {
            betLines: copy.betLines,
            amounts: copy.amounts,
            betSlipMode: copy.betSlipMode,
            betResponse: response
          },
          customerBehalfIdentity
        });
        return { result: true, response };
      }),
      catchError(e => this.handleBetError(e))
    );
  }

  private placeInstantGameBet(customerBehalfIdentity?: CustomerIdentity): Observable<{
    result: boolean;
    response?: CreateInstantGameTransactionsResponse;
    reason?: string;
  }> {
    const copy: InstantGameBetCopy = {
      betCategory: this.configuration.betCategory,
      instantGameTransactions: this.instantGameTransactions
    };

    return this.bettingApiService
      .createInstantGameTransactions(this.instantGameTransactions, customerBehalfIdentity?.customerId)
      .pipe(
        map(responses => {
          this.betPlaced = true;
          this.broadcastingService.broadcast<BetPlaced>(ApplicationEvent.BetPlaced, {
            betCategory: copy.betCategory,
            instantGameBet: {
              instantGameName: copy.instantGameTransactions[0].instantGame,
              instantGameTransactionsResponse: responses
            },
            customerBehalfIdentity
          });
          return { result: true, response: responses };
        }),
        catchError(e => this.handleBetError(e))
      );
  }

  private placeSportsPoolGameBet(): Observable<{
    result: boolean;
    response?: CreateBetResponse;
    reason?: string;
  }> {
    const copy: SportsPoolBetCopy = {
      betCategory: this.configuration.betCategory,
      betLines: this.betLines,
      amounts: this.amounts
    };

    return this.bettingApiService
      .placeSportsPoolBet(this.betLines, this.amounts, this.betSlipFreebetService.selectedCoupon?.id)
      .pipe(
        map(response => {
          this.betPlaced = true;
          this.broadcastingService.broadcast<BetPlaced>(ApplicationEvent.BetPlaced, {
            betCategory: copy.betCategory,
            sportsPoolGameBet: {
              betLines: copy.betLines,
              amounts: copy.amounts,
              betResponse: response
            }
          });
          return { result: true, response: response };
        }),
        catchError(e => this.handleBetError(e))
      );
  }

  private handleBetError(error: BettingError): Observable<never> {
    this.isLocked = false;
    this.isBusy = false;
    return this.catchBetSlipRequestError(error);
  }

  getBetCode(betSystemId?: number, totalOdds?: number): Observable<{ code: string }> {
    if (!this.configuration.betCodeAvailable || (!betSystemId && !this.isBetSlipValid())) {
      return EMPTY;
    }

    this.isLocked = true;

    return this.bettingApiService.getBetCode(this.buildBetCodeRequest(betSystemId, totalOdds)).pipe(
      finalize(() => (this.isLocked = false)),
      catchError(this.catchBetSlipForBetCodeRequestError.bind(this))
    );
  }

  private get getStakePerBetline(): number[] {
    return this.amounts.values.map(v => v?.amount ?? 0);
  }

  private get getOddsBoostIds(): number[] {
    return this.betLines.filter(line => !!line.oddsBoostId).map(line => line.oddsBoostId);
  }

  private get getManualOddsBoostIds(): number[] {
    return this.betLines.filter(line => !!line.manualOddsBoostId).map(line => line.manualOddsBoostId);
  }

  // Returns the stake of each funbet in the order [oddsBoosts..., manualOddsBoosts...],
  // to match the order in which the lines are rebuilt on the server side.
  private getStakePerFunbetLine(oddsBoostIds: number[], manualOddsBoostIds: number[]): number[] {
    const stakeForLine = (predicate: (line: BetLine) => boolean): number => {
      const index = this.betLines.findIndex(predicate);
      return index === -1 ? 0 : this.amounts.values[index]?.amount ?? 0;
    };

    return [
      ...oddsBoostIds.map(id => stakeForLine(line => line.oddsBoostId === id)),
      ...manualOddsBoostIds.map(id => stakeForLine(line => line.manualOddsBoostId === id))
    ];
  }

  private get getDrawGameSelections(): DrawGameSelection[] {
    return this.betLines
      .filter(line => line.betCategoryType === BetCategoryType.DrawGame)
      .map(line => ({
        eventBetTypeId: line.eventBetTypeId,
        stakeMultiplier: line.multiplier,
        baseList: line.baseList ?? [],
        extraList: line.extraList ?? [],
        quickPick: line.quickPick ?? false,
        associatedDrawGamesIds: line.associatedDrawGamesIds ?? [],
        option: line.option
      }));
  }

  private buildBetCodeRequest(betSystemId: number, totalOdds: number): CreateBetCodeRequest {
    const hasBetBuilderBetLines: boolean = this.betLines.some((betLine: BetLine) => betLine.isBetBuilder);
    const eventBetTypeItemIds = this.betLinesMapperService.betLinesToEventBetTypeItemIds(this.betLines);
    const oddsBoostIds: number[] = this.getOddsBoostIds;
    const manualOddsBoostIds: number[] = this.getManualOddsBoostIds;
    const isOddsBoost: boolean = oddsBoostIds.length > 0 || manualOddsBoostIds.length > 0;
    const isSingleOddsBoost: boolean = oddsBoostIds.length + manualOddsBoostIds.length === 1;

    return {
      betSystemId,
      totalOdds,
      eventBetTypeItemIds,
      hasBetBuilderBetLines,
      totalStake: isOddsBoost
        ? this.amounts.values[0]?.amount
        : this.amounts.summary.totalStakeWithTax || this.amounts.summary.totalStake,
      maxPayout: this.amounts.summary.maxPayout,
      betSystemType: convertBetSlipModeToBetSystemType(this.betSlipMode),
      betCategory: this.configuration.betCategory,
      // Singular (deprecated) fields filled only for a single funbet, for backward compatibility
      oddsBoostId: isSingleOddsBoost ? oddsBoostIds[0] : undefined,
      manualOddsBoostId: isSingleOddsBoost ? manualOddsBoostIds[0] : undefined,
      oddsBoostIds,
      manualOddsBoostIds,
      drawGameSelections: this.getDrawGameSelections,
      stakePerLine: this.buildStakePerLine(isOddsBoost, oddsBoostIds, manualOddsBoostIds)
    };
  }

  private buildStakePerLine(isOddsBoost: boolean, oddsBoostIds: number[], manualOddsBoostIds: number[]): number[] {
    if (isOddsBoost) {
      return this.getStakePerFunbetLine(oddsBoostIds, manualOddsBoostIds);
    }

    return this.betSlipMode === BetSlipMode.Simple && this.betLines.length > 0 ? this.getStakePerBetline : [];
  }

  getBetFromBetCode(betCode: string): Observable<BetCodeBet> {
    if (this.isBetSlipValid) {
      this.isLocked = true;

      return this.bettingApiService.getBetFromBetCode(betCode).pipe(
        finalize(() => {
          this.isLocked = false;
        }),
        catchError(this.catchBetSlipForBetCodeRequestError.bind(this))
      );
    }
  }

  isBetSlipValid(balance?: number): boolean {
    if (this.configuration.betCategory === BetCategoryType.InstantGame) {
      return this.instantGameTransactions.length > 0;
    }

    if (!this.isPayoutValid()) {
      return false;
    }

    const selectedCoupon: FreeBetCouponBetSlip | null = this.betSlipFreebetService.selectedCoupon;
    if (
      this.amounts.useFreeBet &&
      (!selectedCoupon ||
        !(
          this.configuration.betCategory === BetCategoryType.SportsFixedOdds ||
          this.configuration.betCategory === BetCategoryType.VirtualFixedOdds ||
          this.configuration.betCategory === BetCategoryType.SportsPool
        ))
    ) {
      return false;
    }

    if (
      this.configuration.betCategory === BetCategoryType.SportsFixedOdds ||
      this.configuration.betCategory === BetCategoryType.VirtualFixedOdds ||
      this.configuration.betCategory === BetCategoryType.SportsPool
    ) {
      if (
        this.betLines.some(bl => bl.leftoverBalanceAmount) &&
        (!this.amounts.useFreeBet ||
          selectedCoupon.useLeftOver ||
          (this.completeMyBetService.completeMyBetInfo?.betId &&
            this.completeMyBetService.completeMyBetInfo?.freebetCouponId === selectedCoupon.id))
      ) {
        return true;
      }

      if (
        this.betSlipMode === BetSlipMode.Simple &&
        this.betLines.some(betLine => !this.isBetLineAmountValid(betLine, null, balance))
      ) {
        return false;
      }

      const increment =
        this.betLines.length === 1
          ? this.betLines[0].minimumAmountIncrement
          : ppcmArr(this.betLines.map(b => b.minimumAmountIncrement));
      if (
        this.betSlipMode !== BetSlipMode.Simple &&
        (this.amounts.summary.totalStakeWithTax < Math.max(...this.betLines.map(l => l.baseAmount)) ||
          this.amounts.summary.totalStakeWithTax > Math.min(...this.betLines.map(l => l.maximumAmount)) ||
          (mod(this.amounts.summary.totalStakeWithTax, increment) !== 0 &&
            !(
              this.scope === Scope.Customer &&
              balance != null &&
              areClose(this.amounts.summary.totalStakeWithTax, balance, 1e-2)
            )))
      ) {
        return false;
      }
    }

    if (this.betSlipMode === BetSlipMode.Simple) {
      if (this.configuration.betCategory === BetCategoryType.SportsFixedOdds) {
        if ((this.operatorConfiguration.betSlipModeSimpleConfiguration?.allowSingleBetOnSports ?? true) === false) {
          return false;
        }
      }

      if (this.configuration.betCategory === BetCategoryType.VirtualFixedOdds) {
        if ((this.operatorConfiguration.betSlipModeSimpleConfiguration?.allowSingleBetOnVirtual ?? true) === false) {
          return false;
        }
      }
    }

    return (
      !this.betLines.some(l => !betLineIsValid(l) || (!!l.newOdds && l.odds !== l.newOdds)) &&
      this.amounts.values.map(v => v.amount).some(x => x > 0)
    );
  }

  private isPayoutValid(): boolean {
    if (this.betSlipMode === BetSlipMode.Simple && this.amounts.values?.length > 0) {
      return !this.amounts.values
        .filter(x => x.payout !== null)
        .some(i => i.payout === 0 || (!this.amounts.useFreeBet && i.amount >= i.payout));
    }

    if (
      this.betSlipMode === BetSlipMode.Multiple &&
      this.amounts.summary.totalStakeWithTax !== null &&
      this.amounts.summary.maxPayout !== null
    ) {
      return !(
        this.amounts.summary.maxPayout === 0 ||
        (!this.amounts.useFreeBet && this.amounts.summary.totalStakeWithTax >= this.amounts.summary.maxPayout)
      );
    }

    return true;
  }

  private isBetLineAmountValid(betLine: BetLine, amount?: number, balance?: number): boolean {
    let currentAmount: number;

    if (amount) {
      currentAmount = amount;
    } else {
      const itemIndex = getBetLineIndex(betLine, this.betLines);
      if (itemIndex === -1) {
        return false;
      }

      currentAmount = this.amounts.values[itemIndex].amount;
    }

    return (
      (!betLine.baseAmount || currentAmount >= betLine.baseAmount) &&
      (!betLine.maximumAmount || currentAmount <= betLine.maximumAmount) &&
      (!betLine.minimumAmountIncrement ||
        mod(currentAmount, betLine.minimumAmountIncrement) === 0 ||
        (this.scope === Scope.Customer && balance != null ? areClose(currentAmount, balance, 1e-2) : false))
    );
  }

  setAcceptOddChange(acceptOddChange: boolean) {
    this.acceptOddChange = acceptOddChange;
    if (this.acceptOddChange) {
      this.applyNewOdds();
    }
  }

  applyNewOdds() {
    if (this.isLocked) {
      return;
    }

    let applied = false;

    this.betLines.forEach((line, i) => {
      if (line.newOdds) {
        this.betLines[i] = { ...line, odds: line.newOdds, newOdds: null, failure: undefined };
        applied = true;
      }
    });

    if (applied) {
      this.updateAmountsForOddsChanges();
    }
  }

  changeMode(mode: BetSlipMode, markAsPersistent?: boolean): boolean {
    if (this.isLocked || this.betSlipMode === mode) {
      return false;
    }

    if (!this.persistedMode) {
      this.persistedMode = markAsPersistent;
    }

    const targetBetSlip: IBetSlipModeHandler = this.getBetSlipModeHandler(mode);
    if (targetBetSlip.canBeInMode(this.betLines)) {
      targetBetSlip.initBetSlip(
        this.betLines,
        this.amounts,
        this.lastBetStakePerBetCategory?.[this.configuration.betCategory]?.amount,
        undefined,
        this.getDefaultBetSlipStake()
      );
      this.betSlipMode = mode;
      this.modeSubject.next(this.betSlipMode);
      this.betSlipModeHandler = targetBetSlip;

      this.computeLeftoverBalanceBetLines();
      this.computeFreeBetCouponBetLineAmount();

      this.computeAmounts();
      this.amountsSubject.next(this.amounts);

      this.computeFreeBetCouponsRequirements();

      this.saveBetSlip();

      return true;
    }
    return false;
  }

  changeType(type: BetSlipType): boolean {
    if (this.betSlipType === type) {
      return false;
    }

    this.betSlipType = type;
    this.computeAmounts();
    this.saveBetSlip();
    return true;
  }

  rehydrateFromBetCode(betCode: string): Observable<BetCodeResponse> {
    return this.getBetFromBetCode(betCode).pipe(
      map((betCodeBet: BetCodeBet) => {
        if (!betCodeBet?.betLines) {
          return { failure: BetCodeFailures.NoBetFound };
        }

        if (
          this.scope === Scope.Agent &&
          betCodeBet.betLines.some(betLine => !!(betLine as BetCodeOddsBoostBetLine).oddsBoost)
        ) {
          return { failure: BetCodeFailures.BetCodeContainsOddsBoost };
        }

        this.applyBetCodeBet(betCodeBet, betCode);
        return {
          failure: null,
          betSystemType: betCodeBet.betSystemType,
          betCategory: betCodeBet.betCategory,
          hasBetBuilderBetLines: betCodeBet.hasBetBuilderBetLines
        };
      })
    );
  }

  private applyBetCodeBet(betCodeBet: BetCodeBet, betCode: string): void {
    this.unLock();
    this.changeCurrentBetCategory(betCodeBet.betCategory);
    this.clear();
    this.persistedMode = true;
    const targetMode = convertBetSystemTypeToBetSlipMode(betCodeBet.betSystemType);
    if (
      targetMode === BetSlipMode.Multiple &&
      this.configuration.availableBetSlipMode.indexOf(BetSlipMode.Multiple) !== -1
    ) {
      this.betSlipModeHandler = new BetSlipMultipleModeHandler(this.operatorConfiguration);
      this.betSlipMode = BetSlipMode.Multiple;
      this.amounts.values = [{ amount: 0 }];
      this.modeSubject.next(this.betSlipMode);
    }
    const linesToAdd = betCodeBet.betLines
      .map(betLine => ({ source: betLine, betLine: this.toBetLine(betLine, betCodeBet) }))
      .filter(item => !!item.betLine);
    linesToAdd.forEach(item => this.addBetLine(item.betLine, undefined, true));
    let hasAppliedPerLineStake: boolean = false;
    linesToAdd.forEach((item, index) => {
      const stake: number =
        (
          item.source as
            | BetCodeEventBetLine
            | BetCodeDrawGameBetLine
            | BetCodeOddsBoostBetLine
            | BetCodeManualOddsBoostBetLine
        )?.stake ?? 0;
      const line: BetLine = this.betLines[index];
      if (stake > 0 && line) {
        this.updateBetLine(line, stake);
        hasAppliedPerLineStake = true;
      }
    });
    if (!hasAppliedPerLineStake) {
      this.applyStake(betCodeBet.totalStake);
    }
    this.setAcceptOddChange(true);
    this.betCode = betCode;
  }

  private toBetLine(
    line: BetCodeEventBetLine | BetCodeOddsBoostBetLine | BetCodeManualOddsBoostBetLine | BetCodeDrawGameBetLine,
    betCodeBet: BetCodeBet
  ): BetLine | null {
    const oddsBoost = (line as BetCodeOddsBoostBetLine).oddsBoost;
    if (oddsBoost) {
      return createOddsBoostBetLine(oddsBoost);
    }

    const manualOddsBoost = (line as BetCodeManualOddsBoostBetLine).manualOddsBoost;
    if (manualOddsBoost) {
      return createManualOddsBoostBetLine(manualOddsBoost);
    }

    const drawGameBetLine = line as BetCodeDrawGameBetLine;
    if (betCodeBet.betCategory === BetCategoryType.DrawGame) {
      return createBetLineWithSelection(
        drawGameBetLine.event,
        drawGameBetLine.eventBetType,
        drawGameBetLine.baseList,
        drawGameBetLine.extraList,
        BetCategoryType.DrawGame,
        drawGameBetLine.drawGameRule,
        undefined,
        undefined,
        drawGameBetLine.stakeMultiplier ?? 1,
        undefined,
        undefined,
        drawGameBetLine.option,
        drawGameBetLine.associatedDrawGames as unknown as number[]
      );
    }

    const eventLine = line as BetCodeEventBetLine;
    // An event line without a valid event (e.g. truncated funbet) must not produce an empty betline
    if (!eventLine.event || !eventLine.eventBetType || !eventLine.eventBetTypeItem) {
      return null;
    }

    return createBetLine(
      eventLine.event,
      eventLine.eventBetType,
      eventLine.eventBetTypeItem,
      BetCategoryType.SportsFixedOdds
    );
  }

  private applyStake(totalStake: number | undefined): void {
    const firstLine: BetLine = this.betLines?.[0];
    if (!totalStake || !firstLine) {
      return;
    }

    const amount: number = this.isBetLineAmountValid(firstLine, totalStake) ? totalStake : firstLine.baseAmount;

    this.updateBetLine(firstLine, amount);
  }

  changeCurrentBetCategory(betCategoryType: BetCategoryType) {
    if (betCategoryType !== this.configuration.betCategory) {
      this.configuration.betCategory = betCategoryType;
      this.rehydrateBetSlip(betCategoryType);
    }
  }

  computeAmount(betLine: BetLine, baseAmount: number = null): { betLine: BetLine; amount: number } {
    let result = null;

    if (
      betLine.betCategoryType === BetCategoryType.HorseRacingMutualInternationalPool ||
      betLine.betCategoryType === BetCategoryType.HorseRacingMutualOperatorPool
    ) {
      result = computeAmountForHorseRacing(betLine);
    } else if (betLine.betCategoryType === BetCategoryType.DrawGame && betLine.entryPointId !== 9003) {
      result = computeAmountForDrawGames(betLine);
    }

    if (!!result && !!baseAmount) {
      result.amount = result.amount < baseAmount ? baseAmount : result.amount;
    }

    return result;
  }

  private get isCustomerOrKiosk(): boolean {
    return this.scope === Scope.Customer || this.scope === Scope.Kiosk;
  }

  private get isSportsFixedOdds(): boolean {
    return this.configuration.betCategory === BetCategoryType.SportsFixedOdds;
  }

  private get isBetCodeActivatedForDrawGames(): boolean {
    return (
      this.configuration.betCategory === BetCategoryType.DrawGame &&
      this.operatorConfiguration.betCodeConfiguration?.activeForDrawGame
    );
  }

  private configureBetSlip(): void {
    this.configureBetCode();
    this.configureAcceptOddChange();
    this.configureAvailableBetSlipModes();
    this.configurePushSubscription();

    if (this.scope === Scope.Customer) {
      this.refreshFreeBetCoupons();
    }

    this.configurationSubject.next(this.configuration);
  }

  private hasFeature(feature: string): boolean {
    return this.operatorConfiguration.operatorFeatures.includes(feature);
  }

  private configureBetCode(): void {
    this.configuration.betCodeAvailable =
      this.isCustomerOrKiosk &&
      (this.isSportsFixedOdds || this.isBetCodeActivatedForDrawGames) &&
      this.hasFeature('BetCode');
  }

  private configureAcceptOddChange(): void {
    this.configuration.acceptOddChangeAvailable = this.isCustomerOrKiosk
      ? this.isSportsFixedOdds
      : this.isSportsFixedOdds && this.operatorConfiguration.global.sportFixedOddsAcceptOddChangeAvailable;
  }

  private configureAvailableBetSlipModes(): void {
    const modes: BetSlipMode[] = [BetSlipMode.Simple];

    const isFixedOdds: boolean =
      this.isSportsFixedOdds || this.configuration.betCategory === BetCategoryType.VirtualFixedOdds;

    if (isFixedOdds && this.hasFeature(Feature.BetSlipModeMultiple)) {
      modes.push(BetSlipMode.Multiple);
    }

    if (this.isSportsFixedOdds && this.hasFeature(Feature.BetSlipModeSystem)) {
      modes.push(BetSlipMode.Systems);
    }

    this.configuration.availableBetSlipMode = modes;
  }

  private configurePushSubscription(): void {
    if (this.isSportsFixedOdds) {
      this.subscribeToPush();
    } else {
      this.unsubscribeFromPush();
    }
  }

  private unsubscribeFromPush(): void {
    this.eventChangedSubscription?.unsubscribe();
    this.eventChangedSubscription = null;

    this.eventBetTypeChangedSubscription?.unsubscribe();
    this.eventBetTypeChangedSubscription = null;

    this.manualOddsPushSubscription?.unsubscribe();
    this.manualOddsPushSubscription = null;
  }

  private updateAmountsForOddsChanges() {
    this.linesSubject.next({
      reason: BetLineChangeReason.OddChange,
      lines: this.betLines,
      instantGameTransactions: this.instantGameTransactions
    });
    this.computeAmounts();
    this.amountsSubject.next(this.amounts);

    this.computeFreeBetCouponsRequirements();

    this.saveBetSlip();
  }

  private computeAmounts() {
    this.computeBonus();
    this.betSlipModeHandler.computeBetSlipSummary(this.betLines, this.amounts);
  }

  configureLeftoverBalanceBetlines(reset = false) {
    this.computeLeftoverBalanceBetLines(reset, true);
  }

  private computeLeftoverBalanceBetLines(reset = false, externalTrigger = false) {
    const canUseLeftoverBalanceObs: Observable<{ result: boolean; amount: number }> =
      this.completeMyBetService.completeMyBetInfo?.betId && this.amounts.values[0]?.amount
        ? of({ result: true, amount: this.amounts.values[0].amount })
        : this.betValidationService.canUseLeftoverBalance(
            this.configuration.betCategory,
            this.betLines,
            this.amounts.useFreeBet,
            this.betSlipFreebetService.selectedCoupon
          );
    canUseLeftoverBalanceObs.subscribe(canUseLeftoverBalance => {
      if (!reset && canUseLeftoverBalance.result) {
        if (this.betSlipMode === BetSlipMode.Multiple) {
          this.amounts.values = [{ amount: canUseLeftoverBalance.amount }];
        }

        this.betLines.forEach(betLine => {
          betLine.leftoverBalanceAmount = canUseLeftoverBalance.amount;
        });

        this.amounts.values = this.betLines.map(_l => {
          return { amount: canUseLeftoverBalance.amount };
        });

        if (externalTrigger) {
          this.computeAmounts();

          this.amountsSubject.next(this.amounts);
          this.linesSubject.next({
            reason: BetLineChangeReason.StateChange,
            lines: this.betLines,
            instantGameTransactions: this.instantGameTransactions
          });
        }
      } else {
        if (this.betLines?.some(bl => bl.leftoverBalanceAmount)) {
          if (this.betSlipMode === BetSlipMode.Multiple) {
            this.amounts.values = [{ amount: Math.max(...this.betLines.map(l => l.baseAmount)) }];
          }
          this.betLines.forEach(betLine => {
            if (betLine.leftoverBalanceAmount) {
              betLine.leftoverBalanceAmount = null;
            }
          });

          if (externalTrigger) {
            this.computeAmounts();

            this.amountsSubject.next(this.amounts);

            this.linesSubject.next({
              reason: BetLineChangeReason.StateChange,
              lines: this.betLines,
              instantGameTransactions: this.instantGameTransactions
            });
          }
          this.betSlipModeHandler.initBetSlip(
            this.betLines,
            this.amounts,
            this.lastBetStakePerBetCategory?.[this.configuration.betCategory]?.amount,
            undefined,
            this.getDefaultBetSlipStake()
          );
        }
      }
    });
  }

  private computeBonus() {
    if (
      this.configuration.betCategory === BetCategoryType.SportsFixedOdds &&
      this.operatorConfiguration.multipleBonus &&
      !this.amounts.useFreeBet &&
      this.betSlipMode === BetSlipMode.Multiple &&
      this.betSlipType === BetSlipType.Real
    ) {
      const eligibleBetLines = this.betLines.filter(
        b => b.odds >= this.operatorConfiguration.multipleBonus.minimumOdds
      );

      const applyableBonus = this.operatorConfiguration.multipleBonus.bonus.filter(
        x => x.linesNumber <= eligibleBetLines.length
      );
      const currentBonus = applyableBonus.length
        ? applyableBonus.reduce((prev, cur) => (prev.linesNumber > cur.linesNumber ? prev : cur))
        : null;

      const availableBonus = this.operatorConfiguration.multipleBonus.bonus.filter(
        x => x.linesNumber > eligibleBetLines.length
      );
      const nextBonus = availableBonus.length
        ? availableBonus.reduce((prev, cur) => (prev.linesNumber < cur.linesNumber ? prev : cur))
        : null;

      if (currentBonus) {
        this.amounts.bonus = {
          percentage: (currentBonus.coefficient - 1).toFixed(4),
          minimumStake: this.operatorConfiguration.multipleBonus.minimumStake,
          ...currentBonus
        };
      } else {
        this.amounts.bonus = null;
      }

      if (nextBonus) {
        this.amounts.nextBonus = {
          percentage: (nextBonus.coefficient - 1).toFixed(4),
          linesToAdd: nextBonus.linesNumber - eligibleBetLines.length,
          minimalOdds: this.operatorConfiguration.multipleBonus.minimumOdds,
          minimumStake: this.operatorConfiguration.multipleBonus.minimumStake,
          ...nextBonus
        };
      } else {
        this.amounts.nextBonus = null;
      }
    } else {
      this.amounts.bonus = null;
      this.amounts.nextBonus = null;
    }
  }

  private catchBetSlipRequestError(err: BettingError) {
    if (err.betLinesFailures) {
      this.betLines.map(x => (x.failure || x.newStake ? { ...x, failure: undefined, newStake: undefined } : x));

      err.betLinesFailures.forEach((betLineError: BetLineError) => {
        const failure = getBetFailurePerPriority(betLineError.reason.map(r => r.failure));
        const indexes: BetLineErrorIndexes = this.getBetLineIndexes(betLineError);
        if (
          this.betLines[indexes.betLineIndex].isBetBuilder &&
          this.betLines[indexes.betLineIndex].betBuilderLines?.length &&
          failure !== BetLineFailure.FixedOddsChanged
        ) {
          this.handleBetSlipBetBuilderError(betLineError, indexes);
        } else if (failure === BetLineFailure.StakeError || failure === BetLineFailure.MaximumAmountError) {
        } else if (failure === BetLineFailure.FixedOddsChanged) {
          this.betLines[indexes.betLineIndex] = {
            ...this.betLines[indexes.betLineIndex],
            newOdds: betLineError.reason.find(r => r.failure === failure).data
          };
        } else if (failure === BetLineFailure.MaximumRiskReached) {
          const newStake = betLineError.reason.find(r => r.failure === failure).data;
          this.betLines[indexes.betLineIndex] = {
            ...this.betLines[indexes.betLineIndex],
            failure: !newStake ? failure : null,
            newStake: newStake
          };
        } // Error state of initial bet lines during a bet completion should not be, for now, displayed.
        else if (
          failure !== BetLineFailure.EventStateNotCompletable &&
          failure !== BetLineFailure.LineStateNotCompletable
        ) {
          this.betLines[indexes.betLineIndex] = { ...this.betLines[indexes.betLineIndex], failure: failure };
        }
      });

      this.linesSubject.next({
        reason: BetLineChangeReason.StateChange,
        lines: this.betLines,
        instantGameTransactions: this.instantGameTransactions
      });
    }

    return throwError(err);
  }

  private catchBetSlipForBetCodeRequestError(err: BettingError) {
    let hasStakeOrMaximumAmountError = false;
    let hasIncompatibleStakeError = false;
    let minimumBaseAmount = null;
    this.betLines.map(x => (x.failure || x.newStake ? { ...x, failure: undefined, newStake: undefined } : x));

    if (err.betLinesFailures) {
      err.betLinesFailures.forEach((betLineError: BetLineError) => {
        const failure = getBetFailurePerPriority(betLineError.reason.map(r => r.failure));
        const indexes: BetLineErrorIndexes = this.getBetLineIndexes(betLineError);

        if (failure === BetLineFailure.StakeError || failure === BetLineFailure.MaximumAmountError) {
          hasStakeOrMaximumAmountError = true;
        } else if (failure === BetLineFailure.IncompatibleStake) {
          hasIncompatibleStakeError = true;
          minimumBaseAmount = betLineError.reason.find(r => r.failure === failure).data;
        } else if (failure === BetLineFailure.FixedOddsChanged) {
          this.betLines[indexes.betLineIndex] = {
            ...this.betLines[indexes.betLineIndex],
            failure: failure,
            newOdds: betLineError.reason.find(r => r.failure === failure).data
          };
        } else if (failure === BetLineFailure.MaximumRiskReached) {
          const newStake = betLineError.reason.find(r => r.failure === failure).data;
          this.betLines[indexes.betLineIndex] = {
            ...this.betLines[indexes.betLineIndex],
            failure: !newStake ? failure : null,
            newStake: newStake
          };
        } else if (
          failure !== BetLineFailure.EventStateNotCompletable &&
          failure !== BetLineFailure.LineStateNotCompletable
        ) {
          this.betLines[indexes.betLineIndex] = { ...this.betLines[indexes.betLineIndex], failure: failure };
        }
      });

      this.linesSubject.next({
        reason: BetLineChangeReason.StateChange,
        lines: this.betLines,
        instantGameTransactions: this.instantGameTransactions
      });
    }

    if (hasIncompatibleStakeError && minimumBaseAmount) {
      err.data = minimumBaseAmount;
      err.failure = CreateBetFailures.IncompatibleStake;
    } else if (hasStakeOrMaximumAmountError) {
      err.failure = CreateBetFailures.IncoherentTotalStakeOrMaxPayout;
    }

    return throwError(err);
  }

  private getBetLineIndexes(betLineError: BetLineError): BetLineErrorIndexes {
    const targetIndex = betLineError.number - 1;

    const betLineErrorIndexes: BetLineErrorIndexes[] = this.betLines.reduce(
      (indexes: BetLineErrorIndexes[], betLine: BetLine, betLineIndex: number) => {
        if (betLine.isBetBuilder && betLine.betBuilderLines?.length) {
          betLine.betBuilderLines.forEach((_, betBuilderLineIndex: number) =>
            indexes.push({ betLineIndex, betBuilderLineIndex })
          );
        } else {
          indexes.push({ betLineIndex, betBuilderLineIndex: undefined });
        }
        return indexes;
      },
      []
    );
    return betLineErrorIndexes[targetIndex];
  }

  private handleBetSlipBetBuilderError(betLineError: BetLineError, indexes: BetLineErrorIndexes): void {
    this.betLines[indexes.betLineIndex] = {
      ...this.betLines[indexes.betLineIndex],
      betBuilderLines: this.betLines[indexes.betLineIndex].betBuilderLines.map(
        (betBuilderLine: BetBuilderLine, index: number) => ({
          ...betBuilderLine,
          betBuilderError:
            betLineError.reason.length && index === indexes.betBuilderLineIndex
              ? betLineError.reason[0].data?.betBuilderError ?? BetBuilderError.IneligibleSelection
              : undefined,
          betBuilderErrorParameters:
            betLineError.reason.length && index === indexes.betBuilderLineIndex
              ? betLineError.reason[0].data?.betBuilderErrorParameters
              : undefined
        })
      ),
      failure: undefined
    };
  }

  private registerPush() {
    const subscribedBetLines: BetLine[] = this.betLines.filter((betLine: BetLine) => !betLine.isBetBuilder);
    const eventBetTypeIds: number[] = this.betLinesMapperService.betLinesToEventBetTypeIds(subscribedBetLines);
    this.pushService.subscribeToOdds(eventBetTypeIds, [], 'betSlip');

    this.pushService.subscribeToEvents(
      this.betLines.map(bl => bl.eventId),
      'betSlip'
    );
  }

  private subscribeToPush() {
    this.eventBetTypeChangedSubscription = this.pushService.eventBetTypeChanged$.subscribe(changed => {
      const lines = this.betLines
        .map((line, index) => ({ line, index }))
        .filter(
          x =>
            (x.line.eventBetTypeId === changed.eventBetTypeId ||
              (x.line.oddsBoostId &&
                x.line.oddsBoost.details.some(d => d.eventBetType.id === changed.eventBetTypeId))) &&
            !x.line.isBetCompletion
        );
      if (lines.length) {
        let applied = false;
        lines.forEach(line => {
          if (line.line.oddsBoostId) {
            if (updateOddsBoostAfterPush(line.line.oddsBoost, changed)) {
              line.line.active = line.line.oddsBoost.active;
              line.line.bettingAllowed = line.line.oddsBoost.active;

              const betLineChanges: any = {
                active: line.line.oddsBoost.active,
                bettingAllowed: line.line.oddsBoost.active
              };

              if (this.acceptOddChange) {
                betLineChanges.odds = line.line.oddsBoost.fixedOdds;
              } else {
                betLineChanges.newOdds = line.line.oddsBoost.fixedOdds;
              }

              this.betLines[line.index] = {
                ...this.betLines[line.index],
                ...betLineChanges
              };
            }
          } else {
            const betLineChanges: any = {};
            betLineChanges.active = changed.active == null ? this.betLines[line.index].active : changed.active;
            betLineChanges.bettingAllowed =
              changed.bettingAllowed == null ? this.betLines[line.index].bettingAllowed : changed.bettingAllowed;

            if (changed.items) {
              const item = changed.items.find(
                x => x.eventBetTypeItemId === this.betLines[line.index].eventBetTypeItemId
              );
              if (item) {
                if (this.acceptOddChange) {
                  betLineChanges.odds = item.odds;
                  applied = true;
                } else {
                  betLineChanges.newOdds = item.odds;
                }

                if (item.bettingAllowed !== null && item.bettingAllowed !== undefined) {
                  betLineChanges.bettingAllowed = betLineChanges.bettingAllowed && item.bettingAllowed;
                }
              }
            }

            this.betLines[line.index] = { ...this.betLines[line.index], ...betLineChanges };
          }
        });

        this.betLines = this.betLines.slice(0);
        if (!this.isLocked) {
          this.linesSubject.next({
            reason: BetLineChangeReason.OddChange,
            lines: this.betLines,
            instantGameTransactions: this.instantGameTransactions
          });
        }

        if (applied) {
          this.updateAmountsForOddsChanges();
        }
      }
    });

    this.eventChangedSubscription = this.pushService.eventChanged$.subscribe(changed => {
      const lines = this.betLines
        .map((line, index) => ({ line, index }))
        .filter(
          x =>
            (x.line.eventId === changed.eventId ||
              (x.line.oddsBoostId && x.line.oddsBoost.details.some(d => d.event.id === changed.eventId))) &&
            !x.line.isBetCompletion
        );
      if (lines.length) {
        lines.forEach(line => {
          const patch: any = {};
          if (changed.changes['state']) {
            if (line.line.isLive) {
              patch.disabled = changed.changes['state'] !== EventStateType.Started;
            } else {
              patch.disabled =
                changed.changes['state'] !== EventStateType.AboutToStart &&
                changed.changes['state'] !== EventStateType.Undisputed &&
                changed.changes['state'] !== EventStateType.Delayed;
            }
            patch.state = changed.changes['state'];
          }
          if (changed.changes['betStop'] !== undefined) {
            this.betLines[line.index].bettingAllowed = !changed.changes['betStop'];
          }
          this.betLines[line.index] = {
            ...line.line,
            ...patch
          };
        });
        this.betLines = this.betLines.slice(0);

        if (!this.isLocked) {
          this.linesSubject.next({
            reason: BetLineChangeReason.StateChange,
            lines: this.betLines,
            instantGameTransactions: this.instantGameTransactions
          });
        }
      }
    });

    this.manualOddsPushSubscription = this.pushService.manualOddsChanged$.subscribe(changed => {
      if (changed && changed.oddsBoostId && changed.changes) {
        const lines = this.betLines
          .map((line, index) => ({ line, index }))
          .filter(x => x.line.manualOddsBoostId && x.line.manualOddsBoostId === changed.oddsBoostId);
        if (lines.length) {
          lines.forEach(line => {
            const patch: any = {};
            patch.manualOddsBoost = {
              ...line.line.manualOddsBoost
            };

            if (changed.changes.baseAmount) {
              patch.baseAmount = changed.changes.baseAmount;
            }

            if (changed.changes.minimumAmountIncrement) {
              patch.minimumAmountIncrement = changed.changes.minimumAmountIncrement;
            }

            if (changed.changes.maximumAmount) {
              patch.maximumAmount = changed.changes.maximumAmount;
            }

            if (changed.changes.newOdds) {
              patch.fixedOdds = changed.changes.newOdds;
            }

            if (changed.changes.expirationDate) {
              patch.manualOddsBoost.expirationDate = changed.changes.expirationDate;
            }

            if (this.acceptOddChange) {
              patch.odds = changed.changes.newOdds;
            } else {
              patch.newOdds = changed.changes.newOdds;
            }

            this.betLines[line.index] = {
              ...line.line,
              ...patch
            };
          });
          this.betLines = this.betLines.slice(0);

          if (!this.isLocked) {
            this.linesSubject.next({
              reason: BetLineChangeReason.OddChange,
              lines: this.betLines,
              instantGameTransactions: this.instantGameTransactions
            });
          }

          this.updateAmountsForOddsChanges();
        }

        if (this.lastBetSelectionPerBetCategory[this.configuration.betCategory]) {
          const lines = this.lastBetSelectionPerBetCategory[this.configuration.betCategory]?.betLines
            .map((line, index) => ({ line, index }))
            .filter(x => x.line.manualOddsBoostId && x.line.manualOddsBoostId === changed.oddsBoostId);

          if (lines?.length) {
            lines.forEach(line => {
              const patch: any = {};
              patch.manualOddsBoost = {
                ...line.line.manualOddsBoost
              };

              if (changed.changes.baseAmount) {
                patch.baseAmount = changed.changes.baseAmount;
              }

              if (changed.changes.minimumAmountIncrement) {
                patch.minimumAmountIncrement = changed.changes.minimumAmountIncrement;
              }

              if (changed.changes.maximumAmount) {
                patch.maximumAmount = changed.changes.maximumAmount;
              }

              if (changed.changes.newOdds) {
                patch.fixedOdds = changed.changes.newOdds;
              }

              if (changed.changes.expirationDate) {
                patch.manualOddsBoost.expirationDate = changed.changes.expirationDate;
              }

              if (this.acceptOddChange) {
                patch.odds = changed.changes.newOdds;
              } else {
                patch.newOdds = changed.changes.newOdds;
              }

              this.lastBetSelectionPerBetCategory[this.configuration.betCategory].betLines[line.index] = {
                ...line.line,
                ...patch
              };
            });
            this.lastBetSelectionPerBetCategory[this.configuration.betCategory].betLines =
              this.lastBetSelectionPerBetCategory[this.configuration.betCategory].betLines.slice(0);
          }
        }
      }
    });
  }

  saveLastBetStakePerBetCategory(amount: number): void {
    this.lastBetStakePerBetCategory[this.configuration.betCategory] = {
      amount
    };
    this.storageService.setItem(lastBetStakePerBetCategoryStorageKey, this.lastBetStakePerBetCategory);
  }

  getLastBetStakePerBetCategory(): {
    [betCategoryType: string]: {
      amount: number;
    };
  } {
    return this.storageService.getItem(lastBetStakePerBetCategoryStorageKey) || {};
  }

  saveLastSelection(betCategoryType: BetCategoryType) {
    if (
      betCategoryType !== BetCategoryType.InstantGame &&
      betCategoryType !== BetCategoryType.HorseRacingMutualInternationalPool &&
      betCategoryType !== BetCategoryType.HorseRacingMutualOperatorPool &&
      betCategoryType !== BetCategoryType.DrawGame
    ) {
      this.lastBetSelectionPerBetCategory[betCategoryType] = {
        betLines: this.betLines,
        amounts: (this.amounts.values ?? []).map(v => v?.amount ?? 0),
        mode: this.betSlipMode
      };
    }
  }

  getLastBetSelectionPerBetCategory() {
    return this.lastBetSelectionPerBetCategory;
  }

  getCurrentBetSlipType(): BetSlipType {
    return this.betSlipType;
  }

  refreshEvent() {
    this.refreshEventSubject.next();
  }

  setNotifyOnBetSystemTypeChange(value: boolean) {
    this.betSystemTypeChangeNotification = value;
  }

  refreshFreeBetCoupons() {
    this.betSlipFreebetService
      .canUseFreeBetCoupons(
        this.betSlipMode,
        this.configuration.betCategory,
        null,
        this.completeMyBetService.completeMyBetInfo?.freebetCouponId
      )
      .subscribe(canUseFreeBetCoupons => {
        this.handleCanUseFreeBetCouponsData(canUseFreeBetCoupons.result, canUseFreeBetCoupons.coupons);
      });
  }

  toggleFreeBetMode(active: boolean, forceRefresh = false) {
    if (!active && forceRefresh) {
      this.refreshFreeBetCoupons();
    }
    if (this.amounts.useFreeBet !== active) {
      this.amounts.useFreeBet = active;
      this.computeAmounts();
      if (active) {
        this.refreshFreeBetCoupons();
      }

      this.computeLeftoverBalanceBetLines(false, true);
      this.computeFreeBetCouponBetLineAmount();
      this.amountsSubject.next(this.amounts);
      this.saveBetSlip();
    }
  }

  onFreeBetCouponChange(coupon: FreeBetCouponBetSlip | null) {
    const previousCoupon: FreeBetCouponBetSlip | null = this.betSlipFreebetService.selectedCoupon;
    if (coupon) {
      this.betSlipFreebetService
        .canUseFreeBetCoupons(
          this.betSlipMode,
          this.configuration.betCategory,
          coupon,
          this.completeMyBetService.completeMyBetInfo?.freebetCouponId
        )
        .subscribe(canUseFreeBetCoupons => {
          if (canUseFreeBetCoupons.result) {
            this.computeLeftoverBalanceBetLines();
            if (previousCoupon?.id !== coupon.id) {
              this.computeFreeBetCouponBetLineAmount(previousCoupon?.freeBetRule.mustUseAllBalance);
            }
          }

          this.linesSubject.next({
            reason: BetLineChangeReason.FreebetCoupon,
            lines: this.betLines,
            instantGameTransactions: this.instantGameTransactions
          });

          this.computeAmounts();
          this.amountsSubject.next(this.amounts);

          this.handleCanUseFreeBetCouponsData(canUseFreeBetCoupons.result, canUseFreeBetCoupons.coupons);
        });
    } else if (this.betSlipFreebetService.selectedCoupon && !coupon) {
      this.removeSelectedFreeBetCoupon();
    }
  }

  configureBetSlipFreeBet(canUseFreeBet: boolean) {
    if (
      this.configuration?.betCategory !== BetCategoryType.SportsFixedOdds &&
      this.configuration?.betCategory !== BetCategoryType.VirtualFixedOdds &&
      this.configuration?.betCategory !== BetCategoryType.SportsPool
    ) {
      this.configuration.canUseFreeBet = false;
      this.configurationSubject.next(this.configuration);
      this.toggleFreeBetMode(false);
    } else if (canUseFreeBet !== this.configuration.canUseFreeBet) {
      this.configuration.canUseFreeBet = canUseFreeBet;
      this.configurationSubject.next(this.configuration);
      this.toggleFreeBetMode(this.completeMyBetService.completeMyBetInfo?.isFreebet);
      if (this.amounts.useFreeBet && this.completeMyBetService.completeMyBetInfo?.freebetCouponId) {
        this.betSlipFreebetService.selectCoupon(this.completeMyBetService.completeMyBetInfo?.freebetCouponId);
      }
    }

    if (this.betSlipFreebetService.selectedCoupon && !this.configuration.canUseFreeBet) {
      this.removeSelectedFreeBetCoupon();
    }
  }

  getEventBetLines(eventId: number): BetLine[] {
    return this.betLinesValue.filter((betLine: BetLine) => betLine.eventId === eventId);
  }

  private handleCanUseFreeBetCouponsData(result: boolean, coupons: FreeBetCoupon[]) {
    this.configureBetSlipFreeBet(result);
    this.betSlipFreebetService.handleCanUseFreeBetCouponsData(
      coupons,
      this.configuration.canUseFreeBet,
      this.completeMyBetService.completeMyBetInfo?.freebetCouponId
    );

    if (this.configuration.canUseFreeBet) {
      this.computeFreeBetCouponsRequirements();
    }
  }

  private removeSelectedFreeBetCoupon() {
    const selectedCoupon: FreeBetCouponBetSlip | null = this.betSlipFreebetService.selectedCoupon;
    if (selectedCoupon) {
      const lockedAmount = this.amounts.useFreeBet && selectedCoupon.useLeftOver;

      this.betSlipFreebetService.selectCoupon();

      if (lockedAmount) {
        this.betLines.forEach(betLine => {
          betLine.leftoverBalanceAmount = null;
        });
        if (this.betSlipMode === BetSlipMode.Multiple) {
          this.amounts.values = [{ amount: Math.max(...this.betLines.map(l => l.baseAmount)) }];
          this.amountsSubject.next(this.amounts);
        }
      }

      this.computeAmounts();
      this.amountsSubject.next(this.amounts);

      this.computeFreeBetCouponsRequirements();

      this.linesSubject.next({
        reason: BetLineChangeReason.FreebetCoupon,
        lines: this.betLines,
        instantGameTransactions: this.instantGameTransactions
      });

      if (lockedAmount) {
        this.betSlipModeHandler.initBetSlip(
          this.betLines,
          this.amounts,
          this.lastBetStakePerBetCategory?.[this.configuration.betCategory]?.amount,
          undefined,
          this.getDefaultBetSlipStake()
        );
      }

      this.saveBetSlip();
    }
  }

  private computeFreeBetCouponsRequirements() {
    if (this.configuration.canUseFreeBet) {
      this.betSlipFreebetService.computeFreeBetCouponsRequirements(
        this.betSlipMode,
        this.amounts,
        this.betLines,
        this.completeMyBetService.completeMyBetInfo?.freebetCouponId
      );
    }
  }

  private computeFreeBetCouponBetLineAmount(reset?: boolean) {
    const selectedCoupon: FreeBetCouponBetSlip | null = this.betSlipFreebetService.selectedCoupon;
    if (!!selectedCoupon && !selectedCoupon?.useLeftOver) {
      if (
        !!selectedCoupon?.freeBetRule.mustUseAllBalance &&
        (!this.completeMyBetService.completeMyBetInfo?.freebetCouponId ||
          this.completeMyBetService.completeMyBetInfo?.freebetCouponId !== selectedCoupon.id)
      ) {
        if (this.betSlipMode === BetSlipMode.Multiple) {
          this.amounts.values = [{ amount: selectedCoupon.balance }];
        } else if (this.betSlipMode === BetSlipMode.Simple) {
          this.amounts.values = this.betLines.map(_ => {
            return { amount: selectedCoupon.balance };
          });
        }
      } else if (reset) {
        if (this.betSlipMode === BetSlipMode.Multiple) {
          this.amounts.values = [{ amount: Math.max(...this.betLines.map(l => l.baseAmount)) }];
        }
        this.betSlipModeHandler.initBetSlip(
          this.betLines,
          this.amounts,
          this.lastBetStakePerBetCategory?.[this.configuration.betCategory]?.amount,
          undefined,
          this.getDefaultBetSlipStake()
        );
      }
    }
  }

  private clearStoredBetSlip(betCategoryType: BetCategoryType): void {
    const storageKey: string = betSlipStorageKey + betCategoryType.toLocaleLowerCase();
    this.storageService.removeItem(storageKey);
  }

  private unLockAndClearBetSlip(): void {
    this.unLock();
    this.clear();
  }

  private getBetSlipModeHandler(mode: BetSlipMode): IBetSlipModeHandler {
    let targetBetSlip: IBetSlipModeHandler;
    if (mode === BetSlipMode.Simple || this.configuration.availableBetSlipMode.indexOf(mode) === -1) {
      targetBetSlip = new BetSlipSimpleModeHandler(this.operatorConfiguration);
    } else if (mode === BetSlipMode.Multiple) {
      targetBetSlip = new BetSlipMultipleModeHandler(this.operatorConfiguration);
    } else {
      targetBetSlip = new BetSlipSystemsModeHandler(this.operatorConfiguration);
    }
    return targetBetSlip;
  }

  private getDefaultBetSlipStake(isBetCompletion: boolean = false): number | undefined {
    return this.scope === Scope.Agent || this.scope === Scope.Kiosk
      ? this.operatorConfiguration.bettingConfiguration?.defaultAgentBetSlipStake
      : isBetCompletion
      ? undefined
      : this.operatorConfiguration.bettingConfiguration?.defaultCustomerBetSlipStake;
  }
}

function getBetFailurePerPriority(failures: BetLineFailure[]) {
  if (failures.indexOf(BetLineFailure.FixedOddsChanged) > -1) {
    return BetLineFailure.FixedOddsChanged;
  }

  if (failures.indexOf(BetLineFailure.OfflineEvent) > -1) {
    return BetLineFailure.OfflineEvent;
  }

  if (failures.indexOf(BetLineFailure.UnknownBetType) > -1) {
    return BetLineFailure.UnknownBetType;
  }

  if (failures.indexOf(BetLineFailure.UnknownEventBetTypeItem) > -1) {
    return BetLineFailure.UnknownEventBetTypeItem;
  }

  if (failures.indexOf(BetLineFailure.TooEarly) > -1) {
    return BetLineFailure.TooEarly;
  }

  if (failures.indexOf(BetLineFailure.TooLate) > -1) {
    return BetLineFailure.TooLate;
  }

  if (failures.indexOf(BetLineFailure.EventStateNotCompatibleWithBetting) > -1) {
    return BetLineFailure.EventStateNotCompatibleWithBetting;
  }

  if (failures.indexOf(BetLineFailure.OfflineEventBetType) > -1) {
    return BetLineFailure.OfflineEventBetType;
  }

  if (failures.indexOf(BetLineFailure.UnavailableFixedOdds) > -1) {
    return BetLineFailure.UnavailableFixedOdds;
  }

  if (failures.indexOf(BetLineFailure.BettingNotAllowed) > -1) {
    return BetLineFailure.BettingNotAllowed;
  }

  if (failures.indexOf(BetLineFailure.DubiousFixedOdds) > -1) {
    return BetLineFailure.DubiousFixedOdds;
  }

  if (failures.indexOf(BetLineFailure.MaximumAmountError) > -1) {
    return BetLineFailure.MaximumAmountError;
  }

  if (failures.indexOf(BetLineFailure.IncompatibleStake) > -1) {
    return BetLineFailure.IncompatibleStake;
  }

  if (failures.indexOf(BetLineFailure.StakeError) > -1) {
    return BetLineFailure.StakeError;
  }

  if (failures.indexOf(BetLineFailure.FixedOddsChanged) > -1) {
    return BetLineFailure.FixedOddsChanged;
  }

  if (failures.indexOf(BetLineFailure.FixedOddsTooLow) > -1) {
    return BetLineFailure.FixedOddsTooLow;
  }

  if (failures.indexOf(BetLineFailure.PlayerIsMissing) > -1) {
    return BetLineFailure.PlayerIsMissing;
  }

  return failures[0];
}

export interface BetSlipConfiguration {
  betCategory: BetCategoryType;
  availableBetSlipMode: BetSlipMode[];
  betCodeAvailable: boolean;
  acceptOddChangeAvailable: boolean;
  canUseFreeBet: boolean;
  applyTaxToFreeBets: boolean;
  predefinedStakes?: number[];
}

interface BetSlipStorageModel {
  mode: BetSlipMode;
  betLines: BetLine[];
  instantGameTransactions: InstantGameTransaction[];
  lastModified: Date;
  amounts: number[];
  type: BetSlipType;
}
