import { Inject, Pipe, PipeTransform } from '@angular/core';
import { BetCategoryType, BetLineHistory, Event, EventType, Match } from '@honoregaming/types';
import { UrlFriendlyGeneratorService } from '../services/url-friendly-generator.service';
import { Scope, scopeToken } from '@honoregaming/core';
import { BetLine } from '@honoregaming/betslip';

@Pipe({
  name: 'hgEventLink',
  pure: false
})
export class EventLinkPipe implements PipeTransform {
  constructor(
    private urlFriendlyGeneratorService: UrlFriendlyGeneratorService,
    @Inject(scopeToken) public userScope: Scope
  ) {}
  transform(item: Event | BetLineHistory | BetLine): (string | number)[] {
    if ((item as Event).id) {
      return this.transformEvent(<Event>item);
    } else if ((item as BetLine).betCategoryType) {
      return this.transformBetLine(<BetLine>item);
    } else if (item as BetLineHistory) {
      const betLineHistory = <BetLineHistory>item;
      return this.buildSportLink(betLineHistory.eventId, betLineHistory.homeTeamName, betLineHistory.awayTeamName);
    }
  }

  private transformEvent(event: Event): (string | number)[] {
    if (event.isVirtual && event.eventType) {
      return this.buildVirtualLink(event.eventType, event.entryPointId, event.id);
    } else if (event.eventType === EventType.DrawGame) {
      return ['/draw-games', 'category', event.eventCategoryId || event.entryPointId, 'draw-game', event.id];
    }
    const match = <Match>event;
    return this.buildSportLink(match.id, match.homeTeamName, match.awayTeamName);
  }

  // toDo:: Uncomment return if we want to unify behaviors, currently eventId is used for betslip redirection and names for events redirection
  private transformBetLine(betLine: BetLine): (string | number)[] {
    if (betLine.betCategoryType === BetCategoryType.VirtualFixedOdds) {
      return this.buildVirtualLink(betLine.eventType, betLine.entryPointId, betLine.eventId);
    } else {
      // return this.buildSportLink(betLine.eventId, betLine.eventHomeTeamName, betLine.eventAwayTeamName);
      return ['/sports', 'event', betLine.eventId];
    }
  }

  private buildVirtualLink(eventType: EventType, entryPointId: number, eventId: number): (string | number)[] {
    switch (eventType) {
      case EventType.Match:
        return ['/virtual', 'category', entryPointId, 'match', eventId];

      case EventType.Race:
      case EventType.VirtualRace:
        return ['/virtual', 'category', entryPointId, 'race', eventId];

      case EventType.NumbersGame:
        return ['/virtual', 'category', entryPointId, 'numbers-game', eventId];
    }
  }

  private buildSportLink(eventId: number, homeTeamName: string, awayTeamName: string): (string | number)[] {
    if (this.userScope === Scope.Customer) {
      return [
        '/sports',
        'event',
        this.urlFriendlyGeneratorService.getUrlFriendlyText(homeTeamName) +
          '-' +
          this.urlFriendlyGeneratorService.getUrlFriendlyText(awayTeamName) +
          '-m' +
          eventId
      ];
    } else {
      return ['/sports', 'event', eventId];
    }
  }
}
