import { InstantGame } from './instant-game.model';

export const TournamentStatus = {
  Draft: 'Draft',
  Upcoming: 'Upcoming',
  Ongoing: 'Ongoing',
  Finished: 'Finished',
  Deleted: 'Deleted'
} as const;

export type TournamentStatus = typeof TournamentStatus[keyof typeof TournamentStatus];

export type TournamentFilter = TournamentStatus | 'ALL';
export interface InstantGameTournament {
  id: number;
  name: string;
  prizePool: number;
  totalFreeSpinAmount: number;
  freeSpinsCount: number;
  itemsCount: number;
  startDate: string;
  endDate: string;
  customerRanking: number;
  customerScore: number;
  isOptInNecessary: boolean;
  isCustomerAlreadyParticipating: boolean;
  isCustomerBlacklisted: boolean;
  isFinished: boolean;
  podiumMembers: PodiumMember[];
  instantGames: InstantGame[];
  status: TournamentStatus;
}

export interface PodiumMember {
  isMe: boolean;
  position: number;
  login: string;
  score: number;
  cashPrizeAmount?: number;
  freeSpinPrizeAmount?: number;
  freeSpinPrizeCount?: number;
}
