import {
  ChangeDetectionStrategy,
  Component,
  EventEmitter,
  Inject,
  Input,
  OnChanges,
  Output,
  SimpleChanges,
  TemplateRef
} from '@angular/core';
import { OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';
import { BetLine, BetLineAmount, BetSlipType, FreeBetCouponBetSlip } from '../../models';
import { getBetLineAmountErrorAndCode } from '../../utils';
import { BetBuilderLine, BetCategoryType, EventType } from '@honoregaming/types';
import { DestroySubject, Scope, scopeToken } from '@honoregaming/core';
import { I18nService } from '@honoregaming/i18n';
import { ppcmArr } from '../../helpers';
import { BetSlipBetBuilderService } from '@honoregaming/betslip';

@Component({
  selector: 'hg-bet-slip-multiple-mode',
  templateUrl: './bet-slip-multiple-mode.component.html',
  styleUrls: [
    './bet-slip-multiple-mode.component.scss',
    '../bet-lines/bet-line.scss',
    '../bet-lines/bet-line-content.scss'
  ],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class BetSlipMultipleModeComponent extends DestroySubject implements OnChanges {
  @Input()
  scope: Scope;
  @Input()
  predefinedStakes: number[];
  @Input()
  betCategory: BetCategoryType;
  @Input()
  betLines: BetLine[] = [];
  @Input()
  amounts: BetLineAmount[] = [];
  @Input()
  betLineTemplate: TemplateRef<any>;
  @Input()
  acceptOddChange: boolean;
  @Input()
  betSlipType: BetSlipType;
  @Input()
  currentMaxPayout: number;
  @Input()
  useFreeBet: boolean = false;
  @Input()
  selectedFreeBetCoupon: FreeBetCouponBetSlip;
  @Input()
  balance: number = 0;
  @Input()
  isUserConnected: boolean = false;
  @Input() isLoadingOddsEventIds: number[] = [];

  @Output()
  betSlipChange = new EventEmitter<{ amount: number; line: number }>();
  @Output()
  betLineRemove = new EventEmitter<BetLine>();

  currency = this.operatorConfiguration.currency.symbol;
  totalOdds: number;
  amount: number;
  baseAmount: number;
  increment: number;
  maxAmount: number;
  errorMessage?: string;
  errorCode?: string;
  betBuilderErrorMessage: string | null = null;
  amountLocked = false;

  EventType = EventType;
  BetCategoryType = BetCategoryType;
  Scope = Scope;

  useLeftOver: boolean;

  displayAllIn: boolean = false;
  newBetLines: BetLine[] = [];
  initialBetLines: BetLine[] = [];
  initialBetLinesOdds: number;

  constructor(
    private betSlipBetBuilderService: BetSlipBetBuilderService,
    private i18nService: I18nService,
    @Inject(operatorConfigurationToken) private operatorConfiguration: OperatorConfiguration,
    @Inject(scopeToken) private userScope: Scope
  ) {
    super();
  }

  ngOnChanges(changes: SimpleChanges) {
    if (changes.amounts) {
      this.amount = this.amounts[0].amount;
    }
    if (changes.betLines) {
      this.baseAmount = Math.max(...this.betLines.map(l => l.leftoverBalanceAmount || l.baseAmount));
      this.maxAmount = Math.min(...this.betLines.map(l => l.leftoverBalanceAmount || l.maximumAmount));
      this.increment =
        this.betLines.length === 1
          ? this.betLines[0].leftoverBalanceAmount || this.betLines[0].minimumAmountIncrement
          : this.betLines[0].leftoverBalanceAmount || ppcmArr(this.betLines.map(b => b.minimumAmountIncrement));

      this.totalOdds = this.calculateOdds(this.betLines);
      this.useLeftOver = this.betLines.some(b => b.leftoverBalanceAmount);
      this.amountLocked = this.useLeftOver;
      this.initCompleteMyBetLines();
      this.handleBetBuilderErrorChanges();
    }
    if (changes.selectedFreeBetCoupon || changes.isUserConnected || changes.balance || changes.useFreeBet) {
      this.updateAllInVisibility();
    }
  }

  onAmountChange() {
    this.betSlipChange.emit({ amount: this.amount, line: 0 });
  }

  onBetLineRemove(betLine: BetLine) {
    this.betLineRemove.emit(betLine);
  }

  onBetBuilderLineRemove(removedData: { betLine: BetLine; betBuilderLine: BetBuilderLine }) {
    this.betSlipBetBuilderService.removeBetBuilderLine(removedData.betLine.eventId, removedData.betBuilderLine);
  }

  onStakeSelected(stake: number) {
    this.amount = stake;
  }

  isValidAmount() {
    ({ error: this.errorMessage, code: this.errorCode } = getBetLineAmountErrorAndCode(
      this.i18nService,
      this.amount,
      this.baseAmount,
      this.maxAmount,
      this.increment,
      null,
      this.currentMaxPayout,
      this.useFreeBet,
      this.useFreeBet ? this.selectedFreeBetCoupon?.balance ?? 0 : this.balance,
      this.userScope
    ));
    return !this.errorMessage;
  }

  applyAllIn() {
    this.amount = this.selectedFreeBetCoupon ? this.selectedFreeBetCoupon.balance : this.balance;
    if (this.amount > 0) {
      this.onAmountChange();
    }
  }

  updateAllInVisibility() {
    this.displayAllIn =
      this.userScope === Scope.Customer &&
      (this.operatorConfiguration.bettingConfiguration?.displayAllInButton ?? false) &&
      (!this.isUserConnected ||
        (this.useFreeBet && this.selectedFreeBetCoupon != null) ||
        (!this.useFreeBet && this.balance > 0));
  }

  private initCompleteMyBetLines(): void {
    this.initialBetLines = [];
    this.newBetLines = [];
    this.betLines.forEach((betLine: BetLine) =>
      betLine.isBetCompletion ? this.initialBetLines.push(betLine) : this.newBetLines.push(betLine)
    );
    this.initialBetLinesOdds = this.calculateOdds(this.initialBetLines);
  }

  private calculateOdds(betLines: BetLine[]): number {
    return betLines.reduce((sum, l) => sum * l.odds, 1);
  }

  private handleBetBuilderErrorChanges(): void {
    this.betBuilderErrorMessage = this.betSlipBetBuilderService.getBetBuilderErrorMessage(this.betLines);
  }
}
