import {
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  ElementRef,
  Inject,
  Input,
  OnChanges,
  OnInit,
  SimpleChanges,
  ViewChild
} from '@angular/core';
import { NavigationEnd, Router } from '@angular/router';
import { filter, takeUntil } from 'rxjs/operators';
import {
  FreeBetCoupon,
  FreeBetType,
  ITransactionPopupService,
  TransactionMode,
  transactionPopupServiceToken
} from '@honoregaming/betslip';
import { DestroySubject, LocalStorageService } from '@honoregaming/core';
import {
  AuthService,
  CustomerOperatorConfiguration,
  customerOperatorConfigurationToken,
  Me,
  NavigationService,
  SmarticoService,
  TelemetryService
} from '@honoregaming/customer-core';
import { Media, MediaService } from '@honoregaming/ui';

@Component({
  selector: 'hg-account-status',
  templateUrl: './account-status.component.html',
  styleUrls: ['./account-status.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class AccountStatusComponent extends DestroySubject implements OnInit, OnChanges {
  @Input() newFreeBalance?: string;
  @Input() closePopup?: boolean;
  @Input() freeBetsWon?: number;
  @Input() actualFreeBalance?: number;
  @Input() storageId?: number;
  @Input() freeBets?: number;
  @Input() name?: string;
  @Input() actualFreeBetCoupons: FreeBetCoupon[] = [];
  @Input() newFreeBetCoupons: FreeBetCoupon[] = [];

  @ViewChild('freebetCount') freebetCount?: ElementRef;

  me?: Me;
  displayClock: boolean = this.customerOperatorConfiguration.complianceConfiguration?.displayClock;
  current?: number;
  routeHistoryAccount: string = '/myaccount/history';
  instantGamePath: string =
    this.customerOperatorConfiguration.betCategoriesPathConfiguration?.instantGamesConfiguration?.path ??
    'instant-games';
  readonly showSmarticoSelector: boolean = this.smarticoService.showSelector;

  freeBetMultiCouponActive: boolean = this.customerOperatorConfiguration.freeBetsConfiguration?.multiCouponEnabled;
  enablePopupMethodDeposit: boolean = this.customerOperatorConfiguration.depositConfiguration?.enablePopupMethod;

  constructor(
    private readonly authService: AuthService,
    private readonly cdRef: ChangeDetectorRef,
    private readonly navigationService: NavigationService,
    private readonly localStorageService: LocalStorageService,
    private readonly router: Router,
    private readonly telemetryService: TelemetryService,
    private readonly mediaService: MediaService,
    private readonly smarticoService: SmarticoService,
    @Inject(transactionPopupServiceToken) private readonly transactionPopupService: ITransactionPopupService,
    @Inject(customerOperatorConfigurationToken)
    private readonly customerOperatorConfiguration: CustomerOperatorConfiguration
  ) {
    super();
  }

  ngOnInit(): void {
    this.authService.me$.pipe(takeUntil(this.destroy$)).subscribe(me => {
      this.me = me;
      this.newFreeBalance = new Intl.NumberFormat('fr-FR').format(this.actualFreeBalance);
      if (this.me) {
        this.freeBets = this.me?.freeBalance;
      }
      this.cdRef.markForCheck();
    });

    this.setRouteHistoryAccount();
    this.router.events.pipe(filter(event => event instanceof NavigationEnd)).subscribe(() => {
      this.setRouteHistoryAccount();
    });
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes.actualFreeBalance) {
      this.newFreeBalance = new Intl.NumberFormat('fr-FR').format(this.actualFreeBalance);
      // Bug fix #15584 => Hack to make freebet balance changes visible after the execution of updateFreeBalance() function.
      // updateFreeBalance() is run for the animation when new freebet are available for the customer
      // With counter() function, Binding of property 'newFreeBalance' is broken, we need to update directly the dom element
      if (this.freebetCount) {
        this.freebetCount.nativeElement.textContent = this.newFreeBalance;
      }

      this.cdRef.markForCheck();
    }
  }

  logout(): void {
    this.trackEvent('loginoff_menu');
    this.authService.logout();
  }

  deposit(): void {
    if (this.enablePopupMethodDeposit) {
      this.transactionPopupService.open(TransactionMode.Deposit);
    } else {
      this.navigationService.goToDeposit();
    }
    this.trackEvent('deposit_button');
  }

  updateFreeBalance(type: FreeBetType): void {
    this.closePopup = true;

    if (type === 'freeBetBalance' && this.actualFreeBalance !== this.freeBets) {
      this.counter(this.actualFreeBalance, this.freeBets, 1000);
      this.localStorageService.setItem(this.name, this.freeBets);
    }

    this.cdRef.markForCheck();
  }

  counter(start: number, end: number, duration: number): void {
    let range: number = end - start;
    let increment: number = end > start ? 1 : -1;
    let step: number = Math.abs(Math.floor(duration / range));
    let timer: NodeJS.Timeout = setInterval(() => {
      if (this.actualFreeBalance + increment <= end) {
        this.actualFreeBalance += increment;
      } else {
        this.actualFreeBalance = end;
      }
      this.newFreeBalance = new Intl.NumberFormat('fr-FR').format(this.actualFreeBalance);
      this.freebetCount.nativeElement.textContent = this.newFreeBalance;

      if (this.actualFreeBalance === end) {
        clearInterval(timer);
      }
    }, step);
  }

  trackEvent(eventName: string): void {
    if (this.authService.isAuthenticated()) {
      this.telemetryService.trackEvent('header_click_loggedon', {
        shortcut_name: eventName,
        shortcut_device: this.mediaService?.media < Media.md ? 'Mobile' : 'Desktop',
        page: this.router.url
      });
    }
  }

  private setRouteHistoryAccount(): void {
    this.routeHistoryAccount = this.getHistoryRoute();
    this.cdRef.markForCheck();
  }

  private getHistoryRoute(): string {
    const hasBetHistory: boolean = this.customerOperatorConfiguration.operatorFeatures.includes('BetHistory');

    if (!hasBetHistory) {
      return '/myaccount/operations-history';
    }

    const isInstantGame: boolean =
      this.router.url.startsWith(`/${this.instantGamePath}`) || this.router.url.includes('instant-games-history');
    const isSportsPool: boolean =
      this.router.url.includes('sports-pool') || this.router.url.includes('sportspool-history');

    if (isInstantGame) {
      return '/myaccount/instant-games-history';
    }

    if (isSportsPool) {
      return '/myaccount/sportspool-history';
    }

    return '/myaccount/history';
  }
}
