import { ITelemetryService } from './telemetry-service.model';
import { Injectable, Inject, PLATFORM_ID } from '@angular/core';

import { isPlatformBrowser } from '@angular/common';
import { buildQueryString } from '@honoregaming/core';
import { take, tap } from 'rxjs/operators';
import { CustomerOperatorConfiguration, customerOperatorConfigurationToken } from '../../models';
import { AuthService } from '../auth.service';

@Injectable()
export class E2PixelTelemetryService implements ITelemetryService {
  isBrowser = isPlatformBrowser(this.platformId);
  configuration = this.operatorConfig.telemetryConfiguration.e2;
  conversionPixel: HTMLImageElement;
  retargetingPixel: HTMLImageElement;

  constructor(
    @Inject(customerOperatorConfigurationToken) private operatorConfig: CustomerOperatorConfiguration,
    private authService: AuthService,
    @Inject(PLATFORM_ID) private platformId
  ) {
    if (this.isBrowser) {
      this.conversionPixel = new Image();
      this.retargetingPixel = new Image();
    }
  }

  trackPageView(_name: string, _path: string): void {
    if (this.isBrowser) {
      var query = {
        key: this.configuration.universalKey
      };

      this.conversionPixel.src = `${this.configuration.serverUrl}/action.gif${buildQueryString(query)}`;
      this.retargetingPixel.src = `${this.configuration.serverUrl}/set-cookie.gif?${this.configuration.retargetingName}_Retargeting_SiteVisit=true`;
    }
  }

  trackEvent(name: string, properties: any): void {
    if (this.isBrowser) {
      this.authService.me$
        .pipe(
          take(1),
          tap(me => {
            switch (name) {
              case 'firstTimeDeposit': {
                let query = {
                  key: this.configuration.firstTimeDepositKey,
                  'cp.param1': me?.id,
                  'cp.total': properties.amount,
                  'cp.orderid': properties.id // cgao id
                };

                this.conversionPixel.src = `${this.configuration.serverUrl}/action.gif${buildQueryString(query)}`;
                this.retargetingPixel.src = `${this.configuration.serverUrl}/set-cookie.gif?${this.configuration.retargetingName}_Retargeting_FTD=true`;
                break;
              }
              case 'sign_up_complete': {
                let query = {
                  key: this.configuration.registrationCompleteKey,
                  'cp.param1': me?.id
                };

                this.conversionPixel.src = `${this.configuration.serverUrl}/action.gif${buildQueryString(query)}`;
                this.retargetingPixel.src = `${this.configuration.serverUrl}/set-cookie.gif?${this.configuration.retargetingName}_Retargeting_RegComplete=true`;
                break;
              }
            }
          })
        )
        .subscribe();
    }
  }
}
