import { APP_INITIALIZER, FactoryProvider, Optional, Injector } from '@angular/core';
import { localeResources, registerStLocale, resourcesProviderToken } from '@honoregaming/i18n';
import {
  AppConfiguration,
  GlobalConfiguration,
  OperatorConfiguration,
  OperatorSeo,
  appConfiguration,
  appConfigurationResolve,
  globalConfiguration,
  globalConfigurationResolve,
  operatorConfigurationToken
} from '@honoregaming/configuration';
import { Request } from 'express';
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { REQUEST } from '@nguniversal/express-engine/tokens';
import { AuthService as CustomerAuthService, GeoblockingService, PrivacyService, TelemetryService } from '../services';
import { GEOBLOCKED_ERROR_CODE, GeoblockingResponse } from '../models';
import { DOCUMENT } from '@angular/common';
import { switchMap, map, tap, catchError, filter } from 'rxjs/operators';
import { I18nService } from '@honoregaming/i18n';
import { Title } from '@angular/platform-browser';
import { Router } from '@angular/router';
import { BetCategoriesGuard, CookieStorageService, kioskToken, LocalStorageService } from '@honoregaming/core';
import { environment } from '../../../../customer/src/environments/environment';
import { EMPTY, Observable, of } from 'rxjs';
import { BetCategoryType } from '@honoregaming/types';
import { ThemeSwitcherService } from '@honoregaming/theme-switcher';
import { AuthService } from '@honoregaming/authentication';
import { getRootFromPath } from '../utils/url.utils';
import { SmarticoService } from '../services/smartico/smartico.service';

declare var location: Location;

export function LoadConfigurationsAndTranslations(
  injector: Injector,
  request: Request,
  storageService: CookieStorageService,
  document: any,
  titleService: Title,
  operatorConfiguration: OperatorConfiguration,
  themeSwitcherService: ThemeSwitcherService,
  privacyService: PrivacyService,
  localStorageService: LocalStorageService
) {
  const routeByBetCategories = {
    [BetCategoryType[BetCategoryType.SportsFixedOdds]]: 'sports',
    [BetCategoryType[BetCategoryType.InstantGame]]: 'instant-games',
    [BetCategoryType[
      (BetCategoryType.HorseRacingMutualOperatorPool, BetCategoryType.HorseRacingMutualInternationalPool)
    ]]: 'horseracing'
  };

  let host = request ? request.headers.selfHost : `${location.protocol}//${location.host}`;

  if (environment.kiosk) {
    host = '.';
  }

  return (): Promise<void> => {
    return new Promise<void>((resolve, reject) => {
      const http = injector.get(HttpClient);
      let getAppConfigObs: Observable<any>;

      let configObs = (
        request?.['config']
          ? of(request['config'])
          : http.get<GlobalConfiguration>(`${host}/configurations/config.json`)
      ).pipe(
        map((globalConfig: GlobalConfiguration) => {
          Object.assign(globalConfiguration, globalConfig);
          globalConfigurationResolve();
        })
      );

      if (environment.natif) {
        getAppConfigObs = http.get<AppConfiguration>(`${host}/configurations/app.config.json`).pipe(
          map(config => {
            Object.assign(appConfiguration, config);
            appConfigurationResolve();
          }),
          switchMap(() => configObs)
        );
      } else {
        getAppConfigObs = configObs;
      }

      getAppConfigObs
        .pipe(
          switchMap(() => {
            return http.get<string>(`${globalConfiguration.apiBaseUrl}operatordata/commercial-code`, {
              responseType: 'text' as 'json'
            });
          }),
          catchError((error: HttpErrorResponse) => {
            if (error.status !== 403) {
              throw error;
            }

            let errorCode: number | undefined;
            try {
              errorCode = JSON.parse(error.error)?.code; // parsing needed because of responseType 'text' in request
            } catch {}

            if (errorCode !== GEOBLOCKED_ERROR_CODE) {
              throw error;
            }

            // Geo-blocked: load the operator theme only, the operator configuration.json stays unloaded.
            return injector
              .get(GeoblockingService)
              .load()
              .pipe(
                catchError(() => of(null)),
                switchMap((geoblocking: GeoblockingResponse | null) => {
                  if (geoblocking) {
                    themeSwitcherService.init(geoblocking.commercialCode);
                  }

                  injector.get(Router).navigate(['geo'], { skipLocationChange: true });
                  resolve();

                  return EMPTY;
                })
              );
          }),
          filter(commercialCode => commercialCode !== null),
          switchMap(commercialCode => {
            let isKiosk = injector.get(kioskToken);
            if (!isKiosk) {
              return http.get<OperatorConfiguration>(
                `${globalConfiguration.staticAssetsPath}${commercialCode}/configuration.json`
              );
            }

            return http.get<OperatorConfiguration>(
              `${globalConfiguration.staticAssetsPath}${commercialCode}/kiosk-configuration.json`
            );
          }),
          switchMap(operatorConfig => {
            if (!document.querySelector('#manifest')) {
              const manifest = document.createElement('link');
              manifest.id = 'manifest';
              manifest.href = `${globalConfiguration.staticAssetsPath}${operatorConfig.commercialCode}/manifest.json`;
              manifest.rel = 'manifest';
              document.querySelector('head').appendChild(manifest);
            }

            if (operatorConfig.onlineConfiguration?.homePageCasino && !!operatorConfig.features) {
              operatorConfig.features.defaultBetCategory = BetCategoryType.InstantGame;
            }

            Object.assign(operatorConfiguration, operatorConfig);
            if (operatorConfiguration.betCategories.indexOf(operatorConfiguration.features.defaultBetCategory) == -1) {
              throw new Error('bad operator configuration');
            }

            const privacyConfiguration = privacyService.initializePrivacyConfiguration();

            // Initialize Smartico as soon as possible
            injector.get(SmarticoService).initialize();

            // Init Telemetry/Pixels as soon as possible when privacy data available in localStorage
            injector.get(TelemetryService).loadTelemetryServices(privacyConfiguration);

            themeSwitcherService.init();

            const instantGamePath =
              operatorConfiguration.betCategoriesPathConfiguration?.instantGamesConfiguration?.path ?? 'instant-games';
            routeByBetCategories[BetCategoryType[BetCategoryType.InstantGame]] = instantGamePath;
            const defaultRoute =
              routeByBetCategories[BetCategoryType[operatorConfiguration.features.defaultBetCategory]];
            if (defaultRoute == null) {
              throw new Error('bad operator configuration');
            }

            injector.get(Router).config.unshift({
              path: '',
              redirectTo: defaultRoute,
              pathMatch: 'full'
            });

            injector
              .get(Router)
              .config.filter(c => c.path === '')[1]
              .children.push({
                path: instantGamePath,
                loadChildren: () =>
                  import('../../../../hg-instant-games/src/lib/hg-instant-games.module').then(
                    m => m.HgInstantGamesModule
                  ),
                data: { 'sidebar-content': 'none', betCategories: [BetCategoryType.InstantGame] },
                canLoad: [BetCategoriesGuard]
              });

            if (!document.querySelector('meta[name*="description"]')) {
              let root = getRootFromPath(document.location.pathname, instantGamePath);
              return http.get<OperatorSeo>(
                `${globalConfiguration.staticAssetsPath}${operatorConfiguration.commercialCode}/seo_${root}.json`
              );
            } else {
              return of(null);
            }
          }),
          switchMap((seo: OperatorSeo | null) => {
            if (seo) {
              titleService.setTitle(seo.title);

              const description = document.createElement('meta');
              description.name = 'description';
              description.content = seo.description;
              document.querySelector('head').appendChild(description);

              let favicon = document.querySelector('link[rel*="icon"]') as HTMLLinkElement;
              if (!favicon) {
                favicon = document.createElement('link');
                document.querySelector('head').appendChild(favicon);
              }
              favicon.type = 'image/x-icon';
              favicon.rel = 'icon';
              favicon.href = `${globalConfiguration.assetsPath}${operatorConfiguration.key}/favicon.ico`;

              if (seo.keywords && !document.querySelector('meta[name*="keywords"]')) {
                const keywords = document.createElement('meta');
                keywords.name = 'keywords';
                keywords.content = seo.keywords;
                document.querySelector('head').appendChild(keywords);
              }
            }
            const iosIcon = document.createElement('link');
            iosIcon.href = `${globalConfiguration.assetsPath}${operatorConfiguration.key}/apple-touch-icon.png`;
            iosIcon.rel = 'apple-touch-icon';
            document.querySelector('head').appendChild(iosIcon);

            const languageCode =
              storageService.getItem('cus_language') &&
              operatorConfiguration.localization.languages.indexOf(storageService.getItem('cus_language')) !== -1
                ? storageService.getItem('cus_language')
                : operatorConfiguration.localization.defaultLanguage;
            storageService.setItem('cus_language', languageCode);

            const oddsformat =
              storageService.getItem('cus_oddsformat') &&
              operatorConfiguration.odds.formats.indexOf(storageService.getItem('cus_oddsformat')) !== -1
                ? storageService.getItem('cus_oddsformat')
                : operatorConfiguration.odds.defaultFormat;
            storageService.setItem('cus_oddsformat', oddsformat);
            return injector
              .get(resourcesProviderToken)
              .getLocaleResources(languageCode)
              .pipe(
                tap(langs => (langs.formats.currencyAsPrefix = langs.formats.currencyFormat.indexOf('¤') === 0)),
                map(langs => ({ langs, languageCode }))
              );
          }),
          tap(localeRes => {
            Object.assign(localeResources, localeRes.langs);
            registerStLocale(localeRes.languageCode, localeResources.formats);

            var localFormat = storageService.getItem('cus_format');
            if (!localFormat || localFormat.currencyAsPrefix != localeResources.formats.currencyAsPrefix) {
              storageService.setItem('cus_format', localeResources.formats);
            }
          }),
          tap(_ => {
            // Initialize sessionId
            if (!localStorageService.getItem('vsid')) {
              const id = 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
                const r = (Math.random() * 16) | 0;
                const v = c === 'x' ? r : (r & 0x3) | 0x8;
                return v.toString(16);
              });

              localStorageService.setItem('vsid', id);
            }
          })
        )
        .subscribe(
          _x => {
            injector.get(I18nService).init();
            if (!injector.get(kioskToken)) {
              injector.get(CustomerAuthService).startRefreshAuthTimer();
            } else {
              injector.get(AuthService).startRefreshAuthTimer();
              injector.get(CustomerAuthService).getMe().subscribe();
            }
            resolve();
          },
          err => {
            if (err instanceof HttpErrorResponse && (err.status === 527 || err.error?.code === GEOBLOCKED_ERROR_CODE)) {
              resolve();
            } else {
              reject(err);
            }
          }
        );
    });
  };
}

export const appInitializerFactory: FactoryProvider = {
  provide: APP_INITIALIZER,
  useFactory: LoadConfigurationsAndTranslations,
  multi: true,
  deps: [
    Injector,
    [new Optional(), REQUEST],
    CookieStorageService,
    DOCUMENT,
    Title,
    operatorConfigurationToken,
    ThemeSwitcherService,
    PrivacyService,
    LocalStorageService
  ]
};
