import { Component, ChangeDetectionStrategy, Input } from '@angular/core';
import { Router } from '@angular/router';
import { BetLine } from '../../../models';

@Component({
  selector: 'hg-sports-pool-bet-line-header',
  templateUrl: './sports-pool-bet-line-header.component.html',
  styleUrls: ['./sports-pool-bet-line-header.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class SportsPoolBetLineHeaderComponent {
  @Input() betLine!: BetLine;

  constructor(private readonly router: Router) {}

  navigate(event: Event): void {
    event.stopPropagation();
    event.preventDefault();

    this.router.navigate(['/sports-pool', this.betLine.sportsPoolGameId]);
  }
}
