import { Component, ChangeDetectionStrategy, Input, Output, EventEmitter } from '@angular/core';

@Component({
  selector: 'hg-generic-content',
  templateUrl: './generic-content.component.html',
  styleUrls: ['./generic-content.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class GenericContentComponent {
  @Input()
  public title: string;

  @Input()
  public icon: string;

  @Input()
  public text: string;

  @Input()
  public subText: string;

  @Input()
  public okButton: boolean;

  @Input()
  public okButtonTranslationKey: string = 'COMMON.OK';

  @Input()
  public isError = false;

  @Output()
  close = new EventEmitter<boolean>();
}
