import { Injectable } from '@angular/core';
import { Subject, Observable } from 'rxjs';
import { filter, map } from 'rxjs/operators';

@Injectable({ providedIn: 'root' })
export class BroadcastingService {
  private $trigger = new Subject<{ event: string; args: any }>();

  constructor() {}

  public register<T>(event: string): Observable<T> {
    return this.$trigger.asObservable().pipe(
      filter(x => x.event === event),
      map(x => x.args)
    );
  }

  public broadcast<T>(event: string, args?: T) {
    this.$trigger.next({ event, args });
  }
}
