import { DOCUMENT, isPlatformBrowser } from '@angular/common';
import {
  Component,
  OnInit,
  ChangeDetectionStrategy,
  Input,
  Inject,
  ChangeDetectorRef,
  Output,
  EventEmitter,
  PLATFORM_ID,
  ViewChild,
  ElementRef,
  SimpleChanges,
  OnChanges,
  AfterViewChecked
} from '@angular/core';
import { Router } from '@angular/router';
import { combineLatest } from 'rxjs';
import { finalize, takeUntil } from 'rxjs/operators';
import { OperatorConfiguration, operatorConfigurationToken, TicketStateCheckerMode } from '@honoregaming/configuration';
import { BetCategoryConfigurationService, DestroySubject, kioskToken, natifToken } from '@honoregaming/core';
import {
  CustomerOperatorConfiguration,
  customerOperatorConfigurationToken,
  MenuShortcut,
  MenuCustomizationService,
  TelemetryService,
  AuthService
} from '@honoregaming/customer-core';
import { EventCategoriesService } from '@honoregaming/events';
import { BetCategoryType, InsaLeagueEnum } from '@honoregaming/types';
import { Media, MediaService } from '@honoregaming/ui';
import { MobileNavService } from 'projects/customer/customer/src/app/services/mobile-nav.service';
import { CharityService } from 'projects/customer/hg-about/src/lib/services/charity.service';

@Component({
  selector: 'hg-mobile-menu',
  templateUrl: './mobile-menu.component.html',
  styleUrls: ['./mobile-menu.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class MobileMenuComponent extends DestroySubject implements OnInit, OnChanges, AfterViewChecked {
  @Input() isBurgerOpened?: boolean;

  @Output() clickOnBurger = new EventEmitter<boolean>();

  @ViewChild('parent') parent?: ElementRef;
  @ViewChild('sports', { static: false }) sports?: ElementRef;

  BetCategoryType = BetCategoryType;

  operatorName: string = this.customerOperatorConfiguration.name;
  instantGamesBetCategoryPath: string = this.betCategoryConfigurationService.getInstantGamesBetCategoryPath();

  hasNewInstantGames: boolean =
    !!this.customerOperatorConfiguration.hasNew && this.customerOperatorConfiguration.hasNew.includes('InstantGames');
  hasCharity: boolean = false;
  hasInsaLeagues: boolean = false;
  hasPromotions: boolean = this.customerOperatorConfiguration.contentsConfiguration?.hasPromotions;
  ticketStateAvailable: boolean =
    this.customerOperatorConfiguration.features.ticketStateCheckerMode !== TicketStateCheckerMode.Disabled;
  isBetCodeCheckerEnabled: boolean = this.customerOperatorConfiguration.betCodeConfiguration?.isBetCodeCheckerEnabled;

  hasWelcomeTutorial: boolean = this.operatorConfiguration.onlineConfiguration?.welcomeTutorial;
  displayLanguageSelector: boolean =
    this.operatorConfiguration.themeCustomizationConfiguration?.displayLanguageSelectorOnBetCategoryBanner;

  displayforAndroid: boolean = false;
  displayforIos: boolean = false;
  displayHelp: boolean = true;
  displayBetcodeTicket: boolean = false;

  isLoading: boolean = false;
  shortcutsLinks: MenuShortcut[] = [];
  numberOfLinks?: number;

  tutorialStepsStorage: string = 'tutorial_steps';
  tutorialStep?: number;

  constructor(
    private readonly cdRef: ChangeDetectorRef,
    private readonly mobileNavService: MobileNavService,
    private readonly eventCategoriesService: EventCategoriesService,
    private readonly betCategoryConfigurationService: BetCategoryConfigurationService,
    private readonly menuCustomizationService: MenuCustomizationService,
    private readonly charityService: CharityService,
    private readonly authService: AuthService,
    private readonly telemetryService: TelemetryService,
    private readonly mediaService: MediaService,
    private readonly router: Router,
    @Inject(operatorConfigurationToken) public readonly operatorConfiguration: OperatorConfiguration,
    @Inject(kioskToken) public readonly isKiosk: boolean,
    @Inject(PLATFORM_ID) private readonly platformId: Object,
    @Inject(customerOperatorConfigurationToken)
    private readonly customerOperatorConfiguration: CustomerOperatorConfiguration,
    @Inject(DOCUMENT) private readonly document: Document,
    @Inject(natifToken) public readonly isNatif: boolean
  ) {
    super();
  }

  ngOnInit(): void {
    this.getMobileShortcuts();
    this.detectUserAgent();
    this.cdRef.markForCheck();

    combineLatest([this.mobileNavService.burgerMenu, this.mobileNavService.jumpInBurgerMenu])
      .pipe(takeUntil(this.destroy$))
      .subscribe(([open, type]) => {
        if (open && type === 'jumpSportsSectionMenu') {
          setTimeout(() => {
            this.sports?.nativeElement.scrollIntoView({ block: 'start' });
          });
        } else if (open && type === 'displayBetcodeTicket') {
          this.displayBetcodeTicket = true;
        }
      });

    this.tutorialStep = Number(localStorage.getItem(this.tutorialStepsStorage));

    if (this.tutorialStep === 3 || this.tutorialStep === 4) {
      this.isBurgerOpened = true;
    }

    this.mobileNavService.tutorialUpdate.pipe(takeUntil(this.destroy$)).subscribe(step => {
      this.tutorialStep = step;

      if (this.tutorialStep === 5) {
        this.closeMenu();
      }
      this.cdRef.markForCheck();
    });

    this.eventCategoriesService.getEntryPoints().subscribe(eventCategories => {
      if (eventCategories.some(eventCategory => eventCategory.id in InsaLeagueEnum)) {
        this.hasInsaLeagues = true;
      }
    });

    if (this.operatorConfiguration.operatorFeatures?.indexOf('Charity') > -1) {
      this.charityService
        .showCharityNavigation()
        .pipe(
          takeUntil(this.destroy$),
          finalize(() => {
            this.cdRef.markForCheck();
          })
        )
        .subscribe(showCharityNavigation => {
          this.hasCharity = showCharityNavigation;
        });
    }
  }

  ngAfterViewChecked(): void {
    if (this.tutorialStep <= 5 && this.hasWelcomeTutorial) {
      this.fixBody();
    }
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes.isBurgerOpened && this.parent?.nativeElement) {
      this.parent.nativeElement.scroll(0, 0);
      this.isBurgerOpened ? this.fixBody() : this.releaseBody();

      if (!this.isBurgerOpened) {
        this.closeMenu();
      }
    }
  }

  closeMenu(): void {
    this.isBurgerOpened = false;
    this.displayBetcodeTicket = false;
    this.clickOnBurger.emit(this.isBurgerOpened);
    this.releaseBody();
    this.cdRef.markForCheck();
  }

  clickDisplayBetcodeTicket(): void {
    this.displayBetcodeTicket = true;
  }

  clickToNextStep(step: number): void {
    if (this.tutorialStep <= 5 && this.hasWelcomeTutorial) {
      localStorage[this.tutorialStepsStorage] = Number.parseInt(localStorage[this.tutorialStepsStorage]) + 1;
      this.mobileNavService.updateStepTutorial(step);
    } else {
      this.closeMenu();
    }
  }

  skipTutorial(): void {
    localStorage[this.tutorialStepsStorage] = Number.parseInt('6');
    this.tutorialStep = Number(localStorage.getItem(this.tutorialStepsStorage));
    this.mobileNavService.updateStepTutorial(6);
  }

  trackEvent(eventName: string): void {
    if (this.authService.isAuthenticated()) {
      this.telemetryService.trackEvent('header_click_loggedon', {
        shortcut_name: eventName,
        shortcut_device: this.mediaService?.media < Media.md ? 'Mobile' : 'Desktop',
        page: this.router.url
      });
    }
  }

  private getMobileShortcuts(): void {
    this.shortcutsLinks = this.menuCustomizationService.mobileShortcuts;
    this.numberOfLinks = this.shortcutsLinks.length;
  }

  private fixBody(): void {
    this.document.documentElement.classList.add('hidden');
  }

  private releaseBody(): void {
    this.document.documentElement.classList.remove('hidden-in-xs', 'hidden');
  }

  private detectUserAgent(): void {
    if (isPlatformBrowser(this.platformId)) {
      if (/iPad|iPhone|iPod/.test(navigator.userAgent)) {
        this.displayforIos = true;
      } else {
        this.displayforAndroid = true;
      }
    }
  }
}
