import { Component, ChangeDetectionStrategy, Input, Output, EventEmitter, Inject } from '@angular/core';
import { operatorConfigurationToken, OperatorConfiguration } from '@honoregaming/configuration';
import { InstantGameTransaction } from '../../models/instant-game-transaction.model';
import { CurrencyMathMixin, DestroySubject } from '@honoregaming/core';

@Component({
  selector: 'hg-instantgame-transaction',
  templateUrl: './instantgame-transaction.component.html',
  styleUrls: [
    './instantgame-transaction.component.scss',
    '../bet-lines/bet-line.scss',
    '../bet-lines/bet-line-content.scss'
  ],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class InstantGameTransactionComponent extends CurrencyMathMixin(DestroySubject) {
  @Input()
  transaction: InstantGameTransaction;

  @Output()
  remove = new EventEmitter<void>();

  @Output()
  transactionChange = new EventEmitter<number>();

  currency = this.operatorConfiguration.currency.symbol;

  constructor(@Inject(operatorConfigurationToken) private operatorConfiguration: OperatorConfiguration) {
    super();
  }

  onRemove() {
    this.remove.emit();
  }

  setMultiplier(multiplier: number) {
    this.transactionChange.next(multiplier);
  }
}
