import { Component, ChangeDetectionStrategy, EventEmitter, Output, Input } from '@angular/core';
import { TimeFilter } from '@honoregaming/types';
import { KeyValue } from '@angular/common';

@Component({
  selector: 'hg-time-filter',
  templateUrl: './time-filter.component.html',
  styleUrls: ['./time-filter.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class TimeFilterComponent {
  public timeFilters = TimeFilter;

  @Input()
  public selectedTimeFilter: TimeFilter;

  @Output()
  public timeFilterSelected = new EventEmitter<TimeFilter>();

  public originalOrder(_a: KeyValue<string, string>, _b: KeyValue<string, string>): number {
    return 0;
  }
}
