import { Component, OnInit, ChangeDetectionStrategy, HostBinding, ChangeDetectorRef, OnChanges } from '@angular/core';
import { DomSanitizer, SafeStyle } from '@angular/platform-browser';
import { DestroySubject, getDateInBrowserTimeZone } from '@honoregaming/core';
import { EventsService } from '@honoregaming/events';
import { EventWithEventBetTypes, HorseRace, HorseRaceEventBetType } from '@honoregaming/types';
import { takeUntil } from 'rxjs/operators';

const displayPriorityOrderQuinte = [1007, 1018, 1017, 14]; // Quinté, Quinté + ALR, Quinté ALR, Quinté +

@Component({
  selector: 'hg-horse-racing-template',
  templateUrl: './horse-racing-template.component.html',
  styleUrls: ['./horse-racing-template.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class HorseRacingTemplateComponent extends DestroySubject implements OnInit, OnChanges {
  nextQuinte: EventWithEventBetTypes<HorseRace, HorseRaceEventBetType>;
  nextQuinteGrossPool: number;

  nextQuinteDay: string;

  loading = false;
  backgroundUrl: any;

  @HostBinding('style.backgroundImage')
  get myStyle(): SafeStyle {
    return this.sanitizer.bypassSecurityTrustStyle(`url(${this.backgroundUrl})`);
  }

  constructor(private eventsService: EventsService, private cdRef: ChangeDetectorRef, private sanitizer: DomSanitizer) {
    super();
  }

  ngOnInit() {
    this.eventsService
      .getNextQuinte(true, getDateInBrowserTimeZone(), true)
      .pipe(takeUntil(this.destroy$))
      .subscribe(nextQuinte => {
        // Sort the quinte by prio
        nextQuinte.eventBetTypes.sort(
          (a, b) => displayPriorityOrderQuinte.indexOf(a.betTypeId) - displayPriorityOrderQuinte.indexOf(b.betTypeId)
        );
        // ------------------------
        this.nextQuinte = nextQuinte;
        this.nextQuinteGrossPool = nextQuinte.eventBetTypes?.find(ebt => ebt.betTypeId === 14)?.grossPool;

        this.cdRef.markForCheck();
      });

    this.loading = true;
  }

  ngOnChanges() {
    if (this.nextQuinte) {
      this.nextQuinteDay = new Date(this.nextQuinte.expectedStart).toISOString().slice(0, 10);
    } else {
      this.nextQuinteDay = null;
    }
  }
}
