import {
  Component,
  ChangeDetectionStrategy,
  AfterViewInit,
  ViewContainerRef,
  ChangeDetectorRef,
  EventEmitter,
  Output,
  OnInit,
  ComponentFactoryResolver
} from '@angular/core';
import { providersLoaders } from '@honoregaming/payment-providers';
import { Provider } from '../../models/provider.model';
import { BankWithdrawProvider, WithdrawProvider } from '../../models/withdraw-provider.model';
import { PaymentProviderStatus } from '../../models/provider.model';
import { ActivatedRoute, Router } from '@angular/router';
import { AccountService } from '../../services/account.service';
import { skip, takeUntil } from 'rxjs/operators';
import { DestroySubject } from '@honoregaming/core';
import { merge } from 'rxjs';
import { PaymentAccount } from 'projects/customer/hg-core/src/lib/models/payment-account.model';
import { AuthService } from '@honoregaming/customer-core';
import { forkJoin } from 'rxjs';

@Component({
  selector: 'hg-withdraw-provider-loader',
  template: '',
  styles: [''],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class WithdrawProviderLoaderComponent extends DestroySubject implements OnInit, AfterViewInit {
  provider: Provider;
  providerName: string;
  canDoWithdrawal: boolean;
  customerPaymentAccounts: PaymentAccount[];
  viewInit: boolean;

  @Output() withdrawValidated: EventEmitter<any> = new EventEmitter<any>();
  uniqueProvider: boolean;

  constructor(
    private activatedRoute: ActivatedRoute,
    private authService: AuthService,
    private router: Router,
    private vcr: ViewContainerRef,
    private cdRef: ChangeDetectorRef,
    private route: ActivatedRoute,
    private accountService: AccountService,
    private resolver: ComponentFactoryResolver
  ) {
    super();
  }

  ngOnInit() {
    this.route.params.subscribe(params => {
      this.providerName = params.provider;
      if (this.viewInit) {
        this.loadProvider();
      }
    });
  }

  ngAfterViewInit() {
    this.viewInit = true;
    this.loadProvider();
  }

  loadProvider() {
    forkJoin([
      this.authService.getMe(),
      this.accountService.getWithdrawalInformation(),
      this.accountService.getPaymentProviders()
    ])
      .pipe(takeUntil(merge(this.destroy$, this.route.params.pipe(skip(1)))))
      .subscribe(([me, withdrawalInformation, providersResponse]) => {
        this.canDoWithdrawal = withdrawalInformation.canDoWithdrawal;
        this.uniqueProvider =
          providersResponse.providers.filter(e => e.withdrawalStatus !== PaymentProviderStatus.Disabled).length === 1;
        this.provider = providersResponse.providers.find(
          e =>
            e.withdrawalStatus !== PaymentProviderStatus.Disabled && e.providerName.toLowerCase() === this.providerName
        );
        if (
          this.provider === undefined ||
          !this.canDoWithdrawal ||
          this.provider.withdrawalStatus === PaymentProviderStatus.Offline ||
          this.provider.withdrawalStatus === PaymentProviderStatus.Disabled
        ) {
          return this.router.navigate(['../'], { relativeTo: this.activatedRoute });
        }

        this.customerPaymentAccounts = me.customerPaymentAccounts.filter(
          c => c.providerName === this.provider.providerName && c.provider === this.provider.providerId
        );

        var providerLoader = providersLoaders[this.provider.parentProviderName ?? this.provider.providerName];
        if (!providerLoader) {
          providerLoader = !this.provider.banks ? providersLoaders['Generic'] : providersLoaders['Bank'];
        }

        providerLoader().then(module => {
          this.vcr.clear();
          let refInstance;
          const factory = this.resolver.resolveComponentFactory(module.withdraw);
          if (factory !== undefined) {
            if (!this.provider.banks) {
              refInstance = this.vcr.createComponent(factory).instance as WithdrawProvider;
            } else {
              refInstance = this.vcr.createComponent(factory).instance as BankWithdrawProvider;
              refInstance.customerPaymentAccounts = this.customerPaymentAccounts as PaymentAccount[];
            }
            refInstance.provider = this.provider;
            refInstance.maximumAmount = withdrawalInformation.maxWithdrawalAmountAvailable;
            refInstance.withdrawalDelay = withdrawalInformation.customerWithdrawalMinDelay;
            refInstance.uniqueProvider = this.uniqueProvider;
            refInstance.customerWithdrawalPredefinedAmount = providersResponse.customerWithdrawalPredefinedAmount;
            refInstance.currentBalance = me.balance;
            refInstance.withdrawValidated.subscribe(() => {
              this.withdrawValidated.emit();
            });

            this.cdRef.markForCheck();
          }
        });
      });
  }
}
