import { switchMap, takeUntil } from 'rxjs/operators';
import { Injectable, Injector } from '@angular/core';
import { ApplicationStateService, DestroySubject } from '@honoregaming/core';
import { ICaptchaService } from './captcha-service.model';
import { CustomerService } from '../customer.service';
import { SecurityPolicy } from '@honoregaming/types';
import { Observable } from 'rxjs';
import { ReCaptchaV3Service } from './recaptchav3.captcha.service';
import { TurnstileCaptchaService } from './turnstile.captcha.service';
import { NoopCaptchaService } from './noop.captcha.service';
import { EvinaCaptchaService } from './evina.captcha.service';
import { FingerprintCaptchaService } from './fingerprint.captcha.service';

@Injectable()
export class CaptchaService extends DestroySubject implements ICaptchaService {
  private captchaService: ICaptchaService;

  constructor(private injector: Injector, appState: ApplicationStateService, private customerService: CustomerService) {
    super();
    appState.isReady$
      .pipe(
        switchMap(() => this.customerService.getSecurityPolicy()),
        takeUntil(this.destroy$)
      )
      .subscribe(securityPolicy => {
        this.loadCaptcha(securityPolicy);
      });
  }

  loadCaptcha(securityPolicy: SecurityPolicy) {
    if (this.captchaService === null || this.captchaService === undefined) {
      if (securityPolicy.captchaProvider?.recaptchaV3?.enabled) {
        this.captchaService = this.injector.get(ReCaptchaV3Service);
      } else if (securityPolicy.captchaProvider?.turnstile?.enabled) {
        this.captchaService = this.injector.get(TurnstileCaptchaService);
      } else if (securityPolicy.captchaProvider?.evina?.enabled) {
        this.captchaService = this.injector.get(EvinaCaptchaService);
      } else if (securityPolicy.captchaProvider?.fingerprint?.enabled) {
        this.captchaService = this.injector.get(FingerprintCaptchaService);
      } else {
        this.captchaService = this.injector.get(NoopCaptchaService);
      }
    }
  }

  applyCaptcha(targetElement: string): Observable<void> {
    return this.captchaService.applyCaptcha(targetElement);
  }

  validateCaptcha(): Observable<string> {
    return this.captchaService.validateCaptcha();
  }

  getLegend(): string {
    return this.captchaService.getLegend();
  }

  clearCaptcha(): void {
    this.captchaService.clearCaptcha();
  }
}
