import {
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  ElementRef,
  EventEmitter,
  Input,
  Output,
  ViewChild
} from '@angular/core';
import { EventBetType, EventBetTypeGroupedByBetType, Match, SelectableEventBetTypeItem } from '@honoregaming/types';

@Component({
  selector: 'hg-event-bet-type-items-list',
  templateUrl: './event-bet-type-items-list.component.html',
  styleUrls: ['./event-bet-type-items-list.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class EventBetTypeItemsListComponent {
  @Input() eventBetTypeGroupedByBetType?: EventBetTypeGroupedByBetType;
  @Input() ebtis?: SelectableEventBetTypeItem[];
  @Input() event!: Match;
  @Input() eventBetType?: EventBetType;
  @Input() betTypeId?: number;
  @Input() canCollapse: boolean = true;
  @Input() noOdds?: boolean;

  @Output() toggleBetEvent = new EventEmitter<{ ebt: EventBetType; item: SelectableEventBetTypeItem }>();

  @ViewChild('ebtiList')
  set ebtiListElement(element: ElementRef) {
    this.updateButtonVisibility(element);
  }

  isFullHeight: boolean = !this.canCollapse;
  hasButton: boolean = false;

  private static readonly MAX_LIST_HEIGHT = 180;
  private static readonly HEADER_HEIGHT = 55;
  private static readonly EVENT_HEADER_HEIGHT = 75;
  private static readonly EVENT_FILTER_HEIGHT = 45;
  private static readonly SCROLL_OFFSET = 50;
  private static readonly TOTAL_HEADER_OFFSET =
    EventBetTypeItemsListComponent.HEADER_HEIGHT +
    EventBetTypeItemsListComponent.EVENT_HEADER_HEIGHT +
    EventBetTypeItemsListComponent.EVENT_FILTER_HEIGHT +
    EventBetTypeItemsListComponent.SCROLL_OFFSET;

  private ebtiListRef?: ElementRef;

  constructor(private readonly cdRef: ChangeDetectorRef) {}

  toggleHeight(): void {
    this.isFullHeight = !this.isFullHeight;

    if (!this.isFullHeight) {
      this.scrollToListIfNeeded();
    }
  }

  trackById(_index: number, item: { id: number }): number {
    return item.id;
  }

  private updateButtonVisibility(element: ElementRef | undefined): void {
    if (!element) {
      return;
    }

    this.ebtiListRef = element;
    this.hasButton = element.nativeElement.offsetHeight >= EventBetTypeItemsListComponent.MAX_LIST_HEIGHT;
    this.cdRef.detectChanges();
  }

  private scrollToListIfNeeded(): void {
    const element: HTMLElement | undefined = this.ebtiListRef?.nativeElement;

    if (!element) {
      return;
    }

    const rect: DOMRect = element.getBoundingClientRect();
    const isInView: boolean =
      rect.top >= EventBetTypeItemsListComponent.TOTAL_HEADER_OFFSET && rect.bottom <= window.innerHeight;

    if (isInView) {
      return;
    }

    const offsetPosition: number = rect.top + window.pageYOffset - EventBetTypeItemsListComponent.TOTAL_HEADER_OFFSET;

    window.scrollTo({
      top: offsetPosition,
      behavior: 'smooth'
    });
  }
}
