import { Component, ChangeDetectionStrategy, Input } from '@angular/core';
import { I18nService } from '@honoregaming/i18n';
import { InstantGameTransaction } from '@honoregaming/types';
import { ToasterService } from '@honoregaming/ui';
import { take } from 'rxjs/operators';

@Component({
  selector: 'hg-musika-transaction',
  templateUrl: './musika-transaction.component.html',
  styleUrls: ['./musika-transaction.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class MusikaTransactionComponent {
  @Input()
  transaction: InstantGameTransaction;

  constructor(private toasterService: ToasterService, private i18n: I18nService) {}

  contentCopied() {
    this.i18n
      .translate('ACCOUNT.COPIED.REFERENCE')
      .pipe(take(1))
      .subscribe(translation => this.toasterService.show(translation));
  }
}
