import { Observable, BehaviorSubject, Subject } from 'rxjs';
import { Inject, Injectable } from '@angular/core';
import {
  AutoBorletteAvailability,
  BetCategoryType,
  BetSystemHistory,
  DrawGame,
  DrawGameBorletteBetType,
  DrawGameMessage,
  DrawGameReplayRequest
} from '@honoregaming/types';
import { ApplicationEvent, BroadcastingService, Scope, scopeToken } from '@honoregaming/core';
import { BetPlaced, BetSlipService, createBetLineWithSelection } from '@honoregaming/betslip';
import { EventsService } from '@honoregaming/events';
import { take } from 'rxjs/operators';
import { MessageService } from '@honoregaming/ui';
import { DrawGamesReplayComponent } from '@honoregaming/draw-games-ui';

@Injectable({
  providedIn: 'root'
})
export class DrawGameBetSlipService {
  private readonly LAST_PLACED_BET_STORAGE_KEY = 'DrawGameBetSlipService_lastPlacedBet';

  lastPlacedBet: BetPlaced | undefined;

  private autoBorletteAvailabilitySubject: BehaviorSubject<AutoBorletteAvailability>;
  $autoBorletteAvailabilityEvent: Observable<AutoBorletteAvailability>;

  private drawGameBetPlacedSubject = new Subject<void>();
  $drawGameBetPlaced = this.drawGameBetPlacedSubject.asObservable();

  constructor(
    private broadcastingService: BroadcastingService,
    private betSlipService: BetSlipService,
    private eventsService: EventsService,
    private messageService: MessageService,
    @Inject(scopeToken) public userScope: Scope
  ) {
    this.autoBorletteAvailabilitySubject = new BehaviorSubject({ availability: false, numbers: [] });
    this.$autoBorletteAvailabilityEvent = this.autoBorletteAvailabilitySubject.asObservable();
    this.broadcastingService.register<BetPlaced>(ApplicationEvent.BetPlaced).subscribe(x => {
      if (x.betCategory === BetCategoryType.DrawGame) {
        this.manageDrawGameBetPlaced(x);
      }
    });
    this.lastPlacedBet = JSON.parse(sessionStorage.getItem(this.LAST_PLACED_BET_STORAGE_KEY));

    this.broadcastingService.register<any>(ApplicationEvent.BetPlaced).subscribe(x => {
      if (x.betCategory === BetCategoryType.DrawGame) {
        this.manageDrawGameBetPlaced(x);
      }
    });

    this.broadcastingService
      .register<DrawGameReplayRequest>(DrawGameMessage.DrawGameReplayRequest)
      .subscribe(request => {
        this.replay(request.authorized, request.betSystem, request.navigateUrl);
      });
  }

  setAutoBorletteAvailability(availability: boolean, numbers: string[]): void {
    this.autoBorletteAvailabilitySubject.next({ availability: availability, numbers: numbers });
  }

  canReplay(authorized: boolean | undefined, betSystemHistory?: BetSystemHistory): boolean {
    const canReplay =
      authorized &&
      ((betSystemHistory != null &&
        betSystemHistory.betCategory === BetCategoryType.DrawGame &&
        betSystemHistory.betLines != null) ||
        (betSystemHistory == null &&
          this.lastPlacedBet != null &&
          this.lastPlacedBet.betCategory === BetCategoryType.DrawGame &&
          this.lastPlacedBet.bet?.betLines != null));

    return canReplay;
  }

  canReplayEvent(
    drawGame: DrawGame,
    authorized: boolean | undefined,
    drawGames: DrawGame[],
    betSystemHistory?: BetSystemHistory,
    bypassDoubChansLimitation?: boolean
  ): boolean {
    const canReplay =
      this.canReplay(authorized, betSystemHistory) &&
      ((betSystemHistory != null &&
        betSystemHistory.betLines.some(betLine =>
          drawGame.drawGameRule.drawGameDetails.some(x => x.betTypeId === betLine.betTypeId)
        )) ||
        (betSystemHistory == null &&
          this.lastPlacedBet.bet.betLines.some(betLine =>
            drawGame.drawGameRule.drawGameDetails.some(
              x =>
                x.betTypeId === betLine.betTypeId &&
                (drawGames == null || drawGames.some(game => game.id === drawGame.id)) &&
                (x.betTypeId !== 40043 ||
                  bypassDoubChansLimitation ||
                  (drawGame.id !== betLine.associatedDrawGamesIds[0] &&
                    (drawGames == null || drawGames.some(game => game.id === betLine.associatedDrawGamesIds[0]))))
            )
          )));

    return canReplay;
  }

  canReplaybetType(betTypeId: number, authorized: boolean | undefined, betSystemHistory?: BetSystemHistory): boolean {
    const canReplay =
      this.canReplay(authorized, betSystemHistory) &&
      ((betSystemHistory != null && betSystemHistory.betLines.some(betLine => betTypeId === betLine.betTypeId)) ||
        (betSystemHistory == null && this.lastPlacedBet.bet.betLines.some(betLine => betTypeId === betLine.betTypeId)));

    return canReplay;
  }

  canReplayOtherThanBetType(
    betTypeId: number,
    authorized: boolean | undefined,
    betSystemHistory?: BetSystemHistory
  ): boolean {
    const canReplay =
      this.canReplay(authorized, betSystemHistory) &&
      ((betSystemHistory != null && betSystemHistory.betLines.some(betLine => betTypeId !== betLine.betTypeId)) ||
        (betSystemHistory == null && this.lastPlacedBet.bet.betLines.some(betLine => betTypeId !== betLine.betTypeId)));

    return canReplay;
  }

  replayEvent(
    event: DrawGame,
    authorized: boolean | undefined,
    exceptBetTypeIds?: number[],
    onlyBetTypeIds?: number[],
    betSystemHistory?: BetSystemHistory
  ): void {
    if (event.eventBetTypes) {
      this.replayWithFullEvent(event, authorized, exceptBetTypeIds, onlyBetTypeIds, undefined, betSystemHistory);
    } else {
      this.eventsService
        .getEventDetails(event.id)
        .pipe(take(1))
        .subscribe((eventWithDetails: DrawGame) => {
          this.replayWithFullEvent(
            eventWithDetails,
            authorized,
            exceptBetTypeIds,
            onlyBetTypeIds,
            undefined,
            betSystemHistory
          );
        });
    }
  }

  replay(authorized: boolean | undefined, betSystemHistory?: BetSystemHistory, navigateUrl?: string) {
    this.messageService
      .sendComponentMessage(
        DrawGamesReplayComponent,
        {
          authorized: authorized,
          betSystemHistory: betSystemHistory,
          navigateUrl: navigateUrl
        },
        {
          canBeDismissed: true,
          displayClose: true,
          className: 'draw-game-replay'
        }
      )
      .closed.pipe(take(1))
      .subscribe();
  }

  replayDoubChans(
    event1: DrawGame,
    event2: DrawGame,
    authorized: boolean | undefined,
    betSystemHistory?: BetSystemHistory
  ): void {
    const mainEvent = event1.expectedStart > event2.expectedStart ? event1 : event2;
    const secondEvent = mainEvent.id === event1.id ? event2 : event1;
    this.replayWithFullEvent(
      mainEvent,
      authorized,
      undefined,
      [DrawGameBorletteBetType.DoubChans],
      secondEvent.id,
      betSystemHistory
    );
  }

  private replayWithFullEvent(
    event: DrawGame,
    authorized: boolean | undefined,
    exceptBetTypeIds: number[] | undefined,
    onlyBetTypeIds: number[] | undefined,
    associatedDrawGameId?: number,
    betSystemHistory?: BetSystemHistory
  ): void {
    if (this.canReplayEvent(event, authorized, undefined, betSystemHistory)) {
      const betLines = betSystemHistory != null ? betSystemHistory.betLines : this.lastPlacedBet.bet.betLines;
      betLines.forEach(betLine => {
        const eventBetType = event.eventBetTypes.find(x => x.betTypeId === betLine.betTypeId);
        if (
          eventBetType &&
          (eventBetType.betTypeId !== 40043 ||
            (betLine.associatedDrawGamesIds != null &&
              betLine.associatedDrawGamesIds.length > 0 &&
              event.id !== betLine.associatedDrawGamesIds[0]) ||
            (associatedDrawGameId != null && event.id !== associatedDrawGameId)) &&
          (!exceptBetTypeIds || !exceptBetTypeIds.includes(eventBetType.betTypeId)) &&
          (!onlyBetTypeIds || onlyBetTypeIds.includes(eventBetType.betTypeId))
        ) {
          let option = betLine.option;
          if (
            betSystemHistory != null &&
            (eventBetType.betTypeId === DrawGameBorletteBetType.Loto4 ||
              eventBetType.betTypeId === DrawGameBorletteBetType.Loto5)
          ) {
            option = +betLine.selectionDigest.split('/')[1].trim().split(':')[1].trim();
          }

          const betLineCopy = createBetLineWithSelection(
            event,
            eventBetType,
            betLine.baseList.map(x => (typeof x === 'string' ? x.replace(/[ x]/g, '') : x)),
            betLine.extraList,
            betSystemHistory != null ? betSystemHistory.betCategory : betLine.betCategoryType,
            event.drawGameRule,
            null,
            null,
            betLine.multiplier,
            undefined,
            undefined,
            option,
            associatedDrawGameId != null
              ? [associatedDrawGameId]
              : betLine.associatedDrawGamesIds != null && betLine.associatedDrawGamesIds.length > 0
              ? [betLine.associatedDrawGamesIds[0]]
              : undefined
          );

          betLineCopy.baseAmount = betSystemHistory != null ? betSystemHistory.systemStake : betLine.baseAmount;

          if (eventBetType.betTypeId === 40043) {
            this.eventsService
              .getEventFromCacheOrService(
                associatedDrawGameId != null ? associatedDrawGameId : betLine.associatedDrawGamesIds[0]
              )
              .pipe(take(1))
              .subscribe(x => {
                if (x?.expectedStart && x.expectedStart > new Date(Date.now())) {
                  this.betSlipService.addBetLine(
                    betLineCopy,
                    betSystemHistory != null
                      ? betSystemHistory.systemStake
                      : (betLineCopy.multiplier ?? 1) * betLineCopy.baseAmount
                  );
                }
              });
          } else {
            this.betSlipService.addBetLine(
              betLineCopy,
              betSystemHistory != null
                ? betSystemHistory.systemStake
                : (betLineCopy.multiplier ?? 1) * betLineCopy.baseAmount
            );
          }
        }
      });
    }
  }

  manageDrawGameBetPlaced(placedBet: BetPlaced): void {
    this.lastPlacedBet = placedBet;
    sessionStorage.setItem(this.LAST_PLACED_BET_STORAGE_KEY, JSON.stringify(this.lastPlacedBet));
    this.drawGameBetPlacedSubject.next();
  }
}
