import { Component, OnInit, ChangeDetectionStrategy, Inject, ChangeDetectorRef, Optional } from '@angular/core';
import { ActivatedRoute, NavigationEnd, Router } from '@angular/router';
import { OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';
import { DestroySubject } from '@honoregaming/core';
import { CustomerOperatorConfiguration, customerOperatorConfigurationToken } from '@honoregaming/customer-core';
import { BetCategoryType } from '@honoregaming/types';
import { Media, MediaService } from '@honoregaming/ui';
import { filter, takeUntil } from 'rxjs/operators';

@Component({
  selector: 'hg-table-contents',
  templateUrl: './table-contents.component.html',
  styleUrls: ['./table-contents.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class TableContentsComponent extends DestroySubject implements OnInit {
  pointOfSalesCategories = this.customerOperatorConfiguration?.resourcesConfiguration?.pointOfSalesCategories;
  operatorName: string;
  showLinks = false;
  generalItems: { link: string; translationKey: string; order?: number }[];
  isGeneralInformations = false;
  isMobile = false;
  BetCategoryType = BetCategoryType;

  constructor(
    private cdref: ChangeDetectorRef,
    private route: ActivatedRoute,
    private router: Router,
    @Optional() private mediaService: MediaService,
    @Inject(customerOperatorConfigurationToken) private customerOperatorConfiguration: CustomerOperatorConfiguration,
    @Inject(operatorConfigurationToken) private operatorConfiguration: OperatorConfiguration
  ) {
    super();
  }

  ngOnInit() {
    this.generalItems = this.customerOperatorConfiguration.customization?.footer?.general;
    this.operatorName = this.operatorConfiguration.resourcesConfiguration?.name ?? this.operatorConfiguration.name;

    this.checkUrl(this.route.snapshot['_routerState'].url);

    this.router.events
      .pipe(filter(x => x instanceof NavigationEnd))
      .pipe(takeUntil(this.destroy$))
      .subscribe((e: NavigationEnd) => {
        this.checkUrl(e.url);
        this.cdref.markForCheck();
      });

    this.cdref.markForCheck();
  }

  checkUrl(url: any) {
    this.mediaService.media$.pipe(takeUntil(this.destroy$)).subscribe(x => {
      if (x < Media.lg) {
        this.isMobile = true;

        if (
          url === '/about/content/about' ||
          url.includes('/about/points-of-sale') ||
          this.generalItems?.find(i => i.link === url)
        ) {
          this.isGeneralInformations = true;
        } else {
          this.isGeneralInformations = false;
        }
      } else {
        this.isMobile = false;
      }

      this.cdref.markForCheck();
    });
  }

  onClickShowLinks() {
    this.showLinks = !this.showLinks;
  }
}
