import { Component, ChangeDetectionStrategy, Input, Output, EventEmitter, OnInit } from '@angular/core';

@Component({
  selector: 'hg-bet-builder-filter',
  templateUrl: './bet-builder-filter.component.html',
  styleUrls: ['./bet-builder-filter.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class BetBuilderFilterComponent implements OnInit {
  @Input() isBetBuilderToggled: boolean = false;
  @Input() disabled: boolean = false;
  @Input() hasNew: boolean = false;

  @Output() betBuilderToggled = new EventEmitter<boolean>();

  isToggleActivated: boolean = false;

  constructor() {}

  ngOnInit() {
    this.isToggleActivated = this.isBetBuilderToggled;
  }

  toggleBetBuilder(isToggled: boolean): void {
    if (!this.disabled && isToggled !== this.isToggleActivated) {
      this.isToggleActivated = isToggled;
      this.betBuilderToggled.emit(isToggled);
    }
  }
}
