import { Component, ChangeDetectionStrategy, Output, EventEmitter } from '@angular/core';
import { Router } from '@angular/router';

@Component({
  selector: 'hg-search-field',
  templateUrl: './search-field.component.html',
  styleUrls: ['./search-field.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class SearchFieldComponent {
  search: string;

  @Output() clickOnBurger = new EventEmitter<boolean>();
  @Output() searchLaunched = new EventEmitter<void>();

  constructor(private router: Router) {}

  onSubmit() {
    this.router.navigate(['sports', 'search', this.search]);
    this.clickOnBurger.emit(false);
    this.searchLaunched.emit();
  }

  trackEvent(_eventName: string): void {}
}
