import {
  Component,
  ChangeDetectionStrategy,
  ViewChild,
  ElementRef,
  AfterViewInit,
  Output,
  EventEmitter
} from '@angular/core';

@Component({
  selector: 'hg-confettis',
  templateUrl: './confettis.component.html',
  styleUrls: ['./confettis.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class ConfettisComponent implements AfterViewInit {
  @Output() animationFinished = new EventEmitter();

  @ViewChild('canvas', { static: true }) canvasRef!: ElementRef<HTMLCanvasElement>;

  private ctx!: CanvasRenderingContext2D;

  private viewWidth = 800;
  private viewHeight = 547;
  private timeStep = 1 / 60;
  private particles: any[] = [];

  constructor() {}

  ngAfterViewInit(): void {
    setTimeout(() => {
      this.initDrawingCanvas();
      requestAnimationFrame(() => this.loop());
    }, 500);
  }

  private initDrawingCanvas(): void {
    const canvas = this.canvasRef.nativeElement;
    canvas.width = this.viewWidth;
    canvas.height = this.viewHeight;
    this.ctx = canvas.getContext('2d')!;
    this.createParticles();
  }

  private Point = class {
    constructor(public x: number = 0, public y: number = 0) {}
  };

  private Particle = class {
    private x: number;
    private y: number;
    private r: number = 0;
    private sy: number = 1;
    private w = 8;
    private h = 6;
    private color: string;
    private time = 0;
    private duration: number;
    complete = false;

    constructor(
      private ctx: CanvasRenderingContext2D,
      private p0: any,
      private p1: any,
      private p2: any,
      private p3: any,
      private timeStep: number,
      private Ease: any,
      private cubeBezier: Function
    ) {
      this.x = p0.x;
      this.y = p0.y;
      this.color = '#' + Math.floor(Math.random() * 0xffffff).toString(16);
      this.duration = 3 + Math.random() * 2;
    }

    update() {
      this.time = Math.min(this.duration, this.time + this.timeStep);
      const f = this.Ease.outCubic(this.time, 0, 1, this.duration);
      const p = this.cubeBezier(this.p0, this.p1, this.p2, this.p3, f);
      const dx = p.x - this.x;
      const dy = p.y - this.y;

      this.r = Math.atan2(dy, dx) + Math.PI * 0.5;
      this.sy = Math.sin(Math.PI * f * 10);
      this.x = p.x;
      this.y = p.y;

      this.complete = this.time === this.duration;
    }

    draw() {
      this.ctx.save();
      this.ctx.translate(this.x, this.y);
      this.ctx.rotate(this.r);
      this.ctx.scale(1, this.sy);
      this.ctx.fillStyle = this.color;
      this.ctx.fillRect(-this.w * 0.5, -this.h * 0.5, this.w, this.h);
      this.ctx.restore();
    }
  };

  // Easing and bezier helpers
  private Ease = {
    outCubic: (t: number, b: number, c: number, d: number) => {
      t /= d;
      t--;
      return c * (t * t * t + 1) + b;
    },
    inBack: (t: number, b: number, c: number, d: number, s: number = 1.70158) => {
      return c * (t /= d) * t * ((s + 1) * t - s) + b;
    }
  };

  private cubeBezier(p0: any, c0: any, c1: any, p1: any, t: number) {
    const nt = 1 - t;
    const p = new this.Point();
    p.x = nt * nt * nt * p0.x + 3 * nt * nt * t * c0.x + 3 * nt * t * t * c1.x + t * t * t * p1.x;
    p.y = nt * nt * nt * p0.y + 3 * nt * nt * t * c0.y + 3 * nt * t * t * c1.y + t * t * t * p1.y;
    return p;
  }

  private createParticles() {
    for (let i = 0; i < 128; i++) {
      const p0 = new this.Point(this.viewWidth / 2, this.viewHeight / 2);
      const p1 = new this.Point(Math.random() * this.viewWidth, Math.random() * this.viewHeight);
      const p2 = new this.Point(Math.random() * this.viewWidth, Math.random() * this.viewHeight);
      const p3 = new this.Point(Math.random() * this.viewWidth, this.viewHeight + 64);
      this.particles.push(
        new this.Particle(this.ctx, p0, p1, p2, p3, this.timeStep, this.Ease, this.cubeBezier.bind(this))
      );
    }
  }

  private loop(): void {
    this.update();
    this.draw();

    if (this.checkParticlesComplete()) {
      this.animationFinished.emit();
      return;
    }

    requestAnimationFrame(() => this.loop());
  }

  private update() {
    this.particles.forEach(p => p.update());
  }

  private draw() {
    this.ctx.clearRect(0, 0, this.viewWidth, this.viewHeight);
    this.particles.forEach(p => p.draw());
  }

  private checkParticlesComplete(): boolean {
    return this.particles.every(p => p.complete);
  }
}
