import { Inject, Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { BehaviorSubject, Observable } from 'rxjs';
import {
  Feature,
  globalConfiguration,
  OperatorConfiguration,
  operatorConfigurationToken
} from '@honoregaming/configuration';
import { Cacheable, CacheableVaryByKey, DestroySubject } from '@honoregaming/core';
import { Charity } from '../models/charity.model';
import { I18nService } from '@honoregaming/i18n';
import { BackEndCharity } from '../models/backend-charity.model';
import { finalize, map, takeUntil } from 'rxjs/operators';
import { CharityAmount } from '../models/charity-amount.model';
import { CharityDonation } from '../models/charity-donation.model';
import { CharityDonationResult } from '../models/charity-donation-result';

@Injectable({ providedIn: 'root' })
export class CharityService extends DestroySubject {
  @CacheableVaryByKey()
  userLanguage: string;

  private readonly charityAmountSubject = new BehaviorSubject<CharityAmount>(null);
  public charityAmount$ = this.charityAmountSubject.asObservable();

  private readonly charityAmountsSubject = new BehaviorSubject<CharityAmount[]>(null);
  public charityAmounts$ = this.charityAmountsSubject.asObservable();

  constructor(
    private readonly httpClient: HttpClient,
    private readonly i18nService: I18nService,
    @Inject(operatorConfigurationToken) private readonly operatorConfiguration: OperatorConfiguration
  ) {
    super();
    this.i18nService.languageChanged$.subscribe(l => (this.userLanguage = l));
  }

  @Cacheable()
  getCharities(): Observable<Charity[]> {
    return this.httpClient
      .get<BackEndCharity[]>(`${globalConfiguration.apiBaseUrl}charity?${this.userLanguage}`)
      .pipe(map(backEndCharities => backEndCharities.map(backEndCharity => this.mapCharity(backEndCharity))));
  }

  @Cacheable()
  getCharity(id: number): Observable<Charity> {
    return this.httpClient
      .get<BackEndCharity>(`${globalConfiguration.apiBaseUrl}charity/${id}`)
      .pipe(map(backEndCharity => this.mapCharity(backEndCharity)));
  }

  @Cacheable()
  showCharityNavigation(): Observable<boolean> {
    return this.httpClient
      .get<boolean>(`${globalConfiguration.apiBaseUrl}charity/any?${this.userLanguage}`)
      .pipe(
        map(anyCharity => this.operatorConfiguration.operatorFeatures.indexOf(Feature.Charity) !== -1 && anyCharity)
      );
  }

  donateToCharity(charityId: number, amount: number) {
    return this.httpClient
      .post<CharityDonationResult>(`${globalConfiguration.apiBaseUrl}charity/donate/${charityId}`, {
        amount
      })
      .pipe(
        finalize(() => {
          this.getCharityAmount(charityId);
        })
      );
  }

  getCharityAmount(id: number) {
    this.httpClient
      .get<CharityAmount>(`${globalConfiguration.apiBaseUrl}charity/amounts/${id}`)
      .pipe(takeUntil(this.destroy$))
      .subscribe(charityAmount => {
        this.charityAmountSubject.next(charityAmount);
      });
  }

  getCharitiesAmounts() {
    this.httpClient
      .get<CharityAmount[]>(`${globalConfiguration.apiBaseUrl}charity/amounts`)
      .pipe(takeUntil(this.destroy$))
      .subscribe(charityAmounts => {
        this.charityAmountsSubject.next(charityAmounts);
      });
  }

  private mapCharity(backEndCharity: BackEndCharity): Charity {
    const charity: Charity = backEndCharity;

    this.showAmountOrNot(charity);

    return charity;
  }

  getCharityDonations(charityId: number, pageNumber: number, pageSize: number) {
    return this.httpClient.get<CharityDonation[]>(`${globalConfiguration.apiBaseUrl}charity/history/${charityId}`, {
      params: {
        pageNumber,
        pageSize
      }
    });
  }

  updateCharityAmount(charity: Charity, charityAmount: CharityAmount) {
    if (!charity || !charityAmount || charity.id !== charityAmount.id) {
      return;
    }

    charity.amount = charityAmount.amount;
    charity.claimedBonus = charityAmount.claimedBonus;

    charity.percentage = charityAmount.percentage;

    this.showAmountOrNot(charity);

    charity.percentage = Math.floor(charityAmount.percentage);
    charity.totalDonors = charityAmount.donors;

    if (charity.totalDonors > 1000) {
      const number = Math.floor(charity.totalDonors / 1000);
      charity.totalDonorsText = `${number} K`;
    } else if (charity.totalDonors) {
      charity.totalDonorsText = `${charity.totalDonors}`;
    }
  }

  showAmountOrNot(charity: Charity) {
    if (charity.percentage > 1) {
      charity.showAmount = 'TRUE';
    } else if (charity.targetAmount) {
      charity.showAmount = 'TARGET_AMOUNT_ONLY';
    } else if (charity.amount) {
      charity.showAmount = 'AMOUNT_ONLY';
    } else {
      charity.showAmount = 'FALSE';
    }
  }
}
