declare var window: any;

import { switchMap } from 'rxjs/operators';
import { Inject, Injectable, PLATFORM_ID } from '@angular/core';
import { DestroySubject } from '@honoregaming/core';
import { ICaptchaService } from './captcha-service.model';
import { CustomerService } from '../customer.service';
import { SecurityPolicy } from '@honoregaming/types';
import { isPlatformBrowser } from '@angular/common';
import { Observable, of } from 'rxjs';
import FingerprintJS from '@fingerprintjs/fingerprintjs-pro/dist/fp.esm.min';

@Injectable()
export class FingerprintCaptchaService extends DestroySubject implements ICaptchaService {
  private securityPolicy: SecurityPolicy;

  private requestId: string;

  constructor(private customerService: CustomerService, @Inject(PLATFORM_ID) private platformId) {
    super();
  }

  loadCaptcha(securityPolicy: SecurityPolicy) {
    this.securityPolicy = securityPolicy;
  }

  applyCaptcha(_targetElement: string): Observable<void> {
    return this.customerService.getSecurityPolicy().pipe(
      switchMap(securityPolicy => {
        this.securityPolicy = securityPolicy;

        if (this.securityPolicy.captchaProvider?.fingerprint?.enabled && isPlatformBrowser(this.platformId)) {
          const fpPromise = FingerprintJS.load({
            apiKey: this.securityPolicy.captchaProvider.fingerprint.browserToken,
            region: 'eu'
          });

          fpPromise
            .then(fp => fp.get())
            .then(result => {
              this.requestId = result.requestId;
            });
        }

        return of(void 0);
      })
    );
  }

  validateCaptcha(): Observable<string> {
    if (this.securityPolicy.captchaProvider?.fingerprint?.enabled && isPlatformBrowser(this.platformId)) {
      return of(this.requestId);
    }

    return of(null);
  }

  getLegend(): string {
    return null;
  }

  clearCaptcha(): void {
    this.requestId = null;
  }
}
