import { Injectable } from '@angular/core';
import { globalConfiguration } from '@honoregaming/configuration';
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Observable, of, throwError } from 'rxjs';
import {
  BetSlipMode,
  CompleteMyBetResponse,
  DrawGameBorletteBetType,
  BetBuilderError,
  BetBuilderEventItemIds
} from '@honoregaming/types';
import { Amounts, BettingError, BetLine, CreateBetFailures, RebetBetLine } from '../models';
import { catchError } from 'rxjs/operators';
import { InstantGameTransaction } from '../models/instant-game-transaction.model';
import { CreateBetCodeRequest } from '../models/api/create-bet.request';
import { CreateInstantGameTransactionRequest } from '../models/api/create-instant-game-transaction.request';
import {
  CreateBetResponse,
  CreateInstantGameTransactionResponse,
  CreateInstantGameTransactionsResponse
} from '../models/api/create-bet.response';
import { BetCodeBet } from '../models/betcode-bet.model';
import { CashoutBetRequest } from '../models/api/cashout-bet.request';
import { CashoutError } from '../models/cashout-error.model';
import { buildQueryString } from '@honoregaming/core';
import { UpdateInstantGameTransactionResponse } from '../models/api/update-instant-game-transaction.response';
import { OddsBoostRebetBetLine } from '../models/odds-boos-rebet-betline.model';
import { UpdateInstantGameTransactionRequest } from '../models/api/update-instant-game-transaction.request';
import { ManualOddsBoostRebetBetLine } from '../models/manual-odds-boost-betline.model';
import { BetComputingService } from './bet-computing.service';
import { BetBuilderOddsResponse } from '../models/api/bet-builder.response';

@Injectable({ providedIn: 'root' })
export class BettingApiService {
  constructor(private httpClient: HttpClient, private betComputingService: BetComputingService) {}

  placeBet(
    betLines: BetLine[],
    mode: BetSlipMode,
    amounts: Amounts,
    acceptOddChange: boolean,
    useFreeBet: boolean,
    betCode?: string,
    customerBehalfId: number | null = null,
    freebetCouponId?: number,
    completeMyBetId: number | null = null
  ): Observable<CreateBetResponse> {
    const request = this.betComputingService.computeRequest(
      this.filterBetLines(betLines),
      mode,
      amounts,
      betCode,
      acceptOddChange,
      useFreeBet,
      customerBehalfId,
      freebetCouponId,
      completeMyBetId
    );

    return this.httpClient
      .post<CreateBetResponse>(`${globalConfiguration.apiBettingBaseUrl}betting`, request)
      .pipe(catchError(this.catchRequestError));
  }

  placeSportsPoolBet(betLines: BetLine[], amounts: Amounts, freebetCouponId?: number): Observable<CreateBetResponse> {
    const request = this.betComputingService.computeSportsPoolRequest(betLines, amounts, freebetCouponId);
    return this.httpClient
      .post<CreateBetResponse>(`${globalConfiguration.apiBettingBaseUrl}sportspool/betting`, request)
      .pipe(catchError(this.catchRequestError));
  }

  placeSimulateBet(betLines: BetLine[], mode: BetSlipMode, amounts: Amounts): Observable<CreateBetResponse> {
    const request = this.betComputingService.computeSimulateRequest(betLines, mode, amounts);

    return this.httpClient
      .post<CreateBetResponse>(`${globalConfiguration.apiBettingBaseUrl}insagames/betting/simulate`, request)
      .pipe(catchError(this.catchRequestError));
  }

  createInstantGameTransaction(
    instantGameTransaction: CreateInstantGameTransactionRequest,
    customerBehalfId: number | null = null
  ): Observable<CreateInstantGameTransactionResponse> {
    return this.httpClient
      .post<CreateInstantGameTransactionResponse>(
        `${globalConfiguration.apiBettingBaseUrl}instantgames/create-transaction`,
        { ...instantGameTransaction, customerId: customerBehalfId }
      )
      .pipe(catchError(this.catchRequestError));
  }

  updateMusikaInstantGameTransaction(
    updateInstantGameTransactionRequest: UpdateInstantGameTransactionRequest
  ): Observable<UpdateInstantGameTransactionResponse> {
    return this.httpClient
      .post<UpdateInstantGameTransactionResponse>(
        `${globalConfiguration.apiBettingBaseUrl}instantgames/update-musika-transaction`,
        updateInstantGameTransactionRequest
      )
      .pipe(catchError(this.catchRequestError));
  }

  createInstantGameTransactions(
    instantGameTransactions: InstantGameTransaction[],
    customerBehalfId: number | null = null
  ): Observable<CreateInstantGameTransactionsResponse> {
    return this.httpClient
      .post<CreateInstantGameTransactionsResponse>(
        `${globalConfiguration.apiBettingBaseUrl}instantgames/create-transactions`,
        instantGameTransactions.map(
          transaction =>
            <CreateInstantGameTransactionRequest>{
              instantGameName: transaction.instantGame,
              stake: transaction.stake,
              multiplier: transaction.multiplier,
              selection: transaction.betSlipObject,
              selections: transaction.selections,
              instantGameMode: transaction.gameMode,
              customerId: customerBehalfId
            }
        )
      )
      .pipe(catchError(this.catchRequestError));
  }

  getBetCode(betCodeRequest: CreateBetCodeRequest): Observable<{ code: string }> {
    return this.httpClient
      .post<{ code: string }>(`${globalConfiguration.apiBettingBaseUrl}betting/get-my-code`, betCodeRequest)
      .pipe(catchError(this.catchRequestError));
  }

  getBetFromBetCode(betCode: string): Observable<BetCodeBet> {
    return this.httpClient.get<BetCodeBet>(`${globalConfiguration.apiBettingBaseUrl}betting/${betCode}`);
  }

  applyCashout(cashoutRequest: CashoutBetRequest): Observable<void> {
    return this.httpClient
      .post<void>(`${globalConfiguration.apiBettingBaseUrl}cashout`, cashoutRequest)
      .pipe(catchError(this.catchCashoutRequestError));
  }

  initCompleteMyBet(betId: number): Observable<CompleteMyBetResponse> {
    return this.httpClient
      .post<CompleteMyBetResponse>(`${globalConfiguration.apiBettingBaseUrl}betting/complete-my-bet`, {
        betId
      })
      .pipe(catchError(this.catchRequestError));
  }

  getBetLinesToRebet(eventBetTypeItemIds: number[] = null, betSystemId: number = null): Observable<RebetBetLine[]> {
    return this.httpClient
      .get<RebetBetLine[]>(
        `${globalConfiguration.apiBettingBaseUrl}betting/rebet${buildQueryString({ eventBetTypeItemIds, betSystemId })}`
      )
      .pipe(catchError(this.catchRequestError));
  }

  getOddsBoostBetLinesToRebet(oddsBoostIds: number[]): Observable<OddsBoostRebetBetLine[]> {
    return this.httpClient
      .get<OddsBoostRebetBetLine[]>(
        `${globalConfiguration.apiBettingBaseUrl}betting/oddsboost-rebet${buildQueryString({ oddsBoostIds })}`
      )
      .pipe(catchError(this.catchRequestError));
  }

  getManualOddsBoostBetLinesToRebet(manualOddsBoostIds: number[]): Observable<ManualOddsBoostRebetBetLine[]> {
    return this.httpClient
      .get<ManualOddsBoostRebetBetLine[]>(
        `${globalConfiguration.apiBettingBaseUrl}betting/manualoddsboost-rebet${buildQueryString({
          manualOddsBoostIds
        })}`
      )
      .pipe(catchError(this.catchRequestError));
  }

  getBetBuilderOdds(
    betBuilderEventsItemIds: BetBuilderEventItemIds[],
    existingBetBuilderBetLinesCount: number
  ): Observable<BetBuilderOddsResponse> {
    return this.httpClient
      .post<BetBuilderOddsResponse>(`${globalConfiguration.apiBettingBaseUrl}betting/bet-builder/odds`, {
        betBuilderEventsItemIds,
        existingBetBuilderBetLinesCount
      })
      .pipe(
        catchError(() =>
          of({
            betBuilderOddsResults: betBuilderEventsItemIds.map((betBuilderEventItemIds: BetBuilderEventItemIds) => ({
              eventId: betBuilderEventItemIds.eventId,
              eventBetTypeItemIds: betBuilderEventItemIds.eventBetTypeItemIds,
              betBuilderOdds: {
                odds: 0,
                betBuilderError: BetBuilderError.ContradictorySelection
              }
            }))
          })
        )
      );
  }

  private catchRequestError(err: HttpErrorResponse) {
    const bettingError: BettingError = {
      failure: null,
      betLinesFailures: null,
      correlationId: err.error?.correlationId
    };

    if (err.status === 401) {
      bettingError.failure = 401;
    }

    if (err.status === 429) {
      bettingError.failure = CreateBetFailures.TooManyRequests;
    }

    if (err.error?.code != null) {
      bettingError.failure = err.error?.code;
    }

    if (err.error?.additionalData) {
      bettingError.betLinesFailures = Object.entries(err.error.additionalData)
        .filter((x: [string, any[]]) => x[1] && x[1].length)
        .map((x: [string, any[]]) => ({ number: +x[0], reason: x[1] }));
      bettingError.data = err.error.additionalData;
    }

    return throwError(bettingError);
  }

  private catchCashoutRequestError(err: HttpErrorResponse) {
    const cashoutError: CashoutError = {
      failure: null,
      correlationId: err.error?.correlationId
    };

    if (err.error?.code != null) {
      cashoutError.failure = err.error?.code;
    }

    if (err.error?.additionalData) {
      cashoutError.data = err.error.additionalData;
    }

    return throwError(cashoutError);
  }

  private filterBetLines(betLines: BetLine[]): BetLine[] {
    return betLines.filter(
      x => x.betTypeId !== DrawGameBorletteBetType.DoubChans || (x.associatedDrawGamesIds?.length ?? 0) > 0
    );
  }
}
