import { Injectable } from '@angular/core';
import {
  BetBuilderLine,
  BetCategoryType,
  BetLineHistory,
  BetSlipMode,
  BetSystemHistory,
  EventBetType,
  EventBetTypeItem,
  EventWithEventBetTypes,
  ManualOddsBoost,
  Match,
  OddsBoost,
  SelectableEventBetTypeItem
} from '@honoregaming/types';
import {
  Amounts,
  BetLine,
  BetLineWithEvent,
  BetSelection,
  BetSlipBetBuilderService,
  BetSlipService,
  createBetLine,
  createManualOddsBoostBetLine,
  createOddsBoostBetLine
} from '@honoregaming/betslip';
import { ApplicationEvent, BetLinesMapperService, BroadcastingService } from '@honoregaming/core';
import { defer, from, iif, Observable, of } from 'rxjs';
import { concatAll, concatMap, filter, map, switchMap, take, tap } from 'rxjs/operators';
import { EventsService, FetchEventBetTypesMode } from '@honoregaming/events';
import { GenericQuestionComponent, MessageService } from '@honoregaming/ui';
import { BetCodeResponse } from '../models/betcode-bet.model';

@Injectable({
  providedIn: 'root'
})
export class BetSlipBetLinesService {
  constructor(
    private readonly betSlipService: BetSlipService,
    private readonly betSlipBetBuilderService: BetSlipBetBuilderService,
    private readonly broadcastingService: BroadcastingService,
    private readonly eventsService: EventsService,
    private readonly betLinesMapperService: BetLinesMapperService,
    private readonly messageService: MessageService
  ) {}

  get isLoadingOddsEventIds$(): Observable<number[]> {
    return this.betSlipBetBuilderService.isLoadingOddsEventIds$;
  }

  get disabledModes(): BetSlipMode[] {
    return this.betSlipService.disabledModes;
  }

  changeMode(mode: BetSlipMode): void {
    const hasBetBuilderChanges: boolean = this.betSlipBetBuilderService.tryChangeBetSlipMode(mode, true);
    if (!hasBetBuilderChanges) {
      this.betSlipService.changeMode(mode, true);
    }
  }

  toggleOddsBoost(oddsBoost: OddsBoost & { nextEventDate: Date; selected: boolean }): void {
    const betLine: BetLine = createOddsBoostBetLine(oddsBoost);
    const selected: boolean = !oddsBoost.selected;
    const hasOddsBoostIdPlaced: boolean = this.tryClearPlacedBet(betLine);
    this.toggleBetLine(betLine, hasOddsBoostIdPlaced && !selected ? true : selected);
  }

  toggleManualOddsBoost(manualOddsBoost: ManualOddsBoost & { selected: boolean }): void {
    const betLine: BetLine = createManualOddsBoostBetLine(manualOddsBoost);
    const selected: boolean = !manualOddsBoost.selected;
    const hasManualOddsBoostIdPlaced: boolean = this.tryClearPlacedBet(betLine);
    this.toggleBetLine(betLine, hasManualOddsBoostIdPlaced && !selected ? true : selected);
  }

  toggleBetLine(betLine: BetLine, isSelected: boolean): void {
    if (!isSelected) {
      this.updateBetSlipBetLine(betLine.eventId, false, [], false, betLine);
      return;
    }

    this.validateBetSlipModeChanges(this.betSlipService.betLinesValue, [betLine])
      .pipe(
        take(1),
        filter((isValidMode: boolean) => isValidMode)
      )
      .subscribe(() => this.betSlipService.addBetLine(betLine));
  }

  toggleEventBetTypeItem(
    match: Match,
    eventBetType: EventBetType,
    eventBetTypeItem: SelectableEventBetTypeItem,
    isSelected: boolean,
    betCategoryType: BetCategoryType = BetCategoryType.SportsFixedOdds,
    eventCategoryName?: string
  ): Observable<boolean> {
    const hasEventBetTypeItemIdPlaced: boolean = this.tryClearPlacedBet({ eventBetTypeItemId: eventBetTypeItem.id });
    eventBetTypeItem.selected = hasEventBetTypeItemIdPlaced && !isSelected ? true : isSelected;

    return (
      eventBetTypeItem.selected
        ? this.validateBetSlipModeChanges(this.betSlipService.betLinesValue, [
            createBetLine(match, eventBetType, eventBetTypeItem, betCategoryType, eventCategoryName)
          ])
        : of(true)
    ).pipe(
      switchMap((isValidMode: boolean) =>
        iif(
          () => isValidMode,
          this.updateBetLineSelection(match, eventBetType, eventBetTypeItem, betCategoryType).pipe(
            map((betLine: BetLine) => !!betLine)
          ),
          of(isValidMode)
        )
      )
    );
  }

  rebet(betSystem: BetSystemHistory): Observable<{ success: boolean; betCategory?: BetCategoryType }> {
    return betSystem.betLines.some((betLineHistory: BetLineHistory) => betLineHistory.betBuilderLines?.length)
      ? this.betSlipBetBuilderService.rebet(betSystem)
      : this.betSlipService.replaceBetLines(betSystem, betSystem.type);
  }

  // Set betslip state from bet code
  // Save bet builder bet code amount as last stake to avoid reset on mode change
  rehydrateFromBetCode(betCode: string): Observable<BetCodeResponse> {
    return this.betSlipService.rehydrateFromBetCode(betCode).pipe(
      tap((betCodeResponse: BetCodeResponse) => {
        if (betCodeResponse.hasBetBuilderBetLines) {
          const amounts: Amounts = this.betSlipService.amountsValue;
          const targetAmount: number | undefined = amounts.values.length ? amounts.values[0].amount : undefined;
          if (targetAmount) {
            this.betSlipService.saveLastBetStakePerBetCategory(targetAmount);
          }
          this.betSlipBetBuilderService.tryChangeToMultipleMode();
        }
      })
    );
  }

  // Fetch last selection events info then create bet lines with existing manual selection process
  // Finally ensure that mode will not be switched to multiple if last selection combined to existing bet lines is eligible
  copyLastSelection(betCategoryType: BetCategoryType): Observable<boolean> {
    const existingBetLines: BetLine[] = this.betSlipService.betLinesValue;
    const existingEventBetTypeItemIds: number[] =
      this.betLinesMapperService.betLinesToEventBetTypeItemIds(existingBetLines);
    const lastBetSelection: BetSelection | undefined = this.betSlipService.getLastSelection(betCategoryType);
    const lastBetLinesSelection: BetLine[] =
      lastBetSelection?.betLines.filter(
        (betLine: BetLine) =>
          !betLine.eventBetTypeItemId || !existingEventBetTypeItemIds.includes(betLine.eventBetTypeItemId)
      ) ?? [];
    const eventsId: number[] = lastBetLinesSelection.reduce((eventsId: number[], lastBetLineSelection: BetLine) => {
      if (!eventsId.includes(lastBetLineSelection.eventId)) {
        eventsId.push(lastBetLineSelection.eventId);
      }
      return eventsId;
    }, []);

    return !eventsId.length
      ? of(false)
      : this.validateBetSlipModeChanges(existingBetLines, lastBetLinesSelection).pipe(
          filter((isValidMode: boolean) => isValidMode),
          switchMap(() =>
            this.eventsService.getEventsByIds(0, eventsId.length, FetchEventBetTypesMode.All, null, [], false, eventsId)
          ),
          take(1),
          map((events: { result: EventWithEventBetTypes<Match>[]; hasMore: boolean }) =>
            lastBetLinesSelection.map((lastBetLineSelection: BetLine) => ({
              betLine: lastBetLineSelection,
              event: events.result.find(
                (event: EventWithEventBetTypes<Match>) => event.id === lastBetLineSelection.eventId
              )
            }))
          ),
          concatMap((betLinesWithEvents: BetLineWithEvent[]) => {
            const betLinesObservables$: Observable<BetLine>[] = this.buildBetLinesFromLastSelection(
              betLinesWithEvents,
              existingEventBetTypeItemIds
            );
            return betLinesObservables$.length
              ? from(betLinesObservables$).pipe(
                  concatAll(),
                  map(() => true)
                )
              : of(true);
          }),
          tap(() => {
            if (lastBetSelection.mode === BetSlipMode.Simple && this.betSlipService.mode === BetSlipMode.Multiple) {
              this.changeMode(lastBetSelection.mode);
            }
          })
        );
  }

  private buildBetLinesFromLastSelection(
    betLinesWithEvents: BetLineWithEvent[],
    existingEventBetTypeItemIds: number[]
  ): Observable<BetLine>[] {
    return betLinesWithEvents.reduce(
      (betLinesObservables: Observable<BetLine>[], betLineWithEvent: BetLineWithEvent) => {
        if (!betLineWithEvent.betLine.betBuilderLines?.length) {
          betLinesObservables.push(
            defer(() =>
              this.buildBetLineFromIds(
                betLineWithEvent.event,
                betLineWithEvent.betLine.eventBetTypeId,
                betLineWithEvent.betLine.eventBetTypeItemId
              )
            )
          );
        } else {
          betLinesObservables.push(
            ...betLineWithEvent.betLine.betBuilderLines
              .filter(
                (betBuilderLine: BetBuilderLine) =>
                  !existingEventBetTypeItemIds.includes(betBuilderLine.eventBetTypeItemId)
              )
              .map((betBuilderLine: BetBuilderLine) =>
                defer(() =>
                  this.buildBetLineFromIds(
                    betLineWithEvent.event,
                    betBuilderLine.eventBetTypeId,
                    betBuilderLine.eventBetTypeItemId
                  )
                )
              )
          );
        }
        return betLinesObservables;
      },
      []
    );
  }

  private buildBetLineFromIds(
    eventWithEventBetTypes: EventWithEventBetTypes<Match>,
    eventBetTypeId: number,
    eventBetTypeItemId: number
  ): Observable<BetLine> {
    const eventBetType: EventBetType | undefined = eventWithEventBetTypes.eventBetTypes.find(
      (eventBetType: EventBetType) => eventBetType.id === eventBetTypeId
    );
    const eventBetTypeItem: EventBetTypeItem | undefined = eventBetType?.eventBetTypeItems.find(
      (eventBetTypeItem: EventBetTypeItem) => eventBetTypeItem.id === eventBetTypeItemId
    );
    return eventBetType && eventBetTypeItem
      ? this.updateBetLineSelection(eventWithEventBetTypes, eventBetType, { ...eventBetTypeItem, selected: true })
      : of(null);
  }

  private updateBetLineSelection(
    match: Match,
    eventBetType: EventBetType,
    eventBetTypeItem: SelectableEventBetTypeItem,
    betCategoryType: BetCategoryType = BetCategoryType.SportsFixedOdds
  ): Observable<BetLine> {
    const existingMatchBetLines: BetLine[] = this.betSlipService.getEventBetLines(match.id);
    return this.createOrUpdateBetLine(
      match,
      eventBetType,
      eventBetTypeItem,
      existingMatchBetLines,
      betCategoryType
    ).pipe(
      take(1),
      tap((betLine: BetLine) => {
        this.broadcastingService.broadcast(ApplicationEvent.BetSelected, {
          event: match,
          eventBetType: eventBetType
        });
        this.updateBetSlipBetLine(
          match.id,
          match.allowBetBuilder,
          existingMatchBetLines,
          eventBetTypeItem.selected,
          betLine
        );
      })
    );
  }

  // Create or update a betBuilderBetLine if a new item of the same match is selected and eligible or if an existing betBuilderLine is unselected with still at least two existing items
  // Otherwise create a simple line
  private createOrUpdateBetLine(
    match: Match,
    eventBetType: EventBetType,
    item: SelectableEventBetTypeItem,
    existingMatchBetLines: BetLine[],
    betCategoryType: BetCategoryType = BetCategoryType.SportsFixedOdds
  ): Observable<BetLine> {
    const existingBetBuilderLinesCount: number =
      existingMatchBetLines.length && existingMatchBetLines[0].betBuilderLines?.length
        ? existingMatchBetLines[0].betBuilderLines.length
        : 0;

    return this.isBetBuilderBetLine(match, eventBetType, item, existingMatchBetLines, existingBetBuilderLinesCount)
      ? this.betSlipBetBuilderService.createOrUpdateBetBuilderBetLine(
          match,
          eventBetType,
          item,
          existingBetBuilderLinesCount ? [] : existingMatchBetLines
        )
      : of(createBetLine(match, eventBetType, item, betCategoryType));
  }

  private updateBetSlipBetLine(
    matchId: number,
    allowBetBuilder: boolean,
    existingMatchBetLines: BetLine[],
    isSelected: boolean,
    betLine: BetLine
  ): void {
    const existingBetBuilderBetLinesCount: number = existingMatchBetLines.filter(
      (betLine: BetLine) => betLine.isBetBuilder
    ).length;

    // Switch to simple mode after line removal if only one bet builder line is active
    if (!isSelected && betLine.betBuilderLines?.length === 1) {
      this.betSlipBetBuilderService.changeBetBuilderBetLineToSimple(betLine);
      return;
    }

    // Remove betline on ebti un-selection if no betBuilderBetLine exist for the current match
    if (!isSelected && !existingBetBuilderBetLinesCount) {
      const isPersisted: boolean = this.betSlipService.isPersistedMode;
      this.betSlipService.removeBetLine(betLine, true);

      if (!isPersisted && this.canBeInBetBuilderMode(allowBetBuilder, existingMatchBetLines, [])) {
        this.changeMode(BetSlipMode.Multiple);
      }
      return;
    }

    // Update existing betBuilderBetLine with newly updated ebti
    if (existingBetBuilderBetLinesCount) {
      this.betSlipService.updateBetLine(betLine);
      return;
    }

    if (existingMatchBetLines.length && this.canBeInBetBuilderMode(allowBetBuilder, existingMatchBetLines, [betLine])) {
      this.betSlipBetBuilderService.tryChangeToMultipleMode(matchId);
      existingMatchBetLines.forEach((matchBetLine: BetLine) =>
        this.betSlipService.removeBetLine(matchBetLine, false, true)
      );
      this.betSlipService.addBetLine(betLine);
      return;
    }

    // Add a simple bet line if match has no existing bet lines or if is not switchable to bet builder
    this.betSlipService.addBetLine(betLine);
  }

  private isBetBuilderBetLine(
    match: Match,
    eventBetType: EventBetType,
    eventBetTypeItem: SelectableEventBetTypeItem,
    existingMatchBetLines: BetLine[],
    existingBetBuilderLinesCount: number
  ): boolean {
    return (
      ((existingMatchBetLines.length && eventBetTypeItem.selected) ||
        (existingBetBuilderLinesCount > 1 && !eventBetTypeItem.selected)) &&
      (!eventBetTypeItem.selected ||
        this.canBeInBetBuilderMode(match.allowBetBuilder, existingMatchBetLines, [
          createBetLine(match, eventBetType, eventBetTypeItem, BetCategoryType.SportsFixedOdds)
        ]))
    );
  }

  private canBeInBetBuilderMode(
    allowBetBuilder: boolean,
    existingMatchBetLines: BetLine[],
    newBetLines: BetLine[]
  ): boolean {
    return (
      this.betSlipBetBuilderService.canBeInBetBuilderMode(existingMatchBetLines, allowBetBuilder) &&
      this.betSlipService.canBeInMode(BetSlipMode.Multiple, newBetLines)
    );
  }

  private validateBetSlipModeChanges(existingBetLines: BetLine[], newBetLines: BetLine[]): Observable<boolean> {
    return this.betSlipService.mode == BetSlipMode.Multiple &&
      ((!this.betSlipBetBuilderService.hasBetBuilderBetLines &&
        newBetLines.some(
          (betLine: BetLine) =>
            !betLine.allowBetBuilder &&
            existingBetLines.some(
              (existingBetLine: BetLine) =>
                !existingBetLine.allowBetBuilder && existingBetLine.eventId === betLine.eventId
            )
        )) ||
        !this.betSlipService.canBeInMode(BetSlipMode.Multiple, newBetLines))
      ? this.openSwitchToSimpleMessage()
      : of(true);
  }

  private openSwitchToSimpleMessage(): Observable<boolean> {
    return this.messageService
      .sendComponentMessage(GenericQuestionComponent, {
        text: 'BETSLIP.NOTIFY.TYPE.CHANGE.TEXT',
        yes: 'BETSLIP.NOTIFY.ACCEPT',
        no: 'COMMON.CANCEL'
      })
      .closed.pipe(
        take(1),
        tap((isChangesValidated: boolean) => {
          if (isChangesValidated) {
            this.changeMode(BetSlipMode.Simple);
          }
        })
      );
  }

  private tryClearPlacedBet(item: Pick<BetLine, 'eventBetTypeItemId' | 'oddsBoostId' | 'manualOddsBoostId'>): boolean {
    const hasItemIdPlaced: boolean = this.betSlipService.hasItemIdPlaced(item);
    this.betSlipService.tryClearPlacedBet();
    return hasItemIdPlaced;
  }
}
