import { Component, ChangeDetectionStrategy, OnInit, ChangeDetectorRef, NgZone } from '@angular/core';
import { ApplicationStateService } from '@honoregaming/core';

@Component({
  selector: 'hg-clock',
  templateUrl: './clock.component.html',
  styleUrls: ['./clock.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class ClockComponent implements OnInit {
  clock: Date;
  hours = '--';
  minutes = '--';
  seconds = '--';

  constructor(
    private cdRef: ChangeDetectorRef,
    private applicationStateService: ApplicationStateService,
    private ngZone: NgZone
  ) {}
  ngOnInit(): void {
    this.applicationStateService.isReady$.subscribe(() => {
      this.ngZone.run(() => {
        setInterval(() => {
          this.clock = new Date();
          this.computeTime();
          this.cdRef.markForCheck();
        }, 1000);
      });
    });
  }

  computeTime(): void {
    const hours = this.clock.getHours();
    const minutes = this.clock.getMinutes();
    const seconds = this.clock.getSeconds();

    this.hours = hours < 10 ? `0${hours}` : hours.toString();
    this.minutes = minutes < 10 ? `0${minutes}` : minutes.toString();
    this.seconds = seconds < 10 ? `0${seconds}` : seconds.toString();
  }
}
