import {
  Component,
  ChangeDetectionStrategy,
  Input,
  Output,
  ViewChild,
  ElementRef,
  EventEmitter,
  forwardRef
} from '@angular/core';
import { ControlValueAccessor, NG_VALUE_ACCESSOR } from '@angular/forms';

@Component({
  selector: 'hg-textarea',
  templateUrl: './textarea.component.html',
  styleUrls: ['./textarea.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      multi: true,
      useExisting: forwardRef(() => TextareaComponent)
    }
  ]
})
export class TextareaComponent implements ControlValueAccessor {
  constructor() {}

  @Input() hasError: boolean;
  @Input() value: string;
  @Input() placeholderKey: string;
  @Input() disabled: boolean;

  @Output() submitValue = new EventEmitter();
  @Output() eventFocusTextArea = new EventEmitter();
  internalValue: any;

  @ViewChild('inputField', { static: true })
  public inputField: ElementRef;

  onChange = (_value: Date | [Date, Date]) => {};
  onTouched = () => {};

  writeValue(value: any): void {
    this.internalValue = value;
    this.onChange(this.internalValue);
    this.update();
  }

  registerOnChange(fn: any): void {
    this.onChange = fn;
  }

  registerOnTouched(fn: any): void {
    this.onTouched = fn;
  }

  update() {
    if (!!this.internalValue) {
      var limit = this.inputField?.nativeElement.scrollHeight > 200 ? 250 : 100;
      this.inputField.nativeElement.style.height = '';
      this.inputField.nativeElement.style.height =
        this.inputField.nativeElement.scrollHeight > 50
          ? Math.min(this.inputField.nativeElement.scrollHeight, limit) + 'px'
          : '43px';
      this.inputField.nativeElement.style.paddingBottom =
        this.inputField.nativeElement.scrollHeight > 50 ? '13px' : '5px';
    } else {
      this.inputField.nativeElement.style.height = 'auto';
      this.inputField.nativeElement.style.paddingBottom = '0px';
    }
    this.onChange(this.internalValue);
  }

  public setFocus(): void {
    this.inputField?.nativeElement?.focus();
  }

  enterSubmit(event: any) {
    if (event.keyCode == 13 && !event.shiftKey) {
      if (!!this.internalValue) {
        this.submitValue.emit(this.internalValue);
      }
      return false;
    }
  }

  focused(value: boolean) {
    this.eventFocusTextArea.emit(value);
  }
}
