import {
  Component,
  ChangeDetectionStrategy,
  Input,
  ContentChild,
  TemplateRef,
  OnInit,
  HostListener,
  ElementRef,
  ViewChild,
  Renderer2,
  OnDestroy,
  Output,
  EventEmitter
} from '@angular/core';
import { NG_VALUE_ACCESSOR, ControlValueAccessor } from '@angular/forms';
@Component({
  selector: 'hg-select',
  templateUrl: './select.component.html',
  styleUrls: ['./select.component.scss'],
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: SelectComponent,
      multi: true
    }
  ],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class SelectComponent implements ControlValueAccessor, OnInit, OnDestroy {
  private changed = new Array<(v: any) => void>();
  private touched = new Array<(v: any) => void>();
  opened = false;
  selected: any;
  @Input()
  options: any[];
  @Input()
  nullable = false;
  @Input()
  appendToBody: boolean;
  dropdownPositon: 'above' | 'below' = 'below';
  @Input() placeholder: any;
  @Input() placeholderText: string;
  @Output() public openWindow = new EventEmitter<boolean>();
  @Input() scrollable: boolean = false;
  @ContentChild('selectTemplate') selectTemplate: TemplateRef<any>;
  @HostListener('document:click', ['$event'])
  handleClick(event: MouseEvent) {
    if (!this.elementRef.nativeElement.contains(event.target)) {
      this.opened = false;
      this.openWindow.emit(this.opened);
    }
  }
  constructor(private elementRef: ElementRef, private renderer: Renderer2) {}
  @ViewChild('dropdown') dropdown: ElementRef;
  @ViewChild('select') select: ElementRef;
  ngOnInit() {
    if (this.options && this.options.length && !this.placeholderText && !this.nullable) {
      this.selected = this.options[0];
    }
  }
  registerOnChange(fn: any): void {
    this.changed.push(fn);
  }
  registerOnTouched(fn: any): void {
    this.touched.push(fn);
  }
  writeValue(value: any): void {
    this.changed.forEach(x => x(value));
    this.touched.forEach(x => x(value));
    this.opened = false;
    this.openWindow.emit(this.opened);

    if (
      (value !== null && value !== undefined && this.options.find(x => x === value)) ||
      (this.nullable && value === null)
    ) {
      this.selected = value;
    } else if (this.placeholder) {
      this.selected = this.placeholder;
    }
  }
  toggle() {
    this.opened = !this.opened;
    this.openWindow.emit(this.opened);
    if (!this.appendToBody) {
      return;
    }
    this.renderer.appendChild(document.body, this.dropdown.nativeElement);
    const dropdownPosition = this.getDropdownPosition();
    if (!this.opened) {
      setTimeout(_ => {
        this.renderer.removeChild(document.body, this.dropdown.nativeElement);
      }, 250);
    } else {
      if (this.dropdownPositon === 'above') {
        this.renderer.setStyle(this.dropdown.nativeElement, 'transform', 'translate(-100%, -100%)');
      } else {
        this.renderer.setStyle(this.dropdown.nativeElement, 'transform', 'translateX(-100%)');
      }
      this.renderer.setStyle(this.dropdown.nativeElement, 'top', `${dropdownPosition.top}px`);
      this.renderer.setStyle(this.dropdown.nativeElement, 'left', `${dropdownPosition.right}px`);
    }
  }
  getDropdownPosition() {
    let result: { top: number; right: number } = { right: null, top: null };
    const box = this.select.nativeElement.getBoundingClientRect();
    const scrollLeft = window.pageXOffset || document.documentElement.scrollLeft;
    const scrollTop = window.pageYOffset || document.documentElement.scrollTop;
    if (window.innerHeight - box.bottom <= 320) {
      result.top = box.top + scrollTop - 10;
      this.dropdownPositon = 'above';
    } else {
      result.top = box.top + scrollTop + 40;
      this.dropdownPositon = 'below';
    }
    result.right = box.right - scrollLeft;
    return result;
  }
  ngOnDestroy() {
    if (this.dropdown.nativeElement) {
      this.renderer.removeChild(document.body, this.dropdown.nativeElement);
    }
  }
}
