import { ChangeDetectionStrategy, Component, Input } from '@angular/core';
import { BetState, SportsPoolBet } from '@honoregaming/types';
import { add } from '@honoregaming/core';

@Component({
  selector: 'hg-sports-pool-bet-result',
  templateUrl: './sports-pool-bet-result.component.html',
  styleUrls: ['./sports-pool-bet-result.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class SportsPoolBetResultComponent {
  @Input() bet: SportsPoolBet;

  BetState = BetState;
  add = add;

  private readonly BASE_KEY_LABEL_BUTTON = 'ACCOUNT.BETS.SPORTS_POOL';

  get labelButton(): string {
    if (this.bet.hasOnGoingGame) {
      return `${this.BASE_KEY_LABEL_BUTTON}.FOLLOW_MY_GRID_LIVE`;
    }

    if (this.bet.betState === BetState.Pending) {
      return `${this.BASE_KEY_LABEL_BUTTON}.FOLLOW_MY_GRID`;
    }

    return `${this.BASE_KEY_LABEL_BUTTON}.DISPLAY_GRID`;
  }
}
