import { Component, ChangeDetectionStrategy, Input, Output, EventEmitter } from '@angular/core';
import { take } from 'rxjs/operators';
import { I18nService } from '@honoregaming/i18n';
import { BetLineStateType, BetSystemHistory } from '@honoregaming/types';
import { ToasterService } from '@honoregaming/ui';
import { BetHistoryService } from '@honoregaming/core';

@Component({
  selector: 'hg-match-bet-system-header',
  templateUrl: './match-header.component.html',
  styleUrls: ['./match-header.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class MatchBetSystemHeaderComponent {
  @Input() betSystem!: BetSystemHistory;
  @Input() isOddsBoost: boolean = false;
  @Input() isManualOddsBoost: boolean = false;
  @Input() betBuilderModeLabel: string = '';
  @Input() betLinesVisible: boolean = true;

  @Output() toggleBetLines = new EventEmitter<void>();

  constructor(
    private readonly toasterService: ToasterService,
    private readonly i18n: I18nService,
    private readonly betHistoryService: BetHistoryService
  ) {}

  get betLineStateCounts(): { state: BetLineStateType; count: number }[] {
    return this.betHistoryService.getBetLineStateCounts(this.betSystem);
  }

  contentCopied(): void {
    this.i18n
      .translate('ACCOUNT.COPIED.REFERENCE')
      .pipe(take(1))
      .subscribe(translation => this.toasterService.show(translation));
  }
}
