import { Component, ChangeDetectionStrategy, Input, OnChanges, Output, EventEmitter, Inject } from '@angular/core';
import { BetLine, BetLineAmount } from '../../../models';
import { BetTypeConfiguration, horseRaceBetTypesConfiguration } from '@honoregaming/core';
import { OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';
import { HorseRaceRunner, HorseRacingFlexi } from '@honoregaming/types';
import { getMultipleForHorseRacing } from '../../../utils';
import { BetSlipService } from '../../../services';

@Component({
  selector: 'hg-horseracing-bet-line',
  templateUrl: './horseracing-bet-line.component.html',
  styleUrls: ['./horseracing-bet-line.component.scss', '../bet-line-content.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class HorseRacingBetLineComponent implements OnChanges {
  @Input()
  betLine: BetLine;

  @Input()
  amount: BetLineAmount;

  @Output()
  betLineChange = new EventEmitter<BetLine>();

  @Output()
  amountChange = new EventEmitter<number>();

  @Output()
  remove = new EventEmitter<void>();

  betTypeConfiguration: BetTypeConfiguration;
  Math = Math;
  remplacementHorses: HorseRaceRunner[];
  totalMultiplier = 1;
  minimalAmount: number;
  maximalAmount: number;
  stakeMode: 'multiplier' | 'customStake' = this.getDefaultStakeMode();
  customStakeActive: boolean = this.operatorConfiguration.horseRacingConfiguration?.customStakeActive ?? true;

  previousBetLineMultipliers: number[];

  constructor(
    public betSlipService: BetSlipService,
    @Inject(operatorConfigurationToken) private operatorConfiguration: OperatorConfiguration
  ) {}

  ngOnChanges() {
    if (this.betLine) {
      this.stakeMode = this.getDefaultStakeMode();
      const currentBetLineMultipliers = this.betLine.multipliers.map(m => m.value);

      this.betTypeConfiguration = horseRaceBetTypesConfiguration[this.betLine.betTypeId];
      this.remplacementHorses = this.betLine.runners?.filter(
        r =>
          !r.nonRunner &&
          this.betLine.baseList.indexOf(`${r.number}`) === -1 &&
          (this.betLine.associatedList == null || this.betLine.associatedList.indexOf(`${r.number}`) === -1)
      );

      if (
        !!this.betLine.replacementHorse &&
        !this.remplacementHorses.filter(horse => horse.number == this.betLine.replacementHorse)?.length
      ) {
        this.setRemplacementHorse(null);
      }

      this.totalMultiplier =
        getMultipleForHorseRacing(
          this.betLine.selectionLength,
          this.betLine.runners.filter(r => !r.nonRunner).length,
          this.betLine.baseList.filter(x => x !== 'X').length,
          this.betLine.associatedList?.length || 0,
          this.betLine.formula.key,
          horseRaceBetTypesConfiguration[this.betLine.betTypeId].isOrdered,
          this.betLine.allOrders
        ) || 1;
      const hasFlexi = this.stakeMode === 'multiplier' && this.betLine.flexi !== HorseRacingFlexi.None;
      this.minimalAmount = !hasFlexi
        ? this.betLine.baseAmount
        : (Math.ceil(this.betLine.baseAmount / this.betLine.minimumAmountIncrement / this.totalMultiplier) || 1) *
          this.betLine.minimumAmountIncrement;

      this.maximalAmount = !this.betLine.maximumAmount
        ? null
        : this.betLine.baseAmount >= this.betLine.maximumAmount / this.totalMultiplier
        ? this.betLine.baseAmount
        : this.betLine.maximumAmount / this.totalMultiplier;
      if (
        this.betLine.baseStake < this.minimalAmount ||
        (this.stakeMode === 'customStake' && this.maximalAmount && this.betLine.baseAmount >= this.maximalAmount)
      ) {
        this.betLine.baseStake = this.minimalAmount;
        this.amountChange.emit(this.minimalAmount * this.totalMultiplier);
      }

      if (
        !this.multipliersValuesAreSame(this.previousBetLineMultipliers, currentBetLineMultipliers) &&
        this.stakeMode === 'multiplier'
      ) {
        this.setMultiplier(this.getSuggestedMultiplier());
      }

      this.previousBetLineMultipliers = currentBetLineMultipliers;
    } else {
      this.betTypeConfiguration = null;
      this.remplacementHorses = null;
    }
  }

  multipliersValuesAreSame(previousBetLineMultipliers: number[], currentBetLineMultipliers: number[]): boolean {
    let multipliersValuesAreSame = true;
    for (const propertyName in previousBetLineMultipliers) {
      if (previousBetLineMultipliers[propertyName] !== currentBetLineMultipliers[propertyName]) {
        multipliersValuesAreSame = false;
        break;
      }
    }

    return multipliersValuesAreSame;
  }

  onAmountChange(amount: number) {
    this.amountChange.emit(amount * this.totalMultiplier);
    this.betLineChange.next({
      ...this.betLine,
      multiplier: this.betLine.multiplier
    });
  }

  setRemplacementHorse(replacementHorseNumber: number) {
    this.betLineChange.next({
      ...this.betLine,
      replacementHorse: replacementHorseNumber
    });
  }

  setMultiplier(multiplier: number) {
    this.betLine.baseStake = this.betLine.baseAmount;
    this.betLine.multiplier = multiplier;
    this.betLineChange.next({
      ...this.betLine,
      multiplier: multiplier
    });
  }

  setStakeMode(mode: 'multiplier' | 'customStake') {
    if (this.stakeMode !== mode) {
      this.betLine.baseStake = this.betLine.baseAmount;
      this.amountChange.emit(this.betLine.baseAmount);
      this.betLineChange.next({
        ...this.betLine,
        multiplier: mode === 'multiplier' ? this.getSuggestedMultiplier() : 1
      });
      this.stakeMode = mode;
    }
  }

  private getSuggestedMultiplier(): number {
    const multipleAmount = this.totalMultiplier * this.betLine.baseStake;
    if (this.betLine.maximumAmount <= multipleAmount) {
      return this.betLine.multipliers[0].value;
    }

    return 1;
  }

  onAllOrdersChanged(): void {
    this.amountChange.emit(this.betLine.baseAmount);
    this.betLineChange.next({
      ...this.betLine
    });
  }

  onRemove() {
    this.remove.emit();
  }

  getDefaultStakeMode() {
    if (this.betLine?.baseStake !== this.betLine?.baseAmount) {
      return 'customStake';
    }

    return 'multiplier';
  }
}
