import { Component, ChangeDetectionStrategy, Input, OnChanges, SimpleChanges } from '@angular/core';
import { Router } from '@angular/router';
import { interval, Observable, of } from 'rxjs';
import { take, tap, map, startWith } from 'rxjs/operators';
import { AuthService, TelemetryService } from '@honoregaming/customer-core';
import { Media, MediaService } from '@honoregaming/ui';

@Component({
  selector: 'hg-freebet-coupons-counter',
  templateUrl: './freebet-coupons-counter.component.html',
  styleUrls: ['./freebet-coupons-counter.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class FreebetCouponsCounterComponent implements OnChanges {
  @Input() actualFreeBetCouponsCount: number = 0;
  @Input() newFreeBetCouponsCount: number = 0;
  @Input() useImage: boolean = false;

  freebetCouponsCount$: Observable<number> | undefined;

  constructor(
    private readonly router: Router,
    private readonly authService: AuthService,
    private readonly telemetryService: TelemetryService,
    private readonly mediaService: MediaService
  ) {}

  ngOnChanges(changes: SimpleChanges): void {
    const previousFreeBetCouponsCount: number = this.actualFreeBetCouponsCount - this.newFreeBetCouponsCount;
    if (!changes.newFreeBetCouponsCount?.previousValue) {
      this.freebetCouponsCount$ = of(previousFreeBetCouponsCount);
    } else if (changes.newFreeBetCouponsCount?.previousValue && !changes.newFreeBetCouponsCount?.currentValue) {
      let updatedCount: number = previousFreeBetCouponsCount - changes.newFreeBetCouponsCount.previousValue;
      this.freebetCouponsCount$ = interval(updatedCount > 0 ? 1000 / updatedCount : 100).pipe(
        startWith(() => updatedCount),
        take(changes.newFreeBetCouponsCount.previousValue),
        tap(() => updatedCount++),
        map(() => updatedCount)
      );
    }
  }

  trackEvent(eventName: string): void {
    if (this.authService.isAuthenticated()) {
      this.telemetryService.trackEvent('header_click_loggedon', {
        shortcut_name: eventName,
        shortcut_device: this.mediaService?.media < Media.md ? 'Mobile' : 'Desktop',
        page: this.router.url
      });
    }
  }
}
