import { ComponentRef, Inject, Injectable, Injector, InjectionToken } from '@angular/core';
import { DOCUMENT } from '@angular/common';
import { Overlay, OverlayConfig, OverlayContainer, OverlayRef } from '@angular/cdk/overlay';
import { ComponentPortal } from '@angular/cdk/portal';
import { ITransactionPopupService, TransactionMode } from '@honoregaming/betslip';
import { TransactionPopupComponent } from 'projects/customer/hg-account/src/lib/components/transaction-popup/transaction-popup.component';

export { TransactionMode } from '@honoregaming/betslip';

export interface TransactionPopupData {
  mode: TransactionMode;
}

export const TRANSACTION_POPUP_DATA = new InjectionToken<TransactionPopupData>('TRANSACTION_POPUP_DATA');

@Injectable({ providedIn: 'root' })
export class TransactionPopupService implements ITransactionPopupService {
  private static readonly OVERLAY_CONTAINER_CLASS: string = 'transaction-popup-open';

  private overlayRef: OverlayRef | null = null;
  private componentRef: ComponentRef<TransactionPopupComponent> | null = null;

  constructor(
    private readonly overlay: Overlay,
    private readonly injector: Injector,
    private readonly overlayContainer: OverlayContainer,
    @Inject(DOCUMENT) private readonly document: Document
  ) {}

  open(mode: TransactionMode): void {
    if (this.overlayRef) {
      return;
    }

    const config = new OverlayConfig();

    this.overlayRef = this.overlay.create(config);

    this.overlayRef.backdropClick().subscribe(() => this.componentRef?.instance.close());
    this.overlayRef.keydownEvents().subscribe((e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        this.componentRef?.instance.close();
      }
    });

    const portalInjector: Injector = Injector.create({
      parent: this.injector,
      providers: [{ provide: TRANSACTION_POPUP_DATA, useValue: { mode } as TransactionPopupData }]
    });

    const portal = new ComponentPortal(TransactionPopupComponent, null, portalInjector);
    this.componentRef = this.overlayRef.attach(portal);
    this.overlayContainer.getContainerElement().classList.add(TransactionPopupService.OVERLAY_CONTAINER_CLASS);
    this.fixBody();
  }

  close(): void {
    if (this.overlayRef) {
      this.overlayRef.dispose();
      this.overlayRef = null;
      this.componentRef = null;
      this.overlayContainer.getContainerElement().classList.remove(TransactionPopupService.OVERLAY_CONTAINER_CLASS);
      this.releaseBody();
    }
  }

  private fixBody(): void {
    this.document.documentElement.classList.add('hidden');
  }

  private releaseBody(): void {
    this.document.documentElement.classList.remove('hidden');
  }
}
