import {
  Component,
  OnInit,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  ViewChild,
  Inject,
  ElementRef,
  HostListener,
  OnDestroy,
  Injector
} from '@angular/core';
import {
  AuthService,
  CustomerService,
  CustomerState,
  ICaptchaService,
  captchaServiceToken,
  TelemetryService,
  PasswordService,
  CustomerOperatorConfiguration,
  customerOperatorConfigurationToken
} from '@honoregaming/customer-core';
import { Router, ActivatedRoute } from '@angular/router';
import { skip, takeUntil } from 'rxjs/operators';
import { DateTime } from 'luxon';
import { HttpErrorResponse } from '@angular/common/http';
import { NgForm } from '@angular/forms';
import { SecurityPolicy, ProfileFieldPolicy, PasswordPolicy, ProfilePolicy, CountryCode } from '@honoregaming/types';
import { operatorConfigurationToken, OperatorConfiguration } from '@honoregaming/configuration';
// tslint:disable-next-line: max-line-length
import { merge, Observable, of } from 'rxjs';
import { CookieStorageService, DestroySubject, hasFlag } from '@honoregaming/core';
import { AKEY } from 'projects/customer/customer/src/app/constants/affiliate.constant';
import { AccountService } from '../../../services/account.service';
import { DOCUMENT } from '@angular/common';
import { I18nService } from '@honoregaming/i18n';

@Component({
  selector: 'hg-step1',
  templateUrl: './step1.component.html',
  styleUrls: ['./step1.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class Step1Component extends DestroySubject implements OnInit, OnDestroy {
  @ViewChild('registerForm')
  form: NgForm;
  @ViewChild('inputPassword') inputPassword: HTMLElement;
  @ViewChild('inputDate') inputDate: ElementRef;
  @ViewChild('activeInput') activeInput: ElementRef;
  @ViewChild('birthMonth') birthMonthInput: ElementRef;
  @ViewChild('birthYear') birthYearInput: ElementRef;

  securityPolicy: SecurityPolicy;
  passwordPolicyRequirements: PasswordPolicy | undefined;
  profilePolicyRequirements: ProfilePolicy;
  login: string;
  loginWithoutPrefix: string;
  email: string;
  password: string;
  confirmPassword: string;
  referrerCode: string;
  profile: Map<string, string>;
  profileRequired: boolean;
  profileFields: (ProfileFieldPolicy & { value: string | Date | boolean })[] | undefined;
  step: number;
  referrerCodeNotFound = false;
  profileFieldError = false;
  passwordLengthError = false;
  passwordDigitError = false;
  passwordLowercaseError = false;
  passwordNonLetterOrError = false;
  passwordUppercaseError = false;
  error = false;
  loading = false;
  isAffiliatedVisitor = false;
  referralActive = this.operatorConfiguration.global.referralActive;
  operatorKey = this.operatorConfiguration.key;
  registrationBlocked = this.operatorConfiguration.complianceConfiguration?.registrationBlocked;
  blacklisted = false;
  isConnected: boolean;
  countries: CountryCode[];

  duplicateMailError: boolean = false;
  underageCustomerError: boolean = false;
  showPasswordValue = false;
  showConfirmPasswordValue = false;
  nextStep = false;
  hasLogin = false;
  stepLoginValidation = false;

  stepPasswordValidation: boolean;
  stepInfosValidation: boolean;
  hasDigital: boolean;
  hasNonLetterOrDigit: boolean;
  hasLowerCharacter: boolean;
  hasUppercharacter: boolean;
  hasPasswordLength: boolean;
  hasConsecutiveNumberSequence: boolean;
  hasConsecutiveLetterSequence: boolean;
  hasSameCharacterRepeated: boolean;
  isEqualToLogin: boolean;
  asteriskPassword: string;
  requiredLength: number;
  requireLowercase: boolean;
  requireUppercase: boolean;
  requireEmail: boolean;
  requireDigit: boolean;
  requireNonLetterOrDigit: boolean;
  preventConsecutiveSequence: boolean;
  preventSameCharacterRepeated: boolean;
  preventEqualToLogin: boolean;

  allowedKeys = ['Delete', 'Backspace', 'ArrowDown', 'ArrowLeft', 'ArrowUp', 'ArrowRight', 'Tab'];

  recaptchaLegend: string;

  birthdate: { day: string; month: string; year: string } = {
    day: undefined,
    month: undefined,
    year: undefined
  };
  minimumAgeRequired: number;
  asteriskConfirmPassword: string;

  // Compliance Fields
  displayComplianceSeparator: boolean;
  private document: Document;

  @HostListener('document:click', ['$event'])
  focusOnLoginField(event: any) {
    this.activeInput?.nativeElement?.contains(event.target) ? (this.hasLogin = true) : (this.hasLogin = false);
  }

  @HostListener('document:keydown', ['$event'])
  keyEvent(e: KeyboardEvent) {
    if (this.inputDate?.nativeElement?.contains(e.target)) {
      if (e.key === '.' || e.key === '+' || e.code === 'KeyE' || e.key === '-') {
        e.preventDefault();
      }
    }
  }

  extraInfos$: Observable<string | null> | null = of(null);
  extraInfosLink$: Observable<string | null> | null = of(null);

  constructor(
    private authService: AuthService,
    private customerService: CustomerService,
    private route: ActivatedRoute,
    private router: Router,
    private storageService: CookieStorageService,
    private cdRef: ChangeDetectorRef,
    private accountService: AccountService,
    @Inject(operatorConfigurationToken) private operatorConfiguration: OperatorConfiguration,
    @Inject(customerOperatorConfigurationToken) private customerOperatorConfiguration: CustomerOperatorConfiguration,
    private telemetryService: TelemetryService,
    @Inject(captchaServiceToken) private captchaService: ICaptchaService,
    injector: Injector,
    private i18nService: I18nService,
    private readonly passwordService: PasswordService
  ) {
    super();
    this.document = injector.get(DOCUMENT);
  }

  ngOnInit() {
    this.authService.me$.pipe(takeUntil(this.destroy$)).subscribe(x => {
      this.isConnected = !!x;
      if (
        this.isConnected &&
        hasFlag(x.state, CustomerState.LoginValidated) &&
        !this.customerOperatorConfiguration.knowYourCustomerConfiguration?.customerAccessLimitationConfiguration
          ?.blockDeposit
      ) {
        this.router.navigate(['myaccount', 'deposit']);
      } else if (
        this.isConnected &&
        hasFlag(x.state, CustomerState.LoginValidated) &&
        this.customerOperatorConfiguration.knowYourCustomerConfiguration?.customerAccessLimitationConfiguration
          ?.blockDeposit
      ) {
        this.router.navigate(['myaccount', 'informations']);
      }
      this.cdRef.markForCheck();
    });

    this.authService.me$.pipe(takeUntil(this.destroy$)).subscribe(me => {
      if (me?.state == CustomerState.Blacklisted) {
        this.blacklisted = true;
      }

      this.minimumAgeRequired =
        this.customerOperatorConfiguration.knowYourCustomerConfiguration?.customerAccessLimitationConfiguration.minimumAgeRequired;

      this.customerService.getSecurityPolicy().subscribe(x => {
        this.securityPolicy = x;
        this.captchaService.loadCaptcha(this.securityPolicy);
        this.captchaService.applyCaptcha('#Register_Validate1').subscribe();

        this.profileRequired = x?.profilePolicyRequirements?.required;
        this.profileFields = x?.profilePolicyRequirements?.fields?.map(field => ({ ...field, value: '' }));
        this.passwordPolicyRequirements = this.securityPolicy.passwordPolicyRequirements;
        this.profilePolicyRequirements = this.securityPolicy.profilePolicyRequirements;
        this.requireLowercase = this.passwordPolicyRequirements?.requireLowercase;
        this.requireUppercase = this.passwordPolicyRequirements?.requireUppercase;
        this.requireDigit = this.passwordPolicyRequirements?.requireDigit;
        this.requiredLength = this.passwordPolicyRequirements?.requiredLength;
        this.requireNonLetterOrDigit = this.passwordPolicyRequirements?.requireNonLetterOrDigit;
        this.preventConsecutiveSequence = this.passwordPolicyRequirements?.preventConsecutiveSequence;
        this.preventSameCharacterRepeated = this.passwordPolicyRequirements?.preventSameCharacterRepeated;
        this.preventEqualToLogin = this.passwordPolicyRequirements?.preventEqualToLogin;
        this.requireEmail = this.profilePolicyRequirements?.fields?.filter(x => x.name === 'email')?.[0]?.required;

        this.isAffiliatedVisitor = !!this.storageService.getItem(AKEY);

        // || any other compliance fields to display at the bottom of the form
        this.displayComplianceSeparator = !!this.profileFields?.find(e => e.name === 'politicallyExposedPerson');

        this.handleRequiredBooleanProfileFields();

        if (this.profileFields?.find(e => e.type === 'country-list')) {
          this.customerService
            .getCountryCodes()
            .pipe(takeUntil(this.destroy$))
            .subscribe(countries => {
              this.countries = countries;
            });
        }

        this.cdRef.markForCheck();
      });

      this.route.queryParams.pipe(takeUntil(this.destroy$)).subscribe(params => {
        this.referrerCode = params.code;
        this.cdRef.markForCheck();
      });
    });

    this.accountService.registerStep.pipe(takeUntil(this.destroy$)).subscribe(x => {
      this.step = x;
      this.cdRef.markForCheck();
    });

    this.i18nService.languageChanged$.pipe(takeUntil(this.destroy$)).subscribe(() => this.updateExtraInfo());
  }

  ngOnDestroy(): void {
    super.ngOnDestroy();

    this.captchaService.clearCaptcha();
  }

  submitRegistration() {
    if (this.loading) {
      return;
    }

    this.loading = true;
    this.referrerCodeNotFound = false;
    this.profileFieldError = false;
    this.duplicateMailError = false;
    this.underageCustomerError = false;
    this.error = false;

    this.profile = new Map();
    this.profileFields?.map(field => {
      if (field.name === 'birthdate') {
        var newDate = new Date(this.birthdate.month + '/' + this.birthdate.day + '/' + this.birthdate.year);
        var luxonDate = DateTime.utc(newDate.getFullYear(), newDate.getMonth() + 1, newDate.getDate());
        field.value = luxonDate.toJSDate();
      }

      this.profile = { ...this.profile, [field.name]: field.value };
    });

    if (this.minimumAgeRequired && this.customerIsUnderage()) {
      this.underageCustomerError = true;
      this.loading = false;
      return;
    }

    this.captchaService
      .validateCaptcha()
      .pipe(takeUntil(this.destroy$))
      .subscribe(token => this.register(token));
  }

  previous() {
    this.stepLoginValidation = false;
    this.nextStep = false;
    this.accountService.clickRegisterStep(0);
  }

  checkInfosAvailibility() {
    this.referrerCodeNotFound = false;
    this.duplicateMailError = false;

    if (this.operatorConfiguration.complianceConfiguration?.registrationBlocked) {
      return;
    }

    if (!this.profilePolicyRequirements) {
      this.customerService
        .checkLoginAvailibity(this.login, this.password, this.referrerCode, this.email)
        .pipe(takeUntil(this.destroy$))
        .subscribe(
          () => {
            this.recaptchaLegend = this.captchaService.getLegend();
            this.cdRef.markForCheck();
            this.submitRegistration();
          },
          (err: HttpErrorResponse) => {
            this.loading = false;

            if (err.error.code === CreateCustomerFailure.LoginAlreadyExists) {
              this.form.controls.login.setErrors({ loginPolicy: 'ALREADYEXISTS' });
            } else if (err.error.code === CreateCustomerFailure.PasswordRequiredLength) {
              this.passwordLengthError = true;
            } else if (err.error.code === CreateCustomerFailure.DuplicateEmail) {
              this.duplicateMailError = true;
            } else if (err.error.code === CreateCustomerFailure.ReferrerCodeNotFound) {
              this.referrerCodeNotFound = true;
            } else if (err.error.code === CreateCustomerFailure.PasswordRequireDigit) {
              this.passwordDigitError = true;
            } else if (err.error.code === CreateCustomerFailure.PasswordRequireLowercase) {
              this.passwordLowercaseError = true;
            } else if (err.error.code === CreateCustomerFailure.PasswordRequireNonLetterOrDigit) {
              this.passwordNonLetterOrError = true;
            } else if (err.error.code === CreateCustomerFailure.PasswordRequireUppercase) {
              this.passwordUppercaseError = true;
            } else if (err.error.code === CreateCustomerFailure.RegistrationBlocked) {
              this.registrationBlocked = true;
            } else {
              this.error = true;
            }

            this.stepPasswordValidation = false;
            this.stepInfosValidation = false;
          }
        );
      this.cdRef.markForCheck();
    } else {
      this.customerService
        .checkLoginAvailibity(this.login, this.password, this.referrerCode, this.email)
        .pipe(takeUntil(this.destroy$))
        .subscribe(
          () => {
            this.stepLoginValidation = true;
            this.accountService.clickRegisterStep(1);

            if (this.nextStep === true) {
              this.submitRegistration();
            } else {
              this.recaptchaLegend = this.captchaService.getLegend();
            }
          },
          (err: HttpErrorResponse) => {
            this.loading = false;

            if (err.error.code === CreateCustomerFailure.LoginAlreadyExists) {
              this.form.controls.login.setErrors({ loginPolicy: 'ALREADYEXISTS' });
            } else if (err.error.code === CreateCustomerFailure.PasswordRequiredLength) {
              this.passwordLengthError = true;
            } else if (err.error.code === CreateCustomerFailure.DuplicateEmail) {
              this.duplicateMailError = true;
            } else if (err.error.code === CreateCustomerFailure.ReferrerCodeNotFound) {
              this.referrerCodeNotFound = true;
            } else if (err.error.code === CreateCustomerFailure.PasswordRequireDigit) {
              this.passwordDigitError = true;
            } else if (err.error.code === CreateCustomerFailure.PasswordRequireLowercase) {
              this.passwordLowercaseError = true;
            } else if (err.error.code === CreateCustomerFailure.PasswordRequireNonLetterOrDigit) {
              this.passwordNonLetterOrError = true;
            } else if (err.error.code === CreateCustomerFailure.PasswordRequireUppercase) {
              this.passwordUppercaseError = true;
            } else if (err.error.code === CreateCustomerFailure.RegistrationBlocked) {
              this.registrationBlocked = true;
            } else {
              this.error = true;
            }

            this.stepPasswordValidation = false;
            this.stepInfosValidation = false;

            this.captchaService.applyCaptcha('#Register_Validate1').subscribe();
            this.cdRef.markForCheck();
          }
        );
    }
    this.cdRef.markForCheck();
  }

  private register(recaptchaToken: string = null) {
    this.error = false;
    this.referrerCodeNotFound = false;
    this.duplicateMailError = false;

    this.telemetryService.trackEvent('sign_up_started');

    this.customerService
      .signup(this.login, this.password, this.referrerCode, this.profile, recaptchaToken)
      .pipe(takeUntil(merge(this.route.queryParams.pipe(skip(1)), this.destroy$)))
      .subscribe(
        customer => {
          if (!this.profilePolicyRequirements) {
            this.stepLoginValidation = false;
          }

          if (customer.state == 'Blacklisted') {
            this.blacklisted = true;
            this.cdRef.markForCheck();
          } else {
            this.authService
              .login(this.login, this.password, false)
              .pipe(takeUntil(merge(this.route.queryParams.pipe(skip(1)), this.destroy$)))
              .subscribe(_ => {
                this.authService
                  .getMe()
                  .pipe(takeUntil(merge(this.route.queryParams.pipe(skip(1)), this.destroy$)))
                  .subscribe(() => {
                    this.router.navigate(['myaccount', 'registration', 'step2']);
                    this.accountService.clickRegisterStep(2);
                  });
              });
          }
        },
        (err: HttpErrorResponse) => {
          this.loading = false;

          if (err.error) {
            if (err.error.code === CreateCustomerFailure.LoginAlreadyExists) {
              this.form.controls.login.setErrors({ loginPolicy: 'ALREADYEXISTS' });
            } else if (err.error.code === CreateCustomerFailure.ReferrerCodeNotFound) {
              this.referrerCodeNotFound = true;
            } else if (err.error.code === CreateCustomerFailure.ProfileFieldError) {
              this.profileFieldError = true;
            } else if (err.error.code === CreateCustomerFailure.DuplicateEmail) {
              this.duplicateMailError = true;
            } else if (err.error.code === CreateCustomerFailure.UnderageCustomer) {
              this.underageCustomerError = true;
            } else {
              this.error = true;
            }
          } else {
            this.error = true;
          }

          this.cdRef.markForCheck();
        }
      );
  }

  private customerIsUnderage() {
    const customerBirthdate = new Date(this.birthdate.month + '/' + this.birthdate.day + '/' + this.birthdate.year);
    const today = new Date();

    const differenceInMilliseconds = today.valueOf() - customerBirthdate.valueOf();
    const millisecondsInYear = 1000 * 60 * 60 * 24 * 365.25;
    const differenceInYears = Math.floor(differenceInMilliseconds / millisecondsInYear);

    if (differenceInYears < this.minimumAgeRequired) {
      return true;
    }

    return false;
  }

  changeText(email: string) {
    this.duplicateMailError = false;
    this.email = email;
  }

  handleRequiredBooleanProfileFields() {
    if (this.profileFields) {
      this.profileFields = [
        ...this.profileFields?.map(field => {
          if (field.type === 'bool' && field.required) {
            field.value = false;
          }

          return field;
        })
      ];
    }
  }

  onChange(password: string) {
    const result = this.passwordService.checkPassword(password, this.loginWithoutPrefix);

    this.hasConsecutiveLetterSequence = result.hasConsecutiveLetterSequence;
    this.hasDigital = result.hasDigital;
    this.hasLowerCharacter = result.hasLowerCharacter;
    this.hasUppercharacter = result.hasUppercharacter;
    this.hasConsecutiveNumberSequence = result.hasConsecutiveNumberSequence;
    this.hasSameCharacterRepeated = result.hasSameCharacterRepeated;
    this.isEqualToLogin = result.isEqualToLogin;
    this.hasPasswordLength = result.hasPasswordLength;
    this.hasNonLetterOrDigit = result.hasNonLetterOrDigit;

    this.error = null;
    this.cdRef.markForCheck();
  }

  onNationalityChange(countryCode: string) {
    const profileField = this.profileFields?.find(e => e.name === 'nationality');
    if (profileField) {
      profileField.value = countryCode;
    }
  }

  getTabIndex(fieldName: string, index: number) {
    const element = this.document.getElementsByClassName(fieldName)[0];
    const order = element ? getComputedStyle(element)?.order : index + 1;

    return order ?? index + 1;
  }

  checkBirthDateInput(event: KeyboardEvent, maxLength: number) {
    if (this.allowedKeys.indexOf(event.key) !== -1 || (event.key === 'a' && event.ctrlKey)) {
      return true;
    }

    const input = event.target as EventTarget & { value: string; selectionStart: number; selectionEnd: number };
    const target = input.value + event.key;

    if (
      (target.length > maxLength && input.selectionEnd === input.selectionStart) ||
      event.key > '9' ||
      event.key < '0' ||
      event.ctrlKey
    ) {
      event.stopPropagation();
      event.preventDefault();
      return false;
    }
  }

  changeFocusIfNeeded(value: string, maxLength: number, nextInput: ElementRef) {
    if (value.length === maxLength && nextInput) {
      nextInput.nativeElement.focus();
    }
  }

  changeLoginWithoutPrefix(value: string) {
    this.loginWithoutPrefix = value;
  }

  updateExtraInfo(): void {
    this.extraInfos$ = this.i18nService.translationKeyExistsSync('REGISTRATION.EXTRA_INFOS')
      ? this.i18nService.translate('REGISTRATION.EXTRA_INFOS')
      : undefined;

    this.extraInfosLink$ = this.i18nService.translationKeyExistsSync('REGISTRATION.EXTRA_INFOS.LINK')
      ? this.i18nService.translate('REGISTRATION.EXTRA_INFOS.LINK')
      : undefined;
  }
}

enum CreateCustomerFailure {
  PasswordRequiredLength = 1,
  PasswordRequireDigit,
  PasswordRequireLowercase,
  PasswordRequireNonLetterOrDigit,
  PasswordRequireUppercase,
  LoginPatternMismatch,
  ResourceValidationMessageNotFound,
  LoginAlreadyExists,
  SenderError,
  ReferrerCodeNotFound,
  ProfileFieldError,
  InvalidRecaptcha,
  ReferralNotActive,
  ReferrerCodeGenerationFailed,
  DuplicateEmail,
  LimitReached,
  UnderageCustomer,
  Spammer,
  RefGenerationFailed,
  PasswordPreventSameCharacterRepeated,
  PasswordPreventConsecutiveSequence,
  PasswordPreventSameAsLogin,
  RegistrationBlocked
}
