import { IdentityDocument } from 'projects/customer/hg-account/src/lib/models/identity-document.model';
import { IncomeSourceType } from '../../../../../core/hg-types/models/enums/income-source-type.enum';
import { GenderType } from '../../../../../core/hg-types/models/enums/gender-type.enum';

export class CustomerProfile {
  firstName: string;
  lastName: string;
  email: string;
  middleName: string;
  incomeSource?: IncomeSourceType;
  birthdate?: string;
  nationality?: string;
  city: string;
  country: string;
  gender?: GenderType;
  region: string;
  message: string;
  reason: string;
  street: string;
  zipCode: string;
  phoneNumber: string;
  profileStatus: CustomerStatus;
  documents: IdentityDocument[];
  registrationDate?: Date;
  politicallyExposedPerson?: boolean;
}

export enum CustomerStatus {
  ToBeVerified = 'ToBeVerified',
  WaitingForCustomer = 'WaitingForCustomer',
  Rejected = 'Rejected',
  Verified = 'Verified'
}
