import { CustomerOperatorConfiguration } from '@honoregaming/customer-core';
import { BetradarFeatureType } from '@honoregaming/configuration';
import { hasFlag } from '@honoregaming/core';

export function operatorHasResult(operatorConfiguration: CustomerOperatorConfiguration): boolean {
  return (
    hasFlag(operatorConfiguration.features.betradarFeatures, BetradarFeatureType.LiveScore) &&
    !!operatorConfiguration?.headerCustomization?.liveScoreUrl
  );
}
