import { Component, ChangeDetectionStrategy, Output, EventEmitter, Input } from '@angular/core';
import { CustomerDirectMessageConfiguration } from '@honoregaming/customer-core';
import { DirectMessageTrackingService } from '../../services/direct-message-tracking.service';

@Component({
  selector: 'hg-direct-message-window',
  templateUrl: './direct-message-window.component.html',
  styleUrls: ['./direct-message-window.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class DirectMessageWindowComponent {
  @Input() configuration!: CustomerDirectMessageConfiguration;

  @Output() reduceEvent = new EventEmitter<void>();
  @Output() closeEvent = new EventEmitter<void>();

  constructor(private readonly directMessageTrackingService: DirectMessageTrackingService) {}

  reduce(): void {
    this.reduceEvent.emit();
  }

  close(): void {
    this.closeEvent.emit();
    this.directMessageTrackingService.trackClose('window');
  }
}
