import { Component, ChangeDetectionStrategy, EventEmitter, Output, ChangeDetectorRef } from '@angular/core';
import { BettingApiService, CashoutError, CashoutBetFailures } from '@honoregaming/betslip';
import { DestroySubject } from '@honoregaming/core';
import { finalize } from 'rxjs/operators';
import { takeUntil } from 'rxjs/operators';

@Component({
  selector: 'hg-cashout-demand',
  templateUrl: './cashout-demand.component.html',
  styleUrls: ['./cashout-demand.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class CashoutDemandComponent extends DestroySubject {
  @Output()
  public close = new EventEmitter<boolean>();

  public betSystemId: number;
  public amount: number;

  public acceptAmountChanges: boolean;
  public loading: boolean;
  public hasError: boolean;
  public cashoutFailure: string;
  public success = false;

  constructor(private bettingApiService: BettingApiService, private cdRef: ChangeDetectorRef) {
    super();
  }

  cashout(): void {
    this.loading = true;
    this.success = false;
    this.hasError = false;
    this.cashoutFailure = null;

    this.bettingApiService
      .applyCashout({
        betSystemId: this.betSystemId,
        amount: this.amount,
        acceptAmountChanges: this.acceptAmountChanges
      })
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.loading = false;
          this.cdRef.markForCheck();
        })
      )
      .subscribe(
        () => {
          this.success = true;
        },
        (err: CashoutError) => {
          if (err.failure != null && err.failure > -1) {
            if (err.failure === CashoutBetFailures.BetSystemNotFound) {
              this.cashoutFailure = 'BET_SYSTEM_NOT_FOUND';
            } else if (err.failure === CashoutBetFailures.NotAllowed) {
              this.cashoutFailure = 'NOT_ALLOWED';
            } else if (err.failure === CashoutBetFailures.AmountChanged) {
              this.amount = err.data.amount;
              this.cashoutFailure = 'AMOUNT_CHANGED';
            } else if (err.failure === CashoutBetFailures.NoLongerAvailable) {
              this.cashoutFailure = 'NO_LONGER_AVAILABLE';
            }
          } else {
            this.cashoutFailure = 'GENERIC';
          }

          this.hasError = true;
        }
      );
  }
}
