export interface RouletteItem {
  number: number;
  color: RouletteItemColor;
  type: RouletteItemType;
  colorGroup?: RouletteItemColorGroupInsa;
}

export enum RouletteItemColor {
  Green = 'Green',
  Red = 'Red',
  Black = 'Black'
}

export enum RouletteItemColorInsa {
  Green,
  Red,
  Black
}

export enum RouletteItemColorGroupInsa {
  Blue,
  Pink,
  Yellow,
  None,
  Orange
}

export enum RouletteItemType {
  None = 'None',
  Odd = 'Odd',
  Even = 'Even'
}
