import { Injectable } from '@angular/core';
import {
  BetBuilderError,
  BetBuilderErrorInfo,
  betBuilderErrorsByPriority,
  BetBuilderEventItemIds,
  BetBuilderLine,
  BetBuilderOdds,
  BetCategoryType,
  BetLineHistory,
  BetLineStateType,
  BetSystemHistory,
  EventBetType,
  EventBetTypeItem,
  EventType,
  Match,
  SelectedItem
} from '@honoregaming/types';
import { BetLine, SportsFixedOddsRebetBetLine } from '@honoregaming/betslip';

@Injectable({
  providedIn: 'root'
})
export class BetLinesMapperService {
  constructor() {}

  hasItemIdPlaced(
    betLines: BetLine[],
    item: Pick<BetLine, 'eventBetTypeItemId' | 'oddsBoostId' | 'manualOddsBoostId'>
  ): boolean {
    return betLines.some(
      (betLine: BetLine) =>
        (item.eventBetTypeItemId &&
          (betLine.eventBetTypeItemId === item.eventBetTypeItemId ||
            betLine.betBuilderLines?.some(
              (betBuilderLine: BetBuilderLine) => betBuilderLine.eventBetTypeItemId === item.eventBetTypeItemId
            ))) ||
        (item.oddsBoostId && betLine.oddsBoostId === item.oddsBoostId) ||
        (item.manualOddsBoostId && betLine.manualOddsBoostId === item.manualOddsBoostId)
    );
  }

  findBetLineHistory(betSystemHistory: BetSystemHistory, eventBetTypeItemId: number): BetLineHistory | undefined {
    return betSystemHistory.betLines.find(
      (betLineHistory: BetLineHistory) =>
        betLineHistory.eventBetTypeItemId === eventBetTypeItemId ||
        betLineHistory.betBuilderLines?.find(
          (betBuilderLine: BetBuilderLine) => betBuilderLine.eventBetTypeItemId === eventBetTypeItemId
        )
    );
  }

  betLinesToEventBetTypeIds(betLines: BetLine[]): number[] {
    return this.betLinesToSelectedItems(betLines).map((selectedItem: SelectedItem) => selectedItem.betTypeId);
  }

  betLinesToEventBetTypeItemIds(betLines: BetLine[]): number[] {
    return this.betLinesToSelectedItems(betLines).map((selectedItem: SelectedItem) => selectedItem.eventBetTypeItemId);
  }

  betLinesHistoryToEventBetTypeItemIds(betLinesHistory: BetLineHistory[]): number[] {
    return betLinesHistory
      .reduce((items: SelectedItem[], betLineHistory: BetLineHistory) => {
        if (betLineHistory.oddsBoostId || betLineHistory.manualOddsBoostId) {
          return items;
        }
        if (betLineHistory.betBuilderLines?.length) {
          items.push(...this.betBuilderLinesToSelectedItems(betLineHistory.eventId, betLineHistory.betBuilderLines));
        } else {
          items.push({
            eventId: betLineHistory.eventId,
            betTypeId: betLineHistory.betTypeId,
            eventBetTypeItemId: betLineHistory.eventBetTypeItemId,
            isBetCompletion: betLineHistory.isBetCompletion
          });
        }
        return items;
      }, [])
      .map((selectedItem: SelectedItem) => selectedItem.eventBetTypeItemId);
  }

  betLinesToSelectedItems(betLines: BetLine[]): SelectedItem[] {
    return betLines.reduce((items: SelectedItem[], betLine: BetLine) => {
      if (
        betLine.betCategoryType === BetCategoryType.DrawGame ||
        !!betLine.oddsBoost ||
        !!betLine.manualOddsBoost ||
        !!betLine.oddsBoostId ||
        !!betLine.manualOddsBoostId
      ) {
        return items;
      }

      if (betLine.betBuilderLines?.length) {
        items.push(...this.betBuilderLinesToSelectedItems(betLine.eventId, betLine.betBuilderLines));
      } else {
        items.push({
          eventId: betLine.eventId,
          betTypeId: betLine.betTypeId,
          eventBetTypeItemId: betLine.eventBetTypeItemId,
          isBetCompletion: betLine.isBetCompletion
        });
      }
      return items;
    }, []);
  }

  betBuilderLinesToSelectedItems(eventId: number, betBuilderLines: BetBuilderLine[]): SelectedItem[] {
    return betBuilderLines.map((betBuilderLine: BetBuilderLine) => ({
      eventId: eventId,
      betTypeId: betBuilderLine.betTypeId,
      eventBetTypeItemId: betBuilderLine.eventBetTypeItemId
    }));
  }

  rebetToBetLine(
    betLineHistory: BetLineHistory,
    betCategoryType: BetCategoryType,
    rebetBetLine: SportsFixedOddsRebetBetLine
  ): BetLine {
    const betLine: BetLine = this.betLineHistoryToBetLine(
      betLineHistory,
      betCategoryType,
      rebetBetLine.eventBetTypeBaseAmount,
      rebetBetLine.eventBetTypeMaximumAmount,
      rebetBetLine.eventBetTypeMinimumAmountIncrement,
      rebetBetLine.newOdds,
      rebetBetLine.allowBetBuilder
    );
    betLine.eventBetTypeId = rebetBetLine.eventBetTypeId;

    return betLine;
  }

  rebetToBetBuilderBetLine(
    betBuilderOdds: BetBuilderOdds,
    betLineHistory: BetLineHistory,
    betCategoryType: BetCategoryType,
    rebetBetLine: SportsFixedOddsRebetBetLine,
    allowedBetLines: SportsFixedOddsRebetBetLine[]
  ): BetLine {
    return {
      ...this.rebetToBetLine(betLineHistory, betCategoryType, rebetBetLine),
      betBuilderLines: betLineHistory.betBuilderLines
        .filter((betBuilderLine: BetBuilderLine) =>
          allowedBetLines.some(
            (betLine: SportsFixedOddsRebetBetLine) => betLine.eventBetTypeItemId === betBuilderLine.eventBetTypeItemId
          )
        )
        .map((betBuilderLine: BetBuilderLine) => {
          const betLine: SportsFixedOddsRebetBetLine = allowedBetLines.find(
            (betLine: SportsFixedOddsRebetBetLine) => betLine.eventBetTypeItemId === betBuilderLine.eventBetTypeItemId
          ) as SportsFixedOddsRebetBetLine;
          betBuilderLine.eventBetTypeItemOdds = betLine.newOdds;
          return !betBuilderOdds.betBuilderError
            ? betBuilderLine
            : {
                ...betBuilderLine,
                betBuilderError: betBuilderOdds.betBuilderError,
                betBuilderErrorParameters: betBuilderOdds.betBuilderErrorParameters
              };
        }),
      isBetBuilder: true,
      eventBetTypeId: undefined,
      betTypeId: undefined,
      odds: betBuilderOdds.odds
    };
  }

  betLineHistoryToBetLine(
    betLineHistory: BetLineHistory,
    betCategoryType: BetCategoryType,
    baseAmount: number,
    maximumAmount?: number,
    minimumAmountIncrement?: number,
    odds?: number,
    allowBetBuilder?: boolean
  ): BetLine {
    const betLine: BetLine = {
      betCategoryType: betCategoryType,
      eventType: betLineHistory.eventType,
      eventId: betLineHistory.eventId,
      eventName: betLineHistory.eventName,
      eventDate: betLineHistory.eventDate,
      entryPointId: betLineHistory.entryPointId,
      betTypeId: betLineHistory.selectionType,
      eventBetTypeItemId: betLineHistory.eventBetTypeItemId,
      eventBetTypeName: betLineHistory.eventBetTypeName,
      eventBetTypeItemName: betLineHistory.selectionName,
      displayId: betLineHistory.displayId,
      state: betLineHistory.state,
      active: true,
      bettingAllowed: true,
      isBetCompletion: betLineHistory.isBetCompletion,
      odds: odds ?? betLineHistory.odds,
      minimumAmountIncrement: minimumAmountIncrement ?? baseAmount,
      maximumAmount: maximumAmount ?? baseAmount,
      baseAmount,
      allowBetBuilder
    };

    if (betLine.eventType === EventType.Match) {
      betLine.eventName = `${betLineHistory.homeTeamName} - ${betLineHistory.awayTeamName}`;
      betLine.eventHomeTeamName = betLineHistory.homeTeamName;
      betLine.eventAwayTeamName = betLineHistory.awayTeamName;
      betLine.isLive = betLineHistory.isLive;
      betLine.categories = betLineHistory.categories;
    }

    return betLine;
  }

  betLinesToBetBuilderErrorInfo(betLines: BetLine[]): BetBuilderErrorInfo | undefined {
    const betBuilderErrorsInfo: BetBuilderErrorInfo[] = this.betLinesToBetBuilderErrorsInfo(betLines);
    let prioritizedErrorInfo: BetBuilderErrorInfo | undefined;

    betBuilderErrorsByPriority.forEach((betBuilderErrorByPriority: BetBuilderError) =>
      betBuilderErrorsInfo.forEach((betBuilderErrorInfo: BetBuilderErrorInfo) => {
        if (!prioritizedErrorInfo && betBuilderErrorInfo.betBuilderError === betBuilderErrorByPriority) {
          prioritizedErrorInfo = betBuilderErrorInfo;
        }
      })
    );
    return prioritizedErrorInfo;
  }

  betLinesToBetBuilderLines(betLines: BetLine[]): BetBuilderLine[] {
    return betLines.map((betLine: BetLine) => this.betLineToBetBuilderLine(betLine));
  }

  betBuilderBetLineToSimpleBetLines(betBuilderBetLine: BetLine): BetLine[] {
    return betBuilderBetLine.betBuilderLines.map((betBuilderLine: BetBuilderLine) => ({
      ...betBuilderBetLine,
      isBetBuilder: false,
      betBuilderLines: [],
      eventBetTypeName: betBuilderLine?.eventBetTypeName,
      eventBetTypeId: betBuilderLine?.eventBetTypeId,
      eventBetTypeItemName: betBuilderLine?.eventBetTypeItemName,
      eventBetTypeItemId: betBuilderLine?.eventBetTypeItemId,
      betTypeId: betBuilderLine.betTypeId,
      odds: betBuilderLine.eventBetTypeItemOdds,
      allowBetBuilder: betBuilderLine.betBuilderError !== BetBuilderError.IneligibleSelection,
      canBeSimulated: betBuilderLine.canBeSimulated
    }));
  }

  betBuilderBetLinesToEventsItemIds(betBuilderBetLines: BetLine[]): BetBuilderEventItemIds[] {
    return betBuilderBetLines.map((betBuilderBetLine: BetLine) => ({
      eventId: betBuilderBetLine.eventId,
      eventBetTypeItemIds:
        betBuilderBetLine.betBuilderLines?.map((betBuilderLine: BetBuilderLine) => betBuilderLine.eventBetTypeItemId) ??
        []
    }));
  }

  simpleBetLinesToBetBuilderBetLine(simpleBetLines: BetLine[]): BetLine {
    const betBuilderLines: BetBuilderLine[] = this.betLinesToBetBuilderLines(simpleBetLines);
    return {
      ...simpleBetLines[0],
      active: true,
      isBetBuilder: true,
      betBuilderLines,
      eventBetTypeName: undefined,
      eventBetTypeId: undefined,
      eventBetTypeItemName: undefined,
      eventBetTypeItemId: undefined,
      betTypeId: undefined,
      odds: 0
    };
  }

  createBetBuilderBetLine(match: Match, eventBetType: EventBetType): BetLine {
    return {
      state: BetLineStateType.Pending,
      betCategoryType: BetCategoryType.SportsFixedOdds,
      eventType: match.eventType,
      eventId: match.id,
      eventDate: match.expectedStart,
      entryPointId: match.entryPointId,
      displayId: match.displayId,
      eventName: `${match.homeTeamName} - ${match.awayTeamName}`,
      eventHomeTeamName: match.homeTeamName,
      eventAwayTeamName: match.awayTeamName,
      categories: match.categories,
      baseAmount: eventBetType.baseAmount,
      minimumAmountIncrement: eventBetType.minimumAmountIncrement,
      maximumAmount: eventBetType.maximumAmount,
      isBetBuilder: true,
      betBuilderLines: [],
      isAsian: eventBetType.isAsian,
      active: eventBetType.active,
      bettingAllowed: eventBetType.bettingAllowed,
      isLive: eventBetType.betTypeId > 20000 && eventBetType.betTypeId < 30000,
      odds: 0,
      allowBetBuilder: true,
      canBeSimulated: match.canBeSimulated && eventBetType.canBeSimulated
    };
  }

  createBetBuilderLine(match: Match, eventBetType: EventBetType, eventBetTypeItem: EventBetTypeItem): BetBuilderLine {
    return {
      state: BetLineStateType.Pending,
      active: eventBetType.active,
      bettingAllowed: eventBetType.bettingAllowed,
      betTypeId: eventBetType.betTypeId,
      isAsian: eventBetType.isAsian,
      eventBetTypeId: eventBetType.id,
      eventBetTypeItemId: eventBetTypeItem.id,
      eventBetTypeName: eventBetType.name,
      eventBetTypeItemName: eventBetTypeItem.longName || eventBetTypeItem.shortName,
      eventBetTypeItemOdds: eventBetTypeItem.odds,
      betBuilderError: !eventBetType.allowBetBuilder ? BetBuilderError.IneligibleSelection : null,
      canBeSimulated: match.canBeSimulated && eventBetType.canBeSimulated && eventBetTypeItem.canBeSimulated
    };
  }

  private betLineToBetBuilderLine(betLine: BetLine): BetBuilderLine {
    return {
      state: betLine.state,
      active: betLine.active,
      bettingAllowed: betLine.bettingAllowed,
      betTypeId: betLine.betTypeId,
      isAsian: betLine.isAsian,
      eventBetTypeId: betLine.eventBetTypeId,
      eventBetTypeItemId: betLine.eventBetTypeItemId,
      eventBetTypeName: betLine.eventBetTypeName,
      eventBetTypeItemName: betLine.eventBetTypeItemName,
      eventBetTypeItemOdds: betLine.odds,
      betBuilderError: !betLine.allowBetBuilder || !betLine.active ? BetBuilderError.IneligibleSelection : null,
      canBeSimulated: betLine.canBeSimulated
    };
  }

  private betLinesToBetBuilderErrorsInfo(betLines: BetLine[]): BetBuilderErrorInfo[] {
    return betLines.reduce((errorsInfo: BetBuilderErrorInfo[], betLine: BetLine) => {
      betLine.betBuilderLines?.forEach((betBuilderLine: BetBuilderLine) => {
        if (betBuilderLine.betBuilderError) {
          errorsInfo.push({
            betBuilderError: betBuilderLine.betBuilderError,
            betBuilderErrorParameters: betBuilderLine.betBuilderErrorParameters
          });
        }
      });
      return errorsInfo;
    }, []);
  }
}
