import { Component, ChangeDetectionStrategy, Input, ViewChild, ElementRef, Output, EventEmitter } from '@angular/core';
import {
  Me,
  DocumentConfiguration,
  DocumentTypeConfiguration,
  KnowYourCustomerConfiguration
} from '@honoregaming/customer-core';
import { Subject } from 'rxjs';

@Component({
  selector: 'hg-account-form-document-type',
  templateUrl: './account-form-document-type.component.html',
  styleUrls: ['./account-form-document-type.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class AccountFormDocumentTypeComponent {
  @Input() knowYourCustomerConfiguration: KnowYourCustomerConfiguration;
  @Input() me: Me;
  @Input() selectedDocumentType: DocumentTypeConfiguration;
  @Input() documentType: DocumentTypeConfiguration;
  @Input() index: number;

  @Output()
  nextDocumentTypeEvent = new EventEmitter();

  @Output()
  previousDocumentTypeEvent = new EventEmitter();

  documentSelected: DocumentConfiguration;
  filesUploadedNumber: number = 0;
  hasAllDocuments: boolean = false;
  cancelSubject: Subject<void> = new Subject<void>();

  @ViewChild('inputFile') inputFile: ElementRef;

  constructor() {}

  fileUploaded() {
    this.filesUploadedNumber++;
    if ((this.documentSelected.rectoVerso && this.filesUploadedNumber === 2) || !this.documentSelected.rectoVerso) {
      this.hasAllDocuments = true;
      this.nextDocumentTypeEvent.emit();
    }
  }

  resetDocuments() {
    this.filesUploadedNumber = 0;
    this.hasAllDocuments = false;
    this.previousDocumentTypeEvent.emit(this.index);
  }

  cancel() {
    this.documentSelected = null;
    this.cancelSubject.next();
  }
}
