import { ITelemetryService } from './telemetry-service.model';
import { Injectable, Inject, PLATFORM_ID } from '@angular/core';
import { DOCUMENT, isPlatformBrowser } from '@angular/common';
import { EgwConversionEvent } from '@honoregaming/configuration';
import { CustomerOperatorConfiguration, customerOperatorConfigurationToken } from '../../models';

declare var window: any;

const EGW_SCRIPT_ID = 'egw-ads-js';

// Vendor-mandated bootstrap snippet, injected verbatim. The internal eval() is the EGW SDK's own
// localStorage cache-replay mechanism; the content here is a static, trusted constant (no user input),
// so injecting it via innerHTML carries no XSS surface — same approach as FacebookPixelTelemetryService.
const EGW_BOOTSTRAP_SNIPPET: string = `;(function (win, doc, loc) { if (loc.getItem('EGW_TRACK_JS')) eval(loc.getItem('EGW_TRACK_JS')); if (new Date().getTime() - (loc.getItem('EGW_TRACK_SINCE_TIME') || 0) > Math.min(24 * 3600000, loc.getItem('EGW_TRACK_EXPIRED') || 0) || !loc.getItem('EGW_TRACK_JS')) { var elem = doc.createElement('script'); elem.src = '//cm-oss.sunnbird.com/tmcsdk/egw.track.js?' + String(new Date().getTime()).substr(-10, 7); elem.async = true; doc.documentElement.appendChild(elem); } if (!win.egw_track_send) win.egw_track_send = function () { var me = win.egw_track_send; me.queue = me.queue || []; me.queue.push(arguments) }; win.egw_track_send('egw_track_init', {}) })(window, document, localStorage);`;

@Injectable()
export class EgwTelemetryService implements ITelemetryService {
  private readonly isBrowser = isPlatformBrowser(this.platformId);
  private readonly configuration = this.operatorConfig.telemetryConfiguration.egw;

  constructor(
    @Inject(customerOperatorConfigurationToken) private readonly operatorConfig: CustomerOperatorConfiguration,
    @Inject(DOCUMENT) private readonly document: Document,
    @Inject(PLATFORM_ID) private readonly platformId: Object
  ) {
    this.registerScript();
  }

  trackPageView(_name: string, _path: string): void {}

  trackEvent(name: string, _properties: unknown): void {
    switch (name) {
      case 'sign_up_complete': {
        this.send(this.configuration?.registration);
        break;
      }
      case 'firstTimeDeposit': {
        this.send(this.configuration?.firstTimeDeposit);
        break;
      }
    }
  }

  private registerScript(): void {
    if (!this.isBrowser || this.document.getElementById(EGW_SCRIPT_ID)) {
      return;
    }

    const scriptElement: HTMLScriptElement = this.document.createElement('script');
    scriptElement.id = EGW_SCRIPT_ID;
    scriptElement.innerHTML = EGW_BOOTSTRAP_SNIPPET;
    this.document.head.appendChild(scriptElement);
  }

  private send(conversion?: EgwConversionEvent): void {
    if (!this.isBrowser || !conversion?.eventCode || !conversion?.conversionTrackingId) {
      return;
    }

    window.egw_track_send(`${conversion.eventCode}`, {
      conversion_tracking_id: Number(conversion.conversionTrackingId)
    });
  }
}
