import { ChangeDetectionStrategy, ChangeDetectorRef, Component, OnInit } from '@angular/core';
import { Observable, of, Subject } from 'rxjs';
import { catchError, switchMap, takeUntil, tap } from 'rxjs/operators';
import { BetCategoryType, BetState, SportsPoolBet, BetCategoryFilterData } from '@honoregaming/types';
import { BetCategoryConfigurationService, DestroySubject } from '@honoregaming/core';
import { AccountService } from '@honoregaming/account';
import { AccountFilter, SelectValue } from '../../models/account-filters.model';

@Component({
  selector: 'hg-sports-pool-bets-history',
  templateUrl: './sports-pool-bets-history.component.html',
  styleUrls: ['./sports-pool-bets-history.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class SportsPoolBetsHistoryComponent extends DestroySubject implements OnInit {
  betCategoriesFilterData: BetCategoryFilterData[] = [];
  readonly BetCategoryType = BetCategoryType;
  bets: SportsPoolBet[] = [];
  isLoading: boolean = false;
  isLoadMore: boolean = false;

  readonly states: SelectValue[] = [{ value: BetState.Pending }, { value: BetState.Won }, { value: BetState.Lost }];

  currentFilter: AccountFilter = {};

  private static readonly PAGE_SIZE = 5;

  private skip: number = 0;
  public hasMore: boolean = true;

  private readonly loadHistory$: Subject<boolean> = new Subject<boolean>();

  constructor(
    private readonly accountService: AccountService,
    private readonly cdRef: ChangeDetectorRef,
    private readonly betCategoryConfigurationService: BetCategoryConfigurationService
  ) {
    super();
  }

  ngOnInit(): void {
    this.betCategoriesFilterData = this.betCategoryConfigurationService.historyBetCategoriesFilterData;
    this.subscribeToLoadHistory();
  }

  filter(filter: AccountFilter): void {
    this.resetPagination();
    // Copy: the filters component mutates and re-emits the very same object reference
    this.currentFilter = { ...filter };
    this.loadHistory$.next(false);
  }

  loadMore(): void {
    if (this.isLoading || !this.hasMore) {
      return;
    }

    this.loadHistory$.next(true);
  }

  private subscribeToLoadHistory(): void {
    this.loadHistory$
      .pipe(
        tap((isLoadMore: boolean) => this.startLoading(isLoadMore)),
        // switchMap cancels the pending request, so a response from a previous
        // filter can never be appended to the list of the newly selected one
        switchMap(() => this.getBets()),
        takeUntil(this.destroy$)
      )
      .subscribe((bets: SportsPoolBet[]) => {
        this.handleResponse(bets);
        this.finishLoading();
      });
  }

  private getBets(): Observable<SportsPoolBet[]> {
    return this.accountService
      .getSportsPoolGameBetsHistory(
        this.skip,
        SportsPoolBetsHistoryComponent.PAGE_SIZE,
        this.currentFilter.state as BetState,
        this.currentFilter.month
      )
      .pipe(catchError(() => of<SportsPoolBet[]>([])));
  }

  private startLoading(isLoadMore: boolean): void {
    this.isLoading = true;
    this.isLoadMore = isLoadMore;
    this.cdRef.markForCheck();
  }

  private handleResponse(bets: SportsPoolBet[]): void {
    if (!bets?.length) {
      this.hasMore = false;
      return;
    }

    this.bets = [...this.bets, ...bets];
    this.skip += bets.length;
    this.hasMore = bets.length === SportsPoolBetsHistoryComponent.PAGE_SIZE;
  }

  private resetPagination(): void {
    this.skip = 0;
    this.hasMore = true;
    this.bets = [];
  }

  private finishLoading(): void {
    this.isLoading = false;
    this.cdRef.markForCheck();
  }
}
