import { ChangeDetectionStrategy, Component, EventEmitter, Input, OnInit, Optional, Output } from '@angular/core';
import { DestroySubject } from '@honoregaming/core';
import { Media, MediaService } from '@honoregaming/ui';
import { takeUntil } from 'rxjs/operators';
@Component({
  selector: 'hg-image-with-link',
  templateUrl: './image-with-link.component.html',
  styleUrls: ['./image-with-link.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class ImageWithLinkComponent extends DestroySubject implements OnInit {
  @Input() desktopImage?: { url: string } | null;
  @Input() mobileImage?: { url: string } | null;
  @Input() link?: string | null;

  @Output() close = new EventEmitter<unknown>();

  constructor(@Optional() private mediaService: MediaService) {
    super();
  }

  ngOnInit(): void {
    this.mediaService?.media$.pipe(takeUntil(this.destroy$)).subscribe(media => {
      // Emit close event if there is no image available for the screen size
      if ((media < Media.md && !this.mobileImage?.url) || (media >= Media.md && !this.desktopImage?.url)) {
        this.close.emit();
      }
    });
  }
}
