import {
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  Inject,
  Input,
  OnDestroy,
  OnInit,
  ViewChild
} from '@angular/core';
import { finalize, takeUntil } from 'rxjs/operators';
import { DestroySubject, LocalStorageService, PushService } from '@honoregaming/core';
import { I18nService } from '@honoregaming/i18n';
import {
  CustomerDirectMessageConfiguration,
  CustomerOperatorConfiguration,
  customerOperatorConfigurationToken,
  DirectMessage,
  DirectMessageCategory,
  DirectMessageDirection,
  DirectMessageService
} from '@honoregaming/customer-core';
import { DirectMessageConfiguration } from '@honoregaming/configuration';
import { TextareaComponent } from '@honoregaming/ui';
import { NavBarService } from 'projects/customer/customer/src/app/services';
import { DirectMessageThreadResolution } from '../../models/direct-message-thread-resolution.model';

@Component({
  selector: 'hg-direct-message',
  templateUrl: './direct-message.component.html',
  styleUrls: ['./direct-message.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class DirectMessageComponent extends DestroySubject implements OnInit, OnDestroy {
  @Input() fromWidget: boolean = false;
  @Input() configuration?: CustomerDirectMessageConfiguration;

  @ViewChild(TextareaComponent) textarea?: TextareaComponent;

  DirectMessageDirection = DirectMessageDirection;
  DirectMessageCategory = DirectMessageCategory;

  localStorageMessageKey: string = 'MESSAGE_CENTER_SAVED_MESSAGED';
  administratorName: string = null;
  directMessageConfig?: CustomerDirectMessageConfiguration;
  displayYearInDate: boolean = this.operatorConfiguration.directMessageConfiguration?.displayYearInDate;
  displayHelpImage: boolean = this.operatorConfiguration.directMessageConfiguration?.displayHelpImage;
  numberOfConsecutiveMessagesAllowed: number =
    this.operatorConfiguration.directMessageConfiguration?.numberOfConsecutiveMessagesAllowed;

  pageIndex: number = 0;
  messages: DirectMessage[] = [];
  resolutions: DirectMessageThreadResolution[] = [];
  repliedMessage: DirectMessage = null;
  lastMessageId?: number;
  firstId?: number;
  hasMore: boolean = false;
  hasMoreUnread: boolean = false;
  newMessageValue: string = null;

  isLoading: boolean = false;
  isPostingNewMessage: boolean = false;
  valid: boolean = false;
  canReply: boolean = false;
  canUploadImage: boolean = false;
  messageTooLong: boolean = false;
  hasSpammed: boolean = false;
  forceScroll: boolean = false;
  hasNoMessageSubText: boolean = false;
  hasFixedInformationText: boolean = false;
  hasNoMessageHelpSubText: boolean = false;
  lockImageTooltip: boolean = false;

  fileSelected?: File = null;
  fileUploadErrorMessage?: string;
  uploadingFile: boolean = false;

  refreshRate: number = 5000;
  interval?: NodeJS.Timeout;
  nextActive?: Date;

  constructor(
    private readonly directMessageService: DirectMessageService,
    private readonly localStorageService: LocalStorageService,
    private readonly navBarService: NavBarService,
    private readonly cdRef: ChangeDetectorRef,
    private readonly i18nService: I18nService,
    private readonly pushService: PushService,
    @Inject(customerOperatorConfigurationToken) private readonly operatorConfiguration: CustomerOperatorConfiguration
  ) {
    super();
  }

  ngOnInit(): void {
    this.loadTranslationsExists();
    this.loadDirectMessageConfig();
    this.loadMessages();
    this.restoreDraftMessage();
    this.setupMessageRefresh();

    this.pushService.directMessageIncrementChangedSubject.next(0);
  }

  ngOnDestroy(): void {
    super.ngOnDestroy();
    clearInterval(this.interval);
  }

  showMore(): void {
    this.pageIndex++;
    this.loadPreviousMessages(this.firstId);
  }

  checkMessageValidity(): void {
    const trimmed: string = this.newMessageValue?.trim();

    this.messageTooLong = this.newMessageValue?.length > 3000;
    this.valid = this.newMessageValue && !this.messageTooLong && trimmed.length > 0;
    this.localStorageService.setItem(this.localStorageMessageKey, this.newMessageValue);
    this.cdRef.markForCheck();
  }

  newMessage(): void {
    if (!this.valid) {
      return;
    }

    if (this.fileSelected) {
      this.uploadImage();
      return;
    }

    this.lastMessageId += 1;
    this.isPostingNewMessage = true;
    this.directMessageService
      .postNewDirectMessages(this.newMessageValue, this.repliedMessage?.id ?? null)
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.checkMessageValidity();
          this.isPostingNewMessage = false;
          this.cdRef.markForCheck();
          setTimeout(() => this.textarea.setFocus());
        })
      )
      .subscribe(newMessage => {
        this.lastMessageId = newMessage.id;
        this.messages.unshift(newMessage);
        this.messages = [...this.messages];
        this.newMessageValue = null;
        this.repliedMessage = null;
        this.localStorageService.removeItem(this.localStorageMessageKey);
        this.forceScroll = true;

        this.checkIfCustomerHasSpammed();
      });
  }

  textareaFocus(isFocus: boolean): void {
    this.navBarService.setNavBarActive(!isFocus);
  }

  selectImage(): void {
    const fileSelect = document.getElementById('picture') as HTMLInputElement;

    if (!fileSelect) {
      return;
    }
    fileSelect.value = '';
    fileSelect.click();
  }

  previewPicture(event): void {
    const picturePreview = document.getElementById('preview') as HTMLInputElement;

    this.fileSelected = event.target.files[0];
    if (this.fileSelected) {
      picturePreview.src = URL.createObjectURL(this.fileSelected);
      this.valid = true;
    }
  }

  openPicture(event): void {
    open(event.target.currentSrc);
  }

  deleteFile(): void {
    const picturePreview = document.getElementById('preview') as HTMLInputElement;

    if (picturePreview) {
      URL.revokeObjectURL(picturePreview.src);
    }
    this.fileSelected = null;
    delete this.fileSelected;
    this.fileUploadErrorMessage = null;
  }

  private loadTranslationsExists(): void {
    this.hasNoMessageSubText = this.i18nService.translationKeyExistsSync('DIRECT_MESSAGE.NO_MESSAGE.SUB_TEXT.HELLO');
    this.hasNoMessageHelpSubText = this.i18nService.translationKeyExistsSync('DIRECT_MESSAGE.NO_MESSAGE.SUB_TEXT.HELP');
    this.hasFixedInformationText = this.i18nService.translationKeyExistsSync('DIRECT_MESSAGE.INFORMATION');
  }

  private loadDirectMessageConfig(): void {
    if (this.configuration) {
      this.setConfiguration(this.configuration, this.operatorConfiguration.directMessageConfiguration);
      return;
    }

    this.isLoading = true;
    this.directMessageService
      .getDirectMessageConfig()
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => this.cdRef.markForCheck())
      )
      .subscribe(config => {
        this.setConfiguration(config, this.operatorConfiguration.directMessageConfiguration);
      });
  }

  private setConfiguration(
    configuration: CustomerDirectMessageConfiguration,
    operatorConfiguration: DirectMessageConfiguration
  ): void {
    this.directMessageConfig = configuration;
    this.canReply = operatorConfiguration.canReplyToDirectMessage;
    this.canUploadImage = operatorConfiguration.allowedImageUpload && configuration.canUploadImage;
    this.nextActive = configuration.nextActiveDateTime ? new Date(configuration.nextActiveDateTime) : null;
    if (!this.directMessageConfig.canSendDirectMessages) {
      this.clearDraftMessage();
    }
  }

  private clearDraftMessage(): void {
    this.localStorageService.removeItem(this.localStorageMessageKey);
    this.newMessageValue = null;
  }

  private restoreDraftMessage(): void {
    this.newMessageValue = this.localStorageService.getItem(this.localStorageMessageKey) ?? null;
    this.checkMessageValidity();
  }

  private setupMessageRefresh(): void {
    this.interval = setInterval(() => {
      if (this.lastMessageId && !this.isLoading) {
        this.loadRecentMessages(this.lastMessageId);
      }
    }, this.refreshRate);
  }

  private loadMessages(): void {
    this.isLoading = true;
    this.directMessageService
      .getDirectMessages()
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.isLoading = false;
          this.cdRef.markForCheck();
        })
      )
      .subscribe(res => {
        let messages: DirectMessage[] = res.items;
        this.messages = this.messages.concat(messages);
        this.hasMore = res.pagination.hasMore;
        this.hasMoreUnread = res.hasMoreUnread;
        this.resolutions = res.resolutions;

        if (messages?.length) {
          this.lastMessageId = messages[0].id;
          this.firstId = messages[messages.length - 1].id;
          this.administratorName ??= res.claimedAdministratorName;
        }

        if (
          messages?.length &&
          messages[0].solved &&
          messages[0].category !== DirectMessageCategory.BatchAction &&
          this.i18nService.translationKeyExistsSync('DIRECT_MESSAGE.DEFAULT_MESSAGE')
        ) {
          this.messages.unshift({
            id: 0,
            content: this.i18nService.translateSync('DIRECT_MESSAGE.DEFAULT_MESSAGE'),
            administratorName: null,
            solved: true,
            direction: DirectMessageDirection.Incoming,
            date: new Date().getDate(),
            dateTime: new Date(),
            month: new Date().getMonth()
          });
        }

        this.checkIfCustomerHasSpammed();
      });
  }

  private loadRecentMessages(lastId: number): void {
    this.directMessageService
      .getRecentMessages(lastId)
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.cdRef.markForCheck();
        })
      )
      .subscribe(res => {
        const { items, claimedAdministratorName } = res;
        const lastMessage: DirectMessage = items?.[items?.length - 1];

        if (lastMessage?.threadResolutions) {
          const resolutions: DirectMessageThreadResolution[] = lastMessage.threadResolutions;
          const newResolutions: DirectMessageThreadResolution[] = resolutions.filter(
            (item: DirectMessageThreadResolution) =>
              !this.resolutions.map(directMessageThreadResolution => directMessageThreadResolution.id).includes(item.id)
          );

          this.resolutions = [...this.resolutions, ...newResolutions];
        }
        items?.splice(items?.length - 1, 1);
        if (items?.length > 0) {
          const newMessages: DirectMessage[] = items.filter(
            (item: DirectMessage) => !this.messages.map(directMessage => directMessage.id).includes(item.id)
          );

          this.messages = newMessages.concat(this.messages);
          this.lastMessageId = newMessages[0]?.id;
        }

        this.administratorName = claimedAdministratorName;
        this.checkIfCustomerHasSpammed();
      });
  }

  private loadPreviousMessages(messageId: number): void {
    this.directMessageService
      .getPreviousDirectMessages(messageId)
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.isLoading = false;
          this.cdRef.markForCheck();
        })
      )
      .subscribe(res => {
        const messages: DirectMessage[] = res.items;

        if (messages.length > 0) {
          this.firstId = messages[messages.length - 1].id;
          this.messages = this.messages.concat(messages);
          this.hasMore = res.pagination.hasMore;
        }
      });
  }

  private uploadImage(): void {
    if (!this.fileSelected) {
      return;
    }

    const { maximumFileSizeAllowed } = this.operatorConfiguration.directMessageConfiguration;

    if (this.fileSelected.size > (maximumFileSizeAllowed || 500000)) {
      this.fileUploadErrorMessage = this.i18nService.translateSync(
        'DIRECT_MESSAGE.UPLOAD_PICTURE.ERROR.2',
        (maximumFileSizeAllowed || 500000).toString()
      );
      return;
    }

    this.isPostingNewMessage = true;
    this.fileUploadErrorMessage = null;
    this.directMessageService
      .uploadImage(this.fileSelected, this.newMessageValue, this.repliedMessage?.id)
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.isPostingNewMessage = false;
          this.cdRef.markForCheck();
          setTimeout(() => this.textarea.setFocus(), 0);
        })
      )
      .subscribe(
        () => {
          this.newMessageValue = null;
          this.repliedMessage = null;
          this.fileSelected = null;
          this.localStorageService.removeItem(this.localStorageMessageKey);
          if (this.lastMessageId) {
            this.loadRecentMessages(this.lastMessageId);
          } else {
            this.loadMessages();
          }
        },
        err => {
          this.fileUploadErrorMessage = this.i18nService.translateSync(
            `DIRECT_MESSAGE.UPLOAD_PICTURE.ERROR.${err.error.code}`,
            (maximumFileSizeAllowed || 500000).toString()
          );
        }
      );
  }

  private checkIfCustomerHasSpammed(): void {
    let shouldSkip: boolean = false;
    let spamCount: number = 0;

    if (this.messages.length > 0) {
      this.messages
        .sort((a, b) => b.id - a.id)
        .forEach((directMessage: DirectMessage) => {
          if (shouldSkip) {
            return;
          }

          if (directMessage.direction === DirectMessageDirection.Outcoming) {
            spamCount++;
          }

          if (spamCount >= this.numberOfConsecutiveMessagesAllowed) {
            this.hasSpammed = true;
            shouldSkip = true;
            return;
          }

          if (directMessage.direction === DirectMessageDirection.Incoming) {
            this.hasSpammed = false;
            shouldSkip = true;
          }
        });
    } else {
      this.hasSpammed = this.numberOfConsecutiveMessagesAllowed === 0;
    }
  }
}
