import { BetLine, Amounts } from '../../models';
import { floorNumber, preciseFloatingPointNumber, add, sub } from '@honoregaming/core';
import { BetCategoryType, isInsaLeaguesEntryPoint } from '@honoregaming/types';
import { IBetSlipModeHandler } from './ibet-slip-mode-handler';
import { getBetLineIndex, computeBettingTaxAmounts, computePaymentTaxAmounts } from '../../utils';
import { MultipleBonus, OperatorConfiguration } from '@honoregaming/configuration';

export class BetSlipMultipleModeHandler implements IBetSlipModeHandler {
  constructor(private operatorConfiguration: OperatorConfiguration) {}

  computeBetSlipInstantGameSummary(_stake: number, _amounts: Amounts): void {
    throw new Error('Method not implemented.');
  }

  initBetSlip(
    betLines: BetLine[],
    amounts: Amounts,
    lastStake?: number,
    reuseAmountsValues?: boolean,
    defaultAmount?: number
  ) {
    const stake: number = lastStake ?? defaultAmount;
    if (!reuseAmountsValues && stake) {
      const baseAmountThreshold = Math.max(...betLines.map(l => l.baseAmount));
      amounts.values = [{ amount: baseAmountThreshold <= stake ? stake : baseAmountThreshold }];
    } else if (!reuseAmountsValues || amounts.values.length !== 1) {
      amounts.values = [{ amount: Math.max(...betLines.map(l => l.baseAmount)) }];
    }
  }

  addBetLine(
    betLineToAdd: BetLine,
    existingBetLines: BetLine[],
    amounts: Amounts,
    lastStake?: number,
    defaultAmount?: number
  ) {
    existingBetLines.push(betLineToAdd);

    const currentAmount: number = amounts.values[0]?.amount;

    if (
      (currentAmount != null && currentAmount < betLineToAdd.baseAmount) ||
      (currentAmount == null && lastStake && lastStake < betLineToAdd.baseAmount) ||
      (currentAmount == null && defaultAmount && defaultAmount < betLineToAdd.baseAmount)
    ) {
      amounts.values[0].amount = betLineToAdd.baseAmount ?? defaultAmount;
    } else if (
      (currentAmount != null && currentAmount > betLineToAdd.maximumAmount) ||
      (currentAmount == null && lastStake && lastStake > betLineToAdd.maximumAmount) ||
      (currentAmount == null && defaultAmount && defaultAmount > betLineToAdd.maximumAmount)
    ) {
      amounts.values[0].amount = betLineToAdd.maximumAmount ?? defaultAmount;
    } else if (currentAmount == null && defaultAmount && lastStake && lastStake < defaultAmount) {
      amounts.values[0].amount = defaultAmount;
    } else if (currentAmount == null && (defaultAmount || lastStake)) {
      amounts.values[0].amount = lastStake ?? defaultAmount;
    }
  }

  removeBetLine(betLineToRemove: BetLine, existingBetLines: BetLine[], _amounts: Amounts) {
    const itemIndex = getBetLineIndex(betLineToRemove, existingBetLines);

    existingBetLines.splice(itemIndex, 1);
  }

  computeBetSlipSummary(betLines: BetLine[], amounts: Amounts) {
    const decimals: number = this.operatorConfiguration.currency.numberOfDecimals;
    const stakeWithTax: number = amounts.values[0]?.amount;

    const { stake, bettingTax } = this.computeStakeAfterBettingTax(stakeWithTax, amounts);
    const rawGrossPayout: number = this.computeGrossPayout(stake, betLines, amounts.useFreeBet);
    const grossPayout: number = floorNumber(preciseFloatingPointNumber(rawGrossPayout), decimals);
    const { bonus, maxBonusReach, payoutWithBonus } = this.computeBonus(rawGrossPayout, stake, amounts, decimals);
    const { payout, paymentTax } = this.computePayoutAfterPaymentTax(stake, payoutWithBonus, amounts, decimals);
    // The displayed gross payouts must stay consistent with the rounded net payout and tax (base + bonus = net + tax)
    const maxPayoutWithBonusAfterRounding: number = paymentTax != null ? add(payout, paymentTax) : payoutWithBonus;

    amounts.summary.totalStakeWithTax = stakeWithTax;
    amounts.summary.bettingTax = bettingTax;
    amounts.summary.totalStake = stake;
    amounts.summary.baseMaxPayout =
      paymentTax != null
        ? sub(maxPayoutWithBonusAfterRounding, bonus)
        : floorNumber(preciseFloatingPointNumber(grossPayout), decimals);
    amounts.summary.bonus = bonus;
    amounts.summary.maxPayoutWithBonus = maxPayoutWithBonusAfterRounding;
    amounts.summary.paymentTax = paymentTax;
    amounts.summary.maxPayout = payout;
    amounts.maxBonusReach = maxBonusReach;
    amounts.values = amounts.values.map(value => ({ ...value }));
  }

  private computeStakeAfterBettingTax(amount: number, amounts: Amounts): { stake: number; bettingTax: number } {
    if (amounts.useFreeBet) {
      return { stake: amount, bettingTax: null };
    }

    const result = computeBettingTaxAmounts(
      amount,
      amounts.bettingTax,
      this.operatorConfiguration.currency.numberOfDecimals
    );
    return { stake: result.amount, bettingTax: result.tax };
  }

  private computeGrossPayout(stake: number, betLines: BetLine[], useFreeBet: boolean): number {
    const combinedOdds: number = betLines.reduce((product, line) => product * line.odds, 1);
    let payout: number = combinedOdds * stake;

    if (useFreeBet && betLines.every(line => line.odds > 0)) {
      payout = sub(payout, stake);
    }

    // Returned unfloored: the server computes the multiple bonus on the raw winnings (cf CreateBetHandler)
    return payout;
  }

  private computeBonus(
    rawGrossPayout: number,
    stake: number,
    amounts: Amounts,
    decimals: number
  ): { bonus: number; maxBonusReach: boolean; payoutWithBonus: number } {
    const grossPayout: number = floorNumber(preciseFloatingPointNumber(rawGrossPayout), decimals);
    const bonusConfig: MultipleBonus = this.operatorConfiguration.multipleBonus;
    const isEligible: boolean =
      amounts.bonus && (bonusConfig.minimumStake == null || bonusConfig.minimumStake <= stake);

    if (!isEligible) {
      return { bonus: null, maxBonusReach: false, payoutWithBonus: grossPayout };
    }

    // Like the server, the bonus is computed on the raw winnings then floored to the currency decimals (cf CreateBetHandler)
    let bonus: number = floorNumber(
      preciseFloatingPointNumber(rawGrossPayout * (amounts.bonus.coefficient - 1)),
      decimals
    );
    let maxBonusReach: boolean = false;

    if ((bonusConfig?.maxPayout && bonus >= bonusConfig.maxPayout) || (!bonusConfig?.maxPayout && !amounts.nextBonus)) {
      bonus = bonusConfig?.maxPayout || bonus;
      maxBonusReach = true;
    }

    const payoutWithBonus: number = floorNumber(add(grossPayout, bonus), decimals);
    return { bonus, maxBonusReach, payoutWithBonus };
  }

  private computePayoutAfterPaymentTax(
    stake: number,
    grossPayout: number,
    amounts: Amounts,
    decimals: number
  ): { payout: number; paymentTax: number } {
    const skipPaymentTax: boolean = amounts.useFreeBet && !this.operatorConfiguration.freeBetsConfiguration.applyTax;

    if (skipPaymentTax) {
      return {
        payout: floorNumber(preciseFloatingPointNumber(grossPayout), decimals),
        paymentTax: null
      };
    }

    const result = computePaymentTaxAmounts(stake, grossPayout, amounts.paymentTax, decimals);
    return {
      payout: result.amount,
      // The server floors the payment tax (HonoreRound Down), rounding to nearest would display one unit more
      paymentTax: result.tax != null ? floorNumber(preciseFloatingPointNumber(result.tax), decimals) : null
    };
  }

  canBeInMode(betLines: BetLine[]): boolean {
    return (
      (betLines.some((betLine: BetLine) => betLine.isBetCompletion) ||
        betLines.length >= 2 ||
        (betLines.length == 1 && betLines[0].isBetBuilder)) &&
      !this.hasDuplicatedEvent(betLines) &&
      !betLines.find(
        bl =>
          !!bl.oddsBoostId ||
          !!bl.manualOddsBoostId ||
          !!bl.isAsian ||
          (bl.betCategoryType !== BetCategoryType.SportsFixedOdds &&
            bl.betCategoryType !== BetCategoryType.VirtualFixedOdds) ||
          !!bl.combinations?.length ||
          // Some Lucky Loot BetTypes and Keno Pick cannot be in multiple
          (bl.betTypeId >= 30031 && bl.betTypeId <= 30036)
      ) &&
      // PBI 14214: It should not be possible to make a multiple between Fast Leagues & Instant Leagues
      !betLines.includes(
        (betLines.find(l => l.entryPointId === 8019) && betLines.find(l => l.entryPointId === 8030)) ||
          (betLines.find(l => l.entryPointId === 8021) && betLines.find(l => l.entryPointId === 8031)) ||
          (betLines.find(l => l.entryPointId === 8020) && betLines.find(l => l.entryPointId === 8032))
      ) &&
      // Do not allow multiple between Insa & Kiron
      !betLines.includes(
        betLines.find(l => l.entryPointId >= 8000 && l.entryPointId <= 8032) &&
          betLines.find(l => isInsaLeaguesEntryPoint(l.entryPointId))
      )
    );
  }

  hasDuplicatedEvent(betLines: BetLine[]): boolean {
    let hasDuplicatedEvent: boolean = false;
    let hasBetBuilderEvent: boolean = false;

    betLines
      .reduce((byEventId: Map<number, BetLine[]>, betLine: BetLine) => {
        const existingBetLines: BetLine[] = byEventId.get(betLine.eventId);
        byEventId.set(betLine.eventId, existingBetLines ? [...existingBetLines, betLine] : [betLine]);
        return byEventId;
      }, new Map<number, BetLine[]>())
      .forEach((betLines: BetLine[]) => {
        if (
          (betLines.length > 1 && betLines.some((betLine: BetLine) => betLine.allowBetBuilder)) ||
          betLines.some((betLine: BetLine) => betLine.isBetBuilder)
        ) {
          hasBetBuilderEvent = true;
        } else if (betLines.length > 1) {
          hasDuplicatedEvent = true;
        }
      });
    return hasDuplicatedEvent && !hasBetBuilderEvent;
  }
}
