import { Inject, Injectable } from '@angular/core';
import { BehaviorSubject, Observable } from 'rxjs';
import {
  Amounts,
  BetLine,
  BetPlaced,
  betValidationServiceToken,
  configureFreeBetCouponForBetSlip,
  FreeBetCoupon,
  FreeBetCouponBetSlip,
  IBetValidationService,
  validateFreeBetRule
} from '@honoregaming/betslip';
import { OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';
import { BetCategoryType, BetSlipMode, FreeBetCouponState } from '@honoregaming/types';
import { tap } from 'rxjs/operators';
import { ApplicationEvent, BroadcastingService, LocalStorageService } from '@honoregaming/core';

@Injectable({
  providedIn: 'root'
})
export class BetSlipFreebetService {
  private freeBetCouponsSubject: BehaviorSubject<FreeBetCouponBetSlip[]>;
  $freeBetCoupons: Observable<FreeBetCouponBetSlip[]>;

  private availableFreeBetCoupons: FreeBetCouponBetSlip[] = [];
  private selectedFreeBetCoupon: FreeBetCouponBetSlip | null = null;

  leftOverFreeBetEnabled = this.operatorConfiguration.freeBetsConfiguration?.leftOverFreeBetEnabled ?? false;
  multiCouponEnabled = this.operatorConfiguration.freeBetsConfiguration?.multiCouponEnabled ?? false;

  constructor(
    @Inject(betValidationServiceToken) private betValidationService: IBetValidationService,
    @Inject(operatorConfigurationToken) private operatorConfiguration: OperatorConfiguration,
    private localStorageService: LocalStorageService,
    private broadcastingService: BroadcastingService
  ) {
    this.freeBetCouponsSubject = new BehaviorSubject([]);
    this.$freeBetCoupons = this.freeBetCouponsSubject.asObservable();

    // Reset selected coupon after BetPlaced
    this.broadcastingService.register<BetPlaced>(ApplicationEvent.BetPlaced).subscribe(response => {
      if (response?.bet?.amounts?.useFreeBet) {
        this.selectedCoupon = null;
      }
    });
  }

  get selectedCoupon(): FreeBetCouponBetSlip | null {
    return this.selectedFreeBetCoupon;
  }

  set selectedCoupon(coupon: FreeBetCouponBetSlip | null) {
    this.selectedFreeBetCoupon = coupon;
  }

  selectCoupon(id?: number): void {
    this.selectedFreeBetCoupon =
      this.availableFreeBetCoupons.find((coupon: FreeBetCouponBetSlip) => coupon.id === id) ?? null;
  }

  canUseFreeBetCoupons(
    betSlipMode: BetSlipMode,
    betCategoryType: BetCategoryType,
    coupon?: FreeBetCouponBetSlip,
    completeMyBetCouponId?: number
  ): Observable<{ result: boolean; coupons?: FreeBetCoupon[] }> {
    return this.betValidationService.canUseFreeBetCoupons(betSlipMode, betCategoryType, completeMyBetCouponId).pipe(
      tap(canUseFreeBetCoupons => {
        if (canUseFreeBetCoupons.result) {
          if (coupon) {
            this.selectedCoupon = coupon;
          } else if (completeMyBetCouponId) {
            this.selectCoupon(completeMyBetCouponId);
          }
        }
      })
    );
  }

  handleCanUseFreeBetCouponsData(coupons: FreeBetCoupon[], canUseFreeBet?: boolean, completeMyBetCouponId?: number) {
    if (canUseFreeBet) {
      const availableCoupons: FreeBetCoupon[] = coupons.filter(
        (coupon: FreeBetCoupon) =>
          !coupon.freeSpinInfos && (coupon.state === FreeBetCouponState.Open || coupon.id === completeMyBetCouponId)
      );
      if (this.detectBetSlipFreeBetCouponsChanges(availableCoupons)) {
        this.availableFreeBetCoupons = availableCoupons.map(x => configureFreeBetCouponForBetSlip(x));
        this.freeBetCouponsSubject.next(this.availableFreeBetCoupons);
      }
    } else {
      this.clearFreeBetCouponsFromBetSlip();
    }
  }

  computeFreeBetCouponsRequirements(
    betSlipMode: BetSlipMode,
    amounts: Amounts,
    betLines: BetLine[] = [],
    completeMyBetCouponId?: number
  ) {
    if (this.availableFreeBetCoupons.length > 0) {
      const availableCoupons: FreeBetCouponBetSlip[] = this.availableFreeBetCoupons.map(coupon =>
        validateFreeBetRule(
          coupon,
          betSlipMode,
          amounts,
          betLines,
          this.leftOverFreeBetEnabled,
          this.multiCouponEnabled,
          completeMyBetCouponId && completeMyBetCouponId === coupon.id
        )
      );
      this.freeBetCouponsSubject.next(availableCoupons);
    }
  }

  shouldDisplayTutorial(): boolean {
    if (!this.operatorConfiguration.freeBetsConfiguration.tutorialEnabled) {
      return false;
    }
    const tutorialUserId: string | undefined = this.localStorageService.getItem('betslip:freebet_tutorial:valid');
    // Ensure retro-compatibility with existing tutorial storage items with value '1'
    return !tutorialUserId || (tutorialUserId !== '1' && tutorialUserId !== this.localStorageService.getItem('id'));
  }

  validateTutorial(): void {
    const userId: string | undefined = this.localStorageService.getItem('id');
    if (userId) {
      this.localStorageService.setItem('betslip:freebet_tutorial:valid', userId);
    }
  }

  private clearFreeBetCouponsFromBetSlip() {
    this.availableFreeBetCoupons = [];
    this.freeBetCouponsSubject.next([]);
  }

  private detectBetSlipFreeBetCouponsChanges(coupons: FreeBetCoupon[]): boolean {
    if (coupons.length !== this.availableFreeBetCoupons.length) {
      return true;
    }

    return coupons.some(x => {
      let currentCoupon = this.availableFreeBetCoupons.find(y => y.id === x.id);
      return !currentCoupon || currentCoupon.balance !== x.balance;
    });
  }
}
