import { DOCUMENT, isPlatformBrowser, Location } from '@angular/common';
import {
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  ComponentFactoryResolver,
  ElementRef,
  HostBinding,
  HostListener,
  Inject,
  NgZone,
  OnDestroy,
  OnInit,
  Optional,
  PLATFORM_ID,
  ViewChild,
  ViewContainerRef
} from '@angular/core';
import { ActivatedRoute, ActivatedRouteSnapshot, NavigationEnd, Router } from '@angular/router';
import { animationFrameScheduler, EMPTY, from, fromEvent, interval, merge, Observable, of, Subscription } from 'rxjs';
import {
  auditTime,
  catchError,
  distinctUntilChanged,
  filter,
  map,
  pairwise,
  startWith,
  switchMap,
  take,
  takeUntil,
  withLatestFrom
} from 'rxjs/operators';
import { Amounts, BetSlipBetLinesService, BetSlipService, DrawGameBetSlipService } from '@honoregaming/betslip';
import {
  appConfiguration,
  DirectMessageConfiguration,
  Feature,
  OperatorConfiguration,
  operatorConfigurationToken
} from '@honoregaming/configuration';
import {
  ApplicationEvent,
  ApplicationStateService,
  BetCategoryConfigurationService,
  BroadcastingService,
  CompleteMyBetService,
  CookieStorageService,
  DestroySubject,
  DialogService,
  happenBefore,
  kioskToken,
  LocalStorageService,
  natifToken,
  PushService
} from '@honoregaming/core';
import {
  APP_LOADED,
  AuthService,
  CustomerDirectMessageConfiguration,
  CustomerOperatorConfiguration,
  customerOperatorConfigurationToken,
  DirectMessageService,
  getNameForEntryPoint,
  IContainer,
  MainRouterEventBroadcasterService,
  Me,
  MessagesService,
  NavigationService,
  PrivacyService,
  SESSION_IDENTIFIER,
  TelemetryService,
  TrackingEventType,
  TrackingService
} from '@honoregaming/customer-core';
import { InitialFreebetComponent } from '@honoregaming/customer-ui';
import { I18nService } from '@honoregaming/i18n';
import { BatchPopupsService } from '@honoregaming/templating';
import {
  BetCategoryType,
  CompleteMyBetInfo,
  EventBetType,
  EventWithEventBetType,
  Match,
  OpenCloseState
} from '@honoregaming/types';
import { Media, MediaService, MessageService, PopinComponent } from '@honoregaming/ui';
import { CustomerPopupLocation } from 'projects/core/hg-types/models/enums/customer-popup-location.enum';
import { DirectMessageWidgetState } from 'projects/customer/hg-direct-message/src/lib/enums/direct-message-widget-view.enum';
import { GameSessionService } from 'projects/customer/hg-instant-games/src/lib/services/game-session.service';
import { AcceptGcuComponent } from '../../popins/accept-gcu/accept-gcu.component';
import { CustomerPopupService } from '../../popup.service';
import { MobileNavService } from '../../services/mobile-nav.service';
import { NavBarService } from './../../services/nav-bar.service';

@Component({
  selector: 'hg-layout',
  templateUrl: './layout.component.html',
  styleUrls: ['./layout.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class LayoutComponent extends DestroySubject implements OnInit, OnDestroy {
  // Decorators
  @HostBinding('class.my-account') myAccountOverflow: boolean;
  @HostBinding('class.instant-games-layout') isInstantGamesPage: boolean;

  @ViewChild('messageContainer', { read: ViewContainerRef, static: true })
  container?: ViewContainerRef;

  @ViewChild('hgHeader', { read: ElementRef }) private headerElement?: ElementRef<HTMLElement>;

  // Constants
  readonly LOCAL_STORAGE_KEY_DM: string = 'direct_message:widget:state';

  // Public properties
  zendeskModuleScript?: HTMLElement;
  messages?: string[];
  displayMessages: boolean = true;
  anchor?: string;
  amounts?: Amounts;
  displayClock: boolean = this.customerOperatorConfiguration.complianceConfiguration?.displayClock;
  showPrivacyConsent: boolean = false;
  showNavBar: boolean = true;
  haveBottomStickyBanner: boolean = false;
  betSlipActive: boolean = false;
  pressBack: boolean = false;
  isBackAction: boolean = false;
  isBrowserAction: boolean = false;
  isBurgerOpened: boolean = false;
  isBurgerClosed: boolean = false;
  displayAppBanner: boolean = false;
  displayNavbarInContents: boolean = true;
  navigationDepth: number = 0;
  navigateCounter: number = 0;
  newDirectMessagesCount: number = 0;
  canViewDirectMessage: boolean = false;
  displayDirectMessageWidget: boolean = false;
  isSportsPage?: boolean;
  tutorialStep?: number;
  tutorialStepsStorage: string = 'tutorial_steps';
  hasWelcomeTutorial: boolean = this.operatorConfiguration.onlineConfiguration?.welcomeTutorial;
  instantGamePath: string =
    this.customerOperatorConfiguration.betCategoriesPathConfiguration?.instantGamesConfiguration?.path ??
    'instant-games';
  hasHomePageCasino: boolean = this.customerOperatorConfiguration.onlineConfiguration?.homePageCasino;
  displayScrollerIcon: boolean = false;
  me?: Me;
  completeMyBetInfo: CompleteMyBetInfo | null = null;
  instantGamesBetCategoryPath: string = this.betCategoryConfigurationService.getInstantGamesBetCategoryPath();
  currentLanguageCode: string = this.i18nService.currentLanguageCode;
  currentPopinName?: string;
  customerDirectMessageConfiguration?: CustomerDirectMessageConfiguration;

  // Private properties
  private messageCloseSubscription?: Subscription;
  private loadMarqueeMessagesSubscription?: Subscription;
  private displayNewCustomerPopupSubscription?: Subscription;
  private pushSubscription?: Subscription;
  private savedScrollY: number = 0;
  private isBodyFixed: boolean = false;

  constructor(
    private readonly messageService: MessageService,
    private readonly route: ActivatedRoute,
    private readonly router: Router,
    private readonly cdRef: ChangeDetectorRef,
    private readonly resolver: ComponentFactoryResolver,
    private readonly pushService: PushService,
    private readonly dialogService: DialogService,
    private readonly mainRouterEventBroadcasterService: MainRouterEventBroadcasterService,
    private readonly applicationStateService: ApplicationStateService,
    private readonly messagesService: MessagesService,
    private readonly betSlipService: BetSlipService,
    private readonly privacyService: PrivacyService,
    private readonly navBarService: NavBarService,
    private readonly localStorage: LocalStorageService,
    private readonly ngZone: NgZone,
    private readonly broadcastingService: BroadcastingService,
    private readonly authService: AuthService,
    private readonly i18nService: I18nService,
    private readonly customerPopupService: CustomerPopupService,
    private readonly telemetryService: TelemetryService,
    private readonly location: Location,
    private readonly navigationService: NavigationService,
    private readonly mobileNavService: MobileNavService,
    private readonly directMessageService: DirectMessageService,
    private readonly betCategoryConfigurationService: BetCategoryConfigurationService,
    private readonly storageService: CookieStorageService,
    private readonly trackingService: TrackingService,
    private readonly batchPopupsService: BatchPopupsService,
    private readonly completeMyBetService: CompleteMyBetService,
    private readonly gameSessionService: GameSessionService,
    private readonly betSlipBetLinesService: BetSlipBetLinesService,
    private readonly elementRef: ElementRef<HTMLElement>,
    @Inject(customerOperatorConfigurationToken)
    private readonly customerOperatorConfiguration: CustomerOperatorConfiguration,
    @Inject(operatorConfigurationToken) public readonly operatorConfiguration: OperatorConfiguration,
    @Inject(kioskToken) public readonly isKiosk: boolean,
    @Inject(natifToken) public readonly isNatif: boolean,
    @Inject(DOCUMENT) private readonly document: Document,
    @Inject(PLATFORM_ID) private readonly platformId: Object,
    @Optional() protected readonly mediaService: MediaService,
    _drawGameBetSlipService: DrawGameBetSlipService
  ) {
    super();
    this.navigationService.initBackAndForwardNavTracking();
  }

  ngOnInit(): void {
    if (!this.storageService.getItem(APP_LOADED) && !this.authService.isAuthenticated()) {
      this.storageService.setItem(APP_LOADED, 1);

      let getAnalyticsIdentifiersPromise: Observable<{ success: boolean }>;

      if (
        this.isNatif &&
        appConfiguration.flavor &&
        this.operatorConfiguration.marketingConfiguration?.appsFlyerEnabled
      ) {
        // Dynamically import both @capacitor/core and @honoreplugins/analytics-sdk
        getAnalyticsIdentifiersPromise = from(
          Promise.all([import('@capacitor/core'), import('@honoreplugins/analytics-sdk')])
        ).pipe(
          switchMap(([{ Plugins }]) => {
            const { AnalyticsSdk } = Plugins;
            const plugin = AnalyticsSdk as any;
            return from(
              plugin.register({
                appsFlyerDevKey: this.operatorConfiguration.marketingConfiguration?.appsFlyerDevKey
              }) as Promise<{
                success: boolean;
              }>
            );
          }),
          catchError(() => of({ success: false }))
        );
      } else {
        getAnalyticsIdentifiersPromise = of({ success: false });
      }

      getAnalyticsIdentifiersPromise
        .pipe(
          switchMap(_ => {
            // Send AppInstall event so we can create the visitor, the dedicated event and we can track them later
            return this.trackingService.trackEvent({
              eventType: TrackingEventType.ApplicationInstall,
              properties: { IsNative: this.isNatif }
            });
          })
        )
        .subscribe(
          () => {},
          () => {
            this.storageService.removeItem(SESSION_IDENTIFIER);
          }
        );
    }

    this.i18nService.languageChanged$.subscribe(() => {
      this.document.documentElement.setAttribute('lang', this.i18nService.currentLanguageCode);

      if (this.currentLanguageCode && this.currentLanguageCode !== this.i18nService.currentLanguageCode) {
        this.trackingService
          .trackEvent({
            eventType: TrackingEventType.LanguageChange,
            properties: { SelectedLanguage: this.i18nService.currentLanguageCode }
          })
          .subscribe(() => {
            this.currentLanguageCode = this.i18nService.currentLanguageCode;
          });
      }

      if (this.operatorConfiguration.onlineConfiguration?.zendeskEnabled) {
        this.updateZendeskLocale();
      }

      this.loadMessages();
    });

    this.previousRoute = this.router.url;
    if (this.router.url === '/sports') {
      this.storedNavigationDepth = 0;
    }
    this.navigationDepth = this.storedNavigationDepth;
    this.displayAppBanner = JSON.parse(localStorage.getItem('appBannerDisplay'));
    this.haveBottomStickyBanner = location.pathname.startsWith('/about/charities/');
    this.tutorialStep = Number(localStorage.getItem(this.tutorialStepsStorage));
    this.displayScrollerIcon = this.operatorConfiguration.onlineConfiguration.displayScrollerIcon;

    this.setNavigationDepth(this.router.url);
    this.verifyPrivacyConsent();
    this.setAnchor(this.router.url);

    this.isInstantGamesPage = this.router.url.startsWith(`/${this.instantGamesBetCategoryPath}`);
    this.isSportsPage = this.router.url.startsWith('/sports');

    if (!this.hasWelcomeTutorial) {
      localStorage.setItem(this.tutorialStepsStorage, '0');
    }

    this.mobileNavService.tutorialUpdate.pipe(takeUntil(this.destroy$)).subscribe(step => {
      const isBrowser = isPlatformBrowser(this.platformId);
      const stopWelcome = step > 5 || !this.hasWelcomeTutorial;
      const isLarge = this.mediaService.media >= Media.lg;

      this.tutorialStep = step;
      if (isBrowser) {
        if (stopWelcome || isLarge) {
          this.startPeriodicMessagesRefresh();
          this.displayNewCustomerPopup();
        }
        if (stopWelcome) {
          this.batchPopupsService.displayBatchPopups();
        }
      }
      this.cdRef.markForCheck();
    });

    this.router.events
      .pipe(filter(x => x instanceof NavigationEnd))
      .pipe(takeUntil(this.destroy$))
      .subscribe((e: NavigationEnd) => {
        this.setAnchor(e.url);
        this.myAccountOverflow = location.pathname === '/myaccount/operations-history';

        this.haveBottomStickyBanner = location.pathname.startsWith('/about/charities/');

        const navBarDisabledRoutes: boolean = [
          '/about/content',
          '/about/faq',
          '/about/points-of-sale',
          '/horseracing/about'
        ].some(word => this.getCurrentUrl().startsWith(word));

        this.displayNavbarInContents = !navBarDisabledRoutes;
        this.isInstantGamesPage = e.url.startsWith(`/${this.instantGamesBetCategoryPath}`);
        this.isSportsPage = this.router.url.startsWith('/sports');

        if (this.tutorialStep > 5 || this.mediaService.media >= Media.lg || !this.hasWelcomeTutorial) {
          this.displayNewCustomerPopup(e.url);
        }
        this.checkDisplayDirectMessageWidget();
        this.cdRef.markForCheck();
      });

    this.loadMessages();
    if (this.mediaService) {
      this.mediaService.media$.subscribe(screenSize => {
        if (screenSize > Media.md && this.router.routerState.snapshot.url === '/myaccount') {
          this.ngZone.run(() => {
            this.router.navigate(['/myaccount/operations-history']);
          });
        } else if (screenSize <= Media.md) {
          this.verifyNavBarActive();
        }
      });
    }
    this.dialogService.registerDialog('myaccount').subscribe(open => {
      open ? this.fixBody(true) : this.releaseBody();
      this.cdRef.markForCheck();
    });

    this.dialogService.registerDialog('betslip').subscribe(open => {
      this.betSlipActive = open;
      this.betSlipActive ? this.fixBody(true) : this.releaseBody();
    });

    let route: ActivatedRouteSnapshot = this.route.snapshot;
    while (route.firstChild) {
      route = route.firstChild;
    }
    this.mainRouterEventBroadcasterService.broadcastNewActivatedRouteSnapshot(route);
    this.router.events.pipe(filter(x => x instanceof NavigationEnd)).subscribe(event => {
      let newRoute = this.route.snapshot;
      while (newRoute.firstChild) {
        newRoute = newRoute.firstChild;
      }

      this.dialogService.toggleDialog('myaccount', false);
      // Don't clear popins during navigation when the BatchPopup is open,
      // otherwise we'll lose the remaining queued popins.
      if (this.currentPopinName !== 'BatchPopupTemplateComponent') {
        this.cleanMessages();
      }
      this.mainRouterEventBroadcasterService.broadcastNewActivatedRouteSnapshot(newRoute);

      setTimeout(() => {
        this.setNavigationDepth(null, event as NavigationEnd);
        this.cdRef.markForCheck();
      });

      this.cdRef.markForCheck();
    });

    this.messageService.message$.subscribe(msg => {
      const factory = this.resolver.resolveComponentFactory(PopinComponent);
      if (factory !== undefined) {
        const compRef = this.container.createComponent(factory);
        compRef.instance.message = msg.msg;
        this.messageCloseSubscription = compRef.instance.close.subscribe(val => {
          this.cleanMessages();
          msg.onclosed(val);
        });
        this.cdRef.markForCheck();
      }

      this.fixBody();
    });

    this.messageService.component$.subscribe(component => {
      const factory = this.resolver.resolveComponentFactory(PopinComponent);

      this.cleanMessages();
      if (factory !== undefined) {
        this.currentPopinName = component.component?.name;
        const compRef = this.container.createComponent(factory);
        compRef.instance.component = component;
        compRef.instance.options = component.options;
        this.messageCloseSubscription = compRef.instance.close.subscribe(val => {
          this.cleanMessages(!!val?.disableReleaseBody);
          component.onclosed(val);
        });
      }

      this.fixBody();
      this.cdRef.detectChanges();
    });

    if (!this.isKiosk) {
      this.broadcastingService
        .register('display-gcu-popin')
        .pipe(takeUntil(this.destroy$))
        .subscribe(_ => {
          this.messageService
            .sendComponentMessage(AcceptGcuComponent, undefined, { queue: true, zIndex: 14 })
            .closed.subscribe(result => {
              this.broadcastingService.broadcast('display-gcu-message-error', result === undefined ? true : !result);
            });
        });

      this.broadcastingService
        .register('display-require-fullscreen')
        .pipe(takeUntil(this.destroy$))
        .subscribe(value => {
          this.displayMessages = !value;
        });
    }

    if (isPlatformBrowser(this.platformId)) {
      if (this.tutorialStep > 5 || this.mediaService.media >= Media.lg || !this.hasWelcomeTutorial) {
        this.startPeriodicMessagesRefresh();
        this.displayNewCustomerPopup();
      }

      this.authService.status$.pipe(takeUntil(this.destroy$)).subscribe(status => {
        if (status === 'connected') {
          this.authService.me$.pipe(take(1)).subscribe(me => {
            this.me = me;

            if (
              (this.hasWelcomeTutorial && this.tutorialStep === 0 && this.mediaService.media >= Media.lg) ||
              this.tutorialStep > 5 ||
              !this.hasWelcomeTutorial
            ) {
              this.batchPopupsService.displayBatchPopups();
            }
            if (this.operatorConfiguration.onlineConfiguration?.zendeskEnabled) {
              if (me) {
                this.initZendesk(me);
              }
            }

            if (!me) {
              return;
            }
            this.completeMyBetService.handleLogin(me.id);
            this.checkDisplayDirectMessageWidget();

            if (this.shouldDisplayInitialFreeBetsPopup(me)) {
              this.messageService.sendComponentMessage(
                InitialFreebetComponent,
                {},
                {
                  displayClose: false,
                  canBeDismissed: false,
                  className: 'transparent',
                  queue: true
                }
              );
            }
          });
        } else {
          if (this.operatorConfiguration.onlineConfiguration?.zendeskEnabled && this.me) {
            this.cleanZendesk();
          }
          this.betSlipService.handleLogout();
          this.checkDisplayDirectMessageWidget();
          this.me = undefined;
        }
      });
    }

    this.route.queryParams.pipe(takeUntil(this.destroy$)).subscribe(params => {
      const betCode = <string>params['betcode'];
      if (betCode && betCode.length) {
        if (!this.isSportsPage) {
          this.router.navigate(['/sport'], { queryParamsHandling: 'preserve' });
        }
        this.betSlipBetLinesService.rehydrateFromBetCode(betCode).pipe(take(1)).subscribe();
      }

      const sessionId = <string>params['session'];
      if (sessionId) {
        this.authService.loginWithSessionId(sessionId).pipe(take(1)).subscribe();
      }
    });

    this.broadcastingService.register<OpenCloseState>(ApplicationEvent.OverlayStateChange).subscribe(event => {
      if (event === 'open') {
        this.fixBody();
      } else if (!this.showPrivacyConsent) {
        this.releaseBody();
      }
      this.cdRef.markForCheck();
    });

    this.broadcastingService
      .register<{ event: Match | EventWithEventBetType<Match>; eventBetType: EventBetType }>(
        ApplicationEvent.BetSelected
      )
      .subscribe(obj => {
        if (
          (obj.eventBetType.betTypeId === 10001 ||
            obj.eventBetType.betTypeId === 20001 ||
            obj.eventBetType.betTypeId === 10002 ||
            obj.eventBetType.betTypeId === 20002) &&
          obj.eventBetType.eventBetTypeItems?.length === 3
        ) {
          let homeTeamOdds = '';
          let drawOdds = '';
          let awayTeamOdds = '';

          if (
            (obj.eventBetType.betTypeId === 10001 || obj.eventBetType.betTypeId === 20001) &&
            obj.eventBetType.eventBetTypeItems?.length
          ) {
            const threeWaysEventBetTypeItems = obj.eventBetType.eventBetTypeItems;

            if (threeWaysEventBetTypeItems[0].active && threeWaysEventBetTypeItems[0].bettingAllowed) {
              homeTeamOdds = threeWaysEventBetTypeItems[0].odds.toString();
            }

            if (threeWaysEventBetTypeItems[1].active && threeWaysEventBetTypeItems[1].bettingAllowed) {
              drawOdds = threeWaysEventBetTypeItems[1].odds.toString();
            }

            if (threeWaysEventBetTypeItems[2].active && threeWaysEventBetTypeItems[2].bettingAllowed) {
              awayTeamOdds = threeWaysEventBetTypeItems[2].odds.toString();
            }
          } else if (
            (obj.eventBetType.betTypeId === 10002 || obj.eventBetType.betTypeId === 20002) &&
            obj.eventBetType.eventBetTypeItems?.length
          ) {
            const twoWaysEventBetTypeItems = obj.eventBetType.eventBetTypeItems;

            if (twoWaysEventBetTypeItems[0].active && twoWaysEventBetTypeItems[0].bettingAllowed) {
              homeTeamOdds = twoWaysEventBetTypeItems[0].odds.toString();
            }

            if (twoWaysEventBetTypeItems[1].active && twoWaysEventBetTypeItems[1].bettingAllowed) {
              awayTeamOdds = twoWaysEventBetTypeItems[1].odds.toString();
            }
          }

          this.telemetryService.trackEvent('add_event_to_betslip', {
            matchId: obj.event.id,
            homeTeamName: obj.event.homeTeamName,
            awayTeamName: obj.event.awayTeamName,
            expectedStart: obj.event.expectedStart.toISOString(),
            tournament: obj.event.categories?.length ? obj.event.categories[0] : '',
            sport: getNameForEntryPoint(obj.event.entryPointId),
            homeTeamOdds: homeTeamOdds,
            drawOdds: drawOdds,
            awayTeamOdds: awayTeamOdds,
            language: this.i18nService.currentLanguageCode
          });
        }
      });

    this.navBarService.clickOnMyBets.pipe(takeUntil(this.destroy$)).subscribe(open => {
      this.showNavBar = open;
      this.cdRef.markForCheck();
    });

    this.mobileNavService.burgerMenu.pipe(takeUntil(this.destroy$)).subscribe(open => {
      this.clickOnBurger(open);
    });

    this.betSlipService.$amounts.pipe(takeUntil(this.destroy$)).subscribe(x => {
      this.amounts = x;
      this.cdRef.markForCheck();
    });

    this.betSlipService.setNotifyOnBetSystemTypeChange(
      this.operatorConfiguration?.onlineConfiguration?.betSystemTypeChangeNotification
    );

    this.completeMyBetService.completeMyBetInfo$
      .pipe(takeUntil(this.destroy$))
      .subscribe((completeMyBetInfo: CompleteMyBetInfo) => {
        this.completeMyBetInfo = completeMyBetInfo;
        this.cdRef.markForCheck();
      });

    this.initDirectMessageListener();
    this.trackGameSessionOnNavigation();
    this.registerBetSlipCopyLastSelectionTracking();
    this.initBalanceChangeListener();
    this.setupHeaderOffsetTracking();
  }

  ngOnDestroy(): void {
    if (this.pushSubscription) {
      this.pushSubscription.unsubscribe();
    }
    this.pushService.subscribeToEvents([]);
    this.pushService.subscribeToOdds([], []);
  }

  // HostListeners
  @HostListener('document:click', ['$event.target'])
  public onClick(): void {
    this.pressBack = false;
    this.navigateCounter = 0;
  }

  @HostListener('window:back', ['$event'])
  clickOnBackBrowser(): void {
    if (this.isBackAction) {
      return;
    }

    this.previousRoute = this.currentRoute;
    this.currentRoute = this.router.url;
    this.isBrowserAction = true;

    this.storedNavigationDepth--;
  }

  @HostListener('window:forward', ['$event'])
  clickOnForwardBrowser(): void {
    if (this.isBackAction) {
      return;
    }

    this.isBrowserAction = true;
    this.storedNavigationDepth++;
  }

  private get currentRoute(): string {
    return sessionStorage.getItem('current_route') ?? '';
  }

  private set currentRoute(value: string) {
    sessionStorage.setItem('current_route', value);
  }

  private get previousRoute(): string {
    return sessionStorage.getItem('previous_route') ?? '';
  }

  private set previousRoute(value: string) {
    sessionStorage.setItem('previous_route', value);
  }

  private get storedNavigationDepth(): number {
    return Number.parseInt(sessionStorage.getItem('navigation_depth') ?? '0', 10);
  }

  private set storedNavigationDepth(value: number) {
    sessionStorage.setItem('navigation_depth', String(value));
  }

  private startPeriodicMessagesRefresh(): void {
    this.applicationStateService.isReady$.subscribe(_ => {
      interval(300000)
        .pipe(takeUntil(this.destroy$))
        .subscribe(_ => {
          this.loadMessages();
        });
    });
  }

  displayNewCustomerPopup(routerUrl: string = this.router.url): void {
    if (!this.isKiosk) {
      this.displayNewCustomerPopupSubscription?.unsubscribe();
      const location: CustomerPopupLocation = this.getCustomerPopupLocation(routerUrl);
      if (location) {
        this.displayNewCustomerPopupSubscription = this.applicationStateService.isReady$.subscribe(_ => {
          this.customerPopupService.displayPopup(location);
        });
      }
    }
  }

  private verifyNavBarActive(): void {
    this.navBarService.navBarActive$.pipe(takeUntil(this.destroy$)).subscribe(navBarActive => {
      this.showNavBar = navBarActive;
      this.cdRef.markForCheck();
    });
  }

  verifyPrivacyConsent(): void {
    this.privacyService.privacyConfiguration$.pipe(takeUntil(this.destroy$)).subscribe(privacyConfiguration => {
      this.showPrivacyConsent = this.customerOperatorConfiguration?.privacyConfiguration && !privacyConfiguration;

      if (this.showPrivacyConsent) {
        this.fixBody();
      } else {
        this.releaseBody();
      }

      this.telemetryService.trackEvent('privacy_consent', { showPrivacyConsent: this.showPrivacyConsent });
    });
  }

  private loadMessages(): void {
    if (this.loadMarqueeMessagesSubscription) {
      this.loadMarqueeMessagesSubscription.unsubscribe();
    }

    this.loadMarqueeMessagesSubscription = this.messagesService
      .getMessages()
      .pipe(takeUntil(this.destroy$))
      .subscribe(messages => {
        this.messages?.splice(0, this.messages.length);
        this.messages = messages;
        this.cdRef.markForCheck();
      });
  }

  private cleanMessages(disableReleaseBody: boolean = false): void {
    this.container.clear();
    if (!disableReleaseBody) {
      this.releaseBody();
    }

    this.currentPopinName = undefined;
    if (this.messageCloseSubscription) {
      this.messageCloseSubscription.unsubscribe();
    }
  }

  fixBody(onlyInXs = false): void {
    // iOS lock le scroll via `position: fixed` sur le body (cf. styles.scss @supports),
    // ce qui perd la position de scroll. On la sauvegarde pour la restaurer au release.
    if (!this.isBodyFixed) {
      this.savedScrollY = this.document.defaultView?.scrollY ?? 0;
      this.document.body.style.top = `-${this.savedScrollY}px`;
      this.isBodyFixed = true;
    }
    onlyInXs
      ? this.document.documentElement.classList.add('hidden-in-xs')
      : this.document.documentElement.classList.add('hidden');
  }

  private releaseBody(): void {
    this.document.documentElement.classList.remove('hidden-in-xs', 'hidden');
    if (this.isBodyFixed) {
      this.document.body.style.top = '';
      this.document.defaultView?.scrollTo(0, this.savedScrollY);
      this.isBodyFixed = false;
    }
  }

  onActivate(component: IContainer): void {
    if (this.pushSubscription && !this.pushSubscription.closed) {
      this.pushSubscription.unsubscribe();
    }
    if (component.getSubscription) {
      this.pushSubscription = component
        .getSubscription()
        .pipe(takeUntil(this.destroy$))
        .subscribe(subs => {
          this.pushService.subscribeToEvents(subs.eventSubscriptions);
          this.pushService.subscribeToOdds(subs.betTypeSubscriptions, subs.betTypeByEventSubscriptions || []);
        });
    } else {
      this.pushService.subscribeToEvents([]);
      this.pushService.subscribeToOdds([], []);
    }
  }

  private setDefaultBetCategoryAnchor(betCategory: BetCategoryType): void {
    switch (betCategory) {
      case BetCategoryType.HorseRacingMutualInternationalPool: {
        this.anchor = this.getHorseRacingMenuAnchor();
        break;
      }
      case BetCategoryType.HorseRacingMutualOperatorPool: {
        this.anchor = this.getHorseRacingMenuAnchor();
        break;
      }
      case BetCategoryType.VirtualFixedOdds: {
        this.anchor = 'virtual-nav-links';
        break;
      }
      case BetCategoryType.DrawGame: {
        this.anchor = 'draw-games-nav-links';
        break;
      }
      case BetCategoryType.SportsFixedOdds: {
        this.anchor = 'home-menu-links';
        break;
      }
      case BetCategoryType.InstantGame: {
        this.anchor = 'instant-games-nav-links';
      }
      case BetCategoryType.SportsPool: {
        this.anchor = 'sports-pool-nav-links';
      }
      default: {
        this.anchor = this.hasHomePageCasino ? 'instant-games-nav-links' : 'home-menu-links';
        break;
      }
    }
  }

  private setAnchor(url: string): void {
    if (!url.startsWith('/myaccount')) {
      if (url.startsWith('/virtual')) {
        this.anchor = 'virtual-nav-links';
      } else if (url.startsWith('/horseracing')) {
        this.anchor = this.getHorseRacingMenuAnchor();
      } else if (url.startsWith('/draw-games')) {
        this.anchor = 'draw-games-nav-links';
      } else if (url.startsWith('/sports-pool')) {
        this.anchor = 'sports-pool-nav-links';
      } else if (url.startsWith('/sports')) {
        this.anchor = 'home-menu-links';
      } else if (url.startsWith(`/${this.instantGamesBetCategoryPath}`)) {
        this.anchor = 'instant-games-nav-links';
      } else {
        this.setDefaultBetCategoryAnchor(this.customerOperatorConfiguration.features.defaultBetCategory);
      }
    } else if (this.anchor === undefined) {
      this.setDefaultBetCategoryAnchor(this.customerOperatorConfiguration.features.defaultBetCategory);
    }
  }

  private getHorseRacingMenuAnchor(): string {
    if (this.operatorConfiguration.horseRacesResultsConfiguration?.horseRacesResults.customerOnline) {
      return 'horseracing-nav-with-results-links';
    } else {
      return 'horseracing-menu-links';
    }
  }

  private setNavigationDepth(url?: string, event?: NavigationEnd): void {
    this.navigateCounter++;
    this.previousRoute = this.currentRoute;
    const navigationDepth: number = this.storedNavigationDepth;

    if (url === undefined) {
      this.currentRoute = this.router.url;
    } else if (event?.url === '/' && event.urlAfterRedirects && event.urlAfterRedirects !== '/') {
      this.currentRoute = event.urlAfterRedirects;
    } else {
      this.currentRoute = this.router.url;
    }

    if (this.navigateCounter < 2) {
      if (!this.isBrowserAction) {
        if (this.currentRoute === this.previousRoute) {
          return;
        }

        this.handleBackBtnScenarios(navigationDepth);
      }
    }

    if (Number.isNaN(this.storedNavigationDepth) || this.storedNavigationDepth < 0) {
      this.storedNavigationDepth = 0;
    }

    this.navigationDepth = this.storedNavigationDepth;
    this.isBackAction = false;
    this.isBrowserAction = false;
    sessionStorage['is_back'] = 'false';
    this.cdRef.markForCheck();
  }

  private handleBackBtnScenarios(navigationDepth: number): void {
    const previousRouteUrl: string = this.previousRoute?.split('?')?.[0] ?? '';
    const currentRouteUrl: string = this.currentRoute?.split('?')?.[0] ?? '';

    const previousRouteParams: string[] = previousRouteUrl.split('/').filter(i => i);
    const currentRouteParams: string[] = currentRouteUrl.split('/').filter(i => i);

    const previousPathRoot: string = previousRouteParams[0];
    const currentPathRoot: string = currentRouteParams[0];

    // Current Route is First Page
    if (currentRouteParams.length === 1) {
      this.storedNavigationDepth = 0;
      return;
    }

    // Handle routing from promotions
    if (previousRouteUrl === '/about/promotions') {
      // Routing to content page
      if (currentPathRoot === 'about') {
        this.storedNavigationDepth = ++navigationDepth;
        return;
      }
    }

    // Handle About page redirection
    if (previousPathRoot !== 'about' && currentRouteParams.some(x => x === 'about')) {
      // In order to trigger location.back, depth must be >= 2.
      this.storedNavigationDepth = navigationDepth < 2 ? 2 : ++navigationDepth;

      return;
    }

    // Change of scope
    if (currentPathRoot !== previousPathRoot && previousPathRoot !== 'about') {
      this.storedNavigationDepth = 0;
      return;
    }

    // Handle sports tabs
    if (currentPathRoot === 'sports' && currentRouteParams.length === 1) {
      this.storedNavigationDepth = 0;
      return;
    }

    // Handle Navigation Depth reset cases
    if (currentRouteParams.length === 2) {
      const currentSubPath = currentRouteParams[1];
      // --- Sports
      if (currentPathRoot === 'sports') {
        if (currentSubPath === 'live' || !Number.isNaN(+currentSubPath)) {
          this.storedNavigationDepth = 0;
          return;
        }
      }

      // --- Horseracing
      if (currentPathRoot === 'horseracing' && (currentSubPath === 'meetings' || currentSubPath === 'results')) {
        this.storedNavigationDepth = 0;
        return;
      }

      // --- Casino
      if (currentPathRoot === this.instantGamesBetCategoryPath && currentSubPath === 'category') {
        this.storedNavigationDepth = 0;
        return;
      }

      // --- Draw Games
      if (currentPathRoot === 'draw-games' && currentSubPath === 'results') {
        this.storedNavigationDepth = 0;
        return;
      }
    }

    // Handle myAccount Depth
    if (currentPathRoot === 'myaccount') {
      this.storedNavigationDepth = currentRouteParams.length - 1;
      return;
    }

    // Handle Sports navigation specific cases
    if (currentPathRoot === 'sports') {
      if (previousRouteParams.length >= 2 && currentRouteParams.length >= 2) {
        // Handle going from event detail to event list of != sport : reset depth
        // Soccer use sports/101?eventCategory != other sports uses sports/id/eventCat
        if (previousRouteParams[1] === 'event' && !Number.isNaN(+currentRouteParams[1])) {
          this.storedNavigationDepth = 0;
          return;
        }
      }

      // In order to trigger location.back, depth must be >= 2.
      if (
        currentRouteParams.length >= 2 &&
        (currentRouteParams[1] === 'event' || (currentRouteParams[1] === 'live' && currentRouteParams[2] === 'event'))
      ) {
        this.storedNavigationDepth = 2;
        return;
      }
    }

    // Handle Virtual navigation specific cases
    if (currentPathRoot === 'virtual') {
      if (
        currentRouteParams.length >= 3 &&
        currentRouteParams[1] === 'category' &&
        !Number.isNaN(+currentRouteParams[2])
      ) {
        // FastLeague & other Games -- Handle filters skip depth
        if (currentRouteParams.length === 3) {
          this.storedNavigationDepth = 1;
          return;
        }

        // InstantLeague -- MatchDetail dissociate Header bck Button with inner btn
        if (currentRouteParams.length === 5 && !Number.isNaN(+currentRouteParams[4])) {
          this.storedNavigationDepth = 1;
          return;
        }

        // Race -- Races dissociate Header bck Button with inner btn
        if (
          currentRouteParams.length >= 5 &&
          currentRouteParams[3] === 'race' &&
          !Number.isNaN(+currentRouteParams[4])
        ) {
          this.storedNavigationDepth = 1;
          return;
        }
      }

      // InstantLeague -- Handle filters/tabs skip depth
      if (
        currentRouteParams.length >= 4 &&
        currentRouteParams[2] === 'instant-league' &&
        !Number.isNaN(+currentRouteParams[3])
      ) {
        this.storedNavigationDepth = 1;
        return;
      }
    }

    // --- Sports Pool
    if (currentPathRoot === 'sports-pool') {
      const currentSubPath: string = currentRouteParams[2];
      sessionStorage['navigation_depth'] = currentSubPath ? 2 : 0;
      return;
    }

    // Back Btn Action
    if (sessionStorage['is_back'] === 'true' || this.isBackAction) {
      this.storedNavigationDepth = navigationDepth - 1;
      return;
    }

    this.storedNavigationDepth = navigationDepth + 1;
  }

  clickOnBack(): void {
    this.isBackAction = true;
    this.isBrowserAction = false;

    const navDepth: number = this.storedNavigationDepth;
    const isMyAccount: boolean = this.router.url.startsWith('/myaccount/');

    if (isMyAccount) {
      this.navigateBackFromMyAccount(navDepth);
      return;
    }

    if (navDepth === 0) {
      this.router.navigate(['/']);
      return;
    }

    if (navDepth <= 1) {
      this.navigateBackToSection();
      return;
    }

    this.location.back();
  }

  private navigateBackFromMyAccount(navDepth: number): void {
    if (navDepth < 1) {
      this.location.back();
      return;
    }

    if (navDepth === 1) {
      this.router.navigate(['/myaccount']);
      return;
    }

    const segments: string[] = this.getCurrentRouteSegments();
    const targetPath = segments.length >= 2 ? `${segments[0]}/${segments[1]}` : '';

    this.router.navigate([`/${targetPath}`]);
  }

  private navigateBackToSection(): void {
    const segments: string[] = this.getCurrentRouteSegments();
    let targetPath: string = segments[0] ?? '';

    const isHorseRacingAbout: boolean = this.router.url.startsWith('/horseracing/about');
    const needsRedirect: boolean = targetPath === 'about' || targetPath === 'myaccount' || isHorseRacingAbout;

    if (needsRedirect) {
      const currentRoute: string = sessionStorage.getItem('current_route') ?? '';
      targetPath = this.resolveFreebetsRedirect(currentRoute);
    }

    this.router.navigate([`/${targetPath}`]);
  }

  private getCurrentRouteSegments(): string[] {
    const pathOnly: string = this.currentRoute.split('?')[0];
    return pathOnly.split('/').filter(Boolean);
  }

  private resolveFreebetsRedirect(currentRoute: string): string {
    return currentRoute.includes('freebets-rules') ? 'myaccount/freebets-coupons' : '';
  }

  clickOnBurger(isBurgerOpened: boolean): void {
    this.isBurgerOpened = isBurgerOpened;
  }

  closeBanner(displayAppBanner: boolean): void {
    this.displayAppBanner = displayAppBanner;
    this.cdRef.markForCheck();
  }

  hideDirectMessageWidget(): void {
    this.displayDirectMessageWidget = false;
  }

  navigateDirectMessageWidget(): void {
    this.isBurgerOpened = false;
    this.isBurgerClosed = true;
  }

  private shouldDisplayInitialFreeBetsPopup(me: Me): boolean {
    return (
      this.operatorConfiguration.freeBetsConfiguration.initialPopinEnabled &&
      !this.localStorage.getItem('freebet_initial:valid') &&
      (!this.operatorConfiguration.freeBetsConfiguration.initialPopinStartDate ||
        (me.profile?.registrationDate &&
          happenBefore(
            new Date(this.operatorConfiguration.freeBetsConfiguration.initialPopinStartDate),
            new Date(me.profile?.registrationDate),
            0
          )))
    );
  }

  private getCustomerPopupLocation(routerUrl: string): CustomerPopupLocation | undefined {
    if (!routerUrl) {
      return undefined;
    } else if (routerUrl.startsWith('/sports/live')) {
      return CustomerPopupLocation.Live;
    } else if (routerUrl.startsWith('/virtual')) {
      return CustomerPopupLocation.Virtual;
    } else if (routerUrl.startsWith('/draw-games')) {
      return CustomerPopupLocation.DrawGames;
    } else if (routerUrl.startsWith('/horseracing')) {
      return CustomerPopupLocation.HorseRaces;
    } else if (this.isSportsPage) {
      return CustomerPopupLocation.Sport;
    } else if (this.isInstantGamesPage) {
      return CustomerPopupLocation.InstantGames;
    }

    return undefined;
  }

  private initZendesk(me: Me): void {
    if (me?.externalTokens?.['ZendeskToken'] && this.document.querySelector('#ze-snippet') === null) {
      // Good old JavaScript using callbacks :)
      const that = this;

      this.zendeskModuleScript = document.createElement('script');
      this.zendeskModuleScript.setAttribute(
        'src',
        `https://static.zdassets.com/ekr/snippet.js?key=${this.operatorConfiguration.onlineConfiguration.zendeskWidgetKey}`
      );
      this.zendeskModuleScript.setAttribute('id', 'ze-snippet');
      this.zendeskModuleScript.setAttribute('async', 'true');
      this.zendeskModuleScript.onload = () => {
        if (!window['zE']) {
          return;
        }
        // #20835 Always hide the small luncher
        that.showOrHideZendesk(false);
        window['zE'](
          'messenger',
          'loginUser',
          function (callback) {
            callback(me.externalTokens['ZendeskToken']);
          },
          function loginCallback(error) {
            if (!(error && (error.type || error.reason || error.message))) {
              that.updateZendeskLocale();
            }
            window['zE']('messenger:on', 'close', () => {
              that.showOrHideZendesk(false);
            });
          }
        );
      };

      this.document.querySelector('head').appendChild(this.zendeskModuleScript);
    }
  }

  private showOrHideZendesk(show: boolean): void {
    if (!window['zE']) {
      return;
    }
    window['zE']('messenger', show ? 'show' : 'hide');
  }

  private cleanZendesk(): void {
    if (this.zendeskModuleScript) {
      if (window['zE']) {
        window['zE']('messenger', 'logoutUser');
        this.showOrHideZendesk(false);
      }

      this.document.querySelector('head').removeChild(this.zendeskModuleScript);
    }
  }

  private updateZendeskLocale(): void {
    if (this.zendeskModuleScript && window['zE']) {
      window['zE']('messenger:set', 'locale', this.i18nService.currentLanguageCode);
    }
  }

  private checkDisplayDirectMessageWidget(): void {
    if (!this.canShowDirectMessageWidget()) {
      this.displayDirectMessageWidget = false;
      return;
    }

    if (this.customerDirectMessageConfiguration) {
      this.displayDirectMessageWidget = this.shouldShowMessageWidget();
      return;
    }

    this.loadDirectMessageConfig();
  }

  private canShowDirectMessageWidget(): boolean {
    const directMessageConfig: DirectMessageConfiguration =
      this.customerOperatorConfiguration.directMessageConfiguration;

    const hasFloatingButton: boolean = !!directMessageConfig?.displayFloatingButton;
    const hasDirectMessageFeature: boolean = this.operatorConfiguration.operatorFeatures?.includes(
      Feature.DirectMessage
    );
    const isAuthenticated: boolean = this.authService.isAuthenticated();
    const currentUrl: string = this.getCurrentUrl();
    const isOnDirectMessagePage: boolean = currentUrl.startsWith('/myaccount/direct-message');
    return hasFloatingButton && hasDirectMessageFeature && isAuthenticated && !isOnDirectMessagePage;
  }

  private loadDirectMessageConfig(): void {
    this.directMessageService
      .getDirectMessageConfig()
      .pipe(takeUntil(this.destroy$))
      .subscribe(
        (config: CustomerDirectMessageConfiguration) => {
          this.newDirectMessagesCount = config.unreadDirectMessageCount;
          this.canViewDirectMessage = config.canViewDirectMessages;
          this.displayDirectMessageWidget = this.shouldShowMessageWidget(true);
          this.customerDirectMessageConfiguration = config;
          this.cdRef.markForCheck();
        },
        () => {
          this.newDirectMessagesCount = 0;
          this.canViewDirectMessage = false;
        }
      );
  }

  private shouldShowMessageWidget(isInit: boolean = false): boolean {
    if (isInit && this.shouldReOpenOnNewMessage()) {
      return true;
    }

    return this.resolveVisibilityFromRoute();
  }

  private shouldReOpenOnNewMessage(): boolean {
    const reOpenOnNewMessage: boolean =
      this.operatorConfiguration.directMessageConfiguration?.reOpenChatBubbleIfNewMessage;
    return reOpenOnNewMessage && this.newDirectMessagesCount > 0;
  }

  private resolveVisibilityFromRoute(): boolean {
    const currentUrl: string = this.getCurrentUrl();

    if (currentUrl.startsWith('/myaccount/direct-message')) {
      return false;
    }

    return this.resolveVisibilityFromLocalStorage();
  }

  private getCurrentUrl(): string {
    return this.route.snapshot['_routerState'].url.split('?')[0];
  }

  private resolveVisibilityFromLocalStorage(): boolean {
    const widgetState: DirectMessageWidgetState = this.localStorage.getItem(this.LOCAL_STORAGE_KEY_DM);
    return !!widgetState && widgetState !== DirectMessageWidgetState.Close;
  }

  private initDirectMessageListener(): void {
    this.pushService.directMessageIncrementChanged$
      .pipe(takeUntil(this.destroy$))
      .subscribe((newMessagesCount: number) => {
        this.handleNewDirectMessages(newMessagesCount);
        this.cdRef.markForCheck();
      });

    this.broadcastingService
      .register('open-direct-message-window')
      .pipe(takeUntil(this.destroy$))
      .subscribe(_ => {
        this.displayDirectMessageWidget = true;
      });
  }

  private handleNewDirectMessages(newMessagesCount: number): void {
    if (newMessagesCount > 0) {
      this.handleIncomingMessages(newMessagesCount);
    } else {
      this.handleNoNewMessages(newMessagesCount);
    }
  }

  private handleIncomingMessages(count: number): void {
    this.newDirectMessagesCount += count;

    const shouldReOpen: boolean = this.operatorConfiguration.directMessageConfiguration?.reOpenChatBubbleIfNewMessage;
    if (shouldReOpen) {
      this.displayDirectMessageWidget = true;
      this.localStorage.setItem(this.LOCAL_STORAGE_KEY_DM, DirectMessageWidgetState.Reduce);
    }
  }

  private handleNoNewMessages(count: number): void {
    this.newDirectMessagesCount = count;
    this.displayDirectMessageWidget = this.shouldShowMessageWidget();
  }

  private trackGameSessionOnNavigation(): void {
    if (!this.shouldCloseGameSessionOnNavigation()) {
      return;
    }

    const navigationEnd$ = this.router.events.pipe(
      filter((event): event is NavigationEnd => event instanceof NavigationEnd),
      map(event => ({ url: event.url, isFirstNavigation: false }))
    );

    const authChange$ = this.authService.status$.pipe(map(() => ({ url: this.router.url, isFirstNavigation: false })));

    merge(navigationEnd$, authChange$)
      .pipe(
        startWith({ url: this.router.url, isFirstNavigation: true }),
        pairwise(),
        withLatestFrom(this.authService.status$),
        filter(
          ([[previous, current], status]) => status === 'connected' && this.shouldCloseGameSession(previous, current)
        ),
        switchMap(() => this.gameSessionService.closeCurrentGameSession().pipe(catchError(() => EMPTY))),
        takeUntil(this.destroy$)
      )
      .subscribe();
  }

  private shouldCloseGameSessionOnNavigation(): boolean {
    return (
      this.operatorConfiguration.operatorFeatures.includes(Feature.GameSession) &&
      this.customerOperatorConfiguration.gameSessionConfiguration.closeSessionOnCustomerNavigation
    );
  }

  private shouldCloseGameSession(
    previous: { url: string; isFirstNavigation: boolean },
    current: { url: string; isFirstNavigation: boolean }
  ): boolean {
    const isInitialPageNotInstantGame: boolean = previous.isFirstNavigation && !this.isInstantGameUrl(previous.url);

    const isLeavingInstantGame: boolean =
      !previous.isFirstNavigation && this.isInstantGameUrl(previous.url) && !this.isInstantGameUrl(current.url);

    return isInitialPageNotInstantGame || isLeavingInstantGame;
  }

  private isInstantGameUrl(url: string): boolean {
    return url.startsWith(`/${this.instantGamesBetCategoryPath}`);
  }

  private registerBetSlipCopyLastSelectionTracking(): void {
    this.broadcastingService
      .register('bet_slip_copy_last_selection')
      .pipe(takeUntil(this.destroy$))
      .subscribe(() => {
        this.telemetryService.trackEvent('bet_slip_copy_last_selection');
      });
  }

  private initBalanceChangeListener(): void {
    this.pushService.balanceChanged$
      .pipe(
        takeUntil(this.destroy$),
        switchMap(newBalance => {
          if (newBalance?.balance) {
            return this.authService.setBalance(newBalance.balance);
          }
          return EMPTY;
        })
      )
      .subscribe();
  }

  private setupHeaderOffsetTracking(): void {
    const view: (Window & typeof globalThis) | null = this.document.defaultView;
    if (!this.operatorConfiguration.smarticoConfiguration?.enabled || !isPlatformBrowser(this.platformId) || !view) {
      return;
    }

    const layoutResize$: Observable<void> = new Observable<void>(subscriber => {
      const resizeObserver: ResizeObserver = new ResizeObserver(() => subscriber.next());
      resizeObserver.observe(this.elementRef.nativeElement);
      return () => resizeObserver.disconnect();
    });

    this.ngZone.runOutsideAngular(() => {
      merge(
        fromEvent(view, 'scroll', { capture: true }),
        fromEvent(view, 'resize'),
        fromEvent(view, 'orientationchange'),
        layoutResize$
      )
        .pipe(
          auditTime(0, animationFrameScheduler),
          map(() => this.headerElement?.nativeElement?.getBoundingClientRect()?.top ?? 0),
          distinctUntilChanged(),
          takeUntil(this.destroy$)
        )
        .subscribe(headerTopOffset =>
          this.document.documentElement.style.setProperty(
            '--header-top-offset',
            headerTopOffset <= 0 ? '0px' : `${headerTopOffset}px`
          )
        );
    });
  }
}
