import { Injectable } from '@angular/core';
import { CustomerService } from '@honoregaming/customer-core';
import { PasswordValidity } from '../models/password-validity.model';

@Injectable()
export class PasswordService {
  requiredLength: number;
  requireLowercase: boolean;
  requireUppercase: boolean;
  requireEmail: boolean;
  requireDigit: boolean;
  requireNonLetterOrDigit: boolean;
  preventConsecutiveSequence: boolean;
  preventSameCharacterRepeated: boolean;
  preventEqualToLogin: boolean;

  constructor(private readonly customerService: CustomerService) {
    this.customerService.getSecurityPolicy().subscribe(x => {
      this.requireLowercase = x.passwordPolicyRequirements.requireLowercase;
      this.requireUppercase = x.passwordPolicyRequirements.requireUppercase;
      this.requireDigit = x.passwordPolicyRequirements.requireDigit;
      this.requiredLength = x.passwordPolicyRequirements.requiredLength;
      this.requireNonLetterOrDigit = x.passwordPolicyRequirements.requireNonLetterOrDigit;
      this.preventConsecutiveSequence = x.passwordPolicyRequirements.preventConsecutiveSequence;
      this.preventSameCharacterRepeated = x.passwordPolicyRequirements.preventSameCharacterRepeated;
      this.preventEqualToLogin = x.passwordPolicyRequirements.preventEqualToLogin;
      this.requiredLength = x.passwordPolicyRequirements.requiredLength;
    });
  }

  checkPassword(password: string, login: string): PasswordValidity {
    const hasDigitRegex = /\d+/;
    const hasLowerCharRegex = /[a-z]+/;
    const hasUpperCharRegex = /[A-Z]+/;
    const hasNonLetterOrDigitRegex = /[!@#$%^&*()_+=\[{\]};:<>|./?,-]/;
    const alphabet = 'abcdefghijklmnopqrstuvwxyz';
    const reverseAlphabet = 'zyxwvutsrqponmlkjihgfedcba';
    const numbers = '0123456789';
    const reverseNumbers = '9876543210';
    const hasSameCharRepeatedRegex = new RegExp(`(.)\\1{${this.requiredLength - 1},}`);

    if (!password || password.length === 0) {
      return {
        hasConsecutiveLetterSequence: false,
        hasConsecutiveNumberSequence: false,
        hasDigital: false,
        hasLowerCharacter: false,
        hasNonLetterOrDigit: false,
        hasPasswordLength: false,
        hasSameCharacterRepeated: false,
        hasUppercharacter: false,
        isEqualToLogin: false
      };
    }

    const loweredPassword = password.toLocaleLowerCase();

    const hasNonLetterOrDigit = hasNonLetterOrDigitRegex.test(password);
    const hasDigital = hasDigitRegex.test(password);
    const hasLowerCharacter = hasLowerCharRegex.test(password);
    const hasUppercharacter = hasUpperCharRegex.test(password);
    const hasConsecutiveLetterSequence =
      loweredPassword.length &&
      (this.passwordContainsSequence(loweredPassword, alphabet) ||
        this.passwordContainsSequence(loweredPassword, reverseAlphabet));
    const hasConsecutiveNumberSequence =
      loweredPassword.length &&
      (this.passwordContainsSequence(loweredPassword, numbers) ||
        this.passwordContainsSequence(loweredPassword, reverseNumbers));
    const hasSameCharacterRepeated = hasSameCharRepeatedRegex.test(loweredPassword);
    const isEqualToLogin = password.includes(login);
    const hasPasswordLength = password.length >= this.requiredLength;

    return {
      hasConsecutiveLetterSequence,
      hasConsecutiveNumberSequence,
      hasDigital,
      hasLowerCharacter,
      hasNonLetterOrDigit,
      hasPasswordLength,
      hasSameCharacterRepeated,
      hasUppercharacter,
      isEqualToLogin
    };
  }

  private passwordContainsSequence(password: string, sequence: string): boolean {
    const sequences = this.getAllPossibleSequences(sequence);

    return sequences
      .map(s => {
        return password.includes(s);
      })
      .some(x => x);
  }

  private getAllPossibleSequences(sequence: string): string[] {
    if (sequence.length < this.requiredLength) {
      return [sequence];
    }

    const array: string[] = [];

    for (let i = 0; i + this.requiredLength < sequence.length; i++) {
      array.push(sequence.substring(i, i + this.requiredLength));
    }

    return array;
  }
}
