import { isPlatformServer } from '@angular/common';
import { HttpClient } from '@angular/common/http';
import { Inject, Injectable, PLATFORM_ID } from '@angular/core';
import { globalConfiguration, OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';
import { MessageService } from '@honoregaming/ui';
import { CustomerBatchPopup } from '@honoregaming/types';
import { LocalStorageService } from '@honoregaming/core';
import { BatchPopupTemplateComponent } from '../templates/batch-popup-template/batch-popup-template.component';
import { map } from 'rxjs/operators';

@Injectable({ providedIn: 'root' })
export class BatchPopupsService {
  private readonly batchPopupsStorageKey = 'batch-popup:seen-map';

  constructor(
    private http: HttpClient,
    @Inject(PLATFORM_ID) private plateform: Object,
    private messageService: MessageService,
    private localStorage: LocalStorageService,
    @Inject(operatorConfigurationToken) private operatorConfiguration: OperatorConfiguration
  ) {}

  public displayBatchPopups() {
    if (isPlatformServer(this.plateform) || this.operatorConfiguration.smarticoConfiguration?.popupsEnabled) {
      return;
    }

    this.http
      .get<CustomerBatchPopup[]>(`${globalConfiguration.apiBaseUrl}batch-popups`)
      .pipe(map(popups => popups?.filter(p => !this.loadSeenIds().includes(p.id)) ?? []))
      .subscribe({
        next: popups => {
          if (!popups.length) {
            return;
          }

          const hasArrows = popups.length > 1;
          let firstPopupShown = false;
          const cycle = (index: number) => {
            const popup = popups[index];
            const ref = this.messageService.sendComponentMessage(
              BatchPopupTemplateComponent,
              { popup, hasArrows, firstPopupShown },
              { bare: true, queue: true }
            );

            ref.closed.subscribe((value: 'next' | 'prev' | boolean) => {
              firstPopupShown = true;
              if (value === 'next' || value === 'prev') {
                const indexes = {
                  next: (index + 1) % popups.length,
                  prev: (index - 1 + popups.length) % popups.length
                };

                if (!this.loadSeenIds().includes(popup.id)) {
                  this.readBatchPopup(popup.id, null).subscribe({ error: () => {} });
                }
                this.markSeen(popup);
                cycle(indexes[value]);
                return;
              }
              if (!this.loadSeenIds().includes(popup.id)) {
                this.readBatchPopup(popup.id, null).subscribe({ error: () => {} });
              }
              this.markSeen(popup);
            });
          };

          cycle(0);
        },
        error: () => {}
      });
  }

  public readBatchPopup(popupId: number, actionClicked: boolean | null = null) {
    return this.http.post(`${globalConfiguration.apiBaseUrl}batch-popups/${popupId}/read`, { actionClicked });
  }

  public markSeen(popup: CustomerBatchPopup) {
    const end = new Date(popup.endDate).getTime();

    if (isNaN(end)) {
      return;
    }

    const map = this.loadSeenMap();

    map[popup.id] = end;
    this.saveSeenMap(map);
  }

  private loadSeenIds() {
    const now = Date.now();
    const map = this.loadSeenMap();
    const cleaned: Record<number, number> = {};
    const ids: number[] = [];

    for (const [idStr, end] of Object.entries(map)) {
      const id = Number(idStr);

      if (typeof end !== 'number') {
        continue;
      }
      if (end > now) {
        ids.push(id);
        cleaned[id] = end;
      }
    }
    this.saveSeenMap(cleaned);
    return ids;
  }

  private loadSeenMap() {
    try {
      const raw = this.localStorage.getItem(this.batchPopupsStorageKey);

      if (!raw) {
        return {};
      }
      const parsed = JSON.parse(raw);

      if (typeof parsed !== 'object' || parsed === null) {
        return {};
      }

      return parsed as Record<number, number>;
    } catch {
      this.localStorage.removeItem(this.batchPopupsStorageKey);
      return {};
    }
  }

  private saveSeenMap(map: Record<number, number>) {
    this.localStorage.setItem(this.batchPopupsStorageKey, JSON.stringify(map));
  }
}
