import { DOCUMENT, isPlatformBrowser } from '@angular/common';
import { Inject, Injectable, PLATFORM_ID } from '@angular/core';
import { CustomerOperatorConfiguration, customerOperatorConfigurationToken } from '../../models';
import { ITelemetryService } from './telemetry-service.model';

@Injectable()
export class GoogleTagManagerTelemetryService implements ITelemetryService {
  isBrowser: boolean = isPlatformBrowser(this.platformId);

  private readonly headElementIdentifier: string = 'google-tag-manager-head';
  private readonly bodyElementIdentifier: string = 'google-tag-manager-body';

  constructor(
    @Inject(customerOperatorConfigurationToken) private readonly operatorConfig: CustomerOperatorConfiguration,
    @Inject(DOCUMENT) private readonly document: Document,
    @Inject(PLATFORM_ID) private readonly platformId: Object
  ) {
    this.initialize();
  }

  initialize(): void {
    if (this.isLoaded()) {
      console.warn(
        'Tried to initialize a Google Tag Manager instance while another is already active. Please call `remove()` before initializing a new instance.'
      );
      return;
    }

    if (this.operatorConfig.telemetryConfiguration.googleTagManager?.enabled) {
      this.addScript(this.operatorConfig.telemetryConfiguration.googleTagManager.trackingId);
    }
  }

  trackPageView(_name: string, _path: string): void {}

  trackEvent(_: string, __: any): void {}

  private addScript(clientId: string): void {
    if (!isPlatformBrowser(this.platformId)) {
      return;
    }

    const headElement: HTMLScriptElement = this.document.createElement('script');
    headElement.id = this.headElementIdentifier;
    headElement.type = 'text/javascript';
    headElement.innerHTML = `
    (function(w,d,s,l,i){w[l]=w[l]||[];w[l].push({'gtm.start':
    new Date().getTime(),event:'gtm.js'});var f=d.getElementsByTagName(s)[0],
    j=d.createElement(s),dl=l!='dataLayer'?'&l='+l:'';j.async=true;j.src=
    'https://www.googletagmanager.com/gtm.js?id='+i+dl;f.parentNode.insertBefore(j,f);
    })(window,document,'script','dataLayer', '${clientId}');`;
    this.document.head.appendChild(headElement);

    const iframeElement: HTMLIFrameElement = this.document.createElement('iframe');
    iframeElement.src = `https://www.googletagmanager.com/ns.html?id=${clientId}`;
    iframeElement.height = '0';
    iframeElement.width = '0';
    iframeElement.style.display = 'none';
    iframeElement.style.visibility = 'hidden';
    const bodyElement: HTMLElement = this.document.createElement('noscript');
    bodyElement.id = this.bodyElementIdentifier;
    bodyElement.appendChild(iframeElement);
    this.document.body.appendChild(bodyElement);
  }

  private isLoaded(): boolean {
    return (
      isPlatformBrowser(this.platformId) &&
      !!this.document.getElementById(this.headElementIdentifier) &&
      !!this.document.getElementById(this.bodyElementIdentifier)
    );
  }
}
