import { isPlatformBrowser } from '@angular/common';
import { NavigationEnd, Router } from '@angular/router';
import {
  Component,
  OnInit,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Inject,
  PLATFORM_ID,
  Input,
  OnChanges,
  SimpleChanges
} from '@angular/core';
import { filter, finalize, takeUntil, map, startWith } from 'rxjs/operators';
import { combineLatest, Observable, of } from 'rxjs';
import {
  operatorConfigurationToken,
  OperatorConfiguration,
  OperatorContact,
  globalConfiguration,
  ContactAction,
  Feature
} from '@honoregaming/configuration';
import {
  BetCategoryConfigurationService,
  BroadcastingService,
  DestroySubject,
  kioskToken,
  LocalStorageService,
  natifToken
} from '@honoregaming/core';
import {
  AnchorType,
  CustomerOperatorConfiguration,
  customerOperatorConfigurationToken,
  Me
} from '@honoregaming/customer-core';
import { BetCategoryType, Template } from '@honoregaming/types';
import { ITemplateService, templateServiceToken } from '@honoregaming/templating';
import { CharityService } from 'projects/customer/hg-about/src/lib/services/charity.service';
import { DirectMessageWidgetState } from 'projects/customer/hg-direct-message/src/lib/enums/direct-message-widget-view.enum';
import { DirectMessageTrackingService } from 'projects/customer/hg-direct-message/src/lib/services/direct-message-tracking.service';

@Component({
  selector: 'hg-footer',
  templateUrl: './footer.component.html',
  styleUrls: ['./footer.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class FooterComponent extends DestroySubject implements OnInit, OnChanges {
  @Input() me?: Me;

  AnchorType = AnchorType;
  BetCategoryType = BetCategoryType;
  Feature = Feature;

  version: string = globalConfiguration.appVersion;
  hasPromotions: boolean = this.customerOperatorConfiguration.contentsConfiguration?.hasPromotions;
  pointOfSalesCategories: number[] = this.customerOperatorConfiguration?.resourcesConfiguration?.pointOfSalesCategories;
  instantGamesBetCategoryPath: string = this.betCategoryConfigurationService.getInstantGamesBetCategoryPath();
  zendeskEnabled: boolean = this.operatorConfig.onlineConfiguration?.zendeskEnabled;
  directMessageEnabled: boolean = this.operatorConfig.operatorFeatures?.includes(Feature.DirectMessage);
  yeastarEnabled: boolean =
    this.operatorConfig.onlineConfiguration?.yeastarEnabled && !!this.operatorConfig.onlineConfiguration.yeastarUrl;

  hasAnchor: boolean = false;
  anchor?: string;
  activeDropdown: number | null = 0;
  copyright: string = '';
  displayforAndroid: boolean = false;
  displayforIos: boolean = false;
  showCharity: boolean = false;
  showCopyright: boolean = false;
  displayLanguageSelector: boolean = false;

  generalItems: { link: string; translationKey: string; order?: number; imageUrl?: string; cssClassName?: string }[];
  helpItems?: {
    link?: string;
    translationKey?: string;
    order?: number;
    imageUrl?: string;
    useFont?: string;
  }[] = [];
  helpContacts: OperatorContact[] = [];
  socialContacts: OperatorContact[] = [];
  templates: Template[] = [];

  displayBannerFooter$: Observable<boolean> = of(false);

  private readonly socialContactsNames: string[] = [
    'facebook',
    'instagram',
    'twitter',
    'youtube',
    'telegram',
    'tiktok',
    'linkedin',
    'x',
    'thread'
  ];

  readonly LOCAL_STORAGE_KEY_DM: string = 'direct_message:widget:state';

  constructor(
    private readonly cdRef: ChangeDetectorRef,
    private readonly charityService: CharityService,
    private readonly betCategoryConfigurationService: BetCategoryConfigurationService,
    private readonly router: Router,
    private readonly broadcastingService: BroadcastingService,
    private readonly localStorage: LocalStorageService,
    private readonly directMessageTrackingService: DirectMessageTrackingService,
    @Inject(templateServiceToken) private readonly templateService: ITemplateService,
    @Inject(operatorConfigurationToken) private readonly operatorConfig: OperatorConfiguration,
    @Inject(customerOperatorConfigurationToken)
    private readonly customerOperatorConfiguration: CustomerOperatorConfiguration,
    @Inject(PLATFORM_ID) private readonly platformId: object,
    @Inject(natifToken) public readonly isNatif: boolean,
    @Inject(kioskToken) public readonly isKiosk: boolean
  ) {
    super();
  }

  ngOnInit(): void {
    this.generalItems = this.customerOperatorConfiguration.customization?.footer?.general;
    this.helpItems = this.customerOperatorConfiguration.customization?.footer?.help;
    this.showCopyright = !!this.operatorConfig.onlineConfiguration?.displayFooterCopyright;
    this.copyright = `${this.operatorConfig.name} ${new Date().getFullYear()}`;
    this.displayLanguageSelector =
      this.customerOperatorConfiguration.themeCustomizationConfiguration?.displayLanguageSelectorInFooter;
    this.detectUserAgent();

    if (this.yeastarEnabled) {
      this.injectYeastar();
    }

    this.displayBannerFooter$ = combineLatest([
      this.templateService.getTemplatesForAnchor(AnchorType.FooterAnchor),
      this.router.events.pipe(
        filter(event => event instanceof NavigationEnd),
        map((event: NavigationEnd) => event.url),
        startWith(this.router.url)
      )
    ]).pipe(
      takeUntil(this.destroy$),
      map(([templates, url]: [Template[], string]) => templates && templates.length > 0 && !url.includes('/myaccount'))
    );

    if (this.operatorConfig.operatorFeatures?.indexOf('Charity') > -1) {
      this.charityService
        .showCharityNavigation()
        .pipe(
          takeUntil(this.destroy$),
          finalize(() => {
            this.cdRef.markForCheck();
          })
        )
        .subscribe(showCharityNavigation => {
          this.showCharity = showCharityNavigation;
        });
    }

    this.socialContacts = this.operatorConfig.contacts.filter((contact: OperatorContact) =>
      this.socialContactsNames.includes(contact.iconUrl)
    );

    this.cdRef.markForCheck();
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (!changes.me) {
      return;
    }
    this.helpContacts = this.operatorConfig.contacts.filter((contact: OperatorContact) => {
      const isNotSocial: boolean = !this.socialContactsNames.includes(contact.iconUrl);
      const isMessageAllowed: boolean = contact.iconUrl !== 'message' || !!this.me;
      const isZendeskAllowed: boolean = contact.action !== ContactAction.OpenZendesk || this.zendeskEnabled;
      const isDirectMessageAllowed: boolean =
        contact.action !== ContactAction.OpenDirectMessage || this.directMessageEnabled;

      return isNotSocial && isMessageAllowed && isZendeskAllowed && isDirectMessageAllowed;
    });
  }

  onChangeAnchor(hasAnchor: boolean): void {
    this.hasAnchor = hasAnchor;
    // markForCheck not enough with ssr (no idea why)
    this.cdRef.detectChanges();
  }

  onContactAction(action: ContactAction): void {
    const actions: Record<ContactAction, Function> = {
      [ContactAction.OpenZendesk]: () => this.openZendesk(),
      [ContactAction.OpenDirectMessage]: () => this.openDirectMessage()
    };

    actions[action]?.();
  }

  toggleDropdown(index: number): void {
    if (this.activeDropdown === index) {
      this.activeDropdown = null;
    } else {
      this.activeDropdown = index;
      setTimeout(() => {
        document.querySelector('.dropdown-content.active')?.scrollIntoView({ behavior: 'smooth' });
      }, 100);
    }
  }

  private openZendesk(): void {
    if (!window['zE']) {
      return;
    }
    // #20835 Small widget must be shown first
    window['zE']('messenger', 'show');
    window['zE']('messenger', 'open');
  }

  private injectYeastar(): void {
    const script: HTMLScriptElement = document.createElement('script');
    script.src = this.operatorConfig.onlineConfiguration.yeastarUrl;
    document.body.appendChild(script);
  }

  private detectUserAgent(): void {
    if (isPlatformBrowser(this.platformId)) {
      if (/iPad|iPhone|iPod/.test(navigator.userAgent)) {
        this.displayforIos = true;
      } else {
        this.displayforAndroid = true;
      }
    }
  }

  private openDirectMessage(): void {
    const hasOnPageChatBubble: boolean = this.operatorConfig.directMessageConfiguration?.onPageChatBubble;
    this.directMessageTrackingService.trackOpen('footer');

    if (hasOnPageChatBubble) {
      this.localStorage.setItem(this.LOCAL_STORAGE_KEY_DM, DirectMessageWidgetState.Open);
      this.broadcastingService.broadcast('open-direct-message-window');
      return;
    }

    this.router.navigate(['/myaccount', 'direct-message']);
  }
}
