import { ChangeDetectionStrategy, Component, EventEmitter, Input, OnChanges, Output } from '@angular/core';
import { BetBuilderError, BetBuilderLine, BetLineStateType } from '@honoregaming/types';
import { DestroySubject } from '@honoregaming/core';

@Component({
  selector: 'hg-bet-builder-lines',
  templateUrl: './bet-builder-lines.component.html',
  styleUrls: ['./bet-builder-lines.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class BetBuilderLinesComponent extends DestroySubject implements OnChanges {
  @Input() betBuilderLines: BetBuilderLine[] = [];
  @Input() displayDelete: boolean = true;
  @Input() displayErrors: boolean = true;
  @Input() displayLogo: boolean = true;
  @Input() isLoadingOddsEventIds: number[] = [];

  @Output() betBuilderLineRemove: EventEmitter<BetBuilderLine> = new EventEmitter();

  hasEligibilityError: boolean = false;

  BetBuilderError = BetBuilderError;
  BetLineStateType = BetLineStateType;

  constructor() {
    super();
  }

  ngOnChanges(): void {
    this.hasEligibilityError =
      this.displayErrors &&
      this.betBuilderLines?.some(
        (betBuilderLine: BetBuilderLine) => betBuilderLine?.betBuilderError === BetBuilderError.IneligibleSelection
      );
  }

  trackByBetBuilderLine(_index: number, betBuilderLine: BetBuilderLine): number {
    return betBuilderLine.eventBetTypeItemId;
  }

  onBetBuilderLineRemove(betBuilderLine: BetBuilderLine): void {
    this.betBuilderLineRemove.emit(betBuilderLine);
  }
}
