import {
  Component,
  ChangeDetectionStrategy,
  Input,
  ChangeDetectorRef,
  Inject,
  OnInit,
  HostBinding,
  HostListener,
  EventEmitter,
  Output,
  OnDestroy
} from '@angular/core';
import {
  SelectableEventBetTypeItem,
  PreEventOrLiveType,
  EventBetTypeItem,
  EventStateType,
  BetCategoryType,
  Match,
  EventWithEventBetTypes
} from '@honoregaming/types';
import { IEventService, eventServiceToken } from '../../services/event.service';
import { SafeStyle, DomSanitizer } from '@angular/platform-browser';
import {
  updateEventBetTypeAfterPush,
  updateEventAfterPush,
  PushService,
  templatingBetSlipServiceToken,
  DestroySubject,
  BroadcastingService,
  ApplicationEvent
} from '@honoregaming/core';
import { Router } from '@angular/router';
import { Subscription } from 'rxjs';
import { BetSlipService, createBetLine } from '@honoregaming/betslip';
import { takeUntil } from 'rxjs/operators';
import { EventsMapperService } from '@honoregaming/events';

@Component({
  selector: 'hg-match-template',
  templateUrl: './match-template.component.html',
  styleUrls: ['./match-template.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class MatchTemplateComponent extends DestroySubject implements OnInit, OnDestroy {
  @Input()
  eventId: number;

  @Input()
  backgroundUrl: string;

  @Output()
  error = new EventEmitter<boolean>();

  eventWithEventBetType: EventWithEventBetTypes<Match>;
  childCategory: string;

  loading = false;

  private betLinesSubscription: Subscription;
  private pushSubscription: Subscription;
  private pushEventSubscription: Subscription;

  @HostListener('click')
  navigateToEvent() {
    this.router.navigate(['/sports/event', this.eventId]);
  }

  @HostBinding('style.backgroundImage')
  get myStyle(): SafeStyle {
    return this.sanitizer.bypassSecurityTrustStyle(`url(${this.backgroundUrl})`);
  }

  constructor(
    private cdRef: ChangeDetectorRef,
    private sanitizer: DomSanitizer,
    private router: Router,
    @Inject(eventServiceToken) private eventService: IEventService,
    @Inject(templatingBetSlipServiceToken) private betSlipService: BetSlipService,
    private pushService: PushService,
    private bcService: BroadcastingService,
    private eventsMapperService: EventsMapperService
  ) {
    super();
  }

  ngOnInit() {
    this.eventService
      .getEventWithDefaultEventBetType<Match>(this.eventId)
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: e => {
          this.eventWithEventBetType = e;
          if (e && e.categories) {
            this.childCategory = e.categories[0];
          }

          if (
            this.eventWithEventBetType &&
            this.eventWithEventBetType.eventBetTypes &&
            this.eventWithEventBetType.eventBetTypes.length
          ) {
            this.pushService.subscribeToOdds(
              [this.eventWithEventBetType.eventBetTypes[0].id],
              [+this.eventId],
              `banner-${this.eventId}`
            );

            this.pushSubscription = this.pushService.eventBetTypeChanged$
              .pipe(takeUntil(this.destroy$))
              .subscribe(changed => {
                if (this.eventWithEventBetType.eventBetTypes[0].id === changed.eventBetTypeId) {
                  updateEventBetTypeAfterPush(this.eventWithEventBetType.eventBetTypes[0], changed);

                  this.cdRef.markForCheck();
                }
              });

            this.betLinesSubscription = this.betSlipService.$lines.pipe(takeUntil(this.destroy$)).subscribe(betSlip => {
              if (this.eventWithEventBetType && this.eventWithEventBetType.eventBetTypes[0]) {
                this.eventsMapperService.updateEventsWithEventBetTypesSelectedItems(
                  [this.eventWithEventBetType],
                  betSlip.lines.map(l => {
                    return {
                      eventId: l.eventId,
                      betTypeId: l.betTypeId,
                      eventBetTypeItemId: l.eventBetTypeItemId,
                      isBetCompletion: l.isBetCompletion
                    };
                  })
                );

                this.cdRef.markForCheck();
              }
            });

            this.pushEventSubscription = this.pushService.eventChanged$
              .pipe(takeUntil(this.destroy$))
              .subscribe(changed => {
                if (this.eventId === changed.eventId) {
                  this.eventWithEventBetType = updateEventAfterPush(
                    this.eventWithEventBetType,
                    [this.eventWithEventBetType.eventBetTypes[0]],
                    changed
                  );

                  if (
                    changed.changes['state'] &&
                    this.eventWithEventBetType.preEventOrLive === PreEventOrLiveType.PreEvent &&
                    changed.changes['state'] === EventStateType.Started
                  ) {
                    this.eventService
                      .getEventWithDefaultEventBetType<Match>(this.eventId)
                      .pipe(takeUntil(this.destroy$))
                      .subscribe(evt => {
                        this.eventWithEventBetType = evt;
                        if (evt && evt.categories) {
                          this.childCategory = evt.categories[0];
                        }
                      });
                  }
                }
              });
          } else {
            this.error.emit(true);
          }

          this.cdRef.markForCheck();
        },
        error: () => {
          this.error.emit(true);
        }
      });
  }

  toggleBet(eventBetTypeItem: SelectableEventBetTypeItem, event: Event) {
    event.preventDefault();
    event.stopImmediatePropagation();

    if (
      !eventBetTypeItem.odds ||
      eventBetTypeItem.odds <= 1 ||
      !this.eventWithEventBetType.eventBetTypes[0].active ||
      !this.eventWithEventBetType.eventBetTypes[0].bettingAllowed ||
      !eventBetTypeItem.active ||
      !eventBetTypeItem.bettingAllowed
    ) {
      return;
    }

    eventBetTypeItem.selected = !eventBetTypeItem.selected;

    const bet = createBetLine(
      this.eventWithEventBetType,
      this.eventWithEventBetType.eventBetTypes[0],
      eventBetTypeItem,
      BetCategoryType.SportsFixedOdds // TODO - UPDATE WITH INSTANTLEAGUE BETTYPE CATEGORY
    );
    if (!eventBetTypeItem.selected) {
      this.betSlipService.removeBetLine(bet);
    } else {
      this.bcService.broadcast(ApplicationEvent.BetSelected, {
        event: this.eventWithEventBetType,
        eventBetType: this.eventWithEventBetType.eventBetTypes[0]
      });
      this.betSlipService.addBetLine(bet);
    }
  }

  // tslint:disable-next-line: use-life-cycle-interface
  ngOnDestroy() {
    super.ngOnDestroy();

    if (this.betLinesSubscription) {
      this.betLinesSubscription.unsubscribe();
    }
    if (this.pushSubscription) {
      this.pushSubscription.unsubscribe();
    }
    if (this.pushEventSubscription) {
      this.pushEventSubscription.unsubscribe();
    }
  }

  trackEventBetTypeItem(_index: number, eventBetTypeItem: EventBetTypeItem) {
    return eventBetTypeItem.id;
  }
}
