import { HttpClient } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { globalConfiguration } from '@honoregaming/configuration';
import { SelfLimitation } from '../models/self-limitation.model';
import { Observable } from 'rxjs';
import { CreateOrUpdateSelfLimitation } from '../models/create-or-update-self-limitation.model';
import { ResponsibleGamblingData } from '../models/responsible-gambling-data.model';
import { SelfLimitationProfile } from '../models/self-limitation-profile.model';

@Injectable({
  providedIn: 'root'
})
export class ResponsibleGamblingService {
  constructor(private httpClient: HttpClient) {}

  getLimitations(): Observable<SelfLimitation[]> {
    return this.httpClient.get<SelfLimitation[]>(
      `${globalConfiguration.apiBaseUrl}responsible-gambling/self-limitations`
    );
  }

  createOrUpdateLimitation(request: {
    selfLimitations: CreateOrUpdateSelfLimitation[];
    profileType: SelfLimitationProfile;
  }): Observable<any> {
    return this.httpClient.put(`${globalConfiguration.apiBaseUrl}responsible-gambling/self-limitations`, request);
  }

  updateSelfExclusion(date: Date): Observable<any> {
    return this.httpClient.put(`${globalConfiguration.apiBaseUrl}responsible-gambling/self-exclusion`, {
      date: date
    });
  }

  getResponsibleGamblingData(): Observable<ResponsibleGamblingData> {
    return this.httpClient.get<ResponsibleGamblingData>(`${globalConfiguration.apiBaseUrl}responsible-gambling`);
  }
}
