import { isPlatformServer } from '@angular/common';
import { Injectable, ApplicationRef, NgZone, PLATFORM_ID, Inject } from '@angular/core';
import { ReplaySubject, of, BehaviorSubject } from 'rxjs';
import { filter, take, timeout, catchError } from 'rxjs/operators';

@Injectable({ providedIn: 'root' })
export class ApplicationStateService {
  private isReadySubject = new ReplaySubject<boolean>(1);
  isReady$ = this.isReadySubject.asObservable();

  private updateAvailableSubject = new BehaviorSubject<boolean>(false);
  updateAvailable$ = this.updateAvailableSubject.asObservable();

  updateAvailable() {
    this.updateAvailableSubject.next(true);
  }

  constructor(appRef: ApplicationRef, zone: NgZone, @Inject(PLATFORM_ID) platformId) {
    const timeoutDuration = isPlatformServer(platformId) ? 2e3 : 4e3;
    zone.runOutsideAngular(() =>
      appRef.isStable
        .pipe(
          filter((isStable: boolean) => isStable),
          take(1),
          timeout(timeoutDuration),
          catchError(_err => {
            console.warn('stable timeout');
            return of(true);
          })
        )
        .subscribe(_ => this.isReadySubject.next(true))
    );
  }
}
