import { Component, ChangeDetectionStrategy, Input, Output, EventEmitter } from '@angular/core';
import { Router } from '@angular/router';
import { DestroySubject } from '@honoregaming/core';
import { BatchPopupsService } from '@honoregaming/templating';
import { CustomerBatchPopup } from '@honoregaming/types';
import { finalize, takeUntil } from 'rxjs/operators';

@Component({
  selector: 'hg-batch-popup-template',
  templateUrl: './batch-popup-template.component.html',
  styleUrls: ['./batch-popup-template.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class BatchPopupTemplateComponent extends DestroySubject {
  @Input() popup: CustomerBatchPopup;
  @Input() hasArrows = false;
  @Input() firstPopupShown = false;
  @Output() close = new EventEmitter<'prev' | 'next' | boolean>();

  isLoading = false;
  constructor(private batchPopupsService: BatchPopupsService, private router: Router) {
    super();
  }

  openLink() {
    const url = this.popup.actionLink?.trim();

    if (!url) {
      this.close.emit(false);
      return;
    }
    this.isLoading = true;
    this.batchPopupsService
      .readBatchPopup(this.popup.id, true)
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.isLoading = false;
          if (url.startsWith('/')) {
            this.router.navigateByUrl(url);
            this.close.emit(true);
            return;
          }
          this.batchPopupsService.markSeen(this.popup);
          this.close.emit();
          window.location.assign(url);
        })
      )
      .subscribe();
  }
}
