import {
  OnInit,
  ChangeDetectionStrategy,
  Input,
  Component,
  Inject,
  OnChanges,
  ChangeDetectorRef,
  PLATFORM_ID,
  NgZone
} from '@angular/core';
import { Match, EventType } from '@honoregaming/types';
import { EventCategoriesService, EventsService } from '@honoregaming/events';
import { DestroySubject, delayBetween, getUtcNow, ApplicationStateService } from '@honoregaming/core';
import { Subscription, timer } from 'rxjs';
import { takeUntil } from 'rxjs/operators';
import { isPlatformBrowser } from '@angular/common';

@Component({
  selector: 'hg-event',
  templateUrl: './event.component.html',
  styleUrls: ['./event.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class EventComponent extends DestroySubject implements OnInit, OnChanges {
  @Input()
  event: Match;
  @Input()
  showEntrypoint: boolean;
  @Input()
  flatMode: boolean;
  @Input()
  showEntryPointName: boolean;
  @Input()
  isAboutToStart: boolean;
  @Input()
  isStreamed: boolean;
  @Input()
  showTimer: boolean;
  @Input()
  showDisplayId: boolean;
  @Input()
  isSticky: boolean;

  entryPointName: string;
  countDown: number;
  timerCountDown: Subscription;
  EventType = EventType;

  fullCategoryPath: string;

  constructor(
    private readonly eventCategoryService: EventCategoriesService,
    private readonly cdRef: ChangeDetectorRef,
    @Inject(PLATFORM_ID) private readonly platformId,
    private readonly zone: NgZone,
    private readonly applicationStateService: ApplicationStateService,
    private readonly eventsService: EventsService
  ) {
    super();
  }

  ngOnInit() {
    if (this.showEntryPointName) {
      this.eventCategoryService.getEntryPoints().subscribe(ep => {
        const eventCategory = ep.find(e => e.id === this.event.entryPointId);
        if (eventCategory) {
          this.entryPointName = eventCategory.name;
        }
      });
    }

    if (this.event.categoryPath) {
      var categoriesPath = this.event.categoryPath.split('/');
      if (categoriesPath?.length >= 4) {
        this.fullCategoryPath =
          categoriesPath[0] + '/' + categoriesPath[1] + '/' + categoriesPath[2] + '/' + categoriesPath[3];
      } else {
        this.fullCategoryPath = this.event.categoryPath;
      }
    }
  }

  ngOnChanges(): void {
    if (this.showTimer && isPlatformBrowser(this.platformId)) {
      this.applicationStateService.isReady$.subscribe(() => {
        if (this.timerCountDown) {
          this.timerCountDown.unsubscribe();
        }

        this.timerCountDown = timer(0, 1000)
          .pipe(takeUntil(this.destroy$))
          .subscribe(_ => {
            this.countDown = delayBetween(getUtcNow(), this.event.expectedStart);
            this.zone.run(() => this.cdRef.markForCheck());
          });
      });
    }
  }

  trackLastEvent(eventId: number): void {
    this.eventsService.trackLastEvent(eventId, this.event.entryPointId);
  }
}
