import { Component, OnInit, ChangeDetectionStrategy, ChangeDetectorRef } from '@angular/core';
import { AsyncTrigger, Async, DestroySubject } from '@honoregaming/core';
import { I18nService } from '@honoregaming/i18n';
import { EventCategory } from '@honoregaming/types';
import { ActivatedRoute } from '@angular/router';
import { forkJoin, merge } from 'rxjs';
import { skip, takeUntil } from 'rxjs/operators';
import { EventCategoriesService } from '@honoregaming/events';

@Component({
  selector: 'hg-category-navigation',
  templateUrl: './category-navigation.component.html',
  styleUrls: ['./category-navigation.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class CategoryNavigationComponent extends DestroySubject implements OnInit {
  eventCategories: EventCategory[];
  entryPointId: number;
  loading = false;

  @AsyncTrigger()
  languageTrigger = this.i18nService.languageChanged$;
  entryPoint: EventCategory;

  constructor(
    private eventCategoriesService: EventCategoriesService,
    private cdRef: ChangeDetectorRef,
    private i18nService: I18nService,
    private route: ActivatedRoute
  ) {
    super();
  }

  ngOnInit() {
    this.entryPointId = this.route.snapshot.params.entryPointId;
    this.route.params.subscribe(params => {
      this.entryPointId = +params.entryPointId;
      this.loadCategoriesForEntryPoint();
    });
  }

  @Async()
  loadCategoriesForEntryPoint() {
    this.loading = true;
    forkJoin([
      this.eventCategoriesService.getEntryPoints(),
      this.eventCategoriesService.getCategoriesForEntryPoint(this.entryPointId)
    ])
      .pipe(
        takeUntil(
          merge(this.destroy$, this.route.params.pipe(skip(1)), this.i18nService.languageChanged$.pipe(skip(1)))
        )
      )
      .subscribe({
        next: ([entryPoints, eventCategories]) => {
          this.entryPoint = entryPoints.filter(x => x.id === this.entryPointId)[0];
          this.eventCategories = eventCategories;
          this.cdRef.markForCheck();
        },
        complete: () => {
          this.loading = false;
        }
      });
  }
}
