import { isPlatformBrowser } from '@angular/common';
import { ChangeDetectionStrategy, ChangeDetectorRef, Component, Inject, OnInit, PLATFORM_ID } from '@angular/core';
import { of } from 'rxjs';
import { finalize, switchMap, take, takeUntil, tap } from 'rxjs/operators';
import { AccountService } from '@honoregaming/account';
import { Feature } from '@honoregaming/configuration';
import { DestroySubject } from '@honoregaming/core';
import {
  AuthService,
  CustomerOperatorConfiguration,
  customerOperatorConfigurationToken,
  CustomerService,
  CustomerStatus,
  KnowYourCustomerConfiguration,
  Me
} from '@honoregaming/customer-core';
import { AskQuestionComponent, AskQuestionWithInputComponent } from '@honoregaming/customer-ui';
import { I18nService } from '@honoregaming/i18n';
import { CountryCode, ProfileFieldPolicy, ProfilePolicy, SecurityPolicy } from '@honoregaming/types';
import { MessageService } from '@honoregaming/ui';
import { ComplianceService } from '../../services/compliance.service';

@Component({
  selector: 'hg-informations',
  templateUrl: './informations.component.html',
  styleUrls: ['./informations.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class InformationsComponent extends DestroySubject implements OnInit {
  oldPassword?: string;
  newPassword?: string;
  confirmPassword?: string;
  changeDone: boolean = false;
  loading: boolean = false;
  securityPolicy?: SecurityPolicy;
  login?: string;
  freeBalance?: number;
  balance?: number;
  firstName?: string;
  lastName?: string;
  birthdate?: string;
  nationality?: string;
  nationalityLabel?: string;
  street?: string;
  region?: string;
  country?: string;
  email?: string;
  password?: string;
  error?: string;
  reference?: string;
  politicallyExposedPerson?: boolean;
  showCurrentPasswordValue: boolean = false;
  showPasswordValue: boolean = false;
  showConfirmPasswordValue: boolean = false;
  isValidatingIdentity: boolean = false;
  isUpdatingEmail: boolean = false;
  isUpdatingPassword: boolean = false;
  isUpdatingOptions: boolean = false;
  me?: Me;
  profilePolicyFields: ProfileFieldPolicy[] = [];
  knowYourCustomerConfiguration: KnowYourCustomerConfiguration =
    this.customerOperatorConfiguration.knowYourCustomerConfiguration;
  profilePolicyRequirements?: ProfilePolicy;
  canSelfCloseAccount: boolean =
    this.customerOperatorConfiguration.complianceConfiguration?.selfAccountClosing?.active || false;
  hasEditableOptions: boolean =
    this.customerOperatorConfiguration?.operatorFeatures?.indexOf(Feature.DirectMessage) > -1;
  showReference: boolean = this.customerOperatorConfiguration?.onlineConfiguration.showCustomerReferenceInMyAccount;
  countries: CountryCode[] = [];
  canEditAccountInformations: boolean =
    this.customerOperatorConfiguration?.onlineConfiguration.canEditAccountInformations;
  canEditPersonalInformations: boolean =
    this.customerOperatorConfiguration?.onlineConfiguration.canEditPersonalInformations;
  canEditAdditionalInformations: boolean =
    this.customerOperatorConfiguration?.onlineConfiguration.canEditAdditionalInformations;
  useExternalKYCValidation: boolean =
    this.customerOperatorConfiguration.knowYourCustomerConfiguration?.useExternalKYCValidation || false;
  isLoadingExternalKYCValidationInformations: boolean = false;
  showPoliticallyExposedPerson: boolean = false;

  constructor(
    private readonly customerService: CustomerService,
    private readonly authService: AuthService,
    private readonly cdRef: ChangeDetectorRef,
    private readonly messageService: MessageService,
    private readonly i18nService: I18nService,
    private readonly complianceService: ComplianceService,
    private readonly accountService: AccountService,
    @Inject(customerOperatorConfigurationToken)
    private readonly customerOperatorConfiguration: CustomerOperatorConfiguration,
    @Inject(PLATFORM_ID) private readonly platformId: Object
  ) {
    super();
  }

  ngOnInit(): void {
    this.customerService
      .getSecurityPolicy()
      .pipe(
        takeUntil(this.destroy$),
        tap(securityPolicy => {
          this.securityPolicy = securityPolicy;
          this.profilePolicyRequirements = this.securityPolicy.profilePolicyRequirements;
          this.profilePolicyFields = this.profilePolicyRequirements?.fields;
          this.showPoliticallyExposedPerson =
            this.profilePolicyFields?.some((field: ProfileFieldPolicy) => field.name === 'politicallyExposedPerson') ??
            false;
          this.cdRef.markForCheck();
        }),
        switchMap(_ => {
          if (this.profilePolicyFields?.find(field => field.name === 'nationality')) {
            return this.customerService.getCountryCodes().pipe(
              tap(countries => {
                this.countries = countries;
              })
            );
          }
          return of(null);
        }),
        switchMap(_ => this.authService.me$),
        tap(me => this.setMe(me))
      )
      .subscribe();

    this.accountService.editProfileInformation.pipe(takeUntil(this.destroy$)).subscribe(() => {
      this.validatingIdentity(true);
    });
  }

  editIdentity(isValidating: boolean): void {
    this.isValidatingIdentity = isValidating;
  }

  validatingIdentity(isValidating: boolean): void {
    if (!this.useExternalKYCValidation) {
      this.isValidatingIdentity = isValidating;
    } else {
      if (this.isLoadingExternalKYCValidationInformations) {
        return;
      }

      this.isLoadingExternalKYCValidationInformations = true;
      this.cdRef.markForCheck();

      this.customerService
        .getExternalKYCValidationUrl()
        .pipe(
          takeUntil(this.destroy$),
          finalize(() => {
            this.isLoadingExternalKYCValidationInformations = false;
            this.cdRef.markForCheck();
          })
        )
        .subscribe((url: string) => {
          if (url && isPlatformBrowser(this.platformId)) {
            window.location.href = url;
          }
        });
    }
  }

  finishValidation(showMessage: boolean = true): void {
    this.authService
      .getMe()
      .pipe(take(1))
      .subscribe(me => {
        this.setMe(me);
      });
    this.isValidatingIdentity = false;
    if (showMessage) {
      this.messageService.sendHeaderMessage('KYC', CustomerStatus.ToBeVerified);
    }
  }

  startUpdatingEmail(): void {
    this.isUpdatingEmail = true;
  }

  finishUpdatingEmail(email: string): void {
    this.isUpdatingEmail = false;
    if (this.email !== email) {
      this.email = email;
    }
  }

  startUpdatingPassword(): void {
    this.isUpdatingPassword = true;
  }

  finishUpdatingPassword(password: string): void {
    this.isUpdatingPassword = false;
    if (this.password !== password) {
      this.password = password;
    }
  }

  startUpdatingOptions(): void {
    this.isUpdatingOptions = true;
  }

  finishUpdatingOptions(): void {
    this.isUpdatingOptions = false;
  }

  selfCloseAccountStep1(): void {
    this.messageService
      .sendComponentMessage(AskQuestionComponent, {
        title: this.i18nService.translateSync('ACCOUNT.SELF_CLOSING.TITLE'),
        text: this.i18nService.translateSync('ACCOUNT.SELF_CLOSING.STEP1')
      })
      .closed.pipe(takeUntil(this.destroy$))
      .subscribe(result => {
        if (result) {
          this.selfCloseAccountStep2();
        }
      });
  }

  private selfCloseAccountStep2(): void {
    this.messageService
      .sendComponentMessage(AskQuestionComponent, {
        title: this.i18nService.translateSync('ACCOUNT.SELF_CLOSING.TITLE'),
        text: this.i18nService.translateSync(
          'ACCOUNT.SELF_CLOSING.STEP2',
          this.balance.toString(),
          this.customerOperatorConfiguration.currency.symbol
        )
      })
      .closed.pipe(takeUntil(this.destroy$))
      .subscribe(result => {
        if (result) {
          this.selfCloseAccountStep3();
        }
      });
  }

  private selfCloseAccountStep3(): void {
    this.loading = true;
    this.complianceService
      .sendAccountClosingVerificationCode()
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.loading = false;
          this.cdRef.markForCheck();
        })
      )
      .subscribe(
        () => {
          this.selfCloseAccountValidationStep();
        },
        _ => {
          this.error = this.error || 'COMMON_GENERIC_ERROR';
          this.selfCloseAccountValidationStep();
        }
      );
  }

  private selfCloseAccountValidationStep(): void {
    this.messageService
      .sendComponentMessage(AskQuestionWithInputComponent, {
        title: this.i18nService.translateSync('ACCOUNT.SELF_CLOSING.TITLE'),
        text: this.i18nService.translateSync('ACCOUNT.SELF_CLOSING.STEP3'),
        inputLabel: this.i18nService.translateSync('ACCOUNT.SELF_CLOSING.VALIDATION_CODE')
      })
      .closed.pipe(takeUntil(this.destroy$))
      .subscribe(result => {
        if (result?.success && result?.value) {
          this.complianceService
            .selfCloseAccount(result.value)
            .pipe(
              takeUntil(this.destroy$),
              finalize(() => {
                this.loading = false;
                this.cdRef.markForCheck();
              })
            )
            .subscribe(
              () => {
                this.authService.logout();
              },
              _ => {
                this.error = this.error || 'COMMON_GENERIC_ERROR';
              }
            );
        }
      });
  }

  private setMe(me: Me): void {
    this.me = me;
    if (this.me) {
      this.login = me.login;
      this.freeBalance = me.freeBalance;
      this.balance = me.balance;
      this.reference = me.reference;
      this.firstName = me.profile?.firstName;
      this.lastName = me.profile?.lastName;
      this.birthdate = me.profile?.birthdate;
      this.street = me.profile?.street;
      this.region = me.profile?.region;
      this.country = me.profile?.country;
      this.email = me.profile?.email;
      this.politicallyExposedPerson = me.profile?.politicallyExposedPerson;
      this.nationality = me.profile?.nationality;
      if (!!this.nationality) {
        const country: CountryCode | undefined = this.countries.find(country => country.iso3_code === this.nationality);
        if (!!country) {
          this.i18nService.languageChanged$.pipe(takeUntil(this.destroy$)).subscribe(language => {
            if (country.hasOwnProperty(language)) {
              this.nationalityLabel = (country as any as Record<string, string>)[language];
            } else {
              this.nationalityLabel = country['en'];
            }
            this.cdRef.markForCheck();
          });
        }
      }
      this.cdRef.markForCheck();
    }
  }
}
