import { Component, ChangeDetectionStrategy, OnInit, ChangeDetectorRef, Input } from '@angular/core';
import { DestroySubject } from '@honoregaming/core';
import { CharityService } from 'projects/customer/hg-about/src/lib/services/charity.service';
import { finalize, takeUntil } from 'rxjs/operators';

@Component({
  selector: 'hg-charity-block',
  templateUrl: './charity-block.component.html',
  styleUrls: ['./charity-block.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class CharityBlockComponent extends DestroySubject implements OnInit {
  @Input()
  forceHorizontal: boolean = false;

  @Input()
  small: boolean = false;

  show: boolean = false;
  constructor(private readonly charityService: CharityService, private readonly cdRef: ChangeDetectorRef) {
    super();
  }

  ngOnInit(): void {
    this.charityService
      .showCharityNavigation()
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.cdRef.markForCheck();
        })
      )
      .subscribe(showCharityNavigation => {
        this.show = showCharityNavigation;
      });
  }
}
