declare var grecaptcha: any;

import { mergeMap } from 'rxjs/operators';
import { Inject, Injectable, PLATFORM_ID } from '@angular/core';
import { DestroySubject } from '@honoregaming/core';
import { ICaptchaService } from './captcha-service.model';
import { CustomerService } from '../customer.service';
import { SecurityPolicy } from '@honoregaming/types';
import { DOCUMENT, isPlatformBrowser } from '@angular/common';
import { Observable, from, of } from 'rxjs';

@Injectable()
export class ReCaptchaV3Service extends DestroySubject implements ICaptchaService {
  private securityPolicy: SecurityPolicy;

  private script: any;

  constructor(
    private customerService: CustomerService,
    @Inject(DOCUMENT) private document,
    @Inject(PLATFORM_ID) private platformId
  ) {
    super();
  }

  loadCaptcha(securityPolicy: SecurityPolicy) {
    this.securityPolicy = securityPolicy;
  }

  applyCaptcha(_targetElement: string): Observable<void> {
    return this.customerService.getSecurityPolicy().pipe(
      mergeMap(securityPolicy => {
        this.securityPolicy = securityPolicy;

        if (this.securityPolicy.captchaProvider?.recaptchaV3?.enabled && isPlatformBrowser(this.platformId)) {
          if (!this.document.querySelector('#RECAPTCHA')) {
            this.script = this.document.createElement('script');
            this.script.src =
              'https://www.google.com/recaptcha/api.js?render=' +
              this.securityPolicy.captchaProvider.recaptchaV3.recaptchaSiteKey;
            this.script.rel = 'script';
            this.script.id = 'RECAPTCHA';

            this.document.querySelector('body').appendChild(this.script);

            return from(
              new Promise<void>((resolve, _) => {
                this.script.onload = () => resolve();
              })
            );
          } else {
            this.script = document.querySelector('#RECAPTCHA');
            return of(void 0);
          }
        }
      })
    );
  }

  validateCaptcha(): Observable<string> {
    if (this.securityPolicy.captchaProvider?.recaptchaV3?.enabled && isPlatformBrowser(this.platformId)) {
      return from(
        new Promise<string>((resolve, _) => {
          grecaptcha.ready(() => {
            grecaptcha
              .execute(this.securityPolicy.captchaProvider.recaptchaV3.recaptchaSiteKey, { action: 'submit' })
              .then((token: string) => {
                resolve(token);
              });
          });
        })
      );
    }

    return of(null);
  }

  getLegend(): string {
    if (this.securityPolicy.captchaProvider?.recaptchaV3?.enabled && isPlatformBrowser(this.platformId)) {
      return (
        'This site is protected by reCAPTCHA and the Google' +
        '<a href="https://policies.google.com/privacy" target="_blank">Privacy Policy</a> and' +
        '<a href="https://policies.google.com/terms" target="_blank">Terms of Service</a> apply.'
      );
    }

    return null;
  }

  clearCaptcha(): void {
    if (this.document.querySelector('#RECAPTCHA')) {
      this.document.querySelector('body').removeChild(this.script);
    }
  }
}
