import {
  Component,
  OnInit,
  ChangeDetectionStrategy,
  Input,
  HostBinding,
  Inject,
  OnChanges,
  EventEmitter,
  Output,
  AfterViewInit,
  ChangeDetectorRef
} from '@angular/core';
import { DOCUMENT } from '@angular/common';
import { NavigationStart, Router } from '@angular/router';
import { filter } from 'rxjs/operators';

@Component({
  selector: 'hg-popup',
  templateUrl: './popup.component.html',
  styleUrls: ['./popup.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class PopupComponent implements OnInit, OnChanges, AfterViewInit {
  @HostBinding('class.opened')
  @Input()
  opened: boolean;

  @HostBinding('class.bottom')
  @Input()
  bottom: boolean;

  @Input() hideClose = false;
  @Input() isLargeDisplay = false;

  @Output() close = new EventEmitter();

  isAfterViewInit: boolean = false;

  constructor(@Inject(DOCUMENT) private document: any, private router: Router, public cdRef: ChangeDetectorRef) {}

  ngOnInit() {
    this.router.events.pipe(filter(x => x instanceof NavigationStart)).subscribe(() => {
      this.close.emit();
    });
  }

  ngAfterViewInit(): void {
    requestAnimationFrame(() => {
      this.isAfterViewInit = true;
      this.cdRef.markForCheck();
    });
  }

  ngOnChanges() {
    this.opened
      ? this.document.documentElement.classList.add('hidden-in-xs')
      : this.document.documentElement.classList.remove('hidden-in-xs');
  }

  onClose() {
    this.close.emit();
  }
}
