import { EventEmitter, Output, OnInit, ChangeDetectorRef, Directive, Inject } from '@angular/core';
import { EventCategoriesService } from '@honoregaming/events';
import { EventCategory } from '@honoregaming/types';
import { ActivatedRoute, Router } from '@angular/router';
import { skip, takeUntil } from 'rxjs/operators';
import { Async, AsyncTrigger, DestroySubject } from '@honoregaming/core';
import { merge } from 'rxjs';
import { scopeToken, Scope } from '@honoregaming/core';
import { I18nService } from '@honoregaming/i18n';

@Directive()
// tslint:disable-next-line: directive-class-suffix
export class EventCategoriesNavigationComponent extends DestroySubject implements OnInit {
  @Output()
  public navigated = new EventEmitter<number>();

  @Output()
  toggleMenuEvent = new EventEmitter<{}>();

  loading = false;
  entryPoints: EventCategory[];
  currentEntryPoint: EventCategory;

  @AsyncTrigger()
  languageTrigger = this.i18nService.languageChanged$;

  constructor(
    private i18nService: I18nService,
    private route: ActivatedRoute,
    private eventCategoriesService: EventCategoriesService,
    protected cdRef: ChangeDetectorRef,
    @Inject(scopeToken) public scope: Scope,
    private router: Router
  ) {
    super();
  }
  ngOnInit() {
    this.loading = true;
    this.getEntryPoints();
  }

  @Async()
  getEntryPoints() {
    // 4 is for Draw Games
    this.eventCategoriesService
      .getEntryPointsForRootEventCategories([4])
      .pipe(
        takeUntil(
          merge(this.route.params.pipe(skip(1)), this.i18nService.languageChanged$.pipe(skip(1)), this.destroy$)
        )
      )
      .subscribe((entryPoints: EventCategory[]) => {
        this.entryPoints = entryPoints;

        this.route.params.pipe(takeUntil(this.destroy$)).subscribe(params => {
          if (this.entryPoints && this.entryPoints.length > 0 && params['eventCategory']) {
            this.currentEntryPoint = this.entryPoints.find(e => e.id === +params['eventCategory']);
          }

          this.loading = false;
          this.cdRef.markForCheck();
        });

        this.loading = false;
        this.cdRef.markForCheck();
      });
  }

  navigate(eventCategory: EventCategory) {
    if (this.scope !== Scope.Customer && this.scope !== Scope.Kiosk) {
      this.currentEntryPoint = eventCategory;
      this.navigated.emit(eventCategory?.id);
      this.toggleMenu();
    }

    this.router.navigate(this.getRoute(eventCategory.id));
  }

  getRoute(id: number) {
    if (this.scope === Scope.Customer || this.scope === Scope.Kiosk) {
      return ['/draw-games'];
    }

    return ['/draw-games/category', id];
  }

  toggleMenu() {
    this.toggleMenuEvent.emit();
  }
}
