import { Component, ChangeDetectionStrategy, Input, HostBinding } from '@angular/core';
import { BetLineStateType, BetState } from '@honoregaming/types';

@Component({
  selector: 'hg-betstate-icon',
  templateUrl: './betstate-icon.component.html',
  styleUrls: ['./betstate-icon.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class BetStateIconComponent {
  @Input()
  state: BetState | BetLineStateType;

  BetState = BetState;

  @HostBinding('class')
  get className() {
    return this.state.toLocaleLowerCase();
  }
}
