import { Inject, Injectable } from '@angular/core';
import { BehaviorSubject, Observable } from 'rxjs';
import { OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';
import { BetLineStateType, BetSystemHistory, BetSystemType } from '@honoregaming/types';
import { LocalStorageService } from './local-storage.service';

const BET_HISTORY_EXPANDED_FORMAT_KEY = 'account:bet-history-expand-format';

const BET_LINE_STATE_DISPLAY_ORDER: BetLineStateType[] = [
  BetLineStateType.Pending,
  BetLineStateType.Won,
  BetLineStateType.Lost,
  BetLineStateType.Refunded
];

@Injectable({ providedIn: 'root' })
export class BetHistoryService {
  public readonly expandedFormat$: Observable<boolean>;

  private readonly expandedFormatSubject: BehaviorSubject<boolean>;

  constructor(
    private readonly localStorageService: LocalStorageService,
    @Inject(operatorConfigurationToken) private readonly operatorConfiguration: OperatorConfiguration
  ) {
    this.expandedFormatSubject = new BehaviorSubject<boolean>(this.getInitialExpandedFormat());
    this.expandedFormat$ = this.expandedFormatSubject.asObservable();
  }

  get expandedFormat(): boolean {
    return this.expandedFormatSubject.value;
  }

  get reducedFormatEnabled(): boolean {
    return this.operatorConfiguration.betHistoryConfiguration?.enableBetHistoryReducedFormat ?? false;
  }

  getBetLineStateCounts(betSystem: BetSystemHistory): { state: BetLineStateType; count: number }[] {
    if (betSystem.type !== BetSystemType.Multiple || !this.reducedFormatEnabled) return [];

    const counts = new Map<BetLineStateType, number>();
    for (const line of betSystem.betLines) {
      const state: BetLineStateType | null = this.normalizeBetLineState(line.state);
      if (!state) continue;
      counts.set(state, (counts.get(state) ?? 0) + 1);
    }

    return BET_LINE_STATE_DISPLAY_ORDER.filter((state: BetLineStateType) => counts.has(state)).map(
      (state: BetLineStateType) => ({
        state,
        count: counts.get(state) ?? 0
      })
    );
  }

  setExpandedFormat(expanded: boolean): void {
    if (this.expandedFormatSubject.value !== expanded) {
      this.expandedFormatSubject.next(expanded);
      this.localStorageService.setItem(BET_HISTORY_EXPANDED_FORMAT_KEY, expanded);
    }
  }

  private normalizeBetLineState(state: BetLineStateType): BetLineStateType | null {
    switch (state) {
      case BetLineStateType.Pending:
        return BetLineStateType.Pending;
      case BetLineStateType.Won:
      case BetLineStateType.PartialWon:
        return BetLineStateType.Won;
      case BetLineStateType.Lost:
      case BetLineStateType.PartialLost:
        return BetLineStateType.Lost;
      case BetLineStateType.Refunded:
        return BetLineStateType.Refunded;
      default:
        return null;
    }
  }

  private getInitialExpandedFormat(): boolean {
    const storedValue: boolean | undefined = this.localStorageService.getItem(BET_HISTORY_EXPANDED_FORMAT_KEY);

    return typeof storedValue === 'boolean' ? storedValue : !this.reducedFormatEnabled;
  }
}
