import {
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  EventEmitter,
  Inject,
  NgZone,
  OnDestroy,
  OnInit,
  Optional,
  Output,
  ViewChild
} from '@angular/core';
import { Router } from '@angular/router';
import { Observable } from 'rxjs';
import { finalize, takeUntil } from 'rxjs/operators';
import { Feature, OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';
import { BroadcastingService, DestroySubject, hasFlag, LocalStorageService } from '@honoregaming/core';
import {
  AuthService,
  CustomerDirectMessageConfiguration,
  CustomerService,
  CustomerState,
  DirectMessageService,
  FreeBetService,
  Me,
  NavigationService,
  SmarticoService
} from '@honoregaming/customer-core';
import { I18nService } from '@honoregaming/i18n';
import { BetCategoryType, PaginatedResponse } from '@honoregaming/types';
import { AnimateDirective, Media, MediaService } from '@honoregaming/ui';
import {
  TransactionMode,
  TransactionPopupService
} from 'projects/customer/hg-core/src/lib/services/transaction-popup.service';
import { DirectMessageWidgetState } from 'projects/customer/hg-direct-message/src/lib/enums/direct-message-widget-view.enum';
import { DirectMessageTrackingService } from 'projects/customer/hg-direct-message/src/lib/services/direct-message-tracking.service';
import { Partner } from '../../models/partner.model';
import { PartnerService } from '../../services/partner.service';
import { AccountTrackingService } from '../../services';

@Component({
  selector: 'hg-account-navigation',
  templateUrl: './account-navigation.component.html',
  styleUrls: ['./account-navigation.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class AccountNavigationComponent extends DestroySubject implements OnInit, OnDestroy {
  @Output() changed = new EventEmitter();

  @ViewChild(AnimateDirective) refreshAnimation?: AnimateDirective;

  me?: Me;
  isValidated: boolean = true;
  hasInstantGamesFeature?: boolean;
  hasSimulateFeature: boolean = this.operatorConfiguration.bettingConfiguration?.allowSimulatedMode;
  isUpdatingBalanceVisibility: boolean = false;

  referralActive?: boolean;
  displayMessagingLink: boolean = false;
  newDirectMessagesCount$: Observable<number>;
  interval?: NodeJS.Timeout;
  showPartners: boolean = false;
  openedFreebetCouponsCount$!: Observable<number>;

  freeBetMultiCouponActive: boolean = this.operatorConfiguration.freeBetsConfiguration?.multiCouponEnabled;
  hasOnPageChatBubble: boolean = this.operatorConfiguration.directMessageConfiguration?.onPageChatBubble;
  enablePopupMethodDeposit: boolean = this.operatorConfiguration.depositConfiguration?.enablePopupMethod;
  enablePopupMethodWithdrawal: boolean = this.operatorConfiguration.withdrawalConfiguration?.enablePopupMethod;

  readonly showSmartico: boolean = this.smarticoService.showMyAccount;

  readonly LOCAL_STORAGE_KEY_DM: string = 'direct_message:widget:state';

  constructor(
    private readonly authService: AuthService,
    private readonly cdRef: ChangeDetectorRef,
    private readonly ngZone: NgZone,
    private readonly directMessageService: DirectMessageService,
    private readonly router: Router,
    private readonly partnerService: PartnerService,
    private readonly freeBetService: FreeBetService,
    private readonly navigationService: NavigationService,
    private readonly customerService: CustomerService,
    private readonly broadcastingService: BroadcastingService,
    private readonly localStorage: LocalStorageService,
    private readonly directMessageTrackingService: DirectMessageTrackingService,
    private readonly transactionPopupService: TransactionPopupService,
    private readonly smarticoService: SmarticoService,
    private readonly accountTrackingService: AccountTrackingService,
    private readonly i18nService: I18nService,
    @Inject(operatorConfigurationToken) private readonly operatorConfiguration: OperatorConfiguration,
    @Optional() protected readonly mediaService: MediaService
  ) {
    super();
  }

  ngOnInit(): void {
    this.initMediaListener();
    this.initDirectMessageState();
    this.initPartners();
    this.initUserState();
    this.initFreebetState();
  }

  ngOnDestroy(): void {
    clearInterval(this.interval);
    super.ngOnDestroy();
  }

  get isZendeskEnabled(): boolean {
    if (!window['zE']) {
      return false;
    }

    return this.operatorConfiguration.onlineConfiguration?.zendeskEnabled;
  }

  logout(): void {
    this.trackMenu('logout', 'ACCOUNT.LOGOUT', false);
    this.authService.logout();
    this.changed.emit(true);
  }

  deposit(): void {
    this.trackMenu('deposit', 'ACCOUNT.DEPOSIT', false);

    if (!this.enablePopupMethodDeposit) {
      this.navigationService.goToDeposit();
      return;
    }

    this.transactionPopupService.open(TransactionMode.Deposit);
  }

  withdrawal(): void {
    this.trackMenu('withdraw', 'ACCOUNT.WITHDRAW', false);

    if (!this.enablePopupMethodWithdrawal) {
      this.navigationService.goToWithdrawal();
      return;
    }

    this.transactionPopupService.open(TransactionMode.Withdraw);
  }

  toggleHideBalance(): void {
    if (!this.me || this.isUpdatingBalanceVisibility) {
      return;
    }

    this.isUpdatingBalanceVisibility = true;
    const newHideBalance: boolean = !this.me.hideBalance;
    this.trackMenu('show_balance', this.me.hideBalance ? 'ACCOUNT.SHOW_BALANCE' : 'ACCOUNT.HIDE_BALANCE', false);
    this.customerService
      .toggleHideBalance(newHideBalance)
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.isUpdatingBalanceVisibility = false;
          if (this.me) {
            this.me.hideBalance = newHideBalance;
            this.authService.refreshMe(this.me);
          }
          this.cdRef.markForCheck();
        })
      )
      .subscribe();
  }

  openMessagingWindow(): void {
    this.trackMenu('messages', 'ACCOUNT.DIRECT_MESSAGE', true);

    if (this.isZendeskEnabled) {
      window['zE']('messenger', 'show');
      window['zE']('messenger', 'open');
      return;
    }

    this.localStorage.setItem(this.LOCAL_STORAGE_KEY_DM, DirectMessageWidgetState.Open);
    this.broadcastingService.broadcast('open-direct-message-window');
    this.directMessageTrackingService.trackOpen('account');
  }

  trackMenu(name: string, translationKey: string, hasNotificationCount: boolean = false): void {
    this.accountTrackingService.trackMenuClick(
      name,
      this.me?.hideBalance ?? false,
      this.i18nService.translateSync(translationKey),
      hasNotificationCount
    );
  }

  private initMediaListener(): void {
    if (!this.mediaService) {
      return;
    }

    this.mediaService.media$.pipe(takeUntil(this.destroy$)).subscribe((screenSize: Media) => {
      const isAboveMediumScreen: boolean = screenSize > Media.md;
      const isOnMyAccountRoot: boolean = this.router.routerState.snapshot.url === '/myaccount';

      if (isAboveMediumScreen && isOnMyAccountRoot) {
        this.ngZone.run(() => this.router.navigate(['/myaccount/operations-history']));
      }
    });
  }

  private initDirectMessageState(): void {
    this.newDirectMessagesCount$ = this.directMessageService.unreadMessageCount;

    const hasDirectMessageFeature: boolean = this.operatorConfiguration.operatorFeatures?.includes(
      Feature.DirectMessage
    );

    if (!hasDirectMessageFeature) {
      this.displayMessagingLink = this.isZendeskEnabled;
      return;
    }

    this.directMessageService
      .getDirectMessageConfig()
      .pipe(takeUntil(this.destroy$))
      .subscribe(
        (config: CustomerDirectMessageConfiguration) => {
          this.displayMessagingLink = config.canViewDirectMessages;
          this.cdRef.markForCheck();
        },
        () => {
          this.displayMessagingLink = false;
        }
      );
  }

  private initPartners(): void {
    if (!this.operatorConfiguration.operatorFeatures?.includes(Feature.Partner)) {
      return;
    }

    this.partnerService
      .getCustomerPartners()
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: (partners: PaginatedResponse<Partner>) => {
          this.showPartners = partners.items.length > 0;
          this.cdRef.markForCheck();
        },
        error: () => {
          this.showPartners = false;
          this.cdRef.markForCheck();
        }
      });
  }

  private initUserState(): void {
    this.authService.me$.pipe(takeUntil(this.destroy$)).subscribe((me: Me) => {
      if (!me) {
        return;
      }

      this.me = me;
      this.isValidated = hasFlag(me.state, CustomerState.LoginValidated);
      this.hasInstantGamesFeature = this.operatorConfiguration.betCategories.includes(BetCategoryType.InstantGame);
      this.referralActive = this.operatorConfiguration.global.referralActive && me.referrerActive;
      this.cdRef.markForCheck();
    });
  }

  private initFreebetState(): void {
    this.openedFreebetCouponsCount$ = this.freeBetService.openedFreebetCouponsCount$;
  }
}
