import { BetLineStateType } from '../bet-history';
import { BetBuilderError } from './bet-builder-errors.model';

export const defaultProductName = 'MyCombo';

export interface BetBuilderEventItemIds {
  eventId: number;
  eventBetTypeItemIds: number[];
}

export interface BetBuilderInfo {
  tutorialCompleted?: boolean;
  isBetBuilderToggled?: boolean;
}

export interface BetBuilderOdds {
  odds: number;
  betBuilderError?: BetBuilderError;
  betBuilderErrorParameters?: string[];
}

export interface BetBuilderOddsResult extends BetBuilderEventItemIds {
  betBuilderOdds: BetBuilderOdds;
}

export interface BetBuilderLine {
  eventBetTypeId: number;
  eventBetTypeItemId: number;
  eventBetTypeName?: string;
  eventBetTypeItemName?: string;
  eventBetTypeItemOdds?: number;
  state: BetLineStateType;

  betBuilderError: BetBuilderError;
  betBuilderErrorParameters?: string[];

  betTypeId?: number;
  active?: boolean;
  isLive?: boolean;
  bettingAllowed?: boolean;
  isAsian?: boolean;
  canBeSimulated?: boolean;
}
