import {
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  EventEmitter,
  Inject,
  OnInit,
  Output
} from '@angular/core';
import { ResponsibleGamblingService } from '../../services/responsible-gambling.service';
import { SelfLimitation } from '../../models/self-limitation.model';
import { SelfLimitationProfile } from '../../models/self-limitation-profile.model';
import {
  BetCategoryType,
  CustomerGameAccountLimitationScope,
  CustomerGameAccountLimitationType
} from '@honoregaming/types';
import { forkJoin } from 'rxjs';
import { finalize, takeUntil } from 'rxjs/operators';
import { addHours, DestroySubject, happenBefore } from '@honoregaming/core';
import { CustomerOperatorConfiguration, customerOperatorConfigurationToken } from '@honoregaming/customer-core';
import { ResponsibleGamblingData } from '../../models/responsible-gambling-data.model';
import { CreateOrUpdateSelfLimitation } from '../../models/create-or-update-self-limitation.model';
import { MessageService } from '@honoregaming/ui';
import { ResponsibleGamblingConfirmationPopinComponent } from '../responsible-gambling-confirmation-popin/responsible-gambling-confirmation-popin.component';

@Component({
  selector: 'hg-responsible-gambling-self-limitation',
  templateUrl: './responsible-gambling-self-limitation.component.html',
  styleUrls: ['./responsible-gambling-self-limitation.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class ResponsibleGamblingSelfLimitationComponent extends DestroySubject implements OnInit {
  @Output()
  openAlert = new EventEmitter<{ errorMessageKey?: string }>();

  loading = false;
  limitation: string;
  currentProfile: SelfLimitationProfile;
  selfLimitationProfile = SelfLimitationProfile;
  currentLimitation: (SelfLimitation & { currentReachedAmount: number; isInProcessOfBeingModified?: boolean })[] = [];
  responsibleGamblingData: ResponsibleGamblingData;
  isModifyingAndHasNotError: boolean = true;
  minAndMaxLimitationsAmount = {
    minimumBetLimitationAmount: this.operatorConfiguration.responsibleGamblingConfiguration.minimumBetLimitationAmount,
    maximumBetLimitationAmount: this.operatorConfiguration.responsibleGamblingConfiguration.maximumBetLimitationAmount,
    minimumDepositLimitationAmount:
      this.operatorConfiguration.responsibleGamblingConfiguration.minimumDepositLimitationAmount,
    maximumDepositLimitationAmount:
      this.operatorConfiguration.responsibleGamblingConfiguration.maximumDepositLimitationAmount
  };

  limitations: (SelfLimitation & { isInProcessOfBeingModified?: boolean })[] = [];
  modifiedLimitations: SelfLimitation[] = [];

  constructor(
    private responsibleGamblingService: ResponsibleGamblingService,
    private cdRef: ChangeDetectorRef,
    private messageService: MessageService,
    @Inject(customerOperatorConfigurationToken) private operatorConfiguration: CustomerOperatorConfiguration
  ) {
    super();
  }

  ngOnInit(): void {
    this.load();
  }

  load() {
    this.loading = true;

    //capitalize the first letter of betCategeories as in the enum
    const customerCategoriesConfiguration =
      this.operatorConfiguration.responsibleGamblingConfiguration.customerCategoriesConfiguration;

    const updatedCustomerCategoriesConfiguration: { [key: string]: any } = {};

    const updatedAmateurBetCategoryConfiguration: { [key: string]: any } = {};
    const updatedBeginnerBetCategoryConfiguration: { [key: string]: any } = {};
    const updatedRegularBetCategoryConfiguration: { [key: string]: any } = {};

    Object.entries(customerCategoriesConfiguration).forEach(([key, value]) => {
      updatedCustomerCategoriesConfiguration[key.charAt(0).toUpperCase() + key.slice(1)] = value;

      Object.entries(value.betCategoriesConfiguration).forEach(([betCategoryKey, betCategoryValue]) => {
        if (key.toLowerCase() === this.selfLimitationProfile.Amateur.toLowerCase()) {
          updatedAmateurBetCategoryConfiguration[betCategoryKey.charAt(0).toUpperCase() + betCategoryKey.slice(1)] =
            betCategoryValue;
        }
        if (key.toLowerCase() === this.selfLimitationProfile.Beginner.toLowerCase()) {
          updatedBeginnerBetCategoryConfiguration[betCategoryKey.charAt(0).toUpperCase() + betCategoryKey.slice(1)] =
            betCategoryValue;
        }
        if (key.toLowerCase() === this.selfLimitationProfile.Regular.toLowerCase()) {
          updatedRegularBetCategoryConfiguration[betCategoryKey.charAt(0).toUpperCase() + betCategoryKey.slice(1)] =
            betCategoryValue;
        }
      });
    });

    this.operatorConfiguration.responsibleGamblingConfiguration.customerCategoriesConfiguration =
      updatedCustomerCategoriesConfiguration;

    this.operatorConfiguration.responsibleGamblingConfiguration.customerCategoriesConfiguration[
      this.selfLimitationProfile.Amateur
    ].betCategoriesConfiguration = updatedAmateurBetCategoryConfiguration;

    this.operatorConfiguration.responsibleGamblingConfiguration.customerCategoriesConfiguration[
      this.selfLimitationProfile.Beginner
    ].betCategoriesConfiguration = updatedBeginnerBetCategoryConfiguration;

    this.operatorConfiguration.responsibleGamblingConfiguration.customerCategoriesConfiguration[
      this.selfLimitationProfile.Regular
    ].betCategoriesConfiguration = updatedRegularBetCategoryConfiguration;

    const limitations = this.responsibleGamblingService.getLimitations();
    const responsibleGamblingData = this.responsibleGamblingService.getResponsibleGamblingData();

    forkJoin([limitations, responsibleGamblingData])
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          if (this.limitations.length > 0) {
            this.setProfile();
          }
          this.loading = false;
          this.cdRef.markForCheck();
        })
      )
      .subscribe(
        ([limitationsResponse, responsibleGamblingDataResponse]) => {
          if (limitationsResponse?.length > 0) {
            let tempLimitations: (SelfLimitation & { isInProcessOfBeingModified?: boolean })[] = [];
            limitationsResponse?.forEach(x => {
              var duplicateLimitation = tempLimitations.find(y => y.betCategoryType === x.betCategoryType);
              var index = tempLimitations.findIndex(y => y.betCategoryType === x.betCategoryType);
              if (duplicateLimitation) {
                if (duplicateLimitation.startDate < x.startDate) {
                  tempLimitations[index].isInProcessOfBeingModified = true;
                  this.modifiedLimitations.push(x);
                }
              } else {
                tempLimitations.push(x);
              }
            });

            this.limitations[0] = tempLimitations?.find(x => !x.betCategoryType);
            this.limitations[1] = tempLimitations?.find(x => x.betCategoryType === BetCategoryType.VirtualFixedOdds);
            this.limitations[2] = tempLimitations?.find(x => x.betCategoryType === BetCategoryType.SportsFixedOdds);
            this.limitations[3] = tempLimitations?.find(x => x.betCategoryType === BetCategoryType.InstantGame);
            this.limitations[4] = tempLimitations?.find(
              x =>
                x.betCategoryType === BetCategoryType.HorseRacingMutualInternationalPool ||
                x.betCategoryType === BetCategoryType.HorseRacingMutualOperatorPool
            );
            this.limitations[5] = tempLimitations?.find(x => x.betCategoryType === BetCategoryType.DrawGame);
          }

          this.responsibleGamblingData = responsibleGamblingDataResponse;
        },
        _ => {
          this.openAlert.emit({ errorMessageKey: 'COMMON.ERROR' });
        }
      );
  }

  setProfile(profile: SelfLimitationProfile = null) {
    this.currentProfile = profile
      ? profile
      : this.limitations.filter(x => !!x).find(x => x.profileType === SelfLimitationProfile.Custom) ||
        this.modifiedLimitations.length > 0
      ? SelfLimitationProfile.Custom
      : this.limitations.filter(x => !!x).find(x => x.profileType !== null)?.profileType;

    this.currentLimitation = [];

    this.isModifyingAndHasNotError = this.currentProfile === profile || profile === null;
    if (this.currentProfile != SelfLimitationProfile.Custom) {
      const configurations =
        this.operatorConfiguration.responsibleGamblingConfiguration.customerCategoriesConfiguration[this.currentProfile]
          .betCategoriesConfiguration;

      if (this.operatorConfiguration.responsibleGamblingConfiguration.depositLimitationActive) {
        const depositLimitation: SelfLimitation & {
          currentReachedAmount: number;
        } = {
          amount:
            this.operatorConfiguration.responsibleGamblingConfiguration.customerCategoriesConfiguration[
              this.currentProfile
            ].depositLimitationAmount,
          profileType: this.currentProfile,
          type: CustomerGameAccountLimitationType.Self,
          currentReachedAmount: this.getCurrentReachedAmount(null),
          scope: CustomerGameAccountLimitationScope.Deposit
        };

        this.currentLimitation.push(depositLimitation);
      }

      this.currentLimitation[1] = configurations[BetCategoryType.VirtualFixedOdds]?.betLimitationActive
        ? {
            betCategoryType: BetCategoryType.VirtualFixedOdds,
            amount: configurations[BetCategoryType.VirtualFixedOdds].betLimitationAmount,
            profileType: profile,
            type: CustomerGameAccountLimitationType.Self,
            currentReachedAmount: this.getCurrentReachedAmount(BetCategoryType.VirtualFixedOdds),
            scope: CustomerGameAccountLimitationScope.Betting
          }
        : null;

      this.currentLimitation[2] = configurations[BetCategoryType.SportsFixedOdds]?.betLimitationActive
        ? {
            betCategoryType: BetCategoryType.SportsFixedOdds,
            amount: configurations[BetCategoryType.SportsFixedOdds].betLimitationAmount,
            profileType: profile,
            type: CustomerGameAccountLimitationType.Self,
            currentReachedAmount: this.getCurrentReachedAmount(BetCategoryType.SportsFixedOdds),
            scope: CustomerGameAccountLimitationScope.Betting
          }
        : null;

      this.currentLimitation[3] = configurations[BetCategoryType.InstantGame]?.betLimitationActive
        ? {
            betCategoryType: BetCategoryType.InstantGame,
            amount: configurations[BetCategoryType.InstantGame].betLimitationAmount,
            profileType: profile,
            type: CustomerGameAccountLimitationType.Self,
            currentReachedAmount: this.getCurrentReachedAmount(BetCategoryType.InstantGame),
            scope: CustomerGameAccountLimitationScope.Betting
          }
        : null;
      this.currentLimitation[4] =
        configurations[BetCategoryType.HorseRacingMutualInternationalPool]?.betLimitationActive ||
        configurations[BetCategoryType.HorseRacingMutualOperatorPool]?.betLimitationActive
          ? {
              betCategoryType: BetCategoryType.HorseRacingMutualOperatorPool,
              amount:
                configurations[BetCategoryType.HorseRacingMutualInternationalPool].betLimitationAmount ||
                configurations[BetCategoryType.HorseRacingMutualOperatorPool].betLimitationAmount,
              profileType: profile,
              type: CustomerGameAccountLimitationType.Self,
              currentReachedAmount:
                this.getCurrentReachedAmount(BetCategoryType.HorseRacingMutualInternationalPool) ||
                this.getCurrentReachedAmount(BetCategoryType.HorseRacingMutualOperatorPool),
              scope: CustomerGameAccountLimitationScope.Betting
            }
          : null;
      this.currentLimitation[5] = configurations[BetCategoryType.DrawGame]?.betLimitationActive
        ? {
            betCategoryType: BetCategoryType.DrawGame,
            amount: configurations[BetCategoryType.DrawGame].betLimitationAmount,
            profileType: profile,
            type: CustomerGameAccountLimitationType.Self,
            currentReachedAmount: this.getCurrentReachedAmount(BetCategoryType.DrawGame),
            scope: CustomerGameAccountLimitationScope.Betting
          }
        : null;

      this.currentLimitation = this.currentLimitation.filter(l => l !== null);
    } else {
      this.currentLimitation[0] = {
        betCategoryType: null,
        amount: this.minAndMaxLimitationsAmount.minimumDepositLimitationAmount,
        profileType: SelfLimitationProfile.Custom,
        type: CustomerGameAccountLimitationType.Self,
        currentReachedAmount: this.getCurrentReachedAmount(null),
        scope: CustomerGameAccountLimitationScope.Deposit
      };
      this.currentLimitation[1] = {
        betCategoryType: BetCategoryType.VirtualFixedOdds,
        amount: this.minAndMaxLimitationsAmount.minimumBetLimitationAmount,
        profileType: SelfLimitationProfile.Custom,
        type: CustomerGameAccountLimitationType.Self,
        currentReachedAmount: this.getCurrentReachedAmount(BetCategoryType.VirtualFixedOdds),
        scope: CustomerGameAccountLimitationScope.Betting
      };
      this.currentLimitation[2] = {
        betCategoryType: BetCategoryType.SportsFixedOdds,
        amount: this.minAndMaxLimitationsAmount.minimumBetLimitationAmount,
        profileType: SelfLimitationProfile.Custom,
        type: CustomerGameAccountLimitationType.Self,
        currentReachedAmount: this.getCurrentReachedAmount(BetCategoryType.SportsFixedOdds),
        scope: CustomerGameAccountLimitationScope.Betting
      };
      this.currentLimitation[3] = {
        betCategoryType: BetCategoryType.InstantGame,
        amount: this.minAndMaxLimitationsAmount.minimumBetLimitationAmount,
        profileType: SelfLimitationProfile.Custom,
        type: CustomerGameAccountLimitationType.Self,
        currentReachedAmount: this.getCurrentReachedAmount(BetCategoryType.InstantGame),
        scope: CustomerGameAccountLimitationScope.Betting
      };
      this.currentLimitation[4] = {
        betCategoryType: BetCategoryType.HorseRacingMutualInternationalPool,
        amount: this.minAndMaxLimitationsAmount.minimumBetLimitationAmount,
        profileType: SelfLimitationProfile.Custom,
        type: CustomerGameAccountLimitationType.Self,
        currentReachedAmount: this.getCurrentReachedAmount(BetCategoryType.HorseRacingMutualOperatorPool),
        scope: CustomerGameAccountLimitationScope.Betting
      };
      this.currentLimitation[5] = {
        betCategoryType: BetCategoryType.DrawGame,
        amount: this.minAndMaxLimitationsAmount.minimumBetLimitationAmount,
        profileType: SelfLimitationProfile.Custom,
        type: CustomerGameAccountLimitationType.Self,
        currentReachedAmount: this.getCurrentReachedAmount(BetCategoryType.DrawGame),
        scope: CustomerGameAccountLimitationScope.Betting
      };

      if (this.limitations.length > 0) {
        this.limitations.forEach(x => {
          if (!x) {
            return;
          }

          const limitation: SelfLimitation & { currentReachedAmount: number; isInProcessOfBeingModified?: boolean } = {
            betCategoryType: x.betCategoryType ?? null,
            amount: x.amount,
            currentReachedAmount: this.getCurrentReachedAmount(x.betCategoryType),
            profileType: x.profileType,
            type: x.type,
            id: x.id,
            scope: x.scope,
            startDate: x.startDate,
            isInProcessOfBeingModified: x.isInProcessOfBeingModified,
            modified: x.modified
          };

          const index = this.currentLimitation.findIndex(l => l.betCategoryType === limitation.betCategoryType);

          this.currentLimitation.splice(index, 1, limitation);
        });
      }
    }

    this.cdRef.markForCheck();
  }

  getCurrentReachedAmount(betCategory: BetCategoryType) {
    switch (betCategory) {
      case BetCategoryType.SportsFixedOdds:
        return this.responsibleGamblingData.sportStake;
      case BetCategoryType.HorseRacingMutualInternationalPool:
      case BetCategoryType.HorseRacingMutualOperatorPool:
        return this.responsibleGamblingData.horseRacingStake;
      case BetCategoryType.InstantGame:
        return this.responsibleGamblingData.instantGameStake;
      case BetCategoryType.DrawGame:
        return this.responsibleGamblingData.drawGameStake;
      case BetCategoryType.VirtualFixedOdds:
        return this.responsibleGamblingData.virtualStake;
      default:
        return this.responsibleGamblingData.deposit;
    }
  }

  createOrUpdateLimitation() {
    let items: CreateOrUpdateSelfLimitation[] = [];

    this.currentLimitation.forEach(x => {
      var limit: CreateOrUpdateSelfLimitation = {
        id: x?.id,
        amount: x.amount,
        scope: x.scope,
        betCategoryId: this.getBetCatgoryId(x.betCategoryType)
      };

      items.push(limit);
    });

    this.loading = true;
    this.responsibleGamblingService
      .createOrUpdateLimitation({ selfLimitations: items, profileType: this.currentProfile })
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.openAlert.emit();
          this.loading = false;
          this.cdRef.markForCheck();
        })
      )
      .subscribe(
        _ => {
          this.load();
        },
        _ => {
          this.openAlert.emit({ errorMessageKey: 'COMMON.ERROR' });
        }
      );
  }

  openPopin() {
    if (this.isModifyingAndHasNotError) {
      this.messageService
        .sendComponentMessage(ResponsibleGamblingConfirmationPopinComponent, {
          isSelfLimitation: true
        })
        .closed.subscribe(data => {
          if (data?.confirmed) {
            this.createOrUpdateLimitation();
          }
        });
    }
  }

  getBetCatgoryId(betCategory: BetCategoryType) {
    switch (betCategory) {
      case BetCategoryType.SportsFixedOdds:
        return 3;
      case BetCategoryType.DrawGame:
        return 4;
      case BetCategoryType.HorseRacingMutualInternationalPool:
      case BetCategoryType.HorseRacingMutualOperatorPool:
        return 1;
      case BetCategoryType.InstantGame:
        return 8;
      case BetCategoryType.VirtualFixedOdds:
        return 5;
      default:
        return null;
    }
  }

  inputIsModifyedAndhasNotError(value: boolean) {
    this.isModifyingAndHasNotError = value;
  }

  canEditLimitations(betCategories?: BetCategoryType[]): boolean {
    const limitationLockDurationInHours =
      this.operatorConfiguration?.responsibleGamblingConfiguration?.delayForCustomerLimitationChangeInHours;

    if (limitationLockDurationInHours > 0) {
      const now = new Date();

      if (betCategories?.length === 1) {
        // Check if specific limitation has to be locked
        const lastModified = this.currentLimitation.find(x => x.betCategoryType === betCategories[0])?.modified;

        if (lastModified) {
          const limitLock = addHours(new Date(lastModified), limitationLockDurationInHours);
          return happenBefore(now, limitLock, 0);
        } else {
          return true;
        }
      } else {
        // Check if update possible (at least one limitation new or after lock range)
        return !this.currentLimitation.every(limitation => {
          const lastModified = limitation.modified;
          if (lastModified) {
            const limitLock = addHours(new Date(lastModified), limitationLockDurationInHours);
            return happenBefore(limitLock, now, 0);
          } else {
            return false;
          }
        });
      }
    } else {
      return true;
    }
  }
}
