import { Injectable } from '@angular/core';
import { CanActivate, ActivatedRouteSnapshot } from '@angular/router';
import { Observable } from 'rxjs';
import { map, take } from 'rxjs/operators';
import { ValidatedError } from '../errors';
import { DirectMessageService } from '@honoregaming/customer-core';

@Injectable()
export class DirectMessageGuard implements CanActivate {
  constructor(private directmessageService: DirectMessageService) {}

  canActivate(_route: ActivatedRouteSnapshot): Observable<boolean> {
    return this.directmessageService.getDirectMessageConfig().pipe(
      take(1),
      map(
        x => {
          return x.canViewDirectMessages;
        },
        () => false
      ),
      map(x => {
        if (x) {
          return x;
        }
        throw new ValidatedError();
      })
    );
  }
}
