import { NgModule, ModuleWithProviders, ErrorHandler, Injector } from '@angular/core';
import { CommonModule } from '@angular/common';
import { AuthService, RoutingEventsService } from './services';
import { AuthenticationGuard } from './guards/authentication.guard';
import { HTTP_INTERCEPTORS } from '@angular/common/http';
import { AuthInterceptor } from './interceptors/auth.interceptor';
import { authenticationErrorsHandlerFactory } from './authentication-errors.handler';

@NgModule({
  imports: [CommonModule]
})
export class HgAuthenticationModule {
  static forRoot(): ModuleWithProviders<HgAuthenticationModule> {
    return {
      ngModule: HgAuthenticationModule,
      providers: [
        AuthService,
        AuthenticationGuard,
        RoutingEventsService,
        { provide: HTTP_INTERCEPTORS, useClass: AuthInterceptor, multi: true },
        {
          provide: ErrorHandler,
          useFactory: authenticationErrorsHandlerFactory,
          deps: [Injector]
        }
      ]
    };
  }
}
