import {
  Directive,
  TemplateRef,
  ViewContainerRef,
  OnDestroy,
  Optional,
  ChangeDetectorRef,
  Input,
  OnInit,
  NgZone
} from '@angular/core';
import { MediaService } from '../services/media.service';
import { Media } from '../enum/media.enum';
import { Subscription } from 'rxjs';

@Directive({
  selector: '[hgMediaIf]'
})
export class MediaIfDirective implements OnDestroy, OnInit {
  @Input() hgMediaIfSsr = false;
  @Input() hgMediaIf: keyof typeof Media;

  private hasView = false;
  private subscription: Subscription;
  constructor(
    private templateRef: TemplateRef<any>,
    private viewContainer: ViewContainerRef,
    private cdRef: ChangeDetectorRef,
    private zone: NgZone,
    @Optional() private mediaService: MediaService
  ) {}

  ngOnInit(): void {
    this.listen(Media[this.hgMediaIf]);
  }

  listen(media: Media) {
    if (this.mediaService) {
      this.subscription = this.mediaService.media$.subscribe(x => {
        this.zone.run(() => {
          if (x <= media && !this.hasView) {
            this.viewContainer.createEmbeddedView(this.templateRef);
            this.hasView = true;
          } else if (x > media && this.hasView) {
            this.viewContainer.clear();
            this.hasView = false;
          }
          this.cdRef.markForCheck();
        });
      });
    } else if (this.hgMediaIfSsr) {
      this.viewContainer.createEmbeddedView(this.templateRef);
      this.hasView = true;
      this.cdRef.markForCheck();
    }
  }

  ngOnDestroy(): void {
    // tslint:disable-next-line:no-unused-expression
    this.subscription && this.subscription.unsubscribe();
  }
}

@Directive({
  selector: '[hgMediaIfNot]'
})
export class MediaIfNotDirective implements OnDestroy, OnInit {
  @Input() hgMediaIfNotSsr = false;
  @Input() hgMediaIfNot: keyof typeof Media;

  private hasView = false;
  private subscription: Subscription;
  constructor(
    private templateRef: TemplateRef<any>,
    private viewContainer: ViewContainerRef,
    private cdRef: ChangeDetectorRef,
    private zone: NgZone,
    @Optional() private mediaService: MediaService
  ) {}

  ngOnInit(): void {
    this.listenInvert(Media[this.hgMediaIfNot]);
  }

  private listenInvert(media: Media) {
    if (this.mediaService) {
      this.subscription = this.mediaService.media$.subscribe(x => {
        this.zone.run(() => {
          if (x > media && !this.hasView) {
            this.viewContainer.createEmbeddedView(this.templateRef);
            this.hasView = true;
          } else if (x <= media && this.hasView) {
            this.viewContainer.clear();
            this.hasView = false;
          }
          this.cdRef.markForCheck();
        });
      });
    } else if (this.hgMediaIfNotSsr) {
      this.viewContainer.createEmbeddedView(this.templateRef);
      this.cdRef.markForCheck();
      this.hasView = true;
    }
  }

  ngOnDestroy(): void {
    // tslint:disable-next-line:no-unused-expression
    this.subscription && this.subscription.unsubscribe();
  }
}
