import { ITelemetryService } from './telemetry-service.model';
import { Injectable, Inject, PLATFORM_ID } from '@angular/core';
import { customerOperatorConfigurationToken, CustomerOperatorConfiguration } from '../../models';
import { DOCUMENT, isPlatformBrowser } from '@angular/common';
import { Router } from '@angular/router';
declare var fbq: any;

@Injectable()
export class FacebookPixelTelemetryService implements ITelemetryService {
  isBrowser = isPlatformBrowser(this.platformId);

  constructor(
    @Inject(customerOperatorConfigurationToken) private operatorConfig: CustomerOperatorConfiguration,
    @Inject(DOCUMENT) private document: Document,
    @Inject(PLATFORM_ID) private platformId,
    private router: Router
  ) {
    this.initialize();

    if (isPlatformBrowser(this.platformId)) {
      if (this.isLoaded()) {
        this.trackPageView(this.router.url, this.router.url);
      }
    }
  }

  initialize(): void {
    if (this.isLoaded()) {
      console.warn(
        'Tried to initialize a Pixel instance while another is already active. Please call `remove()` before initializing a new instance.'
      );
      return;
    }

    this.addPixelScript(this.operatorConfig.telemetryConfiguration.facebook.trackingId);
  }

  trackPageView(name: string, path: string): void {
    if (!isPlatformBrowser(this.platformId)) {
      return;
    }

    if (!this.isLoaded()) {
      console.warn('Tried to track an event without initializing a Pixel instance. Call `initialize()` first.');
      return;
    }

    fbq('track', 'PageView', { name, path });
  }

  trackEvent(name: string, properties: any): void {
    if (!isPlatformBrowser(this.platformId)) {
      return;
    }

    if (!this.isLoaded()) {
      console.warn('Tried to track an event without initializing a Pixel instance. Call `initialize()` first.');
      return;
    }

    fbq('trackCustom', name, properties);
  }

  private addPixelScript(pixelId: string): void {
    if (!isPlatformBrowser(this.platformId)) {
      return;
    }

    const pixelCode = `
    !function(f,b,e,v,n,t,s)
    {if(f.fbq)return;n=f.fbq=function(){n.callMethod?
    n.callMethod.apply(n,arguments):n.queue.push(arguments)};
    if(!f._fbq)f._fbq=n;n.push=n;n.loaded=!0;n.version='2.0';
    n.queue=[];t=b.createElement(e);t.async=!0;
    t.src=v;s=b.getElementsByTagName(e)[0];
    s.parentNode.insertBefore(t,s)}(window, document,'script',
    'https://connect.facebook.net/en_US/fbevents.js');
    fbq('init', '${pixelId}');
    fbq('track', 'PageView');`;

    const pixelNoScript = `<img height="1" width="1" style="display:none"
     src="https://www.facebook.com/tr?id=${pixelId}&ev=PageView&noscript=1"/>`;

    const scriptElement = this.document.createElement('script');
    scriptElement.id = 'pixel-script';
    scriptElement.type = 'text/javascript';
    scriptElement.innerHTML = pixelCode;

    const noScriptElement = this.document.createElement('noscript');
    noScriptElement.innerHTML = pixelNoScript;

    this.document.body.appendChild(scriptElement);
    this.document.body.appendChild(noScriptElement);
  }

  private isLoaded(): boolean {
    if (isPlatformBrowser(this.platformId)) {
      const pixelElement = this.document.getElementById('pixel-script');
      return !!pixelElement;
    }
    return false;
  }
}
