import {
  Component,
  OnInit,
  ChangeDetectionStrategy,
  Input,
  ChangeDetectorRef,
  Inject,
  Output,
  EventEmitter
} from '@angular/core';
import { templateServiceToken, ITemplateService } from '../services/template.service';
import { Template } from '@honoregaming/types';

@Component({
  selector: 'hg-anchor',
  templateUrl: './anchor.component.html',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class AnchorComponent implements OnInit {
  @Input()
  anchor: string;

  @Input()
  multiple = false;

  @Output() hasAnchor = new EventEmitter<boolean>();

  templates: Template[];

  constructor(
    @Inject(templateServiceToken) private templateService: ITemplateService,
    private cdRef: ChangeDetectorRef
  ) {}

  ngOnInit(): void {
    this.templateService.getTemplatesForAnchor(this.anchor).subscribe(templates => {
      if (this.multiple) {
        this.templates = templates;
      } else {
        this.templates = templates.length ? [templates[0]] : [];
      }

      this.hasAnchor.emit(!!this.templates?.length);

      this.cdRef.markForCheck();
    });
  }
}
