import { HttpEvent, HttpHandler, HttpInterceptor, HttpRequest } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { Observable } from 'rxjs';
import { mergeMap, catchError } from 'rxjs/operators';
import { AuthService } from '../services';
import { globalConfiguration } from '@honoregaming/configuration';

@Injectable()
export class AutInterceptor implements HttpInterceptor {
  constructor(private authService: AuthService) {}

  public intercept(req: HttpRequest<any>, next: HttpHandler): Observable<HttpEvent<any>> {
    if (
      (globalConfiguration.apiBaseUrl ||
        globalConfiguration.apiBettingBaseUrl ||
        globalConfiguration.apiPaymentProviderBaseUrl) &&
      !req.url.endsWith('/authentication/refresh') &&
      (req.url.startsWith(globalConfiguration.apiBaseUrl) ||
        req.url.startsWith(globalConfiguration.apiBettingBaseUrl) ||
        req.url.startsWith(globalConfiguration.apiEventsBaseUrl) ||
        req.url.startsWith(globalConfiguration.apiPaymentProviderBaseUrl)) &&
      this.authService.isAuthenticated()
    ) {
      return this.authService.getToken().pipe(
        this.addToken(req, next),
        catchError(err => {
          if (err.status === 401) {
            return this.authService.refresh().pipe(this.addToken(req, next));
          } else {
            throw err;
          }
        })
      );
    }

    return next.handle(req);
  }

  private addToken = (req: HttpRequest<any>, next: HttpHandler) =>
    mergeMap(token => {
      if (token) {
        req = req.clone({
          setHeaders: { Authorization: `Bearer ${token}` }
        });
      }
      return next.handle(req);
      // tslint:disable-next-line:semicolon
    });
}
