export interface BetLine {
  betCategoryType: BetCategoryType;
  eventType?: EventType;
  eventId?: number;
  eventName?: string;
  eventDate?: Date | string;
  entryPointId?: number;

  state?: BetLineStateType;

  oddsBoostId?: number;
  oddsBoost?: OddsBoost;

  manualOddsBoostId?: number;
  manualOddsBoost?: ManualOddsBoost;

  eventHomeTeamName?: string;
  eventAwayTeamName?: string;
  isLive?: boolean;
  categories?: string[];
  displayId?: number;

  betTypeId?: number;
  eventBetTypeId?: number;
  eventBetTypeName?: string;
  isAsian?: boolean;
  eventBetTypeItemId?: number;
  eventBetTypeItemName?: string;
  bettingAllowed?: boolean;
  odds?: number;
  newOdds?: number;
  newStake?: number;
  maxOdds?: number;
  baseList?: string[];
  combinations?: { baseList: string[]; fixedOdds: number }[];
  quickPick?: boolean;
  number?: number;
  canBeSimulated?: boolean;
  isBetCompletion?: boolean;

  // DrawGame
  baseSelectionLength?: number;
  extraList?: string[];
  extraSelectionLength?: number;
  minBaseSelection?: number;
  minExtraSelection?: number;
  extraNumberEnabled?: boolean;
  allowedMultipliers?: number[];
  drawGameDetails?: DrawGameDetails[];
  option?: number;
  associatedDrawGamesIds?: number[];

  // HorseRacing
  flexi?: HorseRacingFlexi;
  meeting?: { number: number; name: string };
  runners?: HorseRaceRunner[];
  formula?: Formula;
  eventNumber?: number;
  associatedList?: string[];
  allOrders?: boolean;
  multiValue?: number;
  replacementHorse?: number;
  multipliers?: { value: number; label: string }[];
  multiplier?: number;
  selectionLength?: number;
  baseStake?: number;
  totalStake?: number;
  baseListMaximumLengthOffset?: number;
  iconUrl?: string;
  booster?: boolean;

  // SportsPool
  poolAmount?: number;
  matchCount?: number;
  sportsPoolGameId?: number;
  selectedSportsPoolGameItems?: SelectedSportsPoolGameItem[];
  flashType?: SportsPoolFlashType;
  maxPayout?: number;

  active?: boolean;
  leftoverBalanceAmount?: number;
  baseAmount: number;
  minimumAmountIncrement?: number;
  maximumAmount: number;

  failure?: BetLineFailure;
  betStop?: boolean;

  betBuilderLines?: BetBuilderLine[];
  isBetBuilder?: boolean;
  allowBetBuilder?: boolean;
}

export interface BetLineWithEvent {
  betLine: BetLine;
  event: EventWithEventBetTypes<Match>;
}

// toDo:: Step by step move followed function to bet lines mapper service

export function createBetLine(
  event: Event,
  eventBetType: EventBetType,
  eventBetTypeItem: EventBetTypeItem,
  betCategoryType: BetCategoryType,
  eventCategoryName?: string
): BetLine {
  const betLine: BetLine = {
    betCategoryType: betCategoryType,
    eventType: event.eventType,
    eventId: event.id,
    eventName: event.name,
    eventDate: event.expectedStart,
    entryPointId: event.entryPointId,
    active: eventBetType.active,
    bettingAllowed: eventBetType.bettingAllowed,
    betTypeId: eventBetType.betTypeId,
    isAsian: eventBetType.isAsian,
    eventBetTypeId: eventBetType.id,
    eventBetTypeItemId: eventBetTypeItem.id,
    eventBetTypeName: eventBetType.name,
    eventBetTypeItemName: eventBetTypeItem.longName || eventBetTypeItem.shortName,
    odds: eventBetTypeItem.odds,
    baseAmount: eventBetType.baseAmount,
    minimumAmountIncrement: eventBetType.minimumAmountIncrement,
    maximumAmount: eventBetType.maximumAmount,
    displayId: event.displayId,
    iconUrl: eventBetType.iconUrl,
    canBeSimulated: eventBetType.canBeSimulated && eventBetTypeItem.canBeSimulated && event.canBeSimulated,
    allowBetBuilder: eventBetType.allowBetBuilder
  };

  if (betLine.eventType === EventType.Match) {
    betLine.eventName = `${(<Match>event).homeTeamName} - ${(<Match>event).awayTeamName}`;
    betLine.eventHomeTeamName = (<Match>event).homeTeamName;
    betLine.eventAwayTeamName = (<Match>event).awayTeamName;
    betLine.isLive = eventBetType.betTypeId > 20000 && eventBetType.betTypeId < 30000;
    betLine.categories = (<Match>event).categories;
  }

  if (eventCategoryName && betLine.eventType === EventType.NumbersGame) {
    betLine.eventName = eventCategoryName;
  }

  return betLine;
}

export function createOddsBoostBetLine(oddsBoost: OddsBoost) {
  const betLine: BetLine = {
    betCategoryType: BetCategoryType.SportsFixedOdds,
    active: !oddsBoost.details.some(d => !d.eventBetType.active),
    bettingAllowed: !oddsBoost.details.some(d => !d.eventBetType.bettingAllowed),
    oddsBoostId: oddsBoost.id,
    oddsBoost: oddsBoost,
    odds: oddsBoost.fixedOdds,
    baseAmount: !!oddsBoost.customerMinAmount
      ? oddsBoost.customerMinAmount
      : Math.max(...oddsBoost.details.map(l => l.eventBetType.baseAmount)),
    maximumAmount: !!oddsBoost.customerMaxAmount
      ? oddsBoost.customerMaxAmount
      : Math.min(...oddsBoost.details.map(l => l.eventBetType.maximumAmount)),
    minimumAmountIncrement: !!oddsBoost.customerIncrement
      ? oddsBoost.customerIncrement
      : oddsBoost.details.length >= 2
      ? ppcmArr(oddsBoost.details.map(l => l.eventBetType.minimumAmountIncrement))
      : oddsBoost.details[0].eventBetType.minimumAmountIncrement
  };

  return betLine;
}

export function createManualOddsBoostBetLine(manualOddsBoost: ManualOddsBoost) {
  const betLine: BetLine = {
    active: manualOddsBoost.active,
    bettingAllowed: true,
    betCategoryType: BetCategoryType.SportsFixedOdds,
    manualOddsBoostId: manualOddsBoost.id,
    manualOddsBoost: manualOddsBoost,
    odds: manualOddsBoost.fixedOdds,
    baseAmount: manualOddsBoost.baseAmount,
    maximumAmount: manualOddsBoost.maximumAmount,
    minimumAmountIncrement: manualOddsBoost.minimumAmountIncrement,
    entryPointId: manualOddsBoost.entryPointId,
    eventId: manualOddsBoost.eventId
  };
  return betLine;
}

export function createBetLineWithSelection(
  event: Event,
  eventBetType: EventBetType,
  baseList: string[],
  extraList: string[],
  betCategoryType: BetCategoryType,
  drawGameRule: DrawGameRule = null,
  odds: number = null,
  combinations: { baseList: string[]; fixedOdds: number }[] = null,
  stakeMultiplier?: number,
  maxOdds?: number,
  eventCategoryName?: string,
  option?: number,
  associatedDrawGamesIds?: number[]
): BetLine {
  if (eventBetType.betTypeId === DrawGameBorletteBetType.DoubChans && (associatedDrawGamesIds?.length ?? 0) === 0) {
    return undefined;
  }

  const betLine: BetLine = {
    betCategoryType: betCategoryType,
    eventType: event.eventType,
    eventId: event.id,
    eventName: event.name,
    eventDate: event.expectedStart,
    entryPointId: event.entryPointId,
    active: eventBetType.active,
    bettingAllowed: eventBetType.bettingAllowed,
    betTypeId: eventBetType.betTypeId,
    isAsian: eventBetType.isAsian,
    eventBetTypeId: eventBetType.id,
    eventBetTypeName: eventBetType.name,
    baseAmount: eventBetType.baseAmount,
    minimumAmountIncrement: eventBetType.minimumAmountIncrement,
    maximumAmount: eventBetType.maximumAmount,
    baseList: baseList,
    extraList: extraList,
    odds: odds,
    maxOdds: maxOdds,
    displayId: event.displayId,
    combinations: combinations,
    multiplier: stakeMultiplier || 1,
    baseSelectionLength: baseList?.length,
    extraSelectionLength: extraList?.length,
    minBaseSelection: drawGameRule?.minBaseSelection,
    minExtraSelection: drawGameRule?.minExtraSelection,
    extraNumberEnabled: drawGameRule?.extraNumberEnabled,
    allowedMultipliers: drawGameRule?.allowedMultipliers,
    drawGameDetails: drawGameRule?.drawGameDetails,
    option,
    associatedDrawGamesIds
  };

  if (eventCategoryName && betLine.eventType === EventType.NumbersGame) {
    betLine.eventName = eventCategoryName;
  }

  if (betLine.eventType === EventType.Match) {
    betLine.eventName = `${(<Match>event).homeTeamName} - ${(<Match>event).awayTeamName}`;
    betLine.eventHomeTeamName = (<Match>event).homeTeamName;
    betLine.eventAwayTeamName = (<Match>event).awayTeamName;
    betLine.isLive = (<Match>event).preEventOrLive === PreEventOrLiveType.Live;
    betLine.categories = (<Match>event).categories;
  }

  return betLine;
}

export function createHorseRaceBetLine(
  event: HorseRace,
  eventBetType: HorseRaceEventBetType,
  baseList: string[],
  associatedList?: string[],
  formula?: Formula,
  allOrders?: boolean,
  replacementHorse?: number,
  stakeMultiplier?: number,
  quickPick?: boolean,
  allowedMultipliers?: number[]
): BetLine {
  const betLine: BetLine = {
    betCategoryType: eventBetType.betCategoryType,
    eventType: event.eventType,
    eventId: event.id,
    eventName: event.name,
    eventDate: event.expectedStart,
    eventNumber: event.number,
    entryPointId: event.entryPointId,
    active: eventBetType.active,
    bettingAllowed: eventBetType.bettingAllowed,
    betTypeId: eventBetType.betTypeId,
    isAsian: eventBetType.isAsian,
    eventBetTypeId: eventBetType.id,
    eventBetTypeName: eventBetType.name,
    baseAmount: eventBetType.baseAmount,
    minimumAmountIncrement: eventBetType.minimumAmountIncrement,
    maximumAmount: eventBetType.maximumAmount,
    meeting: event.meeting,
    runners: event.runners,
    formula: formula,
    baseList: baseList,
    associatedList: associatedList,
    allOrders: allOrders,
    multiValue: formula.multiValues?.[0],
    replacementHorse: replacementHorse,
    multiplier: stakeMultiplier || 1,
    baseStake: eventBetType.baseAmount,
    quickPick: quickPick,
    multipliers: [],
    allowedMultipliers: allowedMultipliers,
    flexi: eventBetType.flexi,
    selectionLength: formula.multiValues?.[0] || horseRaceBetTypesConfiguration[eventBetType.betTypeId].selectionNumber,
    iconUrl: eventBetType.iconUrl,
    booster: eventBetType.booster
  };

  return betLine;
}

export function createSportsPoolBetLine(
  event: SportsPoolGame,
  selectedItems: SelectedSportsPoolGameItem[],
  stakes: number,
  flashType: SportsPoolFlashType
): BetLine {
  const betLine: BetLine = {
    betCategoryType: BetCategoryType.SportsPool,
    baseAmount: stakes,
    maximumAmount: stakes,
    eventType: EventType.SportsPool,
    eventBetTypeId: event.eventBetTypeId,
    entryPointId: event.entryPointId,
    eventDate: event.expectedStart,
    eventName: event.details.name,
    poolAmount: event.details.poolAmount,
    eventBetTypeName: event.name,
    matchCount: event.details.matchCount,
    selectedSportsPoolGameItems: selectedItems.map(item => ({ ...item })),
    flashType: flashType,
    maxPayout: event.details.poolRepartitions[0].prize,
    minimumAmountIncrement: 1,
    sportsPoolGameId: event.id
  };

  return betLine;
}
