import { Injectable } from '@angular/core';
import { NavigationEnd, Router } from '@angular/router';
import { BehaviorSubject, combineLatest, Observable, Subject } from 'rxjs';
import { filter, map, startWith, takeUntil, tap } from 'rxjs/operators';
import { DestroySubject } from '@honoregaming/core';
import { Media, MediaService } from '@honoregaming/ui';

@Injectable()
export class NavBarService extends DestroySubject {
  private static readonly MY_BETS_HISTORY_ROUTES: readonly string[] = [
    '/myaccount/history',
    '/myaccount/instant-games-history',
    '/myaccount/sportspool-history',
    '/myaccount/simulate-bets-history'
  ];

  private readonly navBarActiveSubject$ = new BehaviorSubject<boolean>(true);
  navBarActive$: Observable<boolean> = this.navBarActiveSubject$.asObservable();
  private readonly clickOnMyBetsSubject = new BehaviorSubject<boolean>(false);
  clickOnMyBets: Observable<boolean> = this.clickOnMyBetsSubject.asObservable();
  private readonly clickOnMyBetsNavigationSubject = new Subject<boolean>();
  clickOnMyBetsRedirection: Observable<boolean> = this.clickOnMyBetsNavigationSubject.asObservable();

  constructor(private readonly router: Router, private readonly mediaService: MediaService) {
    super();
    this.watchMyBetsVisibility();
  }

  setNavBarActive(navBarActive: boolean): void {
    this.navBarActiveSubject$.next(navBarActive);
  }

  clickOnNavBarMyBets(openFromNavbar: boolean): void {
    this.clickOnMyBetsSubject.next(openFromNavbar);
  }

  clickOnNavBarMyBetsNavigation(redirection: boolean): void {
    this.clickOnMyBetsNavigationSubject.next(redirection);
  }

  private watchMyBetsVisibility(): void {
    combineLatest([this.mediaService.media$, this.currentUrl$()])
      .pipe(
        tap(([media, url]) => this.updateMyBetsVisibility(media, url)),
        takeUntil(this.destroy$)
      )
      .subscribe();
  }

  private currentUrl$(): Observable<string> {
    return this.router.events.pipe(
      filter(event => event instanceof NavigationEnd),
      map((event: NavigationEnd) => event.url),
      startWith(this.router.url)
    );
  }

  private updateMyBetsVisibility(media: Media, url: string): void {
    if (media >= Media.lg || !url.includes('myaccount')) {
      this.clickOnNavBarMyBets(true);
    } else if (!NavBarService.MY_BETS_HISTORY_ROUTES.some(route => url.startsWith(route))) {
      this.clickOnNavBarMyBets(false);
    }
  }
}
