import {
  Component,
  OnInit,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Inject,
  OnDestroy,
  Input,
  Output,
  EventEmitter,
  OnChanges
} from '@angular/core';
import { AuthService, CustomerService, ICaptchaService, captchaServiceToken } from '@honoregaming/customer-core';
import { finalize, takeUntil } from 'rxjs/operators';
import { DestroySubject } from '@honoregaming/core';
import { ProfilePolicy, SecurityPolicy } from '@honoregaming/types';

@Component({
  selector: 'hg-account-validation-code',
  templateUrl: './account-validation-code.component.html',
  styleUrls: ['./account-validation-code.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class AccountValidationCodeComponent extends DestroySubject implements OnInit, OnDestroy, OnChanges {
  @Input() mfaVerificationMode = false;
  @Input() errorOccured = false;
  @Output() sendValidationRequest = new EventEmitter<string>();
  @Input() validateTradKey = 'COMMON.VALIDATE';

  profilePolicyRequirements: ProfilePolicy;
  securityPolicy: SecurityPolicy;
  isValidated: boolean;
  validationCode: string;
  validationCodeReseted: boolean = null;
  isConnected: boolean;
  loadingValidate: boolean;
  loadingReset: boolean;
  error: boolean;
  resetValidationCodeError: boolean;
  codeLength = 5;
  login: string;
  accept = false;
  recaptchaLegend: string;
  endRestrictionDate: Date;

  constructor(
    private customerService: CustomerService,
    private authService: AuthService,
    private cdRef: ChangeDetectorRef,
    @Inject(captchaServiceToken) private captchaService: ICaptchaService
  ) {
    super();
  }

  ngOnInit() {
    if (this.mfaVerificationMode) {
      this.accept = true;
      this.sendMfaRequest();
    }
    this.authService.me$.pipe(takeUntil(this.destroy$)).subscribe(me => (this.login = me.login));
    this.customerService.getSecurityPolicy().subscribe(x => {
      this.profilePolicyRequirements = x.profilePolicyRequirements;
      this.captchaService.loadCaptcha(x);
      this.captchaService
        .applyCaptcha('#ValidationCode_Reset')
        .pipe(
          finalize(() => {
            this.cdRef.markForCheck();
          })
        )
        .subscribe(() => {
          this.recaptchaLegend = this.captchaService.getLegend();
        });
    });
  }

  ngOnChanges() {
    if (this.errorOccured) {
      this.error = this.errorOccured;
      this.loadingValidate = false;
    }
  }

  ngOnDestroy(): void {
    super.ngOnDestroy();
    this.captchaService.clearCaptcha();
  }

  validate() {
    if (this.loadingValidate) {
      return;
    }

    this.sendValidationRequest.emit(this.validationCode);
    this.loadingValidate = true;
  }

  public resetValidationCode() {
    if (this.loadingReset) {
      return;
    }

    this.loadingReset = true;

    this.captchaService
      .validateCaptcha()
      .pipe(takeUntil(this.destroy$))
      .subscribe(token => {
        if (this.mfaVerificationMode) {
          this.sendMfaRequest(true);
        } else {
          this.submitResetValidationCode(token);
        }
      });
  }

  private sendMfaRequest(reset: boolean = false) {
    this.authService
      .mfaCodeRequest()
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.cdRef.markForCheck();
        })
      )
      .subscribe(() => {
        this.loadingReset = false;
        this.validationCodeReseted = reset;
        () => {
          this.error = true;
          this.loadingReset = false;
        };
      });
  }

  private submitResetValidationCode(recaptchaToken: string) {
    this.loadingReset = true;
    this.customerService
      .resetValidationCode(recaptchaToken)
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.loadingReset = false;
          this.cdRef.markForCheck();
        })
      )
      .subscribe(
        () => {
          this.validationCodeReseted = true;
          this.cdRef.markForCheck();
        },
        err => {
          this.resetValidationCodeError = true;
          if (err.error.code === -1) {
            this.endRestrictionDate = err.error.additionalData.endRestrictionDate;
          }
        }
      );
  }
}
