import { Component, ChangeDetectionStrategy, Input, OnChanges } from '@angular/core';

@Component({
  selector: 'hg-golden-lion-result',
  templateUrl: './golden-lion-result.component.html',
  styleUrls: ['./golden-lion-result.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class GoldenLionResultComponent implements OnChanges {
  @Input()
  result: any;

  serializedResult: any;

  constructor() {}

  ngOnChanges() {
    this.serializedResult = JSON.parse(this.result);
  }
}
