import { Directive, OnInit, ElementRef, Inject } from '@angular/core';
import { AuthService } from '@honoregaming/customer-core';
import { DOCUMENT } from '@angular/common';

@Directive({
  // eslint-disable-next-line @angular-eslint/directive-selector
  selector: 'hg-customer-state-class'
})
export class CustomerStateClassDirective implements OnInit {
  constructor(
    private elementRef: ElementRef,
    private authService: AuthService,
    @Inject(DOCUMENT) private document: any
  ) {}

  ngOnInit() {
    const styleElement = this.document.createElement('style');
    (this.elementRef.nativeElement as HTMLElement).appendChild(styleElement);
    this.authService.me$.subscribe(x => {
      if (x) {
        styleElement.innerHTML = `
          .customer-not-connect { display : none;}
        `;
      } else {
        styleElement.innerHTML = `
        .customer-connect { display : none;}
      `;
      }
    });
  }
}
