import { combineLatest, Observable } from 'rxjs';
import { tap } from 'rxjs/operators';
import { Inject, Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { globalConfiguration } from '@honoregaming/configuration';
import { Cacheable, CacheableVaryByKey, LocalStorageService } from '@honoregaming/core';
import {
  InstantGame,
  InstantGameBigWinner,
  InstantGameCategory,
  InstantGameWinnersStream,
  Vendor
} from '@honoregaming/types';
import { I18nService } from '@honoregaming/i18n';
import { AuthService, authServiceToken } from '@honoregaming/authentication';

@Injectable({ providedIn: 'root' })
export class InstantGameService {
  @CacheableVaryByKey()
  cacheKey: string;

  @CacheableVaryByKey()
  userLanguage: string;

  instantGamesCache: InstantGame[];

  constructor(
    private httpClient: HttpClient,
    private i18nService: I18nService,
    @Inject(authServiceToken) private authService: AuthService,
    private localStorageService: LocalStorageService
  ) {
    this.i18nService.languageChanged$.subscribe(lang => (this.userLanguage = lang));

    combineLatest([this.i18nService.languageChanged$, this.authService.status$]).subscribe(([language, status]) => {
      if (status === 'connected') {
        const userId = this.localStorageService.getItem('id');

        this.cacheKey = `${userId}-${language}`;
      } else {
        this.cacheKey = `${status}-${language}`;
      }
    });
  }

  @Cacheable()
  getInstantGames(): Observable<InstantGame[]> {
    return this.httpClient.get<[]>(globalConfiguration.apiEventsBaseUrl + `instantgames?${this.userLanguage}`).pipe(
      tap((data: InstantGame[]) => {
        this.instantGamesCache = data;
      })
    );
  }

  @Cacheable()
  getInstantGamesCategories(): Observable<InstantGameCategory[]> {
    return this.httpClient.get<InstantGameCategory[]>(
      globalConfiguration.apiEventsBaseUrl + `instant-games/categories?${this.userLanguage}`
    );
  }

  @Cacheable()
  getInstantGameCategory(categoryId: string): Observable<InstantGameCategory> {
    return this.httpClient.get<InstantGameCategory>(
      globalConfiguration.apiEventsBaseUrl + `instant-games/categories/${categoryId}`
    );
  }

  @Cacheable()
  getInstantGamesForVendor(vendor: string): Observable<InstantGame[]> {
    return this.httpClient.get<InstantGame[]>(globalConfiguration.apiEventsBaseUrl + `instant-games/vendor/${vendor}`);
  }

  @Cacheable()
  getSimilarGames(gameId: number, categoryId: number): Observable<InstantGame[]> {
    return this.httpClient.get<InstantGame[]>(
      globalConfiguration.apiEventsBaseUrl + `instant-games/similar-games/${gameId}/${categoryId}`
    );
  }

  @Cacheable()
  getPromotedInstantGames(): Observable<InstantGame[]> {
    return this.httpClient.get<InstantGame[]>(globalConfiguration.apiEventsBaseUrl + 'instant-games/promoted');
  }

  getInstantGame(provider: string, name: string): Observable<InstantGame> {
    return this.httpClient.get<InstantGame>(globalConfiguration.apiEventsBaseUrl + `instant-games/${provider}/${name}`);
  }

  searchInstantGamesVendors(search: string): Observable<{ instantGames: InstantGame[]; vendors: Vendor[] }> {
    return this.httpClient.get<{ instantGames: InstantGame[]; vendors: Vendor[] }>(
      globalConfiguration.apiEventsBaseUrl + `instant-games/search/${search}`
    );
  }

  @Cacheable()
  getBigWinners(): Observable<InstantGameBigWinner[]> {
    return this.httpClient.get<InstantGameBigWinner[]>(
      globalConfiguration.apiEventsBaseUrl + 'instant-games/bigwinners'
    );
  }

  @Cacheable()
  getWinnersStream(): Observable<InstantGameWinnersStream[]> {
    return this.httpClient.get<InstantGameWinnersStream[]>(
      globalConfiguration.apiEventsBaseUrl + 'instant-games/winners-stream'
    );
  }

  @Cacheable()
  getCustomersInPlay(): Observable<{ [key: number]: number }> {
    return this.httpClient.get<{ [key: number]: number }>(
      globalConfiguration.apiEventsBaseUrl + 'instant-games/customers-in-play'
    );
  }

  getRecentlyPlayedInstantGame(): Observable<InstantGame[]> {
    return this.httpClient.get<InstantGame[]>(globalConfiguration.apiEventsBaseUrl + 'instant-games/recently-played');
  }
}
