import { HttpClient, HttpParams } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { globalConfiguration } from '@honoregaming/configuration';
import { Observable } from 'rxjs';
import { Cacheable, CacheableVaryByKey } from '@honoregaming/core';
import { BetTypeExplanations } from '@honoregaming/types';
import { I18nService } from '@honoregaming/i18n';

@Injectable({ providedIn: 'root' })
export class BetTypeService {
  constructor(private httpClient: HttpClient, private i18nService: I18nService) {
    this.i18nService.languageChanged$.subscribe(lang => (this.userLanguage = lang));
  }

  @CacheableVaryByKey()
  userLanguage: string;

  @Cacheable()
  getExplanations(betTypeId: number, betTypeContext?: string): Observable<BetTypeExplanations> {
    const params = betTypeContext != null ? new HttpParams().set('betTypeContext', betTypeContext) : null;
    return this.httpClient.get<BetTypeExplanations>(
      `${globalConfiguration.apiEventsBaseUrl}bet-types/explanations/${betTypeId}`,
      { params }
    );
  }

  @Cacheable()
  getHorseRacingBetTypes(): Observable<number[]> {
    return this.httpClient.get<number[]>(`${globalConfiguration.apiEventsBaseUrl}bet-types/horse-racing`);
  }
}
