import { Component, ChangeDetectionStrategy, Output, EventEmitter, Input } from '@angular/core';

@Component({
  selector: 'hg-show-more-button',
  templateUrl: './show-more-button.component.html',
  styleUrls: ['./show-more-button.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class ShowMoreButtonComponent {
  @Input() quantity: number = 0;

  @Output() showMore: EventEmitter<void> = new EventEmitter<void>();

  constructor() {}

  more(): void {
    this.showMore.emit();
  }
}
