import { DirectMessageThreadResolution } from 'projects/customer/hg-account/src/lib/models/direct-message-thread-resolution.model';
import { DirectMessageCategory } from '../enums';

export interface DirectMessage {
  id: number;
  content: string;
  imageUrl?: string;
  administratorName: string;
  solved: boolean;
  readDate?: Date;
  dateTime: Date;
  direction: DirectMessageDirection;
  date: number;
  month: number;
  category?: DirectMessageCategory;
  threadResolutions?: DirectMessageThreadResolution[];
  quotedMessage?: DirectMessageReply;
}

export enum DirectMessageDirection {
  Incoming = 'Incoming',
  Outcoming = 'Outcoming'
}

export type DirectMessageReply = Pick<
  DirectMessage,
  'id' | 'content' | 'dateTime' | 'administratorName' | 'direction' | 'category' | 'imageUrl'
>;
