import { Component, ChangeDetectionStrategy, EventEmitter, Output, Inject, OnInit } from '@angular/core';
import { globalConfiguration } from '@honoregaming/configuration';
import { CodeType, Utms } from '@honoregaming/customer-core';
import { CustomerOperatorConfiguration, customerOperatorConfigurationToken } from '@honoregaming/customer-core';
import { kioskToken } from '@honoregaming/core';

@Component({
  selector: 'hg-share-code',
  templateUrl: './share-code.component.html',
  styleUrls: ['./share-code.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class ShareCodeComponent implements OnInit {
  @Output()
  public close = new EventEmitter();

  isQrCodeEnabled = this.operatorConfiguration.betCodeConfiguration?.isQrCodeEnabled;
  code: string;
  codeName: string;
  codeType: CodeType;
  shareMessageTemplate: string;
  fbLink: string;
  fbShareMessage: string;
  twShareMessage: string;
  waShareMessage: string;
  copyCodeText: string;

  toast: boolean = false;

  constructor(
    @Inject(customerOperatorConfigurationToken) private operatorConfiguration: CustomerOperatorConfiguration,
    @Inject(kioskToken) public isKiosk: boolean
  ) {}

  ngOnInit(): void {
    this.copyCodeText = this.generateLink(Utms.Social);

    this.fbLink = this.generateLink(Utms.Social, Utms.Facebook);
    const waLink = this.generateLink(Utms.Social, Utms.WhatsApp);
    const twLink = this.generateLink(Utms.Social, Utms.Twitter);

    this.fbShareMessage = encodeURIComponent(this.shareMessageTemplate.replace('{shareLink}', this.fbLink));
    this.waShareMessage = encodeURIComponent(this.shareMessageTemplate.replace('{shareLink}', waLink));
    this.twShareMessage = encodeURIComponent(this.shareMessageTemplate.replace('{shareLink}', twLink));
  }

  generateLink(...utms: Utms[]) {
    if (utms.length > 3) {
      throw new Error('Proxy api only support 3 utms');
    }

    const utmsLink = '0'.repeat(3 - utms.length) + utms.join(''); // padstart
    return `${globalConfiguration.apiProxyBaseUrl}${this.codeType}${this.operatorConfiguration.commercialCode}${utmsLink}${this.code}`;
  }

  activeToast() {
    this.toast = true;
    setTimeout(() => {
      this.toast = false;
    }, 1000);
  }
}
