import { Component, OnInit, ChangeDetectionStrategy, Inject } from '@angular/core';
import { customerOperatorConfigurationToken, CustomerOperatorConfiguration } from '@honoregaming/customer-core';
@Component({
  selector: 'hg-notification-popin',
  templateUrl: './notification.component.html',
  styleUrls: ['./notification.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class NotificationComponent implements OnInit {
  operatorName: string;
  constructor(
    @Inject(customerOperatorConfigurationToken) private operatorConfiguration: CustomerOperatorConfiguration
  ) {}

  ngOnInit() {
    this.operatorName = this.operatorConfiguration?.name;
  }
}
