import { Component, ChangeDetectionStrategy, Input, OnInit, ChangeDetectorRef, Inject } from '@angular/core';
import { BetLineHistory, BetSystemHistory, BetSystemType } from '@honoregaming/types';
import { OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';
import { BetBuilderService } from '@honoregaming/core';
import { NewWonBetSystems } from 'projects/customer/hg-core/src/lib/models/notifications-infos.model';

@Component({
  selector: 'hg-won-bet-systems-notification',
  templateUrl: './won-bet-systems-notification.component.html',
  styleUrls: ['./won-bet-systems-notification.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class WonBetSystemsNotificationComponent implements OnInit {
  @Input() notif!: NewWonBetSystems;

  totalGains: number = 0;
  selectedBetSystem!: BetSystemHistory;
  allBetLines: BetLineHistory[] = [];
  isShowingAll: boolean = false;
  index: number = 0;
  totalOdds?: number;
  currency: string = this.operatorConfiguration.currency.symbol;
  betBuilderModeLabel: string = '';

  constructor(
    private readonly cdRef: ChangeDetectorRef,
    private readonly betBuilderService: BetBuilderService,
    @Inject(operatorConfigurationToken) private readonly operatorConfiguration: OperatorConfiguration
  ) {}

  ngOnInit(): void {
    this.totalGains = this.notif.betSystems.reduce((sum, bs) => sum + bs.earning, 0);
    this.betBuilderModeLabel = this.betBuilderService?.productName;
    this.selectBetSystem(0);
  }

  previous(): void {
    const length: number = this.notif.betSystems.length;
    this.selectBetSystem(this.index > 0 ? this.index - 1 : length - 1);
  }

  next(): void {
    const length: number = this.notif.betSystems.length;
    this.selectBetSystem(this.index < length - 1 ? this.index + 1 : 0);
  }

  selectBetSystem(index: number): void {
    this.index = index;
    const source: BetSystemHistory = this.notif.betSystems[index];
    this.allBetLines = [...source.betLines];
    this.totalOdds = this.computeTotalOdds(source);
    this.selectedBetSystem = { ...source, betLines: this.getVisibleBetLines() };
    this.cdRef.detectChanges();
  }

  toggleAllBetlines(): void {
    this.isShowingAll = !this.isShowingAll;
    this.selectedBetSystem = { ...this.selectedBetSystem, betLines: this.getVisibleBetLines() };
  }

  private getVisibleBetLines(): BetLineHistory[] {
    return this.isShowingAll ? [...this.allBetLines] : this.allBetLines.slice(0, 3);
  }

  private computeTotalOdds(betSystem: BetSystemHistory): number {
    if (betSystem.type === BetSystemType.Multiple && betSystem.betLines.some(bl => bl.odds)) {
      return betSystem.betLines.reduce((acc, bl) => acc * bl.odds, 1);
    }
    return betSystem.betLines[0].odds;
  }
}
