import { ErrorHandler, Injector } from '@angular/core';
import { UnauthorizedError } from './errors/unauthorized.error';
import { BroadcastingService } from '@honoregaming/core';
import { AuthenticationError } from './errors';

export class AuthenticationErrorsHandler implements ErrorHandler {
  constructor(private injector: Injector) {}

  handleError(error: any) {
    const broadcastService = this.injector.get(BroadcastingService);
    if (error.rejection instanceof AuthenticationError || error.rejection instanceof UnauthorizedError) {
      broadcastService.broadcast('AuthenticationError');
    } else {
      throw error;
    }
  }
}

export function authenticationErrorsHandlerFactory(injector: Injector) {
  return new AuthenticationErrorsHandler(injector);
}
