import { Injectable } from '@angular/core';
import { EventBetTypeGroupedByBetType } from '@honoregaming/types';

export interface EventBetTypeGroupView extends EventBetTypeGroupedByBetType {
  xupValue: string | null;
  hasXup: boolean;
  hasValidContext: boolean;
  usesTeamTemplate: boolean;
}

export interface PatchResult {
  groups: EventBetTypeGroupView[];
  changed: boolean;
}

/**
 * Enriches grouped EventBetType data into view-models consumed by the template.
 *
 * Owns the XUP parsing, valid-context detection, and team-template flagging.
 * All methods are pure — no DOM, no subscriptions, no side-effects.
 */
@Injectable({
  providedIn: 'root'
})
export class EventBetTypeViewModelService {
  private static readonly XUP_KEY = '"xup"';
  private static readonly XUP_REGEX = /"xup"\s*:\s*"([^"]*)"/;
  private static readonly VALID_CONTEXT_BET_TYPE_IDS = [10110, 10088];

  /**
   * Full rebuild: maps every filtered group into an enriched view-model.
   */
  enrichGroups(filtered: EventBetTypeGroupedByBetType[], teamTemplateIds: Set<number>): EventBetTypeGroupView[] {
    return filtered.map(bt => this.toViewModel(bt, teamTemplateIds));
  }

  /**
   * Incremental patch: only replaces entries whose `eventBetTypes` reference changed.
   * Returns the patched array and a flag indicating whether anything actually changed.
   */
  patchGroups(
    existing: EventBetTypeGroupView[],
    filtered: EventBetTypeGroupedByBetType[],
    teamTemplateIds: Set<number>
  ): PatchResult {
    if (existing.length !== filtered.length) {
      return { groups: this.enrichGroups(filtered, teamTemplateIds), changed: true };
    }

    let changed: boolean = false;
    const patched: EventBetTypeGroupView[] = existing.slice();

    for (let i = 0; i < existing.length; i++) {
      if (existing[i].eventBetTypes !== filtered[i].eventBetTypes) {
        patched[i] = this.toViewModel(filtered[i], teamTemplateIds);
        changed = true;
      }
    }

    return { groups: changed ? patched : existing, changed };
  }

  hasXupValue(betTypeContext: string | null | undefined): boolean {
    return !!betTypeContext?.includes(EventBetTypeViewModelService.XUP_KEY);
  }

  getXupValue(betTypeContext: string | null | undefined): string | null {
    const match: RegExpExecArray = EventBetTypeViewModelService.XUP_REGEX.exec(betTypeContext);
    return match?.[1] ?? null;
  }

  private toViewModel(bt: EventBetTypeGroupedByBetType, teamTemplateIds: Set<number>): EventBetTypeGroupView {
    return {
      ...bt,
      xupValue: this.getXupValue(bt.betTypeContext),
      hasXup: this.hasXupValue(bt.betTypeContext),
      hasValidContext: this.isBetTypeWithValidContext(bt),
      usesTeamTemplate: teamTemplateIds.has(bt.betTypeId)
    };
  }

  private isBetTypeWithValidContext(betType: EventBetTypeGroupedByBetType): boolean {
    return (
      EventBetTypeViewModelService.VALID_CONTEXT_BET_TYPE_IDS.includes(betType.betTypeId) &&
      betType.betTypeContext !== ''
    );
  }
}
