import { HttpClient } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { BehaviorSubject, Observable } from 'rxjs';
import { catchError, finalize, tap } from 'rxjs/operators';
import { globalConfiguration } from '@honoregaming/configuration';
import { buildQueryString } from '@honoregaming/core';
import { PaginatedResponse } from '@honoregaming/types';
import { GetCustomerDirectMessages } from 'projects/customer/hg-account/src/lib/models/get-customer-direct-messages.model';
import { DirectMessage, CustomerDirectMessageConfiguration } from '../models';

@Injectable({
  providedIn: 'root'
})
export class DirectMessageService {
  private readonly unreadMessageCount$ = new BehaviorSubject<number>(0);

  constructor(private readonly httpClient: HttpClient) {}

  get unreadMessageCount(): Observable<number> {
    return this.unreadMessageCount$.asObservable();
  }

  setUnreadMessagesCount(unreadDirectMessageCount: number): void {
    this.unreadMessageCount$.next(unreadDirectMessageCount);
  }

  getDirectMessages(): Observable<GetCustomerDirectMessages> {
    return this.httpClient
      .get<GetCustomerDirectMessages>(`${globalConfiguration.apiBaseUrl}direct-message`)
      .pipe(finalize(() => this.setUnreadMessagesCount(0)));
  }

  getPreviousDirectMessages(messageId: number): Observable<PaginatedResponse<DirectMessage>> {
    return this.httpClient.get<PaginatedResponse<DirectMessage>>(
      `${globalConfiguration.apiBaseUrl}direct-message/previous${buildQueryString({ messageId })}`
    );
  }

  getRecentMessages(lastMessageId: number) {
    return this.httpClient.get<{
      items: DirectMessage[];
      claimedAdministratorName?: string;
      claimedAdministratorId?: number;
    }>(`${globalConfiguration.apiBaseUrl}direct-message/recent${buildQueryString({ lastMessageId })}`);
  }

  postNewDirectMessages(content: string, quotedMessageId?: number): Observable<DirectMessage> {
    return this.httpClient.post<DirectMessage>(`${globalConfiguration.apiBaseUrl}direct-message`, {
      content,
      quotedMessageId
    });
  }

  getDirectMessageConfig(): Observable<CustomerDirectMessageConfiguration> {
    return this.httpClient
      .get<CustomerDirectMessageConfiguration>(`${globalConfiguration.apiBaseUrl}direct-message/configuration`)
      .pipe(
        tap((directMessageConfig: CustomerDirectMessageConfiguration) =>
          this.setUnreadMessagesCount(directMessageConfig.unreadDirectMessageCount)
        ),
        catchError(err => {
          this.unreadMessageCount$.next(0);
          throw err;
        })
      );
  }

  uploadImage(file: File, content: string | null, quotedMessageId: number | null) {
    const formData = new FormData();

    formData.append('file', file);
    if (content) {
      formData.append('content', content);
    }
    if (quotedMessageId) {
      formData.append('quotedMessageId', quotedMessageId.toString());
    }
    return this.httpClient.post(`${globalConfiguration.apiBaseUrl}direct-message/picture`, formData);
  }
}
