import {
  Match,
  EventBetType,
  SelectableEventBetTypeItem,
  EventWithEventBetTypes,
  EventStateType,
  SelectedItem
} from '@honoregaming/types';
import { BetSlipService, BetSlipLinesInfo, BetSlipBetLinesService } from '@honoregaming/betslip';
import {
  DestroySubject,
  PushService,
  updateEventBetTypeAfterPush,
  updateEventAfterPush,
  AsyncTrigger,
  BroadcastingService,
  BetLinesMapperService
} from '@honoregaming/core';
import { take, takeUntil } from 'rxjs/operators';
import { ChangeDetectorRef, Directive, OnDestroy, OnInit } from '@angular/core';
import { Subscription } from 'rxjs';
import { I18nService } from '@honoregaming/i18n';
import { EventsMapperService } from '@honoregaming/events';

@Directive()
export abstract class EventsWithEventBetTypesComponentBase extends DestroySubject implements OnInit, OnDestroy {
  public events: EventWithEventBetTypes<Match, EventBetType>[] = [];
  selectedItems: SelectedItem[];

  private betLinesSubscription: Subscription;
  private eventBetTypesPushSubscription: Subscription;
  private eventsPushSubscription: Subscription;

  isLoadingOddsEventIds: number[] = [];

  @AsyncTrigger()
  languageTrigger = this.i18nService.languageChanged$;

  constructor(
    protected i18nService: I18nService,
    protected betSlipService: BetSlipService,
    protected pushService: PushService,
    protected cdRef: ChangeDetectorRef,
    protected bcService: BroadcastingService,
    protected eventsMapperService: EventsMapperService,
    protected betLinesMapperService: BetLinesMapperService,
    protected betSlipBetLinesService: BetSlipBetLinesService
  ) {
    super();
  }

  ngOnInit(): void {
    this.listenOnLoadingOddsChanges();
  }

  ngOnDestroy(): void {
    super.ngOnDestroy();

    this.betLinesSubscription?.unsubscribe();
    this.eventBetTypesPushSubscription?.unsubscribe();
    this.eventsPushSubscription?.unsubscribe();

    this.pushService.subscribeToEvents([]);
    this.pushService.subscribeToOdds([], []);
  }

  toggleEventBetTypeItem(
    match: Match,
    ebt: EventBetType,
    selection: {
      item: SelectableEventBetTypeItem;
      selected: boolean;
    }
  ) {
    if (
      selection.item.odds <= 1 ||
      !ebt.active ||
      !ebt.bettingAllowed ||
      !selection.item.active ||
      !selection.item.bettingAllowed ||
      this.isLoadingOddsEventIds.length
    ) {
      return;
    }

    this.betSlipBetLinesService
      .toggleEventBetTypeItem(match, ebt, selection.item, !selection.item.selected)
      .pipe(take(1))
      .subscribe((selected: boolean) => {
        if (selection.item.selected && !selected) {
          this.selectedItems = this.selectedItems.filter(
            (selectedItem: SelectedItem) => selectedItem.eventBetTypeItemId !== selection.item.id
          );
          this.updateSelectedItems();
        }
      });
  }

  registerToPushChanges() {
    this.pushService.subscribeToEvents(this.events?.map(e => e.id) || []);
    this.pushService.subscribeToOdds(
      this.events?.length
        ? this.events
            ?.filter(x => x.eventBetTypes)
            .map(e => e.eventBetTypes.map(ebt => ebt.id))
            .reduce((a, b) => a?.concat(b), [])
        : [],
      []
    );
  }

  subscribeToPushChanges() {
    if (!this.eventBetTypesPushSubscription) {
      this.eventBetTypesPushSubscription = this.pushService.eventBetTypeChanged$
        .pipe(takeUntil(this.destroy$))
        .subscribe(changed => {
          this.events.forEach(x => {
            const index = x.eventBetTypes?.findIndex(y => y.id === changed.eventBetTypeId);
            if (index >= 0) {
              if (changed.active === false) {
                x.eventBetTypes[index].bettingAllowed = false; // HACK until better solution
              } else {
                updateEventBetTypeAfterPush(x.eventBetTypes[index], changed);
              }

              x.eventBetTypes[index] = { ...x.eventBetTypes[index] };
              this.cdRef.markForCheck();
            }
          });
        });
    }

    if (!this.eventsPushSubscription) {
      this.eventsPushSubscription = this.pushService.eventChanged$.pipe(takeUntil(this.destroy$)).subscribe(changed => {
        let eventChangedToLiveState = false;

        this.events.forEach(x => {
          if (x.id === changed.eventId) {
            if (changed.changes['scores']) {
              x.scores = changed.changes['scores'];
            }

            x = updateEventAfterPush(x, x.eventBetTypes, changed);
            if (
              changed.changes['state'] &&
              changed.changes['state'] !== EventStateType.AboutToStart &&
              changed.changes['state'] !== EventStateType.Undisputed &&
              changed.changes['state'] !== EventStateType.Delayed
            ) {
              eventChangedToLiveState = true;
            }

            this.cdRef.markForCheck();
          }
        });

        if (eventChangedToLiveState) {
          this.onEventChangedToLiveState();
        }
      });
    }
  }

  subscribeToBetSlip() {
    if (!this.betLinesSubscription) {
      this.betLinesSubscription = this.betSlipService.$lines.subscribe((betSlipLinesChange: BetSlipLinesInfo) => {
        this.selectedItems = this.betLinesMapperService.betLinesToSelectedItems(betSlipLinesChange.lines);
        this.updateSelectedItems();
      });
    }
  }

  updateSelectedItems() {
    this.eventsMapperService.updateEventsWithEventBetTypesSelectedItems(this.events, this.selectedItems);
    this.cdRef.markForCheck();
  }

  updateEventsSubscriptions() {
    this.subscribeToPushChanges();
    this.subscribeToBetSlip();
    this.registerToPushChanges();
    this.updateSelectedItems();

    this.cdRef.markForCheck();
  }

  onEventChangedToLiveState() {}

  private listenOnLoadingOddsChanges(): void {
    this.betSlipBetLinesService.isLoadingOddsEventIds$
      .pipe(takeUntil(this.destroy$))
      .subscribe((isLoadingOddsEventIds: number[]) => {
        this.isLoadingOddsEventIds = isLoadingOddsEventIds;
        this.cdRef.markForCheck();
      });
  }
}
