import { Pipe, PipeTransform, ChangeDetectorRef, OnDestroy, Inject, PLATFORM_ID } from '@angular/core';
import { I18nService } from '../services/i18n.service';
import { AsyncPipe, isPlatformServer } from '@angular/common';
import { Observable } from 'rxjs';

@Pipe({
  name: 'hgLongTime',
  pure: false
})
export class LongTimePipe implements PipeTransform, OnDestroy {
  async: AsyncPipe;
  previousKey: string;
  previousObservable: Observable<string>;

  constructor(
    private i18nService: I18nService,
    @Inject(PLATFORM_ID) private platformId: any,
    private cdRef: ChangeDetectorRef
  ) {
    this.async = new AsyncPipe(this.cdRef);
  }

  transform(key: any): any {
    if (isPlatformServer(this.platformId)) {
      return '--:--:--';
    }

    if (this.previousKey !== key) {
      this.previousKey = key;
      this.previousObservable = this.i18nService.formatLongTime(key);
    }

    return this.async.transform(this.previousObservable);
  }

  ngOnDestroy(): void {
    this.async.ngOnDestroy();
  }
}
