import { Directive, Input } from '@angular/core';
import { Validator, AbstractControl, NG_VALIDATORS } from '@angular/forms';

@Directive({
  selector: '[hgValidateEqual]',
  providers: [
    {
      provide: NG_VALIDATORS,
      useExisting: EqualsValidatorDirective,
      multi: true
    }
  ]
})
export class EqualsValidatorDirective implements Validator {
  // tslint:disable-next-line:no-input-rename
  @Input('hgValidateEqual') validateEqual: string;
  @Input() reverse: boolean;

  validate(c: AbstractControl): { [key: string]: any } {
    const v = c.value;
    const e = c.root.get(this.validateEqual);

    if (e && v !== e.value && !this.reverse && e.dirty) {
      return {
        validateEqual: true
      };
    }

    if (e && v === e.value && this.reverse) {
      if (e.errors) {
        delete e.errors['validateEqual'];
        if (!Object.keys(e.errors).length) {
          e.setErrors(null);
        }
      }
    }

    if (e && v !== e.value && this.reverse) {
      e.setErrors({ ...e.errors, validateEqual: true });
    }

    return null;
  }
}
