import { Inject, Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';
import { map } from 'rxjs/operators';
import { globalConfiguration, OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';
import { Cacheable } from '@honoregaming/core';
import { ITemplateService } from '@honoregaming/templating';
import { Template } from '@honoregaming/types';

@Injectable()
export class TemplateService implements ITemplateService {
  constructor(
    private httpClient: HttpClient,
    @Inject(operatorConfigurationToken) private operatorConfiguration: OperatorConfiguration
  ) {}

  getTemplatesForAnchor(anchor: string): Observable<Template[]> {
    return this.getTemplates().pipe(map(res => res[anchor] || []));
  }

  @Cacheable()
  private getTemplates() {
    return this.httpClient.get<{ [anchor: string]: Template[] }>(
      `${globalConfiguration.staticAssetsPath}${this.operatorConfiguration.commercialCode}/templates.json`
    );
  }
}
