import { Injectable } from '@angular/core';
import { BehaviorSubject, Observable } from 'rxjs';
import { Media } from '../enum/media.enum';

@Injectable()
export class MediaService {
  private xsMedia = matchMedia('(max-width: 511px)');
  private smMedia = matchMedia('(min-width: 512px) and (max-width: 699px)');
  private mdMedia = matchMedia('(min-width: 700px) and (max-width: 1023px)');
  private lgMedia = matchMedia('(min-width: 1024px) and (max-width: 1535px)');
  private xlMedia = matchMedia('(min-width: 1536px)');

  private mediaSubject: BehaviorSubject<Media>;
  media$: Observable<Media>;

  get media(): Media {
    return this.mediaSubject.value;
  }

  constructor() {
    if (this.xlMedia.matches) {
      this.mediaSubject = new BehaviorSubject<Media>(Media.xl);
    } else if (this.lgMedia.matches) {
      this.mediaSubject = new BehaviorSubject<Media>(Media.lg);
    } else if (this.mdMedia.matches) {
      this.mediaSubject = new BehaviorSubject<Media>(Media.md);
    } else if (this.smMedia.matches) {
      this.mediaSubject = new BehaviorSubject<Media>(Media.sm);
    } else {
      this.mediaSubject = new BehaviorSubject<Media>(Media.xs);
    }

    this.media$ = this.mediaSubject.asObservable();

    this.xlMedia.addListener(mql => {
      if (mql.matches) {
        this.mediaSubject.next(Media.xl);
      }
    });

    this.lgMedia.addListener(mql => {
      if (mql.matches) {
        this.mediaSubject.next(Media.lg);
      }
    });

    this.mdMedia.addListener(mql => {
      if (mql.matches) {
        this.mediaSubject.next(Media.md);
      }
    });

    this.smMedia.addListener(mql => {
      if (mql.matches) {
        this.mediaSubject.next(Media.sm);
      }
    });

    this.xsMedia.addListener(mql => {
      if (mql.matches) {
        this.mediaSubject.next(Media.xs);
      }
    });
  }
}
