import {
  Component,
  ChangeDetectionStrategy,
  Input,
  OnChanges,
  SimpleChanges,
  EventEmitter,
  Output
} from '@angular/core';
import { Tax } from '@honoregaming/configuration';
import { TaxSummary, TaxType } from '@honoregaming/types';
import { TaxesService } from '@honoregaming/core';
import { OperationType } from 'projects/customer/hg-account/src/lib/models/operation.model';

@Component({
  selector: 'hg-tax-summary',
  templateUrl: './tax-summary.component.html',
  styleUrls: ['./tax-summary.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class TaxSummaryComponent implements OnChanges {
  @Input() tax!: Tax;
  @Input() baseAmount?: number;
  @Input() taxType: TaxType = TaxType.Deposit;
  @Input() showInformationIcon: boolean = true;
  @Input() type!: OperationType.Deposit | OperationType.Withdrawal;

  @Output() openTaxInformations: EventEmitter<void> = new EventEmitter<void>();

  taxSummary: TaxSummary | null = null;

  constructor(private readonly taxesService: TaxesService) {}

  ngOnChanges(changes: SimpleChanges): void {
    if (changes.tax || changes.baseAmount) {
      this.taxSummary = this.taxesService.computeTaxSummary(this.tax, this.baseAmount ?? 0);
    }
  }

  openInformations(event: Event): void {
    event.preventDefault();
    this.openTaxInformations.emit();
  }
}
