import { Pipe, PipeTransform, ChangeDetectorRef } from '@angular/core';
import { AsyncPipe } from '@angular/common';
import { Observable } from 'rxjs';
import { OddsFormatService } from '../services/odds-format.service';

@Pipe({
  name: 'oddsFormat',
  pure: false
})
export class OddsFormatPipe implements PipeTransform {
  async: AsyncPipe;
  previousKey: string;
  previousObservable: Observable<string | number>;

  constructor(private oddsFormatService: OddsFormatService, private cdRef: ChangeDetectorRef) {
    this.async = new AsyncPipe(this.cdRef);
  }

  transform(key: any): any {
    if (this.previousKey !== key) {
      this.previousKey = key;
      this.previousObservable = this.oddsFormatService.convertOdds(key);
    }

    return this.async.transform(this.previousObservable);
  }
}
