import {
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  EventEmitter,
  Inject,
  Input,
  OnInit,
  Output,
  forwardRef
} from '@angular/core';
import { ControlValueAccessor, NG_VALUE_ACCESSOR } from '@angular/forms';
import { OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';
import { I18nService } from '@honoregaming/i18n';
import { BetCategoryType } from '@honoregaming/types';
import { SelfLimitation } from '../../models/self-limitation.model';
import { MessageService } from '@honoregaming/ui';
import { ResponsibleGamblingSelfModifiedLimitationPopinComponent } from '../responsible-gambling-self-modified-limitation-popin/responsible-gambling-self-modified-limitation-popin.component';

@Component({
  selector: 'hg-responsible-gambling-limitation-card',
  templateUrl: './responsible-gambling-limitation-card.component.html',
  styleUrls: ['./responsible-gambling-limitation-card.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      multi: true,
      useExisting: forwardRef(() => ResponsibleGamblingLimitationCardComponent)
    }
  ]
})
export class ResponsibleGamblingLimitationCardComponent implements ControlValueAccessor, OnInit {
  currency = this.operatorConfiguration.currency.symbol;
  @Input() betCategory: BetCategoryType;
  @Input() currentReachedAmount: number;
  @Input() isInProcessOfBeingModified: boolean;
  @Output() isModifyingAndHasNotError = new EventEmitter<boolean>();
  @Input() minAndMaxLimitationsAmount: {
    minimumBetLimitationAmount: number;
    maximumBetLimitationAmount: number;
    minimumDepositLimitationAmount: number;
    maximumDepositLimitationAmount: number;
  };
  @Input() modifiedLimitations: SelfLimitation[] = [];
  @Input() isLocked: boolean;

  innerAmount: number;
  displayAmount: string;

  hasError: boolean;
  isModifying: boolean;

  title: string;
  pattern = '^[0-9,.\\s]*$';
  percentageReachedAmount = 0;
  minAmount: number;
  maxAmount: number;

  constructor(
    @Inject(operatorConfigurationToken) private operatorConfiguration: OperatorConfiguration,
    private i18nService: I18nService,
    private cdRef: ChangeDetectorRef,
    private messageService: MessageService
  ) {}

  ngOnInit() {
    this.minAmount = this.betCategory
      ? this.minAndMaxLimitationsAmount.minimumBetLimitationAmount
      : this.minAndMaxLimitationsAmount.minimumDepositLimitationAmount;
    this.maxAmount = this.betCategory
      ? this.minAndMaxLimitationsAmount.maximumBetLimitationAmount
      : this.minAndMaxLimitationsAmount.maximumDepositLimitationAmount;

    this.i18nService.translate(this.titleHelper(this.betCategory)).subscribe(x => {
      this.title = x;
      this.cdRef.markForCheck();
    });
  }

  onChange = (_value: any) => {};

  onTouched = () => {};

  writeValue(value: any): void {
    this.innerAmount = value;

    this.i18nService.formatCurrency(this.innerAmount).subscribe(x => {
      this.displayAmount = x;
    });

    this.percentageReachedAmount = this.innerAmount > 0 ? this.currentReachedAmount / this.innerAmount : 0;
    this.onChange(value);

    this.cdRef.markForCheck();
  }
  registerOnChange(fn: any): void {
    this.onChange = fn;
  }

  registerOnTouched(fn: any): void {
    this.onTouched = fn;
  }
  setDisabledState?(_: boolean): void {}

  titleHelper(betCategory: BetCategoryType) {
    switch (betCategory) {
      case BetCategoryType.SportsFixedOdds:
        return 'RESPONSIBLE_GAMBLING.SPORTS_FIXED_ODDS.LIMITATION.TITLE';
      case BetCategoryType.DrawGame:
        return 'RESPONSIBLE_GAMBLING.DRAWGAME.LIMITATION.TITLE';
      case BetCategoryType.HorseRacingMutualInternationalPool:
      case BetCategoryType.HorseRacingMutualOperatorPool:
        return 'RESPONSIBLE_GAMBLING.HORSE_RACING.LIMITATION.TITLE';
      case BetCategoryType.InstantGame:
        return 'RESPONSIBLE_GAMBLING.INSTANT_GAME.LIMITATION.TITLE';
      case BetCategoryType.VirtualFixedOdds:
        return 'RESPONSIBLE_GAMBLING.VIRTUAL_FIXED_ODDS.LIMITATION.TITLE';
      default:
        return 'RESPONSIBLE_GAMBLING.DEPOSIT.TITLE';
    }
  }

  update(ngModuleValue: any) {
    this.isModifying = true;

    let formattedInput = ngModuleValue.viewModel.replace(/\s/g, '');
    let numericValue = parseFloat(formattedInput);

    if (!isNaN(numericValue)) {
      this.innerAmount = numericValue;
      this.i18nService.formatCurrency(this.innerAmount).subscribe(x => {
        this.displayAmount = x;
      });

      this.percentageReachedAmount = this.innerAmount > 0 ? this.currentReachedAmount / this.innerAmount : 0;
      this.onChange(this.innerAmount);
    } else {
      this.onChange(null);
    }

    this.hasError = !ngModuleValue.valid || this.innerAmount > this.maxAmount || this.innerAmount < this.minAmount;
    this.isModifyingAndHasNotError.emit(this.isModifying && !this.hasError);
  }

  openPopin() {
    var modifiedLimitation = this.modifiedLimitations.find(x => x?.betCategoryType === this.betCategory)
      ? this.modifiedLimitations.find(x => x.betCategoryType === this.betCategory)
      : this.modifiedLimitations.find(x => !x.betCategoryType);
    this.messageService
      .sendComponentMessage(ResponsibleGamblingSelfModifiedLimitationPopinComponent, {
        modifiedLimitation: modifiedLimitation
      })
      .closed.subscribe();
  }
}
