import { trigger, transition, animate, style } from '@angular/animations';
import { Component, ChangeDetectionStrategy, ChangeDetectorRef, Output, EventEmitter } from '@angular/core';
import { DialogService } from '@honoregaming/core';
import { Router } from '@angular/router';
import {
  BetSlipBetLinesService,
  BetCodeBaseComponent,
  ErrorState,
  BetCodeFailures,
  LoadingState
} from '@honoregaming/betslip';

@Component({
  selector: 'hg-bet-code-checker',
  templateUrl: './bet-code-checker.component.html',
  styleUrls: ['./bet-code-checker.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
  animations: [
    trigger('removed', [
      transition('* => void', [animate('.1s ease-out', style({ transform: 'scale(0)', height: '0' }))]),
      transition('void => *', [
        style({ height: '0', transform: 'scale(0)' }),
        animate('.1s ease-out', style({ transform: 'scale(1)', height: '*' }))
      ])
    ])
  ]
})
export class BetCodeCheckerComponent extends BetCodeBaseComponent {
  @Output() closeMenu = new EventEmitter<void>();

  ErrorState = ErrorState;
  BetCodeFailures = BetCodeFailures;
  LoadingState = LoadingState;

  constructor(
    protected readonly dialogService: DialogService,
    protected readonly cdRef: ChangeDetectorRef,
    protected readonly router: Router,
    protected readonly betSlipBetLinesService: BetSlipBetLinesService
  ) {
    super(dialogService, cdRef, router, betSlipBetLinesService);
  }
}
