export interface HorseRaceRunner {
  id: number;
  number: number;
  horseName: string;
  arrivalPosition?: number;
  riderName: string;
  horseRecentPerformance: string;
  winnerProbableOdds?: number;
  nonRunner: boolean;
}

export interface HorseRaceRunnerInformations {
  stable: string;
  blinder: HorseRacingBlinderType;
  coach: string;
  firstTime: boolean;
  horseAge: number;
  horseBirthDate: Date;
  horseBreed: string;
  horseCoat: string;
  horseFather: string;
  horseGender: HorseRacingGenderType;
  horseMaternalGrandFather: string;
  horseMother: string;
  horsePregnant: boolean;
  owner: string;
  rail: number;
  raiser: string;
  riderWeight: number;
  unshod: HorseRacingUnshodType;
  weightWithCond: number;
}

export enum HorseRacingBlinderType {
  Unknown = 'Unknown',
  None = 'None',
  Blinders = 'Blinders',
  Winkers = 'Winkers'
}

export enum HorseRacingGenderType {
  Unknown = 'Unknown',
  Male = 'Male',
  Female = 'Female',
  Gelding = 'Gelding'
}

export enum HorseRacingUnshodType {
  Unknown = 'Unknown',
  None = 'None',
  Fore = 'Fore',
  Hind = 'Hind',
  Both = 'Both'
}
