import {
  ChangeDetectorRef,
  ChangeDetectionStrategy,
  Component,
  EventEmitter,
  Inject,
  Input,
  OnInit,
  Output,
  TemplateRef,
  SimpleChanges,
  OnChanges
} from '@angular/core';
import { trigger, transition, animate, style } from '@angular/animations';
import { Router, NavigationEnd } from '@angular/router';
import { EventType, BetCategoryType, DrawGameBorletteBetType } from '@honoregaming/types';
import { takeUntil, filter } from 'rxjs/operators';
import { BroadcastingService, DestroySubject, scopeToken, Scope } from '@honoregaming/core';
import { BetSlipService, DrawGameBetSlipService } from '@honoregaming/betslip';
import { operatorConfigurationToken, OperatorConfiguration } from '@honoregaming/configuration';
import { BetLine, BetLineAmount, BetSlipType, FreeBetCouponBetSlip } from '../../models';

@Component({
  selector: 'hg-bet-slip-simple-mode',
  templateUrl: './bet-slip-simple-mode.component.html',
  styleUrls: ['./bet-slip-simple-mode.component.scss', '../bet-lines/bet-line.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
  animations: [
    trigger('removed', [
      transition('* => void', [animate('0.1s ease-out', style({ transform: 'scale(0)', height: '0' }))])
    ])
  ]
})
export class BetSlipSimpleModeComponent extends DestroySubject implements OnInit, OnChanges {
  @Input() predefinedStakes: number[] = [];
  @Input() betCategory!: BetCategoryType;
  @Input() betLines: BetLine[] = [];
  @Input() amounts: BetLineAmount[] = [];
  @Input() betLineTemplate?: TemplateRef<any>;
  @Input() acceptOddChange?: boolean;
  @Input() betSlipType!: BetSlipType;
  @Input() useFreeBet: boolean = false;
  @Input() selectedFreeBetCoupon?: FreeBetCouponBetSlip;
  @Input() balance: number = 0;
  @Input() isUserConnected: boolean = false;

  @Output() betSlipChange = new EventEmitter<{ amount: number; line: BetLine }>();
  @Output() betLineRemove = new EventEmitter<BetLine>();

  EventType = EventType;
  BetCategoryType = BetCategoryType;
  canDisplayBorletteButtons: boolean = false;
  borletteNumbers: string[] = [];
  displayAllIn: boolean = false;

  constructor(
    private readonly cdRef: ChangeDetectorRef,
    private readonly broadcastingService: BroadcastingService,
    private readonly betSlipService: BetSlipService,
    private readonly drawGameBetSlipService: DrawGameBetSlipService,
    private readonly router: Router,
    @Inject(scopeToken) private readonly userScope: Scope,
    @Inject(operatorConfigurationToken) private readonly operatorConfiguration: OperatorConfiguration
  ) {
    super();
  }

  ngOnInit(): void {
    this.betLines.forEach(betLine => {
      betLine.newStake = null;
      betLine.failure = null;
    });
    this.betSlipService.$lines.pipe(takeUntil(this.destroy$)).subscribe(bl => {
      this.betLines = bl.lines;
      this.checkBorletteButtons(this.betLines);
    });

    this.router.events
      .pipe(
        takeUntil(this.destroy$),
        filter(event => event instanceof NavigationEnd)
      )
      .subscribe(() => {
        this.checkBorletteButtons(this.betLines);
      });
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (
      changes.selectedFreeBetCoupon ||
      changes.betLines ||
      changes.isUserConnected ||
      changes.balance ||
      changes.useFreeBet
    ) {
      this.updateAllInVisibility();
    }
  }

  trackByFn(index, _betLine: BetLine): number {
    return index;
  }

  trackByNumber(_, betLine: BetLine): number {
    return betLine.number;
  }

  onAmountChange(changes: { amount: number; line: BetLine }): void {
    this.betSlipChange.emit(changes);
  }

  onBetLineRemove(betLine: BetLine): void {
    this.betLineRemove.emit(betLine);
  }

  onBetLineChange(betLine: BetLine): void {
    this.betSlipChange.emit({ amount: null, line: betLine });
  }

  broadcastOpenModalBorlette(type: string): void {
    this.broadcastingService.broadcast('BorletteModal', { type: type, numbers: this.borletteNumbers });
  }

  applyAllIn(betLine: BetLine): void {
    let amount = this.selectedFreeBetCoupon ? this.selectedFreeBetCoupon.balance : this.balance;
    if (amount > 0) {
      this.onAmountChange({ amount: amount, line: betLine });
    }
  }

  private checkBorletteButtons(betLines: BetLine[]): void {
    this.borletteNumbers = [];
    const eventIds: number[] = [];
    let entryPointId: number;
    betLines.map((betLine: BetLine) => {
      if (betLine.eventType === EventType.DrawGame && betLine.betTypeId === DrawGameBorletteBetType.Borlette) {
        if (!eventIds.includes(betLine.eventId)) {
          eventIds.push(betLine.eventId);
        }
        if (!entryPointId) {
          entryPointId = betLine.entryPointId;
        }
        this.borletteNumbers.push(betLine.baseList[0]);
      }
    });

    const autoBorletteAvailable: boolean =
      this.borletteNumbers.length > 1 &&
      eventIds.some(
        x =>
          this.router.url.includes(`draw-games/${x}`) ||
          this.router.url.includes(`draw-game/${x}`) ||
          this.router.url.includes(`draw-games/category/${entryPointId}/draw-game/${x}`)
      );

    this.drawGameBetSlipService.setAutoBorletteAvailability(autoBorletteAvailable, this.borletteNumbers);

    this.canDisplayBorletteButtons = autoBorletteAvailable && this.userScope === Scope.Customer;

    this.cdRef.markForCheck();
  }

  private updateAllInVisibility(): void {
    this.displayAllIn =
      this.userScope === Scope.Customer &&
      (this.operatorConfiguration.bettingConfiguration?.displayAllInButton ?? false) &&
      this.betLines.length === 1 &&
      (!this.isUserConnected ||
        (this.useFreeBet && this.selectedFreeBetCoupon != null) ||
        (!this.useFreeBet && this.balance > 0));
  }
}
