import {
  Component,
  OnInit,
  ChangeDetectionStrategy,
  Input,
  EventEmitter,
  Output,
  Inject,
  ChangeDetectorRef
} from '@angular/core';
import { takeUntil } from 'rxjs/operators';
import { BetHistoryService, DestroySubject, startOfMonth } from '@honoregaming/core';
import { I18nService } from '@honoregaming/i18n';
import { CustomerOperatorConfiguration, customerOperatorConfigurationToken } from '@honoregaming/customer-core';
import { AccountFilter, SelectValue } from '../../models/account-filters.model';

@Component({
  selector: 'hg-account-filters',
  templateUrl: './account-filters.component.html',
  styleUrls: ['./account-filters.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class AccountFiltersComponent extends DestroySubject implements OnInit {
  @Input() states: SelectValue[] = [];
  @Input() options: string[] = [];
  @Input() currentFilter: AccountFilter = {};
  @Input() statesPrefix: string = '';
  @Input() optionsPrefix: string = '';
  @Input() hasFormatMenu: boolean = false;

  @Output() filter = new EventEmitter<AccountFilter>();

  monthNames: string[] = [];
  months: { month: string; date: Date }[] = [];
  selectedMonthName: string | null = null;
  betHistoryExpandedFormat: boolean = this.betHistoryService.expandedFormat;
  betHistoryReducedFormatEnabled: boolean = this.betHistoryService.reducedFormatEnabled;

  constructor(
    private readonly i18nService: I18nService,
    private readonly cdRef: ChangeDetectorRef,
    private readonly betHistoryService: BetHistoryService,
    @Inject(customerOperatorConfigurationToken) private readonly operatorConfiguration: CustomerOperatorConfiguration
  ) {
    super();
  }

  ngOnInit(): void {
    this.subscribeToMonthsNames();
    this.subscribeToExpandedFormat();
  }

  get displayFormatMenu(): boolean {
    return this.betHistoryReducedFormatEnabled && this.hasFormatMenu;
  }

  onExpandedFormatChange(expanded: boolean): void {
    this.betHistoryService.setExpandedFormat(expanded);
  }

  onStateChange(state: string | null): void {
    if (this.currentFilter.state !== state) {
      this.currentFilter.state = state;
      this.applyFilters();
    }
  }

  onOptionChange(option: string): void {
    this.currentFilter.option = option;
    this.applyFilters();
  }

  onMonthChange(selectedMonthName: string): void {
    this.selectedMonthName = selectedMonthName;
    this.currentFilter.month = this.months.find(month => month.month === selectedMonthName)?.date;
    this.applyFilters();
  }

  private initMonths(months: string[]): void {
    const maximumNumberOfMonthsAllowed: number =
      this.operatorConfiguration.onlineConfiguration?.transactionHistoryMaximumDurationInMonths ?? 12;

    this.months = [];

    // Set today's date for the last 30 days
    this.months.push({ month: this.i18nService.translateSync('BET_HISTORY.LAST_30_DAYS'), date: null });

    for (let monthOffset = 0; monthOffset < maximumNumberOfMonthsAllowed; monthOffset++) {
      const firstDateOfMonth: Date = startOfMonth(new Date()).addMonths(-monthOffset);
      const newDate: Date = new Date(firstDateOfMonth.getTime() - 1);
      this.months.push({ month: months[newDate.getMonth()] + ' ' + newDate.getFullYear(), date: newDate });
    }

    this.monthNames = this.months.map(month => month.month);

    if (this.currentFilter.month) {
      const selectedMonth = this.months.find(month => month.date?.getTime() === this.currentFilter.month.getTime());
      this.selectedMonthName = selectedMonth ? selectedMonth.month : this.months[0].month;
    } else {
      this.selectedMonthName = this.months[0].month;
      this.currentFilter.month = this.months[0].date;
    }
  }

  private subscribeToMonthsNames(): void {
    this.i18nService
      .getMonthsNames()
      .pipe(takeUntil(this.destroy$))
      .subscribe(months => {
        this.initMonths(months);
        this.cdRef.markForCheck();
      });
  }

  private subscribeToExpandedFormat(): void {
    this.betHistoryService.expandedFormat$.pipe(takeUntil(this.destroy$)).subscribe(expandedFormat => {
      this.betHistoryExpandedFormat = expandedFormat;
      this.cdRef.markForCheck();
    });
  }

  private applyFilters(): void {
    this.filter.emit(this.currentFilter);
  }
}
