import { Component, ChangeDetectionStrategy, EventEmitter, Output, Input } from '@angular/core';

@Component({
  selector: 'hg-odds-filter',
  templateUrl: './odds-filter.component.html',
  styleUrls: ['./odds-filter.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class OddsFilterComponent {
  public oddsFilters = [1.25, 1.5, 1.75, 2.0];

  @Input()
  public selectedOddsFilter: number;

  @Output()
  public oddsFilterSelected = new EventEmitter<number>();

  onFilterClick(filter?: number) {
    if (!filter || filter === this.selectedOddsFilter) {
      this.oddsFilterSelected.emit(null);
    } else {
      this.oddsFilterSelected.emit(filter);
    }
  }
}
