import {
  Component,
  OnInit,
  ChangeDetectionStrategy,
  Input,
  ViewContainerRef,
  Injector,
  PLATFORM_ID,
  Inject
} from '@angular/core';
import { DOCUMENT, isPlatformServer } from '@angular/common';
import { addScopedStyle } from '../../helper';
@Component({
  selector: 'hg-text-with-bg-and-button',
  templateUrl: './text-with-bg-and-button.component.html',
  styleUrls: ['./text-with-bg-and-button.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class TextWithBgAndButtonComponent implements OnInit {
  @Input()
  text: {
    html: string | { [key: string]: string };
    css: string;
  };

  @Input()
  css: string;

  @Input()
  position: 'left' | 'right' | 'center';

  @Input()
  bgUrl: string;

  @Input()
  bgUrlMd: string;

  @Input()
  button: {
    link: string;
    text: string;
    class: string;
  };

  localizedButtonText: string;
  private document: Document;

  constructor(injector: Injector, private viewContainerRef: ViewContainerRef, @Inject(PLATFORM_ID) private platformId) {
    this.document = injector.get(DOCUMENT);
  }

  ngOnInit() {
    if (this.button) {
      this.localizedButtonText = this.button.text;
    }

    addScopedStyle(
      this.css,
      this.document,
      this.viewContainerRef.element.nativeElement,
      isPlatformServer(this.platformId)
    );
  }
}
