import { ChangeDetectionStrategy, Component, EventEmitter, Input, Output } from '@angular/core';
import { Router } from '@angular/router';
import { BetCategoryFilterData, BetCategoryType } from '@honoregaming/types';

@Component({
  selector: 'hg-bet-categories-filter',
  templateUrl: './bet-categories-filter.component.html',
  styleUrls: ['./bet-categories-filter.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class BetCategoriesFilterComponent {
  @Input() betCategoriesFilterData: BetCategoryFilterData[] = [];
  @Input() activeCategory: BetCategoryType | string = BetCategoryType.Unknown;

  // Handle bet category type and string because "simulate" can be used to filter as a bet category
  @Output() categorySelected = new EventEmitter<BetCategoryType | string>();

  constructor(private router: Router) {}

  selectCategory(category: BetCategoryType | string, navigationPath?: string): void {
    this.categorySelected.emit(category);

    if (navigationPath) {
      this.router.navigate([navigationPath]);
    }
  }
}
