import { isPlatformServer } from '@angular/common';
import {
  ChangeDetectorRef,
  Component,
  EventEmitter,
  HostBinding,
  Inject,
  Input,
  OnDestroy,
  OnInit,
  Optional,
  Output,
  PLATFORM_ID
} from '@angular/core';
import { Router } from '@angular/router';
import { DateTime } from 'luxon';
import { Subscription, combineLatest, of } from 'rxjs';
import { catchError, finalize, take, takeUntil } from 'rxjs/operators';
import { FreeBetCoupon } from '@honoregaming/betslip';
import { OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';
import {
  Async,
  AsyncTrigger,
  BetCategoryConfigurationService,
  BroadcastingService,
  DestroySubject,
  DialogService,
  getUtcNow
} from '@honoregaming/core';
import {
  AuthService,
  CustomerService,
  CustomerState,
  Me,
  NavigationService,
  UserInformationsService,
  ValidateGuard
} from '@honoregaming/customer-core';
import { I18nService } from '@honoregaming/i18n';
import { ContentService } from '@honoregaming/templating';
import { LoginPolicy, SecurityPolicy } from '@honoregaming/types';
import { GenericContentComponent, Media, MediaService, MessageService } from '@honoregaming/ui';
import { NotificationInfos } from 'projects/customer/hg-core/src/lib/models/notifications-infos.model';
import { LoyaltyStatusNotificationComponent } from '../../../../../customer/src/app/popins/loyalty-status-notification/loyalty-status-notification.component';
import { NegativeBalanceNotAllowedComponent } from '../../../../../customer/src/app/popins/negative-balance-not-allowed/negative-balance-not-allowed.component';
import { ActiveSessionAlreadyExistsComponent } from '../../../../../customer/src/app/popins/session-already-active/session-already-active.component';
import { UserBlockedComponent } from '../../../../../customer/src/app/popins/user-blocked/user-blocked.component';
import { WonBetSystemsNotificationComponent } from '../../../../../customer/src/app/popins/won-bet-systems-notification/won-bet-systems-notification.component';
import { WonTournamentNotificationComponent } from '../../../../../customer/src/app/popins/won-tournament-notification/won-tournament-notification.component';
import { NavBarService } from '../../../../../customer/src/app/services';
import { CreateAccessTokenFailure } from './create-access-token-failure.enum';

@Component({
  selector: 'hg-login',
  templateUrl: './login.component.html',
  styleUrls: ['./login.component.scss']
})
export class LoginComponent extends DestroySubject implements OnInit, OnDestroy {
  securityPolicy: SecurityPolicy;
  login: string | undefined;
  password: string;
  loading = false;
  remember: boolean;
  invalidIdOrPasswordError = false;
  hasEmptyLogin = true;
  endRestrictionDate: DateTime;
  isServer = isPlatformServer(this.platformId);

  content: string;
  style: string;
  showPasswordValue = false;
  isRedirection: boolean;
  me: Me;
  currentMedia?: Media;

  Media = Media;

  @AsyncTrigger()
  languageTrigger = this.i18nService.languageChanged$;

  @Input()
  fromMobileDeposit = false;
  private getMeSubscription: Subscription;

  @Input() closePopup: boolean;
  @Input() freeBetsWon: number;
  @Input() freebetCount: number;
  @Input() actualFreeBalance: number;
  @Input() newFreeBalance: string;
  @Input() freeBets: number;
  @Input() name: string;
  @Input() actualFreeBetCoupons: FreeBetCoupon[] = [];
  @Input() newFreeBetCoupons: FreeBetCoupon[] = [];

  @HostBinding('class.active')
  @Input()
  active: boolean;

  @HostBinding('class.from-desktop-deposit')
  @Input()
  fromDesktopDeposit = true;

  @HostBinding('class.from-landing')
  @Input()
  fromLanding = false;

  @Output()
  myAccountClick = new EventEmitter<{}>();

  @Output()
  close = new EventEmitter<{}>();

  loginContentAlreadyLoaded = false;

  instantGamesBetCategoryPath = this.betCategoryConfigurationService.getInstantGamesBetCategoryPath();

  constructor(
    @Optional() protected mediaService: MediaService,
    protected authService: AuthService,
    protected cdRef: ChangeDetectorRef,
    private customerService: CustomerService,
    protected router: Router,
    private messageService: MessageService,
    protected dialogService: DialogService,
    @Inject(operatorConfigurationToken) private operatorConfiguration: OperatorConfiguration,
    private i18nService: I18nService,
    private userInfoService: UserInformationsService,
    @Inject(PLATFORM_ID) private platformId,
    private navigationService: NavigationService,
    private navBarService: NavBarService,
    private contentService: ContentService,
    private betCategoryConfigurationService: BetCategoryConfigurationService,
    private broadCastingService: BroadcastingService
  ) {
    super();
  }

  ngOnInit() {
    this.i18nService.languageChanged$.pipe(takeUntil(this.destroy$)).subscribe(() => {
      this.loginContentAlreadyLoaded = false;
    });

    this.mediaService.media$.pipe(takeUntil(this.destroy$)).subscribe(media => {
      this.currentMedia = media;
      if (media <= Media.md || this.fromLanding) {
        this.loadContent();
      }
    });

    this.remember = this.authService.isUserRemembered() || false;
    this.login = this.authService.getUserRemembered() || '';
    this.customerService
      .getSecurityPolicy()
      .pipe(takeUntil(this.destroy$))
      .subscribe(policy => {
        this.securityPolicy = policy;
        this.cdRef.markForCheck();
      });

    this.dialogService.registerDialog('login').subscribe(open => {
      this.active = open;
      this.cdRef.markForCheck();
    });

    this.navBarService.clickOnMyBetsRedirection.pipe(takeUntil(this.destroy$)).subscribe(redirection => {
      this.isRedirection = redirection;
      this.cdRef.markForCheck();
    });

    this.getMe();
  }

  getMe() {
    this.getMeSubscription?.unsubscribe();
    this.getMeSubscription = this.authService.me$.pipe(takeUntil(this.destroy$)).subscribe(me => {
      this.me = me;
      if (
        me &&
        this.operatorConfiguration.global &&
        me.balance <= this.operatorConfiguration.global.mininumBalanceBeforeAlert
      ) {
        this.i18nService
          .formatCurrency(this.operatorConfiguration.global.mininumBalanceBeforeAlert)
          .pipe(take(1))
          .subscribe(_balance => {
            this.userInfoService.sendMessageUserI18n(
              'ACCOUNT.BALANCE.LESSTHAN',
              '' + this.operatorConfiguration.global.mininumBalanceBeforeAlert
            );
          });
      } else if (me && me.selfExclusionEndDate && new Date(me.selfExclusionEndDate) > getUtcNow()) {
        const selfExclusionEndDate = me.selfExclusionEndDate.toString();

        combineLatest([
          this.i18nService.formatLongDate(selfExclusionEndDate),
          this.i18nService.formatLongTime(selfExclusionEndDate)
        ])
          .pipe(takeUntil(this.destroy$), take(1))
          .subscribe(([date, time]) => {
            this.messageService.sendComponentMessage(
              GenericContentComponent,
              {
                title: this.i18nService.translateSync('RESPONSIBLE_GAMBLING.SELFEXCLUSION.WARNING_TITLE'),
                text: this.i18nService.translateSync(
                  new Date(me.selfExclusionEndDate).getUTCFullYear() !== 9999
                    ? 'RESPONSIBLE_GAMBLING.SELFEXCLUSION.EXPLANATIONS_TEXT'
                    : 'RESPONSIBLE_GAMBLING.SELFEXCLUSION.EXPLANATIONS_TEXT_DEFINITIVE',
                  date,
                  time
                ),
                subText: this.i18nService.translateSync(
                  'RESPONSIBLE_GAMBLING.SELFEXCLUSION.EXPLANATIONS_SUBTEXT',
                  date,
                  time
                ),
                okButton: true,
                okButtonTranslationKey: 'RESPONSIBLE_GAMBLING.SELFEXCLUSION.OK'
              },
              {
                canBeDismissed: true,
                displayClose: true
              }
            );
          });
      }

      this.cdRef.markForCheck();

      if (me && this.me.mustChangePassword) {
        this.router.navigate(['update-password']);
      } else if (me && !me.hasAcceptedGcu && this.router.url.indexOf('step') === -1) {
        this.broadCastingService.broadcast('display-gcu-popin');
      } else if (
        me &&
        !this.operatorConfiguration.smarticoConfiguration?.popupsEnabled &&
        !!me.notificationInformations
      ) {
        this.manageNotifications(me.notificationInformations);
      }
    });
  }

  submit(withRefresh = false, customerId?: string) {
    if (this.loading) {
      return;
    }

    this.invalidIdOrPasswordError = false;
    this.endRestrictionDate = null;
    this.loading = true;
    this.cdRef.markForCheck();

    this.authService
      .login(this.login, this.password, this.remember, withRefresh, customerId)
      .pipe(takeUntil(this.destroy$))
      .subscribe(
        () => {
          this.loading = false;
          this.login = null;
          this.hasEmptyLogin = true;
          this.password = null;
          this.dialogService.toggleDialog('login', false);
          const validation = new ValidateGuard(this.authService, this.router).canActivate(
            null,
            this.router.routerState.snapshot
          );
          this.close.emit();

          if (this.fromMobileDeposit) {
            this.router.navigate(['myaccount', 'deposit']);
          }

          if (this.fromLanding) {
            this.router.navigate(['/']);
          }

          if (this.isRedirection) {
            if (this.router.url === `/${this.instantGamesBetCategoryPath}`) {
              this.router.navigateByUrl('/myaccount/instant-games-history');
            } else {
              this.router.navigate(['myaccount', 'history']);
            }
          }

          validation.subscribe(
            _x => {},
            _e => {
              if (this.me.state === CustomerState.Blacklisted) {
                this.router.navigate(['myaccount', 'registration', 'step1']);
              } else if (
                this.me.isLocked &&
                this.me.state === CustomerState.LoginValidated &&
                this.operatorConfiguration.operatorFeatures.indexOf('CustomerAccountLockManagement') > -1
              ) {
                this.router.navigate(['myaccount', 'unlock']);
              } else {
                this.router.navigate(['myaccount', 'registration', 'step2']);
              }
            }
          );
          this.isRedirection = false;
          this.getMe();
        },
        err => {
          this.loading = false;

          if (err.error.code === CreateAccessTokenFailure.UserBlocked) {
            this.messageService.sendComponentMessage(UserBlockedComponent);
          } else if (err.error.code === CreateAccessTokenFailure.UserBlockedWithDuration) {
            this.messageService.sendComponentMessage(UserBlockedComponent, { withDuration: true });
          } else if (err.error.code === CreateAccessTokenFailure.ActiveSessionAlreadyExists) {
            this.messageService
              .sendComponentMessage(ActiveSessionAlreadyExistsComponent, {
                device: err.error.additionalData.device
              })
              .closed.subscribe(result => {
                if (!!result) {
                  this.submit(true, err.error.additionalData.customerId);
                }
              });
          } else if (err.error.code === CreateAccessTokenFailure.NegativeBalanceNotAllowed) {
            this.messageService.sendComponentMessage(NegativeBalanceNotAllowedComponent);
          } else {
            this.invalidIdOrPasswordError = true;
          }

          this.cdRef.markForCheck();
        }
      );
  }

  logout() {
    this.authService.logout();
    this.me = null;
    this.cdRef.markForCheck();
  }

  openLoginPanel() {
    this.dialogService.toggleDialog('login', true);
  }

  closeLoginPanel() {
    this.dialogService.toggleDialog('login', false);
    this.close.emit();
  }

  ngOnDestroy(): void {
    if (this.getMeSubscription) {
      this.getMeSubscription.unsubscribe();
    }
  }

  manageNotifications(notif: NotificationInfos) {
    if (!!notif.loyaltyStatus) {
      this.messageService
        .sendComponentMessage(
          LoyaltyStatusNotificationComponent,
          { newLoyaltyStatus: notif.loyaltyStatus },
          {
            className: 'no-side-padding',
            canBeDismissed: true,
            displayClose: true
          }
        )
        .closed.subscribe(_ => {
          this.me.notificationInformations.loyaltyStatus = null;
        });
    }
    if (!!notif.betSystems) {
      this.messageService
        .sendComponentMessage(
          WonBetSystemsNotificationComponent,
          {
            notif: notif.betSystems
          },
          {
            className: 'beauty-close high-popin',
            canBeDismissed: true,
            displayClose: true,
            wowEffect: true
          }
        )
        .closed.subscribe(_ => {
          this.me.notificationInformations.betSystems = null;
        });
    }
    if (notif.wonTournaments?.length) {
      this.messageService
        .sendComponentMessage(
          WonTournamentNotificationComponent,
          { tournaments: notif.wonTournaments },
          { className: 'popin-tournament-won', canBeDismissed: true, displayClose: false }
        )
        .closed.subscribe(() => {
          this.me.notificationInformations.wonTournaments = null;
        });
    }
  }

  register() {
    this.navigationService.goToSignup();
  }

  lostPassword() {
    this.navigationService.goToLostPassword();
  }

  @Async()
  loadContent() {
    if (this.loginContentAlreadyLoaded || this.authService.isAuthenticated()) {
      return;
    }

    this.loading = true;
    this.contentService
      .getContent('login')
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.loading = false;
          this.cdRef.markForCheck();
        }),
        catchError(_ => of(null))
      )
      .subscribe(resource => {
        this.content = resource?.content;
        this.style = resource?.style;
        this.loginContentAlreadyLoaded = true;
      });
  }

  checkIfLoginIsEmpty(): void {
    if (!this.login?.length) {
      this.hasEmptyLogin = true;
    } else if (!this.securityPolicy?.loginPoliciesRequirements?.length) {
      this.hasEmptyLogin = false;
    } else {
      const currentLoginPolicyRequirementsIndex: number = this.securityPolicy.loginPoliciesRequirements.findIndex(
        (loginPolicy: LoginPolicy) => loginPolicy.prefix && this.login.includes(loginPolicy.prefix)
      );
      this.hasEmptyLogin =
        this.login.length -
          this.securityPolicy.loginPoliciesRequirements[currentLoginPolicyRequirementsIndex].prefix.length <=
        0;
    }
  }

  onLoginChange(): void {
    this.invalidIdOrPasswordError = false;
    this.checkIfLoginIsEmpty();
    this.cdRef.markForCheck();
  }
}
