import { DOCUMENT } from '@angular/common';
import {
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  ElementRef,
  Inject,
  Input,
  NgZone,
  OnInit
} from '@angular/core';
import { BehaviorSubject, EMPTY, fromEvent, merge, Observable } from 'rxjs';
import { distinctUntilChanged, filter, shareReplay, switchMap, takeUntil } from 'rxjs/operators';
import { DestroySubject, LocalStorageService } from '@honoregaming/core';
import { SmarticoService } from '@honoregaming/customer-core';
import { SmarticoNavigationItem } from '@honoregaming/types';
import {
  DeepLinkParams,
  DpType,
  UserPublicProperties
} from 'projects/customer/hg-core/src/lib/models/smartico-sdk.model';

type SmarticoIdentifier =
  | 'SmarticoSelector_Badges'
  | 'SmarticoSelector_Missions'
  | 'SmarticoSelector_Notifications'
  | 'SmarticoSelector_Store'
  | 'SmarticoSelector_Promotions';

type SmarticoBadge = 'none' | 'missions' | 'notifications';

interface SmarticoMenuItem {
  id: SmarticoIdentifier;
  deepLinkType: DpType;
  deepLinkParams?: DeepLinkParams;
  icon: string;
  labelKey: string;
  badge: SmarticoBadge;
  navigationItem: SmarticoNavigationItem;
}

@Component({
  selector: 'hg-smartico-selector',
  templateUrl: './smartico-selector.component.html',
  styleUrls: ['./smartico-selector.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class SmarticoSelectorComponent extends DestroySubject implements OnInit {
  @Input() width!: number;

  private static readonly LAST_UNREAD_COUNT_KEY = 'smartico:last-unread-count';

  isOpenSubject: BehaviorSubject<boolean> = new BehaviorSubject<boolean>(false);
  isOpen$: Observable<boolean> = this.isOpenSubject.asObservable();

  jiggle: boolean = false;

  isGamificationWidgetOpen$!: Observable<boolean>;
  userProps$!: Observable<UserPublicProperties>;
  missionsCount$!: Observable<number>;

  menuItems!: SmarticoMenuItem[];

  constructor(
    private readonly smarticoService: SmarticoService,
    private readonly cdRef: ChangeDetectorRef,
    private readonly elementRef: ElementRef,
    private readonly ngZone: NgZone,
    private readonly localStorageService: LocalStorageService,
    @Inject(DOCUMENT) private readonly document: Document
  ) {
    super();
  }

  ngOnInit(): void {
    this.setupMenuItems();
    this.setupDismissOnOutsideInteraction();
    this.setupGamificationStreams();
    this.setupJiggleOnNewMessages();
  }

  private setupMenuItems(): void {
    const allMenuItems: SmarticoMenuItem[] = [
      {
        id: 'SmarticoSelector_Badges',
        deepLinkType: DpType.Badges,
        icon: 'assets/smartico/badge.png',
        labelKey: 'SMARTICO.MY_BADGES',
        badge: 'none',
        navigationItem: SmarticoNavigationItem.Badges
      },
      {
        id: 'SmarticoSelector_Missions',
        deepLinkType: DpType.Missions,
        icon: 'assets/smartico/mission.png',
        labelKey: 'SMARTICO.MISSIONS',
        badge: 'missions',
        navigationItem: SmarticoNavigationItem.Missions
      },
      {
        id: 'SmarticoSelector_Notifications',
        deepLinkType: DpType.Activity,
        icon: 'assets/smartico/notification.png',
        labelKey: 'SMARTICO.NOTIFICATIONS',
        badge: 'notifications',
        navigationItem: SmarticoNavigationItem.Notifications
      },
      {
        id: 'SmarticoSelector_Store',
        deepLinkType: DpType.Store,
        icon: 'assets/smartico/store.png',
        labelKey: 'SMARTICO.STORE',
        badge: 'none',
        navigationItem: SmarticoNavigationItem.Store
      },
      {
        id: 'SmarticoSelector_Promotions',
        deepLinkType: DpType.HgGo,
        deepLinkParams: { to: '/about/promotions' },
        icon: 'assets/smartico/promotion.png',
        labelKey: 'SMARTICO.PROMOTIONS',
        badge: 'none',
        navigationItem: SmarticoNavigationItem.Promotions
      }
    ];
    this.menuItems = allMenuItems.filter(item => this.smarticoService.isNavigationItemVisible(item.navigationItem));
    this.cdRef.markForCheck();
  }

  executeDeepLink(type: DpType, params?: DeepLinkParams): void {
    this.smarticoService.executeDeepLink(type, params);
    this.close();
  }

  toggle(): void {
    this.smarticoService.closeGamificationWidget();
    this.isOpenSubject.next(!this.isOpenSubject.value);
    if (this.jiggle) {
      this.jiggle = false;
    }
    this.cdRef.markForCheck();
  }

  trackByItemId(_index: number, item: SmarticoMenuItem): string {
    return item.id;
  }

  private close(): void {
    this.isOpenSubject.next(false);
    this.cdRef.markForCheck();
  }

  private jiggleOnNewMessages(unreadCount: number): void {
    const lastUnreadCount: number = +(
      this.localStorageService.getItem(SmarticoSelectorComponent.LAST_UNREAD_COUNT_KEY) ?? -1
    );
    this.localStorageService.setItem(SmarticoSelectorComponent.LAST_UNREAD_COUNT_KEY, unreadCount);
    if (unreadCount > lastUnreadCount) {
      this.jiggle = true;
      this.cdRef.markForCheck();
    }
  }

  private setupDismissOnOutsideInteraction(): void {
    const closingEvents$: Observable<Event> = merge(
      fromEvent(this.document, 'scroll'),
      fromEvent<MouseEvent>(this.document, 'click').pipe(
        filter(event => !this.elementRef.nativeElement.contains(event.target))
      ),
      fromEvent<KeyboardEvent>(this.document, 'keydown').pipe(filter(event => event.key === 'Escape'))
    );
    this.ngZone.runOutsideAngular(() =>
      this.isOpen$
        .pipe(
          distinctUntilChanged(),
          switchMap(open => (open ? closingEvents$ : EMPTY)),
          takeUntil(this.destroy$)
        )
        .subscribe(() => this.ngZone.run(() => this.close()))
    );
  }

  private setupGamificationStreams(): void {
    this.userProps$ = this.smarticoService.userPublicProperties$.pipe(
      filter((userProps): userProps is UserPublicProperties => !!userProps),
      takeUntil(this.destroy$),
      shareReplay(1)
    );
    this.missionsCount$ = this.smarticoService.missionsCount$;
    this.isGamificationWidgetOpen$ = this.smarticoService.isGamificationWidgetOpen$;
  }

  private setupJiggleOnNewMessages(): void {
    this.userProps$
      .pipe(takeUntil(this.destroy$))
      .subscribe(userProps => this.jiggleOnNewMessages(userProps?.core_inbox_unread_count ?? 0));
  }
}
