import { Component, ChangeDetectionStrategy, Input, Renderer2, ViewChild, ChangeDetectorRef } from '@angular/core';
import { ControlValueAccessor, NG_VALUE_ACCESSOR } from '@angular/forms';
import { I18nService } from '@honoregaming/i18n';
import { Observable } from 'rxjs';
import { take } from 'rxjs/operators';
import { add, sub, mod } from '@honoregaming/core';

@Component({
  selector: 'hg-number-picker',
  templateUrl: './number-picker.component.html',
  styleUrls: ['./number-picker.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: NumberPickerComponent,
      multi: true
    }
  ]
})
export class NumberPickerComponent implements ControlValueAccessor {
  @ViewChild('input')
  input;

  innerValue: number;
  private changed = new Array<(v: number) => void>();
  private touched = new Array<() => void>();

  @Input()
  allowRealtime = false;
  @Input()
  allowZeroValue = false;
  @Input()
  minimum;
  @Input()
  increment;
  @Input()
  maximum: number;
  @Input()
  handleInputClick = false;
  @Input()
  onInputClick: () => Observable<any>;

  disabled: boolean;

  constructor(private i18nService: I18nService, private renderer: Renderer2, private cdRef: ChangeDetectorRef) {}

  get value(): number {
    return +this.innerValue;
  }

  set value(value: number) {
    if (value == null) {
      value = 0;
    }

    const newValue = value != null ? this.i18nService.unformatNumber('' + value) : value;
    if (
      !isNaN(newValue) &&
      this.innerValue !== newValue &&
      (this.allowRealtime ||
        (this.allowZeroValue && newValue === 0) ||
        ((!this.minimum || this.minimum <= newValue) &&
          (!this.maximum || this.maximum >= newValue) &&
          (!this.increment || mod(sub(newValue, this.minimum ? this.minimum : 0), this.increment) === 0)))
    ) {
      if (!(value.toString().includes('.') && +value.toString().split('.')[1] === 0)) {
        this.innerValue = newValue;
      }

      this.changed.forEach(f => f(newValue));
      return;
    }

    if (!this.allowRealtime) {
      this.i18nService
        .formatCurrency(this.innerValue)
        .pipe(take(1))
        .subscribe(x => {
          if (this.input) {
            this.renderer.setProperty(this.input.nativeElement, 'value', x);
          }
        });
    }
  }

  updateOn() {
    return this.allowRealtime ? 'change' : 'blur';
  }

  more() {
    const newValue = add(this.value, this.increment);
    if (newValue < this.minimum) {
      this.value = this.minimum;
    } else if (this.maximum && newValue >= this.maximum) {
      this.value = this.maximum;
    } else {
      this.value = newValue;
    }
  }

  less() {
    const newValue = sub(this.value, this.increment);
    if (newValue < this.minimum) {
      this.value = this.allowZeroValue ? 0 : this.minimum;
    } else if (this.maximum && newValue >= this.maximum) {
      this.value = this.maximum;
    } else {
      this.value = newValue;
    }
  }

  writeValue(obj: number): void {
    // TODO: check
    this.value = obj;
  }

  registerOnChange(fn: any): void {
    this.changed.push(fn);
  }

  registerOnTouched(fn: any): void {
    this.touched.push(fn);
  }

  touch() {
    this.touched.forEach(f => f());
  }

  handleClick(): void {
    if (this.handleInputClick && this.onInputClick && !this.disabled) {
      this.onInputClick().subscribe(value => {
        if (value) {
          this.writeValue(value);
        }
      });
    }
  }

  setDisabledState(isDisabled: boolean) {
    this.disabled = isDisabled;
    this.cdRef.markForCheck();
  }
}
