import { Component, EventEmitter, Input, Output } from '@angular/core';

@Component({
  selector: 'hg-customer-xup',
  templateUrl: './xup.component.html',
  styleUrls: ['./xup.component.scss']
})
export class XupComponent {
  @Input() value: string;

  @Output() close = new EventEmitter<boolean>();

  closePopin(): void {
    this.close.emit();
  }
}
