import { Directive, OnInit, ChangeDetectorRef } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { merge, Observable } from 'rxjs';
import { finalize, skip, takeUntil } from 'rxjs/operators';
import { EventCategoriesService } from '@honoregaming/events';
import { EventCategory } from '@honoregaming/types';
import { I18nService } from '@honoregaming/i18n';
import { Async, AsyncTrigger, DestroySubject } from '@honoregaming/core';

@Directive()
// tslint:disable-next-line: directive-class-suffix
export class EventCategoriesNavigationComponent extends DestroySubject implements OnInit {
  loading = false;
  entryPoints: EventCategory[] = [];
  currentEntryPoint?: EventCategory;

  @AsyncTrigger() readonly languageTrigger: Observable<string> = this.i18nService.languageChanged$;

  constructor(
    protected readonly i18nService: I18nService,
    protected readonly route: ActivatedRoute,
    protected readonly eventCategoriesService: EventCategoriesService,
    protected readonly cdRef: ChangeDetectorRef
  ) {
    super();
  }

  ngOnInit(): void {
    this.loadEntryPoints();
  }

  @Async()
  protected loadEntryPoints(): void {
    this.loading = true;
    const SPORTS_POOL_ROOT_ID: number = 9002;

    this.eventCategoriesService
      .getEntryPointsByIds([SPORTS_POOL_ROOT_ID])
      .pipe(
        takeUntil(
          merge(this.route.params.pipe(skip(1)), this.i18nService.languageChanged$.pipe(skip(1)), this.destroy$)
        ),
        finalize(() => {
          this.finishLoading();
        })
      )
      .subscribe(entryPoints => {
        this.entryPoints = entryPoints ?? [];
        this.updateCurrentEntryPoint();
      });
  }

  protected updateCurrentEntryPoint(): void {
    const eventCategoryId: number = Number(this.route.snapshot.params['eventCategory']);

    if (!eventCategoryId || !this.entryPoints.length) {
      this.currentEntryPoint = undefined;
      return;
    }

    this.currentEntryPoint = this.entryPoints.find(entry => entry.id === eventCategoryId);
  }

  protected finishLoading(): void {
    this.loading = false;
    this.cdRef.markForCheck();
  }
}
