import { ChangeDetectionStrategy, Component, Input } from '@angular/core';
import { CustomerWithdrawalInformation } from '../../models/customer-withdrawal-information.model';

@Component({
  selector: 'hg-withdrawal-forbidden',
  templateUrl: './withdrawal-forbidden.component.html',
  styleUrls: ['./withdrawal-forbidden.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class WithdrawalForbiddenComponent {
  @Input() information!: CustomerWithdrawalInformation;
  @Input() popin: boolean = false;

  get remainingDelayInHoursAndMinutes(): string {
    return this.formatSeconds(this.information.remainingDelayInSeconds ?? 0);
  }

  private formatSeconds(seconds: number): string {
    const hours: number = Math.floor(seconds / 3600);
    const minutes: number = Math.floor((seconds % 3600) / 60);
    const remainingSeconds: number = seconds % 60;

    return [hours, minutes, remainingSeconds].map((value: number) => this.padToTwoDigits(value)).join(':');
  }

  private padToTwoDigits(value: number): string {
    return value < 10 ? `0${value}` : `${value}`;
  }
}
