import {
  Component,
  OnInit,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Input,
  Output,
  EventEmitter,
  ViewChild,
  ElementRef,
  Inject
} from '@angular/core';
import { finalize, takeUntil } from 'rxjs/operators';
import {
  Me,
  KnowYourCustomerConfiguration,
  DocumentTypeConfiguration,
  CustomerStatus,
  CustomerState,
  CustomerOperatorConfiguration,
  customerOperatorConfigurationToken
} from '@honoregaming/customer-core';
import { DestroySubject } from '@honoregaming/core';
import { IncomeSourceType } from 'projects/core/hg-types/models/enums/income-source-type.enum';
import { CustomerService } from '@honoregaming/customer-core';
import { ProfilePolicy, CountryCode } from '@honoregaming/types';
import { I18nService } from '@honoregaming/i18n';
import { DateTime } from 'luxon';

@Component({
  selector: 'hg-account-validate-identity',
  templateUrl: './account-validate-identity.component.html',
  styleUrls: ['./account-validate-identity.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class AccountValidateIdentityComponent extends DestroySubject implements OnInit {
  @Input() knowYourCustomerConfiguration: KnowYourCustomerConfiguration;
  @Input() profilePolicyRequirements: ProfilePolicy;
  @Input() me: Me;
  @Input() countries: CountryCode[];

  formData: CustomerProfile = {
    gender: null,
    firstName: null,
    lastName: null,
    email: null,
    birthdate: '',
    address: null,
    zipCode: null,
    city: null,
    country: null,
    incomeSource: null,
    nationality: null,
    state: '',
    politicallyExposedPerson: null
  };

  birthdate: { day: string; month: string; year: string } = {
    day: undefined,
    month: undefined,
    year: undefined
  };
  documents: {
    identification: {
      recto: string;
      verso: string;
    };
    proofOfResidence: string;
  };
  step: number = 1;
  selectedDocumentType: DocumentTypeConfiguration;
  indexDocumentType: number = 0;
  loading: boolean = false;
  error: boolean | string = false;
  numberOfRequiredDocumentType: number = 100;
  finishSend = false;

  @Output()
  backEvent = new EventEmitter();

  @Output()
  finishValidationEvent = new EventEmitter();

  @ViewChild('inputFile') inputFile: ElementRef;
  showMfa: boolean;
  mfaCode: string;

  useExternalKYCValidation: boolean =
    this.customerOperatorConfiguration.knowYourCustomerConfiguration?.useExternalKYCValidation || false;

  get maxStep(): number {
    return this.numberOfRequiredDocumentType + 2;
  }

  get showStepProgress(): boolean {
    return (
      !this.showMfa &&
      !!this.knowYourCustomerConfiguration &&
      this.me.profile?.profileStatus !== CustomerStatus.Verified &&
      !this.useExternalKYCValidation
    );
  }

  constructor(
    private customerService: CustomerService,
    private cdRef: ChangeDetectorRef,
    @Inject(customerOperatorConfigurationToken) private customerOperatorConfiguration: CustomerOperatorConfiguration,
    private i18nService: I18nService
  ) {
    super();
  }

  ngOnInit(): void {
    if (this.knowYourCustomerConfiguration?.documentTypesConfiguration?.length) {
      this.selectedDocumentType =
        this.knowYourCustomerConfiguration?.documentTypesConfiguration[this.indexDocumentType];
    }

    this.formData.firstName = this.me.profile?.firstName;
    this.formData.lastName = this.me.profile?.lastName;
    const [birthdateYear, birthdateMonth, birthdateDay] = this.me.profile?.birthdate?.slice(0, 10).split('-') ?? [];
    this.birthdate.day = birthdateDay ?? '';
    this.birthdate.month = birthdateMonth ?? '';
    this.birthdate.year = birthdateYear ?? '';
    this.formData.address = this.me.profile?.street;
    this.formData.city = this.me.profile?.city;
    this.formData.zipCode = this.me.profile?.zipCode;
    this.formData.country = this.me.profile?.country;
    this.formData.state = this.me.profile?.region;
    this.formData.incomeSource = this.me.profile?.incomeSource;
    this.formData.nationality = this.me.profile?.nationality;
    this.formData.gender = this.me.profile?.gender;
    this.formData.email = this.me.profile?.email;
    this.formData.politicallyExposedPerson = this.me.profile?.politicallyExposedPerson;
    this.numberOfRequiredDocumentType =
      this.knowYourCustomerConfiguration?.documentTypesConfiguration?.filter(e => e.isRequired)?.length ?? 0;

    this.handleRequiredBooleanProfileFields();
  }

  handleBack() {
    if (this.step === 1) {
      this.backEvent.emit();
      return;
    }

    this.step--;
  }

  submit() {
    if (!this.formIsValid()) {
      this.error = this.i18nService.translateSync('ACCOUNT.PROFILE.ERROR');
      return;
    }

    if (this.knowYourCustomerConfiguration && this.customerIsUnderage()) {
      this.error = this.i18nService.translateSync(
        'REGISTRATION.STEP1.ERROR.PROFILE.BIRTHDATE',
        this.knowYourCustomerConfiguration.customerAccessLimitationConfiguration.minimumAgeRequired.toString()
      );
      return;
    }

    if (
      this.customerOperatorConfiguration.mfaConfiguration?.customerConfiguration?.updatePersonalInformation &&
      (this.me.state === CustomerState.IdentityValidated || this.me.state === CustomerState.Validated)
    ) {
      this.showMfa = true;
      this.cdRef.markForCheck();
    } else {
      this.sendSubmit();
    }
  }

  sendRequestWithMFA(code: string) {
    this.mfaCode = code;
    this.showMfa = false;
    if (this.finishSend) {
      this.sendFinishIdentityCustomerValidation();
    } else {
      this.sendSubmit();
    }
  }

  sendSubmit() {
    this.finishSend = false;
    this.loading = true;
    this.customerService
      .updateCustomerProfile(
        this.formData.country,
        this.me.profile?.phoneNumber,
        this.formatBirthdayDate(this.birthdate.month, this.birthdate.day, this.birthdate.year),
        this.formData.city,
        this.formData.gender,
        this.formData.state,
        this.formData.address,
        this.formData.firstName,
        null,
        this.formData.lastName,
        this.formData.email,
        this.formData.incomeSource as IncomeSourceType,
        this.formData.zipCode,
        this.formData.nationality,
        this.formData.politicallyExposedPerson,
        this.mfaCode
      )
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.loading = false;
          this.showMfa = false;
          this.cdRef.markForCheck();
        })
      )
      .subscribe(
        () => {
          if (
            this.me.profile?.profileStatus === CustomerStatus.Verified ||
            !this.knowYourCustomerConfiguration ||
            this.useExternalKYCValidation
          ) {
            this.finishValidationEvent.emit(false);
            return;
          }
          this.step++;
        },
        err => {
          if (err.error?.code === UpdateProfileFailure.EmailAlreadyTaken) {
            this.error = this.i18nService.translateSync('UPDATE_EMAIL.ERROR.ALREADY_TAKEN');
          } else {
            this.error = this.i18nService.translateSync('COMMON.GENERIC.ERROR');
          }
          return;
        }
      );
  }

  private customerIsUnderage() {
    const customerBirthdate = new Date(this.birthdate.month + '/' + this.birthdate.day + '/' + this.birthdate.year);
    const today = new Date();

    const differenceInMilliseconds = today.valueOf() - customerBirthdate.valueOf();
    const millisecondsInYear = 1000 * 60 * 60 * 24 * 365.25;
    const differenceInYears = Math.floor(differenceInMilliseconds / millisecondsInYear);
    if (
      differenceInYears < this.knowYourCustomerConfiguration?.customerAccessLimitationConfiguration.minimumAgeRequired
    ) {
      return true;
    }

    return false;
  }

  formIsValid() {
    let isValid = true;
    this.profilePolicyRequirements.fields.map(field => {
      if (
        field.type === 'text' &&
        !field.updateIgnored &&
        ((field.required && !this.formData[field.name]) ||
          (this.formData[field.name] && this.formData[field.name].length > 100))
      ) {
        isValid = false;
      }

      if (
        field.type === 'date' &&
        !field.updateIgnored &&
        !(new Date(this.birthdate.month + '/' + this.birthdate.day + '/' + this.birthdate.year) instanceof Date)
      ) {
        isValid = false;
      }

      if (field.type === 'list' && !field.updateIgnored && field.required && !this.formData[field.name]) {
        isValid = false;
      }

      if (field.type === 'bool' && !field.updateIgnored && field.required && this.formData[field.name] === null) {
        isValid = false;
      }
    });

    return isValid;
  }

  nextDocumentType() {
    this.step++;
    if (this.indexDocumentType + 1 < this.knowYourCustomerConfiguration?.documentTypesConfiguration.length) {
      this.indexDocumentType++;
      this.selectedDocumentType =
        this.knowYourCustomerConfiguration?.documentTypesConfiguration[this.indexDocumentType];
    }
  }

  previousDocumentType(index: number) {
    this.indexDocumentType = index;
    this.selectedDocumentType = this.knowYourCustomerConfiguration?.documentTypesConfiguration[this.indexDocumentType];

    this.step--;
  }

  finishIdentityCustomerValidation() {
    this.finishSend = true;
    if (
      this.customerOperatorConfiguration.mfaConfiguration?.customerConfiguration?.updatePersonalInformation &&
      (this.me.state === CustomerState.IdentityValidated || this.me.state === CustomerState.Validated)
    ) {
      this.showMfa = true;
      this.cdRef.markForCheck();
    } else {
      this.sendFinishIdentityCustomerValidation();
    }
  }

  sendFinishIdentityCustomerValidation() {
    this.loading = true;
    this.customerService
      .finishIdentityCustomerValidation()
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.loading = false;
          this.cdRef.markForCheck();
        })
      )
      .subscribe(_response => {
        this.finishValidationEvent.emit();
      });
  }

  formatBirthdayDate(month: string, day: string, year: string): Date {
    let newDate = new Date(month + '/' + day + '/' + year);
    let luxonDate = DateTime.utc(newDate.getFullYear(), newDate.getMonth() + 1, newDate.getDate());
    let finalBirthDayDate = luxonDate.toJSDate();
    return finalBirthDayDate;
  }

  onNationalityChange(countryCode: string) {
    this.formData.nationality = countryCode;
  }

  handleRequiredBooleanProfileFields() {
    this.profilePolicyRequirements.fields = [
      ...this.profilePolicyRequirements?.fields?.map(field => {
        if (field.type === 'bool' && field.required) {
          this.formData[field.name] ??= false;
        }

        return field;
      })
    ];
  }
}

enum UpdateProfileFailure {
  EmailAlreadyTaken = 0
}

interface CustomerProfile {
  gender: string;
  firstName: string;
  lastName: string;
  email: string;
  birthdate: string;
  nationality: string;
  address: string;
  zipCode: string;
  city: string;
  country: string;
  incomeSource: string;
  state: string;
  politicallyExposedPerson?: boolean;
}
