import { Component, ChangeDetectionStrategy, Input, Output, EventEmitter } from '@angular/core';
import { FreeBetCoupon } from '@honoregaming/betslip';
import { FreeBetService } from '@honoregaming/customer-core';

@Component({
  selector: 'hg-new-freebet-coupons',
  templateUrl: './new-freebet-coupons.component.html',
  styleUrls: ['./new-freebet-coupons.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class NewFreebetCouponsComponent {
  @Input() newFreeBetCoupons: FreeBetCoupon[] = [];

  @Output() close = new EventEmitter<void>();

  limit = 3;

  constructor(private freeBetService: FreeBetService) {}

  showMoreLess(show: boolean): void {
    show ? (this.limit = this.newFreeBetCoupons.length) : (this.limit = 3);
  }

  updateFreeBalance(): void {
    this.freeBetService.updateStoredCoupons();
    this.close.emit();
  }
}
