import {
  ChangeDetectionStrategy,
  Component,
  ElementRef,
  EventEmitter,
  HostListener,
  Input,
  OnInit,
  Output
} from '@angular/core';
import { I18nService } from '@honoregaming/i18n';

@Component({
  selector: 'hg-responsible-gambling-confirmation-popin',
  templateUrl: './responsible-gambling-confirmation-popin.component.html',
  styleUrls: ['./responsible-gambling-confirmation-popin.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class ResponsibleGamblingConfirmationPopinComponent implements OnInit {
  @Input()
  isSelfLimitation: boolean;
  @Input()
  exclusionStartDate: Date;
  @Input()
  exclusionEndDate: Date;

  @Output()
  close = new EventEmitter<{ confirmed: boolean }>();

  title: string;
  text: string;

  constructor(private i18nService: I18nService, private element: ElementRef) {}

  ngOnInit(): void {
    if (this.isSelfLimitation) {
      this.i18nService.translate('RESPONSIBLE_GAMBLING.SELF_LIMITATION.CONFIRMATION_TITLE').subscribe(t => {
        this.title = t;
      });
      this.i18nService.translate('RESPONSIBLE_GAMBLING.SELF_LIMITATION.CONFIRMATION_TEXT').subscribe(t => {
        this.text = t;
      });
    } else {
      var endDateString = null;
      var startDateString = null;
      if (this.exclusionEndDate && this.exclusionStartDate) {
        this.i18nService.formatLongDate(this.exclusionEndDate.toString()).subscribe(date => {
          endDateString = date;
        });
        this.i18nService.formatLongDate(this.exclusionStartDate.toString()).subscribe(date => {
          startDateString = date;
        });

        this.i18nService
          .translate('RESPONSIBLE_GAMBLING.SELF_EXCLUSION.CONFIRMATION_TITLE', startDateString, endDateString)
          .subscribe(t => {
            this.title = t;
          });
      } else {
        this.i18nService
          .translate(
            'RESPONSIBLE_GAMBLING.SELF_EXCLUSION.CONFIRMATION.DIFINITELY_TITLE',
            startDateString,
            endDateString
          )
          .subscribe(t => {
            this.title = t;
          });
      }

      this.i18nService.translate('RESPONSIBLE_GAMBLING.SELF_EXCLUSION.CONFIRMATION_TEXT').subscribe(t => {
        this.text = t;
      });
    }
  }

  closePopup() {
    this.close.emit({ confirmed: false });
  }

  confirm() {
    this.close.emit({ confirmed: true });
  }

  @HostListener('focus')
  handleFocus() {
    this.element.nativeElement.type = 'date';
  }

  @HostListener('blur')
  handleBlur() {
    if (this.element.nativeElement.value == '') {
      this.element.nativeElement.type = 'text';
    }
  }
}
