import { Injectable } from '@angular/core';
import { TelemetryService } from '@honoregaming/customer-core';

@Injectable({ providedIn: 'root' })
export class AccountTrackingService {
  constructor(private readonly telemetryService: TelemetryService) {}

  trackMenuClick(itemName: string, hideBalance: boolean, label: string, hasNotificationCount: boolean): void {
    this.telemetryService.trackEvent('account_menu_click', {
      item_name: itemName,
      balance_status: hideBalance ? 'hidden' : 'visible',
      item_label: label,
      has_notification_count: hasNotificationCount
    });
  }
}
