import { HttpClient, HttpHeaders } from '@angular/common/http';
import { Inject, Injectable, InjectionToken } from '@angular/core';
import { Observable, of, throwError as _throw, Subscription, timer, Subject, BehaviorSubject } from 'rxjs';
import { map, tap, finalize } from 'rxjs/operators';
import { JwtToken } from '../models';
import { Router } from '@angular/router';
import { globalConfiguration } from '@honoregaming/configuration';
import { LocalStorageService, Scope, scopeToken, SessionStorageService } from '@honoregaming/core';

const accessKey = 'jwt_access';
const refreshKey = 'jwt_refresh';
const expirationKey = 'jwt_expiration';

export interface IAuthService {
  status$: Observable<'connected' | 'disconnected'>;
  balance$?: Observable<number>;
  getToken(): Observable<string>;
  isAuthenticated(): boolean;
}
export const authServiceToken = new InjectionToken<IAuthService>('AuthService');

@Injectable()
export class AuthService implements IAuthService {
  private accessToken: string;
  private expiration: Date;
  private refreshToken: string;
  private refreshSubscription: Subscription;
  private refreshInterval;

  private statusSubject = new BehaviorSubject<'connected' | 'disconnected'>('disconnected');
  status$ = this.statusSubject.asObservable();

  constructor(
    private httpClient: HttpClient,
    private storageService: LocalStorageService,
    private sessionStorageService: SessionStorageService,
    private router: Router,
    @Inject(scopeToken) public scope: Scope
  ) {}

  getStorageService() {
    return this.scope === Scope.Customer ? this.storageService : this.sessionStorageService;
  }

  startRefreshAuthTimer() {
    this.expiration = new Date(this.getStorageService().getItem(expirationKey));
    this.accessToken = this.getStorageService().getItem(accessKey);
    this.refreshToken = this.getStorageService().getItem(refreshKey);

    if (this.accessToken) {
      this.statusSubject.next('connected');
    }

    if (this.expiration) {
      this.refreshTimer();
    }
  }

  login(
    request:
      | { login: string; password: string }
      | { login: string; password: string; terminalClearance?: string; appVersion?: string }
      | { code: string; sessionId: string; recaptchaToken: string }
      | { code: string; sessionId: string }
  ): Observable<JwtToken> {
    return this.httpClient
      .post<JwtToken>(
        `${globalConfiguration.apiAuthenticationBaseUrl}auth/token/${
          this.scope === Scope.Customer
            ? 'customer'
            : this.scope === Scope.Agent
            ? 'agent'
            : this.scope === Scope.Admin
            ? 'administrator'
            : this.scope === Scope.Affiliate
            ? 'affiliate'
            : this.scope === Scope.Viewer
            ? 'viewer'
            : 'kiosk'
        }`,
        request
      )
      .pipe(
        tap(x => {
          this.accessToken = x.access_token;
          this.getStorageService().setItem(accessKey, x.access_token);
          this.refreshToken = x.refresh_token;
          this.getStorageService().setItem(refreshKey, x.refresh_token);
          const expirationDate = new Date();
          expirationDate.setSeconds(expirationDate.getSeconds() + x.expiresIn);
          this.expiration = expirationDate;
          this.getStorageService().setItem(expirationKey, this.expiration);
          this.refreshTimer();
          this.statusSubject.next('connected');
        })
      );
  }

  getToken(): Observable<string> {
    if (!this.isAuthenticated()) {
      return _throw('not authenticated');
    }

    if (this.accessToken && this.expiration > new Date()) {
      return of(this.accessToken);
    }

    return this.refresh();
  }

  tryRefresh() {
    if (this.accessToken && this.expiration > new Date()) {
      return of(this.accessToken);
    }

    return this.refresh();
  }

  logout(withRedirect: boolean = true, redirectWithReturnUrl: boolean = false): void {
    this.httpClient
      .post(
        `${globalConfiguration.apiAuthenticationBaseUrl}auth/logout/${
          this.scope === Scope.Customer
            ? 'customer'
            : this.scope === Scope.Agent
            ? 'agent'
            : this.scope === Scope.Admin
            ? 'administrator'
            : this.scope === Scope.Affiliate
            ? 'affiliate'
            : this.scope === Scope.Viewer
            ? 'viewer'
            : 'kiosk'
        }`,
        {},
        {
          headers: {
            Authorization: `Bearer ${this.accessToken}`
          }
        }
      )
      .subscribe();

    this.accessToken = null;
    this.refreshToken = null;
    this.expiration = null;
    this.getStorageService().removeItem(accessKey);
    this.getStorageService().removeItem(refreshKey);
    this.getStorageService().removeItem(expirationKey);
    this.statusSubject.next('disconnected');
    if (withRedirect) {
      this.router.navigate(['/login']);
    } else if (redirectWithReturnUrl) {
      this.router.navigate(['/login'], {
        queryParams: {
          returnUrl: this.router.url
        }
      });
    }
    clearInterval(this.refreshInterval);
  }

  // tslint:disable-next-line: member-ordering
  private currentRefreshRequest: Subject<string>;
  refresh(): Observable<string> {
    if (this.currentRefreshRequest) {
      return this.currentRefreshRequest.asObservable();
    }

    if (!this.refreshToken) {
      return of(null);
    }

    this.currentRefreshRequest = new Subject<string>();
    let headers = new HttpHeaders();
    headers = headers.set('Content-Type', 'application/json; charset=utf-8');

    return this.httpClient
      .post<JwtToken>(
        `${globalConfiguration.apiAuthenticationBaseUrl}auth/refresh/${
          this.scope === Scope.Customer
            ? 'customer'
            : this.scope === Scope.Agent
            ? 'agent'
            : this.scope === Scope.Admin
            ? 'administrator'
            : this.scope === Scope.Affiliate
            ? 'affiliate'
            : this.scope === Scope.Viewer
            ? 'viewer'
            : 'kiosk'
        }`,
        `"${this.refreshToken}"`,
        {
          headers
        }
      )
      .pipe(
        map(x => {
          this.accessToken = x.access_token;
          this.getStorageService().setItem(accessKey, x.access_token);
          this.refreshToken = x.refresh_token;
          this.getStorageService().setItem(refreshKey, x.refresh_token);
          const expirationDate = new Date();
          expirationDate.setSeconds(expirationDate.getSeconds() + x.expiresIn);
          this.expiration = expirationDate;
          this.getStorageService().setItem(expirationKey, this.expiration);
          this.refreshTimer();
          if (this.statusSubject.value !== 'connected') {
            this.statusSubject.next('connected');
          }
          this.currentRefreshRequest.next(this.accessToken);
          return this.accessToken;
        }),
        finalize(() => {
          this.currentRefreshRequest.complete();
          this.currentRefreshRequest = null;
        })
      );
  }

  isAuthenticated(): boolean {
    return !!this.refreshToken;
  }

  private refreshTimer() {
    if (this.refreshSubscription) {
      this.refreshSubscription.unsubscribe();
    }
    this.refreshSubscription = timer(this.expiration).subscribe(() => {
      this.refresh().subscribe({
        error: () => {
          // Handle expired refresh tokens
          this.logout();
        }
      });
    });
  }
}
