import { HttpClient } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { Observable, ReplaySubject, Subject } from 'rxjs';
import { globalConfiguration } from '@honoregaming/configuration';
import { Provider } from '../models/provider.model';
import { Operation } from '../models/operation.model';
import {
  BetCategoryType,
  BetState,
  BetSystemHistory,
  InstantGameState,
  SportsPoolBet,
  SportsPoolHistoryGameDetail
} from '@honoregaming/types';
import { buildQueryString, Cacheable } from '@honoregaming/core';
import { InstantGameTransaction } from '@honoregaming/types';
import { ReferralDetails } from '../models/referral-details.model';
import { ReferralHistory } from '../models/referral-history.model';
import { GenericTransactionResponse } from 'projects/customer/hg-payment-providers/src/models/generic-transaction-response.model';
import { TelemetryService, TrackingEventType, TrackingService } from '@honoregaming/customer-core';
import { tap } from 'rxjs/operators';
import { CustomerWithdrawalInformations } from 'projects/customer/hg-payment-providers/src/models/customer-withdrawal-informations.model';
import { PaymentProviderResponse } from '../models/payment-provider-response.model';
import { OperationConfirmationType } from 'projects/customer/hg-payment-providers/src/enums/operation-confirmation-type.enum';
import { SuperReferrerHistoryResponse } from '../models/super-referrer-history-response.model';
import { SortDirection } from 'projects/core/hg-ui/src/lib/enum/sort-direction.enum';
import { CustomerWithdrawalInformation } from '../models/customer-withdrawal-information.model';
import { CustomerDepositInformation } from 'projects/customer/hg-payment-providers/src/models/customer-deposit-information.model';

@Injectable({
  providedIn: 'root'
})
export class AccountService {
  private registerStepSubject: Subject<number> = new Subject();
  public registerStep: Observable<number> = this.registerStepSubject.asObservable();

  private editProfileInformationSubject: ReplaySubject<void> = new ReplaySubject();
  public editProfileInformation: Observable<void> = this.editProfileInformationSubject.asObservable();

  constructor(
    private httpClient: HttpClient,
    private telemetryService: TelemetryService,
    private trackingService: TrackingService
  ) {}

  @Cacheable({
    ttl: 2,
    useLocalStorage: true
  })
  getBetsHistory(
    skip: number,
    take: number,
    betState: BetState,
    endDate: Date,
    betCategory: BetCategoryType
  ): Observable<BetSystemHistory[]> {
    return this.httpClient.get<BetSystemHistory[]>(
      `${globalConfiguration.apiBaseUrl}reporting/history${buildQueryString({
        skip,
        take,
        betState,
        endDate,
        betCategory
      })}`
    );
  }

  @Cacheable({
    ttl: 10,
    useLocalStorage: true
  })
  getInstantGameTransactionsHistory(
    skip: number,
    take: number,
    state: InstantGameState,
    date: Date
  ): Observable<InstantGameTransaction[]> {
    return this.httpClient.get<InstantGameTransaction[]>(
      `${globalConfiguration.apiBaseUrl}reporting/instant-games-history${buildQueryString({
        skip,
        take,
        state,
        date
      })}`
    );
  }

  @Cacheable({
    ttl: 10,
    useLocalStorage: true
  })
  getSimulatedBetsHistory(
    skip: number,
    take: number,
    state: InstantGameState,
    date: Date
  ): Observable<InstantGameTransaction[]> {
    return this.httpClient.get<InstantGameTransaction[]>(
      `${globalConfiguration.apiBaseUrl}reporting/simulated-bets-history${buildQueryString({
        skip,
        take,
        state,
        date
      })}`
    );
  }

  @Cacheable({
    ttl: 10,
    useLocalStorage: true
  })
  getSportsPoolGameBetsHistory(skip: number, take: number, state: BetState, date: Date): Observable<SportsPoolBet[]> {
    return this.httpClient.get<SportsPoolBet[]>(
      `${globalConfiguration.apiBaseUrl}reporting/sportspool-history${buildQueryString({
        skip,
        take,
        state,
        date
      })}`
    );
  }

  getSportsPoolHistoryGameDetail(betId: number): Observable<SportsPoolHistoryGameDetail> {
    return this.httpClient.get<SportsPoolHistoryGameDetail>(
      `${globalConfiguration.apiBaseUrl}reporting/sportspool-history/${betId}`
    );
  }

  @Cacheable()
  getPaymentProviders(): Observable<PaymentProviderResponse> {
    return this.httpClient.get<PaymentProviderResponse>(`${globalConfiguration.apiBaseUrl}payment/payment-providers`);
  }

  getGlobalDepositState(): Observable<boolean> {
    return this.httpClient.get<boolean>(`${globalConfiguration.apiBaseUrl}payment/global-deposit-state`);
  }

  getGlobalWithdrawalState(): Observable<boolean> {
    return this.httpClient.get<boolean>(`${globalConfiguration.apiBaseUrl}payment/global-withdrawal-state`);
  }

  @Cacheable({
    ttl: 10,
    useLocalStorage: true
  })
  getOperationsHistory(skip: number, take: number, type: string, month: Date): Observable<Operation[]> {
    return this.httpClient.get<Operation[]>(
      `${globalConfiguration.apiBaseUrl}reporting/operations${buildQueryString({
        month,
        skip,
        take,
        type
      })}`
    );
  }

  createWithdraw(
    provider: Provider,
    amount: number,
    innerProvider?: string,
    password?: string,
    customerWithdrawalInformations?: CustomerWithdrawalInformations
  ): Observable<GenericTransactionResponse> {
    return this.httpClient
      .post<GenericTransactionResponse>(
        `${globalConfiguration.apiPaymentProviderBaseUrl}payment/${
          provider.parentProviderName ?? provider.providerName
        }/withdrawal`,
        {
          customerWithdrawalInformations: customerWithdrawalInformations,
          amount: amount,
          innerProvider: innerProvider,
          password
        }
      )
      .pipe(
        tap(() => {
          this.telemetryService.trackEvent('withdrawal', { amount, provider: provider.providerName, innerProvider });
        })
      );
  }

  confirmWithdrawal(
    provider: Provider,
    operationRef: string,
    operationConfirmationType: OperationConfirmationType,
    data: object,
    innerProvider?: string
  ): Observable<GenericTransactionResponse> {
    return this.httpClient.post<GenericTransactionResponse>(
      `${globalConfiguration.apiPaymentProviderBaseUrl}payment/${
        provider.parentProviderName ?? provider.providerName
      }/confirm-withdrawal`,
      {
        operationRef,
        operationConfirmationType,
        data,
        innerProvider
      }
    );
  }

  confirmDeposit(
    provider: Provider,
    operationRef: string,
    operationConfirmationType: OperationConfirmationType,
    data: object,
    innerProvider?: string
  ): Observable<GenericTransactionResponse> {
    return this.httpClient
      .post<GenericTransactionResponse>(
        `${globalConfiguration.apiPaymentProviderBaseUrl}payment/${
          provider.parentProviderName ?? provider.providerName
        }/confirm-deposit`,
        {
          operationRef,
          operationConfirmationType,
          data,
          innerProvider
        }
      )
      .pipe(
        tap(data => {
          if (data.firstTimeDeposit) {
            this.telemetryService.trackEvent('firstTimeDeposit', {
              provider: provider.providerName,
              innerProvider,
              id: data.id
            });

            this.trackingService
              .trackEvent({
                eventType: TrackingEventType.FirstTimeDeposit,
                properties: { Provider: provider.providerName }
              })
              .subscribe();
          } else {
            this.telemetryService.trackEvent('deposit', {
              provider: provider.providerName,
              innerProvider,
              id: data.id
            });
          }
        })
      );
  }

  createDeposit(
    provider: Provider,
    amount?: number,
    code?: string,
    innerProvider?: string,
    customerDepositInformation?: Partial<CustomerDepositInformation>
  ): Observable<GenericTransactionResponse> {
    return this.httpClient
      .post<GenericTransactionResponse>(
        `${globalConfiguration.apiPaymentProviderBaseUrl}payment/${
          provider.parentProviderName ?? provider.providerName
        }/deposit`,
        {
          customerDepositInformation: customerDepositInformation,
          amount: amount,
          innerProvider: innerProvider,
          code: code
        }
      )
      .pipe(
        tap(data => {
          if (data.firstTimeDeposit) {
            this.telemetryService.trackEvent('firstTimeDeposit', {
              amount,
              provider: provider.providerName,
              innerProvider,
              id: data.id
            });

            this.trackingService
              .trackEvent({
                eventType: TrackingEventType.FirstTimeDeposit,
                properties: { Provider: provider.providerName }
              })
              .subscribe();
          } else {
            this.telemetryService.trackEvent('deposit', {
              amount,
              provider: provider.providerName,
              innerProvider,
              id: data.id
            });
          }
        })
      );
  }

  getReferralDetails() {
    return this.httpClient.get<ReferralDetails>(`${globalConfiguration.apiBaseUrl}reporting/referral/details`);
  }

  getReferralHistory() {
    return this.httpClient.get<ReferralHistory[]>(`${globalConfiguration.apiBaseUrl}reporting/referral/history`);
  }

  getSuperReferrerHistory(
    skip: number,
    take: number,
    searchTerm: string,
    sortField?: string,
    sortDirection?: SortDirection
  ) {
    return this.httpClient.get<SuperReferrerHistoryResponse>(
      `${globalConfiguration.apiBaseUrl}reporting/super-referrer/history${buildQueryString({
        skip,
        take,
        searchTerm,
        sortField,
        sortDirection
      })}`
    );
  }

  uploadIdentityDocument(file: any): Observable<any> {
    return this.httpClient.post<any>(`${globalConfiguration.apiBaseUrl}profile/identity-document`, file);
  }

  clickRegisterStep(step: number) {
    this.registerStepSubject.next(step);
  }

  editProfileInformationClicked() {
    this.editProfileInformationSubject.next();
  }

  getWithdrawalInformation(): Observable<CustomerWithdrawalInformation> {
    return this.httpClient.get<CustomerWithdrawalInformation>(
      `${globalConfiguration.apiBaseUrl}payment/withdrawal-information`
    );
  }
}
