import {
  Component,
  ChangeDetectionStrategy,
  Input,
  ViewChild,
  ElementRef,
  HostListener,
  EventEmitter,
  Output
} from '@angular/core';
import { DirectMessageTrackingService } from '../../services/direct-message-tracking.service';

@Component({
  selector: 'hg-direct-message-button',
  templateUrl: './direct-message-button.component.html',
  styleUrls: ['./direct-message-button.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class DirectMessageButtonComponent {
  @Input() newDirectMessagesCount?: number;

  @Output() navigateEvent = new EventEmitter<void>();
  @Output() closeEvent = new EventEmitter<void>();

  @ViewChild('button') private readonly buttonElement?: ElementRef;

  constructor(private readonly directMessageTrackingService: DirectMessageTrackingService) {}

  @HostListener('window:resize', ['$event'])
  onResize(event: Event): void {
    if (event && this.buttonElement) {
      this.buttonElement.nativeElement.removeAttribute('style');
    }
  }

  hide(event: MouseEvent | TouchEvent): void {
    this.preventEvent(event);
    this.directMessageTrackingService.trackClose('widget');
    this.closeEvent.emit();
  }

  navigate(): void {
    if (this.buttonElement) {
      this.directMessageTrackingService.trackOpen('widget');
      this.navigateEvent.emit();
    }
  }

  private preventEvent(event: MouseEvent | TouchEvent): void {
    event.preventDefault();
    event.stopPropagation();
    event.stopImmediatePropagation();
  }
}
