export function generateCombinations<T>(input: T[], k: number, ordered: boolean): T[][] {
  const result = [];
  const fn = function (n: number, source: any[], current: any[]) {
    if (n === 0) {
      if (current.length > 0) {
        if (ordered) {
          result.push(...generatePermutation(current));
        } else {
          result.push(current);
        }
      }
      return;
    }
    for (let j = 0; j < source.length; j++) {
      fn(n - 1, source.slice(j + 1), current.concat([source[j]]));
    }
    return;
  };
  fn(k, input, []);
  return result;
}

export function generatePermutation(input: any[]) {
  const result = [];

  for (let i = 0; i < input.length; i = i + 1) {
    const rest = generatePermutation(input.slice(0, i).concat(input.slice(i + 1)));

    if (!rest.length) {
      result.push([input[i]]);
    } else {
      for (let j = 0; j < rest.length; j = j + 1) {
        result.push([input[i]].concat(rest[j]));
      }
    }
  }

  return result;
}

export const getCombinationsMultiplier = (combinations: any[]) => combinations?.length || 1;
