import {
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  ElementRef,
  EventEmitter,
  Input,
  OnInit,
  Output,
  ViewChild
} from '@angular/core';
import { EventBetType, HomeOrAway, Match, SelectableEventBetTypeItem } from '@honoregaming/types';

@Component({
  selector: 'hg-event-bet-type-items-by-team',
  templateUrl: './event-bet-type-items-by-team.component.html',
  styleUrls: ['./event-bet-type-items-by-team.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class EventBetTypeItemsByTeamComponent implements OnInit {
  @Input() eventBetTypes!: Record<HomeOrAway, EventBetType[]>;
  @Input() event!: Match;
  @Input() betTypeId!: number;
  @Input() noOdds?: boolean;
  @Input() isLoadingOdds: boolean = false;

  @Output() toggleBetEvent = new EventEmitter<{ ebt: EventBetType; item: SelectableEventBetTypeItem }>();

  @ViewChild('homeEbtList')
  set homeEbtListElement(element: ElementRef) {
    this.updateButtonVisibility(element, HomeOrAway.Home);
  }

  @ViewChild('awayEbtList')
  set awayEbtListElement(element: ElementRef) {
    this.updateButtonVisibility(element, HomeOrAway.Away);
  }

  private static readonly MAX_HEIGHT_LIST = 180;

  readonly HomeOrAway = HomeOrAway;

  teamState: Record<HomeOrAway, TeamState> = {
    [HomeOrAway.Home]: { canCollapse: true, isFullHeight: false, hasButton: false },
    [HomeOrAway.Away]: { canCollapse: true, isFullHeight: false, hasButton: false }
  };

  constructor(private readonly cdRef: ChangeDetectorRef) {}

  ngOnInit(): void {
    this.teamState[HomeOrAway.Home].canCollapse = this.eventBetTypes[HomeOrAway.Home]?.length === 1;
    this.teamState[HomeOrAway.Away].canCollapse = this.eventBetTypes[HomeOrAway.Away]?.length === 1;
  }

  toggleItem(ebt: EventBetType, item: SelectableEventBetTypeItem): void {
    this.toggleBetEvent.emit({ ebt, item });
  }

  toggleHeight(team: HomeOrAway): void {
    this.teamState[team].isFullHeight = !this.teamState[team].isFullHeight;
  }

  private updateButtonVisibility(element: ElementRef | undefined, team: HomeOrAway): void {
    if (!element) {
      return;
    }

    this.teamState[team].hasButton =
      element.nativeElement.offsetHeight >= EventBetTypeItemsByTeamComponent.MAX_HEIGHT_LIST;
    this.cdRef.detectChanges();
  }
}

interface TeamState {
  canCollapse: boolean;
  isFullHeight: boolean;
  hasButton: boolean;
}
