import {
  Component,
  ChangeDetectionStrategy,
  Input,
  Output,
  EventEmitter,
  OnChanges,
  ViewChild,
  ElementRef
} from '@angular/core';
import { DirectMessageThreadResolution } from '../../models/direct-message-thread-resolution.model';
import {
  DirectMessageCategory,
  DirectMessage,
  DirectMessageDirection,
  CustomerDirectMessageConfiguration
} from '@honoregaming/customer-core';

type MappedMessage = { timestamp: number } & (
  | (DirectMessage & { isResolution: false })
  | (DirectMessageThreadResolution & { isResolution: true; date: number; month: number })
);

const urlRegex = /https?:\/\/[^\s/$.?#].[^\s]*/gi;

@Component({
  selector: 'hg-direct-message-list',
  templateUrl: './direct-message-list.component.html',
  styleUrls: ['./direct-message-list.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class DirectMessageListComponent implements OnChanges {
  @Input() messages?: DirectMessage[];
  @Input() resolutions?: DirectMessageThreadResolution[];
  @Input() hasMore: boolean = true;
  @Input() canReply: boolean = false;
  @Input() scrollToBottom: boolean = false;
  @Input() displayYearInDate: boolean = false;
  @Input() fromWidget: boolean = false;
  @Input() directMessageConfig?: CustomerDirectMessageConfiguration;

  @Output() showMore = new EventEmitter<void>();
  @Output() reply = new EventEmitter<DirectMessage>();

  @ViewChild('container') container?: ElementRef;

  DirectMessageDirection = DirectMessageDirection;
  DirectMessageCategory = DirectMessageCategory;
  mappedMessages: MappedMessage[] = [];

  constructor() {}

  ngOnChanges(): void {
    if (this.scrollToBottom) {
      this.container?.nativeElement?.scroll(0, 0);
    }

    const messages = (this.messages ?? []).map((directMessage: DirectMessage) => {
      const dateObj: Date = new Date(directMessage.dateTime);
      let messageContent: string = directMessage.content;

      if (directMessage.category !== DirectMessageCategory.Picture && urlRegex.test(messageContent)) {
        messageContent = messageContent.replace(urlRegex, url => `<a href="${url}">${url}</a>`);
      }

      return {
        isResolution: false,
        ...directMessage,
        content: messageContent,
        date: dateObj.getDate(),
        month: dateObj.getMonth(),
        timestamp: dateObj.getTime()
      } as const;
    });

    const resolutions = (this.resolutions ?? []).map((resolution: DirectMessageThreadResolution) => {
      const dateObj: Date = new Date(resolution.solvedStateChangedAt);

      return {
        isResolution: true,
        ...resolution,
        date: dateObj.getDate(),
        month: dateObj.getMonth(),
        timestamp: dateObj.getTime()
      } as const;
    });

    this.mappedMessages = [...messages, ...resolutions].sort((a, b) => b.timestamp - a.timestamp);
  }

  onScroll(event: Event): void {
    if (!this.hasMore) {
      return;
    }

    const target = event.target as HTMLElement;
    const isAtBottom: boolean = Math.abs(target.scrollHeight - (target.offsetHeight - target.scrollTop)) <= 1;

    if (isAtBottom) {
      this.showMore.emit();
    }
  }

  trackByMessageId(_index: number, message: MappedMessage): string | number {
    return message.isResolution === true ? `resolution.${message.timestamp}` : message.id;
  }

  scrollToMsg(messageId: number): void {
    const element: HTMLElement = document.getElementById(`msg-${messageId}`);

    if (!element) {
      return;
    }
    element.scrollIntoView({ behavior: 'smooth', block: 'center' });
  }

  openPicture(event): void {
    open(event.target.currentSrc);
  }
}
