import { IBetSlipModeHandler } from './ibet-slip-mode-handler';
import { Amounts, BetLine } from '../../models';
import {
  roundNumber,
  getCombinationsMultiplier,
  floorNumber,
  preciseFloatingPointNumber,
  add,
  mul,
  div,
  sub
} from '@honoregaming/core';
import { computePaymentTaxAmounts, getBetLineIndex, getDrawGameBetLineToUpdateIndex } from '../../utils';
import { computeBettingTaxAmounts } from '../../utils';
import { EventType } from '@honoregaming/types';
import { OperatorConfiguration } from '@honoregaming/configuration';

export class BetSlipSimpleModeHandler implements IBetSlipModeHandler {
  constructor(private operatorConfiguration: OperatorConfiguration) {}

  initBetSlip(
    betLines: BetLine[],
    amounts: Amounts,
    lastStake?: number,
    reuseAmountsValues?: boolean,
    defaultAmount?: number
  ) {
    const stake: number = lastStake ?? defaultAmount;
    if (!reuseAmountsValues && stake) {
      amounts.values = betLines.map(l => {
        return { amount: l.baseAmount <= stake ? stake : l.baseAmount };
      });
    } else if (!reuseAmountsValues || betLines.length !== amounts.values.length) {
      amounts.values = betLines.map(l => {
        return { amount: l.baseAmount * getCombinationsMultiplier(l.combinations) };
      });
    }
  }

  addBetLine(
    betLineToAdd: BetLine,
    existingBetLines: BetLine[],
    amounts: Amounts,
    lastStake?: number,
    defaultAmount?: number
  ) {
    existingBetLines.push(betLineToAdd);
    let amount = mul(betLineToAdd.baseAmount, getCombinationsMultiplier(betLineToAdd.combinations));
    if (lastStake || defaultAmount) {
      if (
        (lastStake && lastStake < betLineToAdd.baseAmount) ||
        (defaultAmount && defaultAmount < betLineToAdd.baseAmount)
      ) {
        amount = betLineToAdd.baseAmount ?? defaultAmount;
      } else if (
        (lastStake && lastStake > betLineToAdd.maximumAmount) ||
        (defaultAmount && defaultAmount > betLineToAdd.maximumAmount)
      ) {
        amount = betLineToAdd.maximumAmount ?? defaultAmount;
      } else if (lastStake && defaultAmount && lastStake < defaultAmount) {
        amount = defaultAmount;
      } else {
        amount = lastStake ?? defaultAmount;
      }
    }
    amounts.values.push({
      amount: amount
    });
  }

  removeBetLine(betLineToRemove: BetLine, existingBetLines: BetLine[], amounts: Amounts) {
    let itemIndex = getBetLineIndex(betLineToRemove, existingBetLines);

    if (betLineToRemove.eventType === EventType.DrawGame) {
      itemIndex = getDrawGameBetLineToUpdateIndex(betLineToRemove, existingBetLines);
    }

    existingBetLines.splice(itemIndex, 1);
    amounts.values.splice(itemIndex, 1);
  }

  computeBetSlipSummary(betLines: BetLine[], amounts: Amounts) {
    const decimals: number = this.operatorConfiguration.currency.numberOfDecimals;
    let totalStakeWithTax: number = 0;
    let totalBettingTax: number = 0;
    let totalStake: number = 0;
    let totalMaxPayoutWithTax: number = 0;
    let totalPaymentTax: number = 0;
    let totalMaxPayout: number = 0;

    amounts.values.forEach((amount, index) => {
      const { stake, bettingTax } = this.computeStakeAfterBettingTax(amount.amount, amounts);
      const grossPayout: number = this.computeGrossPayout(stake, betLines[index], amounts.useFreeBet);
      const { payout, paymentTax } = this.computePayoutAfterPaymentTax(stake, grossPayout, amounts, decimals);

      amount.payout = payout;

      totalStakeWithTax = add(totalStakeWithTax, amount.amount);
      totalBettingTax = add(totalBettingTax, bettingTax);
      totalStake = add(totalStake, stake);
      // The displayed gross payout must stay consistent with the rounded net payout and tax (base = net + tax)
      totalMaxPayoutWithTax = add(
        totalMaxPayoutWithTax,
        paymentTax != null ? add(payout, paymentTax) : floorNumber(preciseFloatingPointNumber(grossPayout), decimals)
      );
      totalPaymentTax = add(totalPaymentTax, paymentTax);
      totalMaxPayout = add(totalMaxPayout, payout);
    });

    amounts.summary.bonus = null;
    amounts.nextBonus = null;
    amounts.summary.totalStakeWithTax = totalStakeWithTax;
    amounts.summary.bettingTax = totalBettingTax;
    amounts.summary.totalStake = totalStake;
    amounts.summary.baseMaxPayout = totalMaxPayoutWithTax;
    amounts.summary.paymentTax = totalPaymentTax;
    amounts.summary.maxPayout = totalMaxPayout;
    amounts.values = amounts.values.map(value => ({ ...value }));
  }

  private computeStakeAfterBettingTax(amount: number, amounts: Amounts): { stake: number; bettingTax: number } {
    if (amounts.useFreeBet) {
      return { stake: amount, bettingTax: null };
    }

    const result = computeBettingTaxAmounts(
      amount,
      amounts.bettingTax,
      this.operatorConfiguration.currency.numberOfDecimals
    );
    return { stake: result.amount, bettingTax: result.tax };
  }

  private computeGrossPayout(stake: number, betLine: BetLine, useFreeBet: boolean): number {
    let payout: number;

    // SportsPool Grid MaxPayout is calculated from Jackpot (first winning rank) and stored in 'maxPayout' property (cf createSportsPoolBetLine)
    if (betLine.maxPayout) {
      payout = betLine.maxPayout;
    } else {
      if (betLine.combinations?.length) {
        const bestOdds: number = Math.max(...betLine.combinations.map(combination => combination.fixedOdds));
        payout = div(stake, betLine.combinations.length) * bestOdds;
      } else {
        payout = stake * (betLine.odds || betLine.maxOdds);
      }

      if (useFreeBet) {
        payout = sub(payout, stake);
      }
    }

    return payout;
  }

  private computePayoutAfterPaymentTax(
    stake: number,
    grossPayout: number,
    amounts: Amounts,
    decimals: number
  ): { payout: number; paymentTax: number } {
    const skipPaymentTax: boolean = amounts.useFreeBet && !this.operatorConfiguration.freeBetsConfiguration.applyTax;

    if (skipPaymentTax) {
      return {
        payout: floorNumber(preciseFloatingPointNumber(grossPayout), decimals),
        paymentTax: null
      };
    }

    const result = computePaymentTaxAmounts(stake, grossPayout, amounts.paymentTax, decimals);
    return {
      payout: result.amount,
      // The server floors the payment tax (HonoreRound Down), rounding to nearest would display one unit more
      paymentTax: result.tax != null ? floorNumber(preciseFloatingPointNumber(result.tax), decimals) : null
    };
  }

  computeBetSlipInstantGameSummary(stake: number, amounts: Amounts): void {
    const bettingTaxValues = amounts.useFreeBet
      ? { amount: stake, tax: null }
      : computeBettingTaxAmounts(stake, amounts.bettingTax, this.operatorConfiguration.currency.numberOfDecimals);

    const totalStake = roundNumber(bettingTaxValues.amount, this.operatorConfiguration.currency.numberOfDecimals);
    const bettingTax = roundNumber(bettingTaxValues.tax, this.operatorConfiguration.currency.numberOfDecimals);
    amounts.summary.totalStakeWithTax = add(totalStake, bettingTax);
    amounts.summary.bettingTax = bettingTax;
    amounts.summary.totalStake = totalStake;
  }

  canBeInMode(_betLines: BetLine[]): boolean {
    return true;
  }
}
