import { Amounts, BetLine } from '../../models';
import { BetCategoryType } from '@honoregaming/types';
import { IBetSlipModeHandler } from './ibet-slip-mode-handler';
import {
  hasDuplicatedItems,
  getBetLineIndex,
  computeBettingTaxAmounts,
  getAllCombinations,
  computePaymentTaxAmounts
} from '../../utils';
import { floorNumber, preciseFloatingPointNumber, add, sub } from '@honoregaming/core';
import { OperatorConfiguration } from '@honoregaming/configuration';

export class BetSlipSystemsModeHandler implements IBetSlipModeHandler {
  constructor(private operatorConfiguration: OperatorConfiguration) {}
  computeBetSlipInstantGameSummary(_stake: number, _amounts: Amounts): void {
    throw new Error('Method not implemented.');
  }

  initBetSlip(betLines: BetLine[], amounts: Amounts, _lastStake?: number, _reuseAmountsValues?: boolean) {
    amounts.values = betLines.map(_l => {
      return { amount: 0 };
    });
  }

  addBetLine(betLineToAdd: BetLine, existingBetLines: BetLine[], amounts: Amounts, _lastStake?: number) {
    existingBetLines.push(betLineToAdd);

    this.initBetSlip(existingBetLines, amounts);
  }

  removeBetLine(betLineToRemove: BetLine, existingBetLines: BetLine[], amounts: Amounts) {
    const itemIndex = getBetLineIndex(betLineToRemove, existingBetLines);
    existingBetLines.splice(itemIndex, 1);

    this.initBetSlip(existingBetLines, amounts);
  }

  computeBetSlipSummary(betLines: BetLine[], amounts: Amounts) {
    const betLineNumbers = betLines.map((_, i) => i);
    const amountsWithTaxes = amounts.values
      .map((amount, index) => {
        const combinaisons = getAllCombinations(betLineNumbers, amounts.values.length - index);

        const bettingTaxValues = amounts.useFreeBet
          ? { amount: amount.amount, tax: null }
          : computeBettingTaxAmounts(
              amount.amount,
              amounts.bettingTax,
              this.operatorConfiguration.currency.numberOfDecimals
            );

        return (
          combinaisons
            .map(c => c.map(i => betLines[i]))
            // Compute the bets amounts
            .map(betLines => {
              const eligibleBetLines = betLines.filter(
                b => b.odds >= this.operatorConfiguration.multipleBonus?.minimumOdds
              ).length;

              const applyableBonus = this.operatorConfiguration.multipleBonus?.bonus.filter(
                x => x.linesNumber <= eligibleBetLines
              );

              const targetBonus = applyableBonus?.length
                ? applyableBonus.reduce((prev, cur) => (prev.linesNumber > cur.linesNumber ? prev : cur))
                : null;

              const odds = betLines.reduce((total, bl) => total * bl.odds, 1);
              const totalStake = bettingTaxValues.amount;

              const bettingTax = bettingTaxValues.tax;

              let baseMaxPayout = totalStake * odds;

              baseMaxPayout = sub(baseMaxPayout, amounts.useFreeBet ? totalStake : 0);

              let bonus = 0;
              let maxPayoutWithBonus = baseMaxPayout;

              if (
                targetBonus &&
                (this.operatorConfiguration.multipleBonus.minimumStake == null ||
                  (this.operatorConfiguration.multipleBonus.minimumStake != null &&
                    this.operatorConfiguration.multipleBonus.minimumStake <= amounts.summary.totalStake))
              ) {
                // Like the server, the bonus is computed on the raw winnings then floored to the currency decimals (cf CreateBetHandler)
                bonus = floorNumber(
                  preciseFloatingPointNumber(baseMaxPayout * (targetBonus.coefficient - 1)),
                  this.operatorConfiguration.currency.numberOfDecimals
                );
                if (
                  (this.operatorConfiguration.multipleBonus?.maxPayout &&
                    bonus >= this.operatorConfiguration.multipleBonus?.maxPayout) ||
                  (!this.operatorConfiguration.multipleBonus?.maxPayout && !amounts.nextBonus)
                ) {
                  bonus = this.operatorConfiguration.multipleBonus?.maxPayout || bonus;
                  amounts.maxBonusReach = true;
                } else {
                  amounts.maxBonusReach = false;
                }
                maxPayoutWithBonus = add(maxPayoutWithBonus, bonus);
              }

              const paymentTaxValues =
                amounts.useFreeBet && !this.operatorConfiguration.freeBetsConfiguration.applyTax
                  ? {
                      amount: floorNumber(
                        preciseFloatingPointNumber(maxPayoutWithBonus),
                        this.operatorConfiguration.currency.numberOfDecimals
                      ),
                      tax: null
                    }
                  : computePaymentTaxAmounts(
                      totalStake,
                      maxPayoutWithBonus,
                      amounts.paymentTax,
                      this.operatorConfiguration.currency.numberOfDecimals
                    );

              const maxPayoutWithTax = paymentTaxValues.amount;
              // The server floors the payment tax (HonoreRound Down), rounding to nearest would display one unit more
              const paymentTax =
                paymentTaxValues.tax != null
                  ? floorNumber(
                      preciseFloatingPointNumber(paymentTaxValues.tax),
                      this.operatorConfiguration.currency.numberOfDecimals
                    )
                  : null;

              // The displayed gross payouts must stay consistent with the rounded net payout and tax (base + bonus = net + tax)
              if (paymentTax != null) {
                maxPayoutWithBonus = add(maxPayoutWithTax, paymentTax);
                baseMaxPayout = sub(maxPayoutWithBonus, bonus);
              }

              return {
                totalStake,
                bettingTax,
                baseMaxPayout,
                maxPayoutWithBonus,
                bonus,
                maxPayoutWithTax,
                paymentTax
              };
            })
        );
      })
      .reduce((all, current) => all.concat(current), [])
      .reduce(
        (total, current) => {
          return {
            totalStake: add(total.totalStake, current.totalStake),
            bettingTax: add(total.bettingTax, current.bettingTax),
            baseMaxPayout: add(total.baseMaxPayout, current.baseMaxPayout),
            maxPayoutWithBonus: add(total.maxPayoutWithBonus, current.maxPayoutWithBonus),
            bonus: add(total.bonus, current.bonus),
            maxPayoutWithTax: add(
              total.maxPayoutWithTax,
              floorNumber(current.maxPayoutWithTax, this.operatorConfiguration.currency.numberOfDecimals)
            ),
            paymentTax: add(total.paymentTax, current.paymentTax)
          };
        },
        {
          totalStake: 0,
          bettingTax: 0,
          baseMaxPayout: 0,
          maxPayoutWithBonus: 0,
          bonus: 0,
          maxPayoutWithTax: 0,
          paymentTax: 0
        }
      );

    amounts.summary.totalStake = amountsWithTaxes.totalStake;
    amounts.summary.bettingTax = amountsWithTaxes.bettingTax;
    amounts.summary.totalStakeWithTax = add(amountsWithTaxes.totalStake, amountsWithTaxes.bettingTax);

    amounts.summary.baseMaxPayout = amountsWithTaxes.baseMaxPayout;
    amounts.summary.bonus = amountsWithTaxes.bonus;
    amounts.summary.maxPayoutWithBonus = amountsWithTaxes.maxPayoutWithBonus;
    amounts.summary.paymentTax = amountsWithTaxes.paymentTax;
    amounts.summary.maxPayout = floorNumber(
      preciseFloatingPointNumber(amountsWithTaxes.maxPayoutWithTax),
      this.operatorConfiguration.currency.numberOfDecimals
    );

    if (this.operatorConfiguration.freeBetsConfiguration?.minimalOdds) {
      amounts.oddsCompatibleWithFreeBet = betLines.every(
        bl => bl.odds >= this.operatorConfiguration.freeBetsConfiguration?.minimalOdds
      );
    }

    if (this.operatorConfiguration.freeBetsConfiguration?.maximalOdds) {
      amounts.oddsCompatibleWithFreeBet = betLines.every(
        bl => bl.odds <= this.operatorConfiguration.freeBetsConfiguration?.maximalOdds
      );
    }
  }

  canBeInMode(betLines: BetLine[]): boolean {
    return (
      betLines.length >= 2 &&
      !hasDuplicatedItems(betLines.map(l => l.eventId)) &&
      !betLines.find(
        bl =>
          !!bl.isAsian ||
          !!bl.oddsBoostId ||
          !!bl.manualOddsBoostId ||
          bl.betCategoryType !== BetCategoryType.SportsFixedOdds ||
          !!bl.combinations?.length
      )
    );
  }
}
