import { ChangeDetectionStrategy, Component, Input, OnChanges, SimpleChanges } from '@angular/core';
import { SportsScoresService } from '@honoregaming/core';
import {
  EventStateDetailsType,
  EventStateType,
  RegulationTimeScore,
  SelectableEventBetTypeItem,
  SportsPoolGameMatch
} from '@honoregaming/types';

@Component({
  selector: 'hg-sports-pool-bet-line-result',
  templateUrl: './sports-pool-bet-line-result.component.html',
  styleUrls: ['./sports-pool-bet-line-result.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class SportsPoolBetLineResultComponent implements OnChanges {
  @Input() gameMatch!: SportsPoolGameMatch;
  @Input() cancelled: boolean = false;
  @Input() reserved: boolean = false;
  @Input() hasOutcome: boolean = false;

  temporaryOccured?: '1' | 'X' | '2';
  displayedScore?: RegulationTimeScore;
  isRegulationTimeOver: boolean = false;

  private static readonly PAUSE_STATES: ReadonlySet<EventStateDetailsType> = new Set([
    EventStateDetailsType.Pause,
    EventStateDetailsType.Pause1,
    EventStateDetailsType.Pause2,
    EventStateDetailsType.Pause3,
    EventStateDetailsType.Pause4,
    EventStateDetailsType.PauseOvertime
  ]);

  constructor(private readonly sportsScoresService: SportsScoresService) {}

  ngOnChanges(changes: SimpleChanges): void {
    if (changes.gameMatch) {
      this.isRegulationTimeOver =
        this.sportsScoresService.isOvertimeStateDetails(this.gameMatch.event.stateDetails) ||
        this.sportsScoresService.hasOvertimeScore(this.gameMatch.scores);
      this.displayedScore = this.sportsScoresService.computeDisplayedScore(this.gameMatch, this.isRegulationTimeOver);
    }

    this.resolveMatchOutcome();
  }

  get isPaused(): boolean {
    return (
      !this.isRegulationTimeOver &&
      this.gameMatch.event.state === EventStateType.Started &&
      SportsPoolBetLineResultComponent.PAUSE_STATES.has(this.gameMatch.event.stateDetails)
    );
  }

  getItemClass(ebti: SelectableEventBetTypeItem): string {
    const isCorrect: boolean = ebti.occured || this.temporaryOccured === ebti.shortName;
    const hasOutcome: boolean = this.hasOutcome || !!this.temporaryOccured;

    if (hasOutcome && ebti.selected && isCorrect) return 'ebtis__item--won';
    if (hasOutcome && ebti.selected && !isCorrect) return 'ebtis__item--lost';
    if (hasOutcome && !ebti.selected && isCorrect) return 'ebtis__item--winner';
    if (ebti.selected) return 'ebtis__item--selected';

    return 'ebtis__item--default';
  }

  private resolveMatchOutcome(): void {
    if (!this.displayedScore) {
      return;
    }

    const home: number = Number.parseInt(this.displayedScore.homeTeamScore);
    const away: number = Number.parseInt(this.displayedScore.awayTeamScore);

    // We need the check score values only when EBT is not Settled
    this.temporaryOccured = !this.gameMatch.eventBetType.settled ? this.getMatchResult(home, away) : undefined;
  }

  private getMatchResult(home: number, away: number): '1' | '2' | 'X' {
    if (home > away) return '1';
    if (home < away) return '2';
    return 'X';
  }
}
