import { Injectable } from '@angular/core';
import { Subject, Observable } from 'rxjs';
import { I18nService } from '@honoregaming/i18n';
import { finalize, take, takeUntil } from 'rxjs/operators';

export interface SendComponentMessageOptions {
  canBeDismissed?: boolean;
  displayClose?: boolean;
  className?: string;
  id?: string;
  wowEffect?: boolean;
  zIndex?: number;
  dark?: boolean;
  noScroll?: boolean;
  bare?: boolean;
  queue?: boolean;
  maxWidth?: number;
}

interface SubjectParams {
  component: any;
  props: any;
  options: SendComponentMessageOptions;
  onclosed: (val) => void;
}

interface QueueEntry {
  component: any;
  props: any;
  options: SendComponentMessageOptions;
  closed$: Subject<any>;
}

@Injectable({
  providedIn: 'root'
})
export class MessageService {
  private messageSubject = new Subject<{ msg: string; onclosed: (val: any) => void }>();
  message$ = this.messageSubject.asObservable();

  private componentSubject = new Subject<SubjectParams>();
  component$ = this.componentSubject.asObservable();

  private headerSubject = new Subject<{ key: string; value: any; onclosed: (val: any) => void }>();
  header$ = this.headerSubject.asObservable();

  private queue = new Map<string, QueueEntry>();
  private isShowing = false;

  constructor(private i18nService: I18nService) {}

  sendI18nMessage(key: string, values?: string[]): { closed: Observable<{}> } {
    const closed = new Subject();
    this.i18nService
      .translate(key, ...(values || []))
      .pipe(take(1))
      .subscribe(msg =>
        this.messageSubject.next({
          msg,
          onclosed: () => {
            closed.next();
            closed.complete();
          }
        })
      );
    return { closed: closed.asObservable() };
  }

  sendComponentMessage(
    component,
    props = null,
    options?: SendComponentMessageOptions,
    destroyEvent$?: Subject<boolean>,
    deleteFromQueueOnDestroy: boolean = false
  ): { closed: Observable<any> } {
    const closed = new Subject<any>();
    const opts = {
      canBeDismissed: true,
      displayClose: true,
      className: '',
      id: '',
      wowEffect: false,
      zIndex: 13,
      dark: false,
      ...options
    };

    if (opts.queue) {
      return this.consumeQueue(
        { component, props, options: opts, closed$: closed },
        destroyEvent$,
        deleteFromQueueOnDestroy
      );
    } else {
      if (this.queue.size > 0) {
        this.queue.forEach(entry => entry.closed$.complete());
        this.queue.clear();
      }

      this.componentSubject.next({
        component,
        props,
        options: opts,
        onclosed: (val: any) => {
          closed.next(val);
          closed.complete();
        }
      });
    }

    return { closed: this.withDestroy(closed, destroyEvent$, component.name, deleteFromQueueOnDestroy) };
  }

  sendHeaderMessage(key: string, value: string): { closed: Observable<{}> } {
    const closed = new Subject();
    this.headerSubject.next({
      key,
      value,
      onclosed: () => {
        closed.next();
        closed.complete();
      }
    });
    return { closed: closed.asObservable() };
  }

  private consumeQueue(
    entry: QueueEntry,
    destroyEvent$: Subject<boolean> | undefined,
    deleteFromQueueOnDestroy: boolean
  ): { closed: Observable<any> } {
    const { component, props, options, closed$ } = entry;

    if (this.queue.has(component.name)) {
      // If a popup is already in the queue let's not duplicate it
      const existingMessage$: Subject<any> = this.queue.get(component.name).closed$;

      this.drain();
      return { closed: this.withDestroy(existingMessage$, destroyEvent$, component.name, deleteFromQueueOnDestroy) };
    }
    this.queue.set(component.name, { component, props, options, closed$ });
    this.drain();
    return { closed: this.withDestroy(closed$, destroyEvent$, component.name, deleteFromQueueOnDestroy) };
  }

  private drain(): void {
    if (this.isShowing) {
      return;
    }

    const iter = this.queue.entries().next();

    if (!iter || iter.done) {
      return;
    }

    const [name, entry] = iter.value;

    this.isShowing = true;
    this.componentSubject.next({
      component: entry.component,
      props: entry.props,
      options: entry.options,
      onclosed: (val: any) => {
        this.queue.delete(name);
        this.isShowing = false;
        entry.closed$.next(val);
        entry.closed$.complete();
        this.drain();
      }
    });
  }

  private withDestroy(
    closed$: Subject<any>,
    destroyEvent$: Subject<boolean> | undefined,
    queueKey: string,
    deleteFromQueueOnDestroy: boolean
  ): Observable<any> {
    if (!destroyEvent$) {
      return closed$.asObservable();
    }

    return closed$.asObservable().pipe(
      takeUntil(destroyEvent$),
      finalize(() => {
        if (closed$.isStopped) {
          return; // closed normally already, nothing to do
        }
        this.isShowing = false;
        if (deleteFromQueueOnDestroy && queueKey) {
          this.queue.delete(queueKey);
        }
      })
    );
  }
}
