import {
  Component,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Inject,
  Output,
  EventEmitter,
  OnInit
} from '@angular/core';
import { ContentComponent, ContentService } from '@honoregaming/templating';
import { I18nService } from '@honoregaming/i18n';
import { Scope, scopeToken } from '@honoregaming/core';

@Component({
  selector: 'hg-bet-builder-tutorial',
  templateUrl: './bet-builder-tutorial.component.html',
  styleUrls: ['./bet-builder-tutorial.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class BetBuilderTutorialComponent extends ContentComponent implements OnInit {
  @Output() close: EventEmitter<void> = new EventEmitter<void>();

  constructor(
    protected contentService: ContentService,
    protected cdRef: ChangeDetectorRef,
    protected i18nService: I18nService,
    @Inject(scopeToken) public scope: Scope
  ) {
    super(contentService, cdRef, i18nService, scope);
  }

  ngOnInit(): void {
    this.name = 'bet-builder-infos';
    super.ngOnInit();
  }

  validateTutorial(): void {
    this.close.emit();
  }
}
