import { ChangeDetectionStrategy, ChangeDetectorRef, Component, EventEmitter, OnInit, Output } from '@angular/core';
import { ResponsibleGamblingService } from '../../services/responsible-gambling.service';
import { MessageService } from '@honoregaming/ui';
import { ResponsibleGamblingConfirmationPopinComponent } from '../responsible-gambling-confirmation-popin/responsible-gambling-confirmation-popin.component';
import { DestroySubject, getUtcNow } from '@honoregaming/core';
import { finalize, takeUntil } from 'rxjs/operators';
import { AuthService, TelemetryService } from '@honoregaming/customer-core';
import { ResponsibleGamblingPeriod } from '../../models/responsible-gambling-period.model';
import { I18nService } from '@honoregaming/i18n';

@Component({
  selector: 'hg-responsible-gambling-self-exclusion',
  templateUrl: './responsible-gambling-self-exclusion.component.html',
  styleUrls: ['./responsible-gambling-self-exclusion.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class ResponsibleGamblingSelfExclusionComponent extends DestroySubject implements OnInit {
  @Output()
  openAlert = new EventEmitter<{ errorMessageKey?: string }>();

  selfExclusionChoices = [
    { id: 1, label: 'Period', selected: true },
    { id: 2, label: 'FixedEndDate', selected: false },
    { id: 3, label: 'Definitely', selected: false }
  ];
  currentChoiceId: number;

  active: boolean;
  responsibleGamblingPeriod = ResponsibleGamblingPeriod;
  exclusionEndDate: Date;
  exclusionStartDate: Date;
  loading: boolean;
  isExcluded: boolean;
  minDate = new Date();
  currentPeriodText: string;

  constructor(
    private responsibleGamblingService: ResponsibleGamblingService,
    private messageService: MessageService,
    private cdRef: ChangeDetectorRef,
    private authService: AuthService,
    private i18nService: I18nService,
    private telemetryService: TelemetryService
  ) {
    super();
  }

  ngOnInit(): void {
    this.authService.me$.pipe(takeUntil(this.destroy$)).subscribe(me => {
      if (me.selfExclusionEndDate) {
        this.isExcluded = new Date(me.selfExclusionEndDate) > new Date();
      }

      this.cdRef.markForCheck();
    });
  }

  onChoiceChange(choice: any) {
    this.exclusionEndDate = null;
    this.currentChoiceId = choice.id;
    this.exclusionStartDate = this.currentChoiceId === 1 || this.currentChoiceId === 2 ? getUtcNow() : null;

    this.selfExclusionChoices.forEach(cb => {
      if (cb !== choice) {
        cb.selected = false;
      } else {
        cb.selected = !cb.selected;
      }
    });
  }

  updateSelfExclusion() {
    this.loading = true;
    this.responsibleGamblingService
      .updateSelfExclusion(this.exclusionEndDate)
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.loading = false;
          this.cdRef.markForCheck();
        })
      )
      .subscribe(
        _ => {
          this.telemetryService.trackEvent('self_exclusion');
          this.openAlert.emit();
        },
        x => {
          this.openAlert.emit({ errorMessageKey: this.getFailure(x.error.code) });
        }
      );
  }

  openPopin() {
    this.messageService
      .sendComponentMessage(ResponsibleGamblingConfirmationPopinComponent, {
        isSelfLimitation: false,
        exclusionEndDate: this.exclusionEndDate,
        exclusionStartDate: this.exclusionStartDate
      })
      .closed.subscribe(data => {
        if (data?.confirmed) {
          this.updateSelfExclusion();
        }
      });
  }

  toggleActive() {
    this.active = !this.active;
  }

  setPeriod(period: ResponsibleGamblingPeriod, key: string) {
    this.canValidate;
    var now = getUtcNow();
    this.exclusionStartDate = now;

    this.i18nService.translate(key).subscribe(x => {
      this.currentPeriodText = x;
    });
    switch (period) {
      case ResponsibleGamblingPeriod.OneDay:
        this.exclusionEndDate = now.addDays(1);
        break;
      case ResponsibleGamblingPeriod.OneWeek:
        this.exclusionEndDate = now.addWeeks(1);
        break;
      case ResponsibleGamblingPeriod.OneMonth:
        this.exclusionEndDate = now.addMonths(1);
        break;
    }
  }

  canValidate() {
    return new Date(this.exclusionEndDate) > getUtcNow() || this.currentChoiceId === 3 ? true : false;
  }

  getFailure(failure: number) {
    switch (failure) {
      case -1:
        return 'RESPONSIBLE_GAMBLING.SELF_EXCLUSION.ERROR.ALREADY_EXCLUDED';
      default:
        'COMMON.ERROR';
    }
  }
}
