  getNextSportsEvents(
    pageIndex: number = 0,
    pageSize: number = 20,
    fetchEventBetTypesMode: FetchEventBetTypesMode = FetchEventBetTypesMode.Default,
    entryPointId: number = null,
    willBeLive: boolean = false,
    betTypeIds = []
  ): Observable<{ result: EventWithEventBetTypes<Match>[]; hasMore: boolean }> {
    const offset = pageIndex * pageSize;

    return this.httpClient
      .get<EventWithEventBetTypes<Match>[]>(
        `${globalConfiguration.apiEventsBaseUrl}events/sports${buildQueryString({
          offset,
          length: pageSize === null ? null : pageSize + 1,
          fetchEventBetTypesMode,
          entryPointId,
          willBeLive,
          betTypeIds
        })}`
      )
      .pipe(
        map(data =>
          data.filter(e => {
            const hasEventBetTypes = this.eventHasEventBetTypes(e);
            if (hasEventBetTypes || fetchEventBetTypesMode === FetchEventBetTypesMode.None) {
              e.expectedStart = new Date(e.expectedStart);
              this.addEventToCache(e);

              return true;
            }

            return false;
          })
        ),
        map(result => {
          return {
            hasMore: result.length === pageSize + 1,
            result: pageSize !== null ? result.slice(0, pageSize) : result
          };
        })
      );
  }

