  getEvents<T extends Event, U extends EventBetType = EventBetType>(
    eventCategoryIds: number[],
    pageIndex: number = 0,
    pageSize: number = 20,
    fetchEventBetTypesMode: FetchEventBetTypesMode = FetchEventBetTypesMode.Default,
    betTypeId: number = null,
    maximumOdds: number = null
  ): Observable<{ result: EventWithEventBetTypes<T, U>[]; hasMore: boolean }> {
    const offset = pageIndex * pageSize;
    const url = `${globalConfiguration.apiEventsBaseUrl}events${buildQueryString({
      eventCategoryIds,
      offset,
      length: pageSize === null ? null : pageSize + 1,
      fetchEventBetTypesMode,
      betTypeId,
      maximumOdds,
      l: this.userLanguage
    })}`;

    const results = this.httpClient.get<EventWithEventBetTypes<T, U>[]>(url).pipe(
      map(data =>
        data.filter(e => {
          if (fetchEventBetTypesMode === FetchEventBetTypesMode.None) {
            return true;
          }

          const hasEventBetTypes = this.eventHasEventBetTypes(e);
          if (hasEventBetTypes) {
            e.expectedStart = new Date(e.expectedStart);
            this.addEventToCache(e);

            return true;
          }

          return false;
        })
      ),
      map(result => {
        return {
          hasMore: result.length === pageSize + 1,
          result: pageSize !== null ? result.slice(0, pageSize) : result
        };
      })
    );

    return results;
  }

  searchEvents<T extends Event>(
    searchTerm: string,
    betCategoryTypes: BetCategoryType[],
    pageIndex: number = 0,
    pageSize: number = 20,
    fetchEventBetTypesMode: FetchEventBetTypesMode = FetchEventBetTypesMode.Default
  ): Observable<{ result: EventWithEventBetTypes<T>[]; hasMore: boolean }> {
    const offset = pageIndex * pageSize;
    const url = `${globalConfiguration.apiEventsBaseUrl}events/search${buildQueryString({
      offset,
      length: pageSize === null ? null : pageSize + 1,
      betCategoryTypes,
      searchTerm,
      fetchEventBetTypesMode
    })}`;
    return this.httpClient.get<EventWithEventBetTypes<T>[]>(url).pipe(
      map(data =>
        data.filter(e => {
          if (e.eventType !== EventType.DrawGame) {
            const hasEventBetTypes = this.eventHasEventBetTypes(e);
            if (hasEventBetTypes) {
              e.expectedStart = new Date(e.expectedStart);
              this.addEventToCache(e);
            }
            return hasEventBetTypes;
          }
          e.expectedStart = new Date(e.expectedStart);
          this.addEventToCache(e);
          return e;
        })
      ),
      map(result => ({ result: result.slice(0, pageSize), hasMore: result.length === pageSize + 1 }))
    );
  }

