  private groupHorseRaceArrivalInCaseOfDraw(
    arrival: { item1: number; item2: number }[]
  ): { position: number; runners: number[] }[] {
    return arrival?.reduce((a, b) => {
      // GROUP ARRIVAL BY PLACE IN CASE OF DRAW
      const indexOfExistingPostion = a.findIndex(w => w.position === b.item1);
      const positionAlreadyExist = indexOfExistingPostion !== -1;
      if (positionAlreadyExist) {
        if (Array.isArray(a[indexOfExistingPostion].runners)) {
          a[indexOfExistingPostion].runners.push(b.item2);
        } else {
          a[indexOfExistingPostion].runners = [...a[indexOfExistingPostion].runners, b.item2];
        }
        return a;
      } else {
        return [...a, { position: b.item1, runners: [b.item2] }];
      }
    }, [] as { position: number; runners: number[] }[]);
  }

