import { Component, ChangeDetectionStrategy, Output, EventEmitter, Input, HostBinding, OnInit } from '@angular/core';
import { SendComponentMessageOptions } from '@honoregaming/ui';

@Component({
  selector: 'hg-popin',
  templateUrl: './popin.component.html',
  styleUrls: ['./popin.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class PopinComponent implements OnInit {
  @Output()
  close = new EventEmitter<any>();

  @Input()
  message: string;

  @Input()
  component: { component: any; props: any };

  @Input()
  options: SendComponentMessageOptions = {
    canBeDismissed: true,
    displayClose: true,
    className: '',
    id: '',
    wowEffect: false,
    zIndex: 20
  };

  isConfettisAnimationFinished: boolean = false;

  @HostBinding('style.z-index')
  zIndex: number = this.options.zIndex;

  ngOnInit(): void {
    this.zIndex ??= this.options.zIndex;
  }
}
