import { mul } from '@honoregaming/core';
import { DrawGameDetails } from '@honoregaming/types';
import { BetLine } from '../models';
import { combinaison, factorial } from './bet-slip.utils';

export function computeAmountForDrawGames(betLine: BetLine): { betLine: BetLine; amount: number } {
  const multiple = getMultipleForDrawGames(betLine);
  let amount: number = null;

  const betLineToUpdate: BetLine = {
    ...betLine
  };

  if (multiple) {
    const multipleAmount = multiple * betLineToUpdate.baseAmount;

    amount = multipleAmount * betLineToUpdate.multiplier;
    betLineToUpdate.multipliers = [];

    betLine.allowedMultipliers.forEach(m => {
      if (!betLineToUpdate.maximumAmount || betLineToUpdate.maximumAmount >= mul(multipleAmount, m)) {
        betLineToUpdate.multipliers.push({ value: m, label: m.toString() });
      }
    });

    if (betLineToUpdate.multipliers?.length === 0) {
      betLineToUpdate.multipliers = [{ value: 1, label: '1' }];
      betLineToUpdate.multiplier = 1;
    }
  } else {
    betLineToUpdate.multipliers = [{ value: 1, label: '1' }];
    betLineToUpdate.multiplier = 1;
  }

  return { betLine: betLineToUpdate, amount: amount };
}

export function getMultipleForDrawGames(betLine: BetLine): number {
  // The rule may carry no detail for the current betType — fall back on the rule minimum
  const drawGameDetail: DrawGameDetails = betLine.drawGameDetails?.find(
    (detail: DrawGameDetails) => detail.betTypeId === betLine.betTypeId
  );
  const minBaseSelection: number = drawGameDetail?.selectionCount ?? betLine.minBaseSelection;

  if (betLine.extraNumberEnabled && betLine.extraList && betLine.extraList.length > 0) {
    return (
      (combinaison(betLine.baseList.length, minBaseSelection) / factorial(minBaseSelection)) *
      (combinaison(betLine.extraList.length, betLine.minExtraSelection) / factorial(betLine.minExtraSelection))
    );
  } else {
    return combinaison(betLine.baseList.length, minBaseSelection) / factorial(minBaseSelection);
  }
}
