import { Injectable } from '@angular/core';
import { OddsPreviewerState } from '@honoregaming/ui';
import { Subject } from 'rxjs';

@Injectable({ providedIn: 'root' })
export class OddsPreviewerVisibilityService {
  private oddsPreviewerVisibilityChangedSubject = new Subject<OddsPreviewerState>();
  public oddsPreviewerVisibilityChanged$ = this.oddsPreviewerVisibilityChangedSubject.asObservable();

  constructor() {}

  public raiseOddsPreviewerVisibilityChanged(state: OddsPreviewerState): void {
    this.oddsPreviewerVisibilityChangedSubject.next(state);
  }
}
