import { Component, OnInit, ChangeDetectionStrategy, Input, OnChanges } from '@angular/core';

@Component({
  selector: 'hg-horseracing-bettype-icon',
  templateUrl: './horseracing-bettype-icon.component.html',
  styleUrls: ['./horseracing-bettype-icon.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class HorseracingBettypeIconComponent implements OnInit, OnChanges {
  @Input()
  betTypeId: number;

  @Input()
  booster: boolean;

  @Input()
  iconUrl: string;

  imgUrl: string = null;

  constructor() {}

  ngOnInit() {
    this.setImgUrl();
  }

  ngOnChanges(): void {
    this.setImgUrl();
  }

  setImgUrl() {
    if (this.iconUrl) {
      if (!this.booster) {
        this.imgUrl = this.iconUrl;
      } else {
        const indexOfLastDot = this.iconUrl.lastIndexOf('.');
        this.imgUrl = this.iconUrl.substring(0, indexOfLastDot) + '-booster' + this.iconUrl.substring(indexOfLastDot);
      }
    } else {
      if (!this.booster) {
        this.imgUrl = '/assets/images/horse-racing/bettype-' + this.betTypeId + '.svg';
      } else {
        this.imgUrl = '/assets/images/horse-racing/bettype-' + this.betTypeId + '-booster.svg';
      }
    }
  }
}
