import { Inject, Injectable } from '@angular/core';
import { CanActivate, ActivatedRouteSnapshot, CanActivateChild, Router } from '@angular/router';
import { Observable, of } from 'rxjs';
import { AuthService } from '@honoregaming/authentication';
import { kioskToken } from '@honoregaming/core';
import { OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';

@Injectable()
export class KioskGuard implements CanActivate, CanActivateChild {
  constructor(
    private authService: AuthService,
    private router: Router,
    @Inject(kioskToken) private isKiosk: boolean,
    @Inject(operatorConfigurationToken) private operatorConfiguration: OperatorConfiguration
  ) {}

  canActivate(_route: ActivatedRouteSnapshot): Observable<boolean> {
    if (_route.routeConfig?.path === 'login' && !this.isKiosk) {
      this.router.navigate(['/']);
      return of(false);
    }

    if (this.isKiosk) {
      if (this.operatorConfiguration.kioskConfiguration?.authenticationRequired ?? true) {
        if (_route.routeConfig?.path !== 'login' && !this.authService.isAuthenticated()) {
          this.router.navigate(['login']);
          return of(false);
        }
      }
    }

    return of(true);
  }

  canActivateChild(childRoute: ActivatedRouteSnapshot): boolean | Observable<boolean> | Promise<boolean> {
    return this.canActivate(childRoute);
  }
}
