import { Component, ChangeDetectionStrategy, Input, Output, EventEmitter } from '@angular/core';

@Component({
  selector: 'hg-horse-racing-selection',
  templateUrl: './horse-racing-selection.component.html',
  styleUrls: ['./horse-racing-selection.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class HorseRacingSelectionComponent {
  @Input()
  betTypeId: number;

  @Input()
  booster: boolean;

  @Input()
  associatedList: (number | string)[];

  @Input()
  addSelectionButton: boolean = false;

  @Input()
  baseList: (number | string)[];

  @Output() openSelectionCompletionClick = new EventEmitter();
  @Output() deleteRaceSelectionClick = new EventEmitter();

  constructor() {}

  openSelectionCompletion() {
    this.openSelectionCompletionClick.next();
  }

  deleteRaceSelection() {
    this.deleteRaceSelectionClick.next();
  }
}
