import { Observable, throwError as _throw, of } from 'rxjs';
import { catchError, shareReplay } from 'rxjs/operators';
import { cacheable } from '../utils';

const CACHEABLE_KEY = '__cacheable_decorator_cacheable_key__';

export interface ICacheConfig {
  ttl?: number; // time to live in second
  useLocalStorage?: boolean;
}

export function Cacheable(cacheConfig?: ICacheConfig) {
  return function (
    target: any,
    propertyKey: string,
    descriptor: TypedPropertyDescriptor<(...args: any[]) => Observable<any>>
  ) {
    if (typeof window === 'undefined') {
      return;
    }
    const originalMethod = descriptor.value;
    const cacheablePropertyName = `__${propertyKey}__cacheablecontent`;
    const cacheableKeyPropertyName = `__${propertyKey}__cacheablecontent__key`;
    const ttlPropertyName = `__${propertyKey}__cacheablecontent__ttl`;

    target[cacheablePropertyName] = {};

    let ttl = null;
    if (cacheConfig?.ttl) {
      ttl = cacheConfig.ttl * 1000; // seconds to milliseconds
    }

    descriptor.value = function (...args: any[]) {
      const valuesKey = args
        .filter(a => {
          if (a instanceof Date) {
            return true;
          } else if (typeof a === 'object' && !Array.isArray(a)) {
            console.warn('Object parameters are not supported. It has been ignored !');
            return false;
          }

          return true;
        })
        .toString();
      if (cacheConfig?.useLocalStorage) {
        let storageItem = localStorage.getItem(`${cacheablePropertyName}_${valuesKey}`);
        let contentValue = storageItem ? JSON.parse(storageItem) : undefined;

        // Cache not found
        if (!contentValue) {
          var observable = originalMethod.apply(this, args).pipe(
            shareReplay(1),
            catchError(error => {
              localStorage.removeItem(`${cacheablePropertyName}_${valuesKey}`);
              return _throw(error);
            })
          );

          observable.subscribe(result => {
            contentValue = {};
            if (ttl) {
              contentValue[ttlPropertyName] = new Date().getTime() + ttl;
            }
            contentValue['result'] = result;
            localStorage.setItem(`${cacheablePropertyName}_${valuesKey}`, JSON.stringify(contentValue));
          });

          return observable;
        }

        // Cache found but ttl hasn't expired
        if (
          contentValue &&
          ttl &&
          contentValue[ttlPropertyName] &&
          (contentValue[ttlPropertyName] as number) + ttl > new Date().getTime()
        ) {
          return of(contentValue['result']);
        }

        // Cache found but ttl has expired
        if (
          contentValue &&
          ttl &&
          contentValue[ttlPropertyName] &&
          (contentValue[ttlPropertyName] as number) + ttl < new Date().getTime()
        ) {
          var observable = originalMethod.apply(this, args).pipe(
            shareReplay(1),
            catchError(error => {
              localStorage.removeItem(`${cacheablePropertyName}_${valuesKey}`);
              return _throw(error);
            })
          );

          observable.subscribe(result => {
            contentValue = {};
            contentValue[ttlPropertyName] = new Date().getTime() + ttl;
            contentValue['result'] = result;
            localStorage.setItem(`${cacheablePropertyName}_${valuesKey}`, JSON.stringify(contentValue));
          });

          return observable;
        }

        if (!ttl) {
          return of(contentValue['result']);
        }
      } else {
        const targetKey = this[CACHEABLE_KEY] ? this[this[CACHEABLE_KEY]] : undefined;

        var needToRefreshCache =
          !!this[cacheablePropertyName][valuesKey] && ttl && target[ttlPropertyName] < new Date().getTime();

        if (
          !this[cacheablePropertyName][valuesKey] ||
          this[cacheableKeyPropertyName] !== targetKey ||
          needToRefreshCache
        ) {
          if (ttl) {
            target[ttlPropertyName] = new Date().getTime() + ttl;
          }

          this[cacheablePropertyName][valuesKey] = cacheable(originalMethod.apply(this, args)).pipe(
            catchError(error => {
              this[cacheablePropertyName][valuesKey] = null;
              return _throw(error);
            })
          );

          if (!needToRefreshCache) {
            this[cacheableKeyPropertyName] = targetKey;
          }
        }

        return this[cacheablePropertyName][valuesKey];
      }
    };
  };
}

export function CacheableVaryByKey() {
  return function (target: Object, propertyKey: string | symbol) {
    target[CACHEABLE_KEY] = propertyKey;
  };
}
