import {
  AutoPaymentLimiterConfiguration,
  ComplianceConfiguration,
  OperatorConfiguration,
  ScoreWidgetConfiguration,
  ScoreWidgetType
} from '@honoregaming/configuration';
import { InjectionToken, Provider } from '@angular/core';
import { DocumentType, DocumentName } from '@honoregaming/types';

export interface CustomerOperatorConfiguration extends OperatorConfiguration {
  customization: { [section: string]: any };

  headerCustomization: {
    liveScoreUrl: string;
    statisticUrl: string;
  };

  scoreWidgetConfiguration: {
    enabled: boolean;
    type: ScoreWidgetType;
    configuration: ScoreWidgetConfiguration;
  };

  knowYourCustomerConfiguration: KnowYourCustomerConfiguration;
  responsibleGamblingConfiguration: ResponsibleGamblingConfiguration;
  complianceConfiguration: ComplianceConfiguration;
  autoPaymentLimiterConfiguration: AutoPaymentLimiterConfiguration | null;
  gameSessionConfiguration: GameSessionConfiguration;
  s2STelemetryConfiguration: S2STelemetryCustomerConfiguration;
  hasNew: string[];
}

export interface KnowYourCustomerConfiguration {
  customerAccessLimitationConfiguration: {
    blockDeposit: boolean;
    blockBetting: boolean;
    blockWithdrawal: boolean;
    numberOfDaysBeforeAutomaticRejection: number;
    minimumAgeRequired: number;
  };
  documentTypesConfiguration: DocumentTypeConfiguration[];
  maximumFileSizeInMb: number;
  useExternalKYCValidation: boolean;
}

export interface ResponsibleGamblingConfiguration {
  selfExclusionActive: boolean;
  betLimitationActive: boolean;
  depositLimitationActive: boolean;
  customerLimitationDurationInDays: number;
  delayForCustomerLimitationChangeInHours: number;
  minimumBetLimitationAmount: number;
  maximumBetLimitationAmount: number;
  minimumDepositLimitationAmount: number;
  maximumDepositLimitationAmount: number;
  customerCategoriesConfiguration: { [key: string]: CustomerCategoryConfiguration };
}

export interface CustomerCategoryConfiguration {
  depositLimitationAmount: number;
  betCategoriesConfiguration: { [key: string]: BetCategoryConfiguration };
}

export interface BetCategoryConfiguration {
  betLimitationAmount: number;
  betLimitationActive: boolean;
}
export interface DocumentTypeConfiguration {
  type: DocumentType;
  isRequired: boolean;
  documentsConfiguration: DocumentConfiguration[];
}

export interface DocumentConfiguration {
  name: DocumentName;
  rectoVerso: boolean;
  formats: string[];
}

export interface GameSessionConfiguration {
  closeSessionOnCustomerNavigation: boolean;
  applyPaymentTaxOnSession: boolean;
}

export const customerOperatorConfigurationToken = new InjectionToken<CustomerOperatorConfiguration>(
  'CustomerOperatorConfiguration'
);

export function customerOperatorConfigurationProviderFactory(): Provider {
  return {
    provide: customerOperatorConfigurationToken,
    useFactory: () => ({})
  };
}

export interface HomePageCustomization {
  searchButtonOrder?: string;
  allSportsButtonOrder?: string;
  topMatchsOrder?: string;
  topInstantGamesOrder?: string;
  numberOfBanners?: string;
  hideAllSportsButton?: string;
  elementsOrder?: ElementsOrder;
  eventTabs?: EventTab[];
  shortcutsLinks?: ShortcutLink[];
}

export interface ElementsOrder {
  desktop: string[];
  mobile: string[];
}
export interface EventTab {
  type: string;
  text: string;
  order: number;
}
export interface ShortcutLink {
  action?: { url: string };
  iconUrl?: string;
  text?: string;
}

export interface S2STelemetryCustomerConfiguration {
  s2SClickIdParams: S2SClickIdParam[];
}

export interface S2SClickIdParam {
  trackerName: string;
  clickIdParam: string;
}
