import {
  Component,
  ChangeDetectionStrategy,
  EventEmitter,
  Output,
  ViewChild,
  ElementRef,
  ChangeDetectorRef
} from '@angular/core';
import { CustomerService } from '@honoregaming/customer-core';
import { finalize } from 'rxjs/operators';

@Component({
  selector: 'hg-accept-gcu',
  templateUrl: './accept-gcu.component.html',
  styleUrls: ['./accept-gcu.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class AcceptGcuComponent {
  @Output()
  public close = new EventEmitter<boolean>();
  @ViewChild('rulesContainer') rulesContainer: ElementRef;
  loading = false;

  constructor(private customerService: CustomerService, private cdRef: ChangeDetectorRef) {}

  acceptGcu() {
    this.loading = true;
    this.customerService
      .acceptGCU()
      .pipe(
        finalize(() => {
          this.loading = false;
          this.cdRef.markForCheck();
        })
      )
      .subscribe(() => {
        this.close.emit(true);
      });
  }
}
