import {
  ChangeDetectionStrategy,
  Component,
  EventEmitter,
  Input,
  OnChanges,
  OnInit,
  Output,
  SimpleChanges
} from '@angular/core';
import { FreeBetCouponBetSlip, FreeBetRuleBettingValidation } from '@honoregaming/betslip';
import { BetCategoryType, BetSlipMode, FreeBetCouponState } from '@honoregaming/types';

// toDo:: Continue to split coupon in multiple components and after try to merge freebet and freespin components
@Component({
  selector: 'hg-freebet-coupon',
  templateUrl: './freebet-coupon.component.html',
  styleUrls: ['./freebet-coupon.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class FreebetCouponComponent implements OnInit, OnChanges {
  @Input() isBetSlipView: boolean = true;
  @Input() freebetCoupon!: FreeBetCouponBetSlip;
  @Input() currentBetCategory?: BetCategoryType | string;

  // Bet-slip Settings
  @Input() isSelected: boolean = false;
  @Input() betSlipMode: BetSlipMode;
  @Input() parentIndex: number;

  // FreeBetFeature Configuration
  @Input() multiCouponActive: boolean;
  @Input() index: number;

  @Output() couponSelected = new EventEmitter<FreeBetCouponBetSlip>();

  ruleDisplayToggle: boolean = false;
  couponImageUrl?: string;

  // Available Images Count - 1 To handle Modulo = 0
  availableImageCount: number = 27;
  customerAssetPath: string = 'assets/freebets/';
  assetExtension: string = '.jpg';

  currentValidationRules?: FreeBetRuleBettingValidation;
  myCouponsBettingValidationCount: number = 0;

  // Types
  BetCategoryType = BetCategoryType;
  FreeBetCouponState = FreeBetCouponState;

  constructor() {}

  ngOnInit(): void {
    this.myCouponsBettingValidationCount = this.getBettingValidationCount();
    this.getCouponImage();
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes.betSlipMode?.currentValue) {
      this.currentValidationRules =
        changes.betSlipMode.currentValue === BetSlipMode.Simple
          ? this.freebetCoupon.bettingValidationSimple
          : this.freebetCoupon.bettingValidationMultiple;
    }

    if (changes.parentIndex !== undefined) {
      this.ruleDisplayToggle = false;
    }

    if (!!changes.index && this.ruleDisplayToggle) {
      this.ruleDisplayToggle = false;
    }
  }

  onCouponSelected(): void {
    if (this.freebetCoupon.canBeUsed) {
      this.couponSelected.emit(this.freebetCoupon);
    } else {
      this.toggleRules();
    }
  }

  toggleRules(event?: Event): void {
    if (this.freebetCoupon.bettingRequirementsQuantity || this.myCouponsBettingValidationCount) {
      this.ruleDisplayToggle = !this.ruleDisplayToggle;
    }
    event?.stopPropagation();
  }

  private getBettingValidationCount(): number {
    if (!this.freebetCoupon.freeBetRule.bettingRequirements) {
      return 0;
    }

    // Default validation on expiration date + additional requirements
    let rulesQuantity = Object.keys(this.freebetCoupon.freeBetRule.bettingRequirements).length;

    if (this.multiCouponActive) {
      rulesQuantity++;
    }

    if (!!this.freebetCoupon.freeBetRule.mustUseAllBalance) {
      rulesQuantity++;
    }

    return rulesQuantity;
  }

  private getCouponImage() {
    const moduloIndex = (this.freebetCoupon.id % this.availableImageCount) + 1;
    this.couponImageUrl = this.customerAssetPath + moduloIndex + this.assetExtension;
  }
}
