import { NgModule, ModuleWithProviders } from '@angular/core';
import { MinDirective } from './validators/min.validator';
import { MaxDirective } from './validators/max.validator';
import { BetCategoriesGuard, FeaturesGuard } from './guards';
import { EqualsValidatorDirective } from './validators/equals-passwords.validator';
import { PasswordPolicyRequirementValidatorDirective } from './validators/password.validator';
import { DeferOnVisibleDirective } from './directives/defer-on-visible.directive';
import { IntersectionObserverDirective } from './directives/intersection-observer.directive';

@NgModule({
  declarations: [
    MinDirective,
    MaxDirective,
    PasswordPolicyRequirementValidatorDirective,
    EqualsValidatorDirective,
    DeferOnVisibleDirective,
    IntersectionObserverDirective
  ],
  imports: [],
  exports: [
    MinDirective,
    MaxDirective,
    PasswordPolicyRequirementValidatorDirective,
    EqualsValidatorDirective,
    DeferOnVisibleDirective,
    IntersectionObserverDirective
  ]
})
export class HgCoreModule {
  static forRoot(): ModuleWithProviders<HgCoreModule> {
    return {
      ngModule: HgCoreModule,
      providers: [BetCategoriesGuard, FeaturesGuard]
    };
  }
}
