import { Component, ChangeDetectionStrategy, Input, Output, EventEmitter, Inject } from '@angular/core';
import { BetLine, BetLineAmount, BetSlipType, FreeBetCouponBetSlip } from '../../../models';
import { operatorConfigurationToken, OperatorConfiguration } from '@honoregaming/configuration';
import { I18nService } from '@honoregaming/i18n';
import { getBetLineAmountErrorAndCode } from '../../../utils';
import { DialogService, Scope, scopeToken } from '@honoregaming/core';

@Component({
  selector: 'hg-match-bet-line',
  templateUrl: './match-bet-line.component.html',
  styleUrls: ['./match-bet-line.component.scss', '../bet-line-content.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class MatchBetLineComponent {
  @Input()
  betLine: BetLine;
  @Input()
  showIndividualNewStakeMessage: boolean = false;
  @Input()
  amount: BetLineAmount;

  @Input()
  acceptOddChange: boolean;

  @Input()
  betSlipType: BetSlipType;

  @Input()
  useFreeBet: boolean = false;

  @Input()
  balance: number = 0;

  @Input()
  selectedFreeBetCoupon: FreeBetCouponBetSlip;

  @Output()
  amountChange = new EventEmitter<number>();
  @Output()
  remove = new EventEmitter<void>();

  currency = this.operatorConfiguration.currency.symbol;

  errorMessage?: string;
  errorCode?: string;

  constructor(
    @Inject(operatorConfigurationToken) private operatorConfiguration: OperatorConfiguration,
    private i18nService: I18nService,
    private dialogService: DialogService,
    @Inject(scopeToken) private userScope: Scope
  ) {}

  onAmountChange(amount: number) {
    this.amountChange.emit(amount);
  }

  onRemove() {
    this.remove.emit();
  }

  isValidAmount() {
    ({ error: this.errorMessage, code: this.errorCode } = getBetLineAmountErrorAndCode(
      this.i18nService,
      this.amount.amount,
      this.betLine.leftoverBalanceAmount || this.betLine.baseAmount,
      this.betLine.leftoverBalanceAmount || this.betLine.maximumAmount,
      this.betLine.leftoverBalanceAmount || this.betLine.minimumAmountIncrement,
      this.showIndividualNewStakeMessage ? this.betLine.newStake : null,
      this.amount.payout,
      this.useFreeBet,
      this.useFreeBet ? this.selectedFreeBetCoupon?.balance ?? 0 : this.balance,
      this.userScope
    ));
    return !this.errorMessage;
  }

  toggleBetSlip() {
    this.dialogService.toggleDialog('betslip', false);
  }
}
