import { Component, ChangeDetectionStrategy, HostBinding, Input } from '@angular/core';

@Component({
  selector: 'hg-three-columns-layout',
  templateUrl: './three-columns-layout.component.html',
  styleUrls: ['./three-columns-layout.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class ThreeColumnsLayoutComponent {
  @Input() leftWidth: string = '300px';
  @Input() centerMaxWidth: string = '792px';
  @Input() rightWidth: string = '300px';

  @HostBinding('style.--left-width') get leftWidthStyle() {
    return this.leftWidth;
  }
  @HostBinding('style.--center-max-width') get centerMaxWidthStyle() {
    return this.centerMaxWidth;
  }
  @HostBinding('style.--right-width') get rightWidthStyle() {
    return this.rightWidth;
  }

  constructor() {}
}
