import { Component, OnInit, ChangeDetectionStrategy, Input, Inject } from '@angular/core';
import { BetLine, BetSlipService, createBetLineWithSelection } from '@honoregaming/betslip';
import { OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';
import { DestroySubject, Scope, scopeToken } from '@honoregaming/core';
import { BorletteSelectionToBetslip } from '@honoregaming/draw-games-ui';
import { BetCategoryType, DrawGame, DrawGameBorletteBetType, EventBetType } from '@honoregaming/types';

@Component({
  selector: 'hg-borlette',
  templateUrl: './borlette.component.html',
  styleUrls: ['./borlette.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class BorletteComponent extends DestroySubject implements OnInit {
  DrawGameBorletteBetType = DrawGameBorletteBetType;

  @Input() drawGame?: DrawGame;
  @Input() drawGames: DrawGame[] = [];
  @Input() isQuickBet: boolean = false;
  @Input() displayPointe: boolean = false;
  @Input() displayRaleBoule: boolean = false;
  activeTab: number | undefined;
  eventBetTypesList: EventBetType[] = [];
  defaultStake: number = 1;
  defaultSelectedDrawGamesIds: number[] = [];

  constructor(
    private readonly betSlipService: BetSlipService,
    @Inject(scopeToken) private readonly userScope: Scope,
    @Inject(operatorConfigurationToken) private readonly operatorConfiguration: OperatorConfiguration
  ) {
    super();
  }

  ngOnInit(): void {
    this.drawGames = this.drawGames.filter(x =>
      x.betTypeIds.some(y => Object.values(DrawGameBorletteBetType).includes(y))
    );
    const seenIds = new Set();
    this.eventBetTypesList =
      (this.drawGame ? this.drawGame : this.drawGames[0]).eventBetTypes?.filter(x => {
        if (!x.active || seenIds.has(x.id)) {
          return false;
        }
        seenIds.add(x.id);
        return true;
      }) ?? [];
    this.eventBetTypesList.sort((a, b) => a.name.localeCompare(b.name, undefined, { sensitivity: 'base' }));
    this.activeTab = this.eventBetTypesList.length > 0 ? this.eventBetTypesList[0].betTypeId : undefined;
    this.defaultStake =
      (this.userScope === Scope.Customer
        ? this.operatorConfiguration.bettingConfiguration?.defaultCustomerBorletteStake
        : this.operatorConfiguration.bettingConfiguration?.defaultAgentBorletteStake) ??
      this.getEventBetType(this.activeTab)?.baseAmount;

    this.defaultSelectedDrawGamesIds = this.drawGame != null ? [this.drawGame.id] : [];
  }

  setActiveTab(betTypeId: number): void {
    this.activeTab = betTypeId;
  }

  getEventBetType(id: number | undefined): EventBetType | undefined {
    return id ? this.eventBetTypesList.find(ebt => ebt.betTypeId === id) : undefined;
  }

  getPredefinedStakes(id: number): number[] {
    return this.getEventBetType(id)?.betTypeId === DrawGameBorletteBetType.Loto6
      ? [10, 25, 50]
      : this.operatorConfiguration.global.predefinedStakes?.drawGameFixedOddsPredefinedStakes ?? [50, 100, 250];
  }

  addToBetSlip(data: BorletteSelectionToBetslip): void {
    const eventBetType = this.getEventBetType(this.activeTab);
    for (let selection of data.selections) {
      if (eventBetType.betTypeId === DrawGameBorletteBetType.DoubChans) {
        const eventA = this.drawGames.find(x => x.id === data.drawGamesIds[0]);
        const eventB = this.drawGames.find(x => x.id === data.drawGamesIds[1]);
        const mainEvent = eventA.expectedStart > eventB.expectedStart ? eventA : eventB;
        const mainEventBetType = mainEvent.eventBetTypes.find(x => x.betTypeId === eventBetType.betTypeId);
        this.betSlipService.addBetLine(
          this.createBetLine(mainEvent, mainEventBetType, selection, data.stakes[0], undefined, [
            mainEvent.id === eventA.id ? eventB.id : eventA.id
          ])
        );
      } else {
        for (let drawGameId of data.drawGamesIds) {
          const betEvent = this.drawGames.find(x => x.id === drawGameId);
          const betEventBetType = betEvent.eventBetTypes.find(x => x.betTypeId === eventBetType.betTypeId);
          if (
            eventBetType?.betTypeId === DrawGameBorletteBetType.Loto4 ||
            eventBetType?.betTypeId === DrawGameBorletteBetType.Loto5
          ) {
            for (let i = 0; i < data.stakes.length; i++) {
              if (Number.isFinite(data.stakes[i])) {
                this.betSlipService.addBetLine(
                  this.createBetLine(betEvent, betEventBetType, selection, data.stakes[i], i + 1)
                );
              }
            }
          } else {
            this.betSlipService.addBetLine(this.createBetLine(betEvent, betEventBetType, selection, data.stakes[0]));
          }
        }
      }
    }
  }

  createBetLine(
    event: DrawGame,
    eventBetType: EventBetType,
    selection: string[],
    stake: number,
    optionNumber?: number,
    associatedDrawGamesIds?: number[]
  ): BetLine {
    const baseList =
      eventBetType.betTypeId === DrawGameBorletteBetType.Mariage
        ? [selection[0] + selection[1]]
        : eventBetType.betTypeId === DrawGameBorletteBetType.Loto6
        ? [selection[0], selection[1], selection[2]]
        : eventBetType.betTypeId === DrawGameBorletteBetType.DoubChans
        ? [selection[0], selection[1]]
        : [selection[0]];
    eventBetType.baseAmount = stake;
    return createBetLineWithSelection(
      event,
      eventBetType,
      baseList,
      [],
      BetCategoryType.DrawGame,
      event.drawGameRule,
      null,
      null,
      undefined,
      undefined,
      undefined,
      optionNumber,
      associatedDrawGamesIds
    );
  }
}
