import { Injectable } from '@angular/core';
import { Inject, PLATFORM_ID } from '@angular/core';
import { isPlatformBrowser } from '@angular/common';

declare var localStorage;

@Injectable({ providedIn: 'root' })
export class LocalStorageService {
  private localStore: { [key: string]: any } = {};
  private storageDisabled = false;

  constructor(@Inject(PLATFORM_ID) private platformId) {
    try {
      // tslint:disable-next-line: no-unused-expression
      void localStorage;
    } catch (e) {
      if (e instanceof DOMException) {
        this.storageDisabled = true;
      }
    }
  }

  getItem(name: string) {
    if (isPlatformBrowser(this.platformId) && !this.storageDisabled) {
      try {
        return JSON.parse(localStorage[name]);
      } catch {
        return localStorage[name];
      }
    } else {
      return this.localStore[name];
    }
  }

  setItem(name: string, value: any) {
    if (isPlatformBrowser(this.platformId) && !this.storageDisabled) {
      localStorage[name] = JSON.stringify(value);
    } else {
      this.localStore[name] = value;
    }
  }

  removeItem(name) {
    if (isPlatformBrowser(this.platformId) && !this.storageDisabled) {
      delete localStorage[name];
    } else {
      delete this.localStore[name];
    }
  }
}
