import {
  Component,
  ChangeDetectionStrategy,
  Input,
  ViewChild,
  ElementRef,
  ChangeDetectorRef,
  Output,
  EventEmitter,
  OnInit,
  OnDestroy
} from '@angular/core';
import { AccountService } from '../../services/account.service';
import { finalize, takeUntil } from 'rxjs/operators';
import { Observable, Subscription } from 'rxjs';
import { DestroySubject } from '@honoregaming/core';
import {
  DocumentTypeConfiguration,
  DocumentConfiguration,
  KnowYourCustomerConfiguration
} from '@honoregaming/customer-core';
import { I18nService } from '@honoregaming/i18n';
import { DocumentType } from '@honoregaming/types';

@Component({
  selector: 'hg-account-form-document-item',
  templateUrl: './account-form-document-item.component.html',
  styleUrls: ['./account-form-document-item.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class AccountFormDocumentItemComponent extends DestroySubject implements OnInit, OnDestroy {
  @Input() knowYourCustomerConfiguration: KnowYourCustomerConfiguration;
  @Input() selectedDocumentType: DocumentTypeConfiguration;
  @Input() documentType: DocumentTypeConfiguration;
  @Input() document: DocumentConfiguration;
  @Input() documentSelected: DocumentConfiguration;
  @Input() cancel: Observable<void>;

  @Output()
  fileUploadedEvent = new EventEmitter();

  @Output()
  documentSelectedEvent = new EventEmitter();

  @Output()
  resetDocumentsEvent = new EventEmitter();

  isVerso: boolean = false;
  loading: string | boolean = false;
  loadingPreview: boolean = false;
  documentFiles: { recto: any; verso: any } = {
    recto: null,
    verso: null
  };
  mode: 'preview' | 'selection';
  currentImagePreview: string;
  currentImageFormData: FormData;
  filesUploadedNumber: number = 0;
  hasAllDocuments: boolean = false;
  error: string;
  private cancelSubscription: Subscription;

  DocumentType = DocumentType;

  @ViewChild('inputFile') inputFile: ElementRef;
  identityDocumentReference: string;

  constructor(
    private accountService: AccountService,
    private cdRef: ChangeDetectorRef,
    private i18nService: I18nService
  ) {
    super();
  }

  ngOnInit(): void {
    this.cancelSubscription = this.cancel.subscribe(() => this.reset());
  }

  onFileChanged(event: any, documentType: any) {
    this.error = undefined;
    if (!this.document.formats.includes(event.target.files[0]?.type)) {
      this.error = this.i18nService.translateSync('ACCOUNT.DOCUMENT.ERROR.BAD_FORMAT');
      return;
    }

    if (event.target.files[0]?.size >= this.knowYourCustomerConfiguration?.maximumFileSizeInMb * (1024 * 1024)) {
      this.error = this.i18nService.translateSync('ACCOUNT.DOCUMENT.ERROR.TOO_BIG');
      return;
    }

    this.loadingPreview = true;
    var formData = new FormData();
    formData.append('File', event.target.files[0]);
    formData.append('Type', documentType.type);
    formData.append('Name', this.document.name);
    formData.append('IsVerso', this.isVerso.toString());
    formData.append('Format', event.target.files[0]?.type);
    formData.append('FileName', event.target.files[0].name);
    formData.append('IdentityDocumentReference', this.identityDocumentReference);

    this.currentImageFormData = formData;

    if (event.target.files[0]?.type.split('/')[0] !== 'image') {
      this.uploadDocument();
    } else {
      const reader = new FileReader();
      reader.onload = _e => {
        this.currentImagePreview = reader.result as string;
        this.mode = 'preview';
        this.loadingPreview = false;
        this.cdRef.markForCheck();
      };
      reader.readAsDataURL(event.target.files[0]);
    }

    event.value = '';
  }

  resetEvent(event: any) {
    const { target = {} } = event || {};
    target.value = '';
  }

  uploadDocument() {
    this.loading = true;
    let fileName = this.currentImageFormData.get('FileName');
    this.currentImageFormData.delete('FileName');
    this.accountService
      .uploadIdentityDocument(this.currentImageFormData)
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.cdRef.markForCheck();
        })
      )
      .subscribe(
        (result: any) => {
          this.loading = false;
          this.documentFiles[this.isVerso ? 'verso' : 'recto'] = result;
          this.documentFiles[this.isVerso ? 'verso' : 'recto'].fileName = fileName;
          this.filesUploadedNumber++;
          if ((this.document.rectoVerso && this.filesUploadedNumber === 2) || !this.document.rectoVerso) {
            this.hasAllDocuments = true;
          }
          this.fileUploadedEvent.emit();
          this.mode = 'selection';
        },
        err => {
          this.loading = false;
          if (err.error?.code === UploadDocumentFailure.FileTooLarge) {
            this.error = this.i18nService.translateSync('ACCOUNT.DOCUMENT.ERROR.TOO_BIG');
          } else if (err.error?.code === UploadDocumentFailure.FormatNotAllowed) {
            this.error = this.i18nService.translateSync('ACCOUNT.DOCUMENT.ERROR.BAD_FORMAT');
          } else if (err.error?.code === UploadDocumentFailure.DuplicateReference) {
            this.error = this.i18nService.translateSync('ACCOUNT.DOCUMENT.ERROR.DUPLICATE_REFERENCE');
          } else {
            this.error = this.i18nService.translateSync('COMMON.GENERIC.ERROR');
          }
        }
      );
  }

  chooseDocument() {
    if (this.documentType.type !== this.selectedDocumentType.type) {
      return;
    }
    this.mode = 'selection';
    this.documentSelectedEvent.emit(this.document);
  }

  chooseDocumentSide(isVerso: boolean = false) {
    this.isVerso = isVerso;
    this.inputFile.nativeElement.click();
  }

  editDocuments() {
    this.filesUploadedNumber = 0;
    this.hasAllDocuments = false;
    this.documentFiles = {
      recto: null,
      verso: null
    };
    this.resetDocumentsEvent.emit();
  }

  reset() {
    this.documentFiles = {
      recto: null,
      verso: null
    };
    this.filesUploadedNumber = 0;
    this.hasAllDocuments = false;
  }

  ngOnDestroy() {
    this.cancelSubscription.unsubscribe();
  }
}

enum UploadDocumentFailure {
  FileTooLarge = 0,
  TypeNotConfigured = 1,
  NameNotConfigured = 2,
  FormatNotAllowed = 3,
  DuplicateReference = 4
}
