import { Component, OnInit, ChangeDetectionStrategy, ChangeDetectorRef, Inject, OnDestroy } from '@angular/core';
import {
  AuthService,
  CustomerOperatorConfiguration,
  CustomerService,
  CustomerState,
  FreeBetService,
  customerOperatorConfigurationToken
} from '@honoregaming/customer-core';
import { Router } from '@angular/router';
import { delay, finalize, takeUntil } from 'rxjs/operators';
import { DestroySubject, hasFlag } from '@honoregaming/core';
import { ProfilePolicy, SecurityPolicy } from '@honoregaming/types';
import { AccountService } from '../../../services/account.service';
import { MessageService } from '@honoregaming/ui';
import { I18nService } from '@honoregaming/i18n';
import { Observable, of } from 'rxjs';

@Component({
  selector: 'hg-step2',
  templateUrl: './step2.component.html',
  styleUrls: ['./step2.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class Step2Component extends DestroySubject implements OnInit, OnDestroy {
  profilePolicyRequirements: ProfilePolicy;
  securityPolicy: SecurityPolicy;
  isValidated: boolean;
  validationCode: string;
  validationCodeReseted: boolean = null;
  isConnected: boolean;
  loadingValidate: boolean;
  loadingReset: boolean;
  resetValidationCodeError: boolean;
  codeLength = 5;
  login: string;
  accept = false;
  recaptchaLegend: string;
  errorOccured: boolean;
  extraInfos$: Observable<string | null> = of(null);

  constructor(
    private authService: AuthService,
    private customerService: CustomerService,
    private cdRef: ChangeDetectorRef,
    private router: Router,
    private accountService: AccountService,
    private messageService: MessageService,
    @Inject(customerOperatorConfigurationToken) private customerOperatorConfiguration: CustomerOperatorConfiguration,
    private i18nService: I18nService,
    private freeBetService: FreeBetService
  ) {
    super();
  }

  ngOnInit() {
    this.customerService.getSecurityPolicy().subscribe(x => {
      this.profilePolicyRequirements = x.profilePolicyRequirements;
      if (this.profilePolicyRequirements) {
        this.accountService.clickRegisterStep(2);
      } else {
        this.accountService.clickRegisterStep(1);
      }
    });

    this.authService.me$.pipe(takeUntil(this.destroy$)).subscribe(x => {
      this.isConnected = !!x;

      if (x) {
        this.login = x.login;
      }

      if (
        this.isConnected &&
        hasFlag(x.state, CustomerState.LoginValidated) &&
        !this.customerOperatorConfiguration.knowYourCustomerConfiguration?.customerAccessLimitationConfiguration
          ?.blockDeposit
      ) {
        this.router.navigate(['myaccount', 'deposit']);
        this.freeBetService.forceRefreshFreeBetCoupon().pipe(delay(500)).subscribe();
      } else if (
        this.isConnected &&
        hasFlag(x.state, CustomerState.LoginValidated) &&
        this.customerOperatorConfiguration.knowYourCustomerConfiguration?.customerAccessLimitationConfiguration
          ?.blockDeposit
      ) {
        this.router.navigate(['myaccount', 'informations']);
        this.freeBetService.forceRefreshFreeBetCoupon().pipe(delay(500)).subscribe();
      }
      this.cdRef.markForCheck();
    });

    if (this.i18nService.translationKeyExistsSync('REGISTRATION.EXTRA_INFOS')) {
      this.extraInfos$ = this.i18nService.translate('REGISTRATION.EXTRA_INFOS');
    }
  }

  ngOnDestroy(): void {
    super.ngOnDestroy();
  }

  validationCodeVerification(code: string) {
    this.validationCode = code;
    this.validate();
  }

  validate() {
    if (this.loadingValidate) {
      return;
    }

    this.accept = true;
    this.loadingValidate = true;
    this.resetValidationCodeError = false;
    this.errorOccured = false;

    this.customerService
      .validate(this.validationCode)
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.loadingValidate = false;
          this.cdRef.markForCheck();
        })
      )
      .subscribe(
        () => {
          this.authService
            .getMe()
            .pipe(takeUntil(this.destroy$))
            .subscribe(_ => {
              if (this.profilePolicyRequirements) {
                this.accountService.clickRegisterStep(3);
              } else {
                this.accountService.clickRegisterStep(2);
              }

              if (
                this.isValidated &&
                !this.customerOperatorConfiguration.knowYourCustomerConfiguration?.customerAccessLimitationConfiguration
                  ?.blockDeposit
              ) {
                this.router.navigate(['myaccount', 'deposit']);
              } else if (
                this.isValidated &&
                this.customerOperatorConfiguration.knowYourCustomerConfiguration?.customerAccessLimitationConfiguration
                  ?.blockDeposit
              ) {
                this.router.navigate(['myaccount', 'informations']);
              }
              this.messageService.sendHeaderMessage('KYC', null);
            });
        },
        () => {
          this.errorOccured = true;
        }
      );
  }
}
