import { ChangeDetectionStrategy, Input, Component, OnChanges } from '@angular/core';

@Component({
  selector: 'hg-event-categories',
  templateUrl: './event-categories.component.html',
  styleUrls: ['./event-categories.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class EventCategoriesComponent implements OnChanges {
  @Input() categories: string[] = [];
  @Input() showOnlyLast: boolean = false;
  @Input() displayLiveIcon: boolean = false;

  internalCategories: string[] = [];

  ngOnChanges() {
    this.internalCategories = this.categories;

    if (this.showOnlyLast) {
      this.internalCategories = [this.internalCategories[0]];
    }
  }
}
