import { Component, ChangeDetectionStrategy, Input, EventEmitter, Output, Inject, OnChanges } from '@angular/core';
import { take } from 'rxjs/operators';
import { CreateBetCodeRequest } from '@honoregaming/betslip';
import { operatorConfigurationToken, OperatorConfiguration } from '@honoregaming/configuration';
import { happenBefore, getUtcNow, DestroySubject, BroadcastingService, add } from '@honoregaming/core';
import { I18nService } from '@honoregaming/i18n';
import {
  BetState,
  BetSystemHistory,
  BetCategoryType,
  BetLineStateType,
  BetLineHistory,
  DrawGameMessage,
  DrawGameReplayRequest
} from '@honoregaming/types';
import { ToasterService } from '@honoregaming/ui';

@Component({
  selector: 'hg-draw-game-bet-system',
  templateUrl: './draw-game-bet-system.component.html',
  styleUrls: ['draw-game-bet-system.component.scss', '../generic-bet-system.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class DrawGameBetSystemComponent extends DestroySubject implements OnChanges {
  @Input() betSystem!: BetSystemHistory;
  @Input() hideSection?: boolean;
  @Input() canRebet?: boolean;
  @Input() shouldDisplayBetCodeButton?: boolean;
  @Input() isGettingBetCode?: boolean;

  @Input()
  authorizedToReplay: boolean = false;
  @Output() getBetCode = new EventEmitter<{ betCodeRequest: CreateBetCodeRequest; totalOdds: string }>();
  @Output() rebet = new EventEmitter<BetSystemHistory>();

  BetState = BetState;
  BetCategoryType = BetCategoryType;
  canReplay: boolean = false;

  public displayRebet: boolean = false;
  public allBetLinesArePending: boolean = false;

  constructor(
    private readonly toasterService: ToasterService,
    private readonly i18n: I18nService,
    @Inject(operatorConfigurationToken) private readonly operatorConfiguration: OperatorConfiguration,
    private broadcastingService: BroadcastingService
  ) {
    super();
  }

  ngOnChanges(): void {
    this.allBetLinesArePending = this.betSystem?.betLines?.every(bl => bl.state === BetLineStateType.Pending);

    this.displayRebet =
      this.canRebet &&
      this.operatorConfiguration.operatorFeatures.indexOf('Rebet') !== -1 &&
      this.betSystem.betCategory === BetCategoryType.DrawGame &&
      this.betSystem.betLines?.some(
        (betLine: BetLineHistory) =>
          betLine.state === BetLineStateType.Pending &&
          !happenBefore(getUtcNow(), new Date(betLine.eventDate), 0) &&
          betLine.betTypeId !== 40043
      );
  }

  public onGetBetCode(betSystemId: number): void {
    const drawGameSelections = this.betSystem?.betLines?.map(bl => ({
      eventBetTypeId: bl.eventBetTypeId,
      stakeMultiplier: bl.stakeMultiplier ?? 1,
      baseList: (bl.baseList ?? []).map(n => n.toString()),
      extraList: (bl.extraList ?? []).map(n => n.toString()),
      quickPick: bl.quickPick ?? false,
      associatedDrawGamesIds: bl.associatedDrawGamesIds ?? [],
      option: bl.option
    }));

    const totalMultipliers =
      (this.betSystem?.betLines ?? []).reduce((acc, bl) => acc + (bl.stakeMultiplier ?? 1), 0) || 1;
    const totalStake = this.betSystem?.totalStake ?? null;
    const bettingTaxAmount = this.betSystem.bettingTaxAmount ?? null;
    const stakePerLine =
      totalStake != null
        ? (this.betSystem?.betLines ?? []).map(
            bl => ((totalStake + bettingTaxAmount) * (bl.stakeMultiplier ?? 1)) / totalMultipliers
          )
        : undefined;

    this.getBetCode.emit({
      betCodeRequest: {
        betSystemId: betSystemId,
        betSystemType: this.betSystem.type,
        betCategory: this.betSystem.betCategory,
        drawGameSelections,
        totalStake: add(totalStake, bettingTaxAmount),
        stakePerLine
      },
      totalOdds: null
    });
  }

  public onRebet(): void {
    this.rebet.emit(this.betSystem);
  }

  contentCopied(): void {
    this.i18n
      .translate('ACCOUNT.COPIED.REFERENCE')
      .pipe(take(1))
      .subscribe(translation => this.toasterService.show(translation));
  }

  replay() {
    this.broadcastingService.broadcast<DrawGameReplayRequest>(DrawGameMessage.DrawGameReplayRequest, {
      authorized: this.authorizedToReplay,
      betSystem: this.betSystem,
      navigateUrl: '/draw-games'
    });
  }
}
