import {
  Component,
  ChangeDetectionStrategy,
  OnInit,
  ChangeDetectorRef,
  ViewChild,
  ElementRef,
  Inject
} from '@angular/core';
import { AccountService } from '../../services/account.service';
import { Provider } from '../../models/provider.model';
import { PaymentProviderStatus } from '../../models/provider.model';
import { DestroySubject, BroadcastingService, getUtcNow } from '@honoregaming/core';
import { takeUntil, filter, finalize, take } from 'rxjs/operators';
import { Router, NavigationStart, ActivatedRoute } from '@angular/router';
import { combineLatest, of } from 'rxjs';
import { AuthService, TelemetryService } from '@honoregaming/customer-core';
import { ResponsibleGamblingService } from '../../services/responsible-gambling.service';
import { CustomerGameAccountLimitationScope } from '@honoregaming/types';
import { Feature, OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';
import { I18nService } from '@honoregaming/i18n';

@Component({
  selector: 'hg-deposit-list',
  templateUrl: './deposit-list.component.html',
  styleUrls: ['./deposit-list.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class DepositListComponent extends DestroySubject implements OnInit {
  providersList: Provider[];
  currentProvider: Provider;
  providerStatus = PaymentProviderStatus;
  depositStateActive: boolean;
  uniqueProvider = false;
  loading = true;
  @ViewChild('header', { static: true, read: ElementRef })
  top: ElementRef;
  depositsNotAllowed: boolean;
  canDeposit = true;
  depositSelectionDetailsText: string;
  showMinimumAmountsInDeposits: boolean = this.operatorConfiguration.onlineConfiguration?.showMinimumAmountsInDeposits;
  showMaximumAmountsInDeposits: boolean = this.operatorConfiguration.onlineConfiguration?.showMaximumAmountsInDeposits;

  constructor(
    private activatedRoute: ActivatedRoute,
    private router: Router,
    private accountService: AccountService,
    private cdRef: ChangeDetectorRef,
    private bcService: BroadcastingService,
    private authService: AuthService,
    private responsibleGamblingService: ResponsibleGamblingService,
    @Inject(operatorConfigurationToken) private operatorConfiguration: OperatorConfiguration,
    private i18nService: I18nService,
    private telemetryService: TelemetryService
  ) {
    super();
  }

  ngOnInit() {
    if (this.i18nService.translationKeyExistsSync('ACCOUNT.DEPOSIT.SELECTION.DETAILS_TEXT')) {
      this.i18nService.translate('ACCOUNT.DEPOSIT.SELECTION.DETAILS_TEXT').subscribe(text => {
        this.depositSelectionDetailsText = text;
      });
    }

    let responsibleGamblingObservable =
      this.operatorConfiguration.operatorFeatures?.indexOf(Feature.ResponsibleGambling) > -1
        ? this.responsibleGamblingService.getLimitations()
        : of([]);

    this.router.events
      .pipe(
        filter(event => {
          return event instanceof NavigationStart;
        })
      )
      .subscribe((event: NavigationStart) => {
        if (event.restoredState) {
          this.currentProvider = null;
        }
      });

    combineLatest([
      responsibleGamblingObservable,
      this.authService.me$,
      this.accountService.getPaymentProviders(),
      this.accountService.getGlobalDepositState()
    ])
      .pipe(
        take(1),
        takeUntil(this.destroy$),
        finalize(() => {
          this.loading = false;
          this.cdRef.markForCheck();
        })
      )
      .subscribe(([limitations, me, providersResponse, depositStateActive]) => {
        if (this.operatorConfiguration.operatorFeatures?.indexOf(Feature.ResponsibleGambling) > -1) {
          const isExcluded = me.selfExclusionEndDate ? new Date(me.selfExclusionEndDate) > getUtcNow() : false;
          const depositLimitReached =
            me.responsibleGamblingDeposit ===
            limitations?.find(x => x.scope === CustomerGameAccountLimitationScope.Deposit)?.amount;

          this.canDeposit = !isExcluded && !depositLimitReached && me.depositsAllowed;
        }

        if (this.canDeposit) {
          this.depositStateActive = depositStateActive;
          this.providersList = providersResponse.providers.filter(
            e => e.depositStatus !== PaymentProviderStatus.Disabled
          );

          if (this.providersList.length === 1 && this.providersList[0].depositStatus === PaymentProviderStatus.Online) {
            this.uniqueProvider = true;
            this.router.navigate([this.providersList[0].providerName.toLowerCase()], {
              relativeTo: this.activatedRoute
            });
          }
        } else {
          this.depositsNotAllowed = true;
        }
      });

    this.bcService
      .register('payment-provider-scroll-to-top')
      .pipe(takeUntil(this.destroy$))
      .subscribe(() => this.top.nativeElement.scrollIntoView(true));
  }

  trackDepositProviderClicked(provider: Provider) {
    this.telemetryService.trackEvent('deposit_provider_select', {
      provider_name: provider.displayName ?? provider.providerName
    });
  }
}
