import {
  Component,
  OnInit,
  ChangeDetectionStrategy,
  Inject,
  ViewChild,
  Input,
  Output,
  EventEmitter,
  ChangeDetectorRef
} from '@angular/core';
import { DrawGameBetSlipService } from '@honoregaming/betslip';
import { BroadcastingService, DestroySubject, Scope, scopeToken } from '@honoregaming/core';
import {
  BorletteSelectionComponent,
  BorletteSelectionToBetslip,
  DrawGamesService,
  RecommendedNumbersSelectionToolComponent,
  RecommendedNumbersSelectionToolProperties,
  SimpleNumbersSelectionToolComponent,
  SimpleNumbersSelectionToolProperties,
  TableNumbersSelectionToolComponent,
  TableNumbersSelectionToolProperties
} from '@honoregaming/draw-games-ui';
import { I18nService } from '@honoregaming/i18n';
import { DrawGame, DrawGameBorletteBetType } from '@honoregaming/types';
import { MessageService } from '@honoregaming/ui';
import { takeUntil } from 'rxjs/operators';

@Component({
  selector: 'hg-borlette-game-borlette',
  templateUrl: './borlette-game-borlette.component.html',
  styleUrls: ['./borlette-game-borlette.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class BorletteGameBorletteComponent extends DestroySubject implements OnInit {
  @ViewChild(BorletteSelectionComponent) selectionComponent!: BorletteSelectionComponent;
  @Input() drawGame!: DrawGame;
  @Input() defaultStake: number = 1;
  @Input() minimumAmount: number = 1;
  @Input() maximumAmount?: number = undefined;
  @Input() increment: number = 1;
  @Input() predefinedStakes: number[] = [];
  @Input() isQuickBet: boolean = false;
  @Input() displayPointe: boolean = false;
  @Input() displayRaleBoule: boolean = false;
  @Input() drawGames: DrawGame[] = [];
  @Output() addToBetSlipEmitted: EventEmitter<BorletteSelectionToBetslip> =
    new EventEmitter<BorletteSelectionToBetslip>();
  DrawGameBorletteBetType = DrawGameBorletteBetType;
  displayAutoBetButtons: boolean = false;
  autoBorletteNumbers: string[] = [];
  defaultSelectedDrawGamesIds: number[] = [];
  isRecommendedNumbersToolEnabled: boolean = false;

  constructor(
    @Inject(scopeToken) private userScope: Scope,
    private i18nService: I18nService,
    private drawGamesService: DrawGamesService,
    private messageService: MessageService,
    private drawGameBetSlipService: DrawGameBetSlipService,
    private cdRef: ChangeDetectorRef,
    private broadcastingService: BroadcastingService
  ) {
    super();
  }

  ngOnInit(): void {
    this.drawGameBetSlipService.$autoBorletteAvailabilityEvent.pipe(takeUntil(this.destroy$)).subscribe(event => {
      this.displayAutoBetButtons = this.userScope === Scope.Agent && event.availability;
      this.autoBorletteNumbers = event.numbers;
      this.cdRef.markForCheck();
    });

    this.defaultSelectedDrawGamesIds = this.drawGame != null ? [this.drawGame.id] : [];
    this.isRecommendedNumbersToolEnabled = this.drawGame != null;
  }

  openBoulePe(): void {
    this.displayTool(SimpleNumbersSelectionToolComponent, {
      title: this.i18nService.translateSync('DRAW_GAMES.BORLETTE.LABEL.TWIN_NUMBERS'),
      numbers: this.drawGamesService.getBorletteTwinNumbers(),
      disabledNumbers: this.selectionComponent
        .getSelectedNumbers()
        .map(x => x[0])
        .filter(x => x.length > 0),
      showSelectAll: true
    });
  }

  openPointe(): void {
    this.displayTool(TableNumbersSelectionToolComponent, {
      title: this.i18nService.translateSync('DRAW_GAMES.BORLETTE.LABEL.POINTE'),
      numbers: this.drawGamesService.getBorlettePointeNumbers(),
      disabledNumbers: this.selectionComponent
        .getSelectedNumbers()
        .map(x => x[0])
        .filter(x => x.length > 0),
      showSelectAll: false,
      keyColumnName: this.i18nService.translateSync('DRAW_GAMES.BORLETTE.LABEL.POINTE'),
      displaySearch: false,
      homogeneousColumnWidth: false,
      searchPlaceholder: ''
    });
  }

  openTchala(): void {
    this.displayTool(TableNumbersSelectionToolComponent, {
      title: this.i18nService.translateSync('DRAW_GAMES.BORLETTE.LABEL.TCHALA'),
      numbers: this.drawGamesService.getBorletteTchalaNumbers(),
      disabledNumbers: this.selectionComponent
        .getSelectedNumbers()
        .map(x => x[0])
        .filter(x => x.length > 0),
      showSelectAll: false,
      keyColumnName: this.i18nService.translateSync('DRAW_GAMES.BORLETTE.LABEL.REV'),
      displaySearch: true,
      homogeneousColumnWidth: true,
      searchPlaceholder: this.i18nService.translateSync('TCHALA.SEARCH')
    });
  }

  openRaleBoule(): void {
    this.displayTool(RecommendedNumbersSelectionToolComponent, {
      title: this.i18nService.translateSync('DRAW_GAMES.LABEL.RECOMMENDEDNUMBERS'),
      searchPlaceholder: this.i18nService.translateSync('DRAW_GAMES.LABEL.ENTERNUMBER'),
      defaultSearchNumber: +this.selectionComponent
        .getSelectedNumbers()
        .map(x => x[0])
        .filter(x => x.length > 0)
        .slice(-1)[0],
      disabledNumbers: this.selectionComponent
        .getSelectedNumbers()
        .map(x => x[0])
        .filter(x => x.length > 0),
      showSelectAll: true,
      betTypeId: DrawGameBorletteBetType.Borlette,
      drawGameRuleIds:
        this.selectionComponent?.selectedDrawGamesIds?.map(
          x => this.drawGames.find(game => game.id === x).drawGameRule.id
        ) ?? [],
      recommendedNumbersCount: 4,
      formatNumber: (number: string) => this.i18nService.formatIntegerNumber(number, 2)
    });
  }

  displayTool(
    component: any,
    properties:
      | SimpleNumbersSelectionToolProperties
      | TableNumbersSelectionToolProperties
      | RecommendedNumbersSelectionToolProperties
  ): void {
    this.messageService
      .sendComponentMessage(component, properties, {
        canBeDismissed: true,
        displayClose: true,
        className: 'draw-game-tool'
      })
      .closed.pipe(takeUntil(this.destroy$))
      .subscribe((numbers: number[] | undefined) => {
        if (numbers) {
          this.selectionComponent.addSelections(numbers.map(x => [x]));
        }
      });
  }

  broadcastOpenModalBorlette(type: string) {
    this.broadcastingService.broadcast('BorletteModal', { type: type, numbers: this.autoBorletteNumbers });
  }

  selectionChanged(): void {
    if (this.selectionComponent) {
      this.isRecommendedNumbersToolEnabled = this.selectionComponent.selectedDrawGamesIds.length > 0;
    }
  }
}
