import { ChangeDetectionStrategy, Component, Input, OnChanges, SimpleChanges } from '@angular/core';
import { Template } from '@honoregaming/types';
import { isInternalLink } from '../../helper';

@Component({
  selector: 'hg-slider-image',
  templateUrl: './slider-image.component.html',
  styleUrls: ['./slider-image.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class SliderImageComponent implements OnChanges {
  @Input() slide!: Template;
  @Input() device!: 'desktop' | 'mobile';

  target: string = '_self';

  ngOnChanges({ slide }: SimpleChanges): void {
    if (slide && this.slide.link) {
      this.target = isInternalLink(this.slide.link) ? '_self' : '_blank';
    }
  }
}
