import { Referee, ReferralHistory } from './../../models/referral-history.model';
import { ReferralDetails } from '../../models/referral-details.model';
import { Component, ChangeDetectionStrategy, OnInit, ChangeDetectorRef, Inject } from '@angular/core';
import { AccountService } from '../../services/account.service';
import { operatorConfigurationToken, OperatorConfiguration } from '@honoregaming/configuration';
import { takeUntil, finalize, take } from 'rxjs/operators';
import { DestroySubject } from '@honoregaming/core';
import { MessageService } from '@honoregaming/ui';
import { ShareCodeComponent } from '@honoregaming/customer-ui';
import { I18nService } from '@honoregaming/i18n';
import { combineLatest, forkJoin } from 'rxjs';
import { AuthService, CodeType, CustomerService, CustomerSuperReferrerState, Me } from '@honoregaming/customer-core';
import { SortDirection } from 'projects/core/hg-ui/src/lib/enum/sort-direction.enum';

@Component({
  selector: 'hg-referral',
  templateUrl: './referral.component.html',
  styleUrls: ['./referral.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class ReferralComponent extends DestroySubject implements OnInit {
  loading = false;
  error = false;
  skip = 0;
  take = 5;
  hasMore: boolean;
  referralHistory: ReferralHistory[] = [];
  referralDetails: ReferralDetails;
  minRefereesNumber = this.operatorConfiguration.global.minRefereesNumber;

  me: Me;
  CustomerSuperReferrerState = CustomerSuperReferrerState;
  sortField: string;
  sortDirection: SortDirection;
  referees: Referee[] = [];
  profileRequired: boolean;
  searchTerm: string;
  superReferrerHistoryLoading: boolean;

  displayCopyToast: boolean = false;

  constructor(
    private accountService: AccountService,
    private cdRef: ChangeDetectorRef,
    private messageService: MessageService,
    private i18nService: I18nService,
    @Inject(operatorConfigurationToken) private operatorConfiguration: OperatorConfiguration,
    private customerService: CustomerService,
    private authService: AuthService
  ) {
    super();
  }

  ngOnInit() {
    this.loading = true;
    this.superReferrerHistoryLoading = true;

    this.customerService.getSecurityPolicy().subscribe(x => {
      this.profileRequired = x?.profilePolicyRequirements?.required;
    });

    this.authService.me$.pipe(takeUntil(this.destroy$)).subscribe(me => {
      this.me = me;
      this.cdRef.markForCheck();
    });

    const referralDetails = this.accountService.getReferralDetails();
    const referrerHistory = this.accountService.getReferralHistory();
    const superReferrerHistory = this.accountService.getSuperReferrerHistory(this.skip, this.take, this.searchTerm);

    forkJoin([referralDetails, referrerHistory, superReferrerHistory])
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.loading = false;
          this.superReferrerHistoryLoading = false;
          this.cdRef.markForCheck();
        })
      )
      .subscribe(
        ([details, history, referees]) => {
          this.referralDetails = details;
          this.referralHistory = history;
          this.referees = referees.referees;
          this.hasMore = this.referees.length < referees.count;
        },
        _ => {
          this.error = true;
        }
      );
  }

  loadReferees(skip: number, take: number) {
    if (this.referralDetails?.directRefereesCount <= this.referees?.length) {
      return;
    }

    this.superReferrerHistoryLoading = true;
    this.accountService
      .getSuperReferrerHistory(skip, take, this.searchTerm, this.sortField, this.sortDirection)
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.superReferrerHistoryLoading = false;
          this.cdRef.markForCheck();
        })
      )
      .subscribe(history => {
        this.skip += 5;
        this.referees = this.referees.concat(history.referees);
        this.hasMore = this.referees.length < history.count;
      });
  }

  filterReferees() {
    this.resetSearch();
    this.loadReferees(this.skip, this.take);
  }

  openShareMessage() {
    const codeNameObservable = this.i18nService.translate('REFERRAL.REFERRAL_CODE');

    const shareMessageObservable = this.i18nService.translate(
      this.operatorConfiguration.global.freeBetRefereeBonusAmount > 0
        ? 'REFERRAL.SHARE_MESSAGE_TEMPLATE'
        : 'REFERRAL.SHARE_MESSAGE_WITHOUT_BONUS_TEMPLATE',
      this.operatorConfiguration.name,
      this.referralDetails.referralCode
    );

    combineLatest([codeNameObservable, shareMessageObservable])
      .pipe(take(1))
      .subscribe(([codeName, shareMessage]) => {
        this.messageService.sendComponentMessage(ShareCodeComponent, {
          code: this.referralDetails.referralCode,
          codeName: codeName,
          codeType: CodeType.Referral,
          shareMessageTemplate: shareMessage + ' 🏆'
        });
      });
  }

  displayCopyConfirmation() {
    this.displayCopyToast = true;
    this.cdRef.markForCheck();

    setTimeout(() => {
      this.displayCopyToast = false;
      this.cdRef.markForCheck();
    }, 3000);
  }

  resetSearch() {
    this.skip = 0;
    this.take = 5;
    this.referees = [];
  }

  sort(event: any) {
    this.resetSearch();
    this.sortField = event.column;
    this.sortDirection = event?.direction;
    this.loadReferees(this.skip, this.take);
  }
}
