import { HttpClient } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { globalConfiguration } from '@honoregaming/configuration';

@Injectable({
  providedIn: 'root'
})
export class ComplianceService {
  constructor(private httpClient: HttpClient) {}

  sendAccountClosingVerificationCode() {
    return this.httpClient.post(`${globalConfiguration.apiBaseUrl}compliance/closing-account-code`, {});
  }

  selfCloseAccount(validationCode: string) {
    return this.httpClient.post(`${globalConfiguration.apiBaseUrl}compliance/close-account`, { validationCode });
  }
}
