import { Component, ChangeDetectionStrategy, Output, EventEmitter, Input } from '@angular/core';

@Component({
  selector: 'hg-warning-data',
  templateUrl: './warning-data.component.html',
  styleUrls: ['./warning-data.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class WarningDataComponent {
  @Output()
  close = new EventEmitter<boolean>();

  @Input() title: string = 'COMMON.WARNING';
  @Input()
  messageKey: string;
}
