import { ITelemetryService } from './telemetry-service.model';
import { Injectable, Inject, PLATFORM_ID } from '@angular/core';
import { isPlatformBrowser } from '@angular/common';
import { take, tap } from 'rxjs/operators';
import { CustomerOperatorConfiguration, customerOperatorConfigurationToken } from '../../models';
import { AuthService } from '../auth.service';
import { BetCategoryType } from '@honoregaming/types';

declare var window: any;
declare var srtmCommands: any;

@Injectable()
export class SportRadarTelemetryService implements ITelemetryService {
  isBrowser = isPlatformBrowser(this.platformId);
  configuration = this.operatorConfig.telemetryConfiguration.sportRadar;

  constructor(
    @Inject(customerOperatorConfigurationToken) private operatorConfig: CustomerOperatorConfiguration,
    private authService: AuthService,
    @Inject(PLATFORM_ID) private platformId
  ) {
    if (this.isBrowser) {
      window['srtmCommands'] = window['srtmCommands'] || [];

      const script = document.createElement('script');
      script.src = 'https://tm.ads.sportradar.com/dist/tag-manager.js?id=' + this.configuration.clientId;
      script.setAttribute('data-srtmn', 'srtmCommands');

      let parent = document.getElementsByTagName('script')[0];
      parent.parentNode.insertBefore(script, parent);
    }
  }

  trackPageView(_name: string, _path: string): void {}

  trackEvent(name: string, properties: any): void {
    if (this.isBrowser) {
      this.authService.me$
        .pipe(
          take(1),
          tap(me => {
            if (me) {
              switch (name) {
                case 'sign_up_complete': {
                  srtmCommands.push({
                    event: 'track.user.registration',
                    payload: { action: 'complete', userId: me.id }
                  });
                  break;
                }

                case 'login': {
                  srtmCommands.push({
                    event: 'track.user.login',
                    payload: { action: 'complete', userId: me.id }
                  });
                  break;
                }

                case 'firstTimeDeposit': {
                  srtmCommands.push({
                    event: 'track.betting.deposit',
                    payload: {
                      action: 'created',
                      label: 'first_deposit',
                      userId: me.id,
                      transactionId: properties.id,
                      amount: properties.amount,
                      currency: this.operatorConfig.currency.symbol
                    }
                  });
                  break;
                }

                case 'deposit': {
                  srtmCommands.push({
                    event: 'track.betting.deposit',
                    payload: {
                      action: 'created',
                      userId: me.id,
                      transactionId: properties.id,
                      amount: properties.amount,
                      currency: this.operatorConfig.currency.symbol
                    }
                  });
                  break;
                }

                case 'bet_placed': {
                  if (properties.bet && properties.betCategory === BetCategoryType.SportsFixedOdds) {
                    const contentIds = [];

                    if (properties.bet.betLines?.length) {
                      properties.bet.betLines.forEach(bl => {
                        if (bl.manualOddsBoost) {
                          contentIds.push(bl.manualOddsBoost.eventId);
                        } else if (bl.eventId) {
                          contentIds.push(bl.eventId);
                        }
                      });
                    }

                    srtmCommands.push({
                      event: 'track.betting.betPlaced',
                      payload: {
                        userId: me.id,
                        transactionId: properties.bet.betResponse.betSystemsIds?.length
                          ? properties.bet.betResponse.betSystemsIds[0]
                          : '',
                        amount:
                          properties.bet.amounts.summary.totalStakeWithTax || properties.bet.amounts.summary.totalStake,
                        currency: this.operatorConfig.currency.symbol,
                        contentIds: contentIds
                      }
                    });
                  }
                  break;
                }
              }
            }

            switch (name) {
              case 'sign_up_started': {
                srtmCommands.push({
                  event: 'track.user.registration',
                  payload: { action: 'start' }
                });
                break;
              }

              case 'event_view': {
                srtmCommands.push({
                  event: 'srt.retargeting',
                  payload: {
                    sportsEvent: {
                      match_id: properties.matchId,
                      team_home_name: properties.homeTeamName,
                      team_away_name: properties.awayTeamName,
                      scheduled: properties.expectedStart,
                      tournament_name: properties.tournament,
                      sport: properties.sport,
                      odds_home: properties.homeTeamOdds,
                      odds_draw: properties.drawOdds,
                      odds_away: properties.awayTeamOdds,
                      language: properties.language
                    }
                  }
                });
                break;
              }

              case 'add_event_to_betslip': {
                srtmCommands.push({
                  event: 'srt.betslip',
                  payload: {
                    sportsEvent: {
                      match_id: properties.matchId,
                      team_home_name: properties.homeTeamName,
                      team_away_name: properties.awayTeamName,
                      scheduled: properties.expectedStart,
                      tournament_name: properties.tournament,
                      sport: properties.sport,
                      odds_home: properties.homeTeamOdds,
                      odds_draw: properties.drawOdds,
                      odds_away: properties.awayTeamOdds,
                      language: properties.language
                    }
                  }
                });
                break;
              }
            }
          })
        )
        .subscribe();
    }
  }
}
