import { HttpClient, HttpHeaders } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { globalConfiguration, appConfiguration } from '@honoregaming/configuration';
import { CookieStorageService } from '@honoregaming/core';
import { Observable, of } from 'rxjs';
import { TrackingEvent } from '../models/tracking-event.model';
import { SESSION_IDENTIFIER } from '../models/constants';

@Injectable({ providedIn: 'root' })
export class TrackingService {
  constructor(private httpClient: HttpClient, private storageService: CookieStorageService) {}

  trackEvent(trackingEvent: TrackingEvent): Observable<{}> {
    const sessionIdentifier = this.storageService.getItem(SESSION_IDENTIFIER);
    if (!!sessionIdentifier) {
      let header = new HttpHeaders();
      header = header.set(SESSION_IDENTIFIER, sessionIdentifier);

      if (!trackingEvent.properties) {
        trackingEvent.properties = {};
      }

      // Always send the flavor to the tracking service
      trackingEvent.properties.Flavor = appConfiguration.flavor || '';

      return this.httpClient.post<{}>(`${globalConfiguration.apiBaseUrl}tracking`, trackingEvent, {
        headers: header
      });
    }

    return of({});
  }
}
