import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';
import { map, mergeMap } from 'rxjs/operators';
import { EventCategory, BetType, PreEventOrLiveType, EventCategoryWithStreamConfiguration } from '@honoregaming/types';
import { globalConfiguration } from '@honoregaming/configuration';
import { I18nService } from '@honoregaming/i18n';
import { CacheableVaryByKey, Cacheable, buildQueryString } from '@honoregaming/core';

@Injectable({ providedIn: 'root' })
export class EventCategoriesService {
  @CacheableVaryByKey() userLanguage?: string;

  constructor(private readonly httpClient: HttpClient, private readonly i18nService: I18nService) {
    this.i18nService.languageChanged$.subscribe(language => (this.userLanguage = language));
  }

  @Cacheable()
  getEntryPoints(): Observable<EventCategory[]> {
    return this.httpClient.get<EventCategory[]>(
      `${globalConfiguration.apiEventsBaseUrl}eventcategories/entrypoints?${this.userLanguage}`
    );
  }

  getEntryPointsForRootEventCategories(eventCategoryIds: number[]): Observable<EventCategory[]> {
    return this.getEntryPoints().pipe(
      map(categs => categs.filter(categ => eventCategoryIds.includes(categ.parentEventCategoryId)))
    );
  }

  getEntryPointsByIds(entryPointIds: number[]): Observable<EventCategory[]> {
    return this.getEntryPoints().pipe(map(categs => categs.filter(categ => entryPointIds.includes(categ.id))));
  }

  @Cacheable()
  getCategoriesForEntryPoint(entryPointId: number): Observable<EventCategory[]> {
    return this.httpClient.get<EventCategory[]>(
      `${globalConfiguration.apiEventsBaseUrl}eventcategories/${entryPointId}?${this.userLanguage}`
    );
  }

  @Cacheable()
  getFavoriteCategories(): Observable<any> {
    return this.httpClient.get<EventCategory[]>(
      `${globalConfiguration.apiEventsBaseUrl}eventcategories/sports/favorites?${this.userLanguage}`
    );
  }

  @Cacheable()
  getEventCategory(eventCategory: number): Observable<EventCategoryWithStreamConfiguration> {
    return this.httpClient.get<EventCategoryWithStreamConfiguration>(
      `${globalConfiguration.apiEventsBaseUrl}eventcategories/${eventCategory}/details`
    );
  }

  @Cacheable()
  getEventCategoryBetTypes(
    eventCategory: number,
    take?: number,
    preEventOrLive?: PreEventOrLiveType
  ): Observable<BetType[]> {
    return this.httpClient.get<BetType[]>(
      `${globalConfiguration.apiEventsBaseUrl}eventcategories/${eventCategory}/bettypes${buildQueryString({
        take,
        preEventOrLive,
        l: this.userLanguage
      })}`
    );
  }

  getEventCategoryName(entrypointId: number, ...eventCategories: number[]): Observable<string> {
    return this.getCategoriesForEntryPoint(entrypointId).pipe(
      map(categories => {
        const path = [...eventCategories];
        let currentCategId = path.shift();
        let currentBranch = categories.find(x => x.id === currentCategId);
        while ((currentCategId = path.shift())) {
          currentBranch = currentBranch.subCategories.find(x => x.id === currentCategId);
        }
        return currentBranch.name;
      })
    );
  }

  getEventCategories(entryPointId: number, ...eventCategories: number[]): Observable<EventCategory[]> {
    return this.getEntryPoints().pipe(
      mergeMap(entryPoints => {
        const targetEntryPoint = entryPoints.find(e => e.id === entryPointId);
        if (targetEntryPoint) {
          return this.getCategoriesForEntryPoint(entryPointId)
            .pipe(
              map(categories => {
                const ec: EventCategory[] = [];
                let currentEventCategory: EventCategory;

                eventCategories.forEach(id => {
                  const targetEventCategory = (currentEventCategory?.subCategories ?? categories).find(
                    c => c.id === id
                  );

                  if (targetEventCategory) {
                    currentEventCategory = targetEventCategory;
                    ec.push(targetEventCategory);
                  }
                });

                return ec;
              })
            )
            .pipe(map(e => [targetEntryPoint, ...e]));
        }

        return [];
      })
    );
  }
}
