import {
  Component,
  ChangeDetectionStrategy,
  OnInit,
  Input,
  Output,
  EventEmitter,
  ChangeDetectorRef
} from '@angular/core';
import { NumbersSelectionToolBase } from '../base/numbers-selection-tool-base';
import { NumberItem } from '../base/model/number-item';
import { TableNumbersItem } from '../base/model/table-numbers-item';
import { TableNumbersInput } from '../base/model/table-numbers-input';
import { Observable } from 'rxjs';
import { finalize, takeUntil } from 'rxjs/operators';

@Component({
  selector: 'hg-table-numbers-selection-tool',
  templateUrl: './table-numbers-selection-tool.component.html',
  styleUrls: ['./table-numbers-selection-tool.component.scss', '../base/numbers-selection-tool.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class TableNumbersSelectionToolComponent extends NumbersSelectionToolBase implements OnInit {
  @Input() title: string;
  @Input() numbers: Observable<TableNumbersInput[]>;
  @Input() disabledNumbers?: string[];
  @Input() showSelectAll: boolean = false;
  @Input() keyColumnName: string;
  @Input() displaySearch: boolean = false;
  @Input() homogeneousColumnWidth: boolean = false;
  @Input() searchPlaceholder: string;
  @Output() close: EventEmitter<string[]> = new EventEmitter<string[]>();

  loading: boolean = false;
  numberItems: NumberItem[] = [];
  fullTableData: TableNumbersItem[] = [];
  tableData: TableNumbersItem[] = [];
  searchText: string;

  constructor(private cdRef: ChangeDetectorRef) {
    super();
  }

  ngOnInit(): void {
    this.loading = true;
    this.numbers
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => (this.loading = false))
      )
      .subscribe(x => {
        for (let input of x) {
          const item: TableNumbersItem = { key: input.key, numbers: [], allSelected: false };
          for (let number of input.numbers) {
            let numberItem = this.numberItems.find(x => x.number === number);
            if (!numberItem) {
              numberItem = {
                number: number,
                selected: false,
                disabled: this.disabledNumbers?.includes(number) ?? false
              };

              this.numberItems.push(numberItem);
            }

            item.numbers.push(numberItem);
          }

          this.fullTableData.push(item);
        }

        this.tableData = this.fullTableData;
        this.cdRef.markForCheck();
      });
  }

  selectItem(item: NumberItem): void {
    super.selectItem(item);
    this.checkAllSelected();
  }

  selectAllInItem(item: TableNumbersItem): void {
    const selection = item.numbers.some(x => !x.disabled && !x.selected);
    for (let number of item.numbers) {
      if (!number.disabled) {
        number.selected = selection;
      }
    }

    this.checkAllSelected();
  }

  checkAllSelected(): void {
    for (let item of this.tableData) {
      item.allSelected = !item.numbers.some(x => !x.disabled && !x.selected);
    }

    this.numberItems = [...this.numberItems];
  }

  onSearchTextChange(value: string): void {
    const searchTextLowerCase = this.searchText.toLowerCase();
    if (value) {
      this.tableData = this.fullTableData.filter(x => x.key.toLowerCase().includes(searchTextLowerCase));
    } else {
      this.tableData = this.fullTableData;
    }
  }
}
