import { DestroySubject } from '@honoregaming/core';
import { BehaviorSubject, Subject } from 'rxjs';
import { Injectable } from '@angular/core';
@Injectable({
  providedIn: 'root'
})
export class MobileNavService extends DestroySubject {
  private displayHeaderMyBets = new BehaviorSubject<boolean>(false);
  displayHeaderMyBets$ = this.displayHeaderMyBets.asObservable();
  private burgerMenuSubject = new Subject<boolean>();
  burgerMenu = this.burgerMenuSubject.asObservable();
  private jumpInBurgerMenuSubject = new Subject<string>();
  jumpInBurgerMenu = this.jumpInBurgerMenuSubject.asObservable();
  private tutorialUpdateSubject = new Subject<number>();
  tutorialUpdate = this.tutorialUpdateSubject.asObservable();

  updateDisplayHeaderMyBets(value: boolean) {
    this.displayHeaderMyBets.next(value);
  }

  clickOnBurgerMenu(state: boolean, type?: string) {
    this.burgerMenuSubject.next(state);
    if (type) {
      this.jumpInBurgerMenuSubject.next(type);
    }
  }

  updateStepTutorial(step: number) {
    this.tutorialUpdateSubject.next(step);
  }
}
