import { Inject, Injectable, Optional, PLATFORM_ID } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { globalConfiguration, OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';
import { LocalStorageService } from '@honoregaming/core';
import { QueryBuilderService } from 'projects/core/hg-core/src/lib/services/query-builder.service';
import { Media, MediaService, MessageService } from '@honoregaming/ui';
import { DateTime } from 'luxon';
import { TemplatePopinComponent } from './popins/template/template-popin.component';
import { isPlatformServer } from '@angular/common';
import { CustomerPopupTemplate } from '@honoregaming/types';
import { CustomerPopupLocation } from 'projects/core/hg-types/models/enums/customer-popup-location.enum';

@Injectable({ providedIn: 'root' })
export class CustomerPopupService {
  constructor(
    private httpClient: HttpClient,
    private storageService: LocalStorageService,
    private messageService: MessageService,
    private builder: QueryBuilderService,
    @Inject(PLATFORM_ID) private plateform,
    @Inject(operatorConfigurationToken) private operatorConfiguration: OperatorConfiguration,
    @Optional() private mediaService: MediaService
  ) {}

  public displayPopup(customerPopupLocation: CustomerPopupLocation) {
    if (
      isPlatformServer(this.plateform) ||
      !customerPopupLocation ||
      this.operatorConfiguration.smarticoConfiguration?.popupsEnabled
    ) {
      return;
    }

    const cacheKey = `popup_${customerPopupLocation.toLowerCase()}`;
    let startDate = this.storageService.getItem(cacheKey);

    if (
      startDate &&
      DateTime.fromISO(new Date().toISOString()).diff(DateTime.fromISO(startDate), 'hours').hours >
        (this.operatorConfiguration?.onlineConfiguration?.popupDisplayDelay ?? 24)
    ) {
      startDate = null;
    }

    var params = this.builder.buildHttpParams({
      location: customerPopupLocation,
      startDate: startDate ? DateTime.fromISO(startDate) : null
    });

    this.httpClient
      .get<CustomerPopupTemplate>(`${globalConfiguration.apiBaseUrl}operatordata/customer-popup`, { params })
      .subscribe(t => {
        if (t && this.canDisplayPopup(t)) {
          this.storageService.setItem(cacheKey, new Date());
          this.messageService.sendComponentMessage(TemplatePopinComponent, { template: t }, { queue: true });
        }
      });
  }

  private canDisplayPopup(popup: CustomerPopupTemplate): boolean {
    if (popup.type === 'image-with-link' && this.mediaService !== null) {
      return this.mediaService.media < Media.md ? !!popup.inputs.mobileImage : !!popup.inputs.desktopImage;
    }
    return true;
  }
}
