import {
  Component,
  OnInit,
  ChangeDetectionStrategy,
  Input,
  HostBinding,
  ChangeDetectorRef,
  Output,
  EventEmitter
} from '@angular/core';
import { DomSanitizer, SafeStyle } from '@angular/platform-browser';
import { DestroySubject } from '@honoregaming/core';
import { EventsService } from '@honoregaming/events';
import { I18nService } from '@honoregaming/i18n';
import { OddsBoost } from '@honoregaming/types';
import { finalize, takeUntil } from 'rxjs/operators';

@Component({
  selector: 'hg-odds-boost-template',
  templateUrl: './odds-boost-template.component.html',
  styleUrls: ['./odds-boost-template.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class OddsBoostTemplateComponent extends DestroySubject implements OnInit {
  @Input()
  oddsBoostId: number;

  isLoading = false;
  oddsBoost: OddsBoost;
  nextEventDate: Date;
  backgroundUrl: any;

  currentLanguage: string = this.i18nService.currentLanguageCode;

  @Output()
  error = new EventEmitter<boolean>();

  @HostBinding('style.backgroundImage')
  get myStyle(): SafeStyle {
    return this.sanitizer.bypassSecurityTrustStyle(`url(${this.backgroundUrl})`);
  }

  constructor(
    private eventsService: EventsService,
    private cdRef: ChangeDetectorRef,
    private sanitizer: DomSanitizer,
    private i18nService: I18nService
  ) {
    super();
  }

  ngOnInit() {
    this.getOddsBoost();

    this.i18nService.languageChanged$.pipe(takeUntil(this.destroy$)).subscribe(l => {
      this.currentLanguage = l;
      this.cdRef.markForCheck();
    });
  }

  getOddsBoost() {
    this.isLoading = true;
    this.eventsService
      .getOddsBoost(this.oddsBoostId, this.currentLanguage)
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.isLoading = false;
          this.cdRef.markForCheck();
        })
      )
      .subscribe({
        next: odd => {
          if (odd) {
            this.nextEventDate = odd.details.reduce((current, next) =>
              current.event.expectedStart < next.event.expectedStart ? current : next
            ).event.expectedStart;

            this.oddsBoost = odd;
          } else {
            this.error.emit(true);
          }
        },
        error: () => {
          this.error.emit(true);
        }
      });
  }
}
