import {
  Component,
  OnInit,
  ChangeDetectionStrategy,
  Input,
  Output,
  EventEmitter,
  OnChanges,
  SimpleChanges
} from '@angular/core';
import { DrawGame } from '@honoregaming/types';

@Component({
  selector: 'hg-draw-games-selection',
  templateUrl: './draw-games-selection.component.html',
  styleUrls: ['./draw-games-selection.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class DrawGamesSelectionComponent implements OnInit, OnChanges {
  @Input() drawGames: DrawGame[] = [];
  @Input() defaultSelectedDrawGamesIds: number[] = [];
  @Input() seeMoreThreshold?: number = undefined;
  @Input() requiredSelectionCount?: number = undefined;
  @Output() selectionChanged: EventEmitter<number[]> = new EventEmitter<number[]>();

  selectedDrawGameIds: number[] = [];
  collapsed: boolean = false;
  displayedDrawGames: DrawGame[] = [];

  constructor() {}

  ngOnInit(): void {
    this.defaultSelectedDrawGamesIds.forEach(x => {
      if (!this.selectedDrawGameIds.includes(x)) {
        this.selectedDrawGameIds.push(x);
      }
    });

    if (this.seeMoreThreshold) {
      this.collapsed = true;
    }

    this.updateDisplayedEvents();
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['drawGames'] || changes['requiredSelectionCount'] || changes['defaultSelectedDrawGamesIds']) {
      this.selectedDrawGameIds = [];
      this.defaultSelectedDrawGamesIds.forEach(x => {
        if (!this.selectedDrawGameIds.includes(x)) {
          this.selectedDrawGameIds.push(x);
        }
      });
      this.updateDisplayedEvents();
    }
  }

  selectEvent(id: number): void {
    if (this.selectedDrawGameIds.includes(id)) {
      this.selectedDrawGameIds = this.selectedDrawGameIds.filter(x => x !== id);
    } else {
      this.selectedDrawGameIds.push(id);
    }

    this.updateDisplayedEvents();
    this.selectionChanged.emit(this.selectedDrawGameIds);
  }

  collapse(): void {
    this.collapsed = !this.collapsed;
    this.updateDisplayedEvents();
  }

  updateDisplayedEvents(): void {
    if (this.seeMoreThreshold > 0 && this.collapsed) {
      const firstSelectedDrawGameIndex = this.drawGames.findIndex(x => this.selectedDrawGameIds.includes(x.id));
      let startIndex = 0;
      if (firstSelectedDrawGameIndex >= this.seeMoreThreshold) {
        startIndex = Math.min(firstSelectedDrawGameIndex, this.drawGames.length - this.seeMoreThreshold);
      }

      this.displayedDrawGames = this.drawGames.slice(startIndex, startIndex + this.seeMoreThreshold);
    } else {
      this.displayedDrawGames = this.drawGames;
    }
  }
}
