import { Inject, Injectable } from '@angular/core';
import { BehaviorSubject, Observable } from 'rxjs';
import { LocalStorageService } from '@honoregaming/core';
import {
  CompleteMyBetConfiguration,
  Feature,
  OperatorConfiguration,
  operatorConfigurationToken
} from '@honoregaming/configuration';
import { CompleteMyBetInfo, EventBetTypeItem, EventStateType, Match, SelectedItem } from '@honoregaming/types';
import { Router } from '@angular/router';

@Injectable({
  providedIn: 'root'
})
export class CompleteMyBetService {
  private displayTutorialSubject$ = new BehaviorSubject<boolean>(false);
  private completeMyBetInfoSubject$ = new BehaviorSubject<CompleteMyBetInfo | null>(null);

  private storageKey = 'complete-my-bet';

  constructor(
    private localStorageService: LocalStorageService,
    @Inject(operatorConfigurationToken) private operatorConfiguration: OperatorConfiguration,
    private router: Router
  ) {}

  get displayTutorial$(): Observable<boolean> {
    return this.displayTutorialSubject$.asObservable();
  }

  get completeMyBetInfo$(): Observable<CompleteMyBetInfo | null> {
    return this.completeMyBetInfoSubject$.asObservable();
  }

  get completeMyBetInfo(): CompleteMyBetInfo | null {
    return this.completeMyBetInfoSubject$.value;
  }

  get storedCompleteMyBetInfo(): CompleteMyBetInfo | null {
    return this.localStorageService.getItem(this.storageKey) ?? null;
  }

  get hasStoredCompletion(): boolean {
    return !!this.storedCompleteMyBetInfo?.betId;
  }

  get configuration(): CompleteMyBetConfiguration {
    return this.operatorConfiguration.completeMyBetConfiguration;
  }

  initCompleteMyBet(betId: number, isFreebet: boolean, freebetCouponId?: number): void {
    if (this.completeMyBetInfo) {
      this.saveCompleteMyBetInfo({
        ...this.completeMyBetInfo,
        betId,
        isFreebet,
        freebetCouponId
      });
      this.checkDisplayTutorial();
      this.router.navigate(['/sports']);
    }
  }

  initCompleteMyBetFromStorage(): void {
    this.saveCompleteMyBetInfo(this.storedCompleteMyBetInfo, false);
    this.checkDisplayTutorial();
  }

  handleLogin(userId: number): void {
    this.saveCompleteMyBetInfo(userId === this.completeMyBetInfo?.userId ? this.completeMyBetInfo : { userId });
  }

  clearBetCompletion(updateStorage: boolean = true): void {
    if (this.completeMyBetInfo) {
      this.saveCompleteMyBetInfo(
        {
          userId: this.completeMyBetInfo.userId,
          tutorialCompleted: this.completeMyBetInfo.tutorialCompleted
        },
        updateStorage
      );

      if (!this.completeMyBetInfo.tutorialCompleted && this.displayTutorialSubject$.value) {
        this.displayTutorialSubject$.next(false);
      }
    }
  }

  closeTutorial(): void {
    if (this.completeMyBetInfo) {
      this.saveCompleteMyBetInfo({
        ...this.completeMyBetInfo,
        tutorialCompleted: true
      });
    }
    this.displayTutorialSubject$.next(false);
  }

  isTopMatchCompletionDisabled(
    selectedItems: SelectedItem[],
    match: Match,
    eventBetTypeItem: EventBetTypeItem
  ): boolean {
    const eventSelectedBets: SelectedItem[] = [];
    let selectedItem: SelectedItem;

    selectedItems.forEach((item: SelectedItem) => {
      if (match.id === item.eventId) {
        eventSelectedBets.push(item);
      }
      if (eventBetTypeItem.id === item.eventBetTypeItemId) {
        selectedItem = item;
      }
    });
    return this.isCompletionDisabled(eventSelectedBets, selectedItem, match, eventBetTypeItem.odds);
  }

  isCompletionDisabled(
    eventSelectedItems: SelectedItem[],
    selectedItem?: SelectedItem,
    match?: Match,
    odds?: number
  ): boolean {
    return (
      this.completeMyBetInfo?.betId &&
      (this.isInInitialBet(selectedItem) ||
        this.isEventAlreadyAdded(eventSelectedItems, selectedItem) ||
        this.isStateDisabled(match?.state) ||
        this.isOddsDisabled(odds))
    );
  }

  private checkDisplayTutorial(): void {
    if (
      this.completeMyBetInfo?.betId &&
      !this.completeMyBetInfo.tutorialCompleted &&
      this.operatorConfiguration.operatorFeatures.indexOf(Feature.CompleteMyBet) > -1 &&
      this.configuration.enableTutorial &&
      !this.displayTutorialSubject$.value
    ) {
      this.displayTutorialSubject$.next(true);
    }
  }

  private saveCompleteMyBetInfo(completeMyBetInfo: CompleteMyBetInfo | null, updateStorage: boolean = true): void {
    this.completeMyBetInfoSubject$.next(completeMyBetInfo);
    if (updateStorage) {
      this.localStorageService.setItem(this.storageKey, completeMyBetInfo);
    }
  }

  private isInInitialBet(selectedItem?: SelectedItem): boolean {
    return selectedItem?.isBetCompletion;
  }

  private isEventAlreadyAdded(eventSelectedItems: SelectedItem[], selectedItem?: SelectedItem): boolean {
    return eventSelectedItems.length > 0 && !selectedItem;
  }

  private isStateDisabled(state?: EventStateType): boolean {
    return (
      !!state &&
      ((!this.configuration.authorizeLive && state === EventStateType.Started) ||
        (!this.configuration.authorizePreEvent && state !== EventStateType.Started))
    );
  }

  private isOddsDisabled(odds?: number): boolean {
    return (
      !!odds && !!this.configuration.minimalOddsForCompletion && this.configuration.minimalOddsForCompletion > odds
    );
  }
}
