import {
  BetState,
  EventStateType,
  SportsPoolGame,
  SportsPoolGameMatch,
  SportsPoolGameMatchLive,
  SportsPoolGameState,
  SportsPoolHistoryGameDetail
} from '@honoregaming/types';
import { ChangeDetectionStrategy, ChangeDetectorRef, Component, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { interval, Observable } from 'rxjs';
import { finalize, switchMap, takeUntil } from 'rxjs/operators';
import { DestroySubject } from '@honoregaming/core';
import { AccountService } from '@honoregaming/account';
import { EventsService } from '@honoregaming/events';
import { MessageService } from '@honoregaming/ui';
import { PopupSportsPoolGameDetailComponent } from 'projects/core/hg-sports-pool-ui/src/lib/components/popup-sports-pool-game-detail/popup-sports-pool-game-detail.component';

@Component({
  selector: 'hg-sports-pool-bet',
  templateUrl: './sports-pool-bet.component.html',
  styleUrls: ['./sports-pool-bet.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class SportsPoolBetComponent extends DestroySubject implements OnInit {
  detail!: SportsPoolHistoryGameDetail;
  gameState!: SportsPoolGameState;

  defaultMatchs: SportsPoolGameMatch[] = [];
  reservedMatchs: SportsPoolGameMatch[] = [];

  hasReservedMatchs: boolean = false;

  betId?: number;
  loading: boolean = false;
  error: boolean = false;

  readonly BetState = BetState;
  readonly EventStateType = EventStateType;
  readonly SportsPoolGameState = SportsPoolGameState;

  constructor(
    private readonly router: Router,
    private readonly route: ActivatedRoute,
    private readonly accountService: AccountService,
    private readonly eventsService: EventsService,
    private readonly messageService: MessageService,
    private readonly cdRef: ChangeDetectorRef
  ) {
    super();
  }

  ngOnInit(): void {
    this.route.params.pipe(takeUntil(this.destroy$)).subscribe({
      next: params => {
        this.betId = Number(params.betId);
        if (this.betId) {
          this.loadBet();
        } else {
          this.goBack();
        }
      },
      error: () => this.goBack()
    });
  }

  get navButtons(): { id: number; direction: string; icon: string }[] {
    return [
      { id: this.detail.nextId, direction: 'left', icon: 'hg-arrow-left' },
      { id: this.detail.previousId, direction: 'right', icon: 'hg-arrow-right' }
    ];
  }

  hasMatchOutcome(match: SportsPoolGameMatch): boolean {
    return (
      match.eventBetType.settled ||
      (!match.cancelled && !match.delayed && !!match.homeTeamScore && !!match.awayTeamScore)
    );
  }

  goBack(): void {
    this.router.navigate(['/myaccount/sportspool-history']);
  }

  private loadBet(): void {
    this.loading = true;
    this.error = false;

    this.accountService
      .getSportsPoolHistoryGameDetail(this.betId)
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => this.finishLoading())
      )
      .subscribe({
        next: detail => this.handleDetail(detail),
        error: () => (this.error = true)
      });
  }

  private handleDetail(detail: SportsPoolHistoryGameDetail): void {
    this.detail = detail;
    this.setMatches(detail.game.matchPositions);
    this.setSportsPoolGameState(detail.game);

    if (this.hasLiveScores(detail.game)) {
      this.subscribeToLiveScores(detail.game.id);
    }
  }

  private setSportsPoolGameState(game: SportsPoolGame): void {
    const now: number = Date.now();
    const start: number = new Date(game.expectedStart).getTime();
    const end: number = new Date(game.expectedEnd).getTime();

    if (start > now) {
      this.gameState = SportsPoolGameState.Undisputed;
    } else if (end > now) {
      this.gameState = SportsPoolGameState.InProgress;
    } else {
      this.gameState = SportsPoolGameState.Finished;
    }
  }

  private setMatches(matches: SportsPoolGameMatch[]): void {
    this.defaultMatchs = matches.filter(sportsPoolGameMatch => !sportsPoolGameMatch?.reserved);
    this.reservedMatchs = matches.filter(sportsPoolGameMatch => sportsPoolGameMatch?.reserved);

    this.hasReservedMatchs = this.reservedMatchs.length > 0;
  }

  private hasLiveScores(game: SportsPoolGame): boolean {
    return game.matchPositions.some(match => Boolean(match.data));
  }

  private subscribeToLiveScores(eventId: number): void {
    this.pollSportsPoolEventLive(eventId)
      .pipe(takeUntil(this.destroy$))
      .subscribe(liveMatches => {
        liveMatches.forEach(liveMatch => this.updateMatchDetails(liveMatch));
      });
  }

  private updateMatchDetails(liveMatch: SportsPoolGameMatchLive): void {
    const index: number = this.detail.game.matchPositions.findIndex(mp => mp.id === liveMatch.id);
    if (index === -1) return;

    const match: SportsPoolGameMatch = this.detail.game.matchPositions[index];

    this.detail.game.matchPositions[index] = {
      ...match,
      homeTeamScore: liveMatch.homeTeamScore,
      awayTeamScore: liveMatch.awayTeamScore,
      scores: liveMatch.scores ?? match.scores,
      data: liveMatch.isLive ? match.data : undefined,
      event: {
        ...match.event,
        stateDetails: liveMatch.isLive && liveMatch.stateDetails ? liveMatch.stateDetails : match.event.stateDetails
      }
    };

    this.setMatches(this.detail.game.matchPositions);
    this.cdRef.markForCheck();
  }

  private pollSportsPoolEventLive(eventId: number): Observable<SportsPoolGameMatchLive[]> {
    return interval(60_000).pipe(switchMap(() => this.eventsService.getSportsPoolEventLive(eventId)));
  }

  private finishLoading(): void {
    this.loading = false;
    this.cdRef.markForCheck();
  }

  public displaySportsPoolDetail(isRanking: boolean = false): void {
    this.messageService.sendComponentMessage(
      PopupSportsPoolGameDetailComponent,
      { details: this.detail.game.details, isRanking: isRanking },
      { bare: true }
    );
  }
}
