import {
  Component,
  ChangeDetectionStrategy,
  Input,
  OnInit,
  ChangeDetectorRef,
  OnChanges,
  SimpleChanges
} from '@angular/core';
import { BetCategoryType } from '@honoregaming/types';
import { BetLine } from '../../../models';
import { EventsService } from '@honoregaming/events';
import { takeUntil } from 'rxjs/operators';
import { DestroySubject } from '@honoregaming/core';

@Component({
  selector: 'hg-draw-games-bet-line-header',
  templateUrl: './draw-games-bet-line-header.component.html',
  styleUrls: ['./draw-games-bet-line-header.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class DrawGamesBetLineHeaderComponent extends DestroySubject implements OnInit, OnChanges {
  @Input()
  betLine: BetLine;

  BetCategoryType = BetCategoryType;

  borletteBetTypeIds = [40035, 40036, 40037, 40038, 40039, 40042, 40043];

  associatedEvents = new Map();

  constructor(private eventsService: EventsService, private cdRef: ChangeDetectorRef) {
    super();
  }

  ngOnInit(): void {
    this.initBetLine();
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['betLine']) {
      this.initBetLine();
    }
  }

  initBetLine(): void {
    this.associatedEvents = new Map();
    if (this.betLine.associatedDrawGamesIds) {
      for (let id of this.betLine.associatedDrawGamesIds) {
        this.eventsService
          .getEventFromCacheOrService(id)
          .pipe(takeUntil(this.destroy$))
          .subscribe(x => {
            if (x?.name) {
              this.associatedEvents.set(id, { name: x.name, date: x.expectedStart });
              this.cdRef.markForCheck();
            }
          });
      }
    }
  }

  public formatDrawGameNumbersMariage(number: string) {
    return number.substring(0, 2) + ' x ' + number.toString().substring(2);
  }
}
