import { Component, ChangeDetectionStrategy, Input, OnInit } from '@angular/core';
import { InstantGameState, InstantGameTransaction } from '@honoregaming/types';

@Component({
  selector: 'hg-insa-games-transaction',
  templateUrl: './insa-games-transaction.component.html',
  styleUrls: ['./insa-games-transaction.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class InsaGamesTransactionComponent implements OnInit {
  @Input() transaction: InstantGameTransaction;

  selection: any;
  result: any;

  InstantGameState = InstantGameState;

  ngOnInit(): void {
    this.result = this.transaction.result ? JSON.parse(this.transaction.result) : undefined;
    this.selection = this.transaction.selection ? JSON.parse(this.transaction.selection) : undefined;
    if (
      !this.selection.numbers &&
      this.selection[0] &&
      !this.selection[0].numbers &&
      this.transaction.instantGameName === 'Keno'
    ) {
      const key = Object.keys(JSON.parse(this.transaction.selection)[0])[0];
      const numbers = key.split('-').map(Number);
      this.selection.numbers = numbers;
    }
    if (!this.selection.betLines) {
      return;
    }

    if (
      this.selection.betLines &&
      this.result.length > this.selection.betLines.length &&
      this.selection.betLines.length === 1
    ) {
      this.result = this.result.filter(result => result.eventId === this.selection.betLines[0].eventId);
    } else {
      this.result.map(result => {
        const betLine = this.selection.betLines.find(betLine => result.eventId === betLine.eventId);
        result.eventName = betLine.event;
        result.eventBetType = betLine.eventBetType;
        result.eventBetTypeItem = betLine.eventBetTypeItem;
        result.fixedOdds = betLine.fixedOdds;
      });
    }
  }
}
