declare var turnstile: any;

import { mergeMap } from 'rxjs/operators';
import { Inject, Injectable, PLATFORM_ID } from '@angular/core';
import { DestroySubject } from '@honoregaming/core';
import { ICaptchaService } from './captcha-service.model';
import { CustomerService } from '../customer.service';
import { SecurityPolicy } from '@honoregaming/types';
import { DOCUMENT, isPlatformBrowser } from '@angular/common';
import { Observable, from, of } from 'rxjs';

@Injectable()
export class TurnstileCaptchaService extends DestroySubject implements ICaptchaService {
  private securityPolicy: SecurityPolicy;

  private script: any;
  private turnstileToken: string;

  constructor(
    private customerService: CustomerService,
    @Inject(DOCUMENT) private document,
    @Inject(PLATFORM_ID) private platformId
  ) {
    super();
  }

  loadCaptcha(securityPolicy: SecurityPolicy) {
    this.securityPolicy = securityPolicy;
  }

  applyCaptcha(_targetElement: string): Observable<void> {
    return this.customerService.getSecurityPolicy().pipe(
      mergeMap(securityPolicy => {
        this.securityPolicy = securityPolicy;

        if (this.securityPolicy.captchaProvider?.turnstile?.enabled && isPlatformBrowser(this.platformId)) {
          var that = this;

          if (!this.document.querySelector('#TURNSTILE')) {
            this.script = this.document.createElement('script');
            this.script.src = 'https://challenges.cloudflare.com/turnstile/v0/api.js?render=explicit';
            this.script.rel = 'script';
            this.script.id = 'TURNSTILE';
            this.script.defer = false;
            this.script.async = false;

            this.document.querySelector('body').appendChild(this.script);

            return from(
              new Promise<void>((resolve, _) => {
                this.script.onload = () => {
                  if (isPlatformBrowser(this.platformId)) {
                    turnstile.ready(function () {
                      turnstile.render('.recaptcha-legend', {
                        sitekey: that.securityPolicy.captchaProvider.turnstile.siteKey,
                        theme: 'light',
                        callback: function (token: string) {
                          that.turnstileToken = token;
                          resolve();
                        }
                      });
                    });
                  }
                };
              })
            );
          } else {
            this.script = document.querySelector('#TURNSTILE');
            return of(void 0);
          }
        }
      })
    );
  }

  validateCaptcha(): Observable<string> {
    if (this.securityPolicy.captchaProvider?.turnstile?.enabled && isPlatformBrowser(this.platformId)) {
      return of(this.turnstileToken);
    }

    return of(null);
  }

  clearCaptcha(): void {
    if (this.document.querySelector('#TURNSTILE')) {
      this.document.querySelector('body').removeChild(this.script);
    }
  }

  getLegend(): string {
    return null;
  }
}
