import { Component, OnInit, ChangeDetectionStrategy, Input, Output, EventEmitter, Inject } from '@angular/core';
import { BetLine, BetLineAmount } from '../../../models';
import { operatorConfigurationToken, OperatorConfiguration } from '@honoregaming/configuration';
import { getCombinationsMultiplier } from '@honoregaming/core';
import { I18nService } from '@honoregaming/i18n';
import { getBetLineAmountErrorAndCode } from '../../../utils';

@Component({
  selector: 'hg-race-bet-line',
  templateUrl: './race-bet-line.component.html',
  styleUrls: ['./race-bet-line.component.scss', '../bet-line-content.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class RaceBetLineComponent implements OnInit {
  @Input()
  betLine: BetLine;
  @Input()
  amount: BetLineAmount;
  @Input()
  showIndividualNewStakeMessage: boolean = false;
  @Input()
  acceptOddChange: boolean;

  @Output()
  amountChange = new EventEmitter<number>();
  @Output()
  remove = new EventEmitter<void>();

  currency = this.operatorConfiguration.currency.symbol;
  getCombinationsMultiplier = getCombinationsMultiplier;
  odds: number;

  errorMessage?: string;
  errorCode?: string;

  constructor(
    @Inject(operatorConfigurationToken) private operatorConfiguration: OperatorConfiguration,
    private i18nService: I18nService
  ) {}

  ngOnInit() {
    if (this.betLine.combinations?.length === 1) {
      this.odds = this.betLine.combinations[0].fixedOdds;
    }
  }

  onAmountChange(amount: number) {
    this.amountChange.emit(amount);
  }

  onRemove() {
    this.remove.emit();
  }

  isValidAmount() {
    ({ error: this.errorMessage, code: this.errorCode } = getBetLineAmountErrorAndCode(
      this.i18nService,
      this.amount.amount,
      this.betLine.leftoverBalanceAmount || this.betLine.baseAmount,
      this.betLine.leftoverBalanceAmount || this.betLine.maximumAmount,
      this.betLine.leftoverBalanceAmount || this.betLine.minimumAmountIncrement,
      this.showIndividualNewStakeMessage ? this.betLine.newStake : null
    ));
    return !this.errorMessage;
  }
}
