import { Component, ChangeDetectionStrategy, EventEmitter, Output, Inject, OnInit } from '@angular/core';
import {
  CustomerOperatorConfiguration,
  customerOperatorConfigurationToken,
  PrivacyService
} from '@honoregaming/customer-core';
import { PrivacyConfiguration, globalConfiguration } from '@honoregaming/configuration';
import { kioskToken } from '@honoregaming/core';

@Component({
  selector: 'hg-privacy',
  templateUrl: './privacy.component.html',
  styleUrls: ['./privacy.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class PrivacyComponent implements OnInit {
  @Output() privacyConsent = new EventEmitter();

  preferenceTitle: string;
  necessaryTitle: string;
  necessaryConsent = true;
  necessaryExpanded = false;
  analyticsActive: boolean;
  analyticsTitle: string;
  analyticsConsent = true;
  analyticsExpanded = false;
  isChoicesOpen: boolean;
  desktopLogoPath =
    globalConfiguration.assetsPath +
    this.customerOperatorConfiguration.key +
    (this.isKiosk && this.customerOperatorConfiguration.kioskConfiguration?.desktopLogoPath !== null
      ? '/' + this.customerOperatorConfiguration.kioskConfiguration.desktopLogoPath
      : '/logo.png');
  mobileLogoPath =
    globalConfiguration.assetsPath +
    this.customerOperatorConfiguration.key +
    (this.isKiosk && this.customerOperatorConfiguration.kioskConfiguration?.mobileLogoPath !== null
      ? '/' + this.customerOperatorConfiguration.kioskConfiguration.mobileLogoPath
      : '/mobile-logo.png');

  constructor(
    private privacyService: PrivacyService,
    @Inject(customerOperatorConfigurationToken) private customerOperatorConfiguration: CustomerOperatorConfiguration,
    @Inject(kioskToken) public isKiosk: boolean
  ) {}

  ngOnInit() {
    this.analyticsActive = this.customerOperatorConfiguration.privacyConfiguration?.consents?.analytics;
  }

  allowAll() {
    const privacyConfiguration: PrivacyConfiguration = {
      consents: {
        analytics: true
      }
    };

    this.setPrivacyConfiguration(privacyConfiguration);
  }

  refuseAll() {
    const privacyConfiguration: PrivacyConfiguration = {
      consents: {
        analytics: false
      }
    };

    this.setPrivacyConfiguration(privacyConfiguration);
  }

  allowSelected() {
    const privacyConfiguration: PrivacyConfiguration = {
      consents: {
        analytics: this.analyticsActive && this.analyticsConsent
      }
    };

    this.setPrivacyConfiguration(privacyConfiguration);
  }

  setPrivacyConfiguration(privacyConfiguration: PrivacyConfiguration) {
    this.privacyService.setPrivacyConfiguration(privacyConfiguration);
    this.privacyConsent.emit();
  }
}
