import { DateTime } from 'luxon';

const MILLISECONDS_IN_DAY = 86400000;

export function addMonths(date: Date, amount: number) {
  date.setMonth(date.getMonth() + amount);
  return date;
}

export function addHours(date: Date, amount: number) {
  date.setHours(date.getHours() + amount);
  return date;
}

export function setDate(date: Date, amount: number) {
  date.setDate(amount);
  return date;
}

export function getDaysInMonth(date: Date) {
  const year = date.getFullYear();
  const monthIndex = date.getMonth();
  const lastDayOfMonth = new Date(0);
  lastDayOfMonth.setFullYear(year, monthIndex + 1, 0);
  lastDayOfMonth.setHours(0, 0, 0, 0);
  return lastDayOfMonth.getDate();
}

export function startOfDay(date: Date) {
  const newDate = new Date(date.getTime());
  newDate.setHours(0, 0, 0, 0);
  return newDate;
}

export function startOfMonth(date: Date) {
  const newDate = new Date(0);
  newDate.setFullYear(date.getFullYear(), date.getMonth(), 1);
  newDate.setHours(0, 0, 0, 0);
  return newDate;
}

export function endOfMonth(date: Date) {
  return DateTime.fromJSDate(date).endOf('month').toJSDate();
}

export function isSameYear(dateLeft: Date, dateRight: Date) {
  return dateLeft.getFullYear() === dateRight.getFullYear();
}

export function isSameDay(dateLeft, dateRight) {
  const dateLeftStartOfDay = startOfDay(dateLeft);
  const dateRightStartOfDay = startOfDay(dateRight);

  return dateLeftStartOfDay.getTime() === dateRightStartOfDay.getTime();
}

export function isSameDate(date1: Date, date2: Date) {
  return date2 && isSameDay(date2, date1) && isSameYear(date2, date1) && isSameYear(date2, date1);
}

export function daysInMonth(date: Date) {
  const totalDays = getDaysInMonth(date);
  return Array.from(Array(totalDays), (_, i) => {
    const day = new Date(date.getTime());
    day.setDate(i + 1);
    return day;
  });
}

export function getDayOfWeekOffset(date: Date) {
  const firstDay = new Date(date.getFullYear(), date.getMonth(), 1);
  const dayOfWeek = firstDay.getDay();
  return Array.from(Array(dayOfWeek), (_, i) => i);
}

export function getDayOfYear(date: Date) {
  const diff = differenceInCalendarDays(date, startOfYear(date));
  const dayOfYear = diff + 1;
  return dayOfYear;
}

export function differenceInCalendarDays(leftDate: Date, rightDate: Date) {
  const startOfDayLeft = startOfDay(leftDate);
  const startOfDayRight = startOfDay(rightDate);

  const timestampLeft = startOfDayLeft.getTime();
  const timestampRight = startOfDayRight.getTime();

  return Math.round((timestampLeft - timestampRight) / MILLISECONDS_IN_DAY);
}

export function startOfYear(date: Date) {
  const cleanDate = new Date(0);
  cleanDate.setFullYear(date.getFullYear(), 0, 1);
  cleanDate.setHours(0, 0, 0, 0);
  return cleanDate;
}

export function getUtcNow(): Date {
  const date = new Date();

  return new Date(
    Date.UTC(
      date.getUTCFullYear(),
      date.getUTCMonth(),
      date.getUTCDate(),
      date.getUTCHours(),
      date.getUTCMinutes(),
      date.getUTCSeconds()
    )
  );
}

export function happenBefore(from: Date, target: Date, delayInMs: number) {
  return target.getTime() - from.getTime() <= delayInMs;
}

export function delayBetween(from: Date, target: Date) {
  return target.getTime() - from.getTime();
}

export function getModernTime(date: Date) {
  const base = new Date('2000-01-01');

  return date.getTime() - base.getTime();
}

export function getModernSecondTime(date: Date) {
  return Math.ceil(getModernTime(date) / 1000);
}

// 0 = today, 1 = yesterday, -1 tomorrow
export function getDaysRange(from: number, to: number): Date[] {
  const result = [];
  for (let i = from; i <= to; i++) {
    const day = new Date();
    day.setHours(12, 0, 0, 0);
    day.setDate(day.getDate() - i);
    result.push(day);
  }

  return result;
}

export function getStartEndDayDate(day: Date): { start: Date; end: Date } {
  const start = new Date(day);
  start.setHours(0, 0, 0, 0);

  const end = new Date(day);
  end.setHours(23, 59, 59, 999);
  return { start, end };
}

export function startOfDayInOperatorTimeZone(ianaTimeZoneId: string, date: Date = null) {
  var dateTimeInOperatorTimeZone = DateTime.now().setZone(ianaTimeZoneId);
  var dateTimeLocalZone = DateTime.now();
  var newDate = DateTime.fromJSDate(new Date(date));

  return new Date(
    dateTimeInOperatorTimeZone.year,
    date ? newDate.month - 1 : dateTimeInOperatorTimeZone.month - 1,
    date ? newDate.day : dateTimeInOperatorTimeZone.day,
    dateTimeLocalZone.hour - dateTimeInOperatorTimeZone.hour,
    0,
    0
  );
}

export function endOfDayInOperatorTimeZone(ianaTimeZoneId: string, date: Date = null) {
  var dateTimeInOperatorTimeZone = DateTime.now().setZone(ianaTimeZoneId);
  var dateTimeLocalZone = DateTime.now();
  var newDate = DateTime.fromJSDate(new Date(date));
  return new Date(
    dateTimeInOperatorTimeZone.year,
    date ? newDate.month - 1 : dateTimeInOperatorTimeZone.month - 1,
    date ? newDate.day : dateTimeInOperatorTimeZone.day,
    dateTimeLocalZone.hour - dateTimeInOperatorTimeZone.hour + 23,
    59,
    59
  );
}

export function startOfDayInUtc(ianaTimeZoneId: string, date: Date) {
  var local = DateTime.fromFormat(
    `${date.getFullYear()}-${('0' + (date.getMonth() + 1)).slice(-2)}-${('0' + date.getDate()).slice(
      -2
    )}T00:00:00 ${ianaTimeZoneId}`,
    "yyyy-MM-dd'T'HH:mm:ss z"
  );
  return local.toString();
}

export function endOfDayInUtc(ianaTimeZoneId: string, date: Date) {
  var local = DateTime.fromFormat(
    `${date.getFullYear()}-${('0' + (date.getMonth() + 1)).slice(-2)}-${('0' + date.getDate()).slice(
      -2
    )}T23:59:59 ${ianaTimeZoneId}`,
    "yyyy-MM-dd'T'HH:mm:ss z"
  );
  return local.toString();
}

export function getDateInBrowserTimeZone() {
  return DateTime.local().toJSDate();
}

export function getDateInOperatorTimeZone(ianaTimeZoneId: string) {
  var dateTimeInOperatorTimeZone = DateTime.now().setZone(ianaTimeZoneId);
  return new Date(
    dateTimeInOperatorTimeZone.year,
    dateTimeInOperatorTimeZone.month - 1,
    dateTimeInOperatorTimeZone.day,
    dateTimeInOperatorTimeZone.hour,
    dateTimeInOperatorTimeZone.minute,
    dateTimeInOperatorTimeZone.second
  );
}

export function convertMsToTime(milliseconds: number) {
  let seconds = Math.floor(milliseconds / 1000);
  let minutes = Math.floor(seconds / 60);
  let hours = Math.floor(minutes / 60);
  seconds = seconds % 60;
  minutes = minutes % 60;

  return `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}:${seconds
    .toString()
    .padStart(2, '0')}`;
}
