import { Injectable } from '@angular/core';
import { Router } from '@angular/router';
import { TelemetryService } from '@honoregaming/customer-core';

@Injectable({ providedIn: 'root' })
export class DirectMessageTrackingService {
  constructor(private readonly telemetryService: TelemetryService, private readonly router: Router) {}

  trackOpen(from: 'footer' | 'widget' | 'account'): void {
    this.telemetryService.trackEvent('direct_message_widget_open', { from, page_location: this.router.url });
  }

  trackMinimize(): void {
    this.telemetryService.trackEvent('direct_message_widget_minimize', { page_location: this.router.url });
  }

  trackClose(type: 'widget' | 'window'): void {
    this.telemetryService.trackEvent('direct_message_widget_close', { type, page_location: this.router.url });
  }
}
