import { Component, ChangeDetectionStrategy, Input, Inject, OnInit } from '@angular/core';
import { operatorConfigurationToken, OperatorConfiguration, PaymentTax } from '@honoregaming/configuration';
import { BetCategoryType, InstantGameTransaction } from '@honoregaming/types';
import { CurrencyMathMixin, DestroySubject } from '@honoregaming/core';

@Component({
  selector: 'hg-instant-game-transaction-footer',
  templateUrl: './instant-game-transaction-footer.component.html',
  styleUrls: ['./instant-game-transaction-footer.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class InstantGameTransactionFooterComponent extends CurrencyMathMixin(DestroySubject) implements OnInit {
  @Input() transaction!: InstantGameTransaction;

  shouldDisplayPaymentTax: boolean = true;
  showTaxInformations: boolean = false;
  useAlternativeDisplayForTax: boolean = this.operatorConfiguration.onlineConfiguration?.useAlternativeDisplayForTax;

  constructor(@Inject(operatorConfigurationToken) private readonly operatorConfiguration: OperatorConfiguration) {
    super();
  }

  ngOnInit(): void {
    this.shouldDisplayPaymentTax =
      this.operatorConfiguration.paymentTaxes?.findIndex(
        pt => pt.showTaxDetail && pt.betCategory && BetCategoryType.InstantGame === pt.betCategory
      ) >= 0;
  }

  get paymentTaxRate(): number {
    const paymentTax: PaymentTax = this.operatorConfiguration.paymentTaxes?.find(
      (tax: PaymentTax) => tax.betCategory && BetCategoryType.InstantGame === tax.betCategory
    );
    return (paymentTax?.rate ?? 0) * 100;
  }

  displayTaxInformations(): void {
    this.showTaxInformations = !this.showTaxInformations;
  }
}
