import { Component, ChangeDetectionStrategy, Input, OnChanges, OnInit, ChangeDetectorRef } from '@angular/core';
import { takeUntil, take } from 'rxjs/operators';
import { DestroySubject, BetHistoryService } from '@honoregaming/core';
import { I18nService } from '@honoregaming/i18n';
import { BetLineStateType, BetState, BetSystemHistory, BetSystemType, EventType } from '@honoregaming/types';
import { ToasterService } from '@honoregaming/ui';

@Component({
  selector: 'hg-virtual-bet-system',
  templateUrl: './virtual-bet-system.component.html',
  styleUrls: ['../generic-bet-system.component.scss', './virtual-bet-system.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class VirtualBetSystemComponent extends DestroySubject implements OnInit, OnChanges {
  @Input() betSystem!: BetSystemHistory;
  @Input() hideSection: boolean = false;

  BetState = BetState;
  BetSystemType = BetSystemType;
  EventType = EventType;
  limitNumber: number = 3;
  betLinesVisible: boolean = true;
  reducedFormatApplies: boolean = false;

  private readonly betHistoryReducedFormatEnabled: boolean = this.betHistoryService.reducedFormatEnabled;

  constructor(
    private readonly toasterService: ToasterService,
    private readonly i18n: I18nService,
    private readonly betHistoryService: BetHistoryService,
    private readonly cdRef: ChangeDetectorRef
  ) {
    super();
    this.betLinesVisible = !this.betHistoryReducedFormatEnabled || this.betHistoryService.expandedFormat;
  }

  get betLineStateCounts(): { state: BetLineStateType; count: number }[] {
    return this.betHistoryService.getBetLineStateCounts(this.betSystem);
  }

  ngOnInit(): void {
    this.subscribeToExpandedFormat();
  }

  ngOnChanges(): void {
    if (this.betSystem.betLines.length > this.limitNumber && !this.hideSection) {
      this.betSystem.isCollapsed = false;
    }

    this.reducedFormatApplies = this.betHistoryReducedFormatEnabled && this.betSystem.type === BetSystemType.Multiple;
  }

  contentCopied(): void {
    this.i18n
      .translate('ACCOUNT.COPIED.REFERENCE')
      .pipe(take(1))
      .subscribe(translation => this.toasterService.show(translation));
  }

  toggleBetLines(): void {
    this.betLinesVisible = !this.betLinesVisible;
  }

  showMore(): void {
    this.betSystem.isCollapsed = !this.betSystem.isCollapsed;
    this.limitNumber = this.betSystem.isCollapsed ? this.betSystem.betLines.length : 3;
  }

  private subscribeToExpandedFormat(): void {
    // Reduced format relies on the header toggle, which is not rendered when the section is hidden
    if (!this.betHistoryReducedFormatEnabled || this.hideSection) {
      this.betLinesVisible = true;
      return;
    }

    if (this.betSystem.type !== BetSystemType.Multiple) {
      this.betLinesVisible = true;
      return;
    }

    this.betHistoryService.expandedFormat$.pipe(takeUntil(this.destroy$)).subscribe(expandedFormat => {
      this.betLinesVisible = expandedFormat;
      this.cdRef.markForCheck();
    });
  }
}
