import { Component, ChangeDetectionStrategy, EventEmitter, Output, Input, OnInit } from '@angular/core';
import { I18nService } from '@honoregaming/i18n';
import { DomSanitizer, SafeHtml } from '@angular/platform-browser';
import { LoyaltyRedeemable, LoyaltyRedeemableType } from '@honoregaming/types';

@Component({
  selector: 'hg-loyalty-redeemable-confirmation',
  templateUrl: './loyalty-redeemable-confirmation.component.html',
  styleUrls: ['./loyalty-redeemable-confirmation.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class LoyaltyRedeemableConfirmationComponent implements OnInit {
  @Output()
  close = new EventEmitter<boolean>();

  @Input()
  loyaltyRedeemable: LoyaltyRedeemable;

  @Input()
  changed = false;

  @Input()
  itemCode: string;

  message: SafeHtml;
  LoyaltyRedeemableType = LoyaltyRedeemableType;

  constructor(private i18nService: I18nService, private sanitizer: DomSanitizer) {}

  ngOnInit(): void {
    if (this.changed) {
      this.message = this.i18nService.translateSync('LOYALTY.EXCHANGE_SUCCESSFULLY');
    } else if (this.loyaltyRedeemable) {
      const isFreeBetBundle = this.loyaltyRedeemable.type === LoyaltyRedeemableType.FreeBetBundle;
      let loyaltyRedeemableLabel =
        '<strong>' +
        (this.loyaltyRedeemable.amount
          ? this.i18nService.formatCurrencySync(this.loyaltyRedeemable.amount, !isFreeBetBundle)
          : this.loyaltyRedeemable.item) +
        '</strong>';

      if (isFreeBetBundle) {
        loyaltyRedeemableLabel += ` <i class="hg-free-bet" style="
          min-width: 14px;
          min-height: 14px;
          border-radius: 50%;
          display: inline-flex;
          justify-content: center;
          align-items: center;
          font-size: 12px;
        "></i>`;
      }

      this.message = this.sanitizer.bypassSecurityTrustHtml(
        this.i18nService.translateSync(
          'LOYALTY.WOULD_EXCHANGE_POINTS',
          this.i18nService.formatCurrencySync(this.loyaltyRedeemable.price),
          loyaltyRedeemableLabel
        )
      );
    }
  }
}
