import {
  Component,
  ChangeDetectionStrategy,
  OnInit,
  ChangeDetectorRef,
  HostBinding,
  Inject,
  ViewChild
} from '@angular/core';
import { operatorConfigurationToken, OperatorConfiguration } from '@honoregaming/configuration';
import { DestroySubject, PushService } from '@honoregaming/core';
import { LiveEventsCountService } from '@honoregaming/events';
import { AnimateDirective } from '@honoregaming/ui';
import { of } from 'rxjs';
import { takeUntil, take, switchMap } from 'rxjs/operators';

@Component({
  selector: 'hg-live-counter',
  templateUrl: './live-counter.component.html',
  styleUrls: ['./live-counter.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class LiveCounterComponent extends DestroySubject implements OnInit {
  @ViewChild(AnimateDirective)
  counter: AnimateDirective;

  @HostBinding('class.hidden')
  public hidden: boolean = true;
  public numberOfLives: number = 0;

  constructor(
    private liveEventsCountService: LiveEventsCountService,
    private cdRef: ChangeDetectorRef,
    @Inject(operatorConfigurationToken) public operatorConfiguration: OperatorConfiguration,
    private pushService: PushService
  ) {
    super();
  }

  ngOnInit() {
    if (this.operatorConfiguration.onlineConfiguration?.showLiveCounter) {
      this.liveEventsCountService.liveCountChangedChanged$
        .pipe(
          takeUntil(this.destroy$),
          take(1),
          switchMap(count => (count ? of(count) : this.liveEventsCountService.getLiveSportsEventsCount()))
        )
        .subscribe(count => {
          this.numberOfLives = count;
          this.liveEventsCountService.incrementListCount(count);
          this.updateLiveCounter();
        });

      this.pushService.liveCounterChanged$.pipe(takeUntil(this.destroy$)).subscribe(changed => {
        if (changed.changes['liveCounterIncrement']) {
          var newCount = this.numberOfLives + changed.changes['liveCounterIncrement'];
          if (newCount >= 0) {
            this.numberOfLives = newCount;
          } else {
            this.numberOfLives = 0;
          }

          this.liveEventsCountService.incrementListCount(this.numberOfLives);
          this.updateLiveCounter();
        }
      });
    }
  }

  private updateLiveCounter() {
    this.hidden = this.numberOfLives <= 0;

    if (this.counter && !this.hidden) {
      this.counter.animate('new');
    }

    this.cdRef.markForCheck();
  }
}
